INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_5_0','纪梦哀容斋陈君也','黄玠','元','昨夜梦中逢故人，
华屋凉天正潇洒。
银罂美酒雕玉觞，
亦有尊前唱歌者。
馀欢未尽忽惊寤，
蔌蔌寒花落灯灺。
忍将今梦梦昔梦，
梦去愁来泪盈把。
西园公子多雅怀，
死骨凄凉在中野。
当时苦爱椎凿声，
岂思此日无遗瓦。
古来丰家无好儿，
荆棘铜驼秋露下。
草间翁仲不解语，
焉用鬼驺牵鬼马。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1','余自辛亥岁馆于魏塘吴氏时义士静心先生方无恙长子彦良应门于家次子景良输力于时皆一时伟人季子季良为赘婿于外与余尤相友善岁壬申景良卒于官所归葬胥山诸孙各求分异学遂废而余乃去矣顷者不逞之徒坏其守冢之庐季良之子璋闻于官罪人斯得众称之曰能故为是诗以勉之','黄玠','元','天目诸峰来迤逦，
又向钱唐渡江水。
伏龙骪骳行地中，
东尽由拳还崛起。
想见昔日遭秦驱，
太古风雷入鞭箠。
山君据地不肯前，
至今乱石犹西指。
下有石龟形质具，
蹂躏良田捷于鬼。
伍员挥剑迹尚存，
缺齾不完神乃死。
当时结友番禺君，
别墅园池此经始。
朝阳亭上醉春风，
谢安曾爱东山妓。
回首光阴二十年，
往事浑非山尚是。
叹息佳人曹子丹，
翁仲无言荆棘里。
摇铃鼓哨旁若无，
乡里小儿何敢尔。
脊令脊令飞且鸣，
能事多惭伯颙氏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2','忆昔行','黄玠','元','忆昔侠家全盛日，
江左数州无亚匹。
黄金横带虎作符，
尽斥民居为第室。
长腰细米光照人，
自给不求归老秩。
舂陵石几汝州瓷，
一席万钱犹俭率。
是翁九十乃未殂，
牙齿重生发如漆。
已无馀福在人间，
此理分明可谙悉。
健鹘生雏尽攫拿，
骄马作驹终覂逸。
寄谢悠悠世上儿，
过眼繁华如电失。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_3','谢氏池上观雪','黄玠','元','二月春光如水冷，
池上倚阑观雪影。
飘飘飒飒舞回风，
颠倒瑶花落天井。
鱼吹柳絮忽销沉，
却避寒澌依藻荇。
何处飞来双脊令，
令我悽然起遐省。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_4','次韵陈县尹汉卿见寄','黄玠','元','九华山前江水长，
平生故人黄绶郎。
百里犹将劳抚字，
欲行不行心未忙。
与君已在杖者列，
岂忆他时能醉狂。
恨无长云数百尺，
一吐愤思三千行。
草间雉子毛羽短，
不拟霄汉参翱翔。
题诗采石吊李白，
或者一驾西飞航。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_5','用水精丸炷火灼丹田中','黄玠','元','仙人掌上水精丸，
摘得金茎秋露颗。
亦同阳燧大蛤珠，
摩挲向日出真火。
冰台作炷丹田宫，
流光直射如血红。
梅花一夜孤根暖，
却笑小还无近功。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_6','拟送曹世长之官柳州赌博寨','黄玠','元','将军曹霸有令子，
躯干魁梧如北人。
辞亲再拜捧黄檄，
去作柳州游徼臣。
櫜鞬已乘官驿马，
顿置仍给公厨珍。
引弓之民百砦列，
控扼峤海安朱垠。
伏波故事亦久矣，
岂有铜柱犹嶙峋。
且当永念易播意，
持酒一酹罗池神。
孤云东北望新月，
山川迢遥来苦辛。
弹舌风雷语刺刺，
索笑万里梅花春。
桄榔大树粉作饵，
椰子酒熟甘而醇。
食膎每与华俗异，
慎勿触手腥蛇鳞。
爱君貌似娄师德，
故是方口又博唇。
古称容容多后福，
唾面自乾可勿嗔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_7','与宇文同知张主簿游道场山','黄玠','元','三月三日天气佳，
县官出城早休衙。
亦有前溪宇文氏，
水晶宫外看春花。
碧浪微风动浮玉，
翡翠兰苕采柔绿。
笑指高人读书处，
轻舟已到何山麓。
何山山头更是山，
路出千岩杳霭间。
僧居蜂房开户牖，
灭没紫翠飞朱丹。
川原忽满最高阁，
五湖烟云一凭阑。
昔年恶虎今在否，
但见丑石遗苍顽。
丽姝来往多如雨，
紫绫香䙬结金缕。
佛前细语人不闻，
倒坐蓝舆下山去。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_8','立春日赠仲珍弟','黄玠','元','阿父八十兄六十，
弟亦今年五十五。
千里一家同得春，
春日春盘行菜缕。
汝缘久别奉晨昏，
我仍渐老怀乡土。
常时相念惜相分，
此日相娱喜相睹。
劳碌馀生病后身，
陶写真情醉中语。
共将卮酒拜亲前，
岁岁亲前吾与汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_9','生日戏书','黄玠','元','天弧之南老星公，
素发垂耳冠夫容。
青鸾引车双羽童，
翩何姗姗来御风。
我生甲子旬再逢，
颠倒扑漉随飞蓬。
磬折而趋跽鞠躬，
神人妙颜冰雪容。
遗我松子种作松，
流肪千年虎珀红，
尔能得之寿乃翁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_10','韩季博所藏青山白云图','黄玠','元','门外马蹄三尺尘，
屋底青山看白云。
不知身世在城市，
但觉爽气吹冠巾。
鸭觜滩头沙渚露，
依约西陵近渔浦。
恼人归思满江东，
烟树半沉天欲雨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_11','酒歌','黄玠','元','酒可喜亦可嗔，
醒语多忌醉语真，
常恐醉语撑触人。
天上星辰何历历，
人间岐路长踆踆。
既不能挥戈回白日，
且当拍手歌青春。
酒固非所嗔，
本亦非所喜。
作事不称情，
寄怀聊复尔。
噫吁嚱，
牝而黄，
牡而骊，
先生既醉不暇知。
苦如薏，
涩如杜，
先生既醉不暇顾。
颂酒之德，
赞酒之功。
伟哉斯人，
吾其与同。
熊经鸟申尽无益，
三杯可使颜再红。
归去来，
游醉乡，
醉乡天地犹鸿荒。
卧看轩辕摇左角，
手挟北斗𣂏天浆。
令汝寿命百有二十岁，
与物无忤永相忘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_12','薄薄酒奉别吴季良二首','黄玠','元','薄薄酒，
可杯勺，
粗粗布，
宜浣濯，
丑妇耐贫勤织作。
我无南阳诸葛田，
赤手欲探蛟龙渊。
曲中箜篌十四弦，
河水东流心惘然。
角上蜗牛且酣战，
鹤胫自长凫自短。
井蛙海鳖相讥嘲，
何似雕鴳俱逍遥。
八珍之味不如良友，
千金之富不如佳儿。
百年一息万世痴，
庞公未为无所遗。
南山有木木有枝，
根如盘石不可移。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_13','薄薄酒奉别吴季良二首','黄玠','元','薄酒味薄情不薄，
丑妇貌丑心不丑。
君不见天下风流朱伯厚，
车如鸡栖马如狗。
河西蒲桃紫雪浆，
秦中琵琶妩媚娘。
黄金快意一日乐，
奄忽百岁如风狂。
天雨未休匏叶苦，
江湖水深不可渡。
豫章非𣏞众莫辨，
橀榽似檀人伐汝。
汉阴丈人抱瓮归，
万事反覆非一机。
博劳东去燕西飞，
毋与寸草争馀晖。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_14','题叶仲明府判竹君右丞公第二子也家于富阳','黄玠','元','虚廊静院连深竹，
色照窗扉如水绿。
题遍琅玕节下诗，
高兴满怀吟未足。
尽教梳洗出清风，
客来径造亦不俗。
出门咫尺是尘间，
野鸟纷纷自相逐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_15','过无锡呈五十三舅','黄玠','元','晓发澄江春水绿，
刺篙夜下梁溪宿。
老者今年六十三，
秀眉霜雪颜如玉。
大郎挟策青鸟市，
小郎恂恂侍巾襆。
就中中郎绝秀殊，
耽书动是千过读。
一门传恭复传孝，
如此穷饿心亦足。
舅甥情爱久更亲，
竟夕寒灯共华屋。
唤奴呼酒出羊淹，
重说生涯乱心曲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_16','即事','黄玠','元','苍头小奚得马刍，
黄吻稚儿看鱼罛。
白发老人教农书，
客来手把河洛书，
话到混沌开天初。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_17','日出柳树东哀刘先生也先生字环翁登进士第授建德录事卒于都下','黄玠','元','日出柳树东，
日没柳树西。
朝朝暮暮出复没，
柳叶黄落半为泥。
郁华仙人驾六螭，
急若弩矢谁能齐。
夸父逐之道暍死，
跬步万里生蒺藜。
千载同一朝，
白发如霜荑。
奈何性命不自理，
只思骑马听朝鸡。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_18','送韩与玉入京求其师张仲举先生','黄玠','元','君家兄弟森群玉，
数兼八韩仍两之。
复有一人更才敏，
将往京域求其师。
其师为谁子张氏，
曲颏美准秀且颀。
鸡栖昂昂立孤鹤，
羽翼已遂冲天飞。
昔年助教国子学，
横经气夺千皋比。
顷日还当大述作，
并录三史追前徽。
使者旁搜异书出，
天下学士来委蛇。
春秋用例如用律，
游夏犹将赞一辞。
直书无愧董狐笔，
上与日月争光辉。
子今行矣快先睹，
涉阅定有新闻知。
赤华之驹不受鞭，
顾影独立长鸣悲。
经途九轨奇骨见，
渠忍局促盐车为。
祗疑慈母手中线，
密缝政恐迟迟归。
文章有神国有造，
赠子脱颖双毛锥。
好音早寄南来雁，
无使淄尘污素衣。
梅花后夜琴曲苦，
满天明月照相思。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_19','赠制笔沈生','黄玠','元','月中仙人白兔公，
缟衣翩然乘玉虹。
遗我利器五色光，
将使奏赋蓬莱宫。
江淹老去才思劣，
夜郎归来亦华发。
愿乞瑶池不死方，
须得玄霜和紫雪。
剥啄叩门秋梦回，
有客真为黄香来。
坐中顿见两毛颖，
脱帽露顶美且䰄。
君不闻朔土贵人执笏思对事，
仓卒墨丸磨盾鼻。
何曾望见㕙与䨲，
马上柳条能作字。
后来雪庵松雪俱善书，
始爱都人张生黄鼠须。
安知沈郎晚出笔更好，
犹及馆阁供欧虞。
拔奇取俊锋锷见，
双兔健似生于菟。
用之不啻仗手檛，
颠倒纵横随所如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_20','种德堂诗','黄玠','元','树木犹为人所爱，
况尔宗盟磐石大。
条梢之末苟勿残，
可使亭亭似车盖。
枝叶能承雨露恩，
乃今流被及本根。
一门青紫什七八，
虽贵弗陵尊行尊。
保家要在全和气，
和气致祥乖气异。
云仍百体同一身，
恒使匀通有生意。
富贵浮生何敢期，
长长幼幼咸在斯。
肯道吾儿幼衰替，
煦妪愿如今日为。
昔之祖者今之祢，
推尔所爱达尔始。
如木有根种厥德，
尧舜之道孝弟而已矣。',NULL,'','{"preface": "青龙章俊甫取种德二字扁其中堂他日设广席大会其族人引二子某某遍见之曰赖祖宗之遗衣食幸有馀饶乃者众建义庄以给宗族吾父与仲父之素志从兄伯吉甫实继而成之区区之私所以奉尊长及卑幼者岁有常数不敢以复出而遂废俟是二儿能自植立户门伏腊之馀凡在席者将他有所资遗富贵无常忽则易人我后子孙有不如今日族之充裕者其勿能有所矜畀之乎噫达哉斯言所谓种德者已推而致之以及于远譬之种木枝叶必茂虽高其门使容驷马车可也余往岁吊其叔父兰溪大夫之丧吉甫以江淮财赋副总管居忧诸兄弟求分异俊甫调停其间意望有觖每以已分所得弥缝之卒无伤大体是信能轻于财者他有善未能尽知姑录此以示吾儿而为之诗", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_21','碧澜侍儿曲','黄玠','元','感之以诚感必深，
应之以真应必捷。
真诚一合两弗离，
听我长歌碧澜妾。
碧澜亦是诸王孙，
世殊事异老且贫。
少陵尚爱燕玉暖，
况是当时真贵人。
春衣典尽春寒峭，
二妾朱颜正姝好。
忍将罗带拆同心，
懊恨浮生头白早。
珠钿翠靥幸仅存，
此时犹及嫁夫君。
十二楼头燕子去，
挥手不用留仙裙。
去妾相悲两相约，
既去犹烦送肴酌。
主君讵忍覆弃之，
见此翻令情绪恶。
一心专，
天得知，
忍著主衣还事谁。
遂携衾襆与俱来，
后君死者当为尼。
碧澜堂下双溪水，
使客往来岂知此。
不愿新欢恋旧恩，
千万人中两人耳。',NULL,'','{"preface": "闻之谢长源吴兴赵碧澜老而贫二妾方少艾虑不能久安遣之曰吾囊箧中物鬻且尽惧及汝也可及此时事人既去弗肯嫁数具肴酒致慇勤于其卒覆诸水曰勿复来余惟割情忍爱以去尔也尔弗我忘祇搅我心既而与其父母俱至泣而言曰我家岁请给府中所积足赡供养奁妆具在愿执事终身为尼以报主恩他日果然碧澜死有寡女又资育之吁贤矣哉吾舅陈汝泉父妾贝氏守义弗嫁事颇相类既作是诗并以寄外弟子章子经", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_22','刘子舆清啸轩','黄玠','元','大哉扶舆，
动应有机，
律吕风云。
黄钟之宫，
发乎自然，
为声气君。
其在我人，
呵嘘吸呼，
节族以分。
啸乎啸乎，
何浊何清，
惟心所存。
力出尔手，
以挤则危，
以掖则安。
气出尔口，
以吹则寒，
以喣则温。
民各有趋，
狂者如籍，
壮者如琨。
嗟我怀人，
愤懑既舒，
亦已忘言。
冥玄洞虚，
不可以名，
以名斯轩。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_23','一姓三氏诗','黄玠','元','彼种树者，
更枝易叶。
以彼成此，
实相应接。
载息载滋，
两殊一合。
天时既从，
物亦允协。
本本支支，
纷其丛沓。
初气永存，
至纯不杂。',NULL,'','{"preface": "传曰因生以赐姓胙之土而命之氏氏者姓之别姓一而氏二者也钱唐陈君子安本姓王氏幼蒙恩养于陈氏姑姑无子请于其父为已子既乃婿于沈氏沈之后又无子身一而已不可以再易氏也子安三子参分之使各从其氏为之后而主其祀焉姓王氏正也姓陈氏恩也姓沈氏时也虽重轻大小之差各殊而亦事之弗得已也上古圣人盖有同出而异系者尧之姓伊耆高辛氏之子也简狄为高辛氏世妃祈于郊禖见玄鸟堕卵而生契契之姓子姜嫄亦为高辛氏世妃祈于郊媒见巨人迹履之生弃弃之姓姬是也况王与陈原其所自又皆舜妫姓之别乎是为诗曰", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_24','伯衡北上余在琏市作此诗以送之不及','黄玠','元','姨氏之子平生亲，
忆昨书来道相别。
青徐大小郡邑残，
却走梁园向京阙。
五河高原车斗风，
鲁缟齐纨吹欲裂。
读书岂是为一官，
倒著狐裘拥飞雪。
重游都市十年馀，
须得青袍慰华发。
日近蓬莱云气佳，
冰解滹沱水声活。
羊酪甘肥马酒醲，
土锉无烟石煤热。
金错披囊罄一欢，
橐笔縢觚待明发。
便令南斗避文星，
归插宫花醉吴月。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_25','龙头之西有伏龙山首枕巨海上有古寺云岚之气尝蒸蒸然如黄梅时唐会昌中诏毁天下僧寺寺僧作诗云云中有寺不容住天下无家何处归有旨得不毁癸酉岁余与族叔族弟及戴彦季同游获观先祖遗墨既暮余与族弟先归山半值大雷雨山上晴朗如故作诗以纪其事云','黄玠','元','青山如龙行且伏，
渴欲饮海海不足。
轻衫短屩小筇枝，
独上龙头叩龙腹。
龙腹空洞声豅豅，
岂有神仓闭神粟。
楝花风起鯼鱼来，
远望渔艘似浮鹜。
痛思我祖伯丰氏，
遗墨宛然三过读。
无食无家走千里，
尚赖馀休守觚牍。
瓜瓞子母相钩带，
断蔓残根仅能续。
徘徊瞻眺不胜情，
贫贱何由复邦族。
忽从岩半黑云生，
归去惊雷撼崖谷。
相望咫尺异阴晴，
众客山椒我山麓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_26','某甫者章氏之庶孽子也所出微不得与众兄弟齿治田庐供衣食比分财得黄金盘杆一其从父弟俊甫方脩青龙镇学一日持以造之曰我为农无用此吾家二先生死无后愿鬻此置祠学宫之侧买田收其租入春秋二时用少牢具祀之以徼福于先圣先贤慰吾父与伯父师弟子之心冥冥之中其为我经营之余与闻斯言时','黄玠','元','章氏孽子操心危，
少曰已爱躬芸芓。
夫耕于前妇后馌，
饮酒安用黄金卮。
不向尊前赏歌笑，
买田独置先生祠。
讵忍若敖无噍类，
工执艺事犹有师。
昔闻此语心为喜，
至今思之不能已。
到处真同说项斯，
遑恤他人恶闻此。
当时师说诒李蟠，
弃置床头如故纸。
乃今面目被生憎，
况肯兴怀尊死鬼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_27','伯清兄弟在者三人次仲实又次季博有练溪别业连云庄弗肯分异户门应酬衣食用费宾客燕会岁一人递收其田租以掌之为计帐以相交付同堂异室内外无间言于兹有年矣是亦保家之善道也不然则力分而用广日且不给况能久而弗坠哉是宜诗伯清即韩分石','黄玠','元','会稽公子谁与俦，
埙篪并和声相求。
户门多事须应酬，
茧丝谷粟岁递收。
公尔忘私无怨尤，
娣娣姒姒俱淑柔。
醪醴洁治蘋藻羞，
岁时祭飨礼数优。
譬如风波同一舟，
戚则共戚休亦休。
彼哉何人此弗犹，
兄弟生分如死雠。
上健下险森戈矛，
黄金用尽身为囚。
令我感叹泪欲流，
人无远虑多近忧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_28','冬至日','黄玠','元','大哉元气何冲融，
周流六虚相始终。
为阴为阳本非二，
政在往来升降中。
去年阳生阴已极，
今年阴消阳复息。
君子有道喜可知，
手把梅花看三易。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_29','西郊醉归似陈汉卿','黄玠','元','人间此客不可孤，
况此翕忽岁欲徂。
吴姬双歌送美酒，
半醉不醉娇相扶。
踏歌携手寻归路，
行云忽送巫山雨。
却上溪边舴艋舟，
舞衣湿透黄金缕。
短棹轻桡不相及，
依约中流闻笑语。
归来庭院已黄昏，
流水落花深闭门。
最思一事尤可怪，
笠子忘却溪南村。
梦回酒醒不复记，
清晓野夫来叩阍。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_30','藏钩似陈汉卿','黄玠','元','世故纷集如猬毛，
今我不乐年将慆。
汉家钩弋作隐戏，
聊足与客娱佳宵。
绿酒荡漾白银瓮，
红烛照耀黄金幖。
明妆列映左右侍，
大宾坐压东西曹。
平生刎颈托交契，
此日意气争分毫。
老拳攘袂坚莫取，
钩神瞪目不敢语。
搏兔壮士声若雷，
失马将军面如土。
忍将他日严毅颜，
涴墨涂鸦上眉宇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_31','馀姚吴季章松斋图','黄玠','元','四明山中木千章，
上有松树生高冈。
不与朴樕同翳荒，
雨露飘洒云之阳。
鹅溪大绢尺度方，
写貌形似分毫芒。
非龙非螭牙角狞，
开卷白日风雷生。
之子秀骨须眉苍，
与松为游三十霜。
小结茅屋松阴凉，
采松之花餐松肪。
弹琴诵诗送流光，
人生有情苦参商。
白水满地天茫茫，
安得送我置尔旁。
脱落世故遗纷庞，
乐与寿命如松长。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_32','伤春曲','黄玠','元','鸳鸯湖边花满蹊，
鸳鸯湖外草萋萋。
春风醉人骄马嘶，
玉花连钱锦障泥。
绣罗为襦金络缇，
鲜卑小带镂文犀。
哀哉王孙归路迷，
红娃翠压愁空闺。
昔时歌莺今不啼，
杨花堕泪章台西。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_33','寄李坦之','黄玠','元','神仙中人不可招，
薄言思之我心劳。
霞裾远曳风飘飘，
照影独立江之皋。
岂无囊中金错刀，
安得携手与游遨。
玉雁银筝紫□□，
吴娃双歌送春醪。
大江东流日滔滔，
江上春风吹碧桃，
花飞万点正魂销。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_34','寄钱竹深','黄玠','元','西方美人隔秋水，
优昙花开白云里。
白云无事长悠悠，
美人不来我心忧。
金井银床露如沐，
玉琴夜罢相思曲。
麝煤鼠尾生暗香，
吴笺染恨春波绿。
织乌西飞何日还，
赪桐始花亦已残。
人生有情歌欲绝，
明朝览镜凋朱颜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_35','辛未七月廿三日大雨','黄玠','元','孟秋之月月在毕，
雨气斗集云深黳。
悬河翻空海水立，
万瓦千霤如奔溪。
向来高原变洿泽，
巨浪上蹴天为低。
三吴良田入井底，
菜茹岂复如畛畦。
室庐藩溷尽漂没，
存者历落犹鸡栖。
男儿性命不自保，
往往中路遗嫛㜷。
书生有情泪沾臆，
落日黤黯秋云西。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_36','梅花庵为吴仲圭作','黄玠','元','函三一气初未分，
包括万象为阳春。
亦如孤根抱独暖，
不与桃李同光尘。
吁嗟此意知者少，
我欲往问庵中人。
高官不如士白贲，
厚富不如农赤贫。
结茅为椒小于笠，
翕翕鼻观通机神。
眼中见花不见我，
我身己与花为身。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_37','次韵王达之园池假山并似钱春野','黄玠','元','海上诸峰皆绝奇，
其高无颠下无涯。
一峰飞来在平地，
小小亦足同幽期。
近结斋庐处其下，
十里平川见多稼。
客来政有酒盈尊，
我生不作悠悠者。
突兀眼底多伟观，
如虎如貔气桓桓。
或窈而深如洞穴，
或峙而立如冈峦。
如积钱色万钧重，
如鸾鹄停欲飞动。
人间此景不可孤，
风月佳时与君共。
偎花倚竹相鲜新，
寒士亦各忘其贫。
胸中丘壑故不俗，
元章石交平生亲。
世变纷纷参复伍，
岁晚相看吾与汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_38','次韵贾玄英烈女祠祠在嵊县青枫岭至元丙子天台王氏妇被掠至此齧指血题诗石上云君王无道妾当灾弃女抛男逐马来夫面不知何日见妾身当是几时回伺兵士少间投崖下而死','黄玠','元','女郎号天杀气黑，
题诗齧指生血滴。
天白赤城山为低，
一掷万仞惊魂飞。
将军讵忍驱迫为，
夫君不见我心悲。
国破家亡两依依，
人命几何花脱枝。
不学明妃辞汉宠，
犹使胡儿拜青冢。
流光一去若箭弦，
安用马上啼婵娟。
语言侏离不可解，
妾有一身无二天。
节不可移头可碎，
口血未乾身已坠。
馀生含笑入九泉，
不向人间偶殊配。
天地阴阳有消息，
终始一心如铁石。
至今积水閟幽灵，
呜咽疑闻髑髅泣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_39','海大船','黄玠','元','太仓龙骧万斛船，
欲动不动艇子牵。
沙江水浅潮易落，
咫尺见海去莫前。
艇子勿誇尔能事，
士生未遇亦如此。
须臾水深风力强，
大船却将小艇行。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_40','采枸杞子作茶饼子','黄玠','元','流水河边见碧树，
上有万颗珊瑚珠。
此疑仙人不死药，
黄鹄衔子来方壶。
露犹未晞手自采，
和以玉粉溲云腴。
卧听松风响四壁，
未老更读千车书。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_41','穿石松歌为叶秀轩总管作','黄玠','元','阖闾古城城北东，
昆山迤逦盘苍龙。
天星之精下融结，
其中有石皆玲珑。
山农穿山若鲮鲤，
雄椎怒击雷光起。
木精土性莫敢私，
蚁垤蜂窠差足拟。
三吴主人欣得之，
保抱护惜犹婴儿。
剔抉泥沙出奇骨，
洗濯烟雾生神姿。
建昌花瓷培宿土，
徂徕稚松沐新雨。
却穿月窦出云凹，
山鬼髑髅毛发竖。
题书寄远情可知，
结交岁晚心勿移。
一卷自有丘壑意，
百折不受冰霜欺。
终朝坐对兀若痴，
茯苓琥珀生有时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_42','苦热行','黄玠','元','十日不雨草树焦，
一月不雨川源竭。
酷吏作威何可当，
大地流熺赤于血。
嗟我有情空自伤，
会擒女魃出神潢。
手挽悬河作甘澍，
坐使大地生清凉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_43','邹一初提点三清阁','黄玠','元','杰哉高阁开神区，
此地何必非玄都。
天上玉京十二楼，
飞来人间作画图。
栾栌交加虎兽伏，
甍宇轩翥龙鸾舒。
上方自与三境接，
星光历历种白榆。
晨朝焚香礼碧落，
仙风半空闻佩琚。
此生尘网如可脱，
愿为清歌随步虚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_44','天星湖上歌似吴泰然','黄玠','元','秀州孤城悬斗口，
中有湖水藏天星。
龙飞已去迹犹在，
灵宫故是白玉京。
题诗欲寄羡门子，
问讯或过茅初成。
交梨火枣如可得，
与尔相见夫容城。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_45','郑彦昭书巢','黄玠','元','郑生结屋名书巢，
岂欲巢居似巢父。
风南枝北两相忘，
焉用缪绸开牖户。
我闻在昔巢父时，
大道何曾立言语。
只从书契造文字，
后来作者多如雨。
生今所藏竟何书，
吾欲沧浪濯缨去。
尽令无用束高阁，
坐使民风返淳古。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_46','濮乐閒得唐雷霄琴黄南窗鼓之','黄玠','元','霹雳昼下乖龙升，
峄阳孤桐才具成。
大唐雷霄与斲削，
木精咋舌山鬼惊。
漆光拂拭净如水，
蛇跗欲走不得行。
主人爱琴仍爱客，
层轩白月秋夜清。
请君为我尽意弹，
我亦为君倾耳听。
上弦洋洋和且平，
下弦琅然如叩冰。
回头始疑崩石裂，
泛指忽作蜚鸿轻。
铜盘乱泣珠琲落，
铁挝碎击珊瑚鸣。
江山清空草木动，
律吕应会风云生。
挥杯弄影喜欲舞，
主客尔汝俱忘形。
人生交契如此酒，
子期知音复知声。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_47','似胡伯可','黄玠','元','人生百年如置棋，
东西南北何多岐。
白云自是山中物，
风雨一出归无期。
我居鸳湖上，
子在龙江湄。
能无咫尺书，
慰此深相思。
长干缘河小于带，
积水满地天光垂。
沧波老树沉欲没，
荒郊冷落如秋时。
小家流逃大屋走，
五种不入民情悲。
思君不见心欲折，
背人白鹭双飞飞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_48','送任子昭北上','黄玠','元','江南二月柳如缫，
欲折未折风骚骚。
天上神京春色好，
兰台玉堂多俊髦。
龙江公子少年日，
乃翁携之与游遨。
翰墨之馀及丹青，
譬彼鲁削非凡刀。
胡为历碌风尘下，
与世俯仰犹桔槔。
未必屠龙不及豨，
要是钓鱼须钓鳌。
亟亟上书自荐达，
一刺民瘼针如毛。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_49','同深甫万户前科赏樱桃','黄玠','元','将军黄金作佩符，
霹雳古篆雕天书。
上有赤赤三明珠，
卧护千里坚无虞。
重为王孙开酒壶，
溪鲫银丝鲙新鱼。
莼龟青小滑可呼，
樱桃结子红珊瑚。
吴姬能歌花不如，
坐拥翠袖飞琼觚，
人生百岁多欢娱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_50','与张叔方','黄玠','元','去年送君作巡官，
双悬雕弧夹马鞍。
今年巡官出迎客，
吠犬不闻山月白。
山人畏之若乳虎，
妖狐髑髅不敢舞。
豚阱鸡埘一万家，
谁子强梁能跋扈。
君不见南台贵臣急如火，
櫜鞬磬折趋道左。
州司尽避供给难，
君独从容无不可。
名驹千里毛骨奇，
雷霆破山亦霁威。
人生才美有如此，
岂可沉埋百寮底，
明朝雕鹗西风起。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_51','赠飞星学古仙','黄玠','元','学古仙，
双瞳如岩下电，
矆睒龙光碧花眩。
乱摘星辰掌上飞，
惊动当时出奇变。
扁舟适从何处来，
湖上鸳鸯乍相见。
袖间小轴锦作幖，
欲钓珊瑚入诗卷。
梅花一笑领略新，
笔底春回冰雪面。
脱尔身上六铢衣，
试我囊中五色线。
昔如羁鹤在樊笼，
今似韝鹰解绦旋。
刮目他年看阿蒙，
收拾黄金如土贱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_52','去矣行','黄玠','元','使我饮酒不如长鲸，
使我食肉不如猛虎。
昨夜雪深人未归，
明日冰开客当去。
念尔公家急急符，
白水无边走何所。
从闻海上有神仙，
上界于今亦官府。
君不见东墅老人粟万钟，
金钥牙筹弃如土。
秪有凄凉鬼绿珠，
怨魂相从泣寒雨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_53','赠永上人','黄玠','元','大休和尚少年日，
尽遗俗缘甘独孤。
人间纷纷臭如帤，
此身不可一日居。
黄金袅蹄明月珠，
美人如花绣裆襦。
收拾众有归元无，
不忍头颅生发须。
即以宅舍为庵庐，
袈裟折那衣五铢。
麻鞋蒲龛坐结趺，
口中波罗天竺书，
高蹈万古隘九区。
绕屋青青种春蔬，
焉能食肉更食鱼。
优昙花开满前除，
空色两忘心澹如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_54','江南稻　至元六年四月上海姚胜一等作閧','黄玠','元','江南稻，
雪色白可喜。
去年八月天雨多，
戢戢禾头尽生耳。
里正急公租，
饥人若羸鬼。
海獠大无知，
毒螫肆蛇虺。
军府上变羽檄飞，
白日森然五兵起。
鼓钲动地火赩天，
性命鸿毛同一燬。
古者反侧加天诛，
歼厥渠魁固常理。
卖剑可牛刀可犊，
不忍农夫亦遭此。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_55','将进酒','黄玠','元','君不见玉台明月镜，
朝朝拂拭生光辉。
上有双飞金鹊影，
识我少年红泽时。
山中小草无远志，
流景歘忽如猋驰。
向来鬒发似鸦羽，
此日春蚕吐白丝。
所以花前月下一壶酒，
古人痛饮无复疑。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_56','泽农','黄玠','元','泽农结屋如鸡栖，
舍中筑塍为畛畦。
春来无地生青草，
况有菜茹供朝齑。
劝农使者出行水，
对此不忍加鞭箠。
田中生鱼鱼尽肥，
屋底瘦人扶不起。
先生闭门听雨声，
为尔惆怅伤余情。
君不见纥干山头冻杀雀，
何不飞去生处乐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_57','庚辰四月廿日赴谢氏馆吴季良携酒为别','黄玠','元','东里先生乌角巾，
薄游吴中三十春。
闻言不如祁孔宾，
见道多惭程伯淳。
强聒自谓愚而神，
胶胶肫肫不可循。
故交零落参与辰，
独有一人长若新。
鸒斯之党何频频，
愿逢新人如故人。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_58','凤凰山','黄玠','元','九山联延何郁苍，
中有一山如凤凰。
凤凰不来名独好，
远势似欲高飞翔。
梧桐有支竹有实，
玉水侧出输天浆。
饥食渴饮无不可，
何独苦爱鸣朝阳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_59','淀山寺','黄玠','元','何年飞来湖上峰，
中有石穴藏蛟龙。
山僧留客共清夜，
竹炉怒吼松涛风。
忽疑坐我天竺下，
眉间秀色浮葱茏。
借尔摩尼如意珠，
听师波罗谈苦空。
与开心孔见真性，
随方应现无不从。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_60','夏日泛舟','黄玠','元','江边青蘋风欲秋，
江上白云如水流。
人间炎热不可处，
驾言出游写我忧。
乌匼小巾一角垫，
黄葛短袂凉飕飕。
白鸥飞来复飞去，
卧听横竹商声讴。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_61','范叔豹苕溪草堂歌','黄玠','元','苕之水，
向东流，
君家草堂溪水头。
一室小于溪上舟，
清风满屋长如秋。
甑中生尘鱼在釜，
终日哦诗摇两股。
君不见杜陵草堂花满川，
将军立马驻江干。
天吴紫凤补短褐，
安用行庖洗玉盘。
良无广厦千万间，
乃欲天下寒士俱欢颜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_62','赵仲穆山水图歌','黄玠','元','山有麓兮水有麋，
石礌礌兮彼渔之。
矶水有麋兮山有麓，
树翳翳兮彼樵之。
谷波极目兮双帆暮飞，
我怀伊人兮渺不知其所之。
采采兰若兮充尔佩袆，
弁之阳苕之浒兮来吾与归。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_63','期戴彦季不至','黄玠','元','众星荧荧不如月，
五金铮铮不如铁。
剡溪公子来何迟，
铁为灵金人不知。
君看针头小于刺，
摩挲生涩无光辉。
大哉天地共消息，
子北午南分坎离。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_64','双松图为程似道作','黄玠','元','双松挺然，
徂徕之巅。
历冰霜而不凋，
泽雨露而不妍。
尔植尔茂，
惟贞惟坚。
用以为君子寿，
如其年如其年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_65','画鲤','黄玠','元','以为鱼耶，
鳞甲已具。
以为龙耶，
头角未露。
时至则化，
厥施斯溥。
蜕骨天渊，
苍生霖雨。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_66','黄南窗小像','黄玠','元','著乌匼之短帽，
曳碧绡之轻裾。
若丹丘之孤鹤，
骨既清而亦癯。
嗟尔童子，
抱琴焉如。
日月不可与留，
归来兮乐吾初。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_67','吴莹之小像','黄玠','元','骨虽清而不枯，
貌虽丰而不腴。
有田与庐，
诵诗读书，
恂恂乎美且都。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_68','吴仲圭画松','黄玠','元','以尔为楹，
其直不可以中绳。
以尔为梠，
其曲不可以中矩。
一丘一壑，
多历年所。
白摧朽骨，
太阴雷雨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_69','吴景良农庆堂诗','黄玠','元','维扬禹疆，
厥壤维沃。
尔服尔耕，
贻我嘉谷。
翼翼冷风，
自南自东。
侯顺侯𡆬，
岁聿屡丰。
有稻有稌，
有𪍓有穱。
我庾既崇，
如山斯岳。
先民是遗，
匪予是能。
擪籥吹诗，
用荐厥声。
厥声洋洋，
式歌且咏。
锡庆自农，
畴敢弗敬。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_70','寄吴季良','黄玠','元','兰有馥兮，
芷有芳。
我怀伊人兮，
惟吴之良。
文武之道兮，
一弛一张。
力有所俟兮，
用有所藏。
机不可以豫谋兮，
变不可以豫量。
庶君子之明亮兮，
感余心兮伥伥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_71','故建昌州判岳德敏哀辞','黄玠','元','眷碧山之幽栖兮，
驾吾舟以遄迈。
升其堂不见其人兮，
抚遗孤以增慨。
览芳岁其犹未艾兮，
何佳木之先瘁。
嗟浮生之翕忽兮，
若奔马之历块。
舍昭晰之茂旦兮，
即永夕之昧昧。
三星奄其西没兮，
孤参横其谁待。
怀馆谷于畴曩兮，
辰历兹其三亥。
感余情之不能忘兮，
悼良会之莫再。
吊明月于中扃兮，
沥觞酒以再拜。
杂椒兰以为粻兮，
又荐之以芳茝。
招游魂于鄂之渚兮，
莫蛟龙之为害。
狐首丘其亦已兮，
羌虽死而弗悔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_72','别夹谷知事可与','黄玠','元','我爱杨子江心百鍊镜，
明于月，
冷于水，
揭之可以照天地。
我爱丰城土中三尺剑，
气如云，
质如银，
佩之可以服鬼神。
尚不如兰陵故人夹谷氏，
大雅愔愔古君子。
韬光自晦常有馀，
藏锋不试终为美。
眉间有色清而温，
玉佩琼琚照秋水。
我有朱弦白雪知者希。
一曲遂为相识始。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_73','堂堂歌','黄玠','元','君不见车如流水马如龙，
大道长驱耳生风。
床头黄金借颜色，
快意正在一日中。
又不见车如鸡栖马如狗，
侧足旁趋面生垢。
投人不遇刺欲漫，
失意宁论百年后。
凫胫自短鹤自长，
颠倒万事未可量。
西来江水东流去，
白日竟是为谁忙。
且当开尊酌美酒，
起舞顿足歌堂堂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_74','与陈众仲提举','黄玠','元','吾闻泉南山水远更奇，
三苏不得专蛾眉。
天海云风发胸臆，
波涛万丈倾雄辞。
越从江汉下南纪，
却入箕尾乘东维。
十年依光日月角，
一官遂作文章师。
平生学问龟五总，
小叩大撞无不知。
东海书生双井客，
思见君子瞻光仪。
君不闻龙泉干将自神物，
铁花生涩埋尘黳。
宁无华山赤土为我发光彩，
一使变化凌空飞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_75','送张叔方湘潭州税务大使','黄玠','元','使君足下远游履，
茇涉湘潭数千里。
江南柳色共依依，
亲老家贫须禄仕。
昔年裤褶作巡官，
矢箙弓櫜悬豹尾。
于今九九学算术，
却执牙筹筦州市。
炎洲蜑人卉为服，
西域贾胡珠作珥。
巴賨奇货积如山，
贱者翠毛兼象齿。
千万人中生俊杰，
识时所务非俗士。
与民尽用一分宽，
粗给官常斯可矣。
君家五世皆达官，
节槩两朝无比儗。
况尔诸孙有祖风，
为国理财聊小试。
扬子江头春雨深，
杯行未尽离歌起。
安得相从到楚乡，
澧有兰兮沅有芷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_76','竹鸡语','黄玠','元','泥滑滑，
江头路。
雨萧萧，
君莫去。
不辞路滑马行迟，
恐君衣裳污泥土。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_77','赠相士王云𡶌','黄玠','元','君不见秦时照胆镜，
光辉团团似明月。
明月自缺还自圆，
此镜一失三千年。
我疑神物犹在此，
飞入云𡶌眉睫里。
镜不解语君能言，
天机到处妙不传。
富贵功名顾盻间，
可使见者挥金泉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_78','题钱思复小像','黄玠','元','尔气之充，
尔色之愉。
博衿长裾，
而拱而趋。
雍雍于于，
山泽之臞。
是所谓温润，
而栗者欤。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_79','壶中一字至十字','黄玠','元','翁。
壶中。
无不容。
天地鸿濛。
其乐也融融。
一室烧丹灶红。
见松下青衣羽童。
是何年竹枝化为龙。
碧桃花下无日不春风。
我欲访山阴旧隐与参同。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_80','僧溥雨𡶌赞','黄玠','元','充然其气之濡也，
凝然其形之臞也。
缤缤乎其雨华也，
矻矻乎其𡶌居也。
遍满六虚不离一区，
非有而有非无而无。
卓卓乎，
西方圣人之徒欤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_81','春晚书怀四声体','黄玠','元','春晚翠阁，
朱户绣箔。
风起昼寂，
红雨乱落。
歌枕梦熟，
啼鸟唤客。
流景电激，
今岂复昨。
尊酒对客，
浮以大白。
余有暇日，
聊与共乐。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_82','阿剌吉','黄玠','元','阿剌吉，
酒之英，
清如井泉花，
白于寒露浆。
一酌咙胡生刺芒。
再酌肝肾犹沃汤。
三酌颠倒相扶将。
身如瓠壶水中央。
天地日月为奔忙。
经宿不解大苍黄。
阿剌吉，
何可当。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_83','古尊彝歌为濮乐閒作','黄玠','元','神物可使厌百祥，
左尊右彝相颉颃。
云雷古篆为文章，
饕餮异兽头角张。
丹砂空青金玉相，
星彩错落半赤苍。
摩挲犹作黄流香，
稽首再拜登斯堂。
手援北斗酌桂浆，
愿君饮此寿而康。
千古既往万古长，
于胥乐兮乐无央。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_84','悲歌行','黄玠','元','七月龙火正西流，
卧看玉宇悬清秋。
三辰旋转不得息，
万事反覆良悠悠。
川原尽为虎豹穴，
风雨常隔凤麟洲。
君不见愚夫凭河去不返，
寡妻遗妾怨箜篌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_85','海水竭','黄玠','元','海水竭，
海人熬波泪成血。
卤花凝白雪不如，
高廪露积万有馀。
征商不行榷法坏，
使者分司来趣卖。
农家食咸苦不多，
盐乎盐乎奈尔何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_86','观打春','黄玠','元','土牛送寒赤于火，
乌衣芒儿立牛左。
大府尊官五色鞭，
置酒高台打春破。
女魃吾知旱有神，
神或汝矜民尚可。
里正夜走急如风，
明日长官来劝农。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_87','采莲女','黄玠','元','妾本鸳鸯湖上女，
家在鸳鸯湖上住。
去年湖上采莲时，
将身嫁作商人妇。
商人今年行不归，
荷花欲语娇为谁。
閒看鸳鸯抛翠菂，
颜色如花命如薏。
莲有藕兮藕有丝，
郎君白面谁家儿。
水烟霏霏日催夕，
解后相逢莫相忆。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_88','参沙神歌','黄玠','元','参沙之神铁作身，
可以厌伏水怪降枫人。
去年汉盐官，
地坼灵海垠。
龙鱼凭怒不可驯，
潮汐奋决惊吾民。
南垣秉钧吏，
飞书报天子。
有命恤民瘝，
奇谋遂蜂起。
君不见临皋间，
剥山及骨赭以殷。
山气靡靡去不还，
山木惨惨愁无颜。
吴船衔尾七百里，
共输山石填海水。
沙虚岸陨势莫支，
虎落长筊非久计。
愚公于今无子孙，
操蛇之神聩不闻。
徒知发鸠有鸟名精卫，
衔冤蓄愤口欲弊。
参沙神，
嗟尔有力赑屃如庚辰，
便当为我桎梏疏属安朱垠。
海行故道从此始，
民情快乐天心喜。
大刻穹碑纪神美，
亿万斯年永无圮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_89','题蘧庐小像','黄玠','元','彼何人兮翩翩，
衣白苧兮纯玄。
曳扶留之枯枝，
若将去而复旋。
虎挟乙以谁威，
龟藏六而自全。
合归休乎吾土，
寄蘧庐以天年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_90','四时木犀歌','黄玠','元','山有木兮木有犀，
其花长秋何皑皑。
灵芝三秀书上瑞，
曾不及尔常芬菲。
初疑师文叩弦发清商，
无射应律变四时。
又疑女夷司花窃天和，
使尔枝格生妩媚。
物生根拨真自异，
天情岂得为尔私。
蟾宫别种万万古，
不与草木同凋萎。
安得灵风锵然驾鸾翼，
与尔上结青云知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_91','升平曲濮乐閒赏灯席上作','黄玠','元','歌升平，
尔田多稼我庾盈。
姑苏台边灯作市，
拦街小儿拜参星。
冰蚕作茧大如瓮，
火鼠摛毫白成雪。
鲛人试手织轻绡，
结束琉璃万明月。
月中五色花满围，
交光相罗宝纹□。
□奴然炬夜不瞑，
吹霞弄日摇春晖。
华屋煌煌耀深迥，
龙脑浮香留藻井。
云母屏开火树花，
水精帘泛金波影。
主人置酒清若渑，
桃花扇底来娇应。
朝廷有道与民乐，
制此一曲歌升平。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_92','种花吟','黄玠','元','满园种花不种桑，
野桑不入名花谱。
五陵豪家纨裤儿，
快乐岂知蚕绩苦。
欢娱未足事已垂，
富贵欺人年少去。
却携锄钁向桑间，
满眼看花花不语。
君不见金谷荒凉梓泽空，
春风锦障俱尘土。
悔不当时学种桑，
尽遣歌姬作蚕妇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_93','赠陆松隐','黄玠','元','武陵刘郎花下歌，
商雒黄公橘中乐。
隐居岂必巢云松，
要在披襟有丘壑。
肘后长悬不老方，
人间共爱长生药。
白发万丈吾何忧，
可待流肪成琥珀。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_94','感怀','黄玠','元','百年如舜华，
览之不盈把。
胡为蜗角争，
流血遍原野。
不闻楚王孙，
风雷生叱咤。
哀哉帐中歌，
美人双泣下。
吟诗故不恶，
饮酒亦大雅。
得失可忘言，
富贵天所假。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_95','程祥甫南山篇','黄玠','元','南中有山何巑岏，
崛起自是佳林峦。
不同躁者与物竞，
长得幽人推户看。
乌皮旧几歙石砚，
黄葛短衫湘竹冠。
此地烟霞足真赏，
他家图画空美观。
尚怜䟤跋风尘下，
俛首局促为盐官。
平生胸次故悠然，
取琴囊中时一弹。
松头秀色近可挹，
窗宇六月生苍寒。
便应许我分半榻，
永矢弗谖歌考槃。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_96','浮云道院诗二十二首，并引','刘鹗','元','青山五亩园，
随意茅三间。
竹树发佳趣，
好鸟鸣关关。
物情固自乐，
聊得开我颜。
长歌答天风，
以永今夕閒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_97','浮云道院诗二十二首，并引','刘鹗','元','胸次寡尘虑，
随寓皆可乐。
孰云柴桑里，
不似麒麟阁。
雨馀草初生，
风定花自落。
荣辱今两忘，
遗经在牛角。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_98','浮云道院诗二十二首，并引','刘鹗','元','广誉薄文绣，
美德贤膏梁。
信道苟不笃，
不几兹言狂。
春风散天和，
宇宙森众芳。
盛德固莫及，
千载遥相望。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_99','浮云道院诗二十二首，并引','刘鹗','元','生人以御物，
何事随物化？
五色双目盲，
昏昏旦为夜。
高处忽眼新，
令我重悲诧。
为塞陷天流，
云开见嵩华。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_100','浮云道院诗二十二首，并引','刘鹗','元','留心强为善，
万事当听天。
天定还胜人，
何须苦烦煎？
原宪竟得贫，
颜子不假年。
在彼不我知，
在我当勉旃。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_101','浮云道院诗二十二首，并引','刘鹗','元','有客远方来，
访我衡门下。
岂无一樽酒，
乐此芳时暇。
好风吹晚花，
绿醑粘盏斝。
痛饮君莫辞，
流水易衰谢。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_102','浮云道院诗二十二首，并引','刘鹗','元','春来农事及，
雨过田水满。
呼童具犁锄，
耕作趁春暖。
但愿黍稷稔，
客至得相款。
此外复何求，
读书识吾短。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_103','浮云道院诗二十二首，并引','刘鹗','元','失之要本无，
既得乃固有。
但知贫为常，
未知贱者丑。
贫贱与得失，
命矣果谁咎？
万态森前陈，
凝然袖吾手。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_104','浮云道院诗二十二首，并引','刘鹗','元','舞雩咏春风，
步履傍花柳。
此景信可乐，
胡为疾其首？
陶然天壤间，
万事皆我友。
惟应瓮头春，
不知今熟否？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_105','浮云道院诗二十二首，并引','刘鹗','元','静夜坐百态，
晓起俱不然。
奈何不自悟，
扰扰欲胜天。
效颦冀见好，
反以丑取捐。
劳心苟无益，
何如信吾缘？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_106','浮云道院诗二十二首，并引','刘鹗','元','权门手可热，
行路为低头。
一朝沧桑翻，
言之使人羞。
伉俪不能庇，
骨肉烂莫收。
悠然茅屋间，
老矣归山丘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_107','浮云道院诗二十二首，并引','刘鹗','元','田园儿女计，
为虑靡不周。
汲汲牛马走，
辛苦悲白头。
朱门有饿莩，
白屋生公侯。
是其禀气初，
穷达非人谋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_108','浮云道院诗二十二首，并引','刘鹗','元','象箸与玉杯，
其流至亡国。
箪瓢陋巷间，
千载有遗德。
采采陌上花，
岂无好颜色？
终然易零落，
岁晚愧松柏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_109','浮云道院诗二十二首，并引','刘鹗','元','孟氏有三乐，
其一无愧心。
俯仰苟无愧，
至乐不可任。
万化不得羁，
超然众芳林。
神仙甚非远，
何必海上寻？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_110','浮云道院诗二十二首，并引','刘鹗','元','知耻斯不辱，
知足常有馀。
岂无负郭田，
亦有堆床书。
春风茶新苗，
雨过还当锄。
准拟读书暇，
茗饮甘如酥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_111','浮云道院诗二十二首，并引','刘鹗','元','古人亦有言，
千橘万户侯。
思之亦烂熟，
有志今甫酬。
金丸炫落日，
清霜满林秋。
户侯讵能拟，
聊得供杖头。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_112','浮云道院诗二十二首，并引','刘鹗','元','骨肉半零落，
有弟差慰意。
日暮田园归，
浊酒聊共醉。
此酒可再得，
此日宁再世？
人间乐固多，
埙篪有真趣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_113','浮云道院诗二十二首，并引','刘鹗','元','春风日已和，
桑麻蔼新绿。
但可了寒暑，
生理亦自足。
沈浮闾里间，
我亦甘碌碌。
俯仰三百年，
苍然此乔木。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_114','浮云道院诗二十二首，并引','刘鹗','元','常怜世间人，
晚岁生恐怖。
问之此何因，
牵以物欲故。
孰知不得将，
此理当自悟。
云散月满怀，
清风湛归路。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_115','浮云道院诗二十二首，并引','刘鹗','元','东坡百世师，
其学常近禅。
虽堕斥逐中，
不作戚戚怜。
两赋耀赤壁，
尚此风泠然。
我梦从之游，
梦觉月满天。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_116','浮云道院诗二十二首，并引','刘鹗','元','常爱陶潜翁，
独归田园居。
采菊东篱间，
酌酒南山隅。
有琴更无弦，
随意良自如。
高风千载间，
太息谁其徒？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_117','拟古七首','刘鹗','元','万顷日二升，
千间夜六尺。
所用能几何，
何苦悴心力。
牙筹与鞭算，
役役夜继日。
百年俱苍苔，
徒资后人惜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_118','拟古七首','刘鹗','元','疏食以当肉，
缓步以当车。
兹言深服膺，
既稳仍且腴。
鄙哉弹铗君，
惓惓志鱼舆。
古人甚能言，
适与吾心如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_119','拟古七首','刘鹗','元','是心亦犹人，
我岂悲富贵？
极知得有命，
常恐坠不义。
才薄未易称，
去来矧难系。
何如田南山，
食力差少愧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_120','拟古七首','刘鹗','元','东邻有处女，
灼灼桃李神。
娉婷不肯嫁，
爱此天地身。
惟恐失所托，
悔恨难自陈。
踟蹰悄无言，
日照空闺春。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_121','拟古七首','刘鹗','元','荆山一片玉，
秀气钟鸿濛。
幽晖不自衒，
老雨苍苔封。
纷纷他山石，
举世多拙工。
卞和今岂无，
至宝宁终穷？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_122','拟古七首','刘鹗','元','京城海子上，
有僧持双铃。
诵经二十载，
寒暑白发生。
辛勤积涓埃，
佛阁开明荧。
吾心若更苦，
天地何冥冥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_123','拟古七首','刘鹗','元','沟断跻牺樽，
骐骥困盐车。
时乎将奈何，
今古谁贤愚？
北风号枯梢，
落日明寒芜。
未遇非所惜，
但恐流年徂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_124','寄黄州旧友四首','刘鹗','元','后会未有期，
岂意岁云变？
不知百年间，
正复能几见？
江湖北风多，
水阔雁无便。
此心剧悠悠，
庭树空倚遍。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_125','寄黄州旧友四首','刘鹗','元','客来为余言，
眠食两无恙。
殊乡吉语传，
慰我心怏怏。
我峨栖霞楼，
仙人在其上。
甚欲往从之，
烟水互莽苍。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_126','寄黄州旧友四首','刘鹗','元','旧书不忍读，
读之耿怀悲。
君子不共赏，
远在天一涯。
喜闻甘棠阴，
雨馀绿差差。
冰玉晚自守，
素志正相期。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_127','寄黄州旧友四首','刘鹗','元','雪霰日已集，
感此寒夜长。
浮云翳白日，
杀气时飞扬。
落叶鸣声悲，
游子思故乡。
去住不自料，
白云杳茫茫。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_128','秋来河水清','刘鹗','元','秋来河水清，
春来河水浑。
水性有二致，
维时有凉暄。
与时相推移，
物态谁具论？
夷险不易节，
永言此心存。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_129','云松巢','刘鹗','元','英英山上云，
郁郁涧底松。
高人抱奇姿，
适与云松同。
云不霖雨施，
松不栋梁为。
归巢云松间，
君元愧明时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_130','题集贤全大学士三首','刘鹗','元','高斋坐深夜，
幽事亦可悦。
恨无千黄金，
夜夜买明月。
买之匪有他，
怜月有圆缺。
愿言月长圆，
不照人离别。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_131','题集贤全大学士三首','刘鹗','元','仲舒不窥园，
我懒辄破戒。
穷冬万木枮，
菜叶青可爱。
羊肉岂不佳，
何如淡交耐。
苟能食其根，
黄河看如带。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_132','题集贤全大学士三首','刘鹗','元','虚窗对风雨，
因得观物妙。
君看四檐集，
不了一罅漏。
沧溟阔如天，
尾闾小如窦。
万事当防微，
悠然发孤笑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_133','寄弟肖庭二首','刘鹗','元','亲丧尚土浅，
游子怀帝乡。
每逢时节临，
重我涕泗滂。
有弟幸可托，
惟兄实无良。
中谋卜葬地，
未审君否臧？
我言兹山佳，
气聚风斯藏。
山川重盘礴，
形势森开张。
翻翻龙蛇集，
蔚蔚鸾凤翔。
东西极完密，
前后分低昂。
明堂可万马，
怀抱包洪荒。
纵未增福庆，
亦可免祸殃。
似堪妥亲灵，
此外俱荒唐。
进取贵果决，
筑舍讥道傍。
尧时只一夔，
竟克成大章。
缅怀父母恩，
罔极齐圆方。
愿言罄所积，
早得归山冈。
惟君当送终，
而我遂显扬。
出处各尽道，
庶可纾恐惶。
两年几寄书，
报章杳茫茫。
北风重寄此，
握笔情感伤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_134','寄弟肖庭二首','刘鹗','元','蟋蟀鸣我宇，
流月照我帷。
我岂铁石心，
宁能不怀归？
种茶南山园，
秋雨苗应肥。
不审木子树，
旱暵今稠稀。
惟应所树棘，
岁久还成篱。
中烦种橘枳，
及时好为之。
此事倘未遂，
今岁勿更迟。
常嗟树如此，
急景风飘吹。
不比王母桃，
动作千岁期。
庶几菟裘成，
晚岁相娱嬉。
连床遂所愿，
听雨忘心悲。
君看京城中，
缁尘化人衣。
百计虑已熟，
食力无瑕疵。
我言甚迂阔，
君亦当三思。
更烦语儿妷，
著意过庭诗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_135','南城书怀','刘鹗','元','新麦绿如韭，
嫩柳含青烟。
东风不私物，
赋与无媸妍。
天地妙化育，
至理昭鱼鸢。
愿言春服成，
我亦沂水边。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_136','菽水堂','刘鹗','元','菽水本澹泊，
母心常自安。
益知为养易，
独觉尽欢难。
孝子情何极，
为儒味每酸。
伫看三釜养，
紫诰写金鸾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_137','题渊泉二首','刘鹗','元','流泉何涓涓，
渊水深更静。
静影涵太虚，
天光发辉映。
积之非一朝，
充溢若天性。
怀哉圣学功，
君应日涵泳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_138','题渊泉二首','刘鹗','元','其出源无穷，
其积常有馀。
不比沟浍雨，
盈涸惟须臾。
幽深不可测，
下有神龙居。
持之作霖雨，
以应当时需。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_139','题朝阳斋','刘鹗','元','曈曈扶桑日，
流光射檐楹。
晨起披我衣，
旦气何其清。
万虑自澄湛，
油然善心萌。
愿学古圣人，
孜孜待鸡鸣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_140','独酌三首','刘鹗','元','聊持一尊酒，
独对西山酌。
我饮本不多，
借此以娱乐。
慨彼山中人，
岂无合仙药？
月出烟萝深，
思之在冥漠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_141','独酌三首','刘鹗','元','独酌花树下，
花影落酒中。
举杯试一吸，
酒尽影亦空。
引壶遂再酌，
花影重玲珑。
乃知酒有尽，
惟影原无穷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_142','独酌三首','刘鹗','元','木叶不饮酒，
胡为赪其颜？
我发不耐秋，
微霜点其间。
叶赪春更绿，
发白何由还？
人生不似叶，
何为空间关？
且可信所遇，
呼酒看西山。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_143','题刘养直南山书院三首','刘鹗','元','结屋南山下，
贮书书屋中。
愿将贻子孙，
百岁相终穷。
万事罕成算，
人生等飞蓬。
渐与桑梓远，
而与梅花同。
永言作汤沐，
说梦时相逢。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_144','题刘养直南山书院三首','刘鹗','元','种鱼亦有池，
艺蔬亦有圃。
胡为轻弃之，
遽忍去乡故。
人情薄如云，
时政猛于虎。
可怜伏腊供，
粗足了官府。
终然不能忘，
时复怀故土。
故土尚可怀，
孤云绕坟墓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_145','题刘养直南山书院三首','刘鹗','元','胸中饱藏书，
随地皆可屋。
适意即为好，
何必重乡曲？
岭南多梅花，
亦足慰幽独。
既免怀土讥，
乔迁岂非福？
异时须昌刘，
从君著芳族。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_146','题东城和尚旧所赠卷后','刘鹗','元','旧题墨如新，
重会俄九载。
俯仰异今昔，
令我重悲慨。
上人渐老大，
未觉颜色改。
富贵多危机，
山中福如海。',NULL,'','{"preface": "九年前，长南雄幕，重修帝师殿。殿成，命东城主之。庚寅，奉旨徵余翰林修撰，东城求一言为别，遂书此卷。戊戌，持节重来，师渐老，出旧卷，重求余题。因有所感，故为书古诗以荅。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_147','赵贞常以善斲琴遇知，琴成奏之，称旨，题其琴曰天历正音。国子监蓝信之徵予言二首','刘鹗','元','唐虞不可作，
大雅何寥寥！
居然正始音，
洋溢天历朝。
一鼓声气和，
再鼓阴阳调。
令我乐忘味，
彷佛齐闻韶。
峄阳多孤桐，
因得备采樵。
愿言圣明世，
勿弃爨下焦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_148','赵贞常以善斲琴遇知，琴成奏之，称旨，题其琴曰天历正音。国子监蓝信之徵予言二首','刘鹗','元','礼乐垂百年，
圣主乃当御。
奎章五云间，
人文日宣著。
子犹师挚始，
风比关雎世。
猗欤圣人心，
借此发天趣。
麟凤不在薮，
甘露降庭树。
大地皆薰风，
宁独子琴遇？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_149','题谈命杨见心','刘鹗','元','阴阳无端倪，
大化不少息。
叶落已复萌，
泉枯又还溢。
虚盈消长机，
今古岂终极？
既见天地心，
祸福从测识。
何须泛天河，
眷眷支机石。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_150','请君勿系驴','刘鹗','元','请君勿系驴，
驴劣伤我树。
树死不足悲，
所悲种树苦。
矧兹初夏临，
清阴绿如雨。
亦解招凉吹，
为我涤炎暑。
愿言共爱惜，
相与保迟暮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_151','大通驿阻风','刘鹗','元','秋晚方北征，
朔风撼平地。
差迟百计非，
留滞岂天意？
十日九不前，
半月始千里。
功名要多艰，
正患得之易。
少折轻疾心，
进德良在是。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_152','遣兴二首','刘鹗','元','万事勿介意，
时来即为之。
幽兰岂无芳，
不与春风期。
大化亦已定，
慎保冰雪姿。
笑歌柳阴中，
剑光白差差。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_153','遣兴二首','刘鹗','元','秋气日已肃，
稍觉庭树变。
江湖子非鱼，
风雨客如燕。
桓桓六尺躯，
漂母寄一砚。
伯牙莫我顾，
遂也羞自荐。
常悲楚卞氏，
刖足固求衒。
巢由古之人，
怀哉不可见。
坐久开我门，
江波白如练。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_154','度狼山','刘鹗','元','狼山出高迥，
风急过如箭。
凄凄挟沙砾，
点点尘吹面。
我马却复前，
努力与风战。
寒日淡如月，
湿雨满郊甸。
皮裘半为冰，
稍觉身体颤。
前村有人家，
酒熟亦堪荐。
关河老涉历，
霜雪饱谙练。
文夫政如此，
何必怀破砚？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_155','月夜','刘鹗','元','中宵月娟娟，
睡起得孤快。
树影在流水，
天地有真态。
洒然心镜空，
如或饮沆瀣。
妙趣苟得之，
著意成蒂芥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_156','通太傅院使存初弓麓庵，善书能诗','刘鹗','元','伊谁白云庵，
矫矫北山麓。
天书发光怪，
五色烂幽谷。
梅月照溪水，
霜雪见乔木。
窗虚自生白，
初起待朝旭。
慨彼庵中人，
奇姿美如玉。
学道存初心，
忘情淡无欲。
文章发天籁，
气节动坤轴。
亲承紫皇诏，
来往监玉局。
一卷黄庭经，
暇日应烂熟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_157','种柳','刘鹗','元','造化无停机，
岁月甚行路。
种柳不满年，
清阴已当户。
柔条亦可人，
随风为余舞。
即景殊怆然，
因悲树如此。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_158','偶题','刘鹗','元','客言不可信，
可信惟至理。
惟理苟可行，
不可即中止。
倘或徇客言，
事变无定体。
问客谢不知，
积谤俱在己。
尚观理若何，
勿为客所使。
题诗置座右，
聊识吾过尔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_159','舟次苏渡，南望诸山怪状，谩成','刘鹗','元','群山多不毛，
怪石忽涌出。
土壤剥落尽，
恍惚见山骨。
端方俄如屏，
秀耸忽如笏。
或员如覆釜，
或锐如顿笔。
千奇与万怪，
欲写难备述。
谁意寂寥中，
惊见此突兀？
双阙高倚云，
令人恣超忽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_160','山中即事','刘鹗','元','雾罢海日高，
衣襟尚馀湿。
高秋煖如春，
鸣禽忽相及。
草木罕黄落，
寒虫不成蛰。
时于极热中，
颇觉凉思集。
于此苟不察，
居然即成疾。
游子思故乡，
虚名空羁絷。
气候何纷纷，
朝夕常岌岌。
何如下泽车，
饱饭老乡邑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_161','次梅南刘先生韵','刘鹗','元','江梅苦难滋，
草木偏易长。
美人不可期，
有约辄屡爽。
惟君砺操行，
如蚓食槁壤。
十年不相逢，
令我劳远想。
畴昔夜梦君，
拄杖时敲门。
梦觉即买丝，
直将绣平原。
沧桑万变馀，
俄然睹孤根。
重以契阔久，
颇觉颜色温。
剧谈到时事，
剀切多危言。
猗欤忠节邦，
惊见善类蕃。
今秋风雨多，
江水何翻翻！
风浪日夕涌，
清者亦复浑。
惟馀江边梅，
高标至今存。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_162','感怀三首','刘鹗','元','丧乱八九年，
乾坤日流血。
人心久不古，
伦义悉磨灭。
豺虎在城市，
生民半鱼鳖。
张弓不得射，
令我重鸣咽。
欲付之忘言，
宁无愧司臬？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_163','感怀三首','刘鹗','元','醉者常百千，
醒者才一二。
苟或不自持，
醒者亦复醉。
诸君愿正大，
政好持善类。
庶几纲目张，
或可起憔悴。
政事如修明，
盗贼亦人尔。
无令贾长沙，
痛哭至流泪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_164','感怀三首','刘鹗','元','丧乱靡有定，
天下无全材。
苟不事淫酗，
辄复多疑猜。
徒知尚权势，
不恤治体乖。
生民化盗贼，
田里多蒿莱。
狂澜亦既倒，
纵挽不可回。
愿忍贾生泪，
且进渊明杯。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_165','早发湴湖，驿行康铜铺','刘鹗','元','小雨不滑道，
好风吹我衣。
畏途得清凉，
实亦天念之。
念之匪有他，
七十方督师。
上忧国步艰，
下悯生民疲。
区区当努力，
早见平淮碑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_166','寄蒙君礼元帅，并书蒙泉二大字以贻之','刘鹗','元','清泉出深山，
初若甚蒙昧。
昼夜不住流，
日积渐充大。
滔滔忽成川，
滚滚直到海。
非比沟浍盈，
其涸可立待。
一朝随苍龙，
化作霖雨霈。
万物俱沾濡，
初不分内外。
赋诗重期君，
奇勋著昭代。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_167','感时','刘鹗','元','世变日已深，
人心不如古。
狐狸向人号，
鳅鳝为谁舞？
承恩喜则人，
怫意怒还虎。
白日当交衢，
杀人莫知禦。
官府不敢问，
曲意尽摩抚。
生者半逃移，
死者空尘土。
礼法徒有名，
生民已无主。
矧今居官人，
冰炭生肺腑。
中心为私室，
藉口誇公举。
何意慕蔺廉，
当面成汉楚。
事功无由成，
丧乱遽如雨。
上天亦何怒，
生民亦何苦？
红日将西沈，
悲歌望伊吕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_168','齿落','刘鹗','元','去年落一牙，
今年落三齿。
动者日已落，
存者能有几？
齿落何足悲，
所悲岁月逝。
行年已七十，
德业无可纪。
远愧赵充国，
成名向边鄙。
作图上方略，
虽老何亹亹！
岂独誇当时，
馀光耀青史。
我今往韶雄，
事势焉能已？
汉贼不两立，
直欲洗国耻。
梅关一岭隔，
调度亦易尔。
会当杀贼奴，
持以报天子。
何妨衣绣衣，
持节老乡里。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_169','题韶州图','刘鹗','元','貂蝉一何高，
武溪一何深！
可怜画师笔，
写余故乡心。
故乡有何好，
桑梓高成阴。
童时所钓游，
至乐不复寻。
重念松与楸，
斧斤日相侵。
庄舄岂不显，
怀土仍越吟。
游鱼恋故渊，
栖鸟恋旧林。
微物尚且尔，
况被冠与簪。
余年已七十，
持节沧海浔。
南北欲断绝，
世道多崎嵚。
田园谩入梦，
鱼雁亦已沈。
纵使铁石肠，
宁能不沾襟？
劫运会已极，
天道当祸淫。
愿言辅吾志，
此贼真成擒。
浩歌返鸡山，
理我无弦琴。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_170','人心如春天','刘鹗','元','人心如春天，
变态不常一。
纷纷乍飞雨，
杲杲俄出日。
解衣遽生寒，
添衣又还热。
寒热既不时，
命我重致疾。
人心固难知，
春天亦叵测。
万事当自防，
底用长叹息？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_171','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
讨贼奋英武。
所至缚贼奴，
将以血觉鼓。
淮阴信无双，
哙等焉足伍？
年富力正强，
成功报明主。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_172','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
赋性机甚警。
沈毅罕言语，
每发中肯綮。
及其闻善言，
沛然发深省。
酷吏尽扫除，
疲民得苏醒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_173','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
忧国常戚戚。
韶民苦凋瘵，
军赋从何出？
慨然示无私，
政令始归一。
仓库岂不盈，
稽之不终日。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_174','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
苦天久不雨。
青黄不相续，
斯民亦良苦。
忠诚自心出，
虔祷遽如许！
神灵亦阴相，
青天雨如澍。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_175','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
拟归集精兵。
凉秋八九月，
伫看官陂平。
其馀持土苴，
不战将自倾。
与子当并驱，
笑敚南雄城。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_176','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
号令甚严肃。
荒村人夜行，
空谷鬼昼哭。
风霆无留滞，
迅若置邮速。
昨日归牵牛，
推恩及茅屋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_177','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
仗义能急难。
水陆势既合，
破贼笑谈间。
声名播南海，
威武耀北蛮。
明当唤班固，
勒名貂蝉山。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_178','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
罕与污冗亲。
所以奸谀夫，
无所容其身。
况耳不妄听，
中心明如神。
谁知杀贼汉，
高出知书人。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_179','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
密尔宜章市。
公然一榻外，
老贼敢鼾睡。
一朝生致之，
持归献天子。
天子嘉其功，
声名播寰宇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_180','送邝将军元帅还郴古诗十首','刘鹗','元','桓桓邝将军，
民社当自重。
但愿贼扫除，
勿遣民倥偬。
居民苟一空，
城存复何用？
此理君固知，
丁宁为君诵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_181','滑石径','刘鹗','元','盛暑远行役，
既老尤难堪。
矧兹滑石径，
乱石何崇巉！
上有千丈崖，
下有百尺潭。
于焉苟失脚，
下饱饥蛟馋。
况余发尽白，
齿落馀二三。
胡为远行役，
揽辔冲瘴岚。
为怀圣主恩，
优渥如云昙。
临难重却避，
臣子宁无惭？
平生志许国，
何敢辞苦甘？
乌知有险阻，
快若乘风帆。
督师急讨贼，
丑类俱除芟。
持以谢明主，
拂袖还江南。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_182','家叔西隐结亭，额曰暖翠，赋诗见寄，次韵寄亭上','刘鹗','元','白发逢盛世，
昕夕凤翔翱。
青山读旧书，
灯火双目蒿。
间从淡泊馀，
世与鸿蒙遭。
此意自有得，
此心不知劳。
不为溟渤鲲，
不作井里螬。
孤亭抚万竹，
无愧五柳陶。
试询紫罗裳，
曷若粗布袍？
暖翠滴衣袂，
朱颜如春桃。
清风飒相遇，
须鬓何萧骚！
阿咸老京国，
俯仰随官曹。
富贵多危机，
平地生波涛。
回头眄兹亭，
孰谓云台高？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_183','秋江送别','刘鹗','元','知己别已难，
木落秋正暮。
明朝孤船开，
苔生别时路。
归看庾岭梅，
已觉花盈树。
回看章水云，
驰情重含楚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_184','题彭氏月池二首','刘鹗','元','高人散幽怀，
独爱池水净。
明月俄飞来，
池光渐如镜。
中有骊龙珠，
纷纷白光映。
静影涵太虚，
悠悠见天性。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_185','题彭氏月池二首','刘鹗','元','好斫月中桂，
莫种池上松。
为谂结繁阴，
虚白生朦胧。
回波忽成弦，
澹澹来天风。
光彩更流丽，
感此多新功。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_186','题黄德明所藏山居图','刘鹗','元','茅屋依密树，
弯溪驾长桥。
山光远泛泛，
野兴寒萧萧。
寡合人所忌，
幽居谁见招？
抚时尘满眼，
亦欲从渔樵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_187','题琴隐','刘鹗','元','抱琴将何之，
驾言归山阴。
南风苦难招，
逃虚岂初心？
钟期固可铸，
但恨无黄金。
惟应涧中泉，
知余为和音。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_188','渊明漉酒巾','刘鹗','元','脱我头上巾，
漉此壶中酒。
糟粕既已无，
渣滓复何有？
陶然见天真，
长风起高柳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_189','听琴图','刘鹗','元','山水有天趣，
写向膝上琴。
听者不少违，
独觉用意深。
古今那可期，
令我重愧今。
审音谅匪难，
所贵相知心。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_190','戏题婴儿图','刘鹗','元','大儿初脱怀，
小儿犹恋乳。
凯风棘成薪，
母氏亦良苦。
人生襁褓中，
焉识母如此？
兹图用情深，
人应尽为子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_191','题赣太守文山与曾通判崖山追劄子后','刘鹗','元','古人重友谊，
不计官崇卑。
况以桑梓亲，
谦厚浮情辞。
节物重稠叠，
翰墨光淋漓。
不谄亦不渎，
二老真吾师。
题诗语薄俗，
勿以富贵移。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_192','采莲女','刘鹗','元','采莲本贫女，
出身甚寒薇。
为因妙歌舞，
遍体蒙珠玑。
睹此忽有感，
中夜常三思。
士当患无实，
不患无人知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_193','闻邻哭有感','刘鹗','元','母哭其子长，
妇哭其夫短。
子魂不可招，
空使母肠断。
母泪似海水，
海水亦有岸。
人间为母心，
怀哉泪㳽旦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_194','游南华山','刘鹗','元','过此不可来，
来游必须遍。
山色青可掬，
溪水甘可荐。
低头拜祖师，
妙音满唐殿。
云何八百年，
生色尚在面。
三生信有缘，
世乱能一见。
一见了即休，
敢作桑下恋。
别师出山门，
山云白如练。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_195','述怀','刘鹗','元','马无千里姿，
伯乐固时有。
琴无山水音，
钟期未尝朽。
落落不自强，
敢怨贾不售？
从今当闭门，
内省原无疚。
珠玉倘有在，
山川自明秀。
遁世莫我知，
我亦甘白首。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_196','四皓','刘鹗','元','汉祖事嫚骂，
耻以长策干。
生平义不辱，
远隐商山间。
轩冕多险巇，
衣冠自高閒。
芝草甘且腴，
白发明苍颜。
超然高物表，
于世了不关。
一朝诣阙下，
汉室安如山。
信有大力量，
谈笑回强澜。
始知老英雄，
未易浅近观。
藏器固有待，
时至功无难。
往往渭水滨，
托兴事钓竿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_197','过龙门','刘鹗','元','龙门郁嵯峨，
岩壑幽更深。
云气拥石壁，
雷雨悬太阴。
远游得胜槩，
良足写我心。
无人鞭长蛟，
为予一长吟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_198','南城门外书所见二首','刘鹗','元','青松夹前道，
白杨荫崇垣。
鲜鲜石麒麟，
不知谁家坟？
有客行且歌，
歌罢向我言。
为言坟中人，
生时乘华轩。
粉黛左右侍，
车马前后奔。
乘时不饮酒，
今日空成尘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_199','南城门外书所见二首','刘鹗','元','我行荒林翳，
道傍卧丰碑。
平生颇好古，
下马细读之。
卢龙刘节度，
生当大唐时。
杖策奋威武，
勋业开边陲。
人无百年身，
既盛还当衰。
植此颂功德，
亦有千年期。
埋没蔓草间，
赫赫谁复知？
往者已可叹，
来者更可悲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_200','题刘翀霄五世图','刘鹗','元','昔闻康节翁，
慈母八十馀。
阶前小稚子，
欢笑娱相呼。
甘旨足丰俭，
自谓此乐无。
今君祖母秦，
九十康强俱。
牙齿尽完好，
起居不资扶。
鲜鲜芙蓉裳，
皎皎明月裾。
䌽舆亲迎养，
独觉爱日舒。
有儿俱白颠，
有孙亦银须。
曾玄绕膝下，
日向庭闱趋。
一门极孝友，
五世咸怡愉。
矧君自奇士，
振策当要途。
风云接平步，
日月明亨衢。
覃恩追考妣，
盛事誇里闾。
苟非母厚德，
此福宁独居？
恨无汉史笔，
逐一为母书。
嗟予辱同姓，
感念成长吁。
祖年百又一，
孙子纷如圭。
深衣昼锦缘，
曾绘家庆图。
寿康世莫比，
好事传京都。
翰林欧苏辈，
诗颂焉可诬？
及今甫七载，
往事浮云徂。
我恨岂有极，
君乐当何如？
题诗卷还君，
悠然泪盈袪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_201','题渊明图','刘鹗','元','雨过林壑静，
寒禽变幽响。
稚子操一瓢，
良辰逐孤往。
微吹惊帽纱，
落日在鹤氅。
无营神自充，
有道心更广。
篱菊虽未花，
随意得真赏。
岂诚嗜杯酒，
借此陶所养。
先生真吾师，
开卷慰遐想。
鄙哉粘壁蛄，
白发心怏怏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_202','夜宿何家寨，寨中止魏、于二姓，为婚姻','刘鹗','元','驱马涉深涧，
山径极深窈。
蜂房比老屋，
矗矗寄林薮。
颇辞尘俗喧，
迥出烟霞杪。
逡巡问主人：
住此安乐否？
主人向我言，
两姓世相守。
辈辈为婚姻，
已是百年久。
开群自牛羊，
忘归任鸡狗。
怡然古人风，
此事出意表。
须臾罗酒浆，
儿女忽环绕。
殷勤劝我饮，
殊觉礼数厚。
自辞酒味薄，
将意不堪口。
聊得慰寂寞，
且用息奔走。
蘧庐止一宿，
漂泊等飞鸟。
愁多不成寐，
庭树鸡戒晓。
天明趋长途，
失笑愧林叟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_203','高佥事招饮于城西门燕山亭','刘鹗','元','步出城西门，
晴日光离离。
不知春浅深，
绿叶含晓滋。
感兹时物变，
但恐毛发衰。
徘徊燕山亭，
胜友相追随。
鲜鲜棠梨花，
灼灼丁香蕤。
节序固已晚，
聊复折一枝。
缅怀古之人，
俯仰令心悲。
草玄良自苦，
献璞宁非痴？
何如即时酒，
歌我浮云诗。
渔人发清响，
远过竹与丝。
风吹罗衣裳，
为子舞僛僛。
微酣剧谈笑，
倒景已莫追。
为乐慎勿极，
苟无负良时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_204','木槎径','刘鹗','元','我行木槎径，
树木高蔽天。
径幽欲无路，
树老不记年。
盛夏霜霰集，
白昼雷雨悬。
头碍卑树枝，
足踏深涧泉。
仰看咫尺间，
半日不得前。
方兹汗如雨，
陡觉风凄然。
行人谬调摄，
疾病相缠绵。
况苦乏药物，
病亦何由痊？
古人号瘴乡，
于以待贬迁。
予生果何为，
自愧亦自怜。
一官号持斧，
从者多控弦。
精神复矍铄，
手足多胝胼。
据鞍气愈壮，
报国心愈坚。
愿言早平寇，
归泛胥江船。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_205','寄监宪','刘鹗','元','乱鸦忽收声，
群鹊逐我屋。
俄传报捷来，
渠魁已就戮。
生民久涂炭，
郡邑久陵谷。
道路少人行，
冤鬼白昼哭。
抚时乱已极，
在理往必复。
桓桓邝将军，
骁勇时所独。
将军固可嘉，
主宪多盛福。
上天既悔祸，
盗贼亦厌乱。
何况天下心，
乱极重思汉。
五羊号雄藩，
地列江右半。
鱼盐足富利，
戎马素强悍。
宪君居是间，
九载屡克叛。
运筹多玄机，
临事有成算。
声名达宸聪，
美誉流汗漫。
西江望旌旗，
如望雨济旱。
政宜挥千金，
谈笑遣黥灌。
乘机捣豫章，
克复在夕旦。
笑提叛臣头，
庾岭作京观。
千秋万古间，
留得路人看。
勋业垂无穷，
人生如露电。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_206','秋日即事','刘鹗','元','我辞五羊来，
老气凌云浮。
意谓此孽丑，
端可一战收。
秋初抵韶阳，
事有大不侔。
主将恣贪暴，
田里多怨愁。
军马晨星稀，
盗贼春云稠。
倏围响石砦，
穷迫已可忧。
又闻湖南陈，
围困连桂州。
谭侯弃南雄，
笃意归旧丘。
牒报关外寇，
复有开韶谋。
民情堪恟恟，
俨如浪中舟。
乞师与请粮，
使者交庭陬。
蹇余持空拳，
无可应其求。
虽云百冗集，
乌足回其头？
精神强奋迅，
随意相应酬。
或诱以好爵，
或赉以银瓯。
或时纠民丁，
相予执戈矛。
南北各有事，
惟幄聊运筹。
胸次日扰扰，
回首已仲秋。
连桂忽报捷，
杀贼如星流。
州城虽无恙，
民物日已偷。
皇天实相我，
幸不贻时羞。
所嗟响石砦，
竟为贼俘囚。
援兵既不利，
与贼空为雠。
桓桓蒙将军，
忠义谁与俦？
讨贼为已任，
誓灭贼乃休。
雍容风鸣树，
便捷鹰脱韝。
临事每千虑，
为虑靡不周。
聚粮辄充栋，
飨士时椎牛。
意气益倾倒，
士乐从之游。
于时赖有此，
长笑看吴钩。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_207','枕上偶成','刘鹗','元','欹枕闻晨鸡，
似觉微阳动。
吹灯起静坐，
聊得醒醉梦。
神仙似可学，
惟在制铅汞。
精神一相交，
龙虎自迎送。
周流如转轮，
迅捷等飞鞚。
或疑云雾蒸，
又若春泉涌。
舌本甜如饴，
远过甘露瓮。
天根与月窟，
春意满空洞。
始信中庸书，
中实多妙用。
蹇余迫衰暮，
王事何倥偬！
有息当自调，
有心苦未统。
归理蓝田云，
相期玉堪种。
留侯惜已远，
此约谁与共？
何年揖浮丘，
丹霄驾飞凤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_208','官军破苏村，恶其与贼通。贼兵破白沙，恶民之不相随','刘鹗','元','苍生果何辜，
十载堕涂炭。
天心不可知，
令我重悲惋。
自从丧乱来，
盗贼苦搆患。
有田不能耕，
有园不能灌。
牛羊被虏掠，
妻子各分散。
穷冬尚无衣，
日午犹未饭。
官府不我恤，
沈浮等鸥雁。
胁从姑偷生，
纵死冀少缓。
昨夜官军来，
又复诛反叛。
粗豪甚豺狼，
猛毒如狴犴。
一槩尽杀掠，
去贼才一间。
玉石俱不分，
生民重糜烂。
纵贼官府嗔，
为民贼杂乱。
左右将安归，
泛若无畔岸。
新春雨潇潇，
何忍听悲叹。
愿言忍须臾，
维持夜将旦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_209','四月十三，书所见','刘鹗','元','天历二载春客燕，
河清海晏消戈鋋。
上林四月风日妍，
乘舆思乐游龙船。
凤辇并驾花云軿，
骑麟翳凤骖群仙。
鸾旂属车相后先，
牙樯锦缆相蝉联。
万马杂遝蒙锦鞯，
千官扈从控紫弦。
和风不动舟徐牵，
琼童玉女歌采莲。
黄门传宣奏钧天，
龙伯国人夜不眠。
金支翠旆千花钿，
光怪出没明遥川。
红云翠雾覆锦筵，
青鸟飞去当帝前。
珍羞玉食罗纷骈，
驼峰骆乳繁馨鲜。
御炉紫烟浮龙涎，
金瓯璚液凝醴泉。
才人歌舞争取怜，
南金蜀锦轻弃捐。
龙颜一笑春八埏，
臣子拜舞呼万年。
呜呼！
吾皇圣智轶汉宣，
但恨子虚之赋，
无一能为君王传。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_210','醉歌','刘鹗','元','常闻有客卑当时，
我谓客语更过之。
及今更事匪客过，
往往亦足卑当时。
胸中怆惶失所主，
忽为虎兮忽为鼠。
昨朝蝴蝶今不飞，
旧日衣冠为谁舞？
令人睹此中心哀，
飘然欲赋归去来。
山中酒熟花正开，
人间久无燕昭台。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_211','题宁戚叩角图','刘鹗','元','丈夫有志凌青云，
时穷偶与蓬蒿群。
牵衣饭牛岂所乐，
一饭不敢忘吾君。
雪花光芒岁将晏，
叩角长歌发悲叹。
草团箬笠不禁寒，
长夜漫漫几时旦？
嗟我齐桓真好贤，
拔之牛口行青天。
君臣庆会勋业异，
千年汗简犹流传。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_212','食黄瓜二章，章五句','刘鹗','元','燕山五月新尝瓜，
浅黄深碧风韵佳。
食之飕飕清齿牙，
时来微物亦荐达，
使我抚髀长咨嗟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_213','食黄瓜二章，章五句','刘鹗','元','却忆去年之来时，
天风摇荡黄花期。
回首岁月如云驰，
人生斗酒即行乐，
功名竹帛将何为？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_214','岭南即事','刘鹗','元','昨朝炎风今日雨，
今日浓云昨朝暑。
阴晴寒暑片时间，
到此令人信难处。
矧今世事多舛讹，
晴日常少阴常多。
随宜料理强排遣，
天运若此将如何？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_215','题东山高卧图','刘鹗','元','君不见今将官，
徒知学公携妓游东山。
一朝传闻贼至关，
匹马远窜不复还。
又不见桓司马秦苻坚，
叛逆之气凌云烟。
惟公胸中兵甲全，
成功谈笑神怡然。
嗟哉！
方今群盗等蝼蚁，
之子见公应愧死。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_216','子卿持节图','刘鹗','元','龙沙茫茫雪如雨，
大窖雪寒羝不乳。
孤臣持节十九年，
忍死不降思报主。
方今世事纷如雨，
同安虎头真忠臣。
江州太守骨已朽，
尚书却作洪都守。
感时抚卷雪漫空，
为吊忠魂酹尊酒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_217','题礼部尚书巎子山','刘鹗','元','神仙亦时有，
公子间时无。
公子世岂无，
不如公读书。
神情俊朗自仙骨，
清淑之气钟扶舆。
娟娟夜月明瑶瑜，
灿灿秋水涵芙蕖。
既不爱臂鹰逐兔驰飞菟，
又不喜杨花扑帐斟流酥。
心之所乐者，
左置史，
右列图。
笔床茶灶胜具俱，
衣冠文物来群儒。
清宵管弦罢歌舞，
白昼翰墨供欢娱。
列职于春官，
复能以礼乐致主于唐虞。
主上眷顾桓渠渠，
功臣世胄有如此。
风雨乔木清敷腴，
公子可谓间世无。
且闻有巙山，
乃是公所居。
清泉白石日辉洁，
幽花野草春扶疏。
山中桃李亦仙品，
风月迥与人间殊。
公犹神仙山蓬壶，
惟公与山闻京都。
蹇予抱大拙，
来此亦已久。
既不能弹铗干田文，
又不能学求齐以吹竽。
世尚誇诈吾迂阔，
吾笃信义人浮虚。
凿圆枘方，
龃龉不相入。
旦夕惟有食破砚，
迩来冰冻砚亦枯。
然亦甘崎岖，
乐此无怨吁。
进退必以正，
求为圣人徒。
闻公高谊压千古，
所以愿曳侯门裾。
其足非趑趄，
其口非嗫嚅，
其诗非狂亦非谀。
尝闻昌黎言，
以为古来王公布衣前后常相须。
乃可千载垂名誉，
吾意若此公踌躇，
遇与不遇天何如？',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_218','归来乎','刘鹗','元','归来乎，
既不能如田千秋，
一言悟主生封侯。
又不能如主父偃，
奏书直上黄金殿。
君臣千载遇合难，
饭牛长夜何漫漫。
胡为久客众公间，
进退俯仰多腼颜。
归来乎，
孟尝君，
不可作，
平原君，
骨亦枯。
买丝欲绣空模糊，
迩来卿相不好儒，
客且无履安得珠。
虽云二子未尽道，
尚能与客相倾倒。
白玉楼空燕不飞，
黄金台圮生秋草。
归来乎，
京师不可以久留，
岁晚霜雪侵貂裘。
山中风月如清流，
醉馀菊花簪满头。
千秋奚足顾，
主父焉能俦？
归来乎，
先人有书今尚存，
青灯夜雨当细论。
孰云落落苦难合，
有志可致乎青云。
他年岁君在癸酉，
看花烂醉琼林酒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_219','群公见和又答四首','刘鹗','元','归来乎，
蟪蛄生不知春秋，
变灭顷刻犹王侯。
归来乎，
五陵草木尽披偃，
昨日秋萤满梁殿。
废兴反掌元非难，
海水清浅尘㳽漫。
吾宁终老青山间，
猿吟鹤唳聊醒颜。
归来乎，
唤童子，
治我圃。
无使霜后菜本枯，
禦寒更遣窗重糊。
从教壮士嗤为儒，
我价自若照乘珠。
文章乌足存古道，
底用词源三峡倒。
功名已付雨中花，
意思要同窗外草。
归来乎，
常笑张子房，
崎岖愿封留。
何如大泽披羊裘，
忘机傲兀临溪流。
富贵不足回其头，
高风千载谁当俦？
归来乎，
故园之菊今应存，
此事欲与渊明论。
孤松独抚倦飞鸟，
出岫雅爱无心云。
明当秋风月在酉，
粳稌初黄催酿酒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_220','群公见和又答四首','刘鹗','元','归来乎，
古来圣人作春秋，
始尊王室严诸侯。
一辞初不待商偃，
岿然古道灵光殿。
纲维名教世所难，
初非凿空凌漶漫。
二百四十馀年间，
乱臣贼子俱汗颜。
归来乎，
后世多不然，
吾道秋叶枯。
纸扇一破难再糊，
种瓜冬实欺群儒，
魏王反诮齐无珠。
纷纷似此不忍道，
冠屦衣裳尽颠倒。
苏秦六国相金印，
园绮商岭饭芝草。
归来乎，
不可留。
山中木绵正堪裘，
乘槎鼓枻湘江流，
直欲下至沧海头。
白衣苍狗纷百变，
蛇神牛鬼宁堪俦？
归来乎，
将安归师之所存，
古今得丧奚须论。
有口不饮贪泉水，
有眼但看南山云。
尘埃风雨夘复酉，
千载虚名一杯酒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_221','群公见和又答四首','刘鹗','元','归来乎，
生不必八千秋，
爵不必万户侯。
饮河得如鼠之偃，
买花种作芙蓉殿。
世途荆棘进取难，
何况风雨长漫漫。
甘心局促笔砚间，
时于乐处寻孔颜。
归来乎，
山中乔木冬不枯，
山前春到花模糊。
胭脂梅绽酸于儒，
黄金橘熟圆如珠。
四时好景难具道，
有客叩门屣颠倒。
醉馀吟诗弄明月，
醉后从仙拾瑶草。
归来乎，
客勿去，
客少留。
尊空尚堪脱鹴裘，
但愿有酒如川流，
长使吏部眠瓮头。
山花野鸟自歌舞，
樵童牧竖相朋俦。
归来乎，
四海故人今几存，
心事落落谁相论？
迩来赖有揭阁老，
亦解为我歌浮云。
人生几何钟报酉，
行乐舒心聊寓酒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_222','群公见和又答四首','刘鹗','元','归来乎，
我生今踰四十秋，
始悔识字求封侯。
少年意气极骄偃，
谓当平步金变殿。
那知命舛百事难，
茧生两足沙漫漫。
有时或堕荆棘间，
努力自奋终强颜。
归来乎，
君不见功成一将万骨枯，
髑髅之血犹模糊。
弓藏鸟尽杀韩信，
几败公事骂竖儒。
笑挥珊瑚示侈靡，
岂意奴辈便吾珠？
诛夷封籍可胜道，
北风吹山山欲倒。
平泉木石又谁家，
金谷楼台半芳草。
归来乎，
故家猿鹤遮我留，
布袍暖胜貂鼠裘。
巾车乘兴寻绝壑，
展席随意临长流。
周旋世事但鲇头，
高节每慕晋宋俦。
归来乎，
及早归。
生涯虽薄今尚存，
尧舜不必吾侪论。
携书稳读牛背日，
领鹤閒种芝田云。
作劳暮归正当酉，
击缶呜呜呼斗酒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_223','天池鱼','刘鹗','元','君不见万岁山下天池中，
赪鲂赤鲤森蚁蜂。
荷阴柳影护深碧，
扬鬐鼓鬣何憧憧！
恩波浩荡得所托，
异日或可随云龙。
乘舆北狩未及远，
鱼已就戮遭群凶。
公然白日恣窃盗，
得钱聊复斗酒供。
圣恩自谓守禦固，
岂知守者元非忠？
群鲜无知固可负，
忍负主意将为容。
又不见苍生与鱼正相似，
托身天池尚如此。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_224','至正甲申岁，大饥，民多艰食，殍死者相望，盗贼扰扰。予亦缺食，未免作粥以延残喘，因赋食粥歌，以畅此怀','刘鹗','元','朝餐一顿粥，
暮餐一顿饭。
每当食粥时，
未免一长叹。
少年何事不相遭，
胡为晚岁方论交。
此时菜蕨各已尽，
以糟配尔为嘉殽。
既啖糟，
复食粥，
却意年当三十六。
笑携省檄上皇州，
曾以文章动流俗。
二程祠宇陋且卑，
我奋赤手更掣之。
至今穹碑照淮水，
碑成秩满游京师。
京师嬉游二十载，
铁石忍穷心有在。
声名欻起凤凰池，
风云已际鱼龙海。
当时结交多贵人，
往往尊我席上珍。
执经或在弟子列，
或遣弟子来相亲。
剧谈王道尊礼乐，
每激薄俗敦彝伦。
闾阎疾苦详敷陈，
亦或一慨眉为颦。
有时华筵湖山下，
争挽先生共陶写。
满堂座客尽豪贵，
亦知推让宗儒雅。
盈盈珍馐簇金盘，
衮衮葡萄浮玉斝。
金钗十二列两行，
班班初匪寻常者。
主人行杯极欢笑，
竞唱新词誇艳冶。
半酣相恼索题诗，
挥毫写向香罗帕。
尊前为我发新声，
自以风流望鄙野。
万钱日食固有限，
一笑千金绝无价。
放怀满饮鹦鹉杯，
何心复恋麒麟画？
鹧鸪舞罢月欲上，
半掩城门归并马。
等閒高会难具论，
酒酣掉臂金马门。
三三五五正少年，
乘兴共我歌浮云。
穷冬出使居庸北，
骏马稳步龙沙雪。
清霜在鬓冰在须，
指冻欲堕饥欲裂。
苦寒不透貂鼠裘，
青鼠煖帽方蒙头。
璚田玉界中著我，
自是奇士真壮游。
解鞍沽酒弹箜篌，
打手刺刺歌鸣讴。
丈夫有志在许国，
我自乐此忘羁愁。
连樯海运三百万，
署黔楮尾方成卷。
每忧谈笑误王事，
朝夕驱驰敢忘勌？
湖广文台正乏贤，
诸公为买江南船。
汉阳春树晴历历，
秦楼夜月明娟娟。
手提文印不半年，
首为鄂学归侵田。
蓬山有诏归朝天，
锦袍公子偕神仙。
宣文阁静万机暇，
时遣中官催进画。
饱聆天语近天光，
神揖天香更潇洒。
壮游既倦思还家，
堨来庾岭观梅花。
桑麻弦诵各得所，
玉堂召我天之涯。
平生所历犹在眼，
夜半思之皆梦幻。
盛时不敢忘贫贱，
自喜枯肠藜藿惯。
饱食粥，
无咨嗟，
尔糟尔粥甘如饴。
鸡鸣曳履东家谁，
芜蒌曾疗王孙饥。
粥兮粥兮敢尔却，
犹胜蕨餈滋味恶。
苟延残喘待秋成，
白发春风会如昨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_225','关武行','刘鹗','元','关西澒洞风尘起，
诸将陈兵耀威武。
愿言下教壮军心，
揽衣下马东门去。
盈盈野水抱城郭，
莽莽寒芜翳沙渚。
沙场筑台高十丈，
玉节光临有攸止。
微风不动碧油幢，
暗尘轻拂银交椅。
当轩下马一寓目，
云鸟鱼丽俱得所。
帐前骏马矫如龙，
帐下健儿猛如虎。
五方牙旂按五色，
戈戟如林分部伍。
台前独建大将旗，
云散天清日当午。
宝刀一挥牛首落，
血祭旌旄洒红雨。
命官奏喜得吉卜，
士卒喧呼发金鼓。
旷怀浩荡纳乾坤，
老气蓊郁生云雾。
祭馀分胙各有序，
旨酒盈樽肉登俎。
酒边好语相激昂，
世事艰危思共济。
同舟慎勿异秦越，
四海相看总兄弟。
愿无争气与争功，
要在相欢勿相妒。
上下心同铁石坚，
城池势若金汤固。
黄河如带山若砺，
当保初心与初誓。
我言剀切因流涕，
忠义推之人肺腑。
三军感激各再拜，
愿效驱驰报明主。
酒酣跽请献所长，
万马争驰置脱兔。
舞剑划若掣电惊，
扬旗欻见飞星度。
止齐不愆六七伐，
练习初非朝夕故。
花奴技痒争角逐，
干盾纷纷向人舞。
将军一笑挽强弓，
百步穿杨骇相顾。
固知蒙恬勇无敌，
尤信张良素多智。
成都底用说花卿，
安西不复歌都护。
曲江江头多壮士，
官陂小贼奚足数？
会当飞度虎头城，
为吊英雄死何苦！
生擒贼奴剖心血，
洒向忠臣坟上土。
功成扫归献天子，
竹帛勋名耀千古。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_226','通集贤全大学士','刘鹗','元','枯桑昨夜生沧溟，
风雨扰扰晦复晴。
功臣子孙半零落，
惟公独克承家声。
金莲坐拥晚出院，
儿童走卒俱知名。
天球河图不篆刻，
金钟玉镛殊铿鍧。
汪汪万顷那可测，
挠亦不浊澄不清。
古今事物贯胸次，
乾坤风月皆性情。
迩来有幸亦再睹，
使我鄙吝不复萌。
始知将相真有种，
往往山岳钟英灵。
自怜片影虽伶仃，
不愿恩叨一顾荣。
霏霏议论玉雪冰，
但愿容我时来听。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_227','勉学者','刘鹗','元','文学登名日，
青云发轫初。
慎毋轻作吏，
亦足取亨衢。
得意宜思效，
功成更读书。
异时横浦上，
烂烂夜明珠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_228','早发阳城，疾赴军垒，风雪失路，因记其苦二首','刘鹗','元','虚名不直死，
何事苦纷纷。
旷野惟空垒，
长途只断云。
日斜心更恐，
风急耳多闻。
未用轻衰飒，
狂歌一张军。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_229','早发阳城，疾赴军垒，风雪失路，因记其苦二首','刘鹗','元','生死不须念，
羸骖当疾驱。
悔来无及事，
到此欲何如？
有友堪同命，
无人可寄书。
忽看毡帐近，
魂魄暂时苏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_230','次韵','刘鹗','元','有客惭毛遂，
何人荐马周？
霜枮铜雀砚，
风冷木绵裘。
徐孺无悬榻，
元龙不筑楼。
好将閒岁月，
乘兴觅糟丘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_231','为武宽则赋湖山','刘鹗','元','结屋红尘外，
何人可得群？
高情洞庭水，
逸兴九疑云。
渔唱江花晚，
樵归野兴曛。
是中最佳处，
凉月夜纷纷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_232','送诗僧泽天全归天竺','刘鹗','元','渊深知有本，
纯一更无机。
偶共浮云出，
还同明月归。
草生频入梦，
花落不沾衣。
天竺山前路，
苍苔雨欲微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_233','京师会维扬旧友次韵以谢','刘鹗','元','宵残明月老，
不复少年心。
最惜平山柳，
今无一树阴。
雷塘春水满，
海鹤暮云深。
无限伤心事，
因君发浩吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_234','乡人杨用甫成家于彼，载酒相劝，因书','刘鹗','元','乡语耳边熟，
闻之喜入神。
谁知穷域外？
亦有故乡人。
儿女皆椎髻，
乡闾自睦姻。
一樽邀共酌，
尚觉此情真。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_235','清远峡','刘鹗','元','峡束山如斗，
江湾路渐回。
可怜人化外，
谩说寺飞来。
殿圮风鸣树，
廊虚雨湿苔。
汉苏那可作？
忍听暮猿哀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_236','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','村迥疑无路，
堤平不复桥。
暖风开芍药，
细雨落凌霄。
自得幽居趣，
何烦隐者招？
小车来往熟，
乘兴不知遥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_237','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','渐与红尘远，
应便野兴清。
绿杨閒放鹤，
芳草坐闻莺。
园果随时摘，
畦蔬取意羹。
青山时徙倚，
如在画图行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_238','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','田许群童种，
粮堪一岁支。
鸡豚同里社，
鹅鸭自陂池。
已分身终隐，
何忧世莫知？
急流中早退，
宁遣叹纷披？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_239','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','接屋青青柳，
当轩灼灼花。
矮屏开锦绣，
乔木舞龙蛇。
深涧云堪煮，
清宵月可赊。
一时幽兴极，
步屧过邻家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_240','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','书帙携孙读，
尊罍待客开。
閒心云外鹤，
高兴雪边梅。
野老时相看，
沙鸥亦复来。
绝怜老松柏，
清影荫莓苔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_241','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','穿树通山色，
浇畦汲井泉。
鱼肥堪脍炙，
蚕熟得丝绵。
怪石粘枯藓，
圆荷贴小钱。
便令金北斗，
宁换此山川？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_242','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','自从辞禁闼，
不复梦含香。
地僻尘机息，
心清六月凉。
烟霞供笑傲，
琴鹤共行藏。
所喜身长健，
从教鬓发苍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_243','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','百年半风雨，
五世此台池。
阴满蒲萄架，
春浮木槿篱。
持家还有妇，
继志岂无儿？
身外忧何事？
惟教酒榼随。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_244','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','对客歌金缕，
家儿爱庆云。
茂陵须病渴，
太守尚能文。
云映山光近，
烟开柳色分。
无边閒富贵，
馀子苦纷纷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_245','高荣禄筑南城别墅，苍松老柏，异花时果，蔚然成林。公与夫人乘小车，携二孙，来往其间。徵余赋，遂次杜公何将军山林十首云','刘鹗','元','宦海久无迹，
风霜将奈何！
起看天尺五，
敢谓地无多。
往事谁能忆？
高情自可歌。
年年当此日，
载酒一相过。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_246','龙虎台肃驾','刘鹗','元','俯仰城空是，
凄凉事已非。
虚传天仗至，
不见祖龙归。
地迥风霜惨，
云深日月微。
高堂一惆怅，
弱泪不胜挥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_247','十月十四日，崇天门听诏，有喜二首','刘鹗','元','听罢龙飞诏，
扬休万口俱。
公忠赖伊霍，
揖让见唐虞。
礼乐开平治，
衣冠协赞谟。
祖宗遗泽在，
千载巩皇图。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_248','十月十四日，崇天门听诏，有喜二首','刘鹗','元','义理推明易，
君臣庆会难。
乾坤归历数，
社稷重丘山。
天意舒晴霁，
人心溢喜欢。
客愁浑为解，
驴背永歌还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_249','哭饶上溪','刘鹗','元','霜蹄惊再蹶，
绿鬓忽华颠。
国子诸生集，
膏肓二竖缠。
死生人有命，
京洛客无毡。
归骨知何日？
思君苦泪悬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_250','致和参议吴彦洪，天历龙飞，以罪贬。既行，薄俗欲求君夫人孔氏为室家，孔闻之即自刎，流血被面，誓死不辱，或闻而止。越四年，诏雪君罪，且徵南还，遂与夫人相见如初。呜呼！视彼一易节，不见答于良人者，槩可感矣','刘鹗','元','夫妇天伦重，
翻云世变深。
秋霜持素节，
颈血见丹心。
岭外梅花瘦，
闺中月影沈。
归来情更苦，
喜极重沾襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_251','秋晚溪上','刘鹗','元','忽忽年华度，
茫茫野水流。
西风杨柳雨，
残照菊花秋。
万事蕉中鹿，
浮云海上鸥。
功名遂意好，
何处有扁舟？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_252','月夜思家','刘鹗','元','清夜思家立，
中庭片月流。
惟忧故园菊，
还似昔年秋。
为口长怜雁，
知机独愧鸥。
明年二三月，
烟水五湖舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_253','送孔与之赴乐安尉二首','刘鹗','元','祖帐东门道，
青山得意归。
山城花泛泛，
客路柳依依。
地僻经过少，
世平警逻稀。
有诗频寄远，
云忆别时飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_254','送孔与之赴乐安尉二首','刘鹗','元','行旅清晨发，
柴扉过夜扃。
桑麻随地绿，
苍藓上阶青。
威武存三略，
词华本六经。
圣门家法在，
随意忆过庭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_255','过高氏十里庄','刘鹗','元','乘风高柳下，
扪虱老松林。
浊酒陶真趣，
清泉洗此心。
晚花偏有态，
落日故多阴。
揭厉宜深浅，
行藏自酌斟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_256','宿阳城 时腊月九日，辱和尚司乡访，还因赋','刘鹗','元','但知为久住，
何用即能归？
客子亦良苦，
官曹如此稀。
繁霜吹老鬓，
斜日照征衣。
岁晚乡心切，
长途恨不飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_257','题宁戚叩角图','刘鹗','元','月色夜轇轕，
开门溪水明。
天机閒始得，
诗思静还生。
柳影临流活，
钟声傍夜清。
频醒尘土梦，
飞步欲登瀛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_258','居庸关','刘鹗','元','形势自雄壮，
古来番汉分。
千年有今日，
四海喜同云。
木落楼台出，
山深鸡犬闻。
危阑閒立马，
壮气扫千军。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_259','倪行简由伴读除江陵教授，谭玄之集贤掾除南雄经历。命既下，二公皆死于道，闻之有感','刘鹗','元','南风久不竞，
天岂薄斯文？
宦辙方云远，
哀音遽忍闻。
秋空残叶露，
夜月断鸿云。
苦泪无从洒，
题诗独吊君。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_260','哭友兄陈养志二首','刘鹗','元','用世有远志，
读书多苦心。
花残偏值雨，
云薄不成霖。
翰墨风流尽，
兴亡感慨深。
池边老松树，
无复共长吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_261','哭友兄陈养志二首','刘鹗','元','讲习常同席，
间关共出山。
青霄鹤背稳，
白昼锦衣还。
雕鹗思腾汉，
芝兰竟化菅。
知君有遗恨，
重我泪潸潸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_262','夜坐有感四首','刘鹗','元','稍稍月当户，
萧萧风满林。
夜寒香梦远，
霜重漏声沈。
孝子终身泪，
忠臣到死心。
承平春似海，
岂料有如今？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_263','夜坐有感四首','刘鹗','元','祸福当求已，
行藏欲问天。
干戈今更盛，
涂炭愈堪怜。
痛恨储胥缺，
何由郡国圆？
恨无双羽翼，
飞诉至尊前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_264','夜坐有感四首','刘鹗','元','礼乐将兴日，
干戈独盛时。
圣躬无失德，
天道苦难知。
嗟尔民何负，
甘心贼忍为？
不平徒怏怏，
推枕起裁诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_265','夜坐有感四首','刘鹗','元','大厦将倾日，
徒劳一木擎。
揆时难与祸，
避位敢忘君？
无术能平寇，
持威谩张军。
中宵时念此，
老气欲干云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_266','报获寇首','刘鹗','元','方建优升议，
旋收斩馘功。
老夫殊矍铄，
诸将尽英雄。
麾下人如虎，
行间马似龙。
渠魁今就戮，
邻寇势应穷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_267','题王棣诗卷后','刘鹗','元','白鹭从师日，
高凉发轫时。
正当供子职，
勿负故人期。
志在青云远，
心清白日迟。
少年宜努力，
勉汝强题诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_268','十二月，桃花盛开，有感赋之','刘鹗','元','梅花犹在树，
桃蕊已盈枝。
岭外惊春早，
江南得暖迟。
好风吹锦绣，
细雨湿胭脂。
前度刘郎老，
无心为赋诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_269','寄雄州监郡','刘鹗','元','既往那容咎，
方来尚可追。
好将功折过，
直以勇忘私。
董卓诚堪鄙，
张巡岂是痴？
凭君当静夜，
仰屋试深思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_270','寄雄州太守谭元凯','刘鹗','元','幸际风云会，
青云纵靶初。
山川融间气，
父子并司徒。
勋业千年在，
金珠过眼虚。
期君师卜式，
庶可遂良图。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_271','题王志亮元帅草庵','刘鹗','元','中原方致力，
那复以家为？
结草聊为屋，
编花谩作篱。
招降多善策，
横槊有新诗。
文武才全备，
王孙自一奇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_272','曾惟吉所藏杨宗瑞赠其师张仲儒卷','刘鹗','元','诸老风流尽，
遗经孰与论？
携持文墨在，
隐约父师存。
世远情何极，
人亡道愈尊。
感君多古意，
珍重付诸孙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_273','仲宜以所植菊花见贻，以诗答之','刘鹗','元','新移初种菊，
送与老夫看。
粲粲黄金盏，
煇煇白玉盘。
虽迟偏有趣，
欲罢更凭阑。
乌府多松柏，
相期共岁寒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_274','经居庸北','刘鹗','元','峡束石如斗，
山回路渐高。
涧寒流水死，
衣冷北风鏖。
败屋兵戈惨，
危途客旅劳。
晤人多出塞，
恨杀紫花袍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_275','题宗性性庵','刘鹗','元','至理俱明彻，
澄澄海不波。
尚须妨蔽诱，
直欲致中和。
水面风光好，
天心月色多。
是庵清兴足，
随意得婆娑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_276','送胡宗性归武宁二首','刘鹗','元','江湖多薄恶，
兵甲更纵横。
失意青云远，
思亲白发生。
畏途宜得友，
随寓莫兼程。
堂上思君切，
持身勿自轻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_277','送胡宗性归武宁二首','刘鹗','元','文章追古作，
挥洒与时新。
可惜当衰运，
何由识伟人？
心坚无远道，
孝感有神明。
华屋斑衣酒，
悬知笑语生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_278','挽刘原耕并刘母黄氏宜人','刘鹗','元','我母忝同姓，
为儿犹弟兄。
亲方悲夭折，
母独喜恩荣。
紫诰金花烂，
斑衣鹤发明。
暮年三釜养，
重我泪如倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_279','元日','刘鹗','元','天门荡荡开黄道，
丹陛雍雍肃晓班。
御气拥云蟠凤阙，
春风随酒上龙颜。
君臣庆会赓歌际，
礼乐升平揖让间。
四海朝元无一事，
华封但祝寿如山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_280','晓起','刘鹗','元','休官彭泽真忘世，
捧檄庐江喜为亲。
荐福自缘渠薄命，
筑台敢谓世无人？
但明一艺俱登仕，
独拥群书不疗贫。
竽瑟相违每如此，
且须珍重百年身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_281','铁马','刘鹗','元','伊谁巧铸渥洼姿，
檐外鏦铮一线羁。
带甲有声如击刺，
凭鞍无力任驱驰。
湘妃环佩天风急，
蜀道霖铃夜雨悲。
漫尔哀鸣求一顾，
奈何钝质本无奇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_282','盆池','刘鹗','元','池中地窄一泓多，
满注流泉复几何？
皓月初圆先得影，
微风虽动了无波。
可容赪鲤十数辈，
仅种圆荷三两窠。
兀坐小窗炯相对，
眼明时见白云过。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_283','苦雨独坐有感','刘鹗','元','白黑贤愚混是非，
诙谐调笑足投机。
平原具眼犹轻遂，
延赏何人解识韦？
红杏碧桃应懒种，
孤云野鹤自高飞。
世间处处鱼羹饭，
好及秋凉早赋归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_284','彭泽','刘鹗','元','江汉朝宗第一门，
擎天老树碧璘珣。
乾坤设此宁无意？
鬼物因之遂有神。
一曲湖山知几劫？
千年风致属何人？
渊明老矣遗祠在，
他日归来愿卜邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_285','白雁','刘鹗','元','稻粱寒暑老营营，
赢得秋霜满背明。
夜月芦花空有影，
江天雪暮但闻声。
鲜鲜固与常禽异，
皦皦尤为俗眼惊。
珍重素衣须自爱，
缁尘近日满江城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_286','双陆','刘鹗','元','摴蒱小戏只消忧，
但恨无人为点筹。
几个疏星榆塞晓，
半弯残月雁门秋。
六军先满俱成列，
单马如飞肯少留？
迟疾知几应甚速，
不知何日取封侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_287','射虎','刘鹗','元','弓强矢劲马初肥，
猎得南山白额归。
势力顿穷甘就戮，
爪牙虽具果何为？
深山百兽应无恐，
绝壑幽狐莫假威。
笑取髑髅横作枕，
壮哉殊足快当时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_288','梅信','刘鹗','元','破雪争春喜夺魁，
好音到我亦悠哉！
孤山久渴诗人想，
庾岭初逢驿使来。
风细暗传香迤逦，
月明难觅影徘徊。
来朝著意勤寻问，
只在前村野水隈。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_289','闻新事','刘鹗','元','平原草木几无主，
金谷楼台半是尘。
已信齐桓能辅国，
焉知陈胜足亡秦？
国家自昔明刑宪，
天地由来有鬼神。
太息渠侬终不悟，
翛然吾自爱吾贫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_290','雪作，萧同可有诗，次韵','刘鹗','元','风高海水化为石，
天迥野云俱是冰。
访戴何人复乘兴？
平吴当日孰先登？
清和月影明无奈，
寒入梅花瘦不胜。
大地无尘车马寂，
晓来胸次尚澄澄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_291','大明殿观元旦朝仪','刘鹗','元','云开日上黄金殿，
地迥风鸣碧玉珂。
虎豹关临仪仗肃，
鱼龙海护俊良多。
霓裳按曲身轻举，
天乐逢春律自和。
鹓鹭陪班臣子事，
观时且赋太平歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_292','雨后','刘鹗','元','雨馀新水钓鱼船，
残日西风树树蝉。
间忆平生如昨日，
不知急景已中年。
姓名未辱当时识，
德业犹堪异代传。
拔剑悲歌频起舞，
茫然欲绝伯牙弦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_293','中秋','刘鹗','元','又此中秋百恨生，
频年骨肉尚飘零。
独援北斗酌明月，
閒看银河感客星。
极目关河归白昼，
满怀风露立青冥。
眼前咫尺清虚府，
未许乘鸾叩玉扃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_294','广寒殿，在万岁山上。山在水中，高数十丈。怪石古木，蔚然如天成。殿在山两傍，稍下，复建两亭，正当山半。又有殿萦然竹石间，山下积石为门。门前有桥，桥有石阑如玉。前有石台，上建圆殿，缭以黑粉墙，如太湖石状。台东西皆板桥，桥东接皇城，西接兴圣宫。水光云影，恍惚天上','刘鹗','元','万岁之山天半青，
广寒宫殿倚空晴。
云生桧柏岩峦暝，
日射蒲荷海水明。
白玉阑深仙仗隐，
绿杨桥锁小舟横。
人间天上神飞越，
恍惚霓裳第一声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_295','广寒殿，在万岁山上。山在水中，高数十丈。怪石古木，蔚然如天成。殿在山两傍，稍下，复建两亭，正当山半。又有殿萦然竹石间，山下积石为门。门前有桥，桥有石阑如玉。前有石台，上建圆殿，缭以黑粉墙，如太湖石状。台东西皆板桥，桥东接皇城，西接兴圣宫。水光云影，恍惚天上','刘鹗','元','怪石疏林远艮岑，
经营已近百年今。
楼台白日神仙集，
雨露青春草木深。
游豫无忘前圣度，
登临还忆上皇心。
广推此乐同天下，
四海讴歌岁旱霖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_296','次韵家西隐叔见寄','刘鹗','元','前人硕德集隆禧，
二百馀年运未衰。
薄劣何堪文学掾？
登庸幸际圣明时。
蹇驴破帽随缘好，
淡饭黄齑到处宜。
三读来诗殊有感，
贻名善恶敢忘思？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_297','来诗','刘鹗','元','毡寒绂冷宋天禧，
十世中间几盛衰？
青紫每由稽古力，
公侯端有复初时。
不能拔俗惭痴叔，
足以光前赖阿宜。
见说除书新入手，
锦还何日慰吾思？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_298','孙锡种盆菊，列为河图','刘鹗','元','菊布河图眼自宽，
缁衣如海不相干。
幽姿过雨秋逾好，
清意冰人夏亦寒。
晚节独宜高自重，
落英虽美竟谁餐？
春风桃李非知己，
珍重瑶琴勿浪弹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_299','九月三日，龙虎台接驾，晚宿新店','刘鹗','元','关南九月草凄凄，
又见征人扈跸归。
日落毡车团野宿，
天寒塞马觅群嘶。
徬徨恋阙孤忠在，
俯仰随人百计非。
犹幸诸公同笑语，
归来茅店谩鸡栖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_300','九日，次韵','刘鹗','元','京华四载倦为客，
乐事良辰岂得兼？
官况甚于纱帽薄，
酒怀聊为菊花添。
文章无用甘牢落，
刀笔随宜谩伏潜。
忽得新诗破孤闷，
为君一笑起巡檐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_301','九日，以公事随官曹之西山新寺，与宋良卿遍游诸寺','刘鹗','元','京城西北地多幽，
依约江南九月秋。
湖岸草枯霜欲下，
野田水落稻初收。
乡心无奈还随雁，
机事相缠独愧鸥。
犹喜簿书今颇静，
追随官长赋清游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_302','西山即事','刘鹗','元','鳌头突兀黄金殿，
水面空明翡翠楼。
锦绣山河天有待，
帝王宫苑地长留。
烟迷柳影三山晓，
月浸荷花十里秋。
更一登临多胜槩，
五云南上即神州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_303','玉泉山二首','刘鹗','元','杨柳芙蕖接断岑，
流泉如玉本源深。
四时潋滟无晴暖，
一派清泠有古今。
石井分甘供御膳，
湖波流润洗尘心。
我来正值秋将晚，
独坐长吟雪满襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_304','玉泉山二首','刘鹗','元','孤塔苍崖结搆牢，
岿然俯视世滔滔。
烟云连野心同远，
楼阁依山步渐高。
性本虚明宜自得，
无经悟入亦徒劳。
可怜有客勤三礼，
不见灵光现玉毫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_305','寿安山','刘鹗','元','汉皇遗寺在人间，
长使忠臣带泪看。
六曲楼台殊壮丽，
九天风露愈高寒。
乘舆血污黄金辇，
圆殿苔生碧玉阑。
利益福田真浪语，
当年共想寿而安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_306','香山永安寺二首','刘鹗','元','幽岩绝壑倚云齐，
杰阁危楼望眼迷。
山势浑雄龙虎踞，
树阴深蔚鸟乌啼。
碑存金志犹堪读，
寺始唐家竟莫稽。
此日清游天所借，
明朝驴背听晨鸡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_307','香山永安寺二首','刘鹗','元','长廊徙倚惬幽期，
衮衮黄尘暂息机。
山鹿背人衔木实，
石泉经砌泻花池。
九天风露围青琐，
三峡烟霞绕翠微。
但恨山僧多俗客，
饱看清致更无诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_308','次友人韵','刘鹗','元','饮罢骑驴出凤城，
拜郊台下赏新晴。
一春苦雪花多死，
十日南风草尽生。
高冢累累牵远恨，
流觞落落负幽情。
归来却忆家山好，
红绿参差坐听莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_309','次舍侄尊谦韵三首','刘鹗','元','灯吐幽花岂我欺，
客来惊见墨离离。
平安有字诚堪喜，
漂泊无家不自知。
此日禁花和露看，
何时野鹤与云随？
每怀竹下相从乐，
煮茗谈诗事事宜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_310','次舍侄尊谦韵三首','刘鹗','元','仕路莫踰科举捷，
生涯赖有父书存。
极知世事宜酬应，
但得工夫更讨论。
一旦风云滋笔力，
九天雨露沛君恩。
归来了却为儿愿，
碑刻封题记某坟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_311','次舍侄尊谦韵三首','刘鹗','元','离别经年岂不思，
山林钟鼎苦何宜？
喜闻门户能如昔，
敢意田园近稍滋。
浮世于人多薄恶，
同心为汝好扶持。
蕃生书子犹烦教，
他日成家未可知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_312','次舍弟此心韵','刘鹗','元','猎猎尘沙吹晓风，
无端马滑更霜浓。
可怜鬓雪千茎白，
才睹宫云一朵红。
平昔亢宗徒有志，
此行报国似无功。
弟兄何限相思意，
回首长安落日中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_313','题南雄府壁二律','刘鹗','元','榕阴满地草齐腰，
官舍如僧更寂寥。
隙地风凉人牧马，
长廊吏散昼鸣枭。
寸心谩切公家务，
两耳惟听使客轺。
可是逢迎少蹉跌？
谤声载道骨形销。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_314','题南雄府壁二律','刘鹗','元','少年馆阁恣游嬉，
老去何期堕有司？
酬应敢云千虑失，
奔驰知忍几回饥？
据鞍尚觉精神壮，
度岭方怜气力衰。
何日归来茅屋里？
夜凉閒听玉参差。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_315','挽刘原耕并刘母黄氏宜人','刘鹗','元','令子携书赋宦游，
胸中初不著离忧。
懒看䌽服争春色，
喜见梅花寄陇头。
高冢松楸残照雨，
平原禾黍旧时秋。
贮书淑子无遗憾，
细读丰碑识故侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_316','洪都人李仲俊至','刘鹗','元','避人避世愁无奈，
全节全身计未差。
始信盛衰元有数，
敢期漂泊老无家。
鳣鲸失势滋蝼蚁，
鸾凤韬光噪晚鸦。
未必苍天终困我，
春风骨肉故园花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_317','题许氏兰秀轩','刘鹗','元','净几明窗春迭荡，
湘花剑叶影扶疏。
易当妙处花前读，
诗到工时叶上书。
旧雨栽培还若此，
只今离乱定何如？
独怜诸老留题在，
恍惚幽芳梦故居。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_318','偶题二首','刘鹗','元','阶前榕叶乱如雨，
窗外老鸦啼向人。
垂老观书偏损目，
殊乡哭友倍伤神。
古今生死真常事，
家国安危系此身。
岭海愿言将息好，
天根月窟有馀春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_319','偶题二首','刘鹗','元','峤南何似八九月，
暑气著人如火烧。
近午炎光几夺目，
此时厉气正生苗。
但教节饮神应旺，
尚觉宽心脉自调。
但得太平开岭海，
归寻旧隐老渔樵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_320','九日','刘鹗','元','痛恨长安信息乖，
江南江北半云霾。
极知随处有白酒，
争奈忧时无好怀。
淡淡黄花谁作主？
萧萧红叶自空阶。
乱离不敢登高处，
忍见苍生万仞崖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_321','芙蓉庵山亭，始于汉隐老康容所居。后葛仙翁炼丹于此，灶尚存，旁有石煤如豆','刘鹗','元','一庵高寄碧崔嵬，
山崦芙蓉锦作堆。
满眼烽烟天地老，
隔江楼观画图开。
云房犹是康容宅，
丹灶空馀晋代煤。
岂为登临行乐计？
要从高处望蓬莱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_322','题寄曹溪禅寺并东南山长老三首','刘鹗','元','亲承祖意振宗风，
一派曹溪万折东。
傍石作亭怜卧虎，
临泉持钵度降龙。
天开图画平山勇，
人仰菩提四海同。
劫火弥天仍独在，
吾师信是佛中雄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_323','题寄曹溪禅寺并东南山长老三首','刘鹗','元','诏持玉节遍咨询，
岭海重来白发新。
济世不存菩萨行，
当年徒见宰官身。
痛怜世外何多劫，
远想山中别有春。
寄语堂头大和尚，
何当握手话前因？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_324','题寄曹溪禅寺并东南山长老三首','刘鹗','元','万刹飞灰海变田，
是中孤塔尚岿然。
此山可谓有盛福，
当世宜称第一禅。
直指人心怀达摩，
洗空尘虑忆坡仙。
少须了却澄清志，
拂袖从师学引年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_325','闻瑞州太守、东广宪副宣命俱至，喜而赋之','刘鹗','元','筠台玺檄珠犹湿，
东广除书墨又新。
草莽何堪蒙圣眷？
菲葑犹下念孤臣。
茫茫关塞连烽火，
莽莽乾坤溷劫尘。
岭海微臣无补报，
提携风纪保斯民。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_326','暇日有怀士彦四首','刘鹗','元','诚心公道宜开布，
愚妇愚夫更有知。
遇事当从彝理听，
操心应比孽臣危。
海翁易虑鸥飞去，
卢老忘机虎卧随。
共说此君曾学道，
是中滋味愿深思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_327','暇日有怀士彦四首','刘鹗','元','提携宝剑斩长蛟，
独运神机不惮劳。
快睹中天悬日月，
徐看沧海息波涛。
剧谈英武今谁敌？
若论猷为昔更高。
老我惟当相羽翼，
太平和气要薰陶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_328','暇日有怀士彦四首','刘鹗','元','沟壑崎岖徒自苦，
每寻正学究天人。
狼贪虎暴从渠斗，
月窟天根自有春。
平昔操修惟至善，
此来受用是清贫。
是非黑白吾宁辨？
愿振台纲洗瘴尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_329','暇日有怀士彦四首','刘鹗','元','老病君王不见疏，
鞠躬尽瘁意何如？
清晨上马了公事，
静夜张灯课子书。
气直干霄山岳动，
精诚贯日鬼神徂。
请看南海韩夫子，
援笔为文徙鳄鱼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_330','次颜子中都事韵','刘鹗','元','犹当相与守危关，
自古忠臣铁作肝。
非敢偷生忘故友，
且须忍死报平安。
干戈荏苒情何极？
礼乐隆平运未残。
揽辔澄清当努力，
诚心北望思漫漫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_331','次韵','刘鹗','元','将军号令凛寒冰，
鸡犬村村夜不惊。
弓劲始知双臂健，
贼多翻觉此身轻。
兵戈劫运临关尽，
烽火妖氛到海清。
笑取虎符归故里，
兹行殊不负平生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_332','岁晚书怀','刘鹗','元','一官岁晚尚驱驰，
骨肉遥应怨别离。
衰世功名何足贵？
暮年风节正须持。
凌人劫运今还盛，
报国忠心老未衰。
奏凯还家归路好，
䌽幡春胜簇前旗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_333','除日试笔','刘鹗','元','桃红酣雨更精神，
久客俄惊节序新。
好是一年将尽夜，
喜看万物又回春。
元正纪朔还逢甲，
谷日祈丰复得辛。
泰运昭回消劫运，
峤南同作太平民。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_334','元日试笔','刘鹗','元','曾随仙仗立仙班，
误逐红尘落世间。
遥向孤城瞻凤阙，
定须清梦绕龙颜。
乾坤劫运随云散，
岭海春光带雨还。
三祝圣躬千万寿，
老臣长与护梅关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_335','寄士彦监宪','刘鹗','元','半载韶雄厌滞留，
雨添新水送行舟。
何因不动南来兴？
所愿聊分北顾忧。
贾谊感时书溅泪，
孔明经国笔为筹。
使君倘采强边策，
春满关南十五州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_336','元宵，奉邀使客张鹏飞照磨过官署小酌','刘鹗','元','北走南奔今日苦，
东涂西抺少年曾。
何妨过此共明月，
勿谓乱来无好灯。
天上鳌山空入梦，
城中竹叶谩为棚。
九城风景虽寥落，
颇觉承平气象增。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_337','夜阑，再用前韵','刘鹗','元','夜半尚闻箫鼓响，
开门领客兴来曾。
历千万劫有今日，
近四三年无此灯。
儿女竞歌桃叶渡，
风光翻盛木香棚。
承平愿与民同乐，
老遇艰危气益增。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_338','明日，鹏飞照磨赐和，再用前韵二首','刘鹗','元','自怜老去情怀别，
笑拾花钿不复曾。
良夜好天千载意，
光风霁月四时灯。
暂辞江表烟尘海，
偶上人间傀儡棚。
一片忠君心似血，
鬓边白发迩来增。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_339','明日，鹏飞照磨赐和，再用前韵二首','刘鹗','元','讨贼七年殊费力，
致多如此旧何曾！
幸无惊犬去吠月，
赢得閒钱来买灯。
正好从容花海会，
莫教零落翠云棚。
儿童笑指游人醉，
共说新来酒价增。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_340','偶成二首','刘鹗','元','中庆堂前日欲西，
干戈未息思依依。
但知为国事经济，
纵使傍人说是非。
众口难调无善会，
入心如面有危机。
揆予俯仰无惭怍，
山鬼通神自向微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_341','偶成二首','刘鹗','元','寸心长共白云驰，
时绕苍龙阙角飞。
群盗纷争何日了？
中原北望几时归？
天心劫运应难测，
世故人情愈觉非。
坎止流行随所遇，
商颜芝草及春肥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_342','寄义士吴元良','刘鹗','元','几年四野龙蛇斗，
嗟子勤王独至今。
曾为忧民添白发，
屡从杀贼见丹心。
当思臣节如山重，
更忆君恩似海深。
善恶贻名宜慎择，
倚楼西望为长吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_343','曾惟吉乃祖岩山先生三告身','刘鹗','元','起家在宋当淳祐，
文武兼资早致身。
翠竹苍梧家学远，
回鸾翥凤诰词频。
桑田沧海人何在？
锦轴牙签墨尚新。
睹物使人双泪堕，
痛怜封诰总成尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_344','奉别瑞甫高掾郎还南台','刘鹗','元','市舶亭前新水长，
楼前欲发奈情何！
莫愁柏府同天远，
所喜南风五月多。
劲气横空秋迭荡，
清标映日玉嵯峨。
矧君素节廉如水，
未必黄庭肯换鹅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_345','分司北道留别监宪五首','刘鹗','元','玉节光浮士气和，
不须更问夜如何？
湟中愿学赵充国，
徼外当如马伏波。
要使蛮夷归礼乐，
伫看岭海罢干戈。
不烦主将多忧顾，
笳鼓归来杂凯歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_346','分司北道留别监宪五首','刘鹗','元','巨镇名藩压海滨，
岂期四海涨烟尘？
丹心激烈宁辞老？
玉斧驱驰不为贫。
此际出师宜有表，
向来馈饷岂无人？
勿容耿邓专前美，
好遣皇家识汉臣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_347','分司北道留别监宪五首','刘鹗','元','志未能酬贼未除，
衰年岂敢恋安车？
愿言息壤坚盟誓，
从使中山有读书。
寂寞宛如天宝后，
升平无复至元初。
会当勒石凌烟阁，
返我承明旧所庐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_348','分司北道留别监宪五首','刘鹗','元','玉节提兵昔见之，
风流儒雅是吾师。
据鞍矍铄诚堪画，
横槊从容谩赋诗。
破贼要如驱海鳄，
忧民那得避仙蜞？
强兵富国当留意，
乘兴长驱庶可期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_349','分司北道留别监宪五首','刘鹗','元','群盗纷纷苦未休，
檄书催我上韶州。
已看肥羜供新馔，
更泛清尊慰别愁。
天眷老臣恩至渥，
君于老友礼殊优。
他无补报惟忠义，
明日驱车不复留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_350','谩书','刘鹗','元','麾下更无兵可调，
城中又乏米堪忧。
孰为报国忠君计？
姑作求田问舍谋。
兔只守株宁可待？
鱼从缘木岂能求？
老夫束手愁无奈，
白尽平生未白头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_351','寄蒙君礼元帅','刘鹗','元','俄惊飞鸟度辕门，
杀气平将贼砦吞。
社稷人民俱政要，
豺狼蛇虎总消魂。
军心一若背水阵，
粮饷多于五丈原。
俘馘凯还应有日，
奇勋泚笔为君论。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_352','水仙花二首','刘鹗','元','水府群仙别一家，
清标为洗世铅华。
霜根种种八九月，
独干亭亭四五花。
素质自堪齐玉雪，
冰肌那肯混烟霞？
他时明月瑶台下，
一笑相逢更绝佳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_353','水仙花二首','刘鹗','元','凌波仙子太轻盈，
钟得扶舆气质清。
太史谬称矾是弟，
花神应许我为兄。
翠葩不逐春风转，
玉骨惟随夜月明。
置向席间看不厌，
哦诗同订岁寒盟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_354','栽松','刘鹗','元','分司无事日徘徊，
移得新松手自栽。
直干行看龙天矫，
清阴留待鹤归来。
冰霜此日存高节，
廊庙他年获大材。
寄语樵夫休剪伐，
要看百尺接天台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_355','岁除，水仙、梅、菊盛开，与鹏飞照磨饮于花间，赋之','刘鹗','元','转眼惊看节序新，
水仙梅菊喜相亲。
时穷幸有花堪友，
道在尤多客可人。
清意纷纷凉似水，
孤标郁郁更无尘。
明朝又道春来到，
岁晏谁云此老贫？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_356','元旦，即事，录似鹏飞照磨','刘鹗','元','旭日微云淡淡晴，
早朝鸦鹊寂无声。
龙楼凤阁浑如梦，
水国山城谩有情。
浩劫固知今止极，
衰年幸再睹承平。
功成不作从山计，
拟学长沮事耦耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_357','元日，宴集中庆堂。客散后，留鹏飞再酌，用前韵','刘鹗','元','宴罢惊看晓日晴，
共传街市有欢声。
故乡休问今奚似？
薄酒何妨更尽情。
遣兴赋诗那用好？
感时抚事苦难平。
尘清共作江南计，
旋买荒田趁早耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_358','新春记实二首','刘鹗','元','新春和气颇薰蒸，
共说今年可太平。
满眼干戈谁击贼？
绕街箫鼓强题灯。
常悲尘世阴晴半，
须信人生苦乐并。
老去不为儿女态，
引杯看剑起呼鹰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_359','新春记实二首','刘鹗','元','忧国烦心苦郁蒸，
眼中万事况难平。
开怀且共新丰酒，
乱眼犹疑太乙灯。
岁晏孤踪犹岭海，
夜阑清梦刷幽并。
柳林记得朝元罢，
曾侍銮舆学臂鹰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_360','复元日韵','刘鹗','元','东风巧放立春晴，
喜听讴歌变颂声。
浩劫逼人还有极，
老天于世岂无情？
云收雨罢山犹在，
日丽风和浪自平。
寄语群凶早回首，
卖刀买犊好归耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_361','试灯小酌，用前韵','刘鹗','元','山泽春回气尚蒸，
黑山四合与云平。
清高庭馆萧萧雨，
牢落杯盘草草灯。
竞利争名人易老，
赏心乐事世难并。
老来尚被微官缚，
何日能如脱臂鹰？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_362','除夕韵','刘鹗','元','每忆盘铭日日新，
读书灯火老犹亲。
姓名虽或闻当世，
德业还应愧古人。
百岁光阴嗟白发，
十年踪迹困红尘。
太平倘与春俱会，
一笑浑忘病是贫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_363','送谢仲宜归五羊','刘鹗','元','酒尽沙头意惘然，
君今归理曲江船。
曾同忧患难为别，
欲取功名莫计年。
世乱人心机似箭，
雨馀山路瘴如烟。
诸君倘问余何似？
一片丹心可对天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_364','寄友，为红巾破九江府','刘鹗','元','早岁同游凤阙前，
于今鬓发各萧然。
御街杨柳春风马，
海子芙蓉夜月船。
满望功名图晚岁，
岂期衰朽度残年？
九江二水难回首，
报国忠君各勉旃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_365','寄乡人袁观所','刘鹗','元','瑟瑟秋风吹客衣，
夜凉如水曷胜悲？
早知多难有今日，
何得长贫似昔时？
华屋凄凉芳草合，
黄金散尽壮颜衰。
妻孥流转无消息，
幸赖纲维有故知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_366','题刘大观诗卷后','刘鹗','元','少年壮气拂云霓，
马上鹰扬老未衰。
荡涤奸凶仍好武，
遨游江海更能诗。
池荒固自多春草，
世乱偏惊见瑞芝。
何况屯田有长策，
曲江真足驻雄师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_367','九日，置酒，与从事饮酣书事，示李子运','刘鹗','元','倏而虎鼠倏虫沙，
世变如云似未涯。
幸有故人来白酒，
且开好况对黄花。
纷纷凉月中军帐，
猎猎西风绝塞笳。
料得来春匡济了，
笑扶玉节共还家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_368','次韵','刘鹗','元','懒能策蹇诣时官，
且唤青山共倚阑。
春到谩寻花作友，
客来须借酒为欢。
山中泉石论交易，
天上风云入梦难。
奉母读书今有日，
却从北斗望长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_369','中秋有感','刘鹗','元','京国湖山十二年，
年年两地望婵娟。
流光过客催我老，
明月与人今夜圆。
又逐云萍来岭表，
幸同儿女乐尊前。
可怜有弟头如雪，
烂漫斑衣绕膝边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_370','登快阁','刘鹗','元','一登快阁情何极，
太史骑鲸已上天。
烟树溟濛秋可画，
江山空阔客如仙。
半生不识东南路，
浪迹深惭上下船。
四海故人今聚会，
忽惊歌舞落尊前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_371','题兴化县严士奇诗卷','刘鹗','元','盘错载逢知利器，
冰霜屡阅见生涯。
轻车熟路老为县，
短什长篇真当家。
今雨田田饶谷粟，
东风处处长桑麻。
公庭静坐无馀事，
閒数梅开第几花？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_372','送徐伯高','刘鹗','元','共宦关南三见秋，
相看政好又韶州。
故家乔木今千载，
碧嶂清江第一流。
案牍暇时仍阅史，
江山佳处更登楼。
如今刀笔皆为相，
好取功名趁黑头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_373','送李子洁巡按','刘鹗','元','十载相违一见君，
何堪岁晏又轻分。
南风十日不成雪，
一雨满山都是云。
滑滑长途宜自重，
萧萧孤驿不堪闻。
周原郡邑咨询遍，
为吊斯民志独勤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_374','次韵','刘鹗','元','节序匆匆又落花，
几回沧海叹乘槎？
不闻庭竹来鸣凤，
祇见宫槐噪晚鸦。
老去可怜心转赤，
悲来那觉鬓生华？
明当拂袖江南好，
山雨晴时笋正芽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_375','奉别瑞甫高掾郎还南台','刘鹗','元','岭海屡惊来诏使，
蛮方孰不仰皇都？
自怜老去难为别，
但有人来莫惜书。
乘兴何妨吟萼棣，
思归应不为莼鲈。
台端历历陈时弊，
十道疲民未得苏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_376','有怀蒙泉都帅二首','刘鹗','元','讨贼提兵垂十稔，
老成练达亦吾师。
竖儒几败乃公事，
男子要为天下奇。
公瑾孤军鏖赤壁，
谢玄劲气破淮肥。
从渠百万终为贼，
要取梅关却赋归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_377','有怀蒙泉都帅二首','刘鹗','元','卜式助边常百万，
如斯乃可济时艰。
传家自有遗经笥，
报国无忘拜将坛。
满眼黄金轻似土，
他年清节重如山。
广东未必真忘我，
但有官鹾定拨还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_378','韶州围城','刘鹗','元','浩劫如天似未涯，
生民性命等飞花。
兵戈轇轕动万计，
柴米从容有几家？
宇宙岂应将拆裂？
英雄到此谩咨嗟。
忠肝义胆难磨灭，
自昔睢阳世共誇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_379','枕上偶成','刘鹗','元','常思为国致升平，
每事参差谩有情。
天魔未除难学道，
国粮不足莫论兵。
痛怜劫运如长夜，
起视明星近五更。
待得朝廷消息好，
笑携儿子赋归耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_380','答胡海翁、胡宗性重谒','刘鹗','元','悠然无语眄庭柯，
风雨伤春奈若何！
浮世周旋如子少，
馀情流丽向人多。
好诗寄我频三诵，
穷巷经年一再过。
无酒固难淹李白，
空馀文燄照松萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_381','来诗','刘鹗','元','暖云扶绿上林柯，
春去春来可奈何！
远道尘泥行客少，
故园风雨落花多。
撷兰溪上心非隐，
种柳庄前足怕过。
尚意玉堂青眼旧，
肯嫌俗驾忤烟萝？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_382','雪罢，小立二首','刘鹗','元','风吹树枝雪，
片片点人衣。
尘浊有清意，
半因忙失之。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_383','雪罢，小立二首','刘鹗','元','呼童清晓起，
扫却门外雪。
日出消作泥，
惟恐涴幽洁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_384','题罗斗明','刘鹗','元','离别本来最苦，
相逢正值高秋。
肠断扁舟难挽，
烦君细问安流。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_385','寄旧友张汉杰二首','刘鹗','元','几度思君欲白头，
凄然常隐去年秋。
此心恨杀中澪水，
不向栖霞楼畔流。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_386','寄旧友张汉杰二首','刘鹗','元','双凤堂前日往来，
东坡池上几徘徊？
遥知尊酒相逢处，
风雨凄凉半是苔。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_387','九日峡江舟中','刘鹗','元','秋风如此客辞家，
重理平生旧帽纱。
不是故山无白酒，
年年奔走负黄花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
