INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_5_0','小景画','朱诚泳','明','流水高山趣自深，
抱琴相对坐松阴。
但须识得其中意，
何用人间有赏音。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1','次春日閒坐閒行二绝韵','朱诚泳','明','左图右史我中间，
坐看沈烟起博山。
读罢黄庭心似水，
绿阴幽鸟自间关。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2','次春日閒坐閒行二绝韵','朱诚泳','明','信步寻诗怕雨催，
手携筇竹步苍苔。
此身自喜无馀事，
閒逐浮云任往来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_3','马上观山','朱诚泳','明','层峦叠嶂倚高寒，
岚翠霏霏午未乾。
自有天然真意趣，
何须移入画图看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_4','书室弹琴','朱诚泳','明','庭院风清午漏残，
博山添火试沈檀。
绿阴满地黄尘逐，
一曲梅花且自弹。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_5','梨花夜月','朱诚泳','明','深院溶溶夜色新，
素娥移步就花神。
琼姿皓魄相辉映，
并作人间一段春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_6','桃花春雪','朱诚泳','明','六花和粉傅红妆，
咫尺天台入渺茫。
忽地作团银海乱，
翻嫌春色误刘郎。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_7','风前杨柳','朱诚泳','明','万缕千条拂钓矶，
细腰无力晚风微。
阿蛮似逞娇痴态，
几度傞傞舞绿衣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_8','雨中海棠','朱诚泳','明','醉来无力倚雕墙，
细雨纷纷湿粉香。
好似马嵬兵变日，
太真含泪卸红妆。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_9','过山家','朱诚泳','明','榆柳阴阴覆短墙，
绕畦黄蝶菜花香。
山翁睡起浑无事，
坐弄儿童笑夕阳。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_10','秋山行客图','朱诚泳','明','凉生疏树雨初收，
山气沾衣翠欲流。
何物骑驴痴老子，
摇鞭吟断一天秋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_11','闺情','朱诚泳','明','宝鸭香销午梦残，
倦来无力整云鬟。
阑干倚遍空惆怅，
人在天涯隔万山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_12','过曲江池','朱诚泳','明','江边一望草蒙茸，
弦管楼台转首空。
红杏不知尘世改，
年年依旧笑春风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_13','荐福僧房','朱诚泳','明','门对南山列画屏，
白云如水宿檐楹。
老僧长日无尘事，
一炷清香一过经。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_14','秋夜斋居与娄克让宪使马启东大参刘文纲少参联句','朱诚泳','明','玄鸟初归去，
宾鸿属仲秋。
金风时渐爽，
火气已全收。
清庙深还邃，
斋居阒且幽。
传呼严夜禁，
次第报更筹。
奉祀遵明训，
为邦赖至休。
茅分秦社稷，
位重汉诸侯。
肥腯供尝献，
丰年获岁酬。
神明歆懿德，
辅弼赞嘉猷。
每惧名难副，
深惭礼未周。
精诚元自集，
职业素能修。
仁义钦天道，
忠勤释帝忧。
春台恒盎盎，
寿域日优优。
相祀劳公等，
宾筵总畯流。
纲维端有本，
感格岂无由。
内外能脩谨，
神人永附投。
年年如此夜，
赓和从珠旒。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_15','郊行与长史吴元素游正固纪善汤以脩联句','朱诚泳','明','小队从容晓出城，
无边光景逐人行。
春明门外鸾声动，
长乐坡前马足轻。
清渭水光遥入望，
终南山色近相迎。
林边吠客谁家犬，
柳外呼人是处莺。
极目云烟春淡薄，
满前石子路峥嵘。
山翁争迓车舆过，
村妇咸惊鼓吹鸣。
茅屋炊烟桑叶暗，
河桥酒幔杏花明。
行厨内竖供茶茗，
小寺痴僧进菜羹。
千载风流馀故事，
一时宾从总含英。
游观肯惜花前醉，
倡和多于马上成。
兴尽归来天未晚，
无劳灯火候麾旌。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_16','竹轩与致政阎文振方伯吴元素长史汤以脩纪善强景明伴读联句','朱诚泳','明','小轩初洒扫，
走价速嘉宾。
暖日扶晴霭，
清风绝点尘。
青阳回北斗，
淑气溢西秦。
土润龙孙迸，
苔穿玉版新。
高贤应与契，
乐事自相因。
侍从多名侣，
吾王乃主人。
疏泉分地脉，
举酒乐天真。
坐爱淇园秀，
遥分湘浦春。
虞韶谐古调，
葛杖是前身。
劲节怜贞士，
虚心忆直臣。
信知渠自得，
宁厌客来频。
有物邀同赋，
相忘许任真。
百壶𢬵尽醉，
一视喜同仁。
把笔承颜晚，
飞觞入手频。
诗坛开胜集，
文会属兹晨。
黄道年逢卯，
青龙月建辰。
生成皆帝力，
雨露总天均。
讵用湔沂水，
何须钓渭滨。
此君端可托，
尤物岂须珍。
让国夷齐瘦，
辞荣渊宪贫。
玉妃堪作偶，
髯叟可为邻。
影落应千尺，
林成拟十旬。
投壶资作矢，
烹茗代为薪。
酒量真无敌，
诗成觉有神。
一腔情浩浩，
四座喜津津。
令肃愁深罚，
才悭愧效颦。
曳裾蒙覆帱，
叨禄荷陶钧。
睿藻光云汉，
清辞冠缙绅。
欣逢今子建，
文治正彬彬。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_17','登山与强景明伴读联句','朱诚泳','明','南山何崔嵬，
浑融出天匠。
百二古称雄，
封疆今独壮。
高于列雉城，
秀比施屏障。
导骑俾暂休，
肩舆聊一上。
霏岚湿我衣，
落絮沾行仗。
峰峦露晓晴，
乾坤正春酿。
山鸟自和鸣，
山花亦争放。
山溜讶琴鸣，
山云若潮涨。
崚嶒倦跻攀，
佳丽足瞻望。
悠悠引旆旌，
浩浩牵情况。
遥看泰华峰，
真乃丈人行。
咫尺近星辰，
分明履蓬阆。
俯察白云低，
遐观清渭漾。
高兴入微茫，
新诗给酬倡。
薄暮始言归，
赏心讵能忘。
山灵肯爽盟，
岁岁期相访。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_18','赏菊与严宗哲太守长史吴元素乔思孝伴读强景明联句','朱诚泳','明','九日招文士，
东篱醉菊花。
懒云神入藻，
苦雨脚成麻。
酒量应无敌，
吟怀讵有涯。
淡香轻桂麝，
佳色陋铅华。
礼秩矜疏放，
盘盂愧静嘉。
八珍兼鹿豕，
诸品杂鱼虾。
狂子歌为剧，
妖童髻作丫。
壮怀轻不落，
醉耳厌琵琶。
白雪翻新谱，
黄流泻紫霞。
天空雨新霁，
风细日初斜。
五亩终殊径，
千畦总异葩。
佳期人共赏，
睿制世争誇。
入枕清魂梦，
调羹溅齿牙。
且倾彭泽酒，
莫点玉川茶。
百拜情无已，
千钟数更加。
龙涎真可拟，
羯鼓不须挝。
雅趣同三益，
雄才陋五车。
仁贤光帝胄，
富贵自天家。
幸际明时好，
何妨逸兴奢。
东平名独盛，
北阙望应赊。
任落参军帽，
休乘博望槎。
风流怜楚客，
结束笑吴娃。
酩酊人分散，
疏林集暮鸦。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_19','和赏菊与长史吴元素游正固纪善汤以脩伴读强景明联句','朱诚泳','明','此日登高节，
东篱菊正花。
满园香似麝，
千本直如麻。
斸出从园脚，
移来傍水涯。
高情盟晚节，
好景殿年华。
富贵惭曹植，
疏狂笑孟嘉。
金铃低护雀，
湘竹细分虾。
喜入徵君眼，
慵簪美妓丫。
古词翻曲谱，
新调入筝琶。
酒艳流琼液，
花光绚彩霞。
环亭诸品植，
压帽数枝斜。
脆管初喧席，
寒蜂正恋葩。
弁欹从客笑，
句就任渠誇。
正味轻椒桂，
馀甘溢齿牙。
情酣非为酒，
神醒尚宜茶。
忘势情偏洽，
崇儒礼莫加。
吟长香易烬，
令急鼓频挝。
宴晚烧高烛，
归时驾小车。
衣冠叨盛会，
辞翰愧名家。
货色非吾事，
游畋肯自奢。
好怀聊共适，
内酝不须赊。
高宴如凌汉，
清游似泛槎。
飞觞劳侍史，
协律付官娃。
挥笔疑神助，
淋漓墨点鸦。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_20','重赏菊与阎文振方伯吴元素长史汤以脩纪善强景明伴读联句','朱诚泳','明','佳节逢重九，
弘开玳瑁筵。
衣冠来座上，
弦管列堂前。
雁度云千里，
虹收雨一天。
繁花分绵绣，
正色缀金钱。
莫为秋容淡，
应期晚节坚。
餐英能辟谷，
饮水可延年。
采采凌霜瘦，
瀼瀼带露鲜。
麝兰纷馥郁，
罗绮斗暄妍。
西子娇疑语，
妖环醉欲眠。
蜂媒情太剧，
蝶使信空传。
秋圃真堪托，
春风不受怜。
橘橙宜共赏，
桃李谩争先。
灿灿诗如锦，
源源酒似泉。
歌喉怜宛转，
舞袖喜翩𦒘。
旧量谁云减，
新声我最便。
吟坛兼四美，
藩邸集群仙。
槛外风初静，
楼头月未圆。
杯盘将欲彻，
宫徵尚相宣。
酬酢情无已，
推敲势欲颠。
尘凡真有庆，
鱼水岂无缘。
更鼓休相促，
茶瓜且少延。
兴阑投彩笔，
醉去压银鞯。
自昔恩波阔，
而今乐事偏。
拜归分绛烛，
护送拥金莲。
感激何由报，
同祈寿八千。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_21','再赏菊与阎文振方伯吴元素长史汤以脩纪善强景明伴读联句','朱诚泳','明','秋来尝苦雨，
九日喜新晴。
佳色看丛菊，
香醪泛落英。
衣冠成胜会，
弦管动新声。
圣世文风盛，
金天灏气清。
锦屏重护影，
玉篆细标名。
繁露沾来重，
清霜著处轻。
绕篱浓复淡，
倚槛直还横。
异品供人玩，
群葩照眼明。
举杯添逸兴，
把笔助吟情。
酒许留连饮，
诗容次第成。
楚骚曾入咏，
彭泽久寻盟。
桃李争春艳，
松篁晚自荣。
秋容三径淡，
雄辩四筵惊。
且折簪华发，
宁辞罄玉罂。
不须烹白石，
焉用煮黄精。
中国多麟凤，
边疆罢甲兵。
老来辞紫绶，
醉后恋银筝。
云锦机中出，
龙蛇笔下生。
九重同覆载，
四海贺升平。
共喜游藩邸，
何妨隐斗城。
身须妨酒困，
心恐为诗怦。
上苑风烟隔，
南阳月旦评。
长诗惭我续，
好景许谁争。
纳海乌先堕，
栖林鸟不鸣。
出门归去晚，
谯鼓振初更。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_22','淡香亭赏菊与丘仲玉少参杨应宁宪副联句','朱诚泳','明','端居葆贞素，
眷言惜秋光。
植彼霜中物，
挹此淡而香。
和气夺金秀，
正色裁坤裳。
楚畹茝兰馥，
天孙云锦张。
黯淡散轻紫，
圆融飞碎黄。
邈矣绝尘俗，
岿然殿群芳。
交联君子社，
爱比富贵妆。
桂府地空辟，
娃宫蜂自忙。
忘言南山趣，
击节老圃章。
鼓兹希声调，
侑以玄酒觞。
一亭中有翼，
八窗秋正凉。
开口苦不易，
盟心故难忘。
繁枝涤芜秽，
夙种深盖藏。
英餐歌楚泽，
水饮怀南阳。
参陪沗高会，
授简惭荒唐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_23','骊山怀古与汤以脩纪善联句','朱诚泳','明','长安晚出袅唫鞭，
税驾骊山一怅然。
烽火台空人已去，
莲花汤暖水犹膻。
山猿窥果来林外，
野鹿衔花出苑前。
樵子云中薪古木，
耕夫雨后拾遗钿。
前朝社稷胡雏坏，
上古阴符老母传。
嬴墓已飞三月火，
汉陵犹锁四时烟。
落霞疑似张绯幕，
流水还如奏管弦。
斗宝谩劳谈往事，
坑儒徒自忆当年。
朱楼紫殿空遗趾，
汉碣唐碑蚀旧镌。
夜月行营人寂寂，
春风辇路草芊芊。
荒祠燕雀寒山下，
高冢牛羊夕照边。
眼底兴亡存鉴戒，
何须搔首问苍天。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_24','莲塘与强景明伴读联句','朱诚泳','明','睡起深宫厌日长，
閒来小辇过莲塘。
沿堤钗股多芳荇，
夹道丝条总绿杨。
步底流泉分地脉，
树头飞翠滴岚光。
移将太液池边景，
散作旃檀国里香。
共爱精神兼色相，
还怜红白间青黄。
应疑根自三峰徙，
果见花开十丈强。
天马有蹄争出浴，
神鱼无饵不须藏。
旋收紫的供茶碗，
自捲青筒当酒觞。
赤日行天纨扇急，
清风入席苧衣凉。
蜻蜓对立来还去，
属玉双飞集又翔。
小竖敲针权作钓，
奚奴横木代为梁。
人缘避暑趋亭上，
客为寻诗坐水傍。
勘破乾坤俱是乐，
真成物我两相忘。
濂溪老子无边趣，
太乙真人一叶航。
自足娱心歌窈窕，
何须濯足赋沧浪。
新诗辏出应难和，
烂醉扶归也不妨。
须信西方真佛境，
更于何处觅仙乡。
非才自愧非韩孟，
七步谁能敌我王。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_25','送成复初指挥南还与严宗哲太守乔思孝长史强景明伴读联句','朱诚泳','明','一骑冲寒出灞陵，
望中仙掌入云层。
三秦豪杰乡评在，
两叶勋华国史登。
龙起当年闻扈从，
蝉联此日看云仍。
琴边得趣追中散，
画里传诗比右丞。
瘦骨独怜清似鹤，
奇毛转觉鸷如鹰。
名通丹陛交章荐，
功在黄河满路称。
分手又从天外未，
举头犹记日边曾。
白云目断松楸远，
紫电光寒浐渭澄。
郑驿梅缄春早寄，
谢池草思梦还凭。
大江潮上初生月，
古渡澌流渐合冰。
归到旧京应忆我，
石头风雨夜窗灯。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_26','二月二十二日与杨应宁宪副宋惟寅宪佥强景明伴读城东泛舟联句','朱诚泳','明','冉冉清溪映绿杨，
杏园遥指碧云傍。
藩宫地接天潢近，
灵沼波分太液长。
鱼鸟乐随人共狎，
主宾情与世相忘。
匆匆不尽仙舟兴，
却笑公家镇日忙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_27','二月二十二日与杨应宁宪副宋惟寅宪佥强景明伴读城东泛舟联句','朱诚泳','明','小舟摇曳出垂杨，
岸草汀花送远香。
善拟东平心最乐，
尊倾北海兴偏长。
百年利涉兰为棹，
一代豪吟笔有床。
天外惠风如解事，
黑云催雨助诗狂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_28','赏春与强景明伴读联句','朱诚泳','明','青春寻乐事，
受简召群仙。
鸟外张油幕，
花前设绮筵。
小阶芳草合，
深苑锦云鲜。
山色开图画，
莺声错管弦。
园桃迎我笑，
宫柳正人眠。
浸酒挼花蕊，
供茶煮竹鞭。
深杯休放却，
高兴更相牵。
睿制容相续，
清词敢售妍。
水鱼元有合，
雨露自无边。
敢谓邹枚盛，
尤惭董贾贤。
多应怜气味，
不是慕荤膻。
令出催金钵，
诗成唾锦笺。
陈思才独盛，
妙思入幽玄。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_29','集句拟刘文纲少参悼亡','朱诚泳','明','击节悲歌缺唾壶，
风花飞坠鸟鸣呼。
纵令奔月成仙去，
为问嫦娥更有无。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_30','集句拟刘文纲少参悼亡','朱诚泳','明','油壁香车不再逢，
阳台云雨去无踪。
写真纵有崔徽笔，
不是崔徽卷里容。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_31','集句拟刘文纲少参悼亡','朱诚泳','明','不见当时劝酒人，
今年依旧去年春。
幽窗谩结相思梦，
梦里相逢恐未真。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_32','集句拟刘文纲少参悼亡','朱诚泳','明','感时心绪杳难平，
无处登临不系情。
寂寂海棠枝上月，
清光此夜为谁明。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_33','集句拟刘文纲少参悼亡','朱诚泳','明','绿窗今夜梦分明，
梦得分明恨转生。
觉起无言成独坐，
参横斗转月三更。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_34','集句拟刘文纲少参悼亡','朱诚泳','明','断猿今夕泪沾衣，
惆怅朱颜不复归。
玉佩无声画屏冷，
寒窗灯尽月斜晖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_35','集句拟刘文纲少参悼亡','朱诚泳','明','离别不堪无限意，
为君惆怅又黄昏。
明眸皓齿今何在，
环佩空归月夜魂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_36','集句拟刘文纲少参悼亡','朱诚泳','明','绣帐金炉冷篆烟，
魂归溟漠魄归泉。
题诗朝忆复暮忆，
花落猿啼又一年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_37','集句拟刘文纲少参悼亡','朱诚泳','明','一寸相思一寸灰，
苍茫罗袖隔红埃。
不知情魄游何处，
且作行云入梦来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_38','集句拟刘文纲少参悼亡','朱诚泳','明','一片香魂不可招，
野烟江草共萧萧。
鱼书欲寄何由达，
隔断巫山去路遥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_39','集句拟刘文纲少参悼亡','朱诚泳','明','红衣落尽暗香残，
相见时难别亦难。
弱水蓬莱三万里，
碧桃何处更骖鸾。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_40','集句拟刘文纲少参悼亡','朱诚泳','明','冰簟银床梦不成，
宵分独坐到天明。
潸然四顾难消遣，
谁为梅花怨未平。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_41','集句拟刘文纲少参悼亡','朱诚泳','明','红颜无奈落花催，
可使英灵许再来。
竟日倚阑空叹息，
寸心争忍不成灰。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_42','集句拟刘文纲少参悼亡','朱诚泳','明','百感中来不自由，
琐窗花老镜鸾收。
云飞雨散知何处，
人自伤心水自流。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_43','集句拟刘文纲少参悼亡','朱诚泳','明','目断黄云雁影沈，
秋声无不搅离心。
月中人去青山在，
一段清愁自不禁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_44','集句拟刘文纲少参悼亡','朱诚泳','明','锦机春煖凤停梭，
生死情深可奈何。
回首不堪肠断处，
高坟新起白峨峨。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_45','集句拟刘文纲少参悼亡','朱诚泳','明','含香体素欲倾城，
自是三千第一名。
今日美人弃我去，
寂寥珠翠想遗声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_46','集句拟刘文纲少参悼亡','朱诚泳','明','旧时仙侣笑相迎，
王母前头作伴行。
宴罢瑶池春梦断，
何年绛节下重城。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_47','集句拟刘文纲少参悼亡','朱诚泳','明','金琐瑶窗翠幔中，
几回魂梦与君同。
相携不尽叮咛语，
得丧悲欢总是空。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_48','集句拟刘文纲少参悼亡','朱诚泳','明','闭门疏雨落梧桐，
多少凄凉在此中。
遐想倚阑人去后，
玉书无路托鳞鸿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_49','集句拟刘文纲少参悼亡','朱诚泳','明','画楼西畔桂堂东，
孔雀屏开烛影红。
今日窅然忘此景，
野花黄蝶领春风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_50','集句拟刘文纲少参悼亡','朱诚泳','明','鸾镜佳人后会稀，
论交却忆十年时。
钗留一股合一扇，
物在人忘无见期。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_51','集句拟刘文纲少参悼亡','朱诚泳','明','旧恨新愁只自知，
高楼独上思依依。
红颜未老恩先断，
惆怅当年意尽违。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_52','集句拟刘文纲少参悼亡','朱诚泳','明','隐几无言有所思，
惨烟悽雨不胜悲。
梧桐叶上偏萧索，
始是思君肠断时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_53','集句拟刘文纲少参悼亡','朱诚泳','明','春梦无心秪似云，
一灯明灭夜将分。
美人粉黛归何处，
欲寄音书那得闻。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_54','集句拟刘文纲少参悼亡','朱诚泳','明','情缘心事两难忘，
回首东风一断肠。
欲吊芳魂何处是，
野田极目草茫茫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_55','集句拟刘文纲少参悼亡','朱诚泳','明','南国佳人去不回，
旧交心为绝弦哀。
若逢佳景惟惆怅，
怀抱何时得好开。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_56','集句拟刘文纲少参悼亡','朱诚泳','明','华笺好作断肠文，
薤露歌残不忍闻。
四尺孤坟何处是，
落花飞絮正纷纷。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_57','集句拟刘文纲少参悼亡','朱诚泳','明','一日相思似九秋，
百壶芳醑岂消忧。
魂归南国迷黄壤，
月户云窗许暂留。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_58','集句拟刘文纲少参悼亡','朱诚泳','明','银烛秋光冷画屏，
绕廊行处思腾腾。
美人一去无消息，
敲遍阑干唤不应。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_59','集句拟刘文纲少参悼亡','朱诚泳','明','几度相思入梦频，
镜中金翠李夫人。
暂时会面终相异，
白水青山空复春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_60','集句拟刘文纲少参悼亡','朱诚泳','明','音容无复见当时，
花落深春莺亦悲。
今日不堪生死别，
相思无路莫相思。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_61','集句拟刘文纲少参悼亡','朱诚泳','明','彩云声断玉箫寒，
几许幽情欲话难。
尽日伤心人不见，
一帘风雨杏花残。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_62','集句拟刘文纲少参悼亡','朱诚泳','明','为哦楚些作哀诗，
婉转蛾眉能几时。
天上人间不相见，
欲从何处寄相思。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_63','赞十四首','朱诚泳','明','赳赳仪容，
桓桓英武。
出甲陇西，
散其部伍。
心拱北辰，
威镇西土。
肇造秦邦，
为我始祖。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_64','赞十四首','朱诚泳','明','堂堂世胄，
曰惟宁河。
姿容严重，
佐理中和。
邑姜媲美，
太姒同科。
配我始祖，
耿耿不磨。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_65','赞十四首','朱诚泳','明','仪容丰伟，
性行脩洁。
震若雷霆，
皎如冰雪。
持已谨严，
维藩卓越。
维我隐祖，
天潢之杰。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_66','赞十四首','朱诚泳','明','天生淑质，
世阀元勋。
中心乐善，
内助惟勤。
贤声洋溢，
令德彰闻。
佐我隐祖，
百世腾芬。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_67','赞十四首','朱诚泳','明','明明隐祖，
允赖匡襄。
笃生国嗣，
曰怀曰康。
宗枝蕃衍，
奕叶隆昌。
夫人之泽，
地久天长。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_68','赞十四首','朱诚泳','明','兢兢持已，
翼翼小心。
靡奢靡纵，
不骄不淫。
夙成令德，
早著徽音。
天夺之速，
千古沉沉。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_69','赞十四首','朱诚泳','明','天姿开爽，
性质刚明。
雅音允协，
巧思层生。
藩维之表，
宗室之英。
惜乎短折，
谥称其情。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_70','赞十四首','朱诚泳','明','天挺幽姿，
配我怀祖。
九死不移，
终身一姥。
烈日严霜，
中流砥柱。
寿考令德，
名垂千古。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_71','赞十四首','朱诚泳','明','天姿英毅，
至性刚方。
敦崇儒术，
雅尚词章。
臣工震肃，
礼乐铺张。
维我康祖，
于秦有光。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_72','赞十四首','朱诚泳','明','具备德容，
博通书史。
纲纪宫闱，
教育孙子。
相我祖王，
实周任姒。
于万斯年，
永赖馀祉。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_73','赞十四首','朱诚泳','明','猗欤昭考，
肫肫其仁。
有如时雨，
有若阳春。
德音秩秩，
文质彬彬。
爱人好予，
宠谥维新。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_74','赞十四首','朱诚泳','明','早膺封册，
相我先王。
寿虽不永，
名亦斯彰。
仪容如在，
传诵不忘。
于穆清庙，
同享烝尝。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_75','赞十四首','朱诚泳','明','天姿贞淑，
懿德慈良。
山川毓秀，
宫壸腾光。
生我育我，
为君为王。
褒赠自天，
永荷吾皇。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_76','赞十四首','朱诚泳','明','粤膺妙选，
继佐先王。
宠颁册命，
恩礼殊常。
尊崇二纪，
宫壸重光。
四旬薨逝，
附葬原冈。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_77','弘治癸丑予以足疾未瘳倦于医居恒忽忽或有进者曰去城之西三百里太白山之下有泉曰凤泉去城之东百馀里曰石门亦有汤泉去城之东北六十里曰骊山亦有温泉浴其水者痼疾皆愈予闻而异之曰有是哉第以守藩不敢专出入乃遣使上告于天子天子许之予拜命踊跃不敢烦有司自饰具以往感恩志喜因有一','朱诚泳','明','忆昨封章叩紫宸，
果然天意俯从人。
𤏄除宿恙凭灵液，
造就馀生荷至仁。
指点终南收胜槩，
摩挲华岳动精神。
挥毫欲写山川秀，
只恐归来记不真。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_78','是岁二月丁未出郭予宗室昆季诸王往饯于城西之十里铺予因有诗留别其诗云','朱诚泳','明','亲藩叨守冒尊荣，
敢为游观出斗城。
赐浴温泉天子诏，
弘开祖席友于情。
秦川日暖旌旗动，
周道风和鼓角鸣。
料得归来诗满卷，
安排赓和答升平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_79','其日巡镇诸公暨诸藩臬候送于崇仁寺予亦有诗留别其诗云','朱诚泳','明','叨绾金符守一方，
喜承温诏浴温汤。
行车细览江山秀，
祖席遥分雨露香。
绝饮平生惩酒诰，
惜田宁敢蹈禽荒。
归来料得无惭德，
独有丹诚答圣皇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_80','途次望汉城甚迩作未央宫怀古','朱诚泳','明','手提一剑竟成功，
定鼎长安此建宫。
作则已非神禹戒，
贻谋翻笑宰臣工。
凤麟殿阁成尘久，
鸡犬乡村有路通。
钟室不知缘底事，
令人千古惜英雄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_81','致政康都阃别业去咸阳仅十里其居枕沣水甚有幽致都阃谒予于道左请留予为之一饭因贻以诗','朱诚泳','明','将军别墅枕沣河，
此日停骖试一过。
绕舍笙簧流水急，
当门图画好山多。
暖风鸡犬鸣深树，
斜日牛羊卧软莎。
应有杜陵馀兴在，
东桥欲问讯如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_82','汉有天下张良实谋臣也逮大功既成乃欲从赤松子游豪杰欺人之言岂可信哉其墓一在咸阳一在韩城俱载郡志未知孰是予所过则咸阳者云','朱诚泳','明','天生才杰起山东，
肯学连衡与合从。
四海风尘争逐鹿，
一编筹策竟从龙。
殡宫已见埋青草，
石室空传伴赤松。
明哲保身公独有，
尚疑人在蹑仙踪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_83','将抵咸阳日已薄暮予临河登舟亦有作云','朱诚泳','明','县城背倚北原坡，
南面通津古渭河。
两岸夕阳青草渡，
半篙春水白鸥波。
当年宫殿阿房盛，
此地丘陵汉室多。
欲向长途询往事，
南山无语郁嵯峨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_84','予既渡宿于咸阳之行台明日因留一绝','朱诚泳','明','半生今始出重城，
客枕通宵梦未成。
月冷乌啼红烛暗，
感怀吊古不胜情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_85','道中即事','朱诚泳','明','步辇乘春古道平，
一村才过一村迎。
杏花雨细沾衣润，
杨柳风和拂面轻。
山势东连秦岭阔，
河流西下渭源清。
前朝胜槩豪华地，
知逐沧桑几变更。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_86','予读汉史暨武帝内传每叹其雄才大略而乃惑神仙且穷兵于远俾末年不下轮台一诏则汉事未可知也矧闻茂陵侈葬可为于邑予行经驻视不无千古之感因占一诗以寄怀云','朱诚泳','明','天马不来人已去，
茂陵老树转斜阳。
东方西母言何诞，
玉露金桃寿可长。
卖武爵真成短计，
上书谏本为元良。
当年不下轮台诏，
岂独亡秦事可伤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_87','暮至兴平','朱诚泳','明','驻马平陵已夕阳，
当年槐树尚成行。
高原西下岐山迥，
曲泊东连渭水长。
隧道衣冠藏汉武，
居人箫鼓祀商汤。
伤心往事皆陈迹，
莫怪青山笑客忙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_88','宿白渠驿夜闻风雨大作感怀','朱诚泳','明','早发咸阳宿始平，
半笼银烛照深更。
窗纱猎猎惊风势，
庭树萧萧送雨声。
顾我未成疏馆梦，
何人不动故乡情。
也知明到温泉近，
屈指犹烦数去程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_89','兴平之西二十里有镇曰马嵬致政阎方伯文振之旧第在焉方伯盖予诗友也且喜其居近周道因为之一留仍贻之以诗曰','朱诚泳','明','文章方伯早悬车，
喜挹清风步二疏。
好水好山供大隐，
非村非郭足幽居。
一缸绿蚁新醅酒，
万轴牙签旧赐书。
满眼儿孙终日醉，
人生适意更何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_90','予读天宝遗事每叹玉环之丑久秽青史明皇昏惑逆竖酿祸马嵬之变无足悼笑兹经故址驻马徘徊殆不能去因以诗纪之','朱诚泳','明','古城无址只荒坡，
翠辇曾经此地过。
羯鼓声沉鼙鼓动，
海棠花落野棠多。
玉环旧恨原头土，
莲步遗踪袜底罗。
蜀道归来南内冷，
梧桐秋雨夜如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_91','再渡渭河','朱诚泳','明','谷风吹渭水，
二月冷于秋。
动荡劳舟子，
扶持藉忖留。
解鞍浮从骑，
鼓枻起群鸥。
去去邰城近，
依稀见驿楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_92','予闻山曲曰盩水曲曰厔而盩厔一邑果在山水之间乃知昔人立名良有以也予既渡渭水风雨甚寒绝无诗思行台明发聊成一诗以写兴云','朱诚泳','明','客窗春梦破残更，
骑从纷纷发县城。
霁色微茫兼曙色，
角声呜咽杂鸡声。
漙漙湛露沾衣润，
淡淡霏烟著树轻。
数里行来人迹少，
远村灯火尚微明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_93','经废寺','朱诚泳','明','楼台金碧委尘埃，
黄叶填门昼不开。
坏壁有基缘薜荔，
断碑无字蚀莓苔。
谈经问偈僧何在，
吊古寻幽我独来。
最是不堪惆怅处，
斜阳枯木鸟声哀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_94','盩厔之南三十里有台焉相传为马融读书之所予闻六籍穿凿于汉儒而女乐生徒之缪亦可资千古一笑途次口占一律聊以吊南郡太守云','朱诚泳','明','扶风家世汉通儒，
不重椒房重道腴。
庐郑久从高弟列，
严敦敢望后尘无。
春围绛帐人如玉，
月满荒台树有乌。
况是临江遗庙在，
春风十里长蘼芜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_95','予尝慕周人王业盖肇迹于公刘渐盛于古公而成功于文武今之凤翔寔古之成周也予入其境缅想遗风而高山景行意自不能已焉因诗以纪之','朱诚泳','明','成周当日旧提封，
王业艰难自古公。
太白终南山势迥，
皋门冢土地形雄。
东来峣崅秦关险，
西上舟车蜀道通。
满眼桑麻民俗厚，
路人争说是豳风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_96','予尝读正蒙诸书而仰止横渠久矣兹过郿阳适道先生故居因询左右乃知先生祠墓在镇遂以瓣香致敬祠下且留一律以寓诚云','朱诚泳','明','孙吴佛老谩须评，
易道深研见理明。
学术有心期圣代，
井田无计到苍生。
两铭文字仪刑地，
一瓣春秋报享情。
此日我来应下拜，
泰山何啻仰高名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_97','郿坞即董卓所据处也噫人生几何而彼乃积金储谷为三十年规何愚甚哉且卓之所为虽燃脐于市不足以偿其罪予因经此遂以诗叹之','朱诚泳','明','策马经郿坞，
临风感慨深。
高腴徵万斛，
珍贝累千金。
桀骜钟人祸，
奸雄竟陆沈。
空馀歌舞地，
斜日下疏林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_98','予登西山送目太白山绝顶积雪齐云耸若冰柱时天风满衣飘飘然真有神游象外之趣既而清思顿发遂作长歌以写兴云','朱诚泳','明','乾坤万里春熙熙，
赐浴温汤来古郿。
闻说西山多胜绝，
兹晨喜我停车旂。
爱山自笑真成癖，
夙驾星言登𡾊㟪。
徐行踏破白云堆，
小队飘摇图画里。
绝顶人传万仞高，
天枢咫尺天风号。
罗衣不奈翠岩冷，
坐久清寒生发毛。
凭高却讶尘寰小，
太白遥看入空杳。
层层积雪碍星辰，
银海光摇射琼岛。
几回欲下又徘徊，
长安回首飞黄埃。
恨隔弱流三万里，
何缘冲举栖蓬莱。
镇日看山厌尘俗，
便须烂煮蓝田玉。
紫皇寿我三千秋，
来往青冥驾黄鹄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_99','孔明天下奇才也其八阵一图鬼神莫测出师二表王业所关奈何天不祚汉而星殒中军可胜叹哉陈寿作史以将略非其所长真缪论也予因登西山绝顶遥望五丈原甚迩且见一祠在林麓间即侯庙也以隔绝未得一荐牲酒姑以诗吊之','朱诚泳','明','斜峪遥连渭水平，
当年伐魏此屯兵。
人怜炎汉三分国，
天夺奇才半世名。
八阵风云今亘古，
千年忠义死犹生。
原头夜半瞻燐火，
尚讶星流大将营。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_100','予登西山绝顶既望武侯祠庙而一吊矣时侍臣有指渭水之阳而告者曰此即太公磻溪也噫昔人不作风物如故虽鹰扬事业殆一浮云耳亦作一诗以吊云','朱诚泳','明','养老风闻自海滨，
远依西伯寄閒身。
梦残石室孤峰月，
占断渔矶两岸春。
玉佩钓来文最古，
鹰扬老去命维新。
江湖多少垂纶者，
徒仰馀光愧后尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_101','太白山之下有凤泉焉世传可以愈疾予承优诏许浴于兹凤泉之水其恩波欤感激之馀辄成古诗一首以示不忘云','朱诚泳','明','新春领明诏，
兹晨浴凤泉。
临源观沸水，
谁能测其然。
翻疑混沌初，
劫火犹连延。
地轴想已焚，
日夜如烹煎。
又疑回禄沈，
堕地生紫烟。
晶荧固宜尔，
辉光烛金天。
方池甃寒石，
涌出孤峰前。
渴虎讵能饮，
乖龙宁敢眠。
我闻黄耇言，
浴者沈疴痊。
时清自多验，
浊世嗟无缘。
方今际昌运，
明良逢圣贤。
山灵谅有知，
寿域开八埏。
我来试𤏄洗，
寒温良不偏。
顿惊四体轻，
末疾忽以捐。
拜手感天子，
丹扃思刻镌。
题诗写山石，
聊为来者传。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_102','予爱山者然予府适面南山虽朝夕快睹而未偿厥趣兹承恩诏赐浴凤泉肩舆连日山行其樵歌牧唱应酬于山水之间鹤唳云飞出没乎林麓之外予心甚乐而幽兴满怀但觉目前风景殆为吾诗设也因口占三首谩记于此','朱诚泳','明','翠微深处绝嚣纷，
岚气空濛湿未分。
樵斧丁丁穿树重，
梵钟隐隐隔溪闻。
龙归古洞留残雨，
鹤憩长松恋白云。
清啸一声毛骨爽，
碧空回首又斜曛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_103','予爱山者然予府适面南山虽朝夕快睹而未偿厥趣兹承恩诏赐浴凤泉肩舆连日山行其樵歌牧唱应酬于山水之间鹤唳云飞出没乎林麓之外予心甚乐而幽兴满怀但觉目前风景殆为吾诗设也因口占三首谩记于此','朱诚泳','明','朝陟青山巅，
暮宿青山下。
逍遥岁月閒，
俯仰乾坤大。
缅怀尘鞅中，
几人得休暇。
驹隙等流光，
莫嗤行乐者。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_104','予爱山者然予府适面南山虽朝夕快睹而未偿厥趣兹承恩诏赐浴凤泉肩舆连日山行其樵歌牧唱应酬于山水之间鹤唳云飞出没乎林麓之外予心甚乐而幽兴满怀但觉目前风景殆为吾诗设也因口占三首谩记于此','朱诚泳','明','出门看青山，
芙蓉千万朵。
倦临白石眠，
吟藉紫苔坐。
好鸟面前啼，
飞花眼中堕。
幽居怡白云，
于焉忘物我。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_105','凤泉之南不二里有一巨石而复承一石大亦称焉以一夫撼之则其势微动加以众力则屹然莫移盖亦异也相传谓之神功石岂其然乎予停舆一视因成二诗','朱诚泳','明','六丁何日遣吴刚，
劈断云根此地藏。
神护鬼呵经岁月，
紫苔玄甲饱风霜。
恨深李广空疑虎，
术妙初平戏叱羊。
一指撼来如欲堕，
当年贲获谩誇强。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_106','凤泉之南不二里有一巨石而复承一石大亦称焉以一夫撼之则其势微动加以众力则屹然莫移盖亦异也相传谓之神功石岂其然乎予停舆一视因成二诗','朱诚泳','明','谁将山骨叠层层，
看到忘言理莫凭。
炊饭只应仙客惯，
补天惟有女娲曾。
青回鸟迹苔千点，
影落龙潭月半棱。
寄语游人莫相近，
岩墙之下尚兢兢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_107','予经山寺爱其幽雅因留宿焉昔人所谓天下名山僧占多者信然哉所惜者世无金山长老而吾带盖不足留聊成一诗以自适云','朱诚泳','明','偶过西山最上峰，
巉岩鸟道接禅宫。
笑谈风月三生外，
俯仰乾坤一瞬中。
香冷竹窗春院静，
灯昏石榻夜堂空。
懵腾偏称閒中睡，
一任东窗曙色红。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_108','予连日山行而颇有山中之乐第恨世无摩诘而画中之诗未有拈出之者因再成二律以写怀云','朱诚泳','明','面面峰峦罨画新，
地偏无处著红尘。
人间空有烟霞想，
林下谁于鹿豕亲。
老木月寒猿啸夜，
落花风暖鸟啼春。
静中契得长生术，
肥遁何妨学隐沦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_109','予连日山行而颇有山中之乐第恨世无摩诘而画中之诗未有拈出之者因再成二律以写怀云','朱诚泳','明','推窗日日看芙蓉，
萧散襟怀野兴浓。
一派山泉和月泻，
几家村杵带云舂。
世情淡比巢林鹤，
诗思清于倚涧松。
睡足五更天欲曙，
梵宫又听隔溪钟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_110','将出西山留别神功石丈','朱诚泳','明','见说环奇久著名，
相逢又复怅离情。
自缘大造流形异，
谁使良工巧琢成。
太白雪深尤突兀，
终南云静益峥嵘。
山灵好为频揩拭，
莫遣尘埃野蔓生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_111','予闻秦始皇好神仙于尹喜楼南立老子庙晋惠更新即今之楼观也厥后废毁胜国时安西王乃大加修饰而于今为盛盖天下第一福地也有系牛柏相传为周时故物殆亦后人附会而补植之者予缅怀青牛老人第无自而闻其道德之言姑成一诗以写胜概云','朱诚泳','明','尘海仙家第一宫，
峥嵘台殿诧秦工。
五千道德言犹在，
百二河山势自雄。
炼药炉寒虚夜月，
系牛柏老动秋风。
穹碑屹立斜阳外，
夜夜龙光贯彩虹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_112','予既出楼观乃登说经台凭高纵目但觉松风满山而恍惚若闻老氏道言也且摩挲古刻而米老第一山字尤甚奇古惜从行无善绘者未能摹写其景以归姑成一诗以涤尘襟云','朱诚泳','明','万山深处一高台，
法演玄元道教开。
金鼎风云龙虎伏，
石坛星斗鬼神哀。
函关紫气今何在，
天竺青牛竟不回。
欲问长生无觅处，
阆风楼阁隔蓬莱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_113','说经台之北仅一舍有祖庭焉予访重阳旧迹虽有黄冠数辈惜无可问之者然而叠阁重楼气象甚都所谓五祖七真者其亦乘云驭鹤而来憩于此耶盖不可知也予面峰峦徘徊松下恍若飞渡弱流而容与蓬山之上矣因作一诗以写幽兴云','朱诚泳','明','峰峦矗矗与天齐，
叠阁层楼望处微。
云去瑶坛丹灶冷，
雨香石径紫芝肥。
湫深自尔宜龙蛰，
树密多应碍鸟飞。
真境可人清兴好，
肯因行役浪思归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_114','予过渼陂是即岑参兄弟约杜甫以同游者也予亦好奇者想渼陂之名忆岑杜之游因成四韵以传好事者','朱诚泳','明','跃马乘春到渼陂，
渼陂风景足清奇。
晴涵山影沈青黛，
冷浸天光漾碧漪。
盛代已无唐室禁，
荒碑犹载杜陵诗。
楼船箫鼓俱陈迹，
禾黍斜阳异昔时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_115','予好奇者每邂逅山水之胜辄注目焉及抵鄠县则逼夜矣聊成一诗以自笑','朱诚泳','明','斗柄横空夜若何，
绛纱笼烛渡涝河。
岚光结暝迷前纛，
水气生寒透薄罗。
拜月妖狐当古道，
惊风栖鸟散乔柯。
宵征莫怪归心急，
屈指严程只恐过。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_116','灵囿盖文王蕃育鸟兽之所也予道经于兹而远想白鸟麀鹿之盛遂口占一诗云','朱诚泳','明','阔野微茫入望迷，
年年芳草一萋萋。
可怜麀鹿搜寻尽，
惟见斜阳白鸟飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_117','予闻文王之作灵台盖以望氛祲察灾祥也且其倏然而成若神灵之所为者故以得名诗不云乎彼美人兮西方之人兮因经台下谩成一绝以寓景行之意云','朱诚泳','明','摇摇小辇过灵台，
为忆周文一怆怀。
盛代不劳閒望气，
朝阳时有凤凰来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_118','灵台之下有灵沼焉然物换星移而无复于牣之兴因太息久之亦成一绝','朱诚泳','明','垂鞭信马日西斜，
灵沼吟看起叹嗟。
鱼鳖成尘春水涸，
年年惟见长桑麻。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_119','昆明池即老杜所谓昆明汉武旧时功者也予经其地盖已墟矣因作一律以寓慨叹之意云','朱诚泳','明','万里昆明未即功，
方池凿象练兵戎。
女牛跨汉东西隔，
旗鼓连营远近同。
巨舰初移云作阵，
石鲸如动水生风。
可怜无限桑麻地，
都付征人事远攻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_120','予过造书台远怀苍颉因睹空阶鸟迹而犹讶其造书时也夫何鸟篆既远而字体变化真如浮云矣彼以俗书逞遒媚者得不知所自欤因成一绝姑以吊造书者云','朱诚泳','明','凿开大块日支离，
混沌元来死不知。
山寺空阶遗鸟篆，
相看犹似造书时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_121','细柳营实汉文劳军之地也予读汉史而追思其事若亚夫者可谓真将军矣彼棘门灞上之军有如儿戏者岂可同日而语哉因成一绝以吊亚夫云','朱诚泳','明','赐复捐租久罢兵，
将军身后只空营。
棘门灞上俱尘土，
青史何劳纪姓名。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_122','予游兴庆宫而远忆李唐之盛因叹尘世繁华真一梦耳太息之不足遂作一诗以寄意焉','朱诚泳','明','复道金堤辇路通，
繁华非复旧时同。
舞衣零落尘埋玉，
珠被销沈烛散风。
春色已随宫树老，
夕阳犹向苑台红。
凭高几许兴亡恨，
都在平芜一望中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_123','予过灞桥偶思郑綮之事可发一笑今春和景物明媚若给予诗料者然而清兴满怀自不可遏又何必在于风雪中耶漫成二绝以资谈柄','朱诚泳','明','官桥烟柳绿丝丝，
折尽长条为别离。
桥上行人桥下水，
滔滔何事日奔驰。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_124','予过灞桥偶思郑綮之事可发一笑今春和景物明媚若给予诗料者然而清兴满怀自不可遏又何必在于风雪中耶漫成二绝以资谈柄','朱诚泳','明','信马东风鸟乱呼，
长桥烟柳晚模糊。
何当添个骑驴叟，
妆点诗家入画图。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_125','骊山之温泉即唐之华清宫也以路当孔道而浴者殆无虚日予奉诏赐浴而且遂游观之乐其感戴圣恩宜何如哉谨成一律以贻诸缙绅云','朱诚泳','明','小队从容晓出城，
喜蒙优诏浴华清。
灵源有性藏真火，
煖气溶春咽凤笙。
岂独纤埃随处尽，
直教沈疾顿然轻。
从今喜得身康泰，
万岁千秋感圣情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_126','予浴温泉而追忆玉环之丑禄儿之秽虽万古有不能涤也奈何三郎郎当入蜀幸赖汾阳诸公再造唐室及过马嵬犹不能忘情于一香囊而为之泣下于乎三郎真郎当哉慨叹之馀因成一律云','朱诚泳','明','华清宫里湛温泉，
沃雪揉香宠爱偏。
过市不惭同辇议，
诲淫曾费洗儿钱。
播迁自失神人主，
恢复多缘将相贤。
底事西归犹不悟，
香囊一睹一潸然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_127','予登骊山而想唐人宫室之盛惟馀故迹于淡烟残照之间而已且终南太华若相竞秀者是亦关中之胜槩也因作诗以写情云','朱诚泳','明','骊山名胜古来闻，
丘垤纷纷夐莫群。
老鹤瞑投孤嶂月，
蛰龙晴吐半岩云。
崔嵬直与终南并，
葱茜疑从太华分。
我欲凭高凌绝顶，
鲁戈须倩挽馀曛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_128','骊山怀古悼周幽也','朱诚泳','明','不见山头再举烽，
断霞遥映夕阳红。
申亡已兆东迁祸，
奚啻妖姬一笑中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_129','新丰盖象丰也汉高斯举其亦孝矣予经是地而闻鸡鸣犬吠之声俨有太平气象第未知太公当日果不思丰否亦不知新丰市上犹有斗酒濯足者乎因成一诗以写兴云','朱诚泳','明','人从生处偏为乐，
莫怪他乡恼太公。
眼底江山虽是汉，
梦中桑梓尚怜丰。
亭台风景元无异，
鸡犬人家也自同。
却笑狂夫双足垢，
瓦盆盛酒气如虹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_130','鸿门之会刘项之雌雄实决于此矣予过其地而想其大风之雄帐下之悲同一大梦也感而有作','朱诚泳','明','汉楚争雄此割疆，
貔貅对垒剧豺狼。
裂眦有勇称樊哙，
舞剑何人敌项庄。
醉脱金卮归太急，
怒撞玉斗恨偏长。
经过不用论群策，
蔓草寒烟几夕阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_131','过鸿沟','朱诚泳','明','龙争虎战欲相吞，
百二河山一剑分。
楚汉兴亡均是梦，
两抔寒土锁秋云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_132','过戏河有作','朱诚泳','明','流水无声伯业空，
人言列国此争雄。
至今春雨桃花落，
还似当年战血红。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_133','予行渭南道中爱其风物不觉成句殆亦有河山之助欤得二律','朱诚泳','明','倌人侵晓驾征骖，
伐鼓鸣金过渭南。
鸡犬顿疑尘世隔，
烟村真与画图堪。
溪流溅石飞晴雨，
山色当途落翠岚。
不待东风吹酒醒，
诗成一笑破馀酣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_134','予行渭南道中爱其风物不觉成句殆亦有河山之助欤得二律','朱诚泳','明','浴罢温泉过渭阳，
肩舆不厌道途长。
溪边老屋鸡声远，
树底新泥燕子忙。
旭日当头摇旆影，
东风随处送花香。
一游一豫皆天赐，
笑咏新诗贮锦囊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_135','予读唐史而每叹汾阳功满天地忠贯日星实后之尚父也予过华州敬谒祠下噫伟人不作而其堂堂大节殆与华岳争高矣因作长歌以寓景仰之私云','朱诚泳','明','李唐将相分忠佞，
功盖寰区谁最盛。
汾阳器宇真天人，
二十四考中书令。
万乘何如懒作家，
恣渠野鹿衔宫花。
佞臣进幸忠臣远，
从此乾坤如溃瓜。
渔阳一旦猪龙起，
若个捐躯报天子。
长安回首没烟尘，
花萼楼前闹如市。
唯公仗节勤王室，
沥血感天天亦泣。
军前免胄示诸酋，
诚信真能贯金石。
唐天几坠公重扶，
唐社将屋公重图。
招之不来麾不去，
心与博陆应同符。
八百年来祠有祝，
寒鸦故里栖乔木。
路人下马拜寝门，
不似崇韬多浪哭。
我来聊尔驻鸾旂，
心香一瓣兴遐思。
人臣徇国尽如此，
虽有颠隮非至危。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_136','莱公赵宋名臣也其孤忠大节盖炳炳于史册间予读前书素仰其人兹过华州一谒祠下因吊以诗云','朱诚泳','明','看山来华岳，
驻马寇公祠。
老蔓缠空木，
荒苔蚀断碑。
乾坤功业大，
史册姓名垂。
千古精诚在，
公安有竹枝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_137','宿华州','朱诚泳','明','历览河山喜胜游，
暂停笳鼓宿名州。
壮怀顿觉添诗思，
不省尘埃客里愁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_138','予经华山而仰观仙掌因笑图经之缪盖不足信偶成一律贻诸缙绅辞虽弗工欲求和也','朱诚泳','明','巨灵伸臂向洪崖，
云际分明一掌开。
捧出海天红日近，
挽将蓬岛列山来。
翠光闪烁萦朱草，
玉笋联翩绣绿苔。
隔断烟尘浑不到，
擎天功业陋三台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_139','予至华阴因忆唐人崔颢诗韵辄和一首大方家见之幸勿卢胡','朱诚泳','明','喜承优诏出咸京，
为爱三峰画不成。
红日捧来仙掌近，
白云飞尽佛头晴。
城边草色连天远，
树底河流入望平。
吟料满前撩逸兴，
应怜诗思自然成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_140','予入华山而爱其名胜恨不登落雁峰携谢朓惊人句搔首以问苍天耳玩之不足而因成一诗山灵有知其尚羡予之奇观也哉','朱诚泳','明','分茅忝秦土，
奉祀主西岳。
兹晨奉明诏，
温泉得疏瀹。
星言驾我车，
遥遥出城郭。
路迂经华阴，
寻幽有真乐。
山路阻且右，
我马劳四骆。
行行及山腹，
万仞如壁削。
霏岚湿我衣，
云根还旋斫。
群山若儿孙，
俛首谨然诺。
仙掌独凭虚，
亭亭入溟漠。
飞瀑自天泻，
灵苗皆大药。
或云巨灵氏，
山倾赖渠托。
如招物外人，
似引空中鹤。
我生有奇癖，
高情腾碧落。
欲上莲华峰，
遐观尽嵩洛。
飘然驭长风，
何须蹑芒蹻。
恨无惊人句，
搔首愧丘壑。
胜游惬素心，
兹行真不恶。
但恐鼾睡翁，
惊我驱山铎。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_141','予既宿华阴之行台明日有事于西岳灯下勉成三律以叙洁祭之诚谅金天主者有知其必鉴予至意也诗似相祀群僚尚希一和','朱诚泳','明','衣自温泉浴罢更，
拟将禋祀报神明。
盘供野簌无兼味，
天湛灵台一至诚。
跋涉敢辞长路杳，
澄渟应喜此心清。
虚堂待旦浑无寐，
饱听松风隔坐声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_142','予既宿华阴之行台明日有事于西岳灯下勉成三律以叙洁祭之诚谅金天主者有知其必鉴予至意也诗似相祀群僚尚希一和','朱诚泳','明','叠嶂凌虚紫翠堆，
閟宫千古面崔嵬。
一帘香雾晴犹合，
满地松云昼不开。
烜赫威灵昭肸蚃，
骈繁神贶■春雷。
凡庸竦息恩无极，
领得宜男福祉回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_143','予既宿华阴之行台明日有事于西岳灯下勉成三律以叙洁祭之诚谅金天主者有知其必鉴予至意也诗似相祀群僚尚希一和','朱诚泳','明','煇煌庭燎照深更，
髦士如云共一诚。
束帛瓣香崇简素，
朱弦玉管载和鸣。
礼严三献神威肃，
庙食千年飨祀精。
我愿明灵昭景贶，
更同民物遂生成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_144','予既祀华山将之蓝田之温泉复取道骊山从者告予曰此焚书坑也予叹虐政之狂奸斯之恶为之弹指者久之于乎始皇其坑儒耶儒其坑始皇耶后人必有能辩之者虽然六经之道炳如日星而阿房之宫骊山之墓盖已付楚人之一炬牧竖之遗烬矣太息之不足因作长歌以哀之','朱诚泳','明','我来刮目骊山下，
为爱骊山一驻马。
从臣指我焚书坑，
不觉风前清泪洒。
却忆当年秦始皇，
鱼肉六国真豺狼。
奸斯阿附助凶燄，
困敝黔首如牛羊。
虐政翻嫌人腹议，
偶语诗书者弃市。
秦人乃以死为安，
争敢编青作私史。
六经诸子尽输官，
章缝无复儒衣冠。
万卷千编归一炬，
守尉谁敢留馀残。
讵识诗书如日月，
日月遭秦真暂蚀。
孔壁还藏科斗文，
至今日月同无息。
祖龙死去楚人来，
秦宫三月飞烟埃。
空有骊山山下墓，
珠襦玉匣俱成灰。
远恨狂秦还一笑，
驱车又上蓝田道。
斜阳荆棘满荒陵，
行人惟吊旌儒庙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_145','予尝目摩诘辋川图爱其山水之秀以为绘者之巧而造化未必有此及自骊山迤𨓦入蓝田皆摩诘图中景也因又叹造化之巧而远非绘者所及矧其春日晴明而山光花气有足悦者因作春山晓行','朱诚泳','明','雨霁春山青插天，
悬厓飞瀑皆春泉。
朝来光景弄晴旭，
眼前物物皆芳妍。
肩舆随处踏芳草，
一路好山青未了。
天翁为我展诗图，
却笑无诗被山恼。
岚光滴滴东风晴，
林间好鸟相和鸣。
山花含露解迎我，
翻因花鸟关幽情。
红绿扶春诗满目，
却愧才非叉手速。
看山且进紫霞杯，
涤我尘埃三万斛。
西秦自昔隔东吴，
兹山能比吴山无。
凭谁唤起王摩诘，
为我写取春山图。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_146','予行蓝田道中而想念古人餐玉之法盖不可传矣因爱其山川风物遂有作云','朱诚泳','明','东华晴色动春朝，
谷口云开雪尽消。
四面好山青绕郭，
一溪流水绿平桥。
鸡鸣草店炊烟乱，
雉雊桑田土脉饶。
白石如粳闻可煮，
茂陵人去讵能招。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_147','予经辋川而爱其风物实诗中之画也所惜者摩诘不作徒见黄鹂之啭于夏木白鹭之飞于水田而已缅想昔人不觉有述噫嘻摩诘其有知乎哉','朱诚泳','明','山路萦回古木疏，
辋川风景小蓬壶。
诗从初调能窥雅，
画到无声不用图。
远岸轻烟笼细柳，
野田流水长新蒲。
怀人几度空惆怅，
不见骊龙照乘珠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_148','蓝田县之东有山高入云表甚秀拔予问从臣此山奚名有知者对曰此李唐仙人王顺登仙山因以一绝纪之','朱诚泳','明','蓝田咫尺接商颜，
谁是丹成出世间。
老鹤无声人已远，
白云空自锁空山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_149','向读三秦记闻周平王东迁见白鹿于此原以是得名予自辋川经此漫思往事而姑识之以诗','朱诚泳','明','周辙东迁叹黍离，
巍然王业遽陵迟。
千年白鹿空原外，
争似呦呦在囿时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_150','予既浴太白之凤泉再浴临潼之温汤又浴石门之温泉仰承明诏盖三浴矣圣天子之优眷如此予忝为宗臣亦将何以报称于万一哉感激之馀谨以一诗识之','朱诚泳','明','我生遘微恙，
足弱勇不前。
人言有神水，
可以一洗𤏄。
封章达天子，
优诏容二年。
春和时雨霁，
驱车历原田。
初经太白山，
灵源名凤泉。
沸水若汤煮，
遥看起炎烟。
顺途骊山下，
莲汤尚依然。
宁非至阳精，
日夜劳烹煎。
回车石门道，
温流亦涓涓。
应疑一脉通，
地轴相钩连。
初浴觉身轻，
再浴忻体便。
三浴莹于玉，
洋洋和气宣。
衣裳易鲜洁，
飘飘若飞仙。
非惟尘垢去，
果见沈疴痊。
维藩愧无似，
乃承天所怜。
周旋如所愿，
微恙幸已蠲。
感恩何以报，
圣寿祈同天。
宗臣老西土，
永守秦山川。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_151','予宿石门清不能寐其所闻者野雉之鸣涧水之声而已因成一绝','朱诚泳','明','空翠侵人睡不成，
夜深惟有野鸡鸣。
翻怜车马明朝发，
坐听潺潺涧水声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_152','马鞍山之普光寺有池曰仰天池实予始祖悯王奉大雄氏处也允为诸刹首称昔有老宿性空者住其间予尝贻之以诗而一时之名士皆属和焉以今计之盖二十年矣兹予重游于此而性空已久入寂同吟者亦多星散因感于中复为一诗以贻住持者云','朱诚泳','明','不到禅关二十年，
山中风景尚依然。
钟鱼有客投金地，
香火何人社白莲。
学士再留腰下玉，
痴僧争乞钵中钱。
独怜惠远今何在，
一塔亭亭夕照边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_153','予既游天池行半舍登所谓五台山者爱其秀丽口占一绝','朱诚泳','明','攀援石磴上仙台，
万壑晴岚午未开。
千尺长松云一片，
半空惟有鹤飞来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_154','予既登五台日已暮矣遂憩山足之古寺野趣撩人灯前不寐遂成七言古诗一首','朱诚泳','明','我昔驰书闻九天，
许我澡浴停温泉。
斜阳缇骑转山径，
聊从金地投金仙。
我居宫掖惟怡素，
忠慎敢矜千乘富。
孳孳好善慕前王，
曾读前书谙世故。
斗鸡走马非吾事，
涉水登山谐夙志。
欲试平生仁智心，
只恐金仙未为是。
坐久山僧争献颂，
钟磬齐鸣灯火共。
雕盘进食拥袈裟，
却讶天厨真有供。
夜深导我石室眠，
梅花纸帐何萧然。
一尘不扰起灵悟，
恍对文殊与普贤。
喜凭法水𤏄尘垢，
打破虚空月穿牗。
倚屏无睡待天明，
忽听一声狮子吼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_155','明日早发迤𨓦山行其千态万状怪怪奇奇诚有如退之南山诗之所云者予素有山癖每涉于目甚悦于心不暇作长诗姑成七言四绝云','朱诚泳','明','宿雨晴来罨画张，
重重螺髻拥穹苍。
数声啼鸟桃花落，
一路东风涧水香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_156','明日早发迤𨓦山行其千态万状怪怪奇奇诚有如退之南山诗之所云者予素有山癖每涉于目甚悦于心不暇作长诗姑成七言四绝云','朱诚泳','明','泼眼青螺宿雨晴，
乘閒连日作山行。
何须对酒听丝竹，
满耳松声杂涧声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_157','明日早发迤𨓦山行其千态万状怪怪奇奇诚有如退之南山诗之所云者予素有山癖每涉于目甚悦于心不暇作长诗姑成七言四绝云','朱诚泳','明','万木阴阴石径斜，
乱山深处有人家。
春风满耳多啼鸟，
涧水流来带落花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_158','明日早发迤𨓦山行其千态万状怪怪奇奇诚有如退之南山诗之所云者予素有山癖每涉于目甚悦于心不暇作长诗姑成七言四绝云','朱诚泳','明','满目烟云散午风，
青山万仞倚晴空。
欲登绝顶聊舒啸，
鸟道巉岩一线通。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_159','五台之西有山曰翠微太宗避暑处也旧有离宫二曰翠微曰永庆遗趾尚存今废为寺因成一律','朱诚泳','明','翠微深处翠微宫，
避暑当年说太宗。
吊古不须增感慨，
凭高聊复得从容。
千章古木苍烟合，
数尺残碑碧藓封。
独喜满前吟兴好，
参天万朵玉芙蓉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_160','予登翠微爱其秀拔纵目久之有寺僧进曰山之绝顶自南而望其千岩万壑虽善绘者莫尽其妙予因命肩舆直造其巅一视果如僧之所言清兴溢发即成七言古诗一首','朱诚泳','明','翠微雨过芙蓉湿，
我兴悠然思适适。
买山直欲捐万金，
况是生平有诗癖。
帖帖肩舆到上头，
凭高四顾凉飕飕。
终南太白拥晴翠，
渭源一线沿川流。
忆昔唐皇来避热，
万户千门巢嵽嵲。
有时云雾失炎精，
六月寒风搅飞雪。
吾驾兹晨为一停，
等閒呵护烦山灵。
分明坐我古图画，
何须点染呼丹青。
移床更入晴岚里，
为爱松声忘坐起。
自是吾家道气浓，
涤尽胸中几渣滓。
坐久欲归归未得，
忽讶片云头上黑。
知是山灵催我诗，
一笑留题许镌刻。
来来车马更迟迟，
好山一路还相随。
从行宾从拥矛槊，
能无和我登山诗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_161','翠微之西有山之小者其拱秀若屏障然有沣水出于其间固可爱玩且有寺曰丰德亦可憩也因成一绝','朱诚泳','明','沣水桥西小径通，
好山如画倚晴空。
禅关欲扣知何处，
隐隐钟声紫翠中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_162','丰德寺之西有圭峰焉圭峰之下乃姚秦之逍遥园也实鸠摩罗什之道场其寺旧极宏敞今久废惟罗什之塔在焉俗谓之草堂寺予留一宿于此因贻一律','朱诚泳','明','忆昔神僧入杳冥，
可怜龙象总彫零。
空阶鸟迹和尘乱，
坏壁蜗涎过雨腥。
石塔尚传藏舍利，
宝函犹自贮残经。
相看独有圭峰在，
还似当年佛首青。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_163','予自草堂将归过古之樊川亦有所感而不能已于言也','朱诚泳','明','斗城南畔杜陵边，
旧是将军食邑田。
屠狗亦匡刘季业，
牝鸡谁道吕媭贤。
当年壮志今安在，
此日英风尚凛然。
禾黍高低残照里，
路人犹指是樊川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_164','自樊川而来经曲江池因忆唐人之春游者莫盛于此物换时移而今之所见第参差烟树而已浩叹之馀继之以诗','朱诚泳','明','曲江池畔黍离离，
肠断慈恩寺里诗。
谢馆夕阳归昨梦，
琼宫秋草祗荒基。
锦筵待士乘春早，
翠袖留人觉夜迟。
细柳新蒲俱不见，
风光又减少陵时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_165','自曲江而来有浮屠耸立于霄汉间者则雁塔也寺曰慈恩尚仍唐扁但钟鱼之盛车马之游则相去远矣漫成一诗聊用吊古云耳','朱诚泳','明','阳鸟何年此瘗形，
浮屠谁搆尚亭亭。
上林无复传苏扎，
萧寺犹惊语梵铃。
势压澄江蟠地轴，
影移残照碍空冥。
一从韦肇题名后，
人物依稀世几经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_166','近雁塔有坡二曰胭脂曰翡翠其春游之盛盖极于开元天宝间矣观其命名之意则当时游冶之乐犹有可想见者因成二律情见乎辞','朱诚泳','明','宣平坊里旧名坡，
故老相传事不讹。
非有猩红将地染，
直看茜水带泥和。
芙蓉争艳凝肌肉，
兰麝吹香入绮罗。
车马去来歌舞散，
东风开遍野花多。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_167','近雁塔有坡二曰胭脂曰翡翠其春游之盛盖极于开元天宝间矣观其命名之意则当时游冶之乐犹有可想见者因成二律情见乎辞','朱诚泳','明','虾蟆陵下曲江边，
传道开元乐事偏。
金缕罗襦相斗靡，
粉容花貌各争妍。
雏莺历历歌喉细，
飞燕盈盈舞袖翩。
今日凄凉成一梦，
淡烟衰草接平川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_168','近郭有玄都观盖禹锡看花处也种桃道士既不可见而兔葵燕麦今尚复然予山行之趣悉见于诗兹将入城而犹有玄都之兴散人好奇亦自可笑诗亦不可不留也','朱诚泳','明','杰阁层楼旧已颓，
海桑变幻几千回。
桃花不见空葵麦，
瓦砾无多只草莱。
尘面至今还自拂，
春光前度为谁栽。
不须立马频伤感，
老屋逃亡更可哀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_169','八声甘州 自集“春归”诗意写怀','熊东遨','当代','问隔江门户为谁开？
雷神令新颁。
看春痕一线，
风邀雨约，
柳上初还。
莺笋探头调舌，
浑似小灵顽。
真个无愁也，
除却乡关。
日日垆边沽醉，
任梅花笑我，
岁月都闲。
算而今只有，
童梦不曾删。
最相知林间鸟雀，
道先生心已属云山。
鸡声里俨然留得，
酒后朱颜。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_170','水调歌头 暮春感事','熊东遨','当代','风雨一番骤，
莫说更能消。
落红犹记当日，
万点带愁飘。
紫陌斜阳西去，
更倩何人呵护？
天意误儿曹。
从此心期绝，
无语对江潮。
掩柴门，
参古局，
诵离骚。
流光磨尽棱骨，
枉自立中宵。
扫净长街残叶，
捧出晴空新月，
眉样已重描。
只有双归燕，
还认旧时巢。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_171','水调歌头 车过黄河寄石城诗友','熊东遨','当代','长笛一声起，
有客渡河梁。
故人鸡黍新具，
不待菊花黄。
邀约春秋佳会，
领略太平滋味，
忘却鬓边霜。
自笑村夫子，
只为酒杯忙。
览江山，
跨世纪，
证沧桑。
此生多少奇遇，
回首也寻常。
闻道孤山雪后，
月与梅花俱瘦，
应是累情商。
我亦梅花似，
开向石家庄。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_172','满江红 醉归和新河四十初度韵','熊东遨','当代','饮罢归来，
乘兴把楚江重涉。
襟袖上，
三湘零雨，
九嶷残雪。
白也无诗酬李盛，
红何有意怜张拙？
直疑他天上巧因缘，
由人设。
聋不听，
鹃啼血；
盲不见，
星围月。
算此生差幸，
非圆非缺。
绊世已知难作隐，
对空未便轻书咄。
看冲霄一鹄起长安，
成孤绝。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_173','满江红 内子生日再用前韵','熊东遨','当代','昨夜双星，
共河汉沧波飞涉。
是谁遣疏梅照影，
一枝先雪？
织锦深怜机杼巧，
吹芦自笑声情拙。
到中流犹未白东方，
杯重设。
曾沸过，
心头血；
曾挽过，
云边月。
守三生何计，
一时圆缺？
天外偶蒙寒雨顾，
林间乐受清莺咄。
细思量都是善因缘，
难回绝。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_174','浣溪纱 守梅','熊东遨','当代','守定春前一段香，
新芽看剪几分长。
断桥西岸雪村旁。
经片刻风声动竹，
得些微月影横窗。
共谁呼酒溯流光？',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_175','鹧鸪天','熊东遨','当代','一色江天淡入秋，
乱峰三五出云头。
古松苍郁新松翠，
近水喧腾远水悠。
篱下菊，
酒边鸥，
心期莫问几时休。
无边气象争供眼，
认得清风是旧游。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_176','鹧鸪天 和庶之','熊东遨','当代','一瓮春醪醉到秋，
松边乍醒手扶头。
丛筠侧侍长身立，
曲涧环吟小调悠。
亲及鹤，
友于鸥，
有时相聚有时休。
云峰雪窟图成卷，
来日偕君作卧游。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_177','鹧鸪天 电视连续剧《大明王朝》观后和长河','熊东遨','当代','镇日蒲团坐不移，
天风海雨任何之。
涧藏深壑留清白，
经到残篇得悟思。
神未死，
庙能持，
自多人物写青词。
笑看泾渭双流合，
分享和谐又一时。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_178','曲游春 平安夜西湖无月用草窗韵','熊东遨','当代','未尽相思债，
奈者番重被，
烟雨罗织。
偶误前期，
便羞含半面，
忍藏云隙？
试着疏帘隔。
怕听见恼人渔笛。
更怕他雪后孤山，
梅蕊暗分颜色。
远陌，
湖灯摇碧。
算成串霜珠，
犹受风勒。
不肯窥人，
是瑶池浴罢，
暂笼香幂？
桂下曾初食。
有百味生于清寂。
纵万年一个轮回，
也须守得。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_179','忆旧游 丁亥冬三探西溪偕诸子谒两浙词人祠新河命和樊榭','熊东遨','当代','是神来之笔，
一抹林烟，
画出山眉。
又续前游意，
听残芦吹雪，
响落霜埼。
伊谁得似渔父，
镇日理长丝？
任波上浮金，
人间造像，
不动心扉。
生机，
待重觅，
算泰半因禅，
少半因诗。
共向祠坛拜，
借云根净水，
细浣初衣。
何当更约西子，
月殿酌清晖。
只醉眼宜留，
遥空看鹤驮梦归。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_180','鹧鸪天 戊子岁首和长河连珠','熊东遨','当代','串串烟花打扮春，
丛篁静绾半溪云。
两三点雨村前过，
一二分愁别后新。
泉石意，
雪泥痕，
算来多是不如人。
偶然回首尘封里，
留得当年梦尚温。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_181','鹧鸪天 上元过六榕寺再用前韵','熊东遨','当代','一朵苍苔点破春，
青衫待补割凉云。
可能近寺蟾光好，
渐觉穿林鸟语新。
追雨脚，
测溪痕，
百年消涨问何人？
山僧醉倒榕阴下，
酒是东坡去后温。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_182','临江仙 元韵答秋风见怀','熊东遨','当代','一角成园居自好，
清风夜送林涛。
酒边花影月边箫。
偶来山雨骤，
涨不动心潮。
圣手争围天下局，
拿云意气堪豪。
老猿无谱乱支招。
孤舟行海上，
彼岸望何遥。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_183','鹧鸪天','熊东遨','当代','未解维摩色是空，
漫从镜底觅真容。
琴挑可见回眸影？
棒喝都成过耳风。
星捧月，
竹围松，
一时缘会古今同。
鸿飞不限天南北，
认得来踪即去踪。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_184','东风第一枝 情人节赋水仙用梅溪韵','熊东遨','当代','雪借天山，
波分洛水，
南园初识风土。
未将素眼窥人，
莫放清霜入户。
蜂媒蝶使，
飞不到画堂深处。
听竹阴一曲禽弦，
撩动乱愁千缕。
多少事欲题无句；
多少梦欲寻无绪。
闲常都说神仙，
若个真成眷侣？
西湖怜我，
早许着宜晴宜雨。
问几时得与荷邻，
相伴钓舟归去？',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_185','清平乐','熊东遨','当代','不须呵护，
都是江山主。
巧借东风谁肯误？
忘却自家来处。
妆春万种柔情，
瞻秋一步行程。
占断无边光景，
何曾想过凋零。',NULL,'','{"preface": "戊子新春，羊城雕塑园有樱花节，海鸥、步云、玉平诸师召赏之。其花系从东岛移截而来，无本之木，竟能艳放，予初以为奇。玉平师观摩良久，忽曰：“根部必有激素包助放。”予始悟。时中大诗词研习社诸子在侧，莫不解惑焉。嗟夫。外力之作用一至如斯，世事不可语者夥矣。归成是阕，聊充社课，非敢讽樱花也。", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_186','鹧鸪天','熊东遨','当代','曾见长林一抹青，
晓风摇曳露珠莹。
寒霜莫笑颅先雪，
好雨应知血未冰。
将旧梦，
语孤星，
众神无趣不须听。
天倾海沸何关碍？
点亮生涯有佛灯。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_187','浣溪纱 有思','熊东遨','当代','相忆相忘两未能，
登楼但说月凄清。
雨肥风折不关情。
十九年花消受血，
二三更梦感知兵。
有时麻木到心灵。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_188','水调歌头 戊子重九庐山白鹿洞书院写怀','熊东遨','当代','千里一钩月，
相伴赴浔阳。
客怀交付烟水，
莫笑鬓飞霜。
待约归田陶令，
同逞登高清兴，
无酒亦何妨？
但恐青庐外，
零雁不成行。
和江声，
分岳色，
赚秋光。
漫将心绪收拾，
来拜读书堂。
人道庭前樟桂，
曾记当时缘会，
可解为诗忙？
渔笛沧浪起，
容与协宫商。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_189','贺新郎 友人以感事长调见示元韵答之','熊东遨','当代','守着青山老，
倚斜阳风回一线，
鸟鸣蝉噪。
聆此天音谁得似？
况在白云怀抱。
醒旧梦原无迟早。
莫把尘窗长封闭，
对苍崖试共松猿啸。
殊不信，
应声悄。
交情怕忆当初好。
痛而今埋琴冢上，
剩残烟袅。
偏是游丝焚难断，
总被他人猜到。
更休说色空俱了。
我本凡胎多俗骨，
每违心听谱清平调。
新格局，
未曾料。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_190','翠圆枝 己丑四月朔西湖漫步同研究院诸子','熊东遨','当代','云气涨湖亭，
旧雨都遵新约。
认取紫筠根上，
有春痕留着。
晚风溜过断桥西，
未把谁抛却。
唤起青荷同舞，
是当时承诺。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_191','八声甘州 夏日偕关东诸子游磐石牧野亭','熊东遨','当代','占松辽一角好江山，
元声四边来。
似天公布局，
星围月点，
妙味须猜。
日夕林蛙草蛐，
撩动旧情怀。
便是神仙顾，
不做安排。
邀得青衫红袖，
向亭前数雨，
真个悠哉。
纵稼轩未到，
醉眼亦宜开。
看长空鹏飞鹤举，
趁明时争展拨云才。
清阴下天容我辈，
坐赏和谐。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_192','鹧鸪天 秋日黄山写意','熊东遨','当代','梦过千遭笔未花，
试邀松侣酌流霞。
偶看箕伯无形手，
撩起佳人半面纱。
知我者，
是谁耶？
且将秋绪敛些些。
奇峰亦在闲中老，
天地风光信有涯。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_193','蝶恋花 重阳后六日初上黄山和蛰兄九日登高韵','熊东遨','当代','坐对秋屏情亦好。
抱月登高趣向天公讨。
壁上流云欺客老，
由它补阙何须扫。
昨是今非休更道。
便具陶腰也向山倾倒。
始信峰前同一笑，
清风不许人生恼。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_194','鹧鸪天 中秋夜机上对月','熊东遨','当代','占得天风一步先，
小银河里试飞船。
神游远古洪荒外，
诗钓芦花浅水边。
将我意，
语坡仙：
今宵莫问是何年。
孤帆直赴蟾宫约，
圆缺阴晴见两全。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_195','临江仙 亲水走廊谒陈连升铜像','熊东遨','当代','一自英雄归去后，
谁持铁笛横吹？
诸峰列阵水成围。
当年鏖战影，
犹向梦中回。
终见九州开画境，
清风莫笑无为。
太平滋味浅深杯。
欲锄江畔月，
补种病前梅。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_196','鹧鸪天 晨起磨子沟散步','熊东遨','当代','一曲鸣溪尚未穷，
忽看云浪涨前峰。
是行是坐俱宜我，
为雨为晴且任侬。
千百步，
两三松，
有时岚影有时风。
山深独许春无赖，
管到林花四月红。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_197','鹧鸪天','熊东遨','当代','入眼香螺一点青，
漫从梳洗认湘灵。
黄花已谢三千本，
白鸟还余四五声。
云影散，
雪涛惊，
巨鱼腾绰不胜情。
孤舟自泊芦湾里，
静看银蟾缓缓生。',NULL,'','{"preface": "舟次洞庭，君山在望。忆去岁登黄山，庶之曾拈此调赋迎客松一阕见示，倏忽经年，良深感念。因步元玉奉寄", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_198','浣溪纱 土家山寨即事','熊东遨','当代','翠玉丛中笑语飞，
东邻女伴采桑回。
插花背篓出江隈。
忙煞寨头诸小子，
争将木叶望空吹。
不知心底各藏谁。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_199','西江月 蒲花暗河泛舟','熊东遨','当代','仿佛初开混沌，
朦胧未识深遥。
诸天影像一时消，
只剩桨声幽窈。
世隔何来人语？
光生忽现星桥。
小银河上雨潇潇，
肯把从前忘了？',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_200','清平乐 庚寅夏游黔江“小南海”“海”因1856年地震湮塞而成','熊东遨','当代','这回寻着，
隐在西南角。
浴石涵云清一勺，
睡过百年才觉。
可怜些许情怀，
无端又被人猜。
好是雨来风去，
不须谁做安排。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_201','生查子 中秋夜偕诸子渤海湾看月','熊东遨','当代','夜色薄如纱，
夜气凉如雪。
偶与白鸥盟，
共醉清秋节。
家在海之南，
人在天之北。
对此眼中圆，
翻觉心头缺。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_202','浣溪纱 新河属题垂虹感旧图','熊东遨','当代','仿佛溪桥见洛神，
一分烟水二分痕。
无风无雨过江村。
蓦忆初弓今夜月，
曾经销尽古人魂。
可能因梦及前身。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_203','鹧鸪天 元玉奉和蛰堪兄半梦填词图','熊东遨','当代','闲剪山云补旧图，
僻居堪慰老怀孤。
寒溪绕郭声来枕，
素月分辉影在庐。
从乐事，
或须吾，
露团清赏碧荷珠。
风光自启心窗得，
管甚人间有也无？',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_204','生查子 重九夜登高寄友','熊东遨','当代','同此履霜天，
同此思亲夜。
梦到未生时，
身在无何野。
不见后来人，
不见先行者。
独自仰虚空，
涕下何由写？',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_205','浣溪纱 燕婷入川访淑萍有词纪胜值予回乡小住感念良多元韵和寄','熊东遨','当代','小卧晴窗雪意深，
梦舟仿佛近山阴。
荒鸡无赖一声侵。
风色不饶秋日鬓，
月华聊慰故园心。
少年滋味怕重寻。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_206','金缕曲 磻溪姜太公钓鱼台','熊东遨','当代','一路溪声绕。
进山来凉生暑敛，
雨迟风悄。
未识何人研水墨，
画出云山初稿。
更添个蓑衣渔佬。
稳坐石矶三千载，
自无言守到崖松老。
直钩在，
拙胜巧。
浪猜怕惹先生笑。
算古今烟波钓客，
不知多少。
浅钓浮名深钓利，
湖海江河池沼。
犹未计旁观意钓。
大小方圆同一梦，
试扪心几个真醒了？
林影下，
有归鸟。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_207','鹧鸪天 春归翌日作','熊东遨','当代','诉尽离怀雨半溪，
等闲误了饯春期。
纵教梅子能私我，
毕竟榴花不似伊。
随白羽，
数红衣，
更无一个与心宜。
眼波眉影思量遍，
恐在天涯独自啼。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_208','临江仙 辛卯夏夜烦霜约赋《娇娜》','熊东遨','当代','记得空林曾见汝，
当时月在瑶阶。
一声娇笑影先来。
纯情珠乍吐，
稚面蕊初开。
恩信识当生死际，
浑然忘却形骸。
素襟只与小青偕。
所怀元自洁，
尽管让人猜。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_209','生查子 同孤云馆主观李胜素演《游湖》','熊东遨','当代','何处小灵仙，
补得湖光足？
一霎白云飞，
一霎青烟束。
风是月同盟，
梦是心归宿。
不逐水之湄，
便逐山之麓。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_210','纪辽东·应养根斋主约，偕穹庐诗会诸君千里驱车畅游呼伦贝尔大草原','熊东遨','当代','江河飞白草飞青，
联车载酒行。
人在画图诗在梦，
若个肯先醒？
偶添新雨两三程，
珠光触眼生。
不辨穹庐何处醉，
所记只曾经。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_211','鹧鸪天','熊东遨','当代','引出秋光满苑诗，
露葵霜菊恰宜时。
清余半璧尤堪惜，
碎泼凉珠竟未知。
天不管，
自成痴，
恍同仙侣坐瑶池。
碧桃开过青春界，
一任西风笑丑枝。',NULL,'','{"preface": "辛卯中秋后三日，予客京华，半斋主人招饮花家怡园，二三子与焉。时云月一天，凉雨间至，斗韵飞觞，不知今夕何夕。因取稼轩“知我者，二三子”句依序联吟，予年长，分韵得“知”字。", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_212','鹧鸪天 奉题《半斋填词图》','熊东遨','当代','自道生涯半属诗，
晓莺声里梦醒时。
闲分石乳研新墨，
细写云涛报故知。
身渐老，
意犹痴，
每携霜电过雷池。
荷花秋水三千顷，
中有凌波第一枝。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_213','八声甘州','熊东遨','当代','借当空压轴一轮圆，
殷殷谢良朋。
算人间滋味，
天烹海酿，
都逊乡情。
漫说童年去远，
有梦系风筝。
还笑灯前我，
须发飘零。
料得清流未改，
问渔歌帆影，
可记曾经？
看岩阿滩曲，
多少浪花腾。
向沧溟非开非谢，
证因缘朵朵是初生。
深杯里，
照青苍鬓，
相惜惺惺。',NULL,'','{"preface": "辛卯腊月既望，予因事过长沙。乡贤戴先生毅明、汤女史素兰伉俪招饮于“同升湖山庄”。陈公和世作陪，哲宏、樵哥、迎辉三学棣与俱。乡音醴酒，同忆清沩，不觉唏嘘者再。", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_214','临江仙 南园望雪','熊东遨','当代','守到年关犹未见，
相思叠若层冰。
溪山不语自多情。
竹云飞片片，
泉石响丁丁。
琼影醉来醒复渺，
何曾一刻消停。
小梅当户月当庭。
写形鸿迹远，
踏意梦痕轻。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_215','鹧鸪天 马湖泛舟分韵得帘字蛰堪命作异调当时未竟夜梦足之','熊东遨','当代','差与东坡趣味兼，
一舟一水一银蟾。
清光任我收壶底，
夜语听人弄舌尖。
神骏杳，
老龙潜，
紫霄宫近许同瞻。
天公妙处多闲笔，
云在青山雨在帘。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_216','鹧鸪天 壬辰夏偕诸子访宜州其地山川秀媚好峰随处多不知名','熊东遨','当代','只有深闺养得成，
百端娇媚是天生。
穿岩水响泠泠白，
掠树云飞淡淡青。
人未识，
且休惊，
木灵山鬼本无名。
泰嵩早失相看意，
自向西南认小星。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_217','清平乐','熊东遨','当代','域中同好，
相约将公扰。
八百年光流过了，
依旧青山不老。
今朝座设西园，
顶香遥拜高轩。
南北两厢呼应：
一声杯汝来前。',NULL,'','{"preface": "稼轩生日作。时新河在北京，燕婷在岭南，而予在西陲十万大山中。遂央先哲为东，相约倾樽，四方同庆", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_218','江神子 向晚芙蓉楼独坐时值壬辰大端午','熊东遨','当代','旧愁都着玉壶收。
甚来由，
又登楼？
醉里推窗，
俯看大江流。
要与龙标争一席，
千载下，
有人不？
平生事业剩清游。
远寻牛，
近呼鸥。
水洞云窝，
那复计春秋。
诗梦恰宜今夜续，
杯在手，
月当头。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_219','鹧鸪天 内子生日用韵和祝','熊东遨','当代','何用春风沐汝身，
前生元是玉霄神。
清香到枕缘非浅，
素影横窗自不群。
泉梦石，
树留云，
海天同福亦同恩。
今宵补个心头印，
百世相寻认此痕。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_220','卜算子','熊东遨','当代','小梦草生珠，
大梦潮吞月。
大小由之到佛前，
无梦存何说？
不问道谁传，
不问鲸谁掣。
只共边缘几个人，
来踏杨花雪。',NULL,'','{"preface": "癸巳春分后三日，蛰堪兄南下羊城，小聚海幢寺。以玉田“记玉关踏雪事清游”句分韵得雪。", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_221','清平乐 倚云兄为燕婷制《小梅窗填词图》附题寄意','熊东遨','当代','霜禽初歇，
帘外飞香雪。
影入流溪声到月，
天地宫商漫协。
庭梅未改真淳，
劳君写出元神。
笑我终朝坐对，
清芳不与人分。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_222','浣溪纱 癸巳花朝后三日，同长虹雨中看西湖。经钱公明锵当年荐茗处，风物依然，斯人已邈，思之戚然','熊东遨','当代','湖上重来忆旧观，
百花添得几分颜？
茗烟依约起前湾。
十里新痕堤畔水，
一帘微影雨中山。
斯人去后尽阑珊。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_223','水调歌头 癸巳二月望与诸子泛舟玉湖蛰堪兄约填此调','熊东遨','当代','老至心何着？
只在水云间。
露花泥草风竹，
定与我相关。
闻道玉湖摇碧，
正要先生舟楫，
岂不动欢颜。
况有烟霞侣，
诗酒共盘桓。
雨三分，
人几个，
水千湾。
歌吟尊俎都罢，
四面看青山。
明月未成邀约，
小勺先分清活，
体味浅深寒。
斯世一何幸，
得似鹭鸥闲。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_224','蝶恋花 春暮松亭小憩','熊东遨','当代','蝶影蜗痕关际会。
雨去风来争逐春之尾。
秀尽残英红到水，
东君惯是无追悔。
一角湖山容小睡。
闻道清时梦也成人美。
不管明朝晴与晦，
绳床先试其中味。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_225','定风波 曲江对雨','熊东遨','当代','瓦响尘腾骤未防，
一瓢飞泼过沧江。
天意有时恩及我，
休躲。
试招荷侣说新凉。
翻墨周遭遮欲断，
何憾？
伊人自在水之阳。
多少云山真面目，
猜着。
不须披露不须藏。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_226','水龙吟','熊东遨','当代','忆中千斛灵珠，
九霄泼下光无际。
天风拂动，
素帘飘捲，
乐声徐起。
不厌相看，
情怀两许，
一觞同醉。
叹十年睽隔，
者番重见，
飞扬意，
俱收矣。
多少江湖旧事，
问颅边雪霜能记？
崎岖世道，
冰烧火浣，
欲行还止。
莫若随伊，
升腾转化，
非终非始。
纵他生未约，
偶成缘会，
信依然是。',NULL,'','{"preface": "癸巳大暑，予应越中诸子之邀，重访雁荡大龙湫，十年不见，一帘飞瀑只剩霏微，感慨系之，赋此以志。", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_227','西江月 偕智妙祥华其良圣栋有韬并内子游南雁荡','熊东遨','当代','旅雁去来无定，
凭谁管领风骚？
青山不语水滔滔，
容得一行人早。
远足正逢佳日，
晚炊争荐溪毛。
夕阳红过小河桥，
人与山都醉了。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_228','行香子 夏日楠溪江纪游','熊东遨','当代','远浦斜曛，
晚市鲜鳞。
近西湾望里渔村。
鹭鸥来去，
碧水盈门。
正柳摇风，
荷待露，
石生云。
一壶清茗，
几个闲人。
任星槎荡入烟津。
蒹葭旧曲，
未忍重闻。
怕有情天，
无准梦，
太伤神。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_229','念奴娇 秋日偕中镇社友登雁门关斗全兄命填是阕效萨翁步东坡韵','熊东遨','当代','险关高峙，
自明妃去后，
尚余何物？
多少风云都付与，
石偶泥胎华壁。
大漠烟寒，
长河草白，
曾见漫天雪。
兵尘劫火，
有时成就英杰。
此日携手登临，
凭虚四望，
未免童心发。
指点江山今到古，
太息涛生林灭。
笔底交锋，
枰前演义，
省个冲冠发。
秋声渐紧，
醉醒归问霜月。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_230','清平乐 小年夜庶之出关赋此寄慰','熊东遨','当代','回家就好，
不必生烦恼。
木未成阴风要扫，
病叶由他去了。
残冬纵有深寒，
可能阻得春还？
一夕羲轮驰过，
依然绿水青山。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_231','沁园春','熊东遨','当代','海角天涯，
共此晴霄，
凉玉一枚。
正清光遍洒，
古人曾照；
流风又起，
今我何为？
云色移松，
泉声动竹，
瘦影横窗定是梅。
箫韶乐，
赖群贤合手，
留住些微。
绝尘遥去乌骓，
浑未信丝缰勒得回。
看柔根裂石，
应知草长；
孤舟渡远，
自有潮推。
不用勾描，
毋须探问，
春在黄莺翅上飞。
沉吟罢，
约良朋三五，
来听惊雷。',NULL,'','{"preface": "甲午上元陈田雅集，分韵得“飞”字。时各地有诗达而人未及者，用此并寄。", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_232','西江月 浏河茗话同明汉','熊东遨','当代','杯盏清时有味，
文章老去何妨。
一襟尘色满头霜，
也是人间气象。
野草自添生意，
流云不碍晴窗。
翠圆枝上柳莺黄，
重把青春唱响。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_233','虞美人 夏日桂平西山写意','熊东遨','当代','非醒非醉松边卧，
只是闲些个。
清风一拂梦帘开，
四面蝉声涌入画中来。
相看妩媚如初好，
留共他年老。
同车载去也无由，
但取精魂供养在心头。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_234','鹧鸪天 乙未春分后一日小石源诗会偕诸子登武功山','熊东遨','当代','仿佛重回太古前，
足边云海顶头天。
三分月见长江尾，
一半春留小石源。
临上界，
晤飞仙，
今朝不用梦成全。
同行只少东坡老，
错过因缘九百年。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_235','生查子 春暮王子山小游纪意用“海”字','熊东遨','当代','自笑野心多，
垂老犹难改。
一半属青山，
一半留沧海。
好是昔人云：
花落春仍在。
秋菊不当时，
梦向东篱采。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_236','清平乐 夏夜偕诸子玉潭公园漫步中途暴雨骤至小令记之','熊东遨','当代','此情同有，
乡味浓于酒。
一掬凉泉初近口，
眉月依稀在手。
风蝉漏夜鸣枝，
无非笑我归迟。
争及骤来山雨，
浇头只管催诗。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_237','浣溪纱 故园江畔小饮步燕婷夏日同些雩茗话韵','熊东遨','当代','渚岸斜开一径幽，
翠阴深处泊行舟。
杏帘挑出古村头。
独许归来成薄醉，
并非容易说长留。
恼人依旧是乡愁。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_238','浣溪纱 夜梦叠前韵','熊东遨','当代','一枕天风渐入幽，
小银河里漫飞舟。
溯洄应已近源头。
来世未知非未想，
帝乡能到不能留。
芷兰无语替人愁。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_239','浣溪纱 重访桃花源','熊东遨','当代','记得山前小洞幽，
重来不用问渔舟。
一生能历几回头？
高士已随星隐没，
桃花只合水收留。
有时沉痛胜于愁。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_240','浣溪纱 二沙岛独步寻幽有作','熊东遨','当代','夏日烟光处处幽，
江行宜步亦宜舟。
开樽未必要由头。
湘月九重凭想望，
荔枝三百足淹留。
而今不缺是清愁。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_241','清平乐 倚梅小筑初成赋贺用有字','熊东遨','当代','素心相守，
此意梅花有。
一树临溪双影瘦，
恰在月圆时候。
阁边丛竹新栽，
成阴不用多猜。
待到松高及屋，
听鹂抱个琴来。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_242','鹧鸪天 夏日偕燕婷南沙访些雩','熊东遨','当代','只合词人住此间，
最高楼上对青山。
何妨片月同孤寂，
自有和风共往还。
云阵阵，
水湾湾，
廿年交契水云闲。
观鱼各袖无争手，
冷却磻溪旧钓竿。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_243','念奴娇 读新河些雩赤壁词有和','熊东遨','当代','百年孤独，
向苍崖坐看，
露横星没。
除却东坡当日影，
眼底更馀何物？
一碧长天，
万竿秋水，
少个知心月。
玉壸倾尽，
待将幽兴催发。
遥念元始之初，
韶音仙乐，
未必宜人接。
便溯流光还起点，
来去终嫌匆卒。
旅食尘间，
悠游幻境，
剩此风骚骨。
炎凉种种，
过江鸿雁能说。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_244','临江仙 冬日太和山小住','熊东遨','当代','做个神仙小梦，
得窥云汉高天。
诸峰作势欲腾骞。
便成龙气象，
终是道根源。
霜雪自添磨砺，
竹松相对怡然。
人生不过百来年。
且留三两日，
细味五千言。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_245','鹧鸪天 山居偶拾','熊东遨','当代','莫谓闲斋雀可罗，
采薇采菊意犹多。
风扶竹影如朋至，
星助灯光感夜和。
行石涧，
坐云窝，
漫裁小景自研磨。
心藏梦忆谁同我，
九百年来只老坡。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_246','高阳台 醉根诗会归寄谷青先生兼示同盟诸友','熊东遨','当代','幽壑鸣雷，
晴云涨雪，
一园生意浑涵。
酒战诗盟，
天教我辈沉酣。
初行佛国明河里，
仗东风鼓动星帆。
算归来难息心根，
有梦图南。
图南计亦堂堂也，
向龙蛇影外，
筑个茅庵。
日夕招邀，
闲禽两两三三。
采薇偶过苍崖下，
听秦人慷慨高谈。
对青屏前事都忘，
后事都谙。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_247','行香子 春暮过草庵寺怀弘一法师','熊东遨','当代','几点微红，
几杵疏钟。
把吾侪引入空蒙。
摩碑辨字，
倚石观松。
对一山云一池月一亭风。
当年佛寺，
曾住诗翁。
大光明顶上圆通。
纷繁世道，
简约行踪。
在竹溪旁梅峰下菊园中。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_248','清平乐 七夕后一日自羊城赴思南','熊东遨','当代','锦帆高并，
仗得天风正。
露菊霜枫来不定，
蝉语足成秋兴。
平生多少回甘，
而今只剩清谈。
好是渡河时节，
故人约到思南。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_249','临江仙 读武当青年诗会诸作用散人“大岳引清樽”句述怀','熊东遨','当代','杞梓楩楠连类出，
万青争拱天门。
秋边气象一时新。
长歌吟白雪，
大岳引清樽。
明日我来应更好，
蟾霜添得三分。
采芝采蕨共山民。
溪头闲坐久，
自与晚峰亲。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_250','虞美人 汴西湖','熊东遨','当代','虹桥影卧烟波渺，
乐煞东坡老。
名湖天下半称西，
剩此汴梁城下未曾题。
浣云浣月俱宜也，
少个携壶者。
不须惆怅不须猜，
且向花间坐等那人来。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_251','清平乐 光孝寺洗钵泉','熊东遨','当代','不闻欸乃，
有脉通南海。
历数千年清未改，
照见人生精彩。
可能初祖重还，
潜鸣又作珠弹。
许我迟来一拜，
梦馀泉石之间。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_252','水调歌头 丙申岁杪姑苏仙游会与文裳弓月兄醉中约赋用风字','熊东遨','当代','仙侣几人在，
相约过江东。
十年离绪销尽，
仗此一帆风。
昨日西楼望月，
明日西湖待雪，
今日且从容。
知己二三子，
只要酒杯同。
遂初心，
经上古，
入鸿蒙。
自由天地行遍，
梦味醉时浓。
曲岸霜枫依旧，
野寺寒梅新瘦，
曾见老诗翁。
故国归来晚，
鸡唱起云中。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_253','清平乐 丁酉立春后二日羊城诗友白云山小聚分韵得幕字','熊东遨','当代','树屏云幕，
成就风骚约。
春似幼雏才破壳，
已把余寒啄落。
嘤其鸣矣清音，
翁之乐者山林。
记得那时情节，
重来拾取童心。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_254','菩萨蛮 立夏前一日天河醉归作','熊东遨','当代','东风过了春山角，
野芳开谢都从略。
轻易莫为诗，
商音不入时。
醉临云海上，
筑梦愁鸡唱。
移枕就高槐，
忽闻歌已而。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_255','最高楼 端午前二日还乡有作','熊东遨','当代','垂杨岸，
烟水正茫茫。
归梦及潇湘。
一从天赐仙游枕，
渐无人念屈沉江。
任长风，
吹疾雨，
下重洋。
也不记西山曾踏月；
也不记西湖曾待雪。
经过了，
便都忘。
此身误入红尘境，
此心犹在白云乡。
待回舟，
邀鹤侣，
泛沧浪。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_256','清平乐 立秋后五日凤凰山绝顶品单枞','熊东遨','当代','草毡云伞，
坐到秋池晚。
小饮流光三两盏，
消受天恩非浅。
古今人不同时，
新陈叶自同枝。
一种沧桑味道，
归来说与谁知。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_257','飞航道中','王揖唐','清末至民国','风定秋晴一鸟悬，
萸囊高佩到云颠。
周游丘是栖栖者，
幻梦庄疑栩栩然。
骑鹤未须誇万贯，
翀天底事说三年。
却惭瞰遍逃亡屋，
博济犹虚但汝怜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_258','送春','黎瞻','明','早起红亭酹一卮，
春归还作送春词。
乱飘远涧花全减，
碎语深林鸟欲悲。
紫蟹漫同邻舍饭，
锦笺新得故人诗。
薰风吹动芙蕖浪，
明日浓阴绿满池。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_259','送霍勉斋大参起用','黎瞻','明','樵岭峨峨万树松，
曾于学士寄高踪。
即看济美如伊陟，
况复匡时起卧龙。
锡命定从三殿下，
仙凫遥向两阶逢。
在封不久淹才子，
此去应闻禁御钟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_260','送黄泰泉宫詹应诏北上','黎瞻','明','三载抽簪返故丘，
紫泥催起侍垂旒。
山光欲傍宫袍动，
云气仍随彩宫浮。
诗点烟花辞泽国，
步凌星汉上皇州。
伫看补衮为霖雨，
两世龙门史汉流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_261','怀朱镇山少保','黎瞻','明','南岳钟灵第一流，
崇阶初入近龙楼。
宫袍细拂金门曙，
象简频沾玉露秋。
预缉色丝脩衮职，
早应喉舌赞皇猷。
无由直北瞻仪宇，
一卧沧江狎白鸥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_262','次无畏简叔雍原韵却寄','王揖唐','清末至民国','讴歌南国旧棠阴，
家世人犹艳茝林。
肯道擎天心胆苦，
微惊著雪鬓毛侵。
纵横酒阵宽杯勇，
啸傲词坛怒客瘖。
一事输君吾亦妒，
好花相对不成吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_263','次和无畏灵谷寺纪游之作','王揖唐','清末至民国','饱霜红叶北风寒，
阅世青山夕照残。
寺僻僧闲知款客，
诗清骨重傥成丹。
伯鸾性不因人热，
孝绰名符第一官。
砥柱南天君勿让，
要凭双手障狂澜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_264','桥西即目二首','李释戡','清末至现当代','王谢风流讵可期，
逢辰作健强题诗。
厌兵乔木萧疏处，
无女高邱寂寞思。
重过閟宫看壁坏，
忍临幽壑问舟移。
多君妙语同惊坐，
归我虚楼学卧痴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_265','桥西即目二首','李释戡','清末至现当代','病妨腰脚畏登高，
佳处秋光任目逃。
白堕临风要酒敌，
乌纱随地落诗豪。
东篱寒露花犹勒，
西苑重阳梦已劳。
长记易樊同负手，
赓酬十九首题糕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_266','斋居','李释戡','清末至现当代','短世轻轻换几秦，
何知中寿已遗民。
陈余张耳多黄土，
郭解朱家自可人。
早具老形安臂痛，
不删少作惜情真。
宵深虚幌鄜州月，
莫照村溪寂寞滨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_267','庚辰除夕','李释戡','清末至现当代','客去灯明岁亦徂，
萧然禅榻影随吾。
乱除爆竹声全寂，
寒甚梅花貌自都。
朔吹翻江檐际落，
宾鸿将子夜深呼。
草堂独把屠苏醉，
五十三年得此无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_268','辛巳元日','李释戡','清末至现当代','当关久不报侵晨，
剥啄今朝尔许频。
世换犹存行夏历，
津迷谁问避秦身。
裼裘侧帽慵延客，
冷蕊疏枝静笑人。
为告仆夫脂毂去，
湖天欲雪好垂纶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_269','梅雨兼句凉甚','李释戡','清末至现当代','曾闻夏浅胜春日，
不道黄梅雨似秋。
六月炎歊何许去，
夜寒教检越绫裯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_270','苦雨不出','李释戡','清末至现当代','学种芭蕉听雨声，
自家失笑筑新城。
空阶点滴心俱入，
竟夕淋浪梦不成。
村路泥深车马绝，
溪桥波涨楯栏倾。
先生不出有天限，
蛙黾从渠作意鸣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_271','园桂盛开二首','李释戡','清末至现当代','月中吹落是何年，
冷馥微醺欲破禅。
八十放翁悭见汝，
让余来作木樨颠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_272','园桂盛开二首','李释戡','清末至现当代','居士芗林劣与俦，
小山招饮续无由。
不须更说西来意，
已占桥西十顷秋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_273','踏莎行 送章一山太史','溥儒','现当代','边塞秋深，
蓬瀛海浅，
新亭有恨无人见。
桑乾西望接天流，
黄沙乱落并州剪。
木叶横空，
青山一线，
孤帆挂雨樽前远。
津门处处短长亭，
柳条攀尽无人管。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_274','从军行','祝允明','明','腰刀帕首报君恩，
初事将军出雁门。
回首家乡无限意，
秋风吹上五陵原。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_275','董娇娆','祝允明','明','京洛何迢迢，
紫衢通丽谯。
采桑谁氏子，
不解意飘摇。
强腕折高枝，
卑指揽柔条。
讵知枯残日，
不爱彼秾朝。
何当华堂上，
丽瑟歌此谣。
此谣固君情，
不移芳与彫。
吾将持赠子，
闻是董娇娆。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_276','卢姬曲','祝允明','明','卢姬貌似月，
复有伎如云。
青丝覆鸾额，
歌舞汉宫春。
参差铜台上，
宛转受恩频。
君不见太祖会杀声清人，
复留妙妓西陵里。
卢姬幸不为冤鬼，
为名嫁人花老矣。
人生行迹自有时，
莫以迟速叹卢姬。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_277','邯郸才人嫁为厮养卒妇','祝允明','明','高下理有定，
金房须玉骨。
不解理有异，
三五月圆缺。
昔为锦绮丛，
今为蕉萃窟。
娇卧邻皂刍，
夜半闻马龁。
遥梦赵王宫，
盈盈望秋月。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_278','陇头树','祝允明','明','陇头多嘉树，
君持作梁柱。
清晨覆宾相，
白日抱歌舞。
哀哉北邙麓，
日日听人哭。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_279','骢马驱','祝允明','明','骢马紫游缰，
光辉照洛阳。
朝辞上林苑，
晚入斗鸡坊。
无因道千里，
城邑少豺狼。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_280','关山月','祝允明','明','明月度关山，
中天照蕃汉。
十万良家子，
嫖姚甲待旦。
健儿秋牧马，
天子晓射雁。
亦有王明君，
独抱穹庐叹。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_281','雉子班','祝允明','明','雉子班，
何牡不顾女，
来语啄班班。
吾不如绞颈谷中。
班班何，
班班何。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_282','天马来','祝允明','明','天马万里来，
天闲□开天马入。
群马辟立视天马，
长安亦有苜蓿食。
饱天子，
德天马，
天马在宛野。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_283','陇头水','祝允明','明','流水出陇头，
白石乱高树。
四海远深渊，
原泉日夜注。
不见人物景，
独向东流去。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_284','吴趋','祝允明','明','阊阖红楼起，
皋桥渌水回。
绮罗摇日丽，
车马逐云来。
施旦非吴艳，
机云是晋才。
欲歌遗古调，
风俗转堪哀。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_285','柳枝','祝允明','明','夹汴春来千万枝，
绿阴随处缚金羁。
殷勤休负东风意，
曾把青芽细细吹。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_286','柳枝','祝允明','明','紫泉宫外晓烟和，
万绿条含太液波。
只有帝家春色好，
争禁人世别离多。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_287','柳枝','祝允明','明','树犹如此我何堪，
长笑殷郎气不男。
若见女儿腰十五，
一生踪迹只江潭。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_288','柳枝','祝允明','明','隋家萧后解伤春，
内苑亲栽几树新。
出塞归唐春渐老，
美人思树树思人。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_289','柳枝','祝允明','明','白家只说舞腰肢，
不把红妆斗翠眉。
嬴得美人怜又妒，
一时都不爱花枝。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_290','柳枝','祝允明','明','营门只阻羽葆幢，
争似连云荫漕艭。
护国清风四十里，
百年人说老平江。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_291','林鸟','祝允明','明','无柰恩情密，
临别自依依。
思君如林鸟，
同宿不同飞。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_292','林鸟','祝允明','明','与君如林鸟，
暂聚遝长离。
得夜乃共宿，
入明不同飞。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_293','泰风','祝允明','明','岁律默迁，
夕飙儆物。
起坐多念，
歌以永言。
灏商回秋，
泰风薄宵。
冲堂袭惟，
其音萧萧。
蜩咽乌栖，
蟋蟀试吟。
岂无忧欣，
以耿遐襟。
肖形声气，
亦有裳衣。
无作我羞，
朝日将晖。
昔之抚景，
鲜驩薄游。
今之抚辰，
力弗及脩。
五十无闻，
先师无畏。
无曰其迟，
其日如驶。
皇序递代，
漫漫百年。
天之将旦，
无然爰爰。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_294','诗','祝允明','明','巍巍大山高，
㳽㳽长河流。
人生百岁间，
有乐亦有忧。
葱葱陵上槿，
朝华夕已休。
俶载向南亩，
岁乃亦有秋。
少壮在努力，
老大且偃息。
偃息安此生，
此生须有成。
努力不在少，
老死终无名。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_295','诗','祝允明','明','滔滔川上水，
羃羃堤边草。
行行远方客，
历历山下道。
道远行易疲，
白日坐已驰。
无忧白日暮，
秪恐严霜垂。
日暮行复朝，
严霜草以彫。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_296','诗','祝允明','明','中谷有道士，
颜色常鲜好。
被以松柏叶，
啖以灵药草。
守气存谷神，
后天可难老。
授我鸿素书，
相期青云表。
众人不尽闻，
安能不枯槁。
神农遗世经，
谷食烝民宝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_297','诗','祝允明','明','物生天地中，
万形同一钧。
小大各自齐，
聚散常相因。
高岸忽为谷，
沧海亦飞尘。
弱质非金石，
谁能独久存。
生世六七十，
永者仅百年。
相去几何许，
等死焉足论。
仙人庄子休，
为君颇开陈。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_298','诗','祝允明','明','夭夭南国子，
声伎妙入神。
审音类子野，
歌舞倾都闉。
城邑不足留，
引领奉韶钧。
浮云翳广路，
且与闾里亲。
倡家日还往，
哇淫累其真。
简兮前上处，
谓言不足珍。
乐府久隔绝，
系籍犹相因。
啸歌且自乐，
亦以共嘉宾。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_299','杂诗','祝允明','明','凤凰执圣符，
有道乃来仪。
白鹤抱仙姿，
俗士每豢之。
栖啄非梧竹，
腥秽苟羁縻。
鸢戾与鹰挚，
性在哺雏雌。
翩翩遵渚雁，
噭噭鸣声悲。
青冥一举翼，
万里乃通岐。
洁食荻中粟，
渴饮清川湄。
孤翔无乱偶，
高风羞诡随。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_300','述行言情诗','祝允明','明','昔受皇灵命，
结此轩奇姿。
一从辞铏璞，
雅负遂参差。
英光没腾越，
皓素变为缁。
兹辰起遥想，
椎凿倘还施。
但恐时日促，
璋琥竟无期。
乃知万物贵，
治琢当及时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_301','述行言情诗','祝允明','明','大钧鼓群有，
黄祗效成物。
流形随风气，
结性亦殊律。
吾生托燕冀，
抱禀愧沉郁。
返兹宽柔方，
茹和克彊倔。
所耻非平康，
徒胜此回屈。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_302','述行言情诗','祝允明','明','结发属偶句，
舞勺肆篇章。
前徵吻羊叔，
髦誉追滕王。
明明内外祖，
公望张辟疆。
提剑多教术，
童弱企高翔。
安知三纪后，
栖栖守榆枋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_303','述行言情诗','祝允明','明','苍姬建鸿历，
祝丘肇遥封。
丰稊托后穰，
疏条鬯周通。
九江树崇议，
司徒奋皇庸。
信栝烂材器，
闽建扇遐风。
渊渊都漕君，
起官来南江。
雄略绝类群，
宏图奠兹邦。
五子粲马窦，
载以辟吾宗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_304','述行言情诗','祝允明','明','曾祖抱至德，
天倪以和神。
善闭本无楗，
泯耀没见闻。
辟时遁朱鬕，
倾否逢皇运。
微情委塞聪，
遵养晦衡门。
洪源浚且潴，
大川乃雄奔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_305','述行言情诗','祝允明','明','赫赫惟王父，
自天拥英休。
完德奠瑚琏，
大积苞坟丘。
敷言对清问，
献纳襄王猷。
宅忧秉大防，
旬宣向闳州。
冀方犹虞岳，
懋縡腾诸侯。
悬车耳顺岁，
高烈方弸彪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_306','述行言情诗','祝允明','明','公有高明居，
安老亦畜小。
时从息经笥，
偃仰思至道。
繁英蔼修荣，
高简棁不藻。
周罗千载语，
竹素光耀耀。
忆跪听公诏，
拜此济生宝。
县丱蹑短阶，
昏旦恣寻讨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_307','述行言情诗','祝允明','明','先人备百行，
为仁乃其基。
至诚动万物，
大孝敷弘规。
慈爱无等伦，
日月洞肝脾。
岂惟天止性，
在三道兼师。
母氏既圣善，
孝敬极壸彝。
坤仪绝振古，
直当任姒期。
喣乳帱载间，
春秋望翔驰。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_308','述行言情诗','祝允明','明','泰否冥斡运，
大小互来往。
童龄何愆戾，
忽使堕毒枉。
焉知循陔庆，
遄成陟屺望。
万生皆有终，
逆质胡不丧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_309','述行言情诗','祝允明','明','大忧缠弱衷，
意气尽荒漠。
向未遨长衢，
中路履綦错。
零霰杀翘荣，
朱光就凄薄。
辰遘萃华滋，
运消易零落。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_310','述行言情诗','祝允明','明','人理有太合，
太合及兹辰。
束楚当星户，
虹梁就鸟津。
彼其行结悦，
予亦御周轮。
从云来粲者，
卺醴合良人。
永始承遥绪，
昌图启后珍。
𠻞嘅山河誓，
与子并千春。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_311','述行言情诗','祝允明','明','执业禀公训，
士节谨干禄。
力修贵潜蕴，
进达戒征逐。
踰冠闻有司，
察业就甄录。
校考既充赋，
胶序且饩育。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_312','述行言情诗','祝允明','明','人生有穷惨，
大化当极否。
偪蹙适三月，
凶割降重累。
钜痛深故创，
沈冤等堕海。
人生覆无天，
云胡不遄死。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_313','述行言情诗','祝允明','明','六极兼弱贫，
百罹萃凶孤。
素薄综物怀，
坐为鄙人图。
仓箱既凉匮，
米盐务锱铢。
自持椅桐姿，
埋沈向泥涂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_314','述行言情诗','祝允明','明','读礼讫祥禫，
试琴成笙歌。
丘坟肆畋狩，
志行穷琢磨。
天人贯粗微，
昔今纷网罗。
大道弥宇宙，
眇薄将如何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_315','述行言情诗','祝允明','明','先人有高栖，
遗我端居室。
幸无丧志物，
塞楹简编集。
皇王植丕训，
子氏张万术。
闭关断来鞅，
庶以究昕夕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_316','述行言情诗','祝允明','明','学聚勤殖藏，
息游解纡结。
宽原或流衍，
澄泉共甘洌。
攀条采硕果，
循畦屏衰叶。
幽禽答遐韵，
候虫依气节。
芳霭蒙晨荣，
明煇扬夕月。
拔时附绝驾，
塞兑谢尘辙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_317','述行言情诗','祝允明','明','服膺从圣轨，
厉志尊前闻。
敦厚觅砥道，
高明抗浮云。
玄元极三古，
疏通穷八垠。
焉能为栖栖，
掩抑斥鴳群。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_318','述行言情诗','祝允明','明','老聃贵知希，
庄周识齐物。
山渊故应平，
精象藏恍惚。
因知在矢溺，
居然返冥极。
安知临牢豕，
终为祝宗絷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_319','述行言情诗','祝允明','明','昔在杕膝下，
拊顶称佳儿。
珠凤已验文，
棋虎亦彰奇。
所企自有立，
名位岂足期。
自从胜簪弁，
颠隮逢百罹。
握志壮室馀，
荐名仅乡司。
逸足远市肆，
永愧英贤规。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_320','述行言情诗','祝允明','明','浮名虽或就，
夙尚乃弥坚。
漆雕有风期，
恒虞终邈然。
英游并汇征，
予犹畏争骞。
兹辰更不伸，
蚇蠖盘黄泉。
因知随时义，
圣谟固昭然。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_321','述行言情诗','祝允明','明','戋戋抱微禀，
自拟犹蓱蓬。
企瞻先哲民，
终羞绝萝松。
追随不越群，
胡足为不同。
何为荡荡世，
亦复此不容。
无闷见君子，
先师尝发矇。
平平王道间，
万厉频交攻。
苟无反躬术，
何以禦诸凶。
皇仁卒全物，
莫高匪玄穹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_322','述行言情诗','祝允明','明','斯人各有尚，
沉潜与高明。
伊予独坦荡，
未解怀戚营。
既不毕狂狷，
安得遂中行。
所睹恒廓如，
万有通一平。
泰嵩輶如毛，
瞳眴已千龄。
不知要其终，
得丧将焉徵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_323','述行言情诗','祝允明','明','同人贵郊野，
气度本恶狭。
出入州闾间，
清浊且参夹。
无衰桑梓敬，
幸共枌榆洽。
鸟兽不可群，
非人其谁狎。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_324','述行言情诗','祝允明','明','大仪靡停运，
百生岂淹息。
丽天星汉度，
附地虫鸟疾。
把策诣有司，
五往五见黜。
岩栖岂无尚，
廛托病多役。
钱刀坏心气，
霜露损毛质。
蕉萃勿复言，
流尘蒙白壁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_325','述行言情诗','祝允明','明','陈根托九壤，
材朴各能蕃。
剥果存孤硕，
微稊仅不残。
芃芃万植中，
吾独姤其艰。
空务封沃勤，
柯条竟疏单。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_326','述行言情诗','祝允明','明','疏单勿复道，
幸抱此高襟。
妙鉴既弘照，
大车亦雄任。
如何覆载洪，
行迹复淹沉。
孤征即长道，
缠绵荆莽侵。
焉能不跼蹐，
日月坐以深。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_327','述行言情诗','祝允明','明','岐路纷百虑，
三十尚择术。
规空际无象，
践迹窒寸尺。
先师有遗矩，
四十乃不惑。
冰鉴端服膺，
物貌讵纤忒。
交衢纷总总，
大路遵有一。
皇皇孔氏程，
圣愚乃同则。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_328','述行言情诗','祝允明','明','万理尽东鲁，
群空乃西来。
馀子骋千涂，
憧憧何取材。
学聚蔽穹壤，
白纷无遗哀。
慹然对今古，
至乐不自裁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_329','述行言情诗','祝允明','明','百代为宇宙，
升降成兴衰。
兴衰极变化，
忽已遘兹期。
方策布群贤，
建躬各随时。
森罗丙法戒，
所在吾有师。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_330','述行言情诗','祝允明','明','有师蒙获富，
君子贵为己。
每求同若人，
力勇由知耻。
周身饬百行，
建节广纲纪。
任重扛九鼎，
致远道千里。
细德未足论，
大干敢摧靡。
丈夫生所期，
恒存在后死。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_331','述行言情诗','祝允明','明','明王方御宇，
世才乃徵庸。
礼乐建皇极，
风猷归大中。
亭育茂登殖，
声名粲光融。
卑高百有位，
道术何终穷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_332','述行言情诗','祝允明','明','仲生能乐志，
夷吾性善养。
恣任总勿阏，
道林胡偃仰。
名都富雄第，
山池半邑党。
崇丽摩浮云，
琼筵日弘敞。
水陆穷罗羞，
歌钟沸繁响。
妙伎逾二肆，
游童列弥广。
毕性声色中，
麟台进功赏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_333','述行言情诗','祝允明','明','素无经世怀，
学仕本先训。
终然拙枘凿，
株木臀久困。
浑玄当有期，
或合阮君遁。
元龟幸垂兆，
长往乃无闷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_334','述行言情诗','祝允明','明','筑舍负崇巘，
高卑缘秀林。
翠岭绚晨晖，
丹崖丽夕阴。
入坐交飞英，
当窗语幽禽。
山人适云觏，
写性将清琴。
郊居赋既就，
白醪亦可斟。
循麓看时艺，
桑麻长方深。
未必谈名理，
欢畅已弥襟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_335','述行言情诗','祝允明','明','清晨风候淑，
引策出郊郭。
青黄交远畴，
循浒桑沃若。
白云被华岑，
飞涧濯幽壑。
汎眺思累新，
冥会神逾廓。
命俦赏已豪，
孤寻寂倍乐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_336','述行言情诗','祝允明','明','驱车出衡门，
薄游览九州。
东征略瀛海，
西陟升昆丘。
冠巾岱华竦，
襟带江河流。
验迹章亥趾，
裁贡禹王畴。
汎观山海图，
遐寻府穴幽。
八维何所极，
撮土此可求。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_337','述行言情诗','祝允明','明','万龄同一域，
千哲共此契。
遥迩幸相闻，
师友丈室内。
行止每讨论，
音辞时赓载。
单躬事百贤，
其益故宜大。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_338','述行言情诗','祝允明','明','遥贤故怀益，
密哲重应钦。
四海三数君，
垂眷后先深。
年位非所限，
存没或殊今。
渊渊玄酒味，
粲粲瑶华音。
怀哉以拜嘉，
毕世铭卑襟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_339','述行言情诗','祝允明','明','仲尼欲无言，
六籍终亦呈。
林蘤向春敷，
有喙随风鸣。
斋房坐清晏，
文言时有成。
左生润瑚佩，
庄周厉风霆。
二汉隆体骨，
六代繁丹青。
至哉统其全，
周后惟唐声。
山鸡且自爱，
蝇辩方营营。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_340','述行言情诗','祝允明','明','学优在用行，
时舍乃含章。
士业岂空言，
斯世存维纲。
脩政用熙载，
树礼为周防。
生养蕃卵胎，
芟夷谢萧■。
文思翊无为，
乐声荐登康。
本未有宏模，
千目森铺张。
褐襟衷短简，
可布亦可藏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_341','述行言情诗','祝允明','明','至道极心性，
域外有真觉。
旷生幸闻脩，
瞽辩岂喧较。
万变终不缪，
吾自了灭乐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_342','述行言情诗','祝允明','明','凤鸟不世见，
四海以德称。
虎豹伏深山，
雄鸷乃驰名。
日月递经天，
夕伏亦沈冥。
目趾待成功，
谁不仰其明。
所以孔仲尼，
君子疾无声。
嗟予蹇淹留，
闭户乃浮名。
高卑共彰彻，
近远均一鸣。
惟忧邦必闻，
求之无其情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_343','述行言情诗','祝允明','明','六籍统宇宙，
七纬键天人。
百子错町畛，
万家腾烟云。
眇眇予日接，
泳洽如渊鳞。
冥蒙日思道，
粲发时摛文。
纷纶向一贯，
光彩摩三辰。
向来觉性言，
寂寞难重陈。
至乐终百年，
与尔同埃尘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_344','金兰操二首','祝允明','明','金兰之猗猗兮。
写我心以贻兮。
聊与子同归兮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_345','金兰操二首','祝允明','明','两公闲闲兮。
贻我金兰兮。
金兰也且，
闲闲也且。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_346','和陶渊明饮酒二十首','祝允明','明','昔者病斯世，
庸人常扰之。
百物安大化，
甚似垂裳时。
衮衮元化中，
吾生托于兹。
学道三十年，
今辰聊寡疑。
愿言戒迷涂，
灵台亦有持。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_347','和陶渊明饮酒二十首','祝允明','明','明时耻韫玉，
抱策下丘山。
所献几何许，
腐义数千言。
有司缪甄录，
一出踰十年。
身世无一补，
何物期自传。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_348','和陶渊明饮酒二十首','祝允明','明','士生三代后，
干名本其情。
所叹少可知，
科版猎空名。
二者齐亡之，
何以为此生。
此生幸长存，
得失何复惊。
陶公但饮酒，
千载名自成。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_349','和陶渊明饮酒二十首','祝允明','明','大鲲本渊潜，
化形亦天飞。
截鹤续凫胫，
二物均为悲。
日月绕玄度，
万象各有依。
天地会有终，
脩短同一归。
吾生向妍华，
何惜此日衰。
有酒不解饮，
而问彼从违。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_350','和陶渊明饮酒二十首','祝允明','明','大道本一致，
无问寂与喧。
每有希夷时，
不见耳目偏。
逝水喜东流，
浮云忘故山。
美人隔秋风，
涉江耻空还。
旦莫或遇之，
庄周有遗言。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_351','和陶渊明饮酒二十首','祝允明','明','客来相话言，
言多非与是。
问我谁适从，
我不识誉毁。
幸客来相过，
惟能默饮尔。
随意翻瓦盆，
不解弹缘绮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_352','和陶渊明饮酒二十首','祝允明','明','秋霜瘁荣木，
春露华槁英。
逝者不能已，
爱憎谁为情。
吾生四十年，
强半居欹倾。
不知谁为之，
孰为相号鸣。
局促百年内，
安足称达生。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_353','和陶渊明饮酒二十首','祝允明','明','凤鸟有五文，
不共群禽姿。
言欲览德辉，
来下梧桐枝。
文采众爱惜，
云是应世奇。
廷无箫韶仪，
好文空言为。
恐终返天山，
逝难风尘羁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_354','和陶渊明饮酒二十首','祝允明','明','世事不可极，
遇酒意自开。
宽然处百年，
亦有几好怀。
吾驾无回辕，
何适亦何乖。
夫子惟天行，
微生病栖栖。
孺子濯以清，
屈公淈其泥。
幸此杯中物，
与我多合谐。
醉中态多乱，
真抱自不迷。
皇唐事悠然，
古意暂可回。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_355','和陶渊明饮酒二十首','祝允明','明','回首望乡井，
窅在东南隅。
倦鸟不出林，
胡为涉川涂。
冬半多北风，
疲马不奈驱。
昔行气长健，
兹来感有馀。
园田苟可治，
岂不怀安居。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_356','和陶渊明饮酒二十首','祝允明','明','长愧先师言，
忧贫不忧道。
劳辛救寒饥，
容体易枯老。
自从强年来，
颇不患衰槁。
翕翕电影间，
英交亦何好。
澹然无得丧，
恐有身外宝。
灵龟不朵颐，
乃活岁月表。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_357','和陶渊明饮酒二十首','祝允明','明','吾足如转莲，
遇风无停时。
节候迭代序，
常与家室辞。
三岁凡五出，
别离复在兹。
行止岂有津，
谁为我稽疑。
不若巢中禽，
乃免霜霰欺。
天运实为尔，
通塞任所之。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_358','和陶渊明饮酒二十首','祝允明','明','尝喜陈图南，
托世在梦境。
亦有阮步兵，
六旬且一醒。
神解与辟世，
此意在各领。
汩汩糟醨间，
少复此冥颖。
哀哉羊皮人，
方彼耀虎炳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_359','和陶渊明饮酒二十首','祝允明','明','四十不拟老，
老状日已至。
饮量复减昔，
三饮已复醉。
诗来亦信口，
甲乙懒排次。
遐览天地间，
何物如我贵。
所恨每自丧，
长失本然味。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_360','和陶渊明饮酒二十首','祝允明','明','所乏百亩田，
亦须五亩宅。
居食少给躬，
何复世上迹。
一身自宾主，
一日足抵百。
知我不暂舍，
举眼天日白。
默然便归化，
亦复何足惜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_361','和陶渊明饮酒二十首','祝允明','明','安世至此日，
世纷亦已经。
庄周不畏烦，
为人校亏成。
五岳屹常居，
四序乃迁更。
微子为之奴，
箕子出门庭。
谁能外阖辟，
妄动枢机鸣。
密云自西郊，
荡荡周文情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_362','和陶渊明饮酒二十首','祝允明','明','卜商有遗言，
学而优则仕。
学既非为人，
仕复宁为己。
有玉求贾沽，
无道谷亦耻。
仰瞻夔龙朝，
俯愧蓬蒿里。
骎骎饶二毛，
行行入四纪。
马逸驾可覂，
风回楫须止。
尔无操御中，
颠覆何所恃。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_363','和陶渊明饮酒二十首','祝允明','明','二仪不翻覆，
万生岂无真。
物情虽冯时，
中亦含元淳。
扬子本清静，
衔垢作美新。
贾生抗高志，
慷慨为过秦。
其君或唐虞，
彷佛皋契尘。
诎已徇一时，
哀哉遘其勤。
因知纭纭内，
心与身自亲。
会须直躬行，
大道无迷津。
提壶挂舟傍，
还戴漉酒巾。
何必访巢许，
今古皆斯人。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_364','秋怀','祝允明','明','时运无长荣，
清商多悲音。
悲音一何苦，
壮士有远心。
萧萧风篁乱，
琴瑟蛜蝛吟。
寄言眷万古，
托之千霜林。
浔阳有馀波，
涯岸倘能寻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_365','梦作月山独步歌','祝允明','明','不忿白日尘，
宵赏有灵悦。
山蹊任襟入，
不必有昔辙。
石淙长写韵，
风林时落叶。
冻狖僵石霜，
跃鳞触潭月。
山空夜深静，
魈鬼时出灭。
自非返冥极，
谁能畏城阙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_366','拟伤乱','祝允明','明','楚氛望方恶，
鲁战谟未谐。
晋籴每多闭，
秦饥良可哀。
三精塞祲雾，
旸雨更为灾。
巴蜀风尘暝，
关河士马来。
洪流灭阡陌，
沟市盈饥骸。
岂无眠戈誓，
慷慨击楫才。
夏屋既漂摇，
郊垒多崩隤。
桢干可相寻，
松柏亦已摧。
天王下制诏，
仁声九域开。
庶几赳赳客，
犹上黄金台。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_367','代江南水灾谣','祝允明','明','天皇耄不事，
地后虐不仁。
尽卷天河水，
淋灌九州人。
九州人，
食多在江南。
江南灌没，
柰何堪之柰之何。
人死无万数，
薪绝灶冷无菜煮。
更那得菽与黍。
遽如许，
推龙号，
挽龙语。
汝不应吾，
吾请天公，
来解谪汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_368','九悯九首','祝允明','明','溪毛圃芽鲜芳殊。
吴侬恒食饶嘉蔬。
今年大馑百年无。
百年无，
柰空肠。
龁野草，
同牛羊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_369','九悯九首','祝允明','明','大麦青青四尺长。
大水过头一尺强。
安得不托与餦餭。
无餦餭，
且自可。
秧不成，
苦杀我。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_370','九悯九首','祝允明','明','四月洚水麦不秋。
五月插秧水不收。
良田万顷尽洪流。
尽洪流，
大无禾。
民皆死，
如国何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_371','九悯九首','祝允明','明','栋挠室摧墉善崩。
沈灶产蛙不得烹。
康衢笫席通流平。
通流平，
慕鸱鸮。
望伯禹，
怀有巢。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_372','九悯九首','祝允明','明','饥亡溺亡十亡五。
载降之疫亡亡数。
谁生厉阶令帝怒。
令帝怒，
半为鬼。
厉阶人，
安富贵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_373','九悯九首','祝允明','明','有田莫买只卖屋。
况有筐箱与巾服。
妻乎子乎牵出鬻。
牵出鬻，
汝不肯。
推沟渎，
竟死等。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_374','九悯九首','祝允明','明','旧乞无几新乞多。
吾食不续欲分何。
汝不吾分越夺那。
越夺那，
乞化偷。
孱则丐，
狠则楼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_375','九悯九首','祝允明','明','旧田不粒犹征逋。
新田为渊租未除。
农来为兵强执殳。
强执殳，
绝钱镈。
国无农，
其何国。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_376','九悯九首','祝允明','明','官囷旷空抽民米。
富人削瘠贫人死。
嗟嗟土牧亦劳只。
亦劳只，
荒政难。
吊吾民，
嗟吾官。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_377','水诗','祝允明','明','雨漫天兮天不得见。
水漫地兮地不得践。
烝人不粒兮桑田变。
神仙老死佛入灭，
伯禹乘龙，
仲尼乘筏。
出八极兮睨洚淫而不即。
公无渡河兮公既没。
妇逐狂夫，
与子偕溺。
青山推，
鳌足断，
蛟蛇腾拿，
万物错乱。
厥初天一兮生水，
其载与天地兮为终始。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_378','雪后杨礼部邀宴用谢宣城韵分得浊字','祝允明','明','季冬雪始降，
佳气通岁朔。
君子良燕会，
时哲总延擢。
揖逊粲宾礼，
登奏鬯嘉乐。
兰薰互沾袭，
松颜齐卓荦。
遐览万物昭，
无复见黟浊。
微言共一契，
所寄在绵邈。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_379','召父歌送朱版曹升之守延平','祝允明','明','西北有高山，
东南有大海。
生我延平民，
居中百千载。
远在天南头，
去圣人万里。
欲得无菑害，
秪赖贤守宰。
圣人念远人，
赐我慈父母。
辍其股肱佐，
来为赤子乳。
我望朱夫子，
如望汉召父。
请为召父歌，
女知召父不。
召父善治田，
从横正疆亩。
始予我钱镈，
以及奄铚艾。
耦耕并牛犁，
粳稌诸种艺。
田功多方理，
要领在水利。
广开沟门阏，
处处广浇灌。
均水作约束，
刻石防决泛。
劭农走阡陌，
止舍即野次。
召父善教人，
颁训从幼艾。
孝弟正家族，
勤谨不弛怠。
趋役赴公事，
和孙于社火。
有禀特秀异，
使结衿带佩。
入学共弦诵，
学古壮而仕。
召父善阜财，
民产加丰大。
召父善听讼，
无情不哗喙。
饥渴召父食，
寒祼召父被。
召父善使人，
随时各分代。
召父善事神，
水旱不为厉。
人口岁增倍，
讼盗悉衰止。
召父去已久，
循良风声在。
惟有朱夫子，
甚与召父似。
凡此召父善，
朱夫子尽备。
夫子来毋迟，
百姓日候伺。
凡此召父事，
于今益有赖。
一一速施行，
惠我起我惫。
上戴天子恩，
夫子还入拜。
愿为公孤贵，
名与召父配。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_380','夙驾迈皇邑','祝允明','明','夙驾迈皇邑，
奏计天子闱。
命臣宰吴民，
民淳幸成治。
君子闲礼教，
细人勤耘耔。
潢池徒涉境，
亦幸免颠隮。
岁月可少假，
当转瘠为肥。
臣政报不欺，
大君企鉴裁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_381','夙驾迈皇邑','祝允明','明','夙驾迈皇邑，
公去我心悲。
京吴期月程，
父母何时归。
所虑大君留，
吾侪将畴依。
贤人在高位，
庶绩用咸熙。
子产往作相，
嗣之来者谁。
大君一内外，
留遣皆贤才。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_382','京馆登楼眺远','祝允明','明','登楼睇遥际，
迩值城东阿。
都市无旷壤，
万室交鳞罗。
花鸟不见妍，
鸣轮日冲过。
衢喧万方言，
嘈杂丝吹和。
赞皇筹幸运，
仲宣忧独多。
吴邦弗可见，
不乐将如何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_383','舟行汶上薄暮看月作','祝允明','明','璇盖莹空青，
飞鉴泛华艳。
川原邈夷旷，
疏木媚寒潋。
广路断浮鞅，
旅玩谐靖念。
迹逝偕志行，
万里靡坊堑。
苟无忠惠持，
谁能劳不厌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_384','自京师南赴岭表仲冬在道中','祝允明','明','秉策志渥丹，
牵丝及班艾。
拜宠北阙下，
寄命南峤外。
霜履将蹈冰，
虚舸循寒濑。
越乡惭古节，
垂堂慄先戒。
刘公存社稷，
雅尚幸终会。
一丘沈结膺，
三历拟投带。
晚荫答苍灵，
赤鉴慎无昩。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_385','五十服官政效白公','祝允明','明','五十服官政，
六十方熟仕。
七十乃致政，
古今固一致。
吾年五十五，
始受一县寄。
七里剧弹丸，
亦有社稷置。
夙怀同刘君，
今此幸谐志。
所忧脚本短，
时彫虞易踬。
秪应尽素衷，
玄鉴不可悖。
一区石湖水，
渔舟早相伺。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_386','梦游','祝允明','明','航苇缘曲溪，
峡深溪转幽。
滢靓水气甘，
葱苍木荫稠。
空舠孤持楫，
愈入世弥遒。
步履穷竖亥，
秪此适余舟。
虫鸟元共性，
非契我何求。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_387','梦游','祝允明','明','予行物已隔，
极境愈欲至。
独有仙巢子，
被发跪云内。
栖岩玩颓阳，
流谷响清喟。
须臾始云觏，
伺我九千岁。
海中多真人，
徒美遐不值。
琅霄有飙轮，
中夜以为会。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_388','读余侍御游泰山记咏其间二三处','祝允明','明','于铄姬后，
缔兹合宫。
爰宅神明，
穆穆王风。
降及后王，
以奉土木。
彼营于朝，
形侈实黩。
今我涖瞻，
犹拜文武。
念兹草木，
且附圣土。
有赫我后，
三登五咸。
臣愿师周，
唯后用鉴。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_389','读余侍御游泰山记咏其间二三处','祝允明','明','乾居冠峻，
岳承级通。
明宫星辰，
缀琨栋云。
雾弥璇墉，
摄齐入金。
门拜肃窥，
天容俯躬。
览八表辨，
方识疆封。
西北拱王，
室舟车方。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_390','读余侍御游泰山记咏其间二三处','祝允明','明','我昔闻日观，
想像当雄哉。
君今登日观，
真从日边来。
君言日观高踞山之东，
左有天门，
右有绝崖。
从中突起一片石，
不知千丈万丈，
上拨浮云开。
扶携石傍东面坐，
但见东方无际畔，
尽在莽苍沧茫间。
上不辨穹霄，
下不分人寰。
八极总一景，
焉知别华蛮。
忽闻天鸡鸣一声，
恍惚红光射破青冥端。
龙宫煆火齐，
琢为太阳丸。
海波潋潋玻璃翻，
搏桑翛翛扫三山。
卫霞从雾纷斓斑，
五彩错乱多朱殷。
龙车不须毂，
踆乌不须翰，
奋迅升天关。
游天衢兮循天环，
开辟六合，
天尊地卑，
万物出作咸乂安。
日观之日乃如此，
亘古不息正天纪。
苍生仰照宣重光，
吾能言之自此始。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_391','方烈妇诗','祝允明','明','芙蕖托藕根，
藕折芙蕖萎。
雄剑出土中，
雌剑飞相随。
桐城有女姚，
嫁事方家郎。
贞心两松柏，
信誓双鸳鸯。
方郎中路陨，
女姚治其丧。
明朝郎入土，
何事妾不亡。
妾有十尺丝，
玉质奄从化。
一夜寒霰零，
兰枯蕙亦谢。
煌煌双白璧，
合瘗南山冈。
宛宛两柔荑，
为人挈三纲。
旌书下万乘，
烈声腾九有。
九原多杂臣，
试问方家妇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_392','莆田郑殿中绿野亭','祝允明','明','吾闻鸟山下，
千载君子宫。
云谁搆此者，
柱下有遗风。
昔与韩忠献，
同升事仁宗。
抗节匡王度，
寒岁荣霜松。
翩然返薜萝，
考槃亭此中。
孙子联翼翔，
邦人亦钦崇。
出处鉴兹宅，
眷言均帝衷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_393','赠伦解元','祝允明','明','佳人出南国，
郁郁春松姿。
手有龙卷文，
忠信以自持。
茂年秉高义，
淑姆群妇师。
君子聘好逑，
任姒共风期。
关关雎鸠化，
四海为雍熙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_394','赠伦解元','祝允明','明','珠玉一出世，
见者爱辉光。
云汉倬昭回，
众夫仰文章。
煌煌锦绣段，
愿为衣与裳。
醴泉消渴心，
嘉禾望充肠。
亭亭梧桐树，
可以栖凤凰。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_395','赠伦解元','祝允明','明','明王揽大宇，
百福日富来。
车书上皇邑，
八表无迟回。
与子遇原野，
携手乃徘徊。
君行遵大路，
日以写予怀。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_396','赠王翰林思','祝允明','明','先公昔登庸，
寔出元礼门。
雄篇累贲遗，
存亡被光燉。
吾儿缪通籍，
重得联英骞。
顽鄙当其中，
俯仰惭祖孙。
夫子笃风义，
眷然推好敦。
昨旅同北都，
今来共南濆。
英哲产自艰，
分气勤化元。
绳矩用必庄，
天球质本温。
藏蓄在王府，
望瞻不可扪。
谁令寘海隅，
混揉珠贝繁。
兰风涤瘴腥，
桐韵澄蛮喧。
迩来观海居，
高寄城西原。
白雉不见来，
蜃气日夕昏。
将无辱贤者，
乘桴慨遗言。
韩公日良觌，
代隔道共存。
时时出卮言，
珍怪无玙璠。
颇闻多幽味，
深澹如丘樊。
蔚林断湫鞅，
疏筱涵静源。
万境不能乱，
始知吾性尊。
凤文非可求，
惠然下蓬轩。
虽钦俯芥收，
终愧仰萝援。
即欲往从之，
川梁棘我辕。
尘谣无足投，
望报来琼琨。
空荒坐迟晚，
劲策幸扶攑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_397','题黄山人诗卷','祝允明','明','南来作县官，
亦希遇异人。
三年雾眯目，
衣上多新尘。
翩翩一黄鹤，
衔书祝融滨。
下庭展袖讽，
字字青瑶㻞。
既惊旦暮契，
犹怀夙昔亲。
凤鸣燕雀间，
视听暂得伸。
鹤乎果有升天翼，
借我乘之朝玉宸。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_398','吉湖口汤泉','祝允明','明','慕诡适修禊，
啸侣阅灵渊。
机权知匪测，
橐籥讵云偏。
觱沸连波起，
鸿垆不断燃。
盖石愈怪杰，
襟湖何渺绵。
萧丘有寒燄，
化理同一玄。
燧人与尧井，
无为帝力全。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_399','鸡黍词','祝允明','明','庭中有群鸡，
主人赋之黍。
鲁鸡偶远立，
于此有遗秬。
越鸡气沾沾，
欣睨跃拙距。
主人轩然笑，
尔蠢何足语。
嗟哉胡得丧，
可恶尔畜羽。
幸祸天所怒，
得丧天所与。
主人唯至公，
但使丰年屡。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_400','读嘉靖改元诏书并阅邸报臣敬作诗一首','祝允明','明','宫车昔晏驾，
鸿宝归亲贤。
元后上圣姿，
神龙潜虞渊。
乘乾奉天祐，
皇极建冲年。
百辟迎代来，
凝命居清玄。
皇风仁偃草，
一日周九埏。
震霆雨作解，
赫曦清旻悬。
除凶力摧虎，
猰㺄犴重键。
击冥走鬼魅，
好问广询延。
急治热愿濯，
从善坂流圆。
响答朝至昃，
万几无停宣。
泰否一往复，
乾坤随转旋。
昔自尧舜来，
神化无此前。
声休度百王，
九庙光蝉嫣。
天禄永无疆，
圣治终始全。
臣诗属先驱，
三灵赫临鉴。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_401','过湖','祝允明','明','纡回苍璧带，
平莹玄铜鉴。
昊旭悬邃霄，
光景高下湛。
周览总一天，
纤埃焉受犯。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_402','出高淳县望宝积寺塔','祝允明','明','岩邑无闉阇，
出市即郊隰。
凄凉木石寡，
衡纵畎浍袭。
微阳广土被，
厚霰蔓草浥。
四垂天茫茫，
忽觏斯独立。
檀栾布牙角，
亭突树磴级。
卑压荟翳丛，
明标粉黛岌。
遂疑廛井络，
仍谓贤圣集。
旋行迩复遐，
窥户廓沈戢。
游烦少解散，
空谛亦丛及。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_403','喜雨篇送推官李公','祝允明','明','三农病焦裂，
百姓慕来苏。
焉知皇运仁，
下土不终瘏。
良风助玄云，
洒淅散膏濡。
农人餔在野，
蔀室欢妇姑。
拜嘉我李父，
驾言忽王都。
愿挟怀中泽，
呈君被九区。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_404','送盛斯徵中丞巡抚江西','祝允明','明','公昔危言行，
忠信严操持。
抗节抑权近，
独结明主知。
腾波百低昂，
底柱无亏移。
况兹唐虞朝，
旰夕须皋夔。
龙升云亦高，
松老节益奇。
眷言命召虎，
江沱烦抚绥。
愚濞狂悖来，
十民九颠痍。
于今保治要，
邦本最先宜。
公岂无素鉴，
次第将裁施。
格君虽美谈，
宁邦幸沉思。
世愿与史声，
岂独乡人期。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_405','送徵明计偕御试','祝允明','明','恭人当远别，
思念畏寅送。
讵惟离群怅，
吴邦去光重。
奇珍不横道，
遄为宗庙用。
君其保气体，
讯问慰寤梦。
鄙夫谁向扣，
日益守空空。
时来玩鹓雏，
頫仰见翔凤。
怠赋李陵诗，
愿为王褒颂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_406','鹤章','祝允明','明','归命礼昊乾，
肃筵事三清。
真功仗宸官，
得此金门卿。
碧牍函赤心，
法步凌紫京。
八霄青㳽㳽，
刚飙别曾城。
独驰丹元叟，
直诣太昊庭。
紫皇已传命，
仙驾垂云征。
翩翩三缟衣，
上下相承迎。
翔卫既通奏，
矫羽歘上升。
安得如几飞，
淹留悦欢情。
傍嬉臣讵同，
畏威敢为荣。
始知精贤师，
可以彻土诚。
铭襟永攀脩，
玄祉庶获并。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_407','汎舟登郡西诸山作','祝允明','明','西岩蔚春气，
丹翠绚长霭。
结驷出阊门，
日华浮羽盖。
晓市凑万响，
方言九州会。
青翰迅妍洲，
遥遥背城迈。
中流箫鼓鸣，
连甍夹堤起。
莺吟方树底，
鸥舞澄沙际。
柳坂少依依，
花溆始綷䌨。
逶迤度重岭，
宛转入蒙荟。
欣遭胜域奏，
虑遣俗累解。
薄暮风咏归，
华月漾玄濑。
鸣笳震水关，
登陆且回憩。
遨翔吁可乐，
来往日月代。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_408','杂吟','祝允明','明','青阳肇物观，
披览川隰外。
草木寒不荣，
玄鸟阒未至。
高原有松柏，
亦为蠹虫败。
繁华须臾间，
后凋亦自贵。
惟望多麦禾，
麦禾可卒岁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_409','杂吟','祝允明','明','春日欣载阳，
凄飙霾曀蒙。
玄云何许集，
昼夜弥衡穹。
孤阳秉光淑，
元化潜开通。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_410','杂吟','祝允明','明','高楼临道院，
舒目乔林端。
天际浮云开，
遥见江上山。
山中有禹书，
竹简锁石函。
我欲往求之，
试寻古道观。
惟恐云复合，
驾言空去还。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_411','杂吟','祝允明','明','凤皇粲德文，
和鸣亦嘒嘒。
举世未曾见，
众口称丽美。
唐虞有至治，
千载盛传闻。
学者抱典谟，
终年向人论。
舜死凤不来，
寒士长欣欣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_412','赋得春阳曲戏柬天文','祝允明','明','钱唐苏小小，
京洛董娇娆。
秾芳竞桃李，
清润并琼瑶。
颓山左右倚，
因风上下飘。
东邻不姓宋，
无吝一相邀。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_413','秋日作','祝允明','明','危阳既骄夏，
衰霖复伤秋。
夏骄众夫病，
秋伤田畯忧。
少壮且颓堕，
耆人衷百愁。
万物蒙化成，
圣贤岂有谋。
栖栖非为佞，
驾言我焉求。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_414','偶述情事','祝允明','明','投弁归柴荆，
时晦企遵养。
颇谐筑搆庸，
亦遂灌植赏。
素履暮已定，
空法独结想。
自甘娄生戒，
无论□□□。
衷和亦气谧，
焉足问直枉。
违俗柰束扰，
钩校既非尚。
物理不爽铢，
答应难绝响。
一旦□□□，
□□□□鞅。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_415','为张孝廉题留犊图送吴邑杨明府','祝允明','明','东京扇廉耀，
风流逮当涂。
时子牧淮甸，
解犊振清模。
介石似灭顶，
千载不数夫。
安知后代士，
裂肤韫明珠。
邕邕杨夫子，
抱琴宰东吴。
盂水谓食洁，
户儿言恤孤。
虞廷奏箾韶，
凤凰翥宸都。
谁能献丹青，
清风拥前驱。
复愿写县壁，
告彼新尹图。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_416','赋得君马黄送黄翰林','祝允明','明','君马黄，
臣马骊，
骖以骥马来何迟。
骊马善折轴，
骥马不失驰。
天闲卫龙驭，
终不到瑶池。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_417','送黄翰林','祝允明','明','阊门车马出，
杨柳绿依依。
龙楼清梦起，
开阁待君归。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_418','送黄翰林','祝允明','明','江山司马笔，
民物杜陵吟。
他年黄阁里，
便是此时心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_419','诗四首','祝允明','明','盈盈高楼女，
粲粲红粉妆。
灼灼耀容华，
粲粲□衣裳。
丹唇激浩齿，
鬒发婉清扬。
□□□闾里，
□□□洞房。
见者惊若神，
翘首仰辉光。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_420','诗四首','祝允明','明','名都多秀艳，
三五骋神逸。
六门交长衢，
窗中坐晓日。
行行万夫望，
□□不可匹。
君子严礼聘，
承筐富充积。
嘉耦□好逑，
高堂鼓琴瑟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_421','诗四首','祝允明','明','珠玉含泽辉，
妖女□容华。
门巷多履綦，
□冶市门誇。
纷纷容悦已，
日暮宿倡家。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_422','诗四首','祝允明','明','巍巍西山高，
湛湛山下水。
昂昂千丈松，
靡靡百草委。
下有虎魄伏，
上有兔萝倚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_423','答黄鲁曾','祝允明','明','昔与君子别，
朔雪正霏霏。
惠音阻良觌，
叹息避炎威。
偃卧怀夙昔，
风雨渰凄凄。
磊磊井上松，
秋菊晚相依。
倏忽时候变，
星霜迅若飞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_424','怀知诗','祝允明','明','入室芝兰始见熏，
也知孤陋合离群。
烟霄本自冥黄鹄，
城市安能驻白云。
震泽晚山青历历，
漕湖秋水碧沄沄。
相思只借中天月，
会把清辉两地分。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_425','怀知诗','祝允明','明','七十看花岁已残，
始怜梅蕊照衰颜。
河清可道遭逢易，
驾俗深惭会合难。
锦绣段间藏黼黻，
骊龙珠抱媚江山。
欲留光彩无穷事，
心绪悠悠竹素间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_426','怀知诗','祝允明','明','我居廛陌子沧洲，
望隔江城各倚楼。
共惜贾生违汉室，
岂知王粲重荆州。
青云尚恐终难附，
白璧空怀未尽投。
十载三都墙室满，
不堪玄晏思悠悠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_427','怀知诗','祝允明','明','舞勺歌诗把袂俦，
白头俱换旧乌头。
深怜武库空怀宝，
却羡名宗独缀旒。
击壤舍君谁作伴，
看山无我不成游。
酣歌李白襄阳曲，
掌上隋珠国已收。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_428','怀知诗','祝允明','明','薰茗清谈午夜陪，
诗筒拂旦又飞来。
应怜去日多来日，
却见千回似一回。
槐院定酬王祜志，
兰庭休起卜商哀。
红芳落尽青青在，
始信松筠是德材。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_429','怀知诗','祝允明','明','行藏踪迹只云萍，
一种神襟尔我形。
清角痛悲鸣晋鄙，
黄钟力挽向虞廷。
丹山凤去尼丘叹，
紫府龙归霅水灵。
昨日书来泪盈把，
南溟心语到东溟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_430','怀知诗','祝允明','明','渚萍漂泊合江蓠，
并逐东流更不移。
岂独松篁能晚节，
共抛簪绂向明时。
烟霞草树春容与，
霄汉星辰夜陆离。
惭愧逢人说桑梓，
只如黄卷对光仪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_431','怀知诗','祝允明','明','文征屡北道空南，
云锦才华织女惭。
宗庙岂能瑚琏舍，
蛟龙未许土泥弇。
襟期天合胶投漆，
光彩神惊玉在函。
不见书来诵书序，
相望浑欲泪毵毵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_432','怀知诗','祝允明','明','穆穆文定，
渊渊金玉。
风被四远，
誉髦归淑。
伊余小子，
钦承在夙。
籋云骏附，
潜泥蠖伏。
嗣林衔恤，
閟息茅庐。
扣户请益，
拱肃趋隅。
教曰勖旃，
竭景劬书。
默尔富获，
单辞靡馀。
选曹展丘，
俾书皇纶。
山房接夕，
返楫同津。
永言夙好，
傍谂前闻。
虚膺秪受，
充然万珍。
公耆后先，
三四及门。
一瞻百益，
矧曰终身。
望之如日，
就之如云。
大雅既丧，
悼霣徒纷。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_433','怀知诗','祝允明','明','肃肃文恪，
有严我师。
扣竭空鄙，
博约兼资。
片语必法，
寸履皆规。
甘雨中含，
滋浃时熙。
屡踬于征，
靡辞有戚。
公荐以升，
黄阁有职。
援呼曰三，
导掖谟百。
嗟予不肖，
鼎冶负德。
邦作封史，
来相予总。
谓言冢君，
车迎馆奉。
力襄怀报，
宁公戾众。
公往趣成，
傍诮莫诵。
公闻斯愠，
命我专统。
谓守载属，
同群益汹。
终亦靡克，
公忾滋勇。
有矢毕命，
卒队兹恐。
公归在堂，
复侍函丈。
三变泰如，
扬休弥畅。
湖山奠高，
风霆下上。
嗟子懦与，
弗从以往。
中星载回，
遄失几杖。
梁木既坏，
吾将安放。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_434','怀知诗','祝允明','明','司徒岩岩，
四海具瞻。
孰不敛衽，
植偃砻顽。
蒙逖以卑，
霄丽泥蟠。
讯之招之，
令之曰前。
旭日垂熙，
温诲孔殷。
昔我先公，
政于晋阳。
知公于童，
拔立序庠。
范之德行，
训之典章。
古道世用，
启迪游扬。
声诗书画，
亦靡不详。
曰尔国器，
必成用光。
公曰于乎，
前德不忘。
乃共之食，
乃赐之帛。
严威俨恪，
靖庄允塞。
拜赐必諴，
餐德必实。
一望弗再，
有衔以讫。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_435','怀知诗','祝允明','明','有华东阳，
烨于吴门。
古有遗高，
展也兹存。
孰为先生，
秀降三辰。
胸集万宝，
手挥五云。
九渊湛映，
千茝齐芬。
鹤跱霄逵，
抗百风尘。
维予二祖，
式契且姻。
亲公自髫，
属于夕昕。
齿惟父子，
视犹季昆。
聚晤员员，
援推勤勤。
谓子良史，
左丘马班。
谓子鹏运，
直举横鶱。
安知乘马，
班如迍邅。
终需于泥，
以卒岁年。
余既暮矣，
公犹岿然。
于何不臧，
自遐不因。
一往不复，
追悔空辛。
岂念平生，
我思古人。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_436','怀知诗','祝允明','明','昌哉我牧，
百夫之特。
瞬洞万棼，
平吞四渤。
经库储学，
智囊韬识。
鸾刀一振，
百截以讫。
吴材总升，
胡特我特。
载笑载言，
载咏以绎。
有作斯属，
惭孤善述。
冥留灵逝，
奚赎身百。
九京有知，
有茹阗臆。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_437','怀知诗','祝允明','明','陆缔于我，
好也奕世。
中丞汪汪，
视实兄弟。
翔泳殊能，
逵磐别致。
川梁无接，
櫑镡遥契。
南都于遘，
日以文会。
勖哉进修，
驩然游艺。
鸥鹭先盟，
江湖结气。
公绩平寇，
尚克铭纪。
首聚须臾，
夙约载厉。
迨登掌武，
爰均四海。
迹用地隔，
礼有嫌废。
穹渊契阔，
恍若越世。
恩谴公被，
不才余弃。
聚散忽再，
幽明永异。
终则群疑，
始亦何讳。
丹诚寸积，
悠悠两在。
天吴昼掠，
鳌波夕沸。
芒芒大壑，
魂兮何寄。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_438','怀知诗','祝允明','明','秀矣孝廉，
名驹在谷。
白玉清冰，
碧梧翠竹。
少游诸老，
孤莺乔木。
予家日见，
匪暝维夙。
黄庭晋度，
朱弦汉曲。
群公星落，
长庚尔独。
后生更仰，
鸡群昂鹄。
颓然顺化，
行阅沧陆。
修年默逝，
亦可世哭。
雅绪君断，
更莫彼续。
来英日富，
风流绝目。
前修履践，
流膏碎馥。
嗟子勤哉，
堆箱叠腹。
繄我与君，
髧皓相逐。
今我视众，
如君我瞩。
馀霜犹几，
三叹不足。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_439','怀知诗','祝允明','明','葑亦多彦，
哿矣两朱。
昆丘连璧，
峄阳双梧。
子出最后，
遗风爽如。
寒泉冬洁，
菉竹秋臞。
积百媚学，
孰俪君劬。
宵闻片籍，
屏寐以须。
失之皇皇，
获之愉愉。
抛裘喷炙，
投玉捐珠。
珍香宝茗，
法绘名书。
清谈晏对，
日坐仙区。
爱我维笃，
弃我亦徐。
怅其邈矣，
临风永吁。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_440','挽歌诗','祝允明','明','清晨出阊门，
丹旗何飞翻。
问之路傍人，
新鬼即幽坟。
翘望旗中题，
知吾夙所敦。
昨朝华屋间，
哑哑相笑言。
日月略流转，
幽明已异门。
昔时强仁义，
兹辰声益尊。
属徒送自返，
妇子亦一喧。
君独长甘眠，
不知悲与欣。
由兹寿无垠，
万秋如一昏。
零霜杀宵草，
绕山游微魂。
游魂不复贵，
所慰行节存。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_441','黄金篇','祝允明','明','灵质自化育，
英姿藉炉锤。
虹光衡煜煜，
晨曦纵焞焞。
紫霞煽虚燄，
青渠晕幽蕤。
在镕未云卜，
跃冶讵其宜。
能函大钧体，
伏型韫神奇。
何当错宝铦，
戮妖血荒陲。
鸿秘已出柙，
勋用吾未知。
痎市碎砧斧，
交易方纷披。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_442','题隐士山居','祝允明','明','志士果藏隐，
胜境合冲閒。
冥冥讨幽赜，
息躬搆深山。
青萝施櫩宇，
循除鸣流湍。
绨韦积皮几，
时衡素丝弹。
出郭便无累，
何烦嵩华艰。
危岑寄远气，
屹矣不可攀。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_443','唐人写蕃马图','祝允明','明','天山一夜雪，
北风吹复乾。
健儿骑马出，
踏碎白琅玕。
薄醉拥貂裘，
日暮不知寒。
季冬飞鸟绝，
虚弦控不弹。
焉知北海雁，
高翥入长安。
帛书天上度，
何功报可汗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_444','家藏马远春山行乐大幅','祝允明','明','淑候媚川石，
初景澹林霏。
扶藤循石坂，
杨柳共依依。
朱弦卧行襆，
随往抱希微。
无论遇高赏，
器在道无违。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_445','戴文进松崖','祝允明','明','阴崖万古县，
横出千岁松。
中有落涧遥，
怒跃数白龙。
长年不闻声，
发卷耳欲聋。
远楚夕莽苍，
町疃回照红。
此域万物静，
尚有坐二翁。
何必非夷齐，
破衣萧萧风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_446','刘西台画松','祝允明','明','何年楮先生，
结此太古骨。
飞龙蜕胾肉，
馀甲裹枸橛。
神根发生理，
元气日勃勃。
彭城已廿载，
此骨长不没。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_447','题画','祝允明','明','白云媚苍山，
寂寂太古春。
窅蔼林薄中，
一区宅无邻。
杨子坐清静，
闭门了玄文。
两生勿轻过，
惟通问字人。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_448','秋山琴月图','祝允明','明','玉照洞秋，
冰厓肃夜。
灵籁之感，
丝音兹舍。
太阴幽煌，
希声无倪。
迎之以虚，
承之以微。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_449','咏新安许氏石潭','祝允明','明','沈沈山下潭，
粲粲潭中石。
结宇子亦贤，
喜作石潭客。
将同丘生栖，
可有奇章癖。
兹标本余契，
遐咏亦驰适。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_450','次韵得之看梅','祝允明','明','江梅不畏寒，
时至开如霰。
瑰姿静在野，
卧病不得见。
国士抱奇宝，
端居察时变。
杖策出城市，
蒿莱满荒甸。
遐寻得幽赏，
独对姑射面。
化泰草木蕃，
时闭贤不见。
无禾比两岁，
□□将九县。
分圭善会计，
弃士如土贱。
俗儒诵腐简，
乡子乐耽燕。
熹歌唐虞授，
复誉汤武战。
子有经世怀，
待贾不自献。
神威盛龙熊，
奇秘卷帐钤。
时节会应求，
风虎期非晏。
巍然奋载绩，
志沛声亦建。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_451','草阁玩水图','祝允明','明','濠上有川叹，
沧洲多海怀。
伊我江湖姿，
浩荡中渊回。
寻秘右洞庭，
飞衿左蓬莱。
瑚琲探富获，
存之无轻开。
扬波万古源，
荡潏塞视埃。
谁能写小笔，
聊意亦可谐。
仁智在户限，
寄言亦悠哉。
临咏志一启，
得者亦可推。
黄汾窈如湮，
安问傅岩才。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_452','长安秋','祝允明','明','长安昔日在关中，
洛阳浙右亦相同。
江东自古帝王宅，
周秦已见气葱葱。
长道石城如踞虎，
长道钟阜似蟠龙。
千年王气浮天表，
一日真人建法宫。
天府天开天阙起，
五门三殿当中峙。
五凤楼前柳似烟，
奉天门外天如水。
金陵金阙胜金城，
玉陛连天接玉京。
星散羽林霜气肃，
天临华盖日华明。
十二飞楼石门缭，
百万貔貅屯八表。
宝刹天花和月飞，
郊坛神乐穿云窅。
御史当街百骑骢，
将军纳陛罗霜锋。
五侯甲第遥迷雾，
七贵前驱响斗风。
凤凰台上凤凰游，
玄武湖中水似油。
万户莺啼花里晓，
千家砧捣月中秋。
会同馆外白雉多，
包茅楛矢交经过。
重译来宾醉卉服，
轻烟澹粉列青蛾。
六楼六馆斗倡妍，
曰日新声沸管弦。
狭市斜街迷错络，
曲房洞户暗钩连。
吴下书生好远游，
抱书来看帝王州。
那知高卧西风邸，
蓬眉萧飒长安秋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_453','吕梁行','祝允明','明','吕梁县水三十仞，
于今汹涌乃安流。
禹平水土通九州，
当此徐兖间，
罔水破山始行舟。
仲尼逢至人，
其言载庄周。
尔来二千年，
高者乃夷衡者揫。
鱼虾龟鳖不可过，
飞鸟临之回翔不能留。
嗟尔东西南北之人，
胡为此中游。
到京忘家，
归家忘京，
不知此险死生隔，
其中为心喉。
痡人皆化为至夫，
吁嗟乎孔庄之叹空悠悠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_454','歌风台','祝允明','明','掉臂长安市，
遥从日边来。
因过芒砀下，
步上歌风台。
沛公善任使，
猛士亡其骸。
帝业袖手成，
慷慨襟抱开。
大风飞云亦壮哉。
韩彭英卢相继死，
寄命寺人髀股间，
未央志气拉飒摧。
相望千年馀，
安能为之哀。
明朝放舟淮浦去，
项王韩侯祠下亦徘徊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_455','答孙山人寄吟卷歌','祝允明','明','秋风落叶露为霜，
美人去我天一方。
只知朔雁翔南去，
宁解鱼书可寄将。
分开尺素云生手，
濯濯芙蓉倚杨柳。
金丹荧荧伏鼎灶，
宝剑时时拂河斗。
仙韶本是清都乐，
欲奏人间舞群兽。
去年送别吴王台，
屐齿微踪长绿苔。
相思每望秦川月，
寄信俄逢越使来。
越使能寄书，
不知书中意何如。
君能寄诗卷，
不知我肠车轮转。
李白上天鲍照没，
此声何处君留得。
霞为衣兮月为泽，
金光草兮换君骨。
二子雄风不可寻，
九霄星露夜沉沉。
但看一片千年月，
悬向青天照我心。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_456','送徐先辈','祝允明','明','吴王城中三月春，
吴王城外送行人。
飞花乱扑长江去，
条风东来布帆举。
将留欲舍心趣多，
难行难止柰君何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_457','招凤辞送弹琴杨三游金陵','祝允明','明','玄桐挂朱丝，
碧轸黄金徽，
独抱登高台。
坐石上，
时一挥，
清商不如清角悲。
凤来归，
凤来归，
高台红日丽秋晖。
秋晖欲落兮，
凤来不来。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_458','任月山九马图歌','祝允明','明','古人颂马自鲁駉，
杜诗尤胜伯乐经。
近代画马称曹韩，
后来独数李龙眠。
世无神手有神马，
眼底谁能分造化。
邹阳示我轴有咫，
惊绝纵横电光起。
定观始识任都水，
马后金声出吴李。
房星九点光殷殷，
天文地类相斓斑。
龙媒无种世亦产，
何必置牝宛代间。
于今不乏十二闲，
如此久堕文书寰。
前年禦戎急刍骑，
何不引此踏贺兰。
呜呼九骏安得归龙班，
一匹可以当三千。
吾言亦能道塞渊，
尔尚伏枥吾何言。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_459','俞汉远云山图','祝允明','明','洞庭之南潇湘西，
湿云从龙凝不飞。
九疑纵横不可辨，
二女望断重华归。
山河茫茫都一暝，
仙宫隐入层霄迥。
水浒浑迷行路踪，
云端忽露青枫顶。
披图亦觉乱心曲，
嗟尔良工意何局。
人间晴雨相倚伏，
秪在君手一翻覆。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_460','曹民部藏何太守山水障歌','祝允明','明','苍烟横晚江，
江树不可辨。
远山虢国眉，
近山鬒不变。
谁将元气夜半翻，
凌乱少陵好东绢。
幽人绝流一苇航，
应恨可人不相见。
千村万落路不通，
恐有闭门忘世翁。
孔明渐老安石卧，
谁为苍生起卧龙。
须臾云树开苍茫，
始识九疑分潇湘。
良工出自何水部，
妙思已落陈思王。
陈思王，
今葛谢，
袖中翛翛有造化。
萧斋晏坐对图画，
时发云霖润天下。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_461','怀施侍御儒遂赠','祝允明','明','崇堞倚紫冥，
丹谯摩空青，
城中树稀无鸟声。
昨日闻公入朝列，
相思一夜肠欲绝。
古人不可见，
今人交多面。
古人千载只可慕，
今人可慕难可遇。
君离越王台，
吴王台下来。
执手一徘徊，
销尽万古胸中埃。
与君交一日，
一日一日益。
交君未渠央，
我长不可极。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_462','怀施侍御儒遂赠','祝允明','明','岭南古松气森森，
如君此时之古心。
蜀山椤梓蟠天回，
如君卓荦之奇材。
文章黼黻溟海深，
令言徽行贵兼金。
天子策名作进士，
选众举为侍御史。
巡行塞徼安远人，
谏诤朝廷厉风纪。
馀力千诗百赋成，
四散江山被绣绮。
丈夫行道志大申，
勋名禄位极此始。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_463','怀施侍御儒遂赠','祝允明','明','关关雎鸠在河洲，
妾事君子愿到头。
红颜虽薄志贞固，
脂泽履綦亦自脩。
鸳鸯锦囊凤绮琴，
蕙筵兰室奉徽音。
金壶玉卮为君斟，
无将管蒯败昔心。
愿为南山之松柏，
不为鹤鹄之离禽。
天道人性此最至，
人伦尽然同古今。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_464','送方行人新擢南道侍御','祝允明','明','彤门九重远万里，
四海平康此中起。
六月七月杂暑雨，
街泥才乾行沮洳。
送君都门东，
堂堂仪貌清且雄。
手持绣斧骑花骢，
丈夫意气凌紫虹。
飞帆南指青冥度，
石城微茫绕烟雾。
明月娟娟淮水楼，
晴霞苒苒钟山树。
玄武湖边揽苍翠，
北睇皇居想安寐。
何以献之缄皂囊，
一日三发迅鸟翔。
君能言，
君理尽。
君言安得皆流行，
一日三发翔鸟迅。
酌君玉壶之美酒，
赠以锦橐之琼琴。
清尘弱水自此隔，
天涯日望瑶华音。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_465','北崖行','祝允明','明','君不见吴江汝君子，
性如山善如水。
胸蟠万卷帝未知，
坦腹高眠故园里。
明珠无渊不可含，
白玉须蕴巉𡽳间。
剪琼截璧为小山，
植朵芙蓉浸潺湲。
花木被皋隰，
鸟鸣相关关。
汝君子，
居盘桓，
澄怀共高閒。
揽苍苍兮瞻岩岩，
恍然卧游穹岩邃谷，
一日数十独往还。
蓬莱近东隔弱波，
衡庐南见空嵯峨。
人间大山西北多，
太行恒华不得并列将如何。
我山不在大，
俗驾不得过。
题名曰北崖，
高揖祝公为我歌。
我歌北崖兮气势上与浮云齐。
光景凌乱干虹蜺，
撑星挂月拂紫微。
崆峒倚天剑，
昆崙升仙梯。
女娲遗子今日补天阙，
或作笔柱写帝黼黻扬鸿辉。
斧钺奸宄乱贼，
定君臣是非。
礼乐制作，
风雅发挥。
汝君子，
北崖为子悦性情成功名。
请歌北崖行，
金石千年标颂声。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_466','独当奇处行题何大参子元藏沈隐君画郴州江山图','祝允明','明','祝融峰高插南极，
东南郴江流不息。
桓圭削绿浸瑶池，
天下江山奇复奇。
昌黎序送廖道士，
地文争奇无比拟。
咄嗟道士不可当，
岂知今有何夫子。
何夫子，
谪仙人。
海外紫鸑鷟，
天边石麒麟。
才如宝剑百乱截，
文似万花天下春。
昔辞瑶京下九国，
仙姿萧飒难容得。
置之江山最奇间，
明珠辞辉玉避色。
沈君颇似能写真，
陈子善题濡笔墨。
何夫子，
归去来。
江山之奇亦小哉，
君有大道县襟怀。
我欲从之问消息，
郴江东去何时回。
东瀛弱水倘可渡，
与君握手登蓬莱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_467','讼风','祝允明','明','臣将众心笺天公，
一月不改东北风。
酸澌射人痛两瞳，
零乱百物纷蓬蓬。
炊烟作难幸出囱，
涕泪满面嘻何从。
苇窗楮帐羞无功，
禽鸟素少并绝踪。
鲲溟竭石海气通，
宁或鼓𩗗由痴龙。
六月七月如初冬，
风伯风伯听吾讼。
颠倒伏腊何强雄，
秪恐老天不君容。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_468','月泉篇','祝允明','明','道人号月泉，
邀作月泉篇。
道院常有月，
道院本无泉。
石坛空歌罢，
斜倚长松眠。
竽籁尽沉寂，
云烟纷绵联。
上有黄玉顶，
下有碧瑶渊。
心赏极神畅，
不测何名天。
恍然欠伸双瞳开，
手握碧萝，
脚蹑紫苔。
犹是朝元之宇，
步虚之台。
人间少玄境，
况此百肆万火中，
安有广寒与蓬莱。
吾闻太湖之傍洞天之幽，
千山绕缭相罗周。
其间飞珠喷玉，
贯穿漱涤多异流。
夜夜玉镜飞上千山头，
来印万壑金波滉漾寒光浮。
姮娥下浴魈魅避，
眼波莹照大九州。
授仙老以玉诀，
与三光而俱留。
道人已自梦中受得金锁流珠之洞文，
吞黄月而饮上池，
舞贝阙而遨蓬丘。
世间月泉空悠悠，
轩辕之孙尔同俦。
胸有日月袖有海，
能为道人作此讴。
向来院字多垢浊，
勿将灵诠语蜉蝣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_469','玉泉咏','祝允明','明','滴滴沥沥瑶佩鸣，
缥缥缈缈银河清。
权公妙句我斟酌，
醍醐稍重琉璃轻。
八功德水发源处，
分来南部深公许。
六指道人隔墙住，
床头共听无舌语。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_470','短长行','祝允明','明','昨日之日短，
今日之日长。
昨日虽短霁而暄，
今日虽永阴复凉。
胡不雨雪为岁祥，
胡不稍暖开初阳。
徒为蔽天氛曀日，
黭黮人物惨懔无精光。
物情望有常，
造化诚叵量。
气候淑美少，
君子道难昌。
阴晴长短不可问，
古来万事都茫茫。
独怜穷海客卧者，
魂绕江南烟水航。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_471','月乌篇','祝允明','明','吾乡沈郎字仲宽，
为我遥索月乌篇。
月乌喻孝与客旅，
二者未知心所安。
孝为百行大且初，
鸟中曾参人不如。
吾闻沈郎孝且才，
即此乃是曾之徒。
寒光满林莫返哺，
哑哑叫断肠欲枯。
我今南飞依棘枝，
为子仰天强哦诗。
乌啼月落粤山低，
一夜魂游吴苑西。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_472','赠盛翰林','祝允明','明','卞和能识玉，
荆山得良宝。
知玉不知人，
屡刖自残槁。
孟尝有内珍，
何意货贿间。
灵物不能舍，
神珠自来还。
盛公抱天瑞，
手把山龙章。
惓与时人观，
放之瀛壶傍。
朝披金光草，
夕悬明月珰。
适从具茨来，
独宿白玉房。
凡夫亦知宝未得，
先生傥肯示以求之方。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_473','凤凰篇','祝允明','明','翩翩双凤凰，
飞集南海傍。
众鸟往从之，
不弃老秃鸧。
凤凰自飞来，
只在海傍宿。
人为天下祥，
我为天下哭。
凤鸣四海清，
老鸧亦解啾啾声。
老鸧无凤姿，
笼中拘辱不得争。
凤凰顾老鸧，
相慰勿自伤。
老鸧荅凤凰，
凤兮知老鸧。
老鸧只在草莽伏，
物遇其类心凯康。
但令凤凰联翩上阿阁，
老鸧百岁没向江湖亦足乐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_474','王提醝画古松歌','祝允明','明','人言松有节，
不见节如松。
问渠老叶终年翠，
何似妖花三日红。
人言松节劲，
不知松气融。
元和畅生意，
华茂春葱葱。
和流则不强，
苦节亦道穷。
王夫子，
和气满胸中，
守道百鍊之青铜。
画史颇善喻，
为君写古松，
予亦为君歌古松。
古松歌，
君柰何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_475','乐孺歌','祝允明','明','渚鸿不侣鹜，
联翩入紫云。
有时下同宿，
终然不离群。
磊落千金马，
贡作万乘车。
双双翼飞龙，
齐秣亦齐驱。
驰翔有美世共珍，
列之天闲织其文，
以章有德劝百臣。
苍鹰虽鸷豺狼猛，
安得称重于其伦。
阊门今古道繁华，
歌钟日夕沸如麻。
东邻宴公子，
西舍酣倡娃。
谁人堂上题乐孺，
中有二士为奚家。
先人应能积为善，
天锡一双白璧皆无瑕。
伯兮友仲兮悌棠华，
韡韡风光媚。
架有互服衣，
榻有共覆被。
入室谐兰香，
出门偕远志。
仗剑作长游，
千里万里亦同次。
番禺城下我逢之，
三人相携共一醉。
醉中尚能为尔歌，
歌此敬多感亦多。
吴中土风清且嘉，
今如君者有几何。
君家伯祖我祖高，
弟子文名风节犹嵯峨。
乃知仁人有后世济美，
看尔富寿方来百福如山河。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_476','孟玉涧画瓜','祝允明','明','溧阳夜燕来仲虚，
示我玉涧画瓜图。
嫣绵生意好手笔，
灯前摸索聊为娱。
尔日南至气转纾，
我心之喜君知无。
黄台离离几抱蔓，
野田倘有青门夫。
焉知大瓞方包杞，
含章陨天天下理。
天地相逢与子起，
品物咸章自此始。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_477','题徵明写赠潘崇礼灌木寒泉大幅','祝允明','明','具区之水被三州，
洞庭之树千万数。
沉森浩㵿天下奇，
灌木寒流此何许。
潘君抱朴山水人，
日日策杖独行遍沧浪之滨。
阳崖众目悦暄媚，
忽逢阴壑如有神。
禹锁老龙铁索绝，
拿云怒雨出洞穴。
木号水呼竹石裂，
众蛇从之互盘结。
蜕骨戌削杂鳞鬣，
飕留风叶枸株橛。
急流抨撞石罅跃，
珠跳汞走斗瀺灂。
微茫上析河汉，
注奔赴绕伯若方丈脚。
山鬼伏窥木客泣，
欲据恐被山伯抶。
仙老时下憩，
濯足而晞发。
招潘君兮子来共千岁以一息。
潘君归语衡山氏，
仙之人兮不可以久留，
吾恐一往与境俱失。
宣州兔肩毛劲如石，
深醮金壶玄玉液。
闭门夜半役鬼工，
倏忽移来窅无迹。
支山谓潘君，
张君高堂白粉壁，
焚香日坐对，
明月之夜风雨夕，
仙伯谓我当来觅。
携君卷图愿写照障入怀袖，
与君骑龙返无极。
馀影终非世中物，
谢绝宾客扃此室，
门外有人勿与识。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_478','卧病怀勉之二首','祝允明','明','郊原行中春风颠，
闭门缩脚七日眠。
惟怀落落五岳客，
仰头抱膝作何物。
尧舜殂落文王没，
仲尼寂寞书在壁。
山川结阴草木僵，
驰今骋古皆未得。
携君璠玙之乐来，
黄金香炉紫玉杯。
烧沉爇蕙降古杰，
共听君手奔风雷，
颓然一醉万事开。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_479','卧病怀勉之二首','祝允明','明','东园梅花白雪深，
大堤杨柳渐垂金。
欲往攀之烟雾阴，
美人观道坐空林。
洪厓举觞江妃斟，
素女鼓瑟容成吟。
我独栖迟卧萝屋，
咏君宝篇千万足。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_480','阊门歌送郭令','祝允明','明','鸡鸣角乌乌，
阊门将启涂。
船头卒徒拥，
屋底翁媪呼。
呼将儿孙起，
来送郭大夫。
大夫强汝柔，
大夫明汝愚。
大夫饱汝饥，
大夫康汝痡。
教汝兴礼节，
教汝诵诗书。
大夫舍汝去，
汝能不思乎。
君子悦其文，
细人念其劬。
说向君子道，
能歌歌大夫。
阊门开，
百姓怀。
云帆指金台，
天王御宇万国来。
万国来，
仰帝力，
王道荡荡，
平康正直。
天子岂不思，
思哉建皇极。
皇极建，
若三五。
大夫忠良伍，
志岂在朝暮。
清风穆如，
去者慰，
存者怀，
穆如清风，
怀其存，
慰其去。
穆如吉甫，
以永今古。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_481','首夏山中行吟','祝允明','明','梅子青，
梅子黄，
菜肥麦熟养蚕忙。
山僧过岭看茶老，
村女当炉煮酒香。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_482','梦与表弟王制彝卿表甥陈鳌子鱼散步河曲鳌邀饮其室觉而赋之写似二子','祝允明','明','三人连袂阊阖行，
二少年弟一老兄。
莫言蒹葭倚高树，
芳菲润映苍枝荣。
鱼也有酒旨且多，
彝也起舞我也歌。
渭阳棠杕声相和，
明日可如今日何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_483','悲秋','祝允明','明','年年吟叹到悲秋，
心语因循竟未酬。
日似宝珠轻易掷，
道如沧海等閒求。
爱憎衮衮风千变，
今古茫茫貉一丘。
老子自怜深兴近，
谯将双眼上南楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_484','旅情','祝允明','明','旅食惭工部，
分携念孟光。
岁时临俎豆，
风露警衣裳。
满月当春面，
明霞见晚妆。
情怀宜自遣，
看是买臣乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_485','江行','祝允明','明','丹阳连北固，
千里草萋萋。
东去水逾急，
北来身渐低。
渔舟长宿火，
客枕厌闻鸡。
风景年年是，
因无妙句题。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_486','看月怀内','祝允明','明','看他夫孺作娇称，
拟向君王觅与卿。
想得夜深刀尺罢，
推帘独自下阶行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_487','答钱二','祝允明','明','病喉少日兼辞酒，
养性经年不看花。
君问情怀看此纸，
新诗字字学唐家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_488','代东园梅见嘲','祝允明','明','祝家园里一株梅，
旧是三郎手自栽。
今岁寒花开欲尽，
三郎何处不归来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_489','燕京陌上游妓','祝允明','明','相逢无路避青蛾，
十五燕姬细马驮。
老眼年来观道熟，
妖娆知柰石肠何。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_490','宫词','祝允明','明','非谪非真是甚仙，
紫云横截大罗天。
依稀记得人间事，
十四封纱二十年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_491','咏都城赁骑驴马','祝允明','明','紫陌东西苦不禁，
朱门饱秣卧花阴。
知君未是登台骨，
休道昭王不挂金。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_492','沿潞河直达淮浒岸柳蔚然','祝允明','明','玲珑翠玉芳阴茂，
窈窕娙娥婉态多。
不是一行千万个，
荒天寥落柰情何。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_493','黄楼','祝允明','明','落日照徐彭，
长堤上下乘。
黄楼不知处，
洪水尚襄陵。
客子能怀警，
官亭试一冯。
波涛终古险，
来往自频仍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_494','卢沟桥','祝允明','明','四海修梁秪有二，
卢沟雄冠帝城边。
下临窅窅疑无地，
上接茫茫恐是天。
紫蜺平飞通碧汉，
白龙横卧破苍烟。
牛车百两春雷过，
愁压幽燕地轴偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_495','卧病','祝允明','明','同人相见总相称，
一级名阶只未登。
此事苦难多著力，
拙夫甘道实无能。
垆边岂有升天客，
榻上分明坐夏僧。
一片商颜半江水，
尽堪黄绮与庄陵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_496','宫词','祝允明','明','黄屋巍巍坐九天，
烟云千叠蔽婵娟。
流莺回首宫墙远，
妾负红颜二十年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_497','儿子续入对大廷感激因赋','祝允明','明','先公磊落传胪处，
老父迂迟失马中。
未必远寻晁董策，
青箱犹可献重瞳。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_498','儿子召试馆职','祝允明','明','黄纸书名已异恩，
玉堂观艺复何论。
持将宣室当前席，
幸有丹衷世世存。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_499','儿子召试后忝窃收录遂蒙钦改庶吉士留学翰林','祝允明','明','文帝弘谟远，
明王懋举初。
望应非曲学，
功欲得真儒。
给膳摅文思，
休朝读秘书。
养成台辅地，
嗟尔意何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_500','舟中忆续','祝允明','明','功名尔已誇雏凤，
情爱吾犹愧老牛。
怅望燕山云海隔，
晓风吹梦过沧洲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_501','追和皮陆夏景冲澹偶然作','祝允明','明','绿漫衡皋带茂林，
林亭遥对接疏襟。
江涵竹影铺丰席，
雨浥梅蒸溽素琴。
槛水生漪浮澹炎，
栋云团盖落虚阴。
人间最是难消此，
未解尘名误道心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_502','娄江舟中述梦续事状','祝允明','明','相慰华堂下，
重逢草野中。
涂鸦犹习幼，
策马拯涂穷。
恩爱千年定，
精诚一刻通。
直能呼共老，
天壤有移鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_503','泪','祝允明','明','昔诵江东咏泪诗，
看来别有一般时。
孤衾独枕斑斑处，
半属吾亲半属儿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_504','泪','祝允明','明','鲁国潸然可柰何，
洛阳年少更能多。
静中怕似奸和妇，
换作临风两韵歌。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_505','壬申夏夜不寐','祝允明','明','冷暖光阴不尽来，
流年五十岂徘徊。
半窗明月三更后，
起步中庭几百回。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_506','苦忆','祝允明','明','苦忆京华更不禁，
百壶那解一生心。
争誇膝下簪缨好，
岂识痴翁别有襟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_507','对酒','祝允明','明','对酒无歌舞，
看天只咏诗。
唐贤文满案，
半是乱离词。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_508','山','祝允明','明','深坞高峰处处宽，
寻常歌啸等閒看。
城门欲闭无船渡，
却笑今朝要入难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_509','咏床头剑','祝允明','明','三尺青萍百鍊锋，
流年三十未开封。
藜床且作书生枕，
只恐中宵跃卧龙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_510','乙亥五月五日王佥宪文明邀宴庐陵螺川驿楼观竞渡','祝允明','明','提刑玉节照清江，
客子游观喜大邦。
夹岸鱼龙争得水，
中流笳鼓杂飞淙。
国谋幸驻襜帷问，
乡思微从俎豆降。
欲待梅花开后寄，
只应迁转忽移幢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_511','县斋早起','祝允明','明','县小才疏政未成，
披衣冲瘴听鸡鸣。
向来啸傲知多暇，
老去驱驰敢自宁。
有物解将王路塞，
何人填得宦途平。
拙谋果是因微禄，
好傍吴田晏起耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_512','归与','祝允明','明','炎洲闭户赋归与，
县尹何妨委巷居。
夺禄浪言耕有代，
旅行谁信出无车。
空惭河上深藏贾，
却笑关门强著书。
莫道文章误公事，
文章今误复何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_513','戏作口号','祝允明','明','道惠何曾惠，
言宁又不宁。
一春眠里过，
三日水中行。
坡老荔犹涩，
陶公酒未成。
哥哥浑不顾，
枉费万千声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_514','题广州客邸壁间','祝允明','明','故国间居四十年，
疏慵虽乐怕违天。
天应尚念疏慵态，
又使閒居瘴海边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_515','广州别表弟赵二','祝允明','明','江沱已喜干戈定，
吴越犹闻稻蟹肥。
把酒正看黄菊好，
凝眸无柰白云飞。
乡闾讯遗情亲减，
中外联行尔我稀。
幸为经营石湖畔，
秫田三亩一苔矶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_516','看山','祝允明','明','岭海看山旅思空，
归来还入画图中。
平生惬性仍知己，
只有青山处处同。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_517','冒冷行役','祝允明','明','谁使衰年冒冷行，
几般辛劳几般情。
重重楼阁深深闭，
家隔东南四座城。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_518','宦游句曲偶读丘殿丞寄茅山道友诗有感遂次其韵','祝允明','明','珠有馀妍玉有辉，
鸡栖鹤驭本相违。
灵飞碧检文难读，
想结金堂梦易归。
颇恨殿丞虚左契，
终怜长史入仙机。
悬知紫陌埋尘骨，
绿草茸深白鹿肥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_519','句曲道中','祝允明','明','老至谁怜昼锦明，
春来聊得客襟清。
宵依星斗宫坛卧，
晓入神仙宅舍行。
眼看山多城郭少，
肩挑诗重簿书轻。
何时总入烟霞去，
不见人间宠辱惊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_520','伤','祝允明','明','三年两度哭亡儿，
莫怪衰翁舐犊痴。
谁使为生便为死，
可堪成喜亦成悲。
青蛾怨积兰枝梦，
黄壤能酬瓜瓞期。
等是人间慈孝事，
□□□□□□□。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_521','口号','祝允明','明','枝山老子鬓苍浪，
万事遗来剩得狂。
从此日和先友对，
十年汉晋十年唐。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_522','口号','祝允明','明','不裳不袂不梳头，
百遍回廊独步游。
步到中庭仰天卧，
便如鱼子转瀛洲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_523','口号','祝允明','明','蓬头赤脚勘书忙，
顶不笼巾腿不裳。
日日饮醇聊弄妇，
登床步入大槐乡。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_524','病卧北牖仰见飞鸢戾天忽然口占','祝允明','明','海国秋炎紫汉空，
一声深入太霄中。
回看五岳三山近，
略望千流万壑通。
未必䌽鸾能瑞世，
可怜黄鹄不离笼。
因思兜率黄金地，
金翅擎波护鹫宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_525','宝梦','祝允明','明','窗外星河五鼓天，
香凝纸帐裹云眠。
遥寻鹤梦游尘外，
却怪鸡声到枕前。
拱璧光阴悲此日，
怀珠奔走笑当年。
知音总没惟怀古，
卷里相看共默然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_526','衰病','祝允明','明','半年衰病入秋深，
减却肌肤长道心。
不省门前犹市井，
忽瞻墙外是祇林。
一端惟静为甘味，
万绪都忘遂苦吟。
□□□□□□□，
□□□□□□□。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_527','病閒','祝允明','明','病閒身懒趣偏长，
书策纵横掷满床。
医业探寻胜士业，
闺房清寂似禅房。
青春总误今何及，
白昼长閒梦始忙。
此境可留终岁月，
岂须重觅引年方。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_528','沧浪池','祝允明','明','出巷少人烟，
林霏四望悬。
冷光涵曲径，
沉绿漾平涟。
古寺依文殿，
高城瞰野田。
每经思版筑，
忘世更怀贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_529','夏日游慈云寺','祝允明','明','命俦乘暇日，
散步入慈云。
野气能遥接，
秋光自独存。
小山侵竹尾，
细水护松根。
众果都连苑，
繁花杂植园。
废兴徵老衲，
文字哭孤孙。
却幸重来好，
禅床许北轩。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_530','舟过故表伯父王氏宅前有感','祝允明','明','轻舟独汎午时风，
车马当年一日空。
绿水青门映红树，
一时都入感伤中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_531','泊嘉善东桥','祝允明','明','石梁磻水浸秋寒，
一夜霜篷寄钓竿。
是处风光解题品，
江湖莫作旅人看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_532','途中即景','祝允明','明','地迥景逾胜，
数程无市人。
隔篱花脕腆，
临水树精神。
村犬随船吠，
沙禽见客亲。
渐看明月上，
夕韵想更新。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_533','即景复为七言两韵','祝允明','明','临水树如朋合志，
隔篱花似女怀春。
护门村犬还惊客，
亲棹沙禽忽讶人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_534','晚上吴山风雨骤至','祝允明','明','东望海门门忽开，
松风十月滚轻雷。
山眉一点云拖黑，
知是龙王送雨来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_535','赴报国院海会喜侯二葛大同集','祝允明','明','隔水应霜钟，
寻声入宝宫。
刹那依燄慧，
六万绕神通。
欢喜来侯白，
清真遇葛洪。
独惭文字累，
未得此缘空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_536','追赋内相吴公邀往书石山中杂题','祝允明','明','上宰邀书睿制篇，
幸从几席向林泉。
晨陪松露翻閒语，
夜傍贤星聚处眠。
暂拂古风嘘故里，
喜逢佳衲过山前。
儿童日夹先公膝，
说向当时屡泫然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_537','雨中句容道中喜看山色','祝允明','明','洗秋零雨向萧神，
京邑风光斩地新。
马上会淹京兆客，
天涯忽见苧萝人。
轻云淡荡铅华薄，
初日曈昽宝镜真。
便欲涉江嗟未得，
芙容犹自隔青蘋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_538','与沈二秋寓建业山院夜话','祝允明','明','倦迹怜司马，
清风遇隐侯。
乡关不堪问，
文酒且须酬。
水压吴王国，
山横建邺秋。
高台仍可喜，
重见凤凰游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_539','嘲客舍山脚下井','祝允明','明','脚带浑泥气带腥，
几家同汲竞罍瓶。
寒泉只在前山里，
笑杀居人总不醒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_540','幽州岁残','祝允明','明','冠天袖海舜幽州，
风候萧森气朔遒。
双阙日移仙仗散，
六街尘滚晚衙休。
马周卧旅犹观国，
王粲怀乡独赋楼。
未得边关擒虎豹，
还思江海弄凫鸥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_541','万安道中','祝允明','明','历历长亭过眼频，
浮家一舸日随身。
江山不苦南征客，
星斗应怜北望人。
剑匣只依书裹住，
酒杯全亚药炉亲。
床头历日閒拈看，
一岁无端半已陈。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_542','赣州','祝允明','明','萧瑟滩声怒复幽，
四程犹未是炎州。
行人不解居人语，
章水相逢贡水流。
蒌叶槟榔须学啖，
莼羹盐豉向谁求。
英贤满路容参谒，
珍重昌言日拜收。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_543','上下滩','祝允明','明','上滩若缘蚁，
下滩若驰驶。
移转顷刻间，
便是人间事。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_544','庾岭寄谢江西白大参宗宪副二同年','祝允明','明','太原白居易，
南阳宗少文。
千年才并出，
一日可离群。
契分秋风桂，
情亲日暮云。
江波二千里，
相逐送清芬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_545','山人献白鹇','祝允明','明','草啄萍栖瘴海濆，
野人携得肯相分。
九还丹颗浮苍顶，
一缕青霞断白云。
五服也知章有德，
百禽应是不同群。
县斋相对悠然想，
烟水城西日易曛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_546','思食豆腐','祝允明','明','蹲鸱亦称野人肠，
薯蓣还输菽乳良。
轑釜不闻流素汞，
堆槃无复截虹肪。
旧知学士能为赞，
今讶淮王不遗方。
只恐南山归去后，
苗稀未得快新尝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_547','失白鹇','祝允明','明','何处青冥会一冲，
短翎应近井庐中。
来时想见银塘静，
去后休嗟蕙帐空。
自笑无鱼难久馆，
谁言有鹄不如笼。
归心一夜秋来月，
吴水吴山几万重。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_548','夏日城南郊行','祝允明','明','古县周遭景物环，
政虽多暇倦跻攀。
偶因送客乘时出，
却得浮生半日閒。
频过水边仍有竹，
忽当林断远逢山。
但教到处情如此，
瘴海无妨缓缓还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_549','游和山麻石岩','祝允明','明','山和人亦和，
乘暇集鸣珂。
陟岭美未得，
到岩奇转多。
交枝树碍马，
一步地旋螺。
成屋自麻石，
作门惟碧萝。
瞻天隔鸟道，
入地学蜂窠。
树向顶上植，
泉从肩畔过。
禽虫冯几住，
云霭入衣摩。
佛座泥三级，
僧床石四阿。
西临野广漠，
东眺径陂陁。
远吹潜生爽，
骄阳暂息苛。
祷祈情敬谨，
乐业舞婆娑。
物穰用亦俭，
地危心不颇。
民风都似此，
吾为尔陈歌。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_550','北郊访友','祝允明','明','风物幽妍上郭宽，
访朋因得一回看。
家家黄土墙三尺，
处处清渠竹数竿。
欲雨欲晴云半密，
如秋如夏汗微乾。
苦吟应得山人句，
却笑笼头少鹖冠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_551','过林头看修竹数里不断甚爱戏题','祝允明','明','五寸冲牙文八矛，
装成十万绕林头。
莫欺楪子兴宁县，
一半人家千户侯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_552','和王太学见赠','祝允明','明','水鉴求才事自公，
徒令寂寂笑英雄。
山斋一枕渊明梦，
开眼犹惭七里封。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_553','和王太学见赠','祝允明','明','道拙才空志不成，
错将言语占时名。
无端抛却山林乐，
换得轩裳底事荣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_554','和王太学见赠','祝允明','明','草庐藏得卧龙才，
许我英雄亦异哉。
刚道同心金可断，
江南便是海南垓。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_555','和王太学见赠','祝允明','明','三载相看有别离，
春鸿秋燕不同时。
我寻松菊去方急，
君会风云行莫迟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_556','登越王台','祝允明','明','环城三面碧波围，
今古楼台满翠微。
不见越王惟见佛，
木绵花里鹧鸪啼。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_557','惠州西湖','祝允明','明','西寺东城两幅图，
长虹脊畔小浮屠。
杭州惠郡都游遍，
醉眼时将作石湖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_558','莆田郑自修宰河源故厚予四月三日舟过县城君以诖误不在予亦以文法行一时风雨大作小泊沙口而去怅然怀君口占一诗期后寄之','祝允明','明','河源西郭夕阳过，
不见美人将奈何。
雷压船头蓬底坐，
一时风雨乱风波。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_559','庚辰三月归至保昌馆李君士元家适士元车马有行色廿四日解携各北南临岐口占为赠','祝允明','明','梅花关下春雨深，
客送主人无限心。
凤生南海莫言远，
明日一飞归上林。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_560','市汊阻风','祝允明','明','十日踰千里，
三宵滞一隈。
旅情忙复缓，
归棹去还来。
横飓摧高木，
飞涛激迅雷。
坐看村市没，
行路不须哀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_561','宿茅峰','祝允明','明','下马门前一振衣，
翠微高迥逼清微。
云边洞里真人去，
月下山中长史归。
丹伏砂床金燄短，
术穿崖窦紫云肥。
神方能咏不能遇，
一夜爽灵峰顶飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_562','登千佛院塔','祝允明','明','八面青红倚碧天，
窗中列坐万金仙。
排云欲挽三茅袂，
拊槛惭升八部肩。
尽讶入檐奇影倒，
应知出世法门偏。
诗题漫道游观胜，
只得尘劳一饭缘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_563','高淳道中','祝允明','明','柴门对树树临流，
春日迟迟满客舟。
一种江南千里景，
只闻鸡犬不闻鸥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_564','经旧游','祝允明','明','当垆一啜手煎茶，
迎客桃花户外斜。
闻得博陵崔护道，
不知今日是谁家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_565','咏公馆花木','祝允明','明','句曲酴醾溧水桃，
溧阳孤柏倚风高。
家园几树桑和柳，
何事令人梦想劳。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_566','未足句','祝允明','明','却恨风光同万里，
眼看百里不能归。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_5_567','未足句','祝允明','明','忧国天高惟有梦，
思家怀近不能归。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_5_568','与句曲李令徐博士等夜饮','祝允明','明','洞天福地神仙县，
宣化承流父母官。
自笑樊笼犹闭鹄，
却怜山树亦栖鸾。
绯英炫幄春方烂，
红蜡摇觞酒快乾。
未必啸歌妨杼轴，
风埃浩浩暂清欢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_569','赠江秀才','祝允明','明','三日芳兰入座薰，
欲将心事为论文。
仙囊古玉餐无诀，
官市新醅饮便醺。
已羡雄飞难久伏，
每嗟同调易离群。
茅峰蒋阜无多地，
未拟相思咏碧云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_570','宿摄山栖霞寺三首','祝允明','明','寒林日暮息车徒，
却得南朝最胜区。
廿载不登禅子榻，
一宵权作佛家奴。
齐梁寂寞名犹是，
儒释纷纭念已无。
最是宦心能败道，
羞将束带问衣珠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_571','宿摄山栖霞寺三首','祝允明','明','泉洞迷藏草没梯，
倚岩千佛坐高低。
叠襟山色周回峭，
隔树江声隐映齐。
宋刻梁文江令笔，
龙蟠龟戴上元题。
栖霞只是枯禅宅，
尔许头颅向里栖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_572','宿摄山栖霞寺三首','祝允明','明','枕上红尘白昼深，
眼开欲得息劳心。
灯花暗入僧床冷，
山阁冯江万木林。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_573','出湖见山','祝允明','明','长湖方出口，
一带横青山。
行处必如此，
何云出世閒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_574','当涂历阳溧水界中数还往遂怀李翰林','祝允明','明','青山历历树苍苍，
远水长天几夕阳。
千载更无仙谪下，
只应愁杀贺知章。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_575','舟行守风阻险辄睡酣适成咏','祝允明','明','行役安危定，
心閒常自如。
每当惊滟滪，
偏得访华胥。
适逐墙头蝶，
清涵水底鱼。
觉来何以遣，
枕畔一堆书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_576','谢杨大送梨花栽成','祝允明','明','来自清修处士家，
草堂初就便增华。
雕栏月上添得影，
画栋云过分作花。
园吏引渠经细干，
闺娥绕树候芳芽。
洗妆先觅催妆句，
凭阁巡看几日斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_577','谢吕禹平惠玉鞭粉团花','祝允明','明','花开根至梢，
素朵附香条。
流苏叠脂粉，
眉钿簇琼瑶。
不逐紫骝马，
空依翠鬓翘。
予方理花事，
先聘汝无骄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_578','中秋日燕客晚雨','祝允明','明','中秋美景当吴苑，
十载佳期共此堂。
珠履高吟欢满座，
金钗送酒看分行。
荆娥妒月俄行雨，
赵女停弦慢绕梁。
莫道西岩轻易堕，
朱帘徐捲烂银光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_579','十六夜召集','祝允明','明','广寒昨夜不曾开，
今夕佳期已报来。
且向草堂杯举待，
人间红粉会相催。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_580','为唐子畏索剑','祝允明','明','手解青萍昔赠君，
仗来多少截妖氛。
知君道就□□后，
把与东人刲白云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_581','简赵西台','祝允明','明','满月澄寒镜，
清霜涤素琴。
独携车后雨，
去润豫章林。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_582','简赵西台','祝允明','明','死恨钱塘水，
悠悠只向东。
雁飞虽不北，
连日有南风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_583','过郑六不遇','祝允明','明','欲作春风上国游，
寻君东海话离忧。
烟波自剪西窗烛，
丝管醉眠何处楼。
五夜不逢黄宪面，
百壶那解长卿愁。
平生国士青君眼，
老矣犹能一笑酬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_584','送顾司封守开封','祝允明','明','皇舆百郡首开封，
良牧分符开治功。
参庭属吏衣冠满，
绕郭编人耒耜丰。
河山郏鄏千秋固，
云雨乾坤万物同。
悬知政化平如水，
共看汉室美吴公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_585','戏为朱民部索齑','祝允明','明','苏公屡欲传冰壶，
此味能参自信吾。
为语版曹朱学士，
客厨争奈并锥无。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_586','留别赵上舍','祝允明','明','归骑聊乘一日閒，
夕阳移座未能还。
西风明日丹阳道，
回首鸡鸣雪满山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_587','吴文定公挽歌词','祝允明','明','鼎轴参黄阁，
阶符坼紫垣。
位迁如始筮，
人慕过生存。
一德天犹格，
三朝国共尊。
君臣两无负，
元烈荷厖恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_588','吴文定公挽歌词','祝允明','明','执绋椒涂远，
前驱凤翣还。
君臣同国运，
忠爱满人间。
速夺山河系，
幽情水竹间。
吾曹惟淑艾，
抱籍哭颓山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_589','吴文定公挽歌词','祝允明','明','吾祖悬车日，
知公释褐初。
遂深鱼水分，
亦有兔萝图。
笑语儿童际，
衣冠梦寐馀。
凄凉天下德，
忍谓及门徒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_590','赠翁隐居','祝允明','明','吴郡翁高士，
森森君子儒。
风标抗轩冕，
礼乐在江湖。
松露濡谈麈，
匏樽尽酒壶。
却嫌城市隔，
欲别重踟蹰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_591','荅日本使','祝允明','明','日边来处几何时，
闻说占申复到寅。
遥仰北辰趋帝座，
却经南甸驻行麾。
诗名愧动鸡林客，
禅谛欣参鹫岭师。
回首山川浑渺邈，
只看明月慰相思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_592','简伊佥宪','祝允明','明','七朝熙洽世臣家，
班序丘樊势并华。
忠孝到君传不匮，
韫沽如玉总无瑕。
园同涑水青山下，
扉掩阊门小曲斜。
老去高情澹如水，
著书观物是生涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_593','西台伊公枉和赠篇至于再三重次呈答','祝允明','明','东野犹居郭外家，
闭门高枕叹年华。
秦人不敢窥干木，
楚事休教误屈瑕。
暑气转嫌秋候溽，
树阴偏受日光斜。
驽骀过辱千金许，
惭愧酬知未有涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_594','赠孙山人一元','祝允明','明','思邈先生不可寻，
紫麟骑下阆风岑。
宵眠华岳星支枕，
晓度关河月满襟。
惊鹤梦残飘露叶，
哀猿肠断抱霜林。
秦台故有吹箫侣，
一片宫商万古心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_595','赠俞隐居','祝允明','明','水南雉市万尘趋，
水北还容陋巷居。
三尺素桐陶靖节，
百篇华赋马相如。
心抛世俗争为事，
手录时贤未见书。
欲继姓名高士传，
怕君嫌我近睢盱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_596','方吴二子偿金之什','祝允明','明','读罢偿金记，
直疑无此人。
唐君解言语，
高义不成尘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_597','艇子','祝允明','明','江南小艇子，
能住亦能诗。
梁柱无阶砌，
门窗即枕帷。
坐流看树过，
行屋逐风移。
试欲作舟史，
半生居在斯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_598','题龙归洞下有龙母嶂','祝允明','明','千峰如帐瞰岩扉，
灵物何年向此飞。
潭底火符玄铁简，
嶂头金母白绡衣。
海多云雨应长往，
壑暗藤萝久不归。
洞外蛟蛇常起陆，
可能消伏运神机。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_599','季冬朔旦汝德周学二秀才过访病禁饮不能留别去怅然竟日烛下得句明日寄之','祝允明','明','相思旬日忽相逢，
不是忙中是病中。
玉麈漫誇谈柄在，
朱颜应笑酒杯空。
怜君济济冲霄鹄，
顾我垂垂失路鸿。
吾道若行千载合，
不须重叹马牛风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_600','上元日喜晴柬董博士及诸秀才','祝允明','明','三月恒阴待此晴，
灯辉晨映日华明。
便趋东郭朝龙驭，
又向宾筵听鹿鸣。
箫鼓儿童聊祝岁，
犁锄父老喜深耕。
云师雨伯休重恼，
欲共温泉祓禊行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_601','神光山','祝允明','明','山郭西南五里强，
翰林留得读书堂。
漫漫古岫云烟薄，
寂寂閒坡草树荒。
数点远村钩望目，
一间空殿锁斜阳。
山灵我为乡人问，
会许何年更有光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_602','赠王希贤秀才','祝允明','明','缁衣耿耿此心长，
青眼随人到异乡。
海外不须誇马脑，
人间谁解识虹肪。
也知老桂为仙树，
岂有幽兰减国香。
奋翅云霄应不远，
相知独愧早称扬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_603','谒张文献公祠','祝允明','明','丞相祠堂曲水涯，
祠边仍是相公家。
千秋若解收金镜，
万里何缘枉翠华。
门外犦牲兼絮酒，
岭头松树夹梅花。
人间不乏牛仙客，
长揽遗编费叹嗟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_604','峡山寺','祝允明','明','灵区苦不到，
到亦苦诗难。
景象绝闻见，
怪神如等閒。
地将海作带，
天借山为关。
今日却堪恨，
绿林栖近间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_605','潮州韩文公庙','祝允明','明','一世北斗望，
千秋南海滨。
文章传绝圣，
政事泽时人。
姓作儿童字，
心将动植驯。
佛灵能有祸，
终不下臣身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_606','次韵奉和方伯汤公回銮志喜之什','祝允明','明','五云遥捧翠华归，
北极芒寒万象依。
关塞岩岩分地险，
金汤面面自天围。
圣图六马知能驭，
永命三灵未待祈。
岭海小臣从国老，
中宵魏阙梦魂飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_607','传闻郊祀后大驾寻复出狩疑信未得因用前韵纪事一首','祝允明','明','穷海欢传八骏归，
仍闻消息语依依。
要荒岂必劳重幸，
帝命今方式九围。
禹服正须垂拱治，
尧年何用筑宫祈。
明禋眷答皇灵切，
长使钩陈护六飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_608','奉和顾宪副梧州谒都宪韩公祠堂','祝允明','明','拔地洪材搆帝家，
倚天雄略眇虫沙。
诚归魏阙心悬石，
血饮匈奴胆破瓜。
半夜昆崙枢密宴，
三言苡薏伏波车。
当时利口今何在，
老树闳祠日又斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_609','梦故知','祝允明','明','气涵珍玉语良金，
不论穷通话尽心。
枕上一时南北海，
半窗梅影月阴阴。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_610','谢汤文守惠地黄煎','祝允明','明','会将云缕换霜华，
一匕玄琼入紫霞。
他日天台莫轻住，
要携徐甲到流沙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_611','梦故人','祝允明','明','今古悠悠老客心，
酬知何必接兰襟。
争怜寂寞卢生枕，
还恐凄凉子敬琴。
吴苑此中非旧社，
越江南去是□林。
纸窗秃笔聊成赋，
风弄清灯夜点沈。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_612','元和爱结过深晤言之馀复投长句思予和女乃就二章意局情饶聊复尔尔','祝允明','明','枝山磊落倚东山，
雪桧霜松许共攀。
文字虚名今且愧，
疏慵物议古来艰。
平生肺腑篇章内，
身外金兰梦寐间。
万卷旧书千石酒，
两人相对白头闲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_613','元和爱结过深晤言之馀复投长句思予和女乃就二章意局情饶聊复尔尔','祝允明','明','故里閒居忆美人，
开轩延伫御周轮。
兼旬病起殷勤探，
玉钿飘零遍委尘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_614','悯时','祝允明','明','巡游方罢乱离平，
岂谓凶饥岁二更。
桂玉断来钱货废，
糟糠空后析骸争。
焉知卜史言天道，
尽望仁人辅圣明。
三户可怜疮痏在，
欲凭开凿了馀生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_615','寄吉安太守徐士元同年','祝允明','明','梅关归路拜车尘，
阁皂书来语意勤。
始信凌云江海客，
能怀闭户薜萝人。
酬知但有篇章旧，
名世争看事业新。
玉版金枨无用递，
涧藤崖刻不妨频。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_616','中表甥陈鳌子鱼久抱微疾怀之得句因寄','祝允明','明','俊鹤祥鸾陈子鱼，
阊门楼阁事亲居。
想因别墅聊行药，
却得云窗漫校书。
俗驾向来虚下榻，
德星何日见牵车。
身为公子心为士，
便是公侯已复初。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_617','足梦中句','祝允明','明','圣境不可到，
魂游记渺绵。
花藏竹林院，
莲号贝多编。
龙鸟如人礼，
山河绕法筵。
秪应身本幻，
此却是真缘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_618','哭周院判','祝允明','明','雅道凄凉后，
何情当此悲。
斯人不易产，
中寿岂难期。
鵩兆将无验，
鸡年竟莫支。
心曾周晚末，
目不瞑严慈。
地有颜渊代，
天无伯道知。
负公兹一饯，
西望涕洟垂。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_619','哭表弟蒋焘','祝允明','明','白玉楼中长吉去，
芙蓉城里石郎归。
煌煌柱国平生念，
看到诸孙内外微。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_620','哭陆大参','祝允明','明','四海铨书失老成，
两朝闺籍尚遗荣。
达如子贡能从政，
忧似希文最善兵。
几度老貂新命夺，
两宵幽鬼故冤平。
文编谏草离离燄，
付与机云续令声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_621','哭王麟','祝允明','明','宾馆初违梦尚縻，
讣音俄至欲成痴。
岂知十日轻谈笑，
便作千年永别离。
鸡絮未陈新繐帐，
凤雏空倚旧霜枝。
高风几许堪传事，
谁写平生入墓碑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_622','答史随州','祝允明','明','楚云飞墨下烟萝，
想见潇湘又绿波。
刀剑已知成牸犊，
簿书何处问弦歌。
照人颜色春风近，
入梦江湖夜雨多。
写就卜居冯问讯，
青袍今误欲如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_623','访华光禄','祝允明','明','高堂此始登，
兰韵久熏蒸。
榻定叨徐稚，
门今识李膺。
倾瞻疑夜烛，
笑语泮春冰。
绿合沙头草，
归舟发未能。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_624','广川城','祝允明','明','皎月浸严城，
苍苍百雉横。
木梁悬絙下，
竹柝夹鼙鸣。
水部从时饮，
山人入夜行。
因思赵公子，
封邑尚垂名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_625','途中','祝允明','明','二年四踏两京尘，
何必临岐更问津。
斜渡羊车山顶路，
半欹皮笠雨中人。
气骄白马涵濡满，
口过玄蝉啸咏频。
我有知心在城阙，
山阴雪驾颇相邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_626','故福建佥宪陈公直道祠五十韵','祝允明','明','日月悬臣道，
乾坤辟圣猷。
丹青开庙貌，
风烈见英庥。
宝历三光合，
鸿钧一气流。
哲人当上瑞，
畿服产南镠。
灵派分妫汭，
洪条发太丘。
修文登石室，
射策步瀛洲。
藩府旬宣重，
河阳惠爱稠。
推丹置人腹，
囊皂达民忧。
岂谓褫鞶带，
仍从把铚耰。
十年依大岳，
一旦起西畴。
再属金闺籍，
还乘绣使驺。
臣心知不贰，
帝德若为酬。
柱砥千回浪，
霜飞六月秋。
触邪惟豸性，
批逆岂龙谋。
范进唐宗典，
苏陈陆相筹。
缉熙光圣业，
取善在旁求。
大学存条目，
遗编可绎䌷。
意诚缘物格，
心正乃身修。
利病非无实，
安危固有由。
愿防多内欲，
乞斩佞人头。
一疏朝封入，
三言夕抒投。
桁杨来孟博，
贯索下酂侯。
耄稚爰书没，
姬姜织室幽。
一家连廿口，
五载作孤囚。
白璧尘埃尽，
青阳造化周。
日华临凤扆，
天语出龙楼。
岂独除罗网，
重教侍冕旒。
玉磨谁可磷，
金鍊转难柔。
按辔抨藩国，
飞章速转邮。
嘉谟应削濞，
雅志欲安刘。
天震雷霆怒，
霜号草木愁。
国书当极典，
臣节果何尤。
祗见义为命，
不知生可偷。
吏持三尺法，
人哭一生休。
政化权衡准，
恩厖渤澥浮。
解维归北阙，
迁秩按南州。
地肃山无警，
波恬海可游。
狐丛斥魈魍，
雀角绝哗咻。
叔度来何暮，
渊明去莫留。
车悬桑梓重，
山隐桂枝樛。
箕尾星辰接，
龙蛇日月遒。
英灵长宇宙，
声节岂浮沤。
主际唐虞圣，
恩非关比俦。
朝廷为世计，
章典复公收。
懿德人惟好，
群公志并优。
学祠崇秩进，
营兆谨封修。
载睹专清庙，
时闻荐洁羞。
浚培知水木，
绍述美箕裘。
直道黄扉扁，
名篇文梓裒。
终天弘劝在，
王化正悠悠。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_627','道院楼子','祝允明','明','重檐雄拔小山幽，
妙景容居最上头。
风扫六窗尘尽去，
鹤乘三洞客来游。
高原树古长依殿，
画栋云飞不碍楼。
怪底霓裙浮沆𤅈，
绿章宵拜石坛秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_628','赠太仓汪使君','祝允明','明','德风千里掩雄州，
争解长刀换乳牛。
共羡汉家封卓茂，
且看夫子戏言游。
功名此去符龟印，
文彩朝来压蜃楼。
最是野人怀惠切，
一廛今拟结沧洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_629','登太仓州中山子怀故襄阳李使君','祝允明','明','州山昔始创，
予幸作游宾。
丰碑备标纪，
幽赏悦心神。
兹来再登陟，
亦遇贤主人。
襄阳不可见，
岘首泪盈巾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_630','游武将军园亭','祝允明','明','武君好人品，
园林亦不群。
幽迥妙水石，
妍蔚盛芳芬。
登眺一时尽，
道俗忽然分。
安得杜工部，
来赋何将军。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_631','赠邢奎','祝允明','明','襟怀洒洒气飘飘，
游遍名都岁月遥。
花暗燕台春走马，
月明淮浦夜吹箫。
华颠相对旧盟在，
笑口一开尘虑消。
更喜儿郎皆孝秀，
入厨甘旨足渔樵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_632','题衲子诗稿','祝允明','明','得来应是呕心肝，
磨破枯蒲几个团。
佛有语言唯说性，
僧为文字不求官。
色离纨裤通身净，
味带齑肠一点酸。
我欲强赓三五首，
却怜无暇尽雕钻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_633','太傅王公款月台','祝允明','明','青天洞荡浮云开，
东方月出临高台。
光流碧汉轮飞度，
影入湖波魄共来。
贤主嘉宾长会合，
同光共景且徘徊。
未咏韩公星没句，
聊从太白漫停杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_634','南洲词四首','祝允明','明','盘门向南起，
城里百花洲。
洲边隐客住，
道是顾虎头。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_635','南洲词四首','祝允明','明','朝向南洲行，
暮向南洲宿。
不钓亦不泛，
爱看南洲绿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_636','南洲词四首','祝允明','明','西风忽然起，
木落波粼粼。
水浑鱼不定，
宵来愁杀人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_637','南洲词四首','祝允明','明','春烟杨柳暗，
秋露芙蕖鲜。
慎莫生宿莽，
沙鸥不得眠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_638','卞将军庙','祝允明','明','瘦马城西步夕曛，
祠堂翼翼护英氛。
下马入门忙拜礼，
行人说是卞将军。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_639','钟山','祝允明','明','五岳峥嵘卫紫微，
万方臣妾仰光辉。
勾陈上直天皇座，
少海中严帝子闱。
峰顶日华迎凤下，
洞中云满待龙归。
终天王气都留此，
花木常新鸟兽肥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_640','金陵眺古','祝允明','明','绿谢平芜野烧乾，
西风吹雨打长干。
盘龙去后金钗饷，
擒虎来时玉树残。
结绮阁中香灺歇，
景阳楼下水花寒。
秦人岂识千年后，
终古神州奠石磐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_641','太湖','祝允明','明','咸池五车直下注，
峨眉岱岳潜相通。
乾坤上下浮元气，
郡国周遭护渚宫。
岩穴会因仙迹幻，
鱼龙不助霸图雄。
拟把玄圭献天子，
再看文命告神功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_642','虎丘','祝允明','明','循麓都来几屐踪，
异观灵景正重重。
入门始见山和水，
汲涧愁惊虎与龙。
四面更无林作伴，
当头又着塔为峰。
尘裾皂衲纷纷满，
二竺终无一个逢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_643','虎丘','祝允明','明','一点紫泥封岱顶，
武丘雄拔阖闾城。
席前花雨天宫落，
槛外云霏脚底生。
毂辘十寻抽玉液，
于菟千百逝金精。
无穷胜是王郎事，
吴越消亡几战争。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_644','包山','祝允明','明','影浸三州混太虚，
道通五岳纽坤舆。
瑶坛白兔藏仙鼎，
宝洞苍龙守禹书。
烟月剩将閒处媚，
风雷常与怒时俱。
渔郎个个不识字，
惭愧高吟莫解居。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_645','白莲寺','祝允明','明','台殿切层霄，
丹霞远建标。
名传白莲妙，
年纪赤乌遥。
迤逦城连郭，
回环水贯桥。
重来拟分榻，
尘虑未全消。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_646','昆山清真观','祝允明','明','疑分疑幻海中洲，
只恐人间无此谋。
殿影四围浮碧沚，
钟声十里出丹楼。
仙人示象书仍在，
道士无鹅字少求。
至竟今宵为旅客，
幸来何事不微留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_647','沧洲姚家涵碧阁','祝允明','明','寒塘带州廨，
幽趣似郊坰。
树影倒浮绿，
天光平漾青。
石渠方似矩，
板屋小如舲。
相对只鱼鸟，
濠梁同性灵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_648','赠邓驾部','祝允明','明','十载襟期利断金，
高山无固海无深。
忽看凤阙城中会，
还似鸡窗梦里寻。
袖底电飞雷焕剑，
壁间泉响伯牙琴。
休论鉴物知音事，
识取悠悠太古心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_649','三月三日施侍御邀宴姚将军庄宅即旧名东郭草亭遗址','祝允明','明','共传修禊事，
相命出郊原。
花鸟何须眼，
栽培亦自村。
辘轳横转水，
畚锸削成垣。
因看劳劳者，
悬知圣主恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_650','三月三日施侍御邀宴姚将军庄宅即旧名东郭草亭遗址','祝允明','明','日影迂龙辔，
春光溢凤城。
绣衣乘暇出，
翠幰逐空行。
姑蔑金盘露，
郎邪石首羹。
簪缨杂巾褐，
莫遣野人惊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_651','三月三日施侍御邀宴姚将军庄宅即旧名东郭草亭遗址','祝允明','明','骀荡三春好，
陂陀五里遥。
篇章传保傅，
地主识嫖姚。
壁上县瑶轸，
空中度玉箫。
南塘无杜句，
深愧故人邀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_652','金华见山亭','祝允明','明','郡廨当空立，
林亭面爽开。
窗中列岫远，
江上送青来。
京兆眉长妩，
陶公菊自栽。
安能乞勾漏，
把笏此徘徊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_653','与胡二游海珠','祝允明','明','人誇本奇境，
我恨近城闉。
四面尽江海，
一拳藏宝珍。
鱼龙游槛砌，
舟楫换比邻。
野马不能到，
却多车盖尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_654','雨窗有怀连韦二博士','祝允明','明','薄宦将三载，
高情有二君。
天涯漫萍梗，
雨下忆兰熏。
四海习凿齿，
千年扬子云。
东邻无百室，
犹自叹离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_655','戏简连博士','祝允明','明','为问涧松夫子来，
酒肠连日可曾开。
天炎地陋佳宾少，
眼底能无曲秀才。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_656','题杭州蒋自容江湖游卷','祝允明','明','越多名族又多才，
诸老篇章取次裁。
但看江湖诗一卷，
定知胸次不尘埃。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_657','题杭州蒋自容江湖游卷','祝允明','明','钱夏老成无复见，
张萧逸驾亦难攀。
风流一日同千载，
犹记当时杖屦间。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_658','题杭州蒋自容江湖游卷','祝允明','明','两人携手五羊城，
浙水东西是弟兄。
但使有诗仍有酒，
不妨长听鹧鸪声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_659','番禺留别衡明府公式','祝允明','明','风尘薄宦来南海，
书计衰年走北畿。
霄汉自怜知己少，
天涯犹觉故人稀。
芳菲桃李祥鸾集，
重叠江山旅雁飞。
为问微官是何物，
相依无久又相违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_660','次韵郡守胡公太湖二首','祝允明','明','名山大川邦域内，
澄波皓月方舟中。
鱼龙窟室藏诸有，
天水鸿濛望并空。
禹功想像三江入，
唐风浩荡九州通。
兹辰更为方舆重，
帝遣诸侯问上公。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_661','次韵郡守胡公太湖二首','祝允明','明','地轴钩横海岳牵，
咸池直下具区连。
封疆何计吴越限，
光景长涵舜禹天。
白鸟舞波摇定日，
骊龙归洞落腥烟。
木奴万个安能住，
不是元公即上仙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_662','次韵郡守胡公阅城登姑苏台','祝允明','明','六门车马簇飞埃，
小垒依稀说旧台。
暇日暂迂羊傅驾，
他年便是岘山隈。
勾吴于越千秋梦，
范蠡西施一种才。
麋鹿绮罗都不见，
紫烟终古锁荒苔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_663','又次登台望虎丘诸山','祝允明','明','乾坤双眼一空亭，
山色能令五马停。
鹿苑尚衔吴子艳，
虎丘重对白公青。
烟消碧落千峰出，
月浸严城万户扃。
不但登高能赋事，
四郊因省荷锄丁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_664','哭子畏','祝允明','明','天道难公也不私，
茫茫聚散底须知。
水衡于此都无准，
月鉴由来最易亏。
不泯人间聊墨草，
化生何处产灵芝。
知君含笑归兜率，
秪为斯文世事悲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_665','哭子畏','祝允明','明','万妄安能灭一真，
六如今日已无身。
周山既不容神凤，
鲁野何须哭死麟。
颜氏道存非谓夭，
子云玄在岂称贫。
高才剩买红尘妒，
身后犹闻乐祸人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_666','送姜梦宾','祝允明','明','万里昆黔地，
于今得使君。
莫言民物幸，
须识圣恩勤。
旭日开幽蔀，
清霜条惠文。
尔知朝事否，
便是昔朱云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_667','送姜梦宾','祝允明','明','矫矫温州牧，
清声范史云。
当时称大老，
今日有夫君。
德用玉为器，
胸盘锦作文。
志行朝野庆，
我独叹离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_668','赠罗抱拙','祝允明','明','休言雅志与今违，
吾道何曾有是非。
自信移山终有术，
岂知流水亦容机。
耕田凿井康怀日，
夏葛冬裘□□衣。
谁信阊门名利窟，
此中巢许自依依。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_669','赠张守之工部','祝允明','明','世交先进两先生，
白首今成老弟兄。
知我得师终不改，
如君直道岂难行。
路无荆棘安能塞，
川汰泥沙只自清。
皓月清风居不隔，
酒杯茶碗共馀情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_670','戏为毛百朋索炭','祝允明','明','眉山羊肉会稽鹅，
颇欲临池手未和。
便可把君乌玉换，
纸窗那得十眉呵。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_671','题沈山人藏王舍人竹枝','祝允明','明','舍人清真同右军，
金銮退直谢鸡群。
千金不肯卖一叶，
今日凤毛留赠君。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_672','梦啖菜甚美','祝允明','明','王醴侯鲭信祸胎，
露茎霜叶是琼瑰。
如今才享天家福，
净洗饕肠待尔来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_673','戏作纪梦','祝允明','明','何事高唐入梦游，
淡云轻雨太温柔。
瑶姬错认维摩婿，
枕畔花人空抱裯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_674','送杨礼部','祝允明','明','我有骏马图，
持附君装畔。
伯乐既上天，
留与何人看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_675','观湖宛转思及友人','祝允明','明','湖上秋风生碧漪，
看来都作忆君思。
君于湖水元何与，
此意冥茫自不知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_676','赠嘉兴陈使君','祝允明','明','有德由来必有言，
天球刚栗且清温。
汲公出守谋难寝，
李勉归来国始尊。
枭獍不同麟凤翥，
松篁会与稻粱蕃。
乾坤直气长留在，
万转千回道自存。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_677','柬松江马别驾','祝允明','明','螭端风采久堂堂，
汉室忧民牧守良。
淮甸已知烦汲黯，
云间今喜得王祥。
霜寒碧落横雕鹗，
日丽丹崖舞凤凰。
犹记观梅向东阁，
缊袍长带岁寒香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_678','简嘉定王令','祝允明','明','江海遥分圣主忧，
春台迟日玉壶秋。
地当大国方千里，
才号明时第一流。
欹枕潮声奇句得，
暗庭花影早衙休。
鸾栖自古通麟阁，
褒德先封汉室侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_679','赠分司钞关于户部','祝允明','明','初从分部谒巾冠，
便略形骸露肺肝。
东有珣琪南有箭，
紫为鸑鷟碧为鸾。
关讥尽道能经国，
王佐何曾务守官。
下对苍生上天子，
知公心事浩漫漫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_680','送贰守曾公擢河南佥宪','祝允明','明','琴鹤扁舟晓解携，
春风江郭暗棠梨。
千家霖雨邦人在，
一道冰霜宪节西。
奉国已知行莫止，
恋恩无奈喜还啼。
平生志操夔皋是，
槐棘堂堂次第跻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_681','重过元抑','祝允明','明','再谒还图笑口开，
客襟长恋校书台。
每从王郑求新义，
试把琼玫共品裁。
直恐星辰惊太史，
岂容江海阻雄才。
悠悠尘迹期君定，
泽国秋高更拟来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_682','赠董五','祝允明','明','邵南今隐士，
园北有幽居。
出市或卖药，
闭门惟读书。
白云媚修竹，
嘉木荫清渠。
见说新成赋，
题名后遂初。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_683','顾秀才阳山草堂','祝允明','明','家住山城不到山，
强题诗句抗尘颜。
君家客坐烟萝里，
尽著閒人自不閒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_684','口占寄陆三','祝允明','明','达者端居东海边，
重楼高榻卧风烟。
想应草木扶疏下，
和得渊明孟夏篇。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_685','送王先辈纳言归柳州','祝允明','明','携将柳州剑，
独下潇湘船。
千里景千变，
一山诗一篇。
离桥梅子雨，
归棹桂花烟。
重会云霄上，
大都才二年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_686','题人园居','祝允明','明','未必丘樊好，
幽居趣自深。
迟行避小草，
高卧托乔林。
抱灌惟知瓮，
挥锄不见金。
问渠终岁里，
曾有惜葵心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_687','东庄','祝允明','明','场上鸡豚争稻穗，
渡头鱼鸭避菱科。
老农到处东庄有，
只少君家击壤歌。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_688','客中以徽扇贶人','祝允明','明','客里嫁嫦娥，
其如良夜何。
共怜风月好，
不道怨恩多。
瘦骨支黄竹，
轻裾叠紫罗。
半年期握手，
无事箧中歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_689','都门送施邦直归吴兴','祝允明','明','一时青眼中容我，
十里黄尘外送君。
坦率自怜犹宋玉，
咄嗟闻共说刘蕡。
袖头三尺秋潭水，
口底千章夏岭云。
今岁南游计应遂，
升山相访幸相分。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_690','赠同年赵缮部','祝允明','明','剑出红炉锦就裁，
霜锋霞彩照人开。
云间素有兼人士，
天上今推独步才。
觅句剪灯连绮席，
浩歌携手看金台。
迂狂幸托金兰尾，
况共高秋擢桂来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_691','赠鲍元卿','祝允明','明','人间有几鲍参军，
已见遗文又见君。
材器共为时世重，
声华相及古今闻。
身随李贺新囊锦，
箧贮羊欣旧练裙。
一日京华尘土尽，
十年深恨久离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_692','都门赠吴渊父','祝允明','明','飞誉响江东，
鸣琴向楚中。
麒麟游甸苑，
凤鸟集梧桐。
气吐风云动，
谈馀瓦砾空。
高松一千丈，
深喜附唐蒙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_693','赠崔鸿胪','祝允明','明','才分震泽清，
山玉映人明。
济北想崔瑗，
九江惭祝生。
笼鹅道士喜，
辨鲊座人惊。
相对华风外，
无因共好兄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_694','送戴户部仲鹖督漕淮关','祝允明','明','董漕分明是胜游，
云司高步向南州。
戴凭不独深经术，
刘晏偏能为国谋。
奇客昼谈风入座，
诗人宵咏月当楼。
悬知燕寝多清梦，
飞满伊凉紫塞头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_695','长乐赠陈参军','祝允明','明','浙水两岐非异土，
天涯万里又同官。
吴江莼菜皆成梦，
庾岭梅花且共看。
立望星河秋耿耿，
醉闻钟鼓夜漫漫。
人生离合真难定，
明日清樽好再乾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_696','次韵奉和左辖方公紫薇东阁之咏','祝允明','明','仙楼十二大瀛东，
何日移来此地雄。
分省势依纶阁重，
栽花种与禁闱同。
文书静向高明处，
星宿芒寒把握中。
知是望京丹悃切，
凌烟早晚圣恩浓。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_697','荅郑河源见赠','祝允明','明','腐芥终依虎魄灵，
相逢莫道是云萍。
因思旧雨来今雨，
却喜文星是使星。
榕叶作团风猎猎，
桂花含晕雾冥冥。
但教光彩长分照，
万里何妨客紫溟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_698','春夜怀郑河源','祝允明','明','传里诗筒两度过，
河源君子近如何。
甘棠昼永迷青野，
芳杜春深覆绿波。
两地颇同多枳棘，
九州何处奏弦歌。
唯应知己情难舍，
早晚疏踪入薜萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_699','海珠寺送黄提刑','祝允明','明','风行五峤过三山，
又得趋庭未是还。
天下望公知已久，
朝廷求治亦非艰。
波澄番舶鲸鲵静，
笔倚骚坛草木闲。
瞻恋清光惟此夕，
月华休下海珠湾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_700','次韵答河源郑侯见赠','祝允明','明','千古高风一日还，
摩挲尘眼对清颜。
且烦元亮为彭泽，
终使羊公重岘山。
渤海未容蠡瓣测，
女萝犹许兔丝攀。
劳君乞与山阴谱，
借取仁言此谕顽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_701','借前韵赠韦博士','祝允明','明','胸有灵丹熟九还，
刀圭能驻世人颜。
盘开苜蓿先生馔，
书对神光学士山。
席上令行椰酒急，
袖中香散桂枝攀。
英才满座沾时雨，
莫信昌黎道鳄顽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_702','又借韵自赋一首用呈诸公','祝允明','明','才到炎方便忆还，
空歌游子剑前颜。
穷秋阳鸟遵遥渚，
短景浮云出故山。
开被放衙星未没，
推窗观海日将攀。
诸公总是蓝田璧，
不弃他山老石顽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_703','答张掌教再次韵','祝允明','明','泮宫清寂坐斋心，
风阁微传弦诵音。
善价未能酬美玉，
佳篇重辱惠兼金。
窗中远岫浮青霭，
门外虚塘卧绿沉。
拟向清风明月夜，
飘然来此共披襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_704','送张掌教致仕归临江','祝允明','明','青眼摩挲醉袂分，
那堪客里别夫君。
风情好似陶彭泽，
官职常如郑广文。
渝水晚沙眠宿鹭，
蒙山老树映归云。
虚堂索句昏钟静，
宦海潺湲想未闻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_705','寄李刑部子庸','祝允明','明','夫子道中庸，
谁言世不容。
山河开正气，
江海辱高踪。
竹素期千载，
梅花又一冬。
永怀金玉韵，
无计久相从。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_706','送朝言邑博','祝允明','明','万里我来逢益友，
三年君宦失严亲。
欢中未料忽生恨，
客里那堪更送人。
夜雨湘江藜烬暗，
秋风蓬岭桂香新。
浮云聚散何须问，
阁凤台鸾看致身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_707','送连邑博','祝允明','明','一纸除书下越中，
遂行吾道遍西东。
人言师傅如君少，
我喜朝廷选士公。
卓荦松筠饶晚翠，
芳芬桃李满春风。
峡山寺里猿声切，
莫使相思梦不通。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_708','送张大参允','祝允明','明','五月炎州拂袖行，
蛮烟瘴雾渐身轻。
鲸波挟飓高如许，
归看澄江旧水清。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_709','广州赠龙鸿胪','祝允明','明','吉水龙夫子，
论交岁月长。
屡衔天子诏，
三使日南王。
却馈舟无宝，
留题稿有囊。
衔杯海滨馆，
远意共茫茫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_710','口占赠徐闻令','祝允明','明','作邑滨南海，
衔恩下北宸。
三吴非异土，
千里亦同寅。
说到襟怀旧，
传来耳目新。
无因便投辖，
欲往活疲民。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_711','广州旅舍有怀提举醝司王廷辅','祝允明','明','阳羡山中王右军，
祓除尘土拥清芬。
高情官下澹如水，
令气座中和若云。
前辈风流今渐少，
平生襟度许平分。
一回聚首一欢乐，
不向天涯叹离群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_712','为王提醝索墨','祝允明','明','荆溪麝煤重似铁，
岭外羊管弱于绵。
婺州伪剂宜恶札，
且望分来用一年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_713','读河源郑明府公牒有感','祝允明','明','读罢昌言耳目明，
头风虽愈沸归情。
海南潦倒江南客，
强饭看君作太平。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_714','宝应衡君公式授宰番禺在都诸君为燕台春饯之什君至粤出示允明倩为补赋','祝允明','明','皇都日日敞离筵，
夫子分符岭海天。
见面谩询为县谱，
观诗遥想过溪贤。
陀楼桂雾迷蛮堞，
宓室秋涛杂雅弦。
我愿君王明万里，
岂宜重咏北山篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_715','赠锲生殷邦宁','祝允明','明','沔阳夫子有佳孙，
四载花斋侍艺文。
合江亭下别我去，
望眼悠悠逐暮云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_716','次韵郭令虎丘千顷云夜坐','祝允明','明','峰顶云擎塔，
门前路接城。
到山先见寺，
近市不闻声。
吊古身逾幻，
凭高酒易醒。
奇中更奇处，
风度县楼更。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_717','次韵郭令虎丘千顷云夜坐','祝允明','明','登山向落晖，
曙色又熹微。
不到上方寂，
安知尘境低。
池星辉国剑，
松露晕朝衣。
民事忧方切，
陶公莫谓非。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_718','遗安堂','祝允明','明','何物堪将付子孙，
襄阳庞老有遗言。
唯留三寸锄头泽，
与作千年葛藟根。
几见危机生白屋，
未容高枕在朱门。
公侯复始人间事，
只恐菑畬笏绶存。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_719','喜友人过访','祝允明','明','每寻云外信，
喜见案头题。
驽驾吾当北，
蛾眉今在西。
风开横海翼，
霜劲踏秋蹄。
二十年来道，
华颠幸不迷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_720','赠杜三表弟','祝允明','明','中表大郎心似水，
通家老弟气如云。
平流浅濑知何用，
五色光华伫看君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_721','和孙二九日','祝允明','明','霜力棱棱酒力禁，
卧游终日似登临。
青山不负谢公操，
黄菊颇知陶令心。
清觞细茗成宾主，
短发长风自古今。
晚步从君聊戏马，
乱峰深处一猿吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_722','赠观','祝允明','明','不知身到转头年，
性子观来已洞然。
铁臼药寒和月捣，
蒲床脚暖踏云眠。
归期笑计铢衣石，
定里閒游宝筏天。
要识来时同我相，
一般门外水中莲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_723','赠道士','祝允明','明','大道于人自不赊，
未须终岁学三车。
云开笙鹤延真驭，
指绕风雷辟众邪。
玄牝谷中金母室，
至阳门上玉皇家。
悬壶满贮春消息，
紫陌任彫千树花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_724','送万寿恩住持碛砂','祝允明','明','东郭名区号碛砂，
主持欣得大方家。
苾刍不碍旁牵蔓，
薝卜能开到处花。
玄鉴杖头酬象马，
归宗拳下辨龙蛇。
真经古集充三藏，
愿假翻寻助五车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_725','送僧还山','祝允明','明','十日云封石榻閒，
偶然飞出又飞还。
送师便拟依师住，
想看梅花欲满山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_726','送洽住天王寺李弟请赠','祝允明','明','权姿妙腊气翩翩，
应世机锋自颖然。
修习久栖三宝地，
主维新属四王天。
高台旷苑宜舒啸，
蒲座香床好息禅。
我为青莲李居士，
挥毫题得壁头篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_727','送谢幼和分教兴化','祝允明','明','芹宫二十春，
经术重同人。
月旦先诸谢，
风流向八闽。
草塘应入梦，
荔子且尝新。
最是襟怀古，
诸生喜饮醇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_728','和吴文定诸公听琴联句','祝允明','明','座有嘉鱼膝有琴，
今人高会古人心。
已闻古奏来盈耳，
更缀华篇作赏音。
聘鲁雅评犹可识，
在齐馀韵窅难寻。
广陵不共嵇公绝，
响逐儿郎鹤在阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_729','闺怀','祝允明','明','静婉那成宠，
娇娆枉自羞。
秦娥箫已冷，
湘女瑟空留。
噩梦疑云雨，
灵期忌女牛。
未禁风绰袂，
无奈月当楼。
蔽膝强含意，
琵琶不识愁。
知谁同薄命，
心欲为通谋。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_730','钱园桃花源','祝允明','明','落英千点暗通津，
小有仙巢问主人。
狂客莫容刘与阮，
流年不管晋和秦。
桑麻活计从岩穴，
萝兔芳缘隔世尘。
只有白云遮不断，
卜居还许我为邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_731','菊圃','祝允明','明','高情别自有风期，
爱是霜馀露后姿。
靖节以来知者寡，
天随而下舍君谁。
誇奇直欲盈千品，
寄兴何妨只一枝。
闲处若能为续谱，
也堪书尾附吾诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_732','月潭','祝允明','明','南溟分取一泓开，
便作嫦娥玉镜台。
魄漾虚金澄万有，
光寒凝碧浸三台。
蛟龙且抱明珠卧，
蟾兔能将桂子来。
平夺霓裳与云锦，
却怜博望乏仙才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_733','谢道士竹鹤斋','祝允明','明','仙房深锁白云间，
君子胎仙共一山。
千个虚心雍伯玉，
一丸浮顶葛洪丹。
瑶台霜莹箫声迥，
珠阙风微羽驾閒。
我欲移家鸡犬畔，
只疑灵境未容攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_734','梅隐居','祝允明','明','平生不识人间路，
万树琼瑶锁竹关。
刚为索诗城市去，
杖藜今始出孤山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_735','赠铁柱宫闵道士','祝允明','明','笋为冠子鹤为衣，
铁弊双鞋只欲飞。
知白自为天下谷，
昏昏默默是玄机。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_736','南浦驿送周训','祝允明','明','放舟南浦草萋萋，
子又东流我又西。
怪此豫章城上月，
清光千里共分携。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_737','题葑门外马生东溪','祝允明','明','吴城三面水为州，
郡郭东南一派流。
羡尔高居占清胜，
更东东去是瀛洲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_738','赠江阴方达之','祝允明','明','岭峤经年未得还，
劳君光彩照尘颜。
故乡自有珊瑚树，
南海何曾见木难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_739','简杨三','祝允明','明','不将黄土点心胸，
六十年来气似龙。
竹坞霜寒青凤峙，
芝田春暖白云封。
各看明月同千里，
共对梅花又一冬。
吴水吴山休负约，
酒壶诗卷日相从。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_740','金陵送徐子昭','祝允明','明','阊门虽不远，
白下忽相同。
仲氏金兰契，
徵君木石风。
抱琴登蒋阜，
拖杖吊吴宫。
拟下陈君榻，
书囊又向东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_741','故相延陵文定公孙仁冠弁窃喜为诗亦以遗之','祝允明','明','四海吴夫子，
成人见冢孙。
礼应先雀弁，
欢满及龙门。
紫鷟非家瑞，
芳兰是国根。
便看瑚琏就，
触目有师存。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_742','见月','祝允明','明','我后久何处，
重光如旧明。
连当三夕见，
喜似百年生。
常仪恒在御，
羲轮日代行。
莫教巫女妒，
淫潦复纵横。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_743','赠张卿','祝允明','明','诸侯严敌忾，
天子极酬功。
进秩三阶重，
提兵九郡雄。
简飞霜气白，
剑绣血膏红。
还应一匡策，
缄在皂囊中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_744','贺汤弟迁居','祝允明','明','与尔为中表，
嗟予多别离。
称觞看雁翥，
迁木指莺期。
杖策时当过，
停云不用思。
加餐更相祝，
行复入京师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_745','山行近白云泉有遥呼于林屋乃瘦石大参也适受风归急不得往抵舍疾甚少间驰怀得句奉呈','祝允明','明','小车芳径出金山，
瞥见仙人水石间。
后客应推先客主，
行云不及定云閒。
烟霞自熟孙登啸，
笙鹤应嗤阮肇还。
想有题名耀丘壑，
可能镵我共苍颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_746','寿徐瘦石大参七十','祝允明','明','邯郸枕里了功名，
安乐窝中适性情。
瘦石烟霞无尽藏，
小山鸡犬亦长生。
云间彩凤衔金简，
花底青鸾度玉笙。
我是橘中同奕者，
定骑龙尾共瑶京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_747','题徐子芳秋庭','祝允明','明','孺子间居与世忘，
萧萧深院映虚堂。
露漙玉干桐孙长，
霜饱金丸橘子香。
白版拄颐迎灏爽，
素丝横膝答清商。
知君不是趋炎客，
长啸一声天地凉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_748','咏梅雪','祝允明','明','阊门佳丽锦为城，
中有仙人降玉京。
罗峤有花花解语，
姑山若雪雪能行。
秾如桃李先当素，
乡自温柔剩得清。
小室维摩唤天女，
鬓丝相映老卿卿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_749','挽都良玉','祝允明','明','曾为瓜圃平生传，
今读东阳哭死诗。
彫谢不禁前辈叹，
风仪长系后人思。
林猿惊上新华表，
鸥鸟来衔旧钓丝。
轩冕知非公素愿，
凤毛方占上林枝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_750','挽沈材广','祝允明','明','当年校艺每同君，
长羡昂昂鹤在群。
半点功名骰子选，
一时声价战场文。
空斋老菊啼秋露，
高冢新松起暮云。
人世漫哀冥世慰，
满枝芳桂散华芬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_751','挽陕妇人','祝允明','明','岂谓中途失少君，
断琴残瑟乱纷纷。
梨花寒食夫君梦，
知逐秦台几处云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_752','寿陈叟','祝允明','明','浑然风气在丘园，
阳抱山前白板门。
得得锄头三寸泽，
悠悠葛藟百年根。
旌旃不用来天使，
轩冕难辞出子孙。
还记三粳兼七秫，
寿乡无日不开尊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_753','寿王贞斋七十','祝允明','明','十霜相别又相迎，
只是当时一样清。
天上选仙惟在善，
物中多寿必由贞。
乡宾近受邦侯礼，
家瑞重看子姓成。
知道洞庭波不竭，
年年酿入紫霞觥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_754','谢道士挽诗','祝允明','明','云房覆清址，
犹自锁虚寒。
耿耿鹤一只，
萧萧竹数竿。
友人留药饵，
弟子宝簪冠。
欲续周师传，
传师与众看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_755','月槎','祝允明','明','老夫欲问广寒事，
只欠扁舟渡海云。
闻有月槎须借我，
授来灵诀却传君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_756','松寿','祝允明','明','陶径曾蒙元亮抚，
君家今辱武功题。
护持长使松无恙，
桑梓清阴百岁齐。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_757','松寿','祝允明','明','手种长松已合围，
翩然骑鹤海天飞。
月明露下虬枝冷，
不见人归见鹤归。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_758','海槎','祝允明','明','老蘖飘摇渤澥滨，
偶然飞上卧闲身。
衣沾织女湔裙水，
石访成都卖卜人。
九汉珠玑光夺镜，
三壶宫阙气如银。
知君半是神仙骨，
携我明年一问津。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_759','题人扇','祝允明','明','扇功本在驱炎上，
不似屏风只好看。
算得题诗真拙计，
却供双眼失清寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_760','鸦','祝允明','明','日中燖得羽毛纁，
强效忠来谁愿闻。
四十颇能知学易，
眼前消息不劳君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_761','竹','祝允明','明','淇园一枝春雨足，
渭川千亩秋风高。
先生青眼对君子，
撚落吟须如凤毛。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_762','水仙','祝允明','明','罢散天花下紫坛，
露横秋袂水鸣环。
凌波欲接君王去，
又恐繁霜不耐寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_763','芙蓉','祝允明','明','赞重清芳却恨迟，
诗人曾费几多词。
春风无限无名草，
莫道芙蓉不遇时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_764','含笑','祝允明','明','如皋未射息侯亡，
不作梁家龋齿妆。
春色晏然花事好，
肯将烽火误君王。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_765','辛夷花','祝允明','明','春丛绀碧杂殷红，
不受中书旧日封。
嬴政少恩君幸免，
年年何事只书空。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_766','芙蓉兔','祝允明','明','霜寒玉线乱秋衣，
叶重花深草气肥。
灵药更无人肯饵，
素娥应道不如归。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_767','衔芦雁','祝允明','明','岁岁随阳计，
秋风三尺芦。
上林光景好，
不见子卿书。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_768','和日本僧省佐咏其国中源氏园白樱花','祝允明','明','剪云雕雪下瑶空，
缀向苍柯翠叶中。
晋代桃源何足问，
蓬山异卉是仙风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_769','牵牛花','祝允明','明','药品能攻疾，
花名强效人。
应无渡河想，
且免服箱辛。
壳绽金铃子，
苞舒碧角巾。
步行骑水牯，
欲觅了无因。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_770','鹡鸰','祝允明','明','长枕三郎作颂时，
桂宫兰殿重含思。
宁哥可是知人意，
小院梨花玉笛吹。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_771','鹌鹑','祝允明','明','利口如锥岂利身，
名题越调耳常新。
莫教轻与人将去，
又遣金陵枉杀人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_772','宣宗皇帝画马图','祝允明','明','昔日宣皇履至尊，
尧章焕焕满乾坤。
三千在御均承宠，
一匹沾恩便不群。
马法尽来空地类，
龙图呈处是天文。
丹青不逐乌号去，
从此房星似掩昏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_773','家藏刘松年小方','祝允明','明','暗门终日痼烟霞，
写得东南处处佳。
湖上烟波志和宅，
山阴风雪戴逵家。
老僧引涧穿新竹，
童子和云扫落花。
揖客入门如有影，
石墙松盖夕阳斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_774','家藏李兴宗毛女','祝允明','明','宝瑟无弦尚自随，
秦声那复记当时。
山头剥枣分猿吃，
云里巢笙唤鹤骑。
见说刘郎驱项籍，
空劳徐韨觅安期。
华阴万树长松叶，
却笑君王未得知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_775','题陈道复画','文嘉','明','襄阳墨沈未曾乾，
十里潇湘五尺宽。
樵斧不禁苔径滑，
渔蓑常傍水云寒。
澄澄僧眼连天碧，
澹澹蛾眉隔雾蟠。
恐为醉翁当日写，
平山堂上雨中观。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_776','家藏高尚书松阴落涧图','祝允明','明','倚壑高松一万株，
拂岩飞瀑氎巾铺。
白龙隐映苍龙舞，
山气虚兼水气濡。
净壁沈沈悬瑀佩，
空堂隐隐奏笙竽。
平生负得匡庐约，
幸拜尚书赐不孤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_777','子昂小景','祝允明','明','春山雨新沐，
掩霭结浓绿。
一叶金芙蓉，
粲粲迎朝旭。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_778','子昂小景','祝允明','明','渔舟何所至，
两两镜光中。
沿洄溯春涨，
更喜天无风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_779','子昂小景','祝允明','明','江亭小于艇，
松子落满顶。
尽日无人来，
流水抱虚影。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_780','子昂小景','祝允明','明','晴阳破岚暝，
水色当春和。
如何异人境，
而有樵者歌。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_781','子昂小景','祝允明','明','隔坞有绝壁，
萝扉对山开。
客子何为者，
能入深山来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_782','吴镇小笔','祝允明','明','树欲化龙先带雨，
泉将归海已如涛。
直恐化人移幻境，
莫誇墨沈与霜毫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_783','戴文进小幅','祝允明','明','峭壁遥撑落照危，
蜿蜿曲陇绕脩陂。
前头径转峰回境，
说与时人定不知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_784','沈徵君遇小景','祝允明','明','藤花垂露媚苍龙，
山静岚深草气融。
紫褐玉琴空指点，
白云楼阁锁重重。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_785','沈徵君遇小景','祝允明','明','净壁虚亭杨柳青，
阑干白袷午风轻。
披残一卷黄庭诀，
不见人声有鹤声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_786','边文进翎毛二首','祝允明','明','的历丹饴妃女唇，
含来名重不胜春。
柏梁台上刘郎老，
断送因他郭舍人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_787','题徵明画','祝允明','明','苍帻滃沈雾，
白氎垂虚泉。
归帆信流水，
万襟同澹然。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_788','徵明墨菊','祝允明','明','冻砚呵寒下笔迟，
须眉幻出陆天随。
知君绕指冰霜走，
更把冰霜吐作词。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_789','金山图','祝允明','明','昔年曾趁海门潮，
独向龙宫吊寂寥。
衬席寒风不成梦，
老蛟一夜献琼瑶。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_790','题何大参菊花图卷子','祝允明','明','花有仙灵笔有神，
化权终不在阳春。
一般秋色成千品，
前度桃花却后尘。
谁信珠玑颜色好，
独怜霜雪性情亲。
菊诗万首从君选，
未必微篇愧古人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_791','戏题子畏墨竹','祝允明','明','唐郎写竹如写字，
正以风情韵度高。
我解平章不能写，
未曾分得凤凰毛。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_792','胡马图','祝允明','明','骏骨千金产，
名王万里归。
风烟辞大漠，
云电赴皇畿。
立仗容陪舞，
从龙敢假威。
此来空地类，
苜蓿近郊肥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_793','省耕图','祝允明','明','老农真我事，
何敢笑樊须。
植杖芸苗处，
伸眉纳税馀。
锄头三寸泽，
田舍五行书。
饱饭高眠熟，
朱门未必如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_794','子儋画梅','祝允明','明','子儋屋润体复胖，
写出冰花朵朵寒。
何物指头能尔许，
元来铁石是心肝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_795','琵琶士女','祝允明','明','马上明妃万里行，
四条弦里断肠声。
如今纤手朱丝底，
不唱离情唱合情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_796','伫立士女','祝允明','明','非缘望远上秦楼，
杨柳依依翠陌头。
画就远山调锦瑟，
最怜夫婿不封侯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_797','题画','祝允明','明','一溪流水半山云，
山桂绵绵日夕芬。
莫言丘壑藏名姓，
高士他年自传君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_798','道士鹅','祝允明','明','曾从老远说遗经，
净影堂前几岁听。
未必右军今有笔，
莫将轻易换黄庭。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_799','绝句','祝允明','明','寒光交逗眼苍然，
半夜人间别有天。
想得非仙亦非鬼，
四山风雨拥孤眠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_800','杂题画景三十一首','祝允明','明','秋浸具区天地寒，
老崖垂脚怒龙蟠。
仙人夜半骑龙去，
木客潜窥古灶丹。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_801','杂题画景三十一首','祝允明','明','断崖横截傲崇冈，
风叶满林斜日黄。
十岁采薪多伴侣，
不知翁子有他肠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_802','杂题画景三十一首','祝允明','明','五月江湖风雨多，
钓矶平没夜来波。
深林中有扬雄宅，
莫怪时人载酒过。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_803','杂题画景三十一首','祝允明','明','云母薄梳青石发，
水花肥点碧荷钱。
树根一坐空山老，
不许时人问岁年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_804','杂题画景三十一首','祝允明','明','赤城霞断逗秋晖，
阊阖风高不耐衣。
极目水天无了际，
先生何处朗吟飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_805','杂题画景三十一首','祝允明','明','滃合浮云晚放晴，
溪山相照寂无声。
不知问字人何处，
门外孤舟尽日横。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_806','杂题画景三十一首','祝允明','明','面面青山曲曲溪，
流云易度石墙低。
苔生任把门踪合，
鹤返容教树杪栖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_807','杂题画景三十一首','祝允明','明','琅琊台顶太山杪，
我欲去登须御风。
稽首东皇拱双手，
金乌高捧一轮红。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_808','杂题画景三十一首','祝允明','明','烂银盘圆一千里，
白玉髓喷三万重。
老蛟背驮龙女泣，
百斛宝珠抛海东。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_809','杂题画景三十一首','祝允明','明','霞捲夕阳天外天，
抗风疏柳几枝偏。
抛将湿网坡头晒，
且旁网边乘醉眠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_810','杂题画景三十一首','祝允明','明','暗崖悬立玉龙飞，
怒蹴层冰万马齐。
半夜哀音和空谷，
愁翻木客唤猿啼。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_811','杂题画景三十一首','祝允明','明','玄文草罢坐川湄，
川与心同清静时。
此地可忘新汉事，
莫将轻易与人知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_812','杂题画景三十一首','祝允明','明','溪桥回转鸟声微，
杖屦萧萧两布衣。
不是耕夫出莘野，
秋风落日采薇归。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_813','杂题画景三十一首','祝允明','明','老石空林了此生，
一江秋水对人清。
扁舟若为求鱼出，
莫向茆亭脚下行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_814','杂题画景三十一首','祝允明','明','天空地阔偶相逢，
散漫寒流砢閜松。
不用方舟细商略，
到头岐路总难同。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_815','杂题画景三十一首','祝允明','明','覆有高林载有苔，
石公木客可参陪。
山居事业略完具，
只是无人肯入来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_816','杂题画景三十一首','祝允明','明','破屋依依寂寞滨，
千山头白树存身。
洛阳县令曾知否，
中有饥吟僵卧人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_817','杂题画景三十一首','祝允明','明','阔屦宽袍顶不巾，
天和拍拍面浮春。
横拖杖子前山去，
知是人间不吏人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_818','杂题画景三十一首','祝允明','明','秋水浮船五尺深，
也无情事到讴吟。
十年荡桨无人问，
却有飞鸿识我心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_819','杂题画景三十一首','祝允明','明','溪林元不择人清，
自少人来向此行。
若使行人多此处，
谢安何必有高情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_820','杂题画景三十一首','祝允明','明','岩谷空明溪水冷，
高人据梧目若瞑。
行留坐卧都不省，
短发长风弄疏影。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_821','杂题画景三十一首','祝允明','明','桃花柳花覆春洲，
燕儿鱼儿迎客舟。
青天白云紫翠嶂，
虚桥小浦回环流。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_822','杂题画景三十一首','祝允明','明','吟诗写画似参禅，
不向他人被里眠。
生公堂前点头石，
天平山上白云泉。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_823','杂题画景三十一首','祝允明','明','曾到和宁市上来，
江山满壁照人开。
都输此幅丹阳景，
回首烟花暗凤台。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_824','杂题画景三十一首','祝允明','明','柳娘标格重经眼，
玉屑珠尘满扇头。
彷佛和宁街上见，
桃花杨柳障春羞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_825','杂题画景三十一首','祝允明','明','落日采薇归，
萧萧两布衣。
尔来人采少，
春雨长顽肥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_826','杂题画景三十一首','祝允明','明','灵岩好个景，
凿得不成山。
人自要头白，
山头也会斑。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_827','陇头泉','张元干','宋','少年时，
壮怀谁与重论。
视文章真成小技，
要知吾道称尊。
奏公车治安秘计，
乐油幕谈笑从军。
百镒黄金，
一双白璧，
坐看同辈上青云。
事大谬，
转头流落，
徒走出修门。
三十载，
黄粱未熟，
沧海扬尘。
念向来浩歌独往，
故园松菊犹存。
送飞鸿五弦寓目，
望爽气西山忘言。
整顿乾坤，
廓清宇宙，
男儿此志会须伸。
更有几渭川垂钓，
投老策奇勋。
天难问，
何妨袖手，
且作闲人。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_828','陪芸轩观海宿村家纪事四首','顾清','明','三月吴江上，
垂杨作意青。
两堤烟冉冉，
一路雨冥冥。
客况今初识，
舟行未可停。
渔翁不愁惧，
独立钓前汀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_829','陪芸轩观海宿村家纪事四首','顾清','明','云合天如羃，
江翻浪若飞。
众山当昼隐，
孤树入烟微。
舟楫危前路，
庭闱感昨非。
不知天早晚，
时见牧童归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_830','陪芸轩观海宿村家纪事四首','顾清','明','暝入空江路，
茫茫问所投。
电光时掣剑，
雨势欲翻舟。
鸿雁鸣何及，
蛟龙怒未休。
前村有灯火，
渐近复生愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_831','陪芸轩观海宿村家纪事四首','顾清','明','中流失舟楫，
一瓠千黄金。
风雨江村暮，
野人怀顾深。
沾濡免僮仆，
欢会洽朋簪。
惜哉漂母意，
当者非淮阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_832','水仙扇面','顾清','明','瑶池不见董双成，
清梦依依绕玉京。
岁晚相逢洛川路，
一江寒碧月空明。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_833','绝句','顾清','明','云暗西山雨欲来，
好风先到读书堆。
幽人正熟羲黄梦，
乱揭床头书卷开。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_834','庚子秋日书感','顾清','明','槐花如雨落秋金，
睡起凭阑思不禁。
满地绿阴容我懒，
一篇长句向谁吟。
马因捷步翻成蹶，
水到无声始是深。
世事相逢已如此，
此生何必漫劳心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_835','送沈惟馨赴举和陈刚中韵','顾清','明','朝阳有鸣凤，
高冈有梧桐。
男儿生盛时，
肯负气吞虹。
君不见饭牛者，
长歌白石齐东野。
尧传舜继虽不逢，
奋起犹能奠青社。
又不见和氏璧，
胚胎本是山中石。
镌磨一日遇良工，
遂与镇圭登紫极。
丝衣采采青于蓝，
江边握手皆停骖。
便登万里道，
肯恋一夕谈。
长风巨浪在足底，
莼丝菰米焉足甘。
送子出九山，
山鸟鸣间关。
官亭杨柳不用攀，
笑指孤鹗青云间。
送子涉淀湖，
画桨摇清波。
凤山回首何嵯峨，
袖中雄剑鸣蛟鼍。
雍雍鸣凤，
菶菶梧桐。
一川秋水，
两腋清风。
辍耕鹿门陇，
献赋长杨宫。
干羽舞两阶，
日月明重瞳。
云梯一回首，
扰扰多沙虫。
嗟我此行不得相从兮，
但虚窗静夜梦想秦淮四壁之高峰。
秋风好消息，
早寄南飞鸿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_836','沈惟馨之赴举也予既有诗和陈刚中韵送之矣今再寄七律一首','顾清','明','凤凰台下簇雕鞍，
台上云封十二阑。
日炫龙光钟阜晓，
空蟠虎气石城寒。
凌风有梦排天阙，
鞭石何由泛海澜。
吹彻紫箫天似水，
月明犹想独乘鸾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_837','题竹','顾清','明','兔颖凉分月魄，
凤毛寒湿松烟。
日暮白云飞尽，
一天秋色苍然。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_838','枯木睡禽','顾清','明','皇仁覃八荒，
虞网解三面。
小鸟深山中，
独宿不惊眄。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_839','咏二乔得真字韵','顾清','明','铜雀金陵总未真，
六朝花月几经春。
阑干误喜逢倾国，
却是丹青卷里人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_840','北坛斋宿','顾清','明','初月明远树，
繁星丽高空。
清坛矗紫垣，
周道蟠青虹。
地胜宅壬坎，
木秀扶杉松。
惟时八月初，
万象呈秋容。
长原锁寒碧，
乾树明新红。
嘉谷卧连野，
败稂枯作丛。
岁功奄铚艾，
吉日临著雍。
时祀不敢后，
冠盖来童童。
微名系官府，
将送烦仆僮。
追随缙绅后，
周旋尊俎中。
仰瞻霄汉间，
神光煜昭融。
骏奔既肃穆，
对越何昂颙。
官备物有纪，
夜寂天无风。
清乐发丝竹，
严令闻鼓钟。
笾豆纷夙饤，
醢菹簇时供。
长烟起苇炬，
画烛辉雕笼。
霓幢隐双凤，
云軿留六龙。
和熙洽幽玄，
蜚蚃闻苍穹。
由来诚敬孚，
不在仪品丰。
吾闻古王都，
右社而左宗。
宗以明祖德，
社以昭神功。
民非土与谷，
生养安所从。
所以古至今，
严祀无终穷。
吾侯素勤理，
祀事尤寅恭。
饮食神既嗜，
茀嘏宜来崇。
君看秋野间，
万宝如崇墉。
百室会盈止，
醴醪各迎逢。
闾阎礼让行，
囹圄莓苔封。
神功不可忘，
允侯诚所通。
作诗纪盛事，
窃效康衢童。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_841','破镜篇','顾清','明','破镜宁终破，
不愿重入奁。
断弦宁终断，
不愿鸾胶粘。
人生一生惟一死，
此身岂可轻相许。
因循一语涉狐疑，
死向重泉作羞鬼。
所以古志士，
跬步不敢轻。
譬逢三岐路，
熟问乃敢行。
屹立万仞冈，
决眦孤风生。
乾坤落落一身远，
风尘混混双眸明。
古人已去不可作，
末世吁嗟轻唯诺。
昨日仇雠今友朋，
朝哭泣兮暮欢谑。
凉风萧萧吹客衣，
苍茫岁晚孤鸿飞。
梅花夹道慵举首，
涕泪满襟怀昔时。
我愿天地间，
万事皆从愿。
有始必有终，
不作风花片。
陶然百岁中，
永绝痴儿面。
君不闻蔡琰胡笳十八拍，
千载英雄泪如霰。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_842','征妇词','顾清','明','银灯花落夜迟迟，
最忆灯前笑语时。
哀乐易迁惊逝水，
关山无路怨娥眉。
风沙漠漠人何在，
星汉迢迢鹊亦疑。
见说天山弓未挂，
敢将清泪浪沾颐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_843','村居杂兴六首','顾清','明','屋东小堤长半里，
疏柳成行荫秋水。
无风时复一叶飞，
有风终夜鸣不已。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_844','村居杂兴六首','顾清','明','庭前蔷薇好枝叶，
初秋落残冬更发。
虽无颜色媚西风，
甘与贞松待霜雪。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_845','村居杂兴六首','顾清','明','石榴经霜红满枝，
前年三月移根时。
珠囊玉醴纤手擘，
幽人为尔惊栖迟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_846','村居杂兴六首','顾清','明','盆池养莲期看花，
两年不发吁堪嗟。
浮萍叶死水痕长，
微波蹙蹙跳鱼虾。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_847','村居杂兴六首','顾清','明','梅花吾侪之故人，
寂寞短篱今五春。
迟唤南邻锦囊客，
月明为返罗浮魂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_848','村居杂兴六首','顾清','明','灵均沈湘陶令死，
篱下寒香久无主。
江边一笑倚清秋，
烂漫西风几今古。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_849','秋夕露坐作','顾清','明','玄天大无匹，
要亦有穷处。
不知穷处外，
旷莽复何寓。
茫然仰太虚，
㗳尔消万虑。
规规尘网中，
龌龊焉足谕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_850','登夏时茂澄碧览翠二楼','顾清','明','澄碧高楼三泖东，
阑干如画倚江空。
风传鹤语滩声静，
潮挟龙腥海气通。
万象尽沉云影底，
八窗都在月明中。
抛书便作南昌梦，
秋水长天一色同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_851','登夏时茂澄碧览翠二楼','顾清','明','越水吴山指顾中，
虚檐百尺卧元龙。
都将宇宙清明气，
散入江湖礧磈胸。
天末鸟飞云淡淡，
海门烟散树重重。
若为借得湘妃瑟，
鼓向江南十二峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_852','寒夜','顾清','明','晚云欲雪寒模糊，
微月递明光有无。
枯桑林头北风急，
山鬼叫啸林鸦呼。
此时柴门寂如磬，
借问夫子何为乎。
一盏油灯照虚壁，
梦在洙泗谈黄虞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_853','夜半灯尽作','顾清','明','寒鸡声啾啾，
阴墙明残雪。
推窗月当户，
始闻二鼓歇。
残编有至味，
鼋鼎芬在列。
夜阑烛复尽，
此意谁共说。
严风逼两袖，
揽衾更骚屑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_854','雪中对客','顾清','明','茅屋无风已自寒，
客来飞雪满遥山。
相看只合围炉坐，
欲去谁能放棹还。
梅萼映空增怅望，
松枝低槛故阑珊。
平生陶谷多才隽，
愁绝佳人一笑间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_855','除夜','顾清','明','更无柏酒共桃符，
一卷离骚伴竹炉。
短褐有情怜岁月，
敝冠无恙笑头颅。
白波东逝伤心远，
青鸟西飞入望孤。
久卧沧江惯愁思，
不将明日问荣枯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_856','辛丑春夜闻雨','顾清','明','破屋寒多怯夜眠，
骤闻鸣雨更欣然。
已拚窗下琴书湿，
暗喜庭前草木鲜。
檐溜不齐时点点，
灯花无谓故娟娟。
清时美景双惆怅，
卧听淋浪百虑煎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_857','遣兴','顾清','明','门掩青萝月，
窗含绿树烟。
咿吾閒白昼，
寂寞任长年。
荒野无穷日，
沧江不尽天。
伤春复怀友，
怅望一凄然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_858','遣兴','顾清','明','绿重墙头柳，
红欹谷口桃。
燕轻翻水捷，
鹳暖入云高。
好景宜佳句，
残尊有浊醪。
故人沧海上，
相忆钓金鳌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_859','雨不止','顾清','明','细雨久不止，
江皋泥渐深。
出门妨散步，
隐几独长吟。
柳重墙头压，
苔添石面侵。
烟云方满眼，
花鸟莫关心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_860','春日将适郊外忽暴风阻行','顾清','明','二月六日天气恶，
捲地黑风吹倒人。
却看花柳俱无色，
忽讶江山不似春。
高卧野人滋懒散，
欲飞燕子自逡巡。
东园有约不如意，
须待来朝理钓纶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_861','写怀','顾清','明','美酒新丰市，
轻车洛下城。
星霜悲聚散，
寒暑递枯荣。
彤管三千字，
青冥十万程。
辽天来去雁，
华屋短长檠。
烟柳风中乱，
溪云席上横。
西山朝有气，
北斗夜无声。
病得休文瘦，
贫看季子轻。
几年嗟敝褐，
此日笑长缨。
茅屋依江静，
林花近眼明。
芊绵随绿草，
怅望听流莺。
画虎将焉用，
屠龙竟未成。
扁舟徒漾漾，
春水故盈盈。
尚觉乾坤大，
空馀梦寐清。
一枝原树鹊，
百丈海天鲸。
落月愁何奈，
沧洲岁屡更。
途穷滋懒钝，
时屈藉幽贞。
雅郑难同调，
枭鸾本异鸣。
永怀萍泛泛，
敢谓铁铮铮。
遇竹时题句，
逢鸥且问盟。
茂先如可作，
雄剑在延平。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_862','春日杂兴','顾清','明','东风一梦过南园，
吴水吴山兴杳然。
经雨落花还似锦，
弄风柳絮不成绵。
林𤠔夜啸空哀月，
江鸟晴飞欲傅天。
处处兰桡移白昼，
边生终日枕书眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_863','春日杂兴','顾清','明','群山西北翠如烟，
三女荒冈草树连。
瑶井鹤鸣凡几岁，
碧潭龙去不知年。
潮平沪渎城头月，
花落云间洞里天。
千古废兴如昨日，
几回窗下掩残编。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_864','春日杂兴','顾清','明','泛观今古不胜哀，
又向江边步绿苔。
曾见楚兵回柏举，
谁教越女上苏台。
君臣得失馀文史，
罗绮繁华遍草莱。
最恨鸱夷五湖去，
胥涛空涌浙江雷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_865','春日杂兴','顾清','明','千雉孤城枕碧流，
晴天望远自生愁。
金羁络绎花边马，
玉雾葱茏柳外楼。
何处健儿誇仗剑，
几年渔父独垂钩。
白鸥飞入苍烟里，
目断斜阳送去舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_866','环溪十咏得莼菜','顾清','明','秋风吹嫩碧溪莼，
春韭寒菘别置伦。
入手细牵青不断，
盈筐满贮绿仍匀。
许同玉脍成双美，
未数金盘馔八珍。
多渴长卿愁内热，
谢他清淡养天真。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_867','锦衣归钓图','顾清','明','天上归来锦作袍，
吴江春水泛蒲萄。
傍人未识扁舟意，
犹道先生学钓鳌。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_868','八月十五夜','顾清','明','月色好如此，
欲吟谁起予。
钩帘望南极，
散履下前除。
润气连沧海，
浮光混太虚。
旷然心境会，
端坐念玄初。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_869','秋兴和芸轩韵','顾清','明','海峤千峰插汉齐，
每因松竹问幽栖。
江山举目成图画，
天地从人作品题。
身隐不妨随鹿豕，
门閒应得长蒿藜。
何须绿野功成后，
始是黄梁梦破时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_870','秋兴和芸轩韵','顾清','明','伏雨阑风日未休，
越山吴水共悠悠。
鸾书不返瑶台暮，
雁阵争回碧树秋。
敝褐有情依客子，
断碑无主怨王侯。
平生宋玉多悲感，
拟脱青衫趁白鸥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_871','秋兴和芸轩韵','顾清','明','碧海萦回天际还，
海山青翠束连环。
铜城北望三千里，
金斗西横百二关。
落月有时闻画角，
夕阳何处倚危阑。
清江面面芙蓉满，
安得凌波却暂攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_872','冬至书怀','顾清','明','阴尽阳复回，
年华递相促。
明灯坐深夜，
长叹拊髀肉。
忆昨童丱初，
未念寒与燠。
依依邻舍儿，
游嬉日相逐。
九龄事书史，
稍解知捡束。
十三文义通，
孜孜务磨琢。
维时心尚孩，
寒暴略相续。
逡巡邻弱冠，
人事有颠踣。
旧业竟萧条，
凄然泣松竹。
系名庠序间，
晨暮恒碌碌。
夙心虽未改，
奈此尘嚣渎。
翻思少日误，
閒暇安可复。
今年值霪雨，
积潦弥旬朔。
荒居迫沮洳，
下床水没足。
鱼行仅两月，
闷绝每思哭。
侵冬始安居，
卒岁已无谷。
匆匆日复日，
不觉流光速。
朝来日长至，
推枕乃惊𥈭。
清晨随冠冕，
州衙拜黄屋。
于惟万乘尊，
至德春同育。
顾兹岁小歉，
圣心已烦蹙。
恭闻遣明诏，
四出洗冤狱。
人和天乃应，
生意岂长鞠。
惟应西江水，
不及辙中涸。
归来茅屋底，
寂寞对僮仆。
仰看天意愁，
雨雪交相属。
侵陵及兰蕙，
摧压倒松菊。
海宫东南天，
一望云弥目。
傍村八九家，
悄若住空谷。
往来迹已断，
况乃相贺祝。
物情厌荒落，
天亦恨幽独。
闭门日易暮，
忽已见灯烛。
所思渺云汉，
谁与论心曲。
须臾雨声歇，
窗隙风簌簌。
夜久寒转严，
指直不敢触。
寒炉拨残灰，
邈矣拱先躅。
因思古达士，
涉世多翻覆。
譬之百鍊金，
历久乃精熟。
蹇予沙矿姿，
敢尔恨幽辱。
顾此年岁长，
便便止空腹。
烟云方满眼，
何时见清旭。
维东有沧海，
浩漫侵坤轴。
其上通星辰，
其下连河渎。
吾将驾灵查，
一访巫咸卜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_873','海棠四首','顾清','明','濯锦江头富贵花，
何年流落海天涯。
玉人二八空闺里，
岁岁因君感物华。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_874','海棠四首','顾清','明','屑玉涂坯艳一丛，
内园开处锦屏幪。
何人错认杨妃醉，
泪湿春风忆梦中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_875','海棠四首','顾清','明','日暖风暄人意慵，
海棠正向此时红。
谁云花好能消恨，
花恨于人更不同。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_876','海棠四首','顾清','明','香颊潮红亸翠襦，
绛唇微吐滴胭脂。
游丝不动日停午，
斜倚东风若有思。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_877','通波塘泛舟沈惟馨王大用钱时敛联句','顾清','明','舟出五里塘，
迢迢去路长。
水花红近眼，
烟柳绿成行。
茅屋依山小，
汀兰拂棹香。
时时见渔父，
击楫下沧浪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_878','梦登连阁甚高敞前绕群山松影披拂檐下真异境也赋诗八句而记其半漫识于此','顾清','明','高阁凌虚拂紫霄，
四檐轩敞接连鳌。
千岩对起龙蛇窟，
两足亲登凤鸟巢。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_879','相先生具庆堂','顾清','明','尧日仁风遍，
莱庭瑞气重。
康强惟德召，
和乐自天钟。
甲第花迎户，
高堂雪覆松。
伯鸾才不衒，
德耀礼偏恭。
穆穆金兰契，
娟娟玉树容。
纮綖催夜绩，
杖屦阅春农。
景入榆林晚，
甘回蔗境秾。
鞶缨晨济济，
笙鼓日雍雍。
偕老无遗恨，
传芳有亢宗。
已全三釜养，
行遂五花封。
委曲吴江水，
微茫泰岱峰。
题诗遥献寿，
春色两融融。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_880','醉书','顾清','明','车不避太行坂，
舟不辞滟滪堆。
男儿生不履穷途，
一生肝胆何由开。
君不见东鲁缊袍子，
君不见南海伏波老。
二旬九食未为病，
白头意气日矫矫。
英雄未遇龙蟠泥，
他日何缘悔曩时。
逝将白石砺吾齿，
饥来快嚼南山芝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_881','巢云为倪举人赋','顾清','明','越山山人迹大奇，
卜居直与浮云齐。
诛茅不畏虎争穴，
拓地远教龙择栖。
初来尚嫌巾履湿，
住久更觉青天低。
飞旌卷旆互明灭，
松窗石榻同凄迷。
时时蒸翠落书幌，
往往空青沾杖藜。
山人前年不出山，
丹崖绿壑时攀跻。
半筇横绝陇头路，
一犁耕破芝田泥。
今日山人振衣起，
飞云万里随东西。
翻腾百川雨九土，
变化岂复知端倪。
云兮能舒复能卷，
世间万事如蓬转。
岩崖霄汉各有时，
男儿那得长偃蹇。
作歌赠君殊短短，
功成旧巢莫相远。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_882','尝瓜得麻字','顾清','明','旋拔霜刀剖玉瓜，
清甘入口四筵誇。
凭君莫问渠家世，
见说青门又种麻。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_883','待月轩为钱塘沈廷璧赋','顾清','明','高轩峨峨临水开，
虚檐四敞无纤埃。
主人为此兴不浅，
要待嫦娥天际来。
晴空落日清如洗，
远水微茫翠烟起。
清簟疏栊半捲帘，
思入沧溟几千里。
沧溟迢迢天汉东，
玉蟾戏水龙王宫。
清辉只尺不可睹，
幽情烂熳迷云空。
有时掀髯琢诗句，
乌鹊啁啾隔烟树。
长吟呼起白凤来，
恨不同飞碧霄去。
有时凭阑吹洞箫，
箫声幽咽惊潜蛟。
倦来梦入水精殿，
寒光百道飞银瑶。
香残烛冷催更鼓，
遐想苍茫极今古。
牛渚金陵夜夜天，
风流百世俱尘土。
感时抚事情依依，
东望蓬莱意转迷。
绕阑风露不知冷，
隔水松篁应惨凄。
钱塘亦是三江地，
风景寻常接宵寐。
抚卷知君信可人，
不觉神飞渡江澨。
我歌待月篇，
月应解我意，
不用阑干苦凝睇。
少迟银桥天际起，
与尔同舞霓裳队。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_884','久雨','顾清','明','江上痴云接地低，
闭门终日看凄迷。
东园有约无由到，
想见春泥没马蹄。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_885','癸卯立春日寄陆时敏','顾清','明','五载蓝袍触暗尘，
梅花风起又新春。
漫怜司马长多病，
自说莱芜已惯贫。
经雪松篁犹在眼，
弄晴禽鸟渐宜人。
风光此日催诗梦，
已入芳洲采绿蘋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_886','初赴举时赋七律一首留别诸公适时敏以诗来即用其韵','顾清','明','同时济济尽英才，
况复清朝景运开。
幸与诸公作先路，
敢期三策便抡魁。
秦淮山好天开画，
扬子江深地走雷。
应到高秋明月夜，
思君直上凤凰台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_887','奉饯郡守稷山王侯得凤字','顾清','明','南薰不入虞弦弄，
两岐每诧渔阳诵。
岂知三年东海头，
黍稻连云茧如瓮。
皇华问俗已知本，
丹扆思贤每劳梦。
双旌此去谁能留，
矫首梧冈听鸣凤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_888','初举不第却回书所历','顾清','明','潜鱼不出椮，
栖鸟不出林。
不因风雷便，
岂识天地之大江湖深。
天风飒飒吹黄槐，
江船击鼓凌晨开。
便为万里客，
岂复儿女猜。
云帆悠悠渡三泖，
已觉从来双眼小。
瞥然一瞬出淀湖，
使我尘襟豁如扫。
将军祠前芳草多，
阴廊古瓦封苔窠。
英雄恨杀白衣橹，
千载此地还来过。
陈湖北来势尤大，
气象浑疑在天外。
波光黯惨迷西东，
惊雷喷雪吹腥风。
同舟十人半失色，
我疑此处藏蛟龙。
湖西一带风初静，
呼酒开筵共相庆。
推蓬又觉眼豁然，
黄天独墅天相连。
向来颠沛几不免，
到此始知应自怜。
出门只尺已如此，
况乃天涯千万里。
何处池塘杨柳青，
谁家门巷炊烟起。
依稀渐觉风景佳，
前头已是姑苏台。
夫差句践两寂寞，
倡讴市语喧如雷。
扬帆径逐东风便，
不尽平生游览愿。
扁舟信宿过望亭，
锡山如画遥相迎。
道傍深刻十三字，
千载不磨贤令名。
毗陵郭里舟初住，
榆叶零零杂风雨。
綀衾独拥不成眠，
是夕方知有羁旅。
丹阳自昔称畏途，
我实初行兼病躯。
蹇驴登登不能止，
缘崖历谷何萦纡。
日斜憩足句容道，
尊酒聊将润枯槁。
当垆可是临邛人，
茜裳廉纤不动尘。
人言巫山在平地，
对面已隔黄姑津。
风尘浩荡催征马，
西望金陵去如写。
片云飞来我已愁，
顷刻滂沱遍原野。
道边茅庐大比拳，
俛首急入如穷猿。
苍皇已识异乡味，
帡幪始知大厦恩。
行行见说宸居近，
趣马加鞭气重奋。
此时天公亦开晴，
氛埃涤尽穹宇清。
中和桥上初登览，
目极遥天发深感。
江山如此不早来，
几向此生虚𡒄坎。
钟山如龙云际来，
石城双阙中天开。
固知传闻不虚假，
神祖规模真壮哉。
长衢荡荡平于砥，
井画棋分各条理。
接栋连甍如灌云，
去马来轩若流水。
声华文物竞奢豪，
公子王孙处处遭。
佳人总为王幼玉，
将军不数霍嫖姚。
东山明月西江水，
尽日寻游看不已。
细柳深藏朱雀桥，
飞花暗满长干里。
自从失脚下青冥，
往迹回看如败枰。
束书羞咏月中桂，
鼓棹还为江上行。
长江三面山如壁，
环拱金陵护宸极。
古称天堑信非虚，
自是荒淫足亡国。
波平风稳帆樯健，
倏忽金山当我面。
奇形秀色画莫工，
信知天巧非人功。
平生梦想不可到，
足慰此行樵悴容。
南徐自古雄豪地，
到此令人益奇气。
惜无许浑千首诗，
洗我胸中不平事。
舟行半日下丹阳，
新丰美酒又闻香。
同行半是同来伴，
相对不言空感伤。
搴篷径指吴门路，
一片归心乱云雾。
江山不学苏秦家，
风景苍苍只如故。
故园到日天已寒，
江枫落叶秋斑斑。
青尊提携湛绿醑，
故人为我开欢颜。
西风落日吹芳菊，
共挹寒香散幽独。
困穷拂郁岂徒尔，
况我霜毫未应秃。
君不见芙蓉花生江皋，
秋风未至宁萧条。
又不见千里驹服盐车，
霜蹄一蹶气转加。
丈夫结束自有地，
肯学儿女空愁嗟。
风帘日暮展书读，
炳炳丹青照人目。
临渊羡鱼知已非，
呼童静掩林间屋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_889','读庄子有感','顾清','明','落日平林烟雾生，
西风茅屋短檠明。
书生已惜三千字，
狂客犹誇九万程。
蛮触干戈神独领，
蜉蝣日月梦潜惊。
旧游亦有芝兰契，
冰雪何人与问盟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_890','少年行','顾清','明','驱车上太行，
前有九折坂。
回车下平原，
毕竟无人挽。
升高望同行，
去去日已远。
及今努力尚可追，
西山白日下来时。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_891','甲辰九月五日迎司马兰亭过蔡廷章宿','顾清','明','岸侧野花香拂棹，
竹间细水暗通船。
尘中已觉俱成梦，
幽处真疑别有天。
红敛江村寒映日，
翠浮沙市晚生烟。
平生不为耽幽兴，
容易那能到辋川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_892','甲辰九月五日迎司马兰亭过蔡廷章宿','顾清','明','清霜未降枫先赤，
紫蟹初尝菊半黄。
终岁只闻田舍乐，
一时顿觉市朝忙。
清晨雁鹜盈前浦，
落日牛羊满近冈。
为问东皋有馀地，
便应从此作邻庄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_893','感兴六首','顾清','明','青皇播群品，
百鸟和声音。
秋风一夜起，
绕屋寒蛩吟。
四时有代谢，
何况古与今。
怀哉刘文苑，
高卧紫山岑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_894','感兴六首','顾清','明','凤凰长丹穴，
不识乌与鸢。
飞飞度中州，
关山郁芈绵。
文翰一震耀，
百喙起纷然。
昆崙有瑶树，
玄洲多玉田。
下有醴泉流，
上有蔚蓝天。
谁能复记虑，
一去三千年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_895','感兴六首','顾清','明','兀兀深夜坐，
迢迢千古思。
弃我万镒宝，
坐此一饭羁。
前瞻日既远，
内顾心还悲。
兰荆不同长，
绿发坐成丝。
彦明古烈士，
谁哉继馀辉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_896','感兴六首','顾清','明','投鼠且忌器，
爱牛搏其䖟。
事固有大体，
一怒安可凭。
所以古圣哲，
远览穷千龄。
岂无一决勇，
而独务含宏。
斯人不可作，
彼夫竟凭陵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_897','感兴六首','顾清','明','椿寿期万岁，
龟龄亦千秋。
伤哉蜉蝣虫，
朝生夕不留。
君子与众人，
其道亦相侔。
计日不计年，
吾生将安投。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_898','感兴六首','顾清','明','不寐起中夜，
钩帘坐前楹。
傍见松桂影，
仰看江月生。
银河正无翳，
万里亘天横。
晶光动左右，
四闼晃虚明。
中怀正如此，
安得谢尘缨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_899','悦清为卢永清赋','顾清','明','岂无离群意，
翛然野鹤姿。
好山时拄颊，
幽涧或忘饥。
心赏丹青会，
神融翰墨知。
年来渐成癖，
无计得中医。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_900','古松','顾清','明','年来耆旧多零落，
如此长松见亦稀。
劲直不随冰雪困，
馨香宜得凤鸾依。
流脂化魄皆堪斸，
坠子成林又合围。
好在主人封殖厚，
清游留待子房归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_901','玉扇坠歌','顾清','明','天星夜坠乌玉渠，
灵光化作双鲤鱼。
目光夹日摇明珠，
昆冈八月秋气孤。
万夫入水群龙逋，
玄鬐一跃升天衢。
金索贯颐来献俘，
清风先生坐冰壶。
掀髯一笑留坐隅，
被以组绶恩礼殊。
金闺窈窕连黄枢，
尔我相倚出入俱。
自从倭风入中区，
飘然弃予瓦砾如。
时移世变日下趋，
何意更逢君子徒。
亦知所好非所须，
意气相感终不渝。
河东昔感中厩驹，
我歌双鱼双涕濡。
古人中人今岂无，
时哉不遇索莫俛首栖寒庐。',NULL,'','{"preface": "古者中国男女通用团扇团扇之制不便于怀藏故以组贯物于其柄遇执事则以为重而悬之带间谓之扇坠好事者或刻玉石为人物虫鱼之形而因以为玩及摺扇行此制遂废虽时或流落人间而用之者鲜矣予尝谓天下之变相寻于无穷而大率每变日趋于巧此亦其一也怡柑陆先生尝畜一墨玉双鱼扇坠系之摺扇出以索题当弁髦废弃之馀而独加赏爱其诸有所感乎因为作短歌以贻之于以见一物之废兴可以占世道之变而世之不谐于俗者又自别有赏音也", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_902','题梅花仙子图盛子昭画','顾清','明','烟林乌啼天未霜，
落月漏云金镜光。
美人独宿九华殿，
天风吹动金琅珰。
瑶阶露重侵罗袜，
冻合梅梢不成雪。
翩然飞下西湖头，
独傍寒香倚愁绝。
寒香郁郁愁冲冲，
冰魂荡漾迷西东。
星眸欲流滴秋水，
霓裳不动萦天风。
天风飒飒鸣璚玖，
欲去踟蹰更回首。
武塘仙人五彩毫，
偷眼方朔窥金桃。
凌晨写出一时景，
清寒入面风萧骚。
苍苔粼粼白石净，
空青暗滴阴崖冷。
石畔丛篁低拂云，
云外疏桐落金井。
翠禽一声河汉横，
辽天回首思冥冥。
云楼雾阁渺何许，
冷蕊疏枝空翠屏。
美人只今游太清，
武塘遗迹亦晨星。
怅望龙城梦中路，
寒绡惨淡来精灵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_903','满江红 乙巳元宵','顾清','明','云月澄鲜，
重城夜启。
满目繁华，
正江南春早，
红灯初试。
帘影千门摇粉黛，
香尘十里随罗绮。
论今宵何止刻千金，
堪游戏。
欢未已，
愁还继。
暗想今年，
遥怜往岁。
四时相代如流水。
上林春色三千里。
望鳌山凤辇是何年，
心摇曳。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_904','送高进之入上海学','顾清','明','企也来时犹稚年，
双髫初合未胜冠。
三冬自解攻文史，
五色今看振羽翰。
人欲别时情自恶，
学粗通处事方难。
重来定有惊人句，
不作寻常子弟看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_905','与曹宗魏高进之酌别','顾清','明','小石桥西旧草堂，
故人停驾速壶觞。
相从未觉当时乐，
已别方知此会良。
泼眼生红榴万点，
染衣浓绿柳千行。
旧时游处今为客，
怪得尊前语话长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_906','戊申春雨书寓所壁','顾清','明','去年秋旱深忧稼，
今岁春霖复损苗。
圣主不应天有谴，
清时宁许物为妖。
浸淫便恐鱼生釜，
漂泊谁将蚁渡桥。
江上舍前泥一尺，
掩书终夕听飘萧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_907','题张性夫小景四绝句','顾清','明','寂寂空山里，
春和草自芳。
隔溪人不见，
髣髴唤刘郎。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_908','题张性夫小景四绝句','顾清','明','水木阴森处，
茅堂四五间。
主人容直造，
携手看青山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_909','题张性夫小景四绝句','顾清','明','秋气著林麓，
萧条门户閒。
儿童拾松子，
日暮不知还。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_910','题张性夫小景四绝句','顾清','明','积雪断山路，
柴扉昼不开。
明朝稍晴霁，
先看屋东梅。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_911','种桂花','顾清','明','桂花分种出蟾宫，
柯叶虽异根荄同。
移来植向万仞峰，
天高地阔风露浓。
柯如碧琅玕，
织网罥出波涛寒。
叶如蓝田玉，
金刀刻成光煜煜。
吴刚有斧不敢侵，
买臣睥睨停讴吟。
月来清影亦萧瑟，
雨后绿叶常阴森。
我昔游广寒，
面受嫦娥诀。
世间兰麝竟纷纷，
天香自与凡花别。
便须和本移，
不必凌风折。
眼明见此秋风前，
已觉身在青云边。
还将两袖黄金粟，
散作奇香遍九天。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_912','纪蝉','顾清','明','青林的皪珠月明，
有蜩夜栖安不惊。
吸风饮露高且清，
忽焉有物来相仍。
扼吭拊背施五兵，
失声长号死复生。
命已绝兮犹力争，
我方抚卷临前楹。
闻之恻然起再行，
脩翎广颡金簧声。
须臾已复不得矜，
弱肉强食神所憎。
六王已毕秦亦倾，
临危欲援力不能，
岂独此蜩伤我情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_913','题宋起周扇','顾清','明','马头花雾扑春衣，
马尾青山步步随。
归去奚童莫催促，
先生得意正吟诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_914','阮庄为张信夫题','顾清','明','张郎别墅阮郎琴，
千载风流此会心。
认得湖山佳绝处，
绿杨窣地草堂深。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_915','过吴应文墓','顾清','明','弱龄随伴走红尘，
青眼相看独有君。
俯仰十年嗟逝水，
凄凉今日拜孤坟。
英雄有恨文章在，
忠信无凭夭寿分。
下马不堪重上马，
夕阳回首乱浮云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_916','己酉西行','顾清','明','出门别亲友，
长揖官道傍。
送者或低回，
行者何慨慷。
功名来趣人，
安得恋旧乡。
千金装湛卢，
万斛驾艅艎。
扬帆出三泖，
凌空度天潢。
挥刃斩蛟鼍，
回首招凤凰。
浮云东南来，
矫若游龙翔。
前飞若先驱，
遥遥西北行。
西北帝王居，
楼阙天中央。
年华际太平，
贤俊争趋跄。
一行策奇勋，
六辔驰康庄。
致君尧舜上，
载歌卿云章。
夙志自耿耿，
况当膂力刚。
雨过碧天净，
月明仙桂香。
豪饮尽百瓠，
长歌激清商。
去去君莫疑，
船头起虹光。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_917','梅竹月横幅','顾清','明','罗浮仙子跨青鸾，
午夜凌风觐广寒。
十二楼中都不寐，
大家齐凭玉阑看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_918','题扇面二绝句','顾清','明','绿树荫重滩，
平畴绕故山。
一犁春雨足，
万事不相关。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_919','题扇面二绝句','顾清','明','敲火然青竹，
磨刀割素鳞。
江湖真乐事，
输与洞庭人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_920','泗泾晓发','顾清','明','梦醒沧江月上初，
依稀听得唱吴歈。
推篷欲认停舟处，
已过前村十里馀。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_921','泊七宝镇','顾清','明','春来三月未登山，
此夜偏舟暂当閒。
怪底剑光藏不得，
舟人齐指斗牛间。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_922','庚戌初度','顾清','明','三十年前此日中，
满堂犀玉动春风。
桑弧有事羞长剑，
花甲无情恨转篷。
白日啸歌天地老，
青衫拜舞岁时同。
云山向晚催诗句，
目断天涯没去鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_923','春日杂书','顾清','明','双翼锦䙰褷，
花间任尔栖。
春来自多雨，
日暮不烦啼。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_924','春日杂书','顾清','明','日日花枝上，
新声变转娇。
何如逐鸣凤，
天上协箫韶。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_925','春日杂书','顾清','明','清晨戒童子，
竹户不须开。
昨夜东风恶，
苍苔有落梅。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_926','春日杂书','顾清','明','庭树谁教种，
无端恼客情。
昨宵窗外雨，
一半是渠声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_927','春日杂书','顾清','明','无事盆池畔，
吹萍看藕秧。
金鱼前岁放，
长得许来长。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_928','春日杂书','顾清','明','种花种长春，
君子有深意。
愿得堂上人，
红颜亦如是。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_929','春日杂书','顾清','明','凡花皆可爱，
萱草更忘忧。
未必真能尔，
聊将慰远游。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_930','王相之画石蝴蝶','顾清','明','处士梦中幽意，
美人衣上春风。
日午小轩人静，
阑干伫立从容。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_931','乐归为张椿庭赋','顾清','明','东皇运玄化，
百物竞华滋。
金商一司令，
黄叶满庭墀。
大块陶我形，
有合须有离。
古来贤达人，
此事那能违。
桓子治石椁，
三年费鑴追。
牛山感夕阳，
哀伤涕沾衣。
拳拳惜馀日，
欲作无穷规。
竟同草木腐，
千秋有馀悲。
贤哉椿庭翁，
洞烛今古非。
自言八十载，
不蹈危险机。
修身慎吾行，
大化从迁移。
幸此手足完，
庶不惭恩私。
生乎颓然顺，
死当浩然归。
陶潜拟挽歌，
生与亲旧辞。
司空游圹中，
酣饮仍赋诗。
二子信可人，
吾今其庶几。
酌酒自为奠，
告终自为词。
琅琅数百言，
药石兼蓍龟。
春风动歌吹，
宾从相追随。
山丘及华屋，
一视了不疑。
旷然世外游，
岂为形迹羁。
人生有此身，
所贵能不亏。
全归见其亲，
此乐知者稀。
尚怀子舆氏，
易箦开衾时。
往者信自贤，
来日方未涯。
愿翁劭厥德，
优游过期颐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_932','寄张拱辰','顾清','明','纳纳乾坤一草庐，
年来踪迹半樵渔。
龙纹渐涩床头剑，
鸿宝虚传枕内书。
霜后菊花香未减，
月中杨柳叶全疏。
飞书欲共天公语，
矫首青鸾隔太虚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_933','秋雨三首','顾清','明','江头雨深泥没膝，
闭门十日气欲塞。
黄茅断岸景色异，
正昼狐狸啸丛棘。
骑牛小儿誇惯熟，
疾走鸣鞭叩牛角。
幽人拄颊楼上坐，
欲拔青蛇抉云破。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_934','秋雨三首','顾清','明','男儿不学资身策，
有家不居远为客。
年过三十尚尘土，
屡揖庸儿愧腰膝。
堂堂白日閒里过，
可怜少年难再得。
呜呼此道亦未丧，
且复临风默惆怅。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_935','秋雨三首','顾清','明','日暮北风捲地来，
柴扉无人惊自开。
黄沙飘扬击人面，
起看天色如煤炱。
此时高堂坐白首，
弱妻供具正奔走。
主人酌酒殷勤劝，
不知客心随风乱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_936','题柳文裔扇','顾清','明','峥嵘碧琅玕，
上有栖凤枝。
凤凰飞不还，
山鸟空愁思。
春风开野棠，
绿叶含华滋。
岂无好声音，
缄口芳菲时。
谅无同心人，
欲语先成悲。
佳人惜芳年，
壮夫怀远期。
宁能阘两翅，
扑簌蒿下肥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_937','庚戌岁暮在子南馆梦二人传呼入大门数折而东予问此何处曰内阁也方思所以应对者忽闻百舌鸣而寤以诗记','顾清','明','贾董才名愧不胜，
皋夔事业我何情。
春风一刻邯郸路，
欹枕窗前百舌声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_938','辛亥感兴六首','顾清','明','六籍无孔孟，
诸子竞为书。
班马雄两汉，
韩柳后驰驱。
斯文虽未丧，
元气久已殊。
云胡后来者，
每变日下趋。
靡然事华藻，
琐甚雕虫鱼。
杳眇乱人耳，
黄钟委路衢。
时无欧阳子，
谁为扫其芜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_939','辛亥感兴六首','顾清','明','秦皇肆吞噬，
王白亦雄哉。
汉祖仗黄钺，
韩彭后先来。
仁暴虽异趋，
戡定各奇才。
悠悠千载下，
文胜武略颓。
貔貅百万辈，
孰是长城材。
虎卧不脱爪，
天行不废雷。
干羽格有苗，
兹运久未回。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_940','辛亥感兴六首','顾清','明','大运日颓下，
皇风返无期。
区区二三子，
乘时各扬眉。
声名动京阙，
举世钦所为。
吾观古人作，
举措不如兹。
悠悠叹升沉，
我独伤此时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_941','辛亥感兴六首','顾清','明','汉王仗三尺，
陆贾陈诗书。
齐客工弹瑟，
其王乃好竽。
为业非不精，
凿枘将焉如。
入水须操舟，
陆行须驾车。
君看屠龙手，
终年不食鱼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_942','辛亥感兴六首','顾清','明','仲淹归乡闾，
荣光照江东。
散帛分族人，
府藏一时空。
明年买义庄，
倾橐无吝容。
向来西山下，
平田正春农。
老稚各欣欣，
乡里自成风。
仰止慕芳躅，
咄嗟吾道穷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_943','辛亥感兴六首','顾清','明','急湍无漫波，
高冈多烈风。
君子抱奇节，
安能与时同。
譬彼松柏姿，
岂杂萧艾丛。
水浊不污月，
道丧身乃穷。
谁云唐虞远，
大运不再逢。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_944','梦入大第若官府有冠帔如命妇者肃容出果实为礼皆大如瓜将别赠以砚其言意之委曲不能详也记之以诗','顾清','明','海霞流光五色烂，
瑶花风吹香不断。
曲廊转入迷近远，
朱帘素壁光凌乱。
青衣传言凤凰啭，
云鬟十二梳未遍。
金龙水寒粟生钏，
银屏窈窕深不见。
朱扉哑然开半扇，
屋梁初日晃如练。
当轩揖我使我先，
神清度远不敢眄。
遗我五花文玉砚，
雕盘异果珠琲粲，
入手光辉不能辨。
鸣鞘一声来天上，
回身踏破梅花帐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_945','题吴子南梅花扇','顾清','明','一枝清绝傍瑶池，
消息须从雪里窥。
待得玲珑开满树，
狂蜂浪蝶已能知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_946','筠屋为徐大章季父廷美赋','顾清','明','徐君爱竹如爱玉，
种竹成林密如束。
林间结屋三四楹，
自说此生心事足。
阑干一径曲复曲，
落翠飞青暗人目。
我疑月明深夜中，
定有青鸾屋头宿。
青鸾飞去久不还，
满林翠羽秋阑珊。
时时一羽落书幌，
清气逼人毛骨寒。
前年识徐君，
倾盖即知己。
坐我筠屋中，
焚香拂素几。
弹琴瀹茗终日留，
知我爱君清莫比。
云萍一散雨经秋，
春风想见林塘幽。
晴窗展卷对图画，
使我东望心悠悠。
山林诗酒自真味，
江湖风波多隐忧。
洛阳红紫易消歇，
冰雪此君宜共游。
呼王猷，
招蒋诩，
便合屋中连日住。
明年骑鹤上扬州，
碧云回首知何处。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_947','花见羞后唐明宗淑妃王氏也予读五代史感其濒死为子乞命数语故为赋之','顾清','明','花见羞，
问汝何时生，
不得见尔面，
徒闻誇尔名。
尔名至今犹在人，
尔貌当时知绝伦。
花见羞，
双蛾绿，
出侯门，
入金屋。
君王本代来，
不识中州曲。
风尘一朝起，
零落随马足。
随马足，
事已非，
果然摧眉伏沙泥。
游魂茫茫绕青冢，
罗衣血染何当归。
花见羞，
入黄泉，
生时花应妒，
死后花反怜。
花谢枝头子还结，
妾死心事谁当传。
君王墓草埋寒烟，
春风麦饭洒谁边。
花见羞，
恨千年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_948','赋得碧甃寒根寿胡友松','顾清','明','曲廊阴阴清昼閒，
砌台乱匝苔花斑。
苍龙何年蜕寒骨，
化为古松根屈蟠。
百折不能去，
回戈折戟相撑住。
突然奋起石为裂，
散作孙枝不知数。
坚刚不容蝼蚁穴，
正直默有神灵护。
主人自是华阳仙，
双瞳碧色耳垂肩。
平生丘壑有深癖，
爱此松根时醉眠。
薰风四月日正长，
松阴满庭天气凉。
我来寿君劝君酒，
摩挲铁石龙鳞香。
松兮岁久根益深，
流膏渗乳日侵浔。
更千年后重相寻，
为君斸取根下苓。
采花酿酒共君斟，
飘然轻举紫山岑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_949','夜泊凤凰山闻鸟啼有感','顾清','明','吴蚕三眠欲上山，
吴禽夜啼吻欲乾。
啼言摘山须看火，
天欲明时啼更苦。
伤弓伤虎人物同，
此鸟前身是蚕女。
青楼美人红锦帷，
歌舞归来月已低。
银釭斜明照春睡，
问著摘山浑不知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_950','节庵','顾清','明','君不见徂徕松，
四时不改叶。
又不见淇园竹，
青青傲霜雪。
借问二子何能然，
信是平生有奇节。
男儿意气干云霓，
草庐抱膝龙蟠泥。
庙廊不改岩穴操，
事在他时人未知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_951','同以祥赴试过张性夫宿','顾清','明','水底鸡鸣事有无，
琉璃千顷浸浮图。
眼中便觉尘嚣尽，
他日何烦去五湖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_952','同以祥赴试过张性夫宿','顾清','明','落日放舟三泖西，
红霞碧浪树参差。
辋川风景还堪画，
唤取王维共赋诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_953','同以祥赴试过张性夫宿','顾清','明','梦破沧洲明月低，
水村依约有鸣鸡。
江神借我天风便，
墙柳枝枝尽向西。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_954','枫桥望虎丘','顾清','明','阖闾葬后三千岁，
霸气销沈虎亦亡。
留得当时旧园寝，
重重楼阁祀空王。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_955','为阮大经题画二首','顾清','明','万里龙沙隔五湖，
朔风吹雪点黄芦。
题诗为问沙头雁，
来日天骄款塞无。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_956','为阮大经题画二首','顾清','明','单于羊马汉臣衣，
泪洒西风日暮时。
千岁子卿终不死，
白头知为李陵悲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_957','试后待榜题桂花期顾时亨次舜和韵','顾清','明','花发年年自有时，
往年空恨得花迟。
长安归路天香满，
唤起黄筌写折枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_958','试后待榜题桂花期顾时亨次舜和韵','顾清','明','忆从年少看花谱，
数到红梅已厌迟。
入手天香笑今日，
秋风己过第三枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_959','为任芸轩题画兼以识别','顾清','明','先生家住南村头，
草堂占绝林塘幽。
阴森竹树交户牖，
屏居终岁忘春秋。
家藏旧书三万轴，
子孙百世犹堪读。
渔乡松乡及薇庵，
后先声价遥相属。
先生读书不为名，
春秋四十犹閒身。
弹琴赋诗足真趣，
壶矢终日留佳宾。
晴窗时临硬黄帖，
铁画银钩照箱箧。
广平老宋何足誇，
高意直与钟王接。
新编古制收不遗，
珊瑚宝树琅玕枝。
人言一字不充饱，
先生把玩恒忘饥。
鲰生忝是龙门客，
十载过从如一日。
天风吹人不得留，
只尺遂成千里隔。
离筵示我古画图，
画景彷佛南村居。
青山九点遥相映，
浅水平桥接芳径。
桥上人来知为谁，
安丘横云远莫定。
山林朝市不可偕，
临图使我心悠哉。
便须立效报天子，
还此同歌归去来。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_960','河间道中遇雪次何汝诚韵','顾清','明','冒雪登车倚酒酣，
日高犹自怯风严。
不须更问春消息，
已有天花压帽檐。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_961','陆孝子刲股辞','顾清','明','儿有身兮母之遗。
母疾之殆兮儿生何为。
身死母可代兮儿甘如饴。
残吾身兮寸肌。
免吾亲兮阽危。
孝哉陆生兮人子之仪。
吁嗟生兮当此时。
目见母兮身不为儿。
儿肌断兮母不知。
母命以续兮肌复滋。
嗟生之孝兮于古稀。
彼鄠之对兮理固宜。
情迫于中兮拟议安施。
仁有杀身而成兮身今在兹。
毁以易亲死兮又何惜，
夫此而嗟生之孝兮今谁继之。
持以奉吾君兮千秋万岁其无亏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_962','朱孺人哀辞','顾清','明','有美人兮山之中，
潜玄室兮翳贞松。
明镜掩兮虚夜月，
尘机断兮悲秋风。
思夫君兮往日，
谐琴瑟兮商宫。
怀德音兮意难穷，
怅泉台兮路几重。
良人恸兮惋切，
嗟别路兮音尘绝。
升空堂兮迟迟，
俨履綦兮成列。
惟勤劳兮未偿，
怀贞淑兮心菀结。
凉风动兮中闺，
纷綷縩兮罗帏。
知百年兮终尽，
羌触物兮增悲。
托文词兮发潜辉，
有知无知兮慰尔思。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_963','辰庆堂辞为赵叔鸣赋','顾清','明','翁生之岁兮龙丽天门。
龙周于天兮挟公子以凌云。
翁寿而燕兮捷书在阍。
翁举觞兮酹苍旻。
纷重拜兮罗众宾。
嘅人生兮不齐，
哀夭贱兮纷纷。
孰吉昌兮参会，
将厚德兮通神。
淮之南兮江之浒，
柳藏其门兮花映其庑。
翁作堂兮承帝之嘏，
翁燕而喜兮式歌且舞。
堂之构兮嶙峋，
巩厥址兮惟千春。
我作歌兮告尔后昆，
尔燕而聚兮无忘尔世勋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_964','东山辞','顾清','明','岁峥嵘兮白日驰，
朔风晨起兮霜雁飞。
长河千里兮愁欲断，
公何为兮忽言归。
挽公兮屡撝，
怅别公兮见何时。
渺渺兮寒江，
心眷眷兮欲安施。
惟人生兮悦贤，
孰憎爱兮予私。
抗予章兮天阍，
指肝膈兮敷陈。
忱恳切兮臣志，
沛汪濊兮天之恩。
忽东山兮回首，
渺白云兮孤村。
别来兮几时，
丛桂枝兮轮囷。
顾幅巾兮犹昔，
莞一笑兮忘言。
公将行兮裴𧙪，
俨东路兮骖騑。
忽回瞻兮天阙，
思承恩兮赤墀。
惟人生兮不常，
嗟终始兮多违。
不竟兮公施，
以张兮世维。
熊蹯兮鲂鲤，
审吾择兮奚疑。
荆之山兮湘之江，
我思公兮道阻且长。
总羸马兮东路，
忽西崦兮斜阳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_965','兰谷辞为黄时雍尊人赋','顾清','明','兰之生兮于彼空谷，
抱幽贞兮不群以独。
白石兮清泉，
纷紫茎兮冒寒。
渌兰之香兮扬扬，
汎光风兮朝阳。
谷无人兮自芳，
谷有人兮吾与子兮徜徉。
谷中之人兮清且真，
不可见兮徒名闻。
仰丹崖兮千仞，
思委佩兮江滨。
折芳兮谁赠，
羌云路兮愁人。
抚瑶琴兮叹息，
长寄情兮斯文。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_966','石淙辞','顾清','明','山之石兮孱颜，
飞淙交兮石之间。
龙跃兮虎斗，
砰雷击兮云翻。
寻源兮何处，
望极浦兮扬澜。
碧之鸡兮金之马，
点苍纷兮高下。
众壑兮争流，
指沧溟兮一泻。
舟万斛兮鸿毛，
群龙乘之兮以变化。
繄山川之伟绝兮，
宜夫子之挺生。
起一邦而天下兮，
亦足称其神灵。
京江既已改筑兮，
犹眷眷乎兹土。
颍峨嵋吴蜀山兮孰云今之非古。
石弗泐兮淙弗枯，
散为江海蒸为霖雨兮润八区。
吾诚不测夫子之妙用兮，
固将等廊庙于江湖。
渺南云兮万里，
长寄兴兮桑弧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_967','乐间园为同年夏如山赋十二首','顾清','明','天之德兮曰仁，
山得之兮镇厚坤。
既雄秀兮又以尊，
抚众壑兮如儿孙。
千花兮万卉，
吾与尔兮长春。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_968','乐间园为同年夏如山赋十二首','顾清','明','群仙游兮大罗，
时憩息兮岩之阿。
玉柱兮金窗，
俯洞庭兮烟波。
忽中宵兮月上，
听泠泠兮空歌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_969','乐间园为同年夏如山赋十二首','顾清','明','漫吾出兮周星，
忽归来兮亭以成。
嗟平生兮万事，
亦何择兮何营。
偶欣然兮终日，
孰久近兮千龄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_970','乐间园为同年夏如山赋十二首','顾清','明','思美人兮不来，
步石径兮生青苔。
聊升高兮骋望，
揽桂枝兮徘徊。
晴天兮万里，
见一鹤兮飞回。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_971','乐间园为同年夏如山赋十二首','顾清','明','泉何为兮此流，
湛清泠兮岩之陬。
洗京洛兮缁尘，
玩濠梁兮浮鯈。
渺真源兮何处，
望龙山兮落日幽幽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_972','乐间园为同年夏如山赋十二首','顾清','明','路转兮山回，
望幽岩兮阻深隈。
忽凌空兮飞步，
振予策兮丹台。
愿镌崖兮有纪，
步灵踪兮天台。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_973','乐间园为同年夏如山赋十二首','顾清','明','结湘筠兮玲珑，
交桂枝兮隐隐丛丛。
玉叶兮金英，
来清芬兮远风。
将书香兮此类，
嗣云仍兮无穷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_974','乐间园为同年夏如山赋十二首','顾清','明','竹柏兮成林，
中一径兮静以深。
谢红紫兮春阳，
饱风霜兮重阴。
怀佳人兮怅望，
将千载兮同心。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_975','乐间园为同年夏如山赋十二首','顾清','明','山中人兮不归，
樵柯烂兮闾里全非。
嗟人生兮几何，
奄夕曛兮朝晖。
神仙兮戏予，
拂苍珉兮渺遐思。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_976','乐间园为同年夏如山赋十二首','顾清','明','圉圉兮洋洋，
忽吾止兮濠之梁。
绿藻兮青蘋，
与尔游兮两忘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_977','乐间园为同年夏如山赋十二首','顾清','明','室无尘兮更明，
晏独处兮憺以清。
左瞻兮右仰，
诸史兮群经。
聊逍遥兮永日，
孰宠利兮荣名。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_978','乐间园为同年夏如山赋十二首','顾清','明','隐吾屋兮山之东，
仰仁高兮一径潜通。
有芭蕉兮夏绿，
更芙蓉兮晚红。
忽夕阳兮云合，
倚阑干兮意万重。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_979','画水辞庚辰六月礼部南斋作','顾清','明','群山兮东倾，
百川兮与俱。
昆崙兮万里，
渺东极兮归墟。
龙门兮三峡，
屹峥嵘兮喷鞺鞳。
奠九服兮常宁，
疏万派兮终合。
展瑶签兮拂霜藤，
目窈窕兮耳泠泠。
江南兮春尽，
蘼芜绿兮枫青。
思美人兮何处，
抚朱弦兮空复情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_980','题画梅','顾清','明','四百峰头霜气横，
玉尊零落翠禽声。
寒绡三尺对虚牖，
髣髴松林残月明。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_981','题画梅','顾清','明','江南见梅只是梅，
燕山见画殊依依。
西垣夜半草堂梦，
青子绿阴雏燕飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_982','送使山东','顾清','明','春云拖影拂轺车，
南出都门候吏趋。
两岁青齐仍苦旱，
带将甘雨洗焦枯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_983','和听鹤亭联句韵送毛太史维之归省','顾清','明','夜闻东壁饯文星，
晓起西堂乍酒醒。
未许馀光分末坐，
空吟佳句入无形。
歌停渭柳仍翻调，
舞爱皋禽拟著经。
更与玉堂添故事，
未应寥落叹槐厅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_984','午日昭应宫送陈深渊得兽字','顾清','明','危弦激清湍，
奇香袅金兽。
佳辰良友集，
高宴启清昼。
维时值升平，
四郊息烽堠。
缙绅多暇日，
遨赏遗俗旧。
况兹金玉人，
声价儒林右。
十年期破的，
一矢尚虚彀。
于焉送将归，
不饮复何有。
薰风晚更起，
叠嶂远仍秀。
遐观穷八纮，
醉舞翻两袖。
区区蛮触争，
琐细安足究。
尚怀禹稷心，
未忍苍生瘦。
往者勿复云，
来日知未后。
三年家政成，
洗耳明光奏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_985','送同年周时敏归安陆','顾清','明','男儿意气淩四方，
结发万里期翱翔。
槐黄催赴观国光，
手携尺书朝帝王。
帝曰汝贤留我傍，
往视予宰铨才良。
红帘粉署夏日长，
峨冕吁咈谈虞唐。
白云飞来经太行，
翩然归思不可当。
帝恩旷荡真无疆，
汝暂释事归故乡。
都门朝日天气凉，
束装出祖驱骕骦。
关吏旧识趋路将，
举鞭挥手振紫缰。
眼中已见荆山苍，
男儿名成拜高堂。
人间此乐殊未央，
九重待补龙山章。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_986','送秦国声归省','顾清','明','天上秋光近，
人间乐事并。
华轩启澄霁，
高宴接恩荣。
鹤寿元无算，
鹏飞始发程。
云霄遂归志，
闾里溢欢声。
袅袅风生坐，
娟娟月傍楹。
酒来吴市美，
茶瀹惠泉清。
瓜果纷前馔，
诗篇罚后成。
有阶堪报国，
随寓足陶情。
绿竹宜镌字，
丹台早注名。
他年佐觞豆，
应及海波平。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_987','送朱良翊','顾清','明','翩然聚首忽言归，
立遣奚童趣赋诗。
千里畏途当赤日，
十分清兴寄乌丝。
贾生世共知才大，
李广人犹恨数奇。
悬榻故人专有待，
飞腾应不后明时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_988','送周兵马之金陵','顾清','明','将军宝剑双龙鳞，
锦衣红蹙绣麒麟。
甲第东华接诸贵，
楼船南国隘通津。
干戈万里风尘静，
两都冠盖如云盛。
朝出长干访原涉，
暮入乌衣过剧孟。
书生昔未试吴钩，
悲歌三入凤台游。
醉拔霜毫赠君别，
三山落日不胜愁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_989','送盛斯徵归娶','顾清','明','柳色衣裳玉色鞭，
看花归去又逢仙。
黑头事业须君做，
洞府星桥别是天。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_990','夜雨','顾清','明','蓟北雨连晓，
江南定若何。
还应碧窗里，
灯影暗银荷。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_991','秋夜叹','顾清','明','银河流光湿垂地，
高梧滴露浓如洗。
城头击柝城下杵，
幽人已卧中夜起。
东院西院无人声，
星下草间蛩对鸣。
一星起来对吴分，
恨不从之觅乡信。
诸君走马长安陌，
肯信中宵此中立。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_992','新秋即事','顾清','明','暮雨残暑尽，
官居清可挹。
疏栊捲秋幔，
流盼伫危级。
温凉四时异，
心会各有入。
鸦啼烟树寒，
露下银床湿。
抚景怀昔贤，
兹地几翔集。
新凉信可爱，
雨霰行且及。
愿言惜芳时，
功业期早立。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_993','拟中元谒陵','顾清','明','玉座秋风动紫宸，
寝园时祀敕亲臣。
云屯松梓衣冠集，
月照庭楹俎豆陈。
天地有灵钟王气，
山陵终古享精禋。
词臣欲献甘泉赋，
指日皇舆驾翠麟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_994','登第后寄所知','顾清','明','春风逐伴上金台，
便著青衫未得回。
夜听玉龙官烛冷，
晓趋丹凤御香来。
匡时未展江湖志，
饱食频惊岁月催。
翘首碧云南国路，
美人谁在读书堆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_995','送刘文瑞','顾清','明','青袍白马日纷纷，
何处秋光忽送君。
天地百年同逆旅，
风尘此地独离群。
时平宰相精求士，
朝暇将军总好文。
去去江湖莫淹久，
有人虚席仰多闻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_996','奉饯定庵张先生之南台','顾清','明','四历雄藩秉宪旄，
荐更三府肃铨曹。
文章旧是南金重，
风节遥淩北斗高。
舆论只今推宋璟，
空群他日想方皋。
两京均逸天心在，
莫向霜台梦午桥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_997','夜坐','顾清','明','仙都閟灵境，
假日休官程。
高斋坐来久，
夜景湛虚明。
起步视天宇，
旷然遗世缨。
素心适有会，
幽兴顿此生。
沧波望不极，
落月金盆倾。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_998','夜坐','顾清','明','遥遥天汉津，
耿耿横太清。
招摇运珠斗，
时节忽已更。
感此念昨日，
凄然思友生。
群聚不知乐，
已别始牵情。
人事与日长，
后期焉可凭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_999','明妃和汪抑之','顾清','明','汉朝翁主半家人，
临到王嫱国论新。
解道怀戎尚忠信，
庙堂谁谓少谋臣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1000','明妃和汪抑之','顾清','明','宣王六月驾戎车，
武帝旌旗万里赊。
独以一身宁四海，
明妃何恨泣琵琶。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1001','杨妃','顾清','明','汉家妃子度金微，
裂面西风损黛眉。
教得后来人解事，
只从金屋抚番儿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1002','题画送胡友松','顾清','明','画里看山惜别离，
松间立马醉题诗。
伏波老去心犹壮，
太白狂来酒不辞。
云日九重丹凤阙，
风烟千顷白鸥陂。
归舟正及鲈鱼信，
应对西风有所思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1003','记蝎','顾清','明','读书心二三，
耳闻窗蝎走。
捲纸濡馀膏，
火起蝎在牖。
抑首伏不行，
翘尾若有候。
人言蝎易得，
此意殊未究。
怀毒乃忘身，
祸起遂莫救。
柳州怜蝮蛇，
释械低予首。
因诗戒宵人，
阴贼恒反受。',NULL,'','{"preface": "虫之毒者南方之即且北方之蝎即且能飞见人辄疾走而蝎行甚缓闻人声反止不动故多为人得七月廿三夜闻窗间爬沙声火烛之踞而翘尾卓然可畏乃知其不动者盖将以有为也即且犹知畏人而蝎止以伺之其甚矣然卒以自毙悲夫故记之以为戒", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1004','海屋添筹','顾清','明','沧海尘飞是几秋，
北堂花甲数方周。
试寻孝子无穷意，
尽下仙人未了筹。
红日傍檐晴可爱，
绿萱当砌足忘忧。
只应尽醉长春酒，
同送飙轮过弱流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1005','秋夜读书','顾清','明','高秋净炎暑，
官居若蓬瀛。
落日人吏散，
琴书有馀清。
烛至童子去，
抚卷临前楹。
仰窥羲皇秘，
俯探周孔情。
下上千万年，
历历指掌明。
自从大道丧，
圣哲希复生。
幸此未坠地，
庶以开吾懵。
稍稍庭叶下，
凄凄草虫鸣。
初月上东垣，
露草光晶荧。
清景与心会，
宵眠竟无成。
微吟倚青琐，
天风起松声。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1006','初预丁祭','顾清','明','北阙初鸣佩，
东胶肃展仪。
感深思坏木，
喜极预承齍。
江汉神如在，
山龙服俨垂。
自今期秉德，
无愧骏奔时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1007','玉堂对月','顾清','明','万古此明月，
流看属吾人。
人生见月时，
欢寡愁日频。
眷兹玉堂署，
清切近帝宸。
金铺启澄霁，
光景何鲜新。
古人去日多，
后来浩无垠。
而我于其间，
渺然凝心神。
不有通夕玩，
奈彼风雪辰。
茫茫太无中，
置此冰玉轮。
荧光载灵魄，
终古如环循。
闻有丹桂树，
婆娑映天津。
复有乘鸾女，
炼药司大钧。
愿从乞刀圭，
驻此尘土身。
青冥无终极，
怅望徒逡巡。
人生会有役，
玩物丧乃真。
掩扉送馀辉，
朝车已辚辚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1008','送陈邦直赴西安','顾清','明','千古关中郡，
山川号上游。
俗馀周日化，
地重禹书州。
别驾聊伸骥，
长才类解牛。
词林有遗派，
嘉绩会先收。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1009','送何溥之西川','顾清','明','西望蜀川千万山，
美人莲幕暂栖鸾。
云连剑阁春前度，
天近青城雪后看。
今日筹边宜得士，
古来行道不论官。
务閒好课戎郎学，
拭目秋风振彩翰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1010','沂州谷生尝从张友山学能诗善医工画梅家有园亭之胜比自京师还同馆陈君德卿作云山别意诗以赠邀予同赋','顾清','明','亭亭空外云，
蔼蔼云中山。
云山苍茫自今古，
江湖游人时往还。
黄金台前杨柳枯，
奚奴青丝提玉壶。
挽君征骖酌君酒，
握手目送飞鸿孤。
花光三昧传者少，
山翁老去谁同调。
一命常怀拯溺心，
十全每奏回生效。
长安车马日逢迎，
五侯七贵皆知名。
拂衣东去不返顾，
何异黄鹄摩空征。
舞雩坛前春信早，
园亭尽说君家好。
肩舆何日径敲门，
坐咏云山藉芳草。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1011','次韵答张拱辰','顾清','明','张籍经年病卧家，
纷纷九陌自繁华。
春风为遣江南信，
拂杀龙泉旧剑花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1012','次韵答张拱辰','顾清','明','中朝文献几名家，
每见殷勤访国华。
尽有声名动京邑，
未应消瘦学梅花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1013','奉饯圭峰董先生之南京','顾清','明','秩宗分务简元僚，
学士声华重本朝。
辍讲暂违东殿直，
移家初听下江潮。
西风燕市柳条短，
春日金陵物色饶。
莫倚官閒疏献纳，
左垣踪迹未全遥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1014','东洋','顾清','明','东南百川会，
入海不复返。
茫洋天地间，
今古无潦旱。
吾观玄化初，
一气亦微婉。
刚柔相荡摩，
积润成浸灌。
天地且有穷，
海波宁无岸。
常思淩天行，
会应得奇观。
王生东海居，
兹兴知不浅。
迟予驾飙轮，
携尔出汗漫。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1015','同年胡镇之挽诗','顾清','明','天道由来远，
人生定可疑。
如君便长已，
造物竟何为。
旅殡僧房启，
科名墓石垂。
九原风雨夕，
肠断脊令诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1016','送薛平甫','顾清','明','岁暮行旅稀，
官河断舟楫。
朔风吹狐裘，
征旆向空揭。
念我同乡彦，
孤怀耿冰雪。
南宫既联镳，
北门亦并辙。
清词与妙句，
脱口人竞说。
方需丽泽资，
胡尔当远别。
男儿四方志，
岂不在京阙。
顾彼西山景，
幽衷日千结。
一行遂素心，
万里若踰闑。
因君感予怀，
揽辔剧中热。
行尘望欲尽，
归意更骚屑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1017','送吴南仲','顾清','明','去年放舟过垂虹，
霜露尽降湖波空。
三高祠下拂苍石，
长啸宇内生雄风。
此时闻君未相识，
指点烟芜问君宅。
今年君归我留此，
却望江南动颜色。
君才自是当世资，
暂蹶霜蹄何必疑。
名场声价蔼然在，
故园山水聊栖迟。
春洲二月芳杜长，
芦芽抽碧河豚上。
短楫轻舠不用帆，
北里南村恣来往。
东家郑郎交最投，
新年闻亦理归舟。
诗筒酒榼百里近，
慎勿流连负壮游。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1018','晚归即事','顾清','明','城头官柳绿交加，
日日斜阳集乳鸦。
湖海书生羸马背，
春来通算九移家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1019','卢布政挽诗','顾清','明','早折宫花上玉墀，
郎曹五转冠藩维。
西铨藻鉴冰霜在，
南国威名草木知。
洛社几年初入会，
昴精前夜忽骑箕。
薤歌不尽思贤意，
落日长江起碧漪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1020','甲寅正月七日迎驾','顾清','明','紫坛成礼当人日，
玉佩迎銮望合宫。
辇路暗尘清积雪，
御旗晴影动春风。
祥祯协应知天意，
对越勤劳仰圣躬。
湖海书生瞻盛典，
耻将文笔赋河东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1021','初预庆成燕敬赋','顾清','明','半生湖海梦钧天，
此日云霄奉御筵。
虞典孟郊神并享，
镐京春燕礼无前。
黄分内酝惊殊宠，
红戴宫花忆去年。
无限感恩图报意，
未论文赋美甘泉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1022','柯学士先生所种二柏树歌','顾清','明','君不见刘保斋柯竹岩，
一时名声齐斗南。
文鹓孔翠赤霄上，
遗迹世人争竦瞻。
玉堂之南双翠柏，
传是竹岩先生手所植。
我来抚玩不忍去，
树底犹疑有行迹。
忆初种来今几年，
高标已见摩云天。
雨淋日炙长苔藓，
虬须龙甲皆苍然。
斜阳独立双树阴，
寒天老气转萧森。
丈夫有作期百世，
此物岂异甘棠林。
我歌双柏篇，
继彼角弓吟。
古人已恨材难用，
何处悠悠语此心。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1023','送许启衷','顾清','明','榕阴垂绿荔支丹，
五月南州画里看。
忆别况逢新岁后，
赐归犹及未春残。
堂高海日明衣锦，
路入乡山信马鞍。
还忆西垣镫火夜，
重来不遣旧盟寒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1024','送许启衷又二绝句','顾清','明','一自看花入禁垣，
清秋憔悴卧春残。
金茎不是君王惜，
自忆家山荔子丹。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1025','送许启衷又二绝句','顾清','明','圣代仁深远俗安，
侧生无复上雕鞍。
閒居续得君谟谱，
聊为南风一寄看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1026','送周都尉告祀孝陵','顾清','明','明明我圣祖，
承天驭华夷。
赫怒定海宇，
忧勤固皇基。
典则遗子孙，
万世如一时。
恭惟衣冠藏，
郁郁镇地维。
云车与风马，
日夕恒来思。
神灵居帝傍，
监观靡有遗。
日闻寝园中，
风雨尝纷披。
松柏帝所念，
行列恐有欹。
玉帛命专使，
洁斋代亲祠。
周侯戚畹英，
寅清帝心知。
况此共欣戚，
宁为跋涉辞。
都亭三月初，
春光照轩帷。
祖席列群彦，
载咏皇华诗。
峨峨紫金山，
宫阙何崔嵬。
侍卫固有职，
汎扫宜如仪。
圣情切注想，
归矣无需迟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1027','石田野色','顾清','明','茅屋青林映短篱，
渺然西崦望东菑。
白羊不起麦平垄，
黄犊閒眠水满陂。
远树每于晨雾失，
短筇尤共晚晴宜。
南阳未为苍生起，
风雨还闻长紫芝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1028','毕府丞父母同寿','顾清','明','高槐荫庭风日清，
花罗剪春香雾轻。
金屏翠帷尊两楹，
门前车马来倾城。
美人一双弹玉筝，
双歌南飞献长生。
凤雏衔书仪帝廷，
紫鸾诏书天与荣。
瑶环涓秀瑜珥晶，
书香三世连科名。
膝前拜舞䌽衣明，
人间此乐岂易并。
愿吹济水添瑶觥，
灵椿不凋萱不零，
年年珠履花间迎。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1029','戏效荆公作四首','顾清','明','城东野意动，
名园滋华芳。
弱柳黄晼晚，
夭桃映新阳。
循原涉浅渚，
连步陟崇冈。
兴至陈尊俎，
凭高顾江乡。
生世间逸少，
怀归念王章。
东游昨夜梦，
川谷永相忘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1030','戏效荆公作四首','顾清','明','高柳骈密荫，
疏篁延清风。
留客广厦宽，
沈李冰壶空。
梁石介清池，
绿波缘芙蓉。
日转禽语乐，
幽林回短筇。
逍遥崇台上，
兴入江南峰。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1031','戏效荆公作四首','顾清','明','长林过朝雨，
高堂生微凉。
帘幕含霁景，
临轩送清觞。
遥岑参差碧，
远浦明夕阳。
渚宫遂寂寞，
登楼望川梁。
何当溯流辉，
汀洲采兰香。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1032','戏效荆公作四首','顾清','明','早寒信已严，
颇得羔裘重。
起开西楼钥，
坐愁长河冻。
阳和逊重阴，
飞雪积危栋。
红炉照邻壁，
蓝尾生怜送。
吴江万里天，
媚景春如梦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1033','东拙为舜和太史祖赋','顾清','明','君不见汉阴叟，
抱瓮终朝不濡亩。
又不见愚溪翁，
琼琚玉佩分天工。
拙人劳力泰宇定，
巧智终以灾其躬。
东城徐翁阅世久，
宁为汉阴不为柳。
鸤鸠无能鹊巢坐，
庄樗散木偏多寿。
才不用，
全其真，
功无成，
贻后昆。
颓然八十馀，
无怀葛天民。
古云大巧外若拙，
吁嗟翁乎岂其人。
我本拙者，
于时罕通，
为翁作歌，
仰翁高风。
丹崖青壁不可以力致，
幅巾杖履想见城之东。
天子方好古，
蒲车起申公。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1034','送人赴番昜丞','顾清','明','陈子饶阳去，
抡才可是宜。
能无愧职事，
应不计班资。
宦况湖头月，
行装马上诗。
前途犹未晚，
努力向明时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1035','望云','顾清','明','青天多白云，
游子嗟别亲。
白云飞扬随处见，
极目亲舍徒伤神。
徒伤神，
情何极，
一回仰天一沾臆。
春风绿酒金台前，
恨不随云堕亲侧。
云可望，
不可攀，
但愿亲寿如南山，
又如长江东注之波澜。
富贵有时来，
难驻惟朱颜，
亲年无恙百事閒。
劝云一卮，
祝云南飞。
向我高堂前，
荫我椿树萱花枝。
无使秋霜容易凋华滋，
游子西风江上归。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1036','送徐都阃归宜兴','顾清','明','五色春衫拂地垂，
东门高宴驻旌麾。
旧来仲郢人知少，
欲去玄成马上迟。
红叶巧当官路坠，
白云长傍禁垣移。
鲤庭桃李春阴在，
却愧杨生后赋诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1037','送王参政庆贺还河南','顾清','明','流电光中玉佩趋，
鸿胪当仗赞嵩呼。
瞻天旧识威颜近，
分陕新兼体貌殊。
北阙朝辞云拥陛，
东门秋饯士倾都。
雄藩尚有宣房虑，
何日玄圭协禹谟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1038','读书有感','顾清','明','良宵可虚掷，
明镫了残书。
开卷对古人，
已隔千载馀。
精神方尺间，
恍若倾盖初。
共惟德业光，
照耀流中区。
藐予嗣前绪，
十年事菑畬。
惜哉无良耜，
终亩多薪樗。
幸逢明圣朝，
挟册随冠裾。
纷纷杂纂组，
琐琐雕虫鱼。
白日无留光，
西飞若飙车。
凉风振高树，
落叶满庭除。
念此不能寐，
摄衣起踌蹰。
盛年无再至，
驽驾不可虚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1039','送屠都宪元勋巡抚蓟州等处兼督边关','顾清','明','玉节朝辞出凤楼，
朱旗遥映塞垣秋。
宁边旧属西台重，
当宁今无北顾忧。
铃阁春风閒卫戟，
海山晴日动轻裘。
极知根本须才杰，
未为还朝是黑头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1040','周世贞父六十','顾清','明','海山金桃几年熟，
天台灵源流水速。
仙翁六十自世间，
老圃西风终日閒。
凤雏衔书赤霄上，
五彩朝阳烂相向。
云中有路不可归，
春酒盈尊独惆怅。
瓢笙四管寸脍鱼，
咀羊城下梅花初。
锦衣他日拜家庆，
人看相如驷马车。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1041','琅琊书屋为石秀才赋','顾清','明','醉翁去来三百年，
琅琊山水仍依然。
林芳谷秀谁管领，
石家书屋僧庐偏。
主人读书少谐俗，
文章往往追古贤。
山中风月足吟弄，
世上富贵从推迁。
连连冈阜拥檐牖，
郁郁竹树留风烟。
晴猿昼啼白云下，
独鹤夜叫长松巅。
冥搜得意或拊几，
感慨双涕时沦涟。
悠悠宁逐蠹鱼尽，
兀兀已觉筌蹄捐。
君不见玉屏峰南瑁湖上，
我家旧屋临清涓。
绿萝摇春拂窗户，
纸屏竹几清且便。
十年栖迟不谓好，
一日怅望空云天。
终南少室非我有，
东华尘土劳鞍鞯。
劝君及时须行乐，
豪杰未有终林泉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1042','文武传芳为李惟中郎中父寿','顾清','明','公家奕世龙韬学，
已会风云取高爵。
百年海宇烟尘清，
又向雷门见头角。
峨嵋剑阁横金天，
西连草堂锦水边。
雄豪秀润各有得，
公独于此当其全。
西风使节相如归，
公呼诸孙候江湄。
遂开高堂称寿卮，
锦衣前拜绣帽随。
熊罴鹓鹭各有姿，
邦人来观啧相语。
谁似公家文更武，
文谟庙堂武禦侮。
天佑公家后方钜，
万岁千秋奉明主。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1043','送蒋国器','顾清','明','西风一夕起平原，
到处羁人忆故园。
失路未须怜季子，
作书方拟贺参元。
功名入手无多事，
尘土留人岂足论。
记取他年说今日，
冷云疏雨出都门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1044','送汤同知督运','顾清','明','兖河秋水不容舠，
沽口回风积万艘。
五服上供推袖领，
九重深眷想贤劳。
君恩左右惭虚被，
民力东南亦孔骚。
眼底白茅连瓠子，
夕阳离思满亭皋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1045','水仙扇面','顾清','明','银杯侧西风，
罗襦不禁冷。
空江月落时，
想象孤鸿影。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1046','送曾执初知嘉定州','顾清','明','都亭杨柳秋来短，
独采黄花映别觞。
五马双旌万馀里，
西风随处挹清香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1047','九日招德卿抑之','顾清','明','小酌无劳折简催，
自分花饵饤玫瑰。
只应免得渊明笑，
两岁重阳不举杯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1048','题戴司寇所藏张翚小景四幅','顾清','明','岱岳东南日观峰，
鸡鸣遥见日轮红。
仙家应说人间世，
银箭金壶漏未终。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1049','题戴司寇所藏张翚小景四幅','顾清','明','一色沧波浩渺间，
人言此外有三山。
莫欺只尺生绡里，
多少楼船去不还。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1050','题戴司寇所藏张翚小景四幅','顾清','明','老翚笔意师观远，
怪石长松气凛然。
四十年来真迹乱，
夕阳红树满山川。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1051','题戴司寇所藏张翚小景四幅','顾清','明','斗帐无风铁砚冰，
梅花未要雪天晴。
坐来尚有关心处，
时复空山折竹声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1052','文华进讲','顾清','明','鹄立朱衣正殿东，
炉烟飘动讲帷风。
百年礼乐逢昌运，
乙夜勤劳仰圣躬。
毫末岂能裨海岳，
精诚直欲感苍穹。
邠风无逸前王训，
稽首钧天意万重。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1053','河浑浑','顾清','明','河浑浑，
发昆崙，
奔驰万里出龙门。
出龙门，
齧金堤，
汎瓠子。
鱼鼋蛟鼍，
乘时奋起。
城郭坏，
丘陵颓，
汉帝沉，
玉马劳歌入云哀。
河浑浑，
洵神灵。
我皇龙飞初，
泥沙潜伏波镜澄。
皇钦事，
禋孔精。
胡为乎一日骋雄悍，
违天经。
奔腾荡潏，
岸坼堤倾。
使行者不得遂，
居者不得宁，
园庐漂溺鱼鳖横。
河浑浑，
下民咨。
神禹上天去，
贾尉来何时。
三年青兖民亦疲，
土牛楗石将恐非。
河浑浑，
侧身南望劳我思。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1054','梦中得四句如咏讲筵事者','顾清','明','翠幕光中黼坐开，
觚棱初日照春台。
缃函未启中人捧，
玉辇才临正殿回。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1055','樗老','顾清','明','君不见麝憎脐鸡恶尾，
又不见豹患皮象患齿。
苏张戮辱韩白菹，
全神乃在支离子。
东吴杨翁太古民，
妙诀早受南华君。
尽将智巧付时辈，
甘与樗栎同轮囷。
阖闾城西云水阔，
南北舟航日阗噎。
春花秋月闭门看，
八十年来几兴灭。
泥龟曳尾宁诧神，
沟断庙尊俱失真。
万牛回首歌孔柏，
少陵岂是知心人。
樗日老，
翁日健，
尘海桑田几回变。
人道孙枝却不如，
前年选入明光殿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1056','秦府纪善林介庵挽诗','顾清','明','五十飘然便挂冠，
向来城府掉头看。
高踪自与鸿飞杳，
短世频惊蝶梦残。
絮酒何年奠冥漠，
囊金他日记汍澜。
哀歌不尽思贤意，
尘海风波正渺漫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1057','送乡僧','顾清','明','乾坤无物碍行踪，
又送孤云入九峰。
林鹤暗惊空外锡，
海鲸先报佛前钟。
金衣拂晓承新露，
丈室凝尘记旧封。
应识西来祖师意，
逢人莫浪演三宗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1058','冬至朝贺','顾清','明','璿管灰飞宿霭消，
紫宸班动御香飘。
貔貅列仗开弓剑，
芝羽充廷杂佩貂。
长日光中瞻黼扆，
卿云影里听箫韶。
愿言圣德同阳长，
永从夔龙集治朝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1059','乙夘正月抑之以疾告归盖有为也作春雪歌送之','顾清','明','昨夜西堂春梦好，
已向池边觅芳草。
雪花日暮忽满城，
无乃天欲留君行。
惊飞乱舞不自制，
黄雪冥冥直侵地。
公子城东醉未归，
将军塞上愁无寐。
此时念君当别离，
官河千里冰未澌。
仆夫宵装待明发，
车轮凌兢马蹄滑。
旗亭呼酒强劝君，
明朝望君越与秦。
丈夫结束自有地，
征途药饵宜相亲。
玉河东堤旧行路，
冒雪送君从此去。
无限幽怀不易论，
回首西垣万银树。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1060','上苑闻鸠','顾清','明','春波溶溶宫柳低，
春云漠漠斑鸠啼。
柳阴渐深看不见，
时复数声金殿西。
青绳辇路无尘土，
鸣鞘不来日亭午。
高树低枝相应呼，
似惜田农望时雨。
农人望雨心如渴，
鸠啼日暮声不歇。
乾明门前春气深，
太液池头烟水阔。
烟水微茫连别殿，
忽去还啼画楼畔。
柳密花深不再闻，
时复宫壶坠银箭。
忆昨至尊亲劝农，
青旂黛耜临春风。
一声此日彻天耳，
碧霄几见回重瞳。
八年海宇歌太平，
春田处处斑鸠声。
绿秧刺波桑椹青，
却忆江南村落行。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1061','春雨','顾清','明','麦苗侵垄黍含滋，
微雨东来似有期。
凉拂画楼分迥野，
润兼红杏点清池。
丰穰竟惬三农望，
造化宁于一物私。
想得宸游同众喜，
彩帘高捲看飞丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1062','内阁赏芍药次韵二首','顾清','明','层城紫阁对阴阴，
天与名花著意深。
素瓣巧攒怜玉带，
醉颜微晕侧檀心。
一时胜赏谁当继，
前辈流芳故许寻。
拟和阳春歌浩态，
斜阳步屧几沉吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1063','内阁赏芍药次韵二首','顾清','明','紫泥封后玉堂归，
阁吏钩帘午漏稀。
花事直于今烂漫，
赏心犹自惜芳菲。
官厨次第传宫酝，
城日参差散锦帷。
不似维扬谶金紫，
年来春色满黄扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1064','午日即事','顾清','明','节物相催似转蓬，
御筵仍见䌽丝红。
君王未押群臣燕，
先酌蒲觞寿两宫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1065','桐隐为龚九成赋','顾清','明','凤凰起丹穴，
不息凡木枝。
飞飞度中州，
正值轩虞时。
六律既以谐，
九德被弦徽。
回瞻紫山岑，
青桐映朝曦。
醴泉漱其根，
祥飙扇萎蕤。
一敛赤霄羽，
永日共娱嬉。
由来千仞心，
岂有稻粱思。
黄鹄淩紫烟，
一往无还期。
云鹏六月息，
荒忽经天池。
古来高尚徒，
不必皆颍箕。
终南隔人世，
达士供一嗤。
方寸有万里，
何须裂冠緌。
我歌桐隐篇，
想象卷阿诗。
君王富车马，
迟尔看来仪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1066','题扇送同年奚从之使海南','顾清','明','仙人乘槎南海去，
祖席燕市已分冰。
把赠金陵半轮月，
为君随处扫炎蒸。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1067','有草名雁来红者茎叶如鸡冠而无花得霜红甚俗呼老少年或画以贻樗翁良德南夫因赋以为寿予亦继作','顾清','明','凉风过林薄，
众绿俱以萎。
嫣然丛苇间，
见此春花姿。
物变理趋朽，
化工岂其私。
老螳缘其颠，
顾盼如有思。
物情怜晚荣，
予亦怀安期。
因之发孤咏，
持玩惜芳时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1068','送宗都运廷威之长芦','顾清','明','我家东海居，
目击鹾丁苦。
民劳莫如农，
衣食自王土。
输官赢斗升，
小大得濡喣。
溟沙列万灶，
勺合尽官府。
肩箱入连仓，
私鬻剪为虏。
燎薪与募直，
一一挂文簿。
商课或不充，
输钱为市补。
缗镪非天坠，
贸易复何所。
不应为法初，
乃尔自相牾。
公私两煎迫，
称贷日旁午。
穷年困炎歊，
肉尽继肝膂。
坐令兼并徒，
旦暮收拾伍。
微文牵积弊，
鱼烂不可举。
常思桑孔意，
宁料遽如许。
必逢忠爱士，
重为整机杼。
宗君沧州行，
倚任切当宁。
北南虽殊风，
物久理同蛊。
执炎思冷风，
久亢觊霖雨。
便文止须臾，
垂名动千古。
予言未可穷，
君行念靡盬。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1069','送同年施亨父令固始','顾清','明','霄汉初分列宿光，
固陵回首是桐乡。
驿程到日齐封尽，
乡信回时郢树苍。
莫以官曹殊内外，
直须政事抚流亡。
老成人物经纶手，
遴选应无负庙堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1070','送沈良臣赴南雄守','顾清','明','南安旧俗思张守，
又喜南雄得使君。
五岭封疆元不改，
三吴人物并能文。
香凝画阁晨听事，
风捲朱旗晓看耘。
正使勋名照青简，
未须违远叹红云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1071','南雄北界南安民以负担为利数起争焉张公汝弼守南安为正疆界而二邦之讼息故诗语及之秋郊观稼','顾清','明','金天高迥霜日晶，
原田靡靡黄云平。
老农携馌坐田首，
梨枣缀树光晶荧。
儿童笑呼驱鸟雀，
落日村巷多欢声。
我行按辔为助喜，
感叹欲去还徐行。
前年江南雨连月，
百谷烂死秋无成。
去年山东仍苦旱，
塍尾兆坼横庚庚。
室中啼呼道傍卧，
岂有束穗酬深耕。
今年丰稔信可乐，
却思旧日还心惊。
茫茫禹甸极四海，
安得是处皆丰盈。
君不见紫瑶草，
俱长物，
惟有丰年妇子宁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1072','徐希曾母寿六十','顾清','明','天上春衣绚䌽霞，
庭前慈竹间黄花。
仙家岁月看初遍，
圣主恩波未有涯。
青镜自知双鬓在，
玉梭曾度五更赊。
遥知孙子称觞罢，
犹自从容问鹿车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1073','嘉兴蹇贰守六十得子','顾清','明','青雀东飞入海云，
梦熊新兆协生申。
天将福胤怡眉寿，
人向箕裘卜世臣。
那用铅砂还汉鼎，
直须花甲度庄椿。
无由共酌鸳湖渌，
一睹天家五色麟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1074','题画送李大尹','顾清','明','云白天青映海山，
使君花县白云间。
山中老稚收成毕，
齐望双凫日下还。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1075','冶斋先生挽诗','顾清','明','猎猎红旌动驿舟，
萧萧行李不禁秋。
盐梅已觖苍生望，
樗栎虚惭药笼收。
圣眷有隆馀恤典，
国谋谁与记先忧。
西风一掬羊昙泪，
东去遥添逝水流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1076','挹泉','顾清','明','寒泉出幽谷，
上有长松林。
我行林谷间，
毛发增萧森。
脱缨不忍濯，
竟日临清深。
清深堪娱嬉，
感彼潢污池。
当其在山时，
泓澄亦如斯。
皓质本易涅，
素心亦难持。
谁能幽谷里，
相对弄珠玑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1077','城南别墅','顾清','明','梦里南徐漏未残，
角巾回首便商颜。
傍村花竹多侵市，
背郭亭台远见山。
身世百年云变尽，
功名千古鸟飞还。
寻常诸杜频来往，
赌酒敲诗亦未閒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1078','送方与义赴资阳得读字丙辰斋居作','顾清','明','阳精行天明四目，
孽狐潜形狡兔伏。
太微郎位发光润，
万里炎荒起迁逐。
平生未识晋鄙阳，
邂逅幸饯忠州陆。
男儿有身许家国，
风波雨云随反覆。
资阳虽远实壮县，
次第皇恩此牵复。
古来直躬多坎坷，
毕竟纲常系吾属。
眼前琐细犹不弃，
如君岂合长碌碌。
天衢峥嵘岁华尽，
车轮宵脂马晨粟。
峨嵋西南望松桂，
已觉春阳动幽谷。
从来自许百鍊钢，
此去人看九秋菊。
微之一折轻自坏，
元城百挫无转足。
两公遗事炳丹青，
牙签时整西风读。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1079','斋居和同馆曹良金刑部韵','顾清','明','华月分光映列躔，
白云元共紫微连。
炉熏茗碗还今夕，
阁试堂书又隔年。
功业要看归宿地，
赓酬不碍往来篇。
欲驱蹇劣追神骏，
拨尽寒灰午夜前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1080','送殷通判之严州','顾清','明','三百危滩走急流，
万重山色护严州。
人家树里开图画，
驿吏花间候䌽舟。
骏足岂应今日展，
高名合向晚年收。
子陵祠庙云霞上，
为想春风露冕游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1081','乌木扇歌','顾清','明','南蕃乌查乌角光，
剡溪溪藤色比霜。
两物迢迢天一方，
阿谁妙手巧裁量。
坐令皎月生筐箱，
金花点缀七宝装。
牙箫钿靥回光芒，
为君鼓舞生清凉。
回思故国云茫茫，
枯蔓朽株纷路傍。
人生贵贱岂有常，
牺尊沟断同根芳。
君不见金门六月清暑殿，
犹堪舒卷奉君王。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1082','陪李子阳吴克温二太史杭世卿吏部游城东潘氏园赋得流水','顾清','明','玉泉山前看滥觞，
凫鹥翔集菰蒲香。
远波明灭带城阙，
别派宛转通林塘。
褰衣经涉孺子喜，
展席俯视尘襟凉。
斜阳上马傍堤去，
极目东流思故乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1083','游香山','顾清','明','几年尘里说登山，
涉涧穿林路几盘。
碧树楼台深见寺，
红云城阙远平阑。
廊僧揖客多乡语，
春菜登盘称野餐。
斜日催人强归去，
欲从羸马谢朝冠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1084','送李原复之南京刑部','顾清','明','水云亭上坐论诗，
眼见红芳落酒卮。
好景一番连孟夏，
故人相继作分司。
风波道路君应识，
冰檗心怀我旧知。
两字哀矜一尊酒，
临歧不唱渭城词。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1085','升彼高堂为毛太安人寿','顾清','明','升彼高堂，
酌其兕觥。
兕觥欣欣，
春酒载盈。
维彼硕人，
是介是承。
硕人雍雍，
厥德洵美。
载其有家，
维惠恭止。
维惠恭止，
休其承祉。
其祉伊何，
兰茁其芽。
处也家宝，
出维国华。
国华有辉，
维帝宠嘉。
锡之鸾书，
曰汝之报。
汝考汝母，
汝迪汝教。
维往莫追，
生也永耀。
硕人拜命，
弗掖弗持。
珠翟霞裳，
象服孔宜。
邦人来观，
秩秩其仪。
其仪秩秩，
其容有怿。
乃筵斯堂，
乃几斯席。
硕人燕胥，
笾豆有绎。
维南有山，
维东有海。
硕人寿考，
终燕乐岂。
山石弗砺，
海波弗尘。
维彼硕人，
于千百春。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_1086','双桂堂为宜兴张世麟世凤赋','顾清','明','美人出南国，
文采并娴都。
风云一朝会，
联步起天衢。
伯也空冀北，
叔兮照三吴。
何异同根桂，
分庭各敷腴。
春风会京邑，
闾里增欢娱。
联芳世所羡，
况此一岁俱。
峨峨双桂堂，
丽榜辉新图。
清芬既不异，
茂干宜相扶。
昔闻云间陆，
亦有眉山苏。
往迹炳如在，
师贤在吾徒。
皇风发雅奏，
金石间笙竽。
愿附棠华咏，
千秋扬令模。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1087','题竹','顾清','明','悬石嵌青空，
下临湘江水。
中宵明月来，
照见青鸾尾。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1088','送王敬止使朝鲜','顾清','明','大人值兴运，
避地开东藩。
八条一以施，
礼俗仪中原。
燕满中扰乱，
淳风久仍存。
流传扶馀慈，
至性天所惇。
真德颂唐运，
金石振清温。
至今云海上，
想象扶桑暾。
皇帝膺宝历，
威德被鱼豚。
维东实首顺，
圭组继胀膰。
赴告谨终始，
宠数亦殷繁。
皇皇使者车，
中天下旂幡。
共瞻天人姿，
照耀东海垠。
宇宙有大界，
中华有常尊。
奉使固有体，
专对非徒言。
春风海山道，
注目盼回轩。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1089','送李太史希贤提学浙江','顾清','明','吴越连云海，
蓬瀛切斗枢。
皇仁无内外，
宪府敕文儒。
左掖天低户，
西清月在隅。
法冠初著豸，
文笔近提朱。
甄别推明鉴，
陶镕属大炉。
化源深涤溉，
皇路俨驰驱。
帖括经言病，
雕镌士习殊。
洗心端有待，
简命的非徒。
列屋思明烛，
停云怅据梧。
真淳钦雅度，
洒落见长图。
梁栋时方重，
昌苓世并须。
未应嗟远别，
回首是清都。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1090','送杨邃庵提学陕西','顾清','明','海内声华四十春，
向来江汉梦犹新。
门墙愧不参诸子，
祖席何期列从宾。
东壁二星终近斗，
南徐一水又通秦。
平生万里真无负，
到处青云满后尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1091','送沈云松还上海','顾清','明','已觉人间万事全，
钟情犹为别离牵。
但令消息年年好，
即是斑衣舞膝前。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1092','送沈明本教泰顺','顾清','明','欲别无言意万重，
扁舟望望过江东。
名场自昔有遗恨，
学海几年成此翁。
人向中朝愧山简，
天教南士识胡公。
云门雁荡经行处，
为想肩舆入画中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1093','送沈鸣岐教寿昌','顾清','明','七里滩头倚短篷，
锦云峰里坐春风。
旧来鸑鷟文犹炳，
老去骅骝气尚雄。
人世几番云作雨，
功名千古鸟飞空。
何当共酌桐江水，
一洗从前鄙吝胸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1094','送李子阳先生归省','顾清','明','朝下西清月未沉，
东门冠盖簇儒林。
湖山梦里三年别，
风雨秋前一夜心。
后阁承欢青鸟集，
前星回望䌽云深。
潘家林外春阴在，
还许追陪继赏音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1095','送王伯安下第还馀姚','顾清','明','五色光中炫早曦，
丹山秋日凤南飞。
常疑劲翮冲霄惯，
未信中原结网稀。
吴越天连双阙迥，
蓬莱云近一星辉。
杏花江上春如海，
莫待西风吹绿衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1096','题莆田郭氏世美卷','顾清','明','酂侯传国魏谟封，
七叶貂蝉四世公。
我赋郭家三孝子，
万年人纪列清风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1097','题莆田郭氏世美卷','顾清','明','壶山苍翠入闽天，
曾见参军哭墓年。
生死靖康南北路，
可知当日事昭然。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1098','题莆田郭氏世美卷','顾清','明','一家纯孝祖孙同，
狂卒何知亦敛戎。
看取弟兄争死日，
古人何必是褒融。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1099','题莆田郭氏世美卷','顾清','明','一命初沾竟力辞，
清漳心事鬼神知。
平生不惯谈茫昧，
欲与先生赋瑞芝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1100','恒斋为体斋宗伯弟曰谦赋','顾清','明','浮云天地倦西东，
一语南人契始终。
自古良医比良相，
传家正尔不须同。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1101','恒斋为体斋宗伯弟曰谦赋','顾清','明','粉署微垣列弟兄，
青囊留我万山行。
年来悟得雷风象，
不向人间取近名。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1102','送石训导之临湘','顾清','明','令弟清台著绣衣，
一毡还与郑虔宜。
过湘不用轻为赋，
圣代崇儒正此时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1103','送石训导之临湘','顾清','明','天岳山前倚短篷，
目穷飞鸟没晴空。
平生万里江湖念，
都付春风化雨中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1104','送华文光尊甫南归','顾清','明','数行官柳带城斜，
又送庞公上小车。
天上神驹方独步，
江南乔木几名家。
山当朔野霜先结，
水绕官河路不差。
闻道家君北来近，
相逢何处整乌纱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1105','送郭鲁瞻知山阴为砺斋太史作','顾清','明','我家简子山阴日，
清昼垂帘一事无。
遗俗未应忘旧老，
好官须自出吾儒。
青春日月当周道，
黄甲风云入壮图。
别有故人簪彩笔，
金鳌峰顶候双凫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1106','寿罗子文父得钟山芝','顾清','明','龙蟠山下郁青葱，
紫盖分明五叶通。
灵秀独钟麟趾地，
寿昌多应鹤髯翁。
歌传汉府空闻调，
食著仙经是有功。
拟掇芳腴荐清醑，
夜深飞梦绕江东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1107','杨启祥金兰','顾清','明','煮胶和金金作泥，
捣蓝染楮光砑脂。
杨郎醉把离骚词，
幽意已在沅湘湄。
须臾光风荡朝曦，
林隈水曲皆春姿。
丛石卧羊低竹枝，
紫茎绿叶芳菲菲。
佳人远游春不归，
蘼芜绿满孤帆迟。
愁来罢琴抚瑶徽，
临图更觉同心稀。
愿采芳香遥寄之，
江湖阔远波浪危，
空梁落月渺予思。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1108','送苏伯诚太史提学江西','顾清','明','郁孤台下驻旌旄，
鹄立诸生拥绣袍。
新命北来天语重，
故乡南望岭云高。
欧阳旧俗尧藩冠，
许国遗宗汉署豪。
有待一番时雨遍，
归来东观理风骚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1109','堵氏母七十','顾清','明','纨布萧然古孟光，
向来闺阃意何长。
不将本分矜流俗，
直以孤贞代义方。
年与日添频把酒，
心随兰死只留香。
良人地下应含笑，
青鬓于今浅带霜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1110','重送刘文瑞有怀顾颐弘先生','顾清','明','太息颐翁不可招，
离亭东望客心劳。
贻书恨不当时早，
归兴何如此日高。
尘世百年终剧戏，
溪山随处足游遨。
只应未及君家祖，
烂醉春风拥二豪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1111','严以德送女至留半月归赋长句为别','顾清','明','我弟之妇君家甥，
君女还作吾儿妇。
天然两姓若萝葛，
不独朱陈誇世旧。
忆昨与君初结言，
望松楼下开宾筵。
友松老人执杯酒，
千金一诺须臾边。
微官系人不能去，
五载停云渺江树。
向平心事两自知，
山阔水遥关百虑。
西风鱼雁交梭驰，
君来不来使我疑。
不知今夕是何夕，
把酒却送君南归。
君来官河尚舟楫，
君归河梁积冰雪。
故人分手自不堪，
况复钟情初远别。
钟情远别不须嗟，
儿今有室女有家。
官道附书如驿置，
春江放棹若仙槎。
人情得陇还望蜀，
我已安排洗孙局。
明年此日待君来，
玉果犀钱遍童仆。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1112','题雪竹送陈生归吴','顾清','明','虎丘山下雪晴时，
拄杖敲门自一奇。
京邑归来看图画，
春盘玉版斗青丝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1113','崔民瞻郎中父母同寿','顾清','明','万里晴空倦鸟归，
祝融峰下旧柴扉。
手栽堂树皆堪芘，
坐对云山已息机。
长日溪鲜堪入馔，
新年宫锦又添衣。
孟光同德还同岁，
何止人间七十稀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1114','送赵悦梅','顾清','明','北来行李报家君，
归棹还迎潞渚春。
两岁风光动梅柳，
一时冠盖集荀陈。
无穷渌蚁尊中满，
有约青山梦里频。
长向西风听佳信，
阿戎官况只清贫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1115','戊寅四月廿八日录至此叹息久之时天常殁矣保定赵守浚河筑桥诗为傅北潭太史作','顾清','明','郁郁平阡带古壕，
沈沈新绿卧虹腰。
滹沱不复思王霸，
溱洧何烦济国侨。
千里桑麻分雨露，
一时粉绘杂风谣。
他年三辅收遗事，
应续黄图第几条。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1116','题孙良辅所藏小景四幅','顾清','明','野桃山杏各乘春，
多事刘郎为怆神。
六百年来只如此，
一番花老一番新。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1117','题孙良辅所藏小景四幅','顾清','明','坛杏无花到水莲，
中间辽阔二千年。
窗前风月湖边景，
只恐丹青未易传。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1118','题孙良辅所藏小景四幅','顾清','明','欲出未出峰顶月，
将栖不栖林杪禽。
曾踏长安软红土，
方识幽人此夜心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1119','题孙良辅所藏小景四幅','顾清','明','旧识襄阳孟浩然，
蹇驴冲雪据吟鞍。
老来自怯溪桥滑，
便作林逋一样看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1120','送周先生出守嘉兴','顾清','明','雪后燕山画不如，
东华晴旭散朝车。
黄迷禁柳辞龙仗，
红逗江花引隼旟。
西浙几年忧困弊，
南宫当日记吹嘘。
丈夫五马寻常事，
泚笔勋名俟特书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1121','季本清给事父母双寿','顾清','明','画帘花暖春云香，
金尊酒满蒲萄光。
玉童双歌按清商，
门前珠履来成行。
凤生三雏一雏翔，
淩历紫清栖柏梁。
两雏膝下斑衣裳，
春风对舞送霞觞。
山中之臞炼铅霜，
洁身独立遗天常。
槁项黄馘同枯桑，
人生七十齐高堂。
腰有绿绶怀银章，
俯仰无愧终康强。
滑甘滫瀡供时尝，
三山弱水是何方。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1122','蒋监事济民出主靖安簿盖不得于其长也为题其秋塘白鹭图送之','顾清','明','曾逐青云上绣衣，
龙墀晴日飏朝晖。
天风不碍江湖迹，
还向秋塘自在飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1123','题毛维勤所藏禹门三跃图','顾清','明','一夕风雷动九重，
春江回首万鰅鳙。
云泥只尺从人辨，
诸葛南阳本是龙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1124','题陈克明竹','顾清','明','日永湖山桧影斜，
微风时堕紫藤花。
道人无限江南意，
更写筼筜向客誇。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1125','送赵明嗣袭职之金陵','顾清','明','锦衣将军燕蓟郎，
面围红玉颜清扬。
全家旧住双阙旁，
一门诸父皆周行。
阿翁昔日事先皇，
金戈日侍殿东厢，
一日不见回清光。
将军后出亦堂堂，
韬钤间续诗书香。
十三学书临硬黄，
十五百步穿垂杨。
二十辞家宦南国，
已觉万里前无当。
圣人南面驭八荒，
风尘不动塞草长。
将军功业何所见，
可惜龙剑明秋霜。
龙剑明霜龙不如，
莲花凿镂金蟠挐，
但令不试慎勿疏。
君不见金张之子世宿卫江东，
虽好岂是将军居。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1126','梦作朝退步至南亭诗有步入南亭路不难落花红衬紫苔斑之句感而有作','顾清','明','一自看花入上林，
溪山长是梦中寻。
不知谁辟南亭路，
又向朝回发短吟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1127','出郭','顾清','明','出郭频瞻尺五天，
雨馀云物更清妍。
楼高紫凤中天见，
山跃青龙到海旋。
香径细寻芳草入，
酒帘低傍绿杨悬。
微官自笑成何事，
閒过东风又一年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1128','出郭','顾清','明','好景城南四月天，
游人容冶百花妍。
红惊小辇流莺起，
绿衬阳坡细马旋。
风里游丝晴自袅，
雨馀新月晚初悬。
春光容易空抛却，
频倒芳樽莫问年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1129','阎太守复任西安','顾清','明','好去西安守，
还乘五马车。
封疆参井旧，
民物汉唐馀。
会府人咸喜，
铨曹最已书。
儿童候公久，
归驾莫纾徐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1130','王舍人孟端为华处士作耕渔图久而失去其孙珵访求得之','顾清','明','舍人善竹兼善画，
源流本是湖州派。
湖州之画掩以竹，
舍人妙思䌷不足。
耕渔之图谁所传，
华家明珠海上还。
家声不愧见父祖，
元气有托留人间。
川原靡靡高复低，
东村网罟西村犁。
长鞭驱烟入深树，
小艇载雨归前溪。
溪鱼正肥春酒熟，
百斛新输官廪粟。
酒酣月出歌一声，
何处高门有华屋。
浮生不逮斯人早，
前辈风流迹如扫。
银钩金错发天机，
何幸典刑犹此老。
舍人寸纸时共珍，
华郎见图如见亲。
乾坤无穷百年速，
撝诃安得烦鬼神。
君不见平泉树石散诸贵，
此子此孙今几人。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1131','萧升荣母曾孺人挽诗','顾清','明','堂北霜风紧，
天涯客梦催。
犹看衣线在，
不及诰鸾回。
遗德良人感，
新铭阁老裁。
前山松柏迥，
猿鹤助悲哀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1132','萧升荣母曾孺人挽诗','顾清','明','氛沴交行日，
乡邻出次时。
情惟舅姑重，
义不死生移。
执礼神应鉴，
怜孤族并推。
小郎今长大，
衰杖有馀悲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1133','闻蛙','顾清','明','入秋足霖雨，
颇长南池渌。
鸣蛙欣所遇，
日夕鼓其族。
喧喧未渠已，
隐隐撼吾屋。
群和杂蛄蚓，
间噪警鹅鹜。
已惊西堂梦，
复乱城南读。
孔公乃纪实，
周生斯矫俗。
鼓吹本吾厌，
矧兹强称目。
盐调恧胹熊，
灰洒念燔菊。
顾兹繁有徒，
一一胜掩扑。
维天运四时，
万品均化育。
妍媸与细大，
赋受咸自足。
春阳鸣鹂鹒，
寒雨悲蛩蠋。
时至理则然，
天机讵能伏。
可憎谅多在，
君意偶斯属。
不见趸与蛇，
无声日衷毒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1134','亚圣嗣孙翰林五经博士元蒙恩赠封父母','顾清','明','尼邱降神圣，
鸿化流无疆。
三迁毓明德，
重光丽秋阳。
周辙竟不西，
斯贤复遑遑。
坐令百代下，
掩卷悲齐梁。
博士几叶孙，
逢时迈虞唐。
通籍联禁从，
鸣玉司烝尝。
仍于报功典，
再衍酬恩章。
煌煌紫鸾书，
照耀东山傍。
逝者不可作，
萱枝独芬芳。
永怀五鼎意，
先后同悲凉。
予亦章甫士，
诗书沐馀光。
顾兹盛明典，
何以称褒扬。
共惟神明胄，
允矣万夫望。
惟圣始孝弟，
惟皇眷忠良。
怀哉复何言，
尔祖训有常。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1135','寿少师谦斋先生七十','顾清','明','太微无云星汉明，
商飙按节回玉衡。
土阶六叶飞尧蓂，
岁在戊申申甫生。
甲戌仲舒杨大庭，
引翼房杜登蓬瀛。
金钟玉律谐颂声，
圣人龙潜资六经。
缃麻日侍龙楼清，
有时石室翻金縢。
甲子周岁龙飞腾，
白麻首出金瓯名。
司马入府毡裘惊，
十年海宇歌太平。
如皋如夔连茹征，
鸾鹄济济充皇扃。
并包细大靡矜争，
香山日夕思旧盟。
帝恩非常归未能，
黄扉日晏下紫清。
寿觞百斛分金茎，
谁欤寿者公与卿。
次者乃是銮坡英，
天佑我皇惟纯精。
钟灵毓秀归老成，
往昔宵寐通精灵。
先知已属范高平，
麟袍五色腰玉横。
巍然百辟瞻仪刑，
氓饥欲粟寒欲缯。
公无言归劳圣情，
年年此辰称兕觥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1136','送毛彦伯','顾清','明','议论相逢便伟然，
省华诸子固多贤。
风云幸接鸿飞后，
乡国仍看樾荫连。
两月客程还膝下，
几宵归梦又江边。
春衣好作重云锦，
令祖新秋又八千。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1137','送李师文令将乐','顾清','明','建业秋风歌鹿鸣，
同时龙李最知名。
一筹已惜三年后，
百里犹烦匹马行。
星出紫垣南去迥，
水经闽岭北来清。
馀杭令尹新祠庙，
香火于今更有情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1138','爱鹤为海虞曹舜祥赋','顾清','明','青田双白鹤，
脱略尘凡姿。
东海有逸民，
心赏同幽奇。
天质不自媚，
野情谅难羁。
逍遥云海间，
永与鸡群辞。
鹤也诚可人，
爱鹤人可知。
人有异于鹤，
贾鞭眩黄栀。
骎寻不自觉，
沦没共污缁。
君子拟鸾凤，
憸壬乃鸮鸱。
我歌爱鹤篇，
继彼乘轩词。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1139','米元晖小景一幅浅色积成高五六寸长不二尺而渺然有千里之势为赋六言','顾清','明','芳树春酣雨后，
薄云横带山腰。
极目青萦白缭，
江南何处迢迢。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_1140','樗老杨翁挽诗','顾清','明','昔年同馆士，
频岁泣霜风。
又接樗翁讣，
其如洛社空。
行身汉阴叟，
避世鹿门翁。
渐觉沧洲远，
烟波日夜东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1141','樗老杨翁挽诗','顾清','明','道为无心得，
才因不用全。
子看青琐贵，
身到白头年。
太史春秋志，
中台琬琰镌。
新坟才四尺，
佳气日苍然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1142','樗老杨翁挽诗','顾清','明','海雁依时到，
庭花不再红。
通家锦囊在，
入室繐帷空。
歌哭同杯酒，
江湖想钓筒。
真淳那复见，
落日起悲风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1143','厉处士挽诗','顾清','明','末路嗟何似，
江湖见此奇。
能于外物薄，
不逆故人欺。
淳孝真堪传，
馀言尽可师。
九原逢德耀，
无愧白头词。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1144','九日卫景玉西庄赋','顾清','明','前年重阳燕城南，
去年重阳小山前。
今年重阳西郭下，
青山碧树开芳筵。
前年坐客黄与李，
去年去作南曹吏。
今年坐客罗八九，
一半相看非旧岁。
不才濩落无所施，
三年坐食尻生胝。
主人爱客我不去，
年年对举黄花卮。
西清步出长安道，
一带青山远相撩。
霜风拂衣声摵摵，
寒日映帽光杲杲。
入门下马耳已清，
刘东胡琴薛鸾筝。
新声共爱白翎雀，
浮云不动黄龙城。
黄龙古城秋草里，
狐狸钻穴荆棘横。
石家郎君从失足，
四百馀载胡风腥。
西风慷慨对斜日，
只此便合倾千觥。
主人有酒，
客无庸辞。
千古在前，
后亦如斯。
中间可乐，
其与几时。
谓君不信上高处，
燕丹郭隗冢累累。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1145','十日南山宅尊乡会分得东字','顾清','明','摇落龙山夕照空，
衣冠高会凤城东。
从渠海内风流盛，
输我尊前笑语同。
几处黄花如故里，
他年绿野感秋蓬。
晚来白发颓中坐，
欲改南山号醉翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1146','题史引之所藏长江六月图','顾清','明','长松泠泠生昼寒，
高岩侧缀青琅玕。
阳坡宛转行朱阑，
青莎滑腻碧藓斑。
红桥直走淩惊湍，
下接孤屿高巑岏。
隔江青山如伏羱，
柴扉草堂相对安。
渔舟缥缈青林端，
樵童牧叟时往还。
群山忽断百里宽，
青蒲绿藻萦微澜。
临江飞阁丛井干，
江流石角随弯环。
前山转深势未残，
层崖复磴劳跻攀。
上方寂寞空禅关，
平林演迤临江干。
江回山尽路险艰，
飞梁侧卧波潺潺。
江流自此入渺漫，
遥山一抹天际看。
东京画史真高閒，
故将山水穷瑰观。
岷峨嘉陵远草殚，
九华落星扬子湾。
晴洲历历被芳兰，
美人不来空浩叹。
疾风吹尘暗燕山，
金星龙尾冰攒攒。
燔熊炽豹光赫殷，
为君炙兔扫冰纨。
君归终日山水间，
肯忆羸马随朝班。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1147','十月四日同韩国器中书张时行吉士饯刘御史文焕还赴尊乡会于陆太仆第得夕字','顾清','明','东城送客罢，
觚棱动暝色。
尊乡奉严戒，
后至有明谪。
挥鞭不返顾，
望望淩紫陌。
同行韩与张，
先后互驱策。
我马才本下，
此日殊努力。
及门见僮骑，
相顾如有得。
主人闻客来，
索带命殽炙。
众宾已沾醉，
为我还促席。
劝酬略登降，
问劳杂谐剧。
写情会有赋，
探韵止馀夕。
飞觞不假借，
阁笔岸予帻。
清时自难遇，
胜会固鲜袭。
今晨复何晨，
烂漫挹珠珀。
矧兹乡邻聚，
更觉情景适。
南斟出珍藏，
北馔割鲜硕。
虽微霜橙荐，
时菊尚可摘。
寒更近尤长，
城柝时漫击。
华镫蔼馀辉，
落月沉坏璧。
欢悰不可竟，
明发会有役。
据鞍谢主人，
璇标已东北。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1148','十一月朔张南山寿日','顾清','明','一自登名立从班，
周旋长在五云间。
官阶四品中兼外，
书法三吴柳继颜。
退食有时乘褐马，
趋朝满目是青山。
蓬台此日群仙会，
风雪犹应许扣关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1149','送袁良辅还封丘','顾清','明','闻道双凫晓欲飞，
锦笺红烛夜裁诗。
月明古寺嗟人远，
寒压重裘觉岁驰。
卓令至今佳传在，
山公休道荐书迟。
黄金台下西南路，
眼见青骢入奏时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1150','董虞臣辰溪八景为赋其二','顾清','明','云根一片压中流，
曾是仙人玉斧修。
绝岸巧通平野去，
细波长共远山浮。
苔纹想象空飞舄，
树影参差壑驾舟。
借问碧阑容点笔，
淩风我欲试清游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1151','董虞臣辰溪八景为赋其二','顾清','明','桃花不记武陵源，
峒里人间别有天。
罨画溪山明白昼，
接云禾黍自丰年。
前冈饮犊逢巢父，
别浦移舟渡辋川。
问著主人无一事，
久抛金甲事春田。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1152','冬至感怀','顾清','明','浮世侵寻四十将，
劳生何以称冠裳。
回思丁未看辛丑，
别有愁根更是长。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1153','戊午元日候朝和冬至韵','顾清','明','尘途役役苦迎将，
五色谁从补舜裳。
坐拥槐枝候明发，
忧端不数漏声长。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1154','谒文山祠次同游诸公韵','顾清','明','东风一梦过钱塘，
直自元丰兆靖康。
终岁诸公讲和战，
到头赤手树纲常。
生前骨肉山河碎，
身后辉光日月长。
新庙城南更雄丽，
公忠遗种讵荒凉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1155','人日乡里会归曹良金秋官寄示咏怀新句明日斋所奉答','顾清','明','薄寒催酒斗新年，
犹是郊斋一日前。
事往旧游真作梦，
诗来险韵恰逢咽。
莺调歌舌方求友，
柳著官黄欲试绵。
子建平生最萧洒，
壮怀宁许豆秸然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1156','同年斋院中朝振同戴御史元之宿僧舍宪清南夫有诗嘲之往返良苦予最后作为之解围','顾清','明','清晓诗筒入递频，
夜窗虚榻看横陈。
贾馀竞欲收三捷，
戒狃予方息两民。
掖竹本因枝带叶，
胡卢岂必画非真。
西堂三日伊蒲馔，
且共瞿昙讲幻身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1157','同年刘直之父母双寿','顾清','明','东望蓬莱极海云，
仙筹满屋旧曾闻。
老馀骢马留桓典，
归卧青山共少君。
华发笑看明镜在，
䌽丝犹忆画帘分。
高堂岁晚长生燕，
还折梅花映宝薰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1158','纪梦寄文宿诸友','顾清','明','客舍春来觉梦多，
黄衫连夕报登科。
七星散落云中斗，
独鹤高乘树杪柯。
捷足故人俱绿鬓，
关心乡社渺沧波。
从今不作停云望，
倾耳雷门听凯歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1159','送汪进之令永嘉','顾清','明','马上相逢识未真，
论交已是十年人。
风云聚散惊浮世，
霄汉飞腾有健身。
奉日岂应忘近主，
鸣琴聊欲试亲民。
东风百里温州路，
谁看桃花满县春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1160','赋得瀛海奎光送马良佐先生之南院','顾清','明','仙家苍茫云海东，
海光上与星辰通。
昭回万象森布列，
灵景独应图书宫。
宫中明星十有六，
一一紫焰舒长虹。
珠宫贝阙相荡漾，
顷刻万状难为容。
群仙无事亦来往，
鸾鹤隐见空明中。
翩然一鹤下南斗，
流辉万丈惊蛟龙。
蛟龙惊遁海天净，
惟有匹练悬高空。
紫宫东南纵遐眺，
晴霞五色交青红。
天孙停梭赤霄上，
指点毫末分纤秾。
帝傍丝纶要经纬，
旋轸不待星躔终。
石渠延阁五云绕，
紫泥黄纸三更封。
悬知不学卯金子，
馀光反借青藜公。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1161','题萱桂图送徐理之父子','顾清','明','白头人对䌽衣裳，
本自无忧不待忘。
谁写萱花傍丛桂，
要看雏凤挹天香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1162','蒋国器往岁南归予苦头风不得送赋诗有记取他年说今日冷云疏雨出都门之句今再至而归予亦病中天复阴雨俯仰今昔为之慨然','顾清','明','五载京华两赋归，
客心都似宦情微。
天应有意还留舌，
雨亦何心惯湿衣。
长路不须怀近事，
旧题浑已谶先几。
小昆山下农田早，
为想秋风蟹稻肥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1163','徐子容祖母寿八十三','顾清','明','春湖映空光一碧，
春日烘云成五色。
金堂仙人燕王母，
云影波光乱瑶席。
麟洲别来几清浅，
兰叶萱枝翠如剪。
笑轮花甲问东风，
八十三年供一莞。
杨花扑帘春昼迟，
鸾笙幻眇朱弦稀。
瑶环涓秀瑜珥润，
戏舞绕膝争含饴。
就中一孙俊而奇，
珊瑚玉树含春晖。
担簦上国未能去，
几日目断孤云飞。
西风八月仙桂黄，
手携鹗书还故乡。
仙人一笑开北堂，
重帘复幔皆天香。
男儿悦亲宁碌碌，
作诗献寿还拭目。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1164','邹时鸣父母双寿','顾清','明','玉陛风光动䌽裾，
鹊声先已报江鱼。
鸾回两检新封敕，
龙卧三湘旧隐居。
喜气并添凝望里，
宾筵相压小春馀。
无因得与升堂拜，
长傍红云想使车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1165','家僮摘槐芽','顾清','明','小奴携筐绿掩苒，
斜日归自东邻家。
青精未试仙子诀，
泠淘的见诗翁誇。
人间正味竟何在，
天地育物真无涯。
紫莼青荇更不恶，
高秋谁泛三江槎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1166','送王约赴河间县丞','顾清','明','平原西北古瀛洲，
长记征车半日留。
山接全燕从地起，
河分二水带城流。
千年王泽诗书古，
永日丞厅竹树幽。
好去王郎更清白，
龙门一局未应休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1167','挽苏廷玉','顾清','明','到处江湖识此翁，
几番倾廪惠疲癃。
灵岩山下一片石，
叹息高踪已梦中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1168','何处士赏静亭','顾清','明','万里松州限蜀川，
风流幕府重当年。
筹边屡上金城略，
退食还歌菉竹篇。
意外云山争自媚，
环中风月许谁传。
瀼西茅屋长邻近，
相望孤鸿落照边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1169','送可晚吴翁','顾清','明','十里山塘接虎丘，
隐翁家近白蘋洲。
偶来暂别延陵庙，
欲去还同孺子舟。
云里䌽衣高捧日，
雨中黄菊苦思秋。
经年正有庭闱念，
为酌离觞悔远游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1170','送谢司仓','顾清','明','宁知信宜邑，
乃在古高州。
地接朱鸢近，
天连碧海浮。
官仓馀火米，
土俗罢绵裘。
莫作炎蒸虑，
男儿重远游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1171','书饶贡士友爱堂卷','顾清','明','江雨红垂荆树花，
草堂千里梦京华。
无人为续池塘句，
长向春风忆谢家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1172','书饶贡士友爱堂卷','顾清','明','风雨长安旅食孤，
夜窗灯火说江湖。
红尘下马东城路，
来看饶家友爱图。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1173','送夏良惠','顾清','明','君从澄江来，
还望澄江去。
澄江渺千里，
孰是君归处。
连连波上山，
历历沙边树。
长安多亲知，
青云在指顾。
一行拂尘衣，
高意竟莫禦。
淩江望农烟，
憩石呼晚渡。
芳阡笑儿童，
佳木散徒御。
问讯钓鱼竿，
汀洲未云暮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1174','送宋惟德分教池州','顾清','明','池阳风物似长沙，
第一名山是九华。
输与能诗宋文学，
芙蓉影里岸乌纱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1175','送王汝昭考绩还南乐','顾清','明','鸣玉薰风下紫清，
日华流采照君明。
重来一鹗秋期近，
暂去双凫晓翼轻。
封域未踰关辅地，
别离无奈故人情。
归轮入境应频驻，
一路棠阴父老迎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1176','送汪县丞还吴兴','顾清','明','吴绵百箧练千箱，
岁占东南第一纲。
不似朱家贡花石，
九重龙衮要文章。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1177','送汪县丞还吴兴','顾清','明','洞庭烟浪接吴兴，
使者归舟画里行。
浮玉山前万松底，
好诗多为别来生。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1178','题李徵伯扇','顾清','明','新雨蕉叶大，
云根生昼阴。
只此可永日，
何必弦鸣琴。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1179','题赵希文所藏王孟仁小景','顾清','明','柳丝如烟散晴风，
小桃野树交青红。
芳洲细草何丰茸，
绿波远与青天同。
遥山西入空濛中，
扁舟兀坐谁氏翁。
物色似是天随公，
惊麇骇鹿不可踪。
此日此意殊从容，
自从挟书朝帝宫。
十年梦寐劳江东，
长桥飞盖连垂虹。
尚想烟雨推孤篷，
偶然一笑岂易逢。
丹青信有缩地功，
燕山六月苦蕴隆。
开轩对此情无穷，
谁欤往者吾其从。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1180','送盛世虔兼简严以德','顾清','明','红云千里隔江关，
容易看君独往还。
留得锦笺无恙在，
不教空到小吴山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1181','送盛世虔兼简严以德','顾清','明','东河日日望兰舟，
远客新年已倦游。
为忆相逢话京邸，
红菱白藕正清秋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1182','书吴通判焚黄卷','顾清','明','淮甸风烟接海门，
甘棠随处绿阴蕃。
人传旧德歌三异，
帝有新恩贲九原。
华表月明苍树合，
宝函春动彩云翻。
乡人应悔籯金误，
衰草荒坟泣断猿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1183','送杨启祥','顾清','明','杨生画兰近无敌，
挥笔使金如使墨。
玄缯绀楮随所遇，
入手光风灿朝日。
湘江南北几千里，
收拾都归笔锋里。
閒来天上弄秋光，
落笔便得天颜喜。
有时片纸出人间，
传看一日遍九廛。
五侯七贵争莫致，
时复挥翰骚人前。
西风八月吹锦衣，
掉手还向江南归。
汀洲蘼芜寒更绿，
木叶时傍孤帆飞。
回首思君何处切，
南薰殿里午风微。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1184','八月六日周北野宅尊乡会雨不能赴先是予招客亦值大雨','顾清','明','秋雨亦无赖，
偏欺我与君。
每当开燕日，
故作满城云。
未说初春旱，
何如后夜闻。
一般尤足恨，
红湿从伶裙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1185','孝松为故华亭贰尹吴君赋','顾清','明','君昔哦松古华亭，
我方挟书游县城。
流风善政尚能忆，
未省至孝通神明。
郎君京华报君讣，
握手道边双涕横。
潜光隐德有如此，
如君岂独堪为丞。
乾坤茫茫日月速，
斯人已复从先茔。
茔前郁郁万松树，
总是君手栽培成。
乡人重君不忍斥，
指点苍翠歌仪刑。
秋霜春雨几悲怆，
大篇长句何铿鍧。
松兮节操本自贞，
何幸遇君增令名。
田家紫荆尚千岁，
何况美与参骞并。
我歌孝松君敬听，
古来万化由家庭。
行将东海甘棠树，
并入朱弦流颂声。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1186','乡人徐景晖老而丧子游京师意象悲甚将别赠此','顾清','明','早向丹山识凤雏，
十年清梦隔江湖。
偶来聚首惊霜鬓，
忽漫长歌缺唾壶。
春雨南洲生杜若，
夕阳西崦近桑榆。
扁舟挥手渡江去，
从此人间谢畏途。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1187','东海先生有表弟褚君跛一足先生呼为鹧鸪叟输赋入京求此诗','顾清','明','有叟有叟名鹧鸪，
壮年意气亦豪疏。
豪行不顾一足拘，
苦吟赢得全身癯。
有儿不令左右扶，
独携短筇朝帝都。
县吏睢盱索官租，
儿职催科翁代输。
输完妇子得宁居，
老身健在百不虞。
西风官亭倾别壶，
亭树哑哑啼乳乌，
似是忧翁步趑趄。
乌不能言意有馀，
何不啼向吴城隅。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1188','宋宫蹴鞠图','顾清','明','甲马营中五色光，
天将一统付真王。
后园踏鞠宁为戏，
犹有萧娘卧榻傍。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1189','题画送夏时臣尹龙游','顾清','明','红叶西风吹客衣，
江边行李立多时。
舟师亦解衢人喜，
横棹中流歌竹枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1190','新安郑氏四节坊','顾清','明','卫乱共氏理，
周兴比干封。
义节本天授，
褒扬系皇风。
閒披新安志，
仰企荥阳宗。
烈烈四女士，
允为男子雄。
世运有迁革，
英风浩无穷。
高闳丽云汉，
大字腾蛟龙。
在殷比三仁，
于宋齐五忠。
世有长乐老，
此地无经从。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1191','送少师谦斋先生致政归义兴','顾清','明','逢掖登庸玉带归，
近来亲见古应稀。
两朝旧学传黄卷，
一代完名映紫微。
西洛园池增胜槩，
东城冠盖掩前辉。
门墙剩有抠趋地，
还许相从认钓矶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1192','题画马','顾清','明','吴兴公子人中英，
文学之外百艺精。
龙纹鸟迹穷变态，
落笔万类无潜形。
画家难工在狗马，
即物计数皆天成。
平生所见凡几本，
如形在鉴影在灯。
君家此幅得何处，
真迹似是来吴兴。
前行三匹骏且狞，
急鞚恐作蛟龙腾。
一匹顾类未肯行，
一匹欲卧垂青缨。
中间一匹骨如堵，
四蹄犹带交河冰。
紫衫奚官发鬅鬙，
胡靴短靿带红鞓。
当年内厩事毛仲，
几随仙仗过华清。
兴亡百变物尽化，
惟有遗迹留丹青。
摩挲绢素三叹息，
毛鬣似觉雄风生。
君不见千金尚买死后骨，
此马此人君勿轻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1193','塞上谣','顾清','明','十月龙沙百草乾，
嫖姚乘胜逐呼韩。
关中更有萧丞相，
千里无忧给饷难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1194','塞上谣','顾清','明','千顷膏腴紫塞秋，
健儿耕作贵人收。
金城遗迹犹堪按，
只在忠良与国谋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1195','题松鹤图为周太守寿','顾清','明','翩翩双白鹤，
飞自瑶台阴。
玄裳既修整，
缟袂亦萧森。
乔林纵远步，
虚壑引清音。
俛仰各有得，
逍遥清涧浔。
达人事当世，
雅志本云林。
悬车不待岁，
戢羽思高寻。
何异松间鹤，
飘飖云汉心。
嘉诞宾友集，
初筵列朋簪。
鸣丝送旨酒，
抗节起高吟。
白日丽华栋，
簪犀炫钩金。
招要香山翁，
笑傲白云岑。
岁岁但如此，
焉知寒暑侵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1196','邹静修挽诗','顾清','明','好景耆年正合閒，
背堂花竹面楼山。
祖风田画交游里，
家法王凝伯仲间。
尘梦一宵惊汗漫，
舞衣当日记斓斑。
伤心玉井峰头叶，
谁共沧洲载月还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1197','陈清泉挽诗','顾清','明','短世匆匆春梦同，
蜉蝣蜾裸空西东。
眼中寿考已如此，
膝下子孙谁似公。
纪德前身太丘长，
游仙此去云台翁。
清风来往雁山下，
应笑白发悲儿童。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1198','题姜少卿廷宪墨竹','顾清','明','草草临池墨，
萧萧落叶风。
高情不可见，
怅望越江东。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1199','送程克晦','顾清','明','春阳迟迟风奕奕，
滦河潞河冻俱释。
河边官柳千万株，
一一长条曲尘色。
小车载酒沿堤去，
目逐行舟不能住。
攀条弄色临晚风，
却忆前年别君处。
君家奕世廊庙人，
暂蹶霜蹄何足云。
南山积书充四库，
西洛奥旨穷三坟。
山深昼长风日美，
把卷临流思千里。
有书数寄南来鸿，
慎勿待建邺西风吹桂子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1200','秦一元自通山尹调归善李文瑞索诗送之','顾清','明','青云早折桂林枝，
鄂渚鸣琴有去思。
为爱罗浮峰顶月，
清光犹得照朱丝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1201','陈汝砺宪使自云南入觐升左方伯','顾清','明','朔云逢入觐，
南纪送归藩。
地昔埋轮旧，
官今列岳尊。
冰霜回晚烈，
风日散春温。
定遣炎州物，
秋毫识帝恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1202','东圃题陈明之菊期南夫二郎','顾清','明','日出东轩积雪融，
菊芽兰茁竞春工。
君看石畔丛丛碧，
已办西风一丈红。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1203','吴汝玉自公安赴会试以例格不许','顾清','明','吴郎自负知何似，
一落荆南便十秋。
夜榻偶然同举酒，
春风几处独登楼。
名场接轸分胡越，
剑气中宵看斗牛。
已识行藏非在我，
江湖何地不优游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1204','月楼为杨尚絅赋','顾清','明','飞盖桥头踏月华，
顺流东去是君家。
晓风依约凭阑处，
隔浦金盆漾浅沙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1205','月楼为杨尚絅赋','顾清','明','层轩高栋切云浮，
纵有阑干不碍秋。
谁在隔江歌水调，
清寒重忆广庭游。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1206','题王敬止所藏陈明之菊二首','顾清','明','云根翳金英，
零露杂芳草。
忆昨南山行，
相逢正秋晓。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1207','题王敬止所藏陈明之菊二首','顾清','明','王郎东使年，
金绯照云海。
馀辉贲园芳，
岁晚犹采采。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1208','偶书','顾清','明','万事人间不可期，
云中日日候来仪。
九苞自爱桑榆暖，
惭愧西风碧树枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1209','偶书','顾清','明','鱼腹隐刀犹可测，
牛头有角岂难知。
寒泉渴饮真破甑，
更向青冥学忍饥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1210','李方伯挽诗','顾清','明','玉节新移自汴郊，
缄题千里托神交。
有怀旱岁为霖雨，
无地青山酹束茅。
南楚遗民怨芳草，
西江归榇泣潜蛟。
诸郎不忝长平裔，
云路争看丽九苞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1211','书感','顾清','明','九十百里半，
一篑千仞基。
少壮必有立，
晚节乃堪持。
感彼日暮者，
眷此青阳时。
婉娈不自爱，
瓦裂当告谁。',NULL,'','{"preface": "山阴青裙姥家有雪色鹅右军往观之烹鹅候烟萝入门访所闻盘馔纷前罗姥意岂不勤客来其谓何相知古云难即此感人多咄哉悠悠者何必皆操戈", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1212','袁澄夫顾东曙寄诗各次其韵','顾清','明','夜归连得故人诗，
二妙谁令聚一时。
感旧不知吾慷慨，
论才宁合子栖迟。
花当春半方堪赏，
杯到愁来只自持。
只尺龙潭笑游地，
扶摇今日望天池。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1213','袁澄夫顾东曙寄诗各次其韵','顾清','明','生世端如雪上鸿，
一尊犹记别时同。
云山有梦寻常到，
江水无情日夜东。
未许文章真我辈，
尚馀礼乐待诸公。
他年只恐西亭鹤，
哀怨西风繐帐空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1214','送胡仲光分务清江浦','顾清','明','计省郎官白发新，
抡才元是玉堂人。
不将粉黛从时样，
尽有风流愧后尘。
淮海又成千里别，
山林犹是十年身。
秋风会有离群思，
还向清江采白蘋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1215','送林光甫分教上犹','顾清','明','行尽西江是上犹，
南来五岭入云浮。
官曹不厌诗书冷，
风物且为山水留。
虚市早春梅子大，
畬田初夏稻花稠。
公馀我欲烦骑马，
一访张公铁汉楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1216','沙阳徐复礼持曹宗孝书来却归省亲还赴南雍秋试','顾清','明','剑岭西南不断青，
七峰罗立凤冈横。
弦歌里俗誇新尹，
江海奇珍见此生。
远信恰随春雁至，
归心先逐暮云征。
扶摇更觉南溟近，
为想西风六翮轻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1217','寄寿何以仁御医用匏翁韵','顾清','明','松间倚几逐阴迁，
竹里茶铛扫叶然。
老去益知閒有味，
丹成不恨世无传。
风尘笑我方为客，
云海如君更羡仙。
翘首碧山丛桂底，
一尊相属定何年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1218','送谭贡士拱之入南雍','顾清','明','陋巷频烦枉刺笺，
入门风格故翩然。
云衢继美看诸父，
璧水蜚英及壮年。
师友尽观南国士，
平安时报上江船。
清秋桂子金陵月，
还比长安一样圆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1219','送丁指挥','顾清','明','丁将军，
家习武，
身好文，
一生读书思致君。
君门射策不得意，
俛著兜鍪发如猬。
男儿岂必皆明经，
叔皮定远俱成名。
阴山尚有强梁客，
听我秋弓霹雳声。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1220','送任希贤分教云和','顾清','明','古栝风烟接四明，
旧家文学最知名。
承恩尚及青毡在，
怀土潜惊白发生。
春雨菁莪遥送喜，
秋风棠棣独关情。
祗应此后池塘梦，
长共飞云绕凤城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1221','题书堂二小画','顾清','明','收却吴蚕八茧丝，
草虫连夜促鸣机。
内家见此谁能解，
游子江南正忆归。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1222','题书堂二小画','顾清','明','蒹葭倚空未老，
蓼花被水初红。
我觉蜻蜓得意，
翾飞来往薰风。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_1223','两峰书屋','顾清','明','青山相对起，
我屋住中间。
读书有时倦，
曳履看青山。
峰头云气来，
飞翠入窗户。
相逢载酒人，
却度前冈去。
摊书石床上，
偶坐窗前树。
微风山半来，
松花落无数。
斜阳度西岭，
返照松下石。
莓苔新雨过，
灼烁炫金碧。
湖东海月出，
山半竹窗虚。
斜白棂间壁，
分明见蠹鱼。
明月照前峰，
影向北峰落。
幽人夜启扉，
惊去松梢鹤。
湖头三尺雨，
峰顶云一寸。
雨止山依然，
琴书得馀润。
自有两峰来，
几人此高卧。
掩卷问青山，
岩花向人堕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1224','春试锁院日闻刑部奏举邵郎中天衢任方面众许作诗送行已而得福建按察副使','顾清','明','剡报初传自棘闱，
使星今已向东维。
一时戏语今成谶，
两月清欢合有诗。
云近紫垣明绣豸，
日临沧海动朱旗。
还朝便作三年别，
未放秋霜点鬓丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1225','送徐子容下第归洞庭','顾清','明','长安城中十日雨，
马首不见纤尘飞。
群峰远想湖上碧，
一鹤独向秋前归。
青云缓步更自稳，
宝剑频拭还增辉。
江头今夕谁共语，
船窗落月明絺衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1226','何丘山生日会以疾不赴','顾清','明','西第南楼迹已尘，
北轩长夏更宜人。
年华如此便千古，
汤饼不须愁众宾。
炎日病躯妨跃马，
绿阴高柳正欹巾。
一番又负花前醉，
遥听笙歌聒四邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1227','湘水飞云','顾清','明','客有潇湘意，
新图展白云。
天边几晴雨，
坐里日氛氲。
聚爱桑阴茂，
行怜雁影分。
新年多喜气，
五色变龙纹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1228','西苑观太液莲圆殿古松及进冰者各记以诗','顾清','明','亭亭芙蓉花，
独出清沚中。
青天飞䌽云，
堕此明镜空。
杲日耀华色，
炯然临晓风。
天质岂不丽，
自无桃李容。
窈窕灵洲远，
逶迤仙苑通。
永谢蔓草缠，
寂寞甘自红。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1229','西苑观太液莲圆殿古松及进冰者各记以诗','顾清','明','层城出云雨，
其上多古松。
但观郁苍苍，
莫记植者功。
众鸟不敢栖，
恐是跋地龙。
回影拂金瓦，
疏枝吟天风。
翠华有时来，
绮绣交玲珑。
吾闻泰山植，
耻受秦人封。
物巨宜有灵，
时清多幸逢。
培植不厌厚，
乾坤固无穷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1230','西苑观太液莲圆殿古松及进冰者各记以诗','顾清','明','凌人慎时令，
初夏进寒冰。
天阙自旷迥，
龙楼晨更清。
金盘未及荐，
洞户秋风生。
瑶姬玉笋指，
仙袂六铢轻。
持玩更调笑，
柔纤映红明。
岂识单衣子，
冲寒镵冱溟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1231','王汉英通政母八十','顾清','明','银台先生发如漆，
太君高堂新八十。
朝回迎客花底揖，
花枝拂衣红一色。
折花奉觞拜膝席，
君家太君藐姑射。
太君沾醉朱颜溢，
鸾笙入房侍儿掖。
后堂歌声䌽云隔，
主人留宾还促席。
青衣传语催劝客，
太君万寿客无出。
从此年年作生日，
记取明朝是重七。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1232','题颜山人画送刘可大先生归五羊','顾清','明','山人胸中山万重，
傍吞云梦涵太空。
落笔天机横复纵，
须臾万象分纤秾。
大山盘盘云与连，
小山江面如浮烟。
江长山远望不极，
彷佛孤帆疑上天。
高岩飞流散冰雪，
转出深林凡几折。
上方台殿空烟霏，
下界尘嚣此中绝。
林回路转地益清，
垂杨一径通幽亭。
先生高坐客不去，
终日扁舟相对树。
平桥浅水带远村，
青林茅屋春氲氲。
儿孙生长不相识，
鸡犬有时中夜闻。
山人昔年侍明光，
填门造请皆侯王。
熊姿犀角日点缀，
局束不奈冠与裳。
兹图旷逸知有以，
无乃赐金归去放笔临潇湘。
风流太史同州彦，
乞归几奏金銮殿。
离觞载举索我歌，
不觉飞蝇污东绢。
山人山人今有无，
江湖落日愁烟芜。
玉堂挥翰须健手，
碧山长啸非良谟。
北来倘有阳关意，
好写瀛洲春燕图。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1233','七月十五日久旱而雨同启衷给事送林宗清','顾清','明','夜窗题诗风雨集，
想得行人喜欲狂。
领取官河三尺水，
连宵通闸放归航。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1234','七月十五日久旱而雨同启衷给事送林宗清','顾清','明','左谏声华日月边，
故人身到九重天。
山中桂树今无恙，
好赋淮南第二篇。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1235','陆仪宾使还过吴省亲','顾清','明','萧史乘鸾去，
千秋尚䌽衣。
来陪双阙拜，
行望五湖归。
故老争先睹，
高堂谢夕违。
山迎秋晚翠，
门映海东晖。
腰袅金重络，
芙蓉画两旂。
舞疑天上别，
歌听月中稀。
仙醴频添蚁，
宫罗叠送绯。
一尊欢不尽，
又逐彩云飞。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1236','题野庄卷','顾清','明','秋风吹庭树，
落叶满空除。
閒寻野庄句，
感我丘园居。
丘园正收穫，
此日乐有馀。
亲交亦相念，
奈此川陆迂。
尔庄复何许，
言在南浦隅。
同处百里间，
原田料相如。
欲往念未可，
抚时空郁纡。
聊咏寄吾志，
行哉归荷锄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1237','送石城李先生祭告阙里','顾清','明','簪绂清斋出禁林，
尼山秋色正萧森。
雷风岂有金縢警，
玉帛深悬黼座心。
此日羹墙亲仰止，
平生海岱快登临。
皇华不用歌离别，
并入新宫播雅音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1238','送汤尧德从事西川','顾清','明','好去皇华使，
相将万里行。
冰霜乌府节，
风物锦官城。
驿骑春山丽，
文书夜案清。
成名在年少，
乡社莫牵情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1239','九日招天章','顾清','明','蓟北江东路几千，
万重心事别三年。
官程算得无多日，
莫为渊明靳酒钱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1240','篁墩先生挽诗','顾清','明','理学龙门后，
文章太史公。
蜚腾当景运，
简注切渊衷。
载笔皇猷润，
传经帝业崇。
芬华沾草木，
名姓熟儿童。
琬琰镌磨遍，
川源涤溉空。
为霖须海内，
骑尾忽天东。
往事浮云改，
遗书列屋充。
掀髯怀指授，
擿埴叹颛蒙。
怅望仙衢远，
追攀逸驾穷。
南山秋月夜，
愁断白杨风。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1241','进士熊世芳太仆陆献臣先生令新建时所造士也奉使过家先生赋诗为其尊人寿要予同作','顾清','明','邂逅春风识凤雏，
又随群彦送轺车。
人看白发迎门日，
路是青云发轫初。
寿酒正宜桑落后，
舞衣犹带御香馀。
只应喜杀洪都尹，
亲见挥金为买书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1242','彭景武出守过家索诗为其尊人寿','顾清','明','振铎俱成绩，
悬车不待年。
青山同洛社，
红日在尧天。
名德存诸老，
勋庸付后贤。
庭趋看五马，
堂集记三鳣。
天与龄如鹤，
人知祖姓篯。
寿杯醲若露，
仙果大于拳。
俨雅吴黉像，
飘摇蠡浦船。
圣恩殊未艾，
玉帛伫登延。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1243','与原复饮时章宅夜冒雪归马上联句','顾清','明','灞桥诗思玉河东，
客散重城夜向中。
皓白暗欺云路月，
清寒时拂帽檐风。
十年江外孤篷远，
此夕灯前一盏同。
明发趋朝看晴景，
水精浑琢大明宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1244','次日夜酌用前韵','顾清','明','明朝尘海各西东，
莫惜清欢此夜中。
韵好不妨还用雪，
杯深那复畏冲风。
阅来世事常多感，
语到心期每自同。
飞矢夺枭成一笑，
插花犹忆醉南宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1245','次日夜酌用前韵','顾清','明','插花犹忆醉南宫，
尊酒三年此会同。
嘉绩已看书上考，
醉吟何惜到春风。
楸枰的历棋分角，
壶耳铿鍧矢跃中。
回首不堪凝望眼，
白云长满五湖东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1246','李叔渊父寿七十八','顾清','明','世味真应染指休，
太行千亩即菟裘。
天书有宠红裁锦，
春酒无时绿满瓯。
到处烟霞宜杖屦，
会心花鸟自林丘。
新年八十相将近，
更伴庄椿一度秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1247','御医杨信之故宅在玉河东涯有花竹山石之胜时行借居有作次韵','顾清','明','满城车马此堂閒，
招隐真堪赋小山。
花竹四时春不断，
琴书列屋昼常关。
开尊又喜逢青眼，
携手还思弄碧潺。
却怪相期数相迕，
早朝常隔殿西班。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1248','记十一月十九夜梦','顾清','明','夜梦飞行万山顶，
下视黄河如汲绠。
仰观明星万银饼，
青天倒垂碧瑶鼎。
大冶神光赤霞炯，
我暂窥之百夫警。
东北玄云突如猛，
上冲层霄失参井。
若华欲舒震方炳，
人间寂寥万物瞑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1249','送原复','顾清','明','阙下恩光动锦袍，
东行未觉故山遥。
云当驿路还停马，
酒溢春杯拟颂椒。
归日诸园花并发，
拜时双鬓雪全消。
何因暂作称觞客，
醉拥蓝舆过午桥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1250','江西傅生复立其远祖学士初庵书院于其乡体斋宗伯先生属为赋诗','顾清','明','前朝学士有闻孙，
能读家书习旧闻。
远道不辞来上国，
名山时为访遗文。
青毡次第还初观，
白马联翩向暮云。
遥忆精庐清夜永，
一灯还与列斋分。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1251','庭树着雪宛若梅花遣兴一首','顾清','明','朔风吹庭树，
岁晚益萧疏。
同云散微雪，
披拂下寒虚。
旖旎轻点缀，
芳华在须臾。
感此岁寒物，
念我田园居。
岂不信假合，
凭轩亦欣如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1252','冬夜德卿希大徵伯过访','顾清','明','良夜宾友集，
开尊坐南轩。
华月照两楹，
炽炭回春暄。
妙语入肯綮，
雅歌振清温。
共言会晤难，
菲恶愧盘飧。
且复延兹赏，
明发又尘樊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1253','雪中思南夫迥碧楼戏简','顾清','明','迥碧新题几首成，
无人曾见雪天清。
晚来剧有山阴兴，
忆著袁安未敢行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1254','除夕招王德馨','顾清','明','客舍长安岁屡迁，
屠苏明日又新年。
共君只向灯前醉，
免与儿童计后先。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1255','送僧还妙严己未斋居泰鲁山僧舍作','顾清','明','鹤城西北古招提，
十载长安梦不迷。
我正凭阑送归目，
君来卓锡话留题。
邯郸枕里三生速，
瀛海天南一雁低。
幽径小轩何日到，
碧流长绕画廊西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1256','再赋','顾清','明','夜宿端公房，
念与永公别。
青灯淡疏棂，
起坐见微月。
野鹤飞无定，
笼鹰动遭掣。
翩然思南翔，
神爽渺飞越。
精蓝古城隈，
台殿高嵽嵲。
幽房回曲径，
只尺人境绝。
公持桑下意，
我忆云门袜。
他年续清游，
还放西潭枻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1257','庚申斋居和钱世恒佥宪','顾清','明','频年僧室共郊斋，
引接多惭降等侪。
诗老渐看过大历，
语真时复到无怀。
好风先夕知清道，
朗月中天想燎柴。
明日衢尊又承庆，
还同既醉舞尧阶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1258','庆成燕和张南山','顾清','明','日高仙跸殿东来，
鹄立帘前候扇开。
舞队夹门参马象，
衢尊当陛绕云雷。
宠承天语亲教坐，
清列卿班独许陪。
连日玉河惊纸贵，
遍传新制咏台莱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1259','前题奉次侍读白先生韵','顾清','明','紫盖前头拥八鸾，
日华流彩映天颜。
升中庆衍三朝会，
供奉筵高六品班。
众乐送觞仙调缓，
诸番入队舞衣斑。
明朝齐和阳春曲，
谁复周京咏北山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1260','和孚若咏雪三首','顾清','明','微阳犹伏地中雷，
寒勒江云势未回。
啁哳渐多篱外雀，
浮沉频拨瓮头醅。
占年有喜先知麦，
拟赋无能且用梅。
晓起江山尽银海，
更容神女著芦灰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1261','和孚若咏雪三首','顾清','明','帘旌不动晓来风，
一刻瑶花满太空。
神用莫窥龙变化，
幽踪谁别兔雌雄。
先生东郭行应遍，
公子西园兴未穷。
便欲君王借千骑，
夜驱残甲出云中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1262','和孚若咏雪三首','顾清','明','书生裘褐自无兼，
雪意连旬未解严。
天上烂开群玉府，
人间那有却寒帘。
檐栖白凤遥分势，
阙映苍龙已没尖。
能赋只应输子建，
百篇信口不停占。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1263','再和煮雪雪山二首','顾清','明','玉铉金觞未许拈，
陶家风致我何嫌。
云英一化春无迹，
乳脚初翻火正炎。
真乐故应儿女笑，
清欢那得故人兼。
风窗细啜诗成后，
何物中边数蜜甜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1264','再和煮雪雪山二首','顾清','明','群儿痴绝不知寒，
搏雪中庭作幻观。
忽讶海波晨涌地，
更疑华顶夜凭阑。
斜侵院竹惊枝短，
清逼皋禽觉袂单。
不用孙龙较同异，
浮生只合此俱看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1265','并蒂瓜榴为钱世恒赋','顾清','明','瓜蔓远更硕，
榴房寒始红。
由来重嘉实，
不必当春风。
君看小山植，
朱碧秋重重。
间出或偶尔，
俱骈岂人工。
必有千里驹，
为君叶维熊。
如机云轼辙，
方驾凌紫虹。
善颂敢云我，
深培本缘公。
他年记父执，
无忽丹青功。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1266','元夕匏翁宅次马宗勉少卿韵','顾清','明','瀛海风光自一家，
衣冠此日共清华。
奉常彩笔飞千兔，
学士银屏簇万花。
看到春城无此盛，
传来郢曲拜君嘉。
宾筵喜气晨犹在，
散作东园五色霞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1267','再和匏翁韵','顾清','明','玉署东来第一厅，
元宵灯火灿银屏。
青云幸接诸公武，
白雪犹疑隔岁听。
江海几人思旧雨，
烟霄此地拱繁星。
宁知起草明光夜，
别有金莲彻晓停。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1268','遣天彝归省','顾清','明','遣汝宁容易，
高堂念久违。
书将锦字寄，
心傍白云飞。
干誉知吾意，
承欢羡尔归。
有怀言莫尽，
愁立到斜晖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1269','遣天彝归省','顾清','明','地是承家重，
年今抱子馀。
出门初托汝，
念别正愁予。
乡党先亲旧，
川途慎起居。
由来荣故里，
非必在高车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1270','遣天彝归省','顾清','明','吾家寒薄味，
汝顷及亲尝。
莫以花间日，
都忘叶上霜。
容仪师抑抑，
裘马戒扬扬。
自古谦恭子，
名高禄寿昌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1271','遣天彝归省','顾清','明','槿花随日殒，
松柏入云高。
树德由先世，
沾恩到尔曹。
亲贤衣袭麝，
从恶火消膏。
看取盘中粟，
耕耘亦甚劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1272','遣天彝归省','顾清','明','八年违故里，
此别更悬心。
伎俩人看汝，
承传始自今。
罗囊知不带，
缃卷亦时寻。
勿忘临行语，
风来伫好音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1273','和良金咏雪','顾清','明','白战功成四百年，
骚坛弧矢到君拈。
中天屡合鴐鹅阵，
小帐犹歌阿鹊盐。
弄影月娥回缟练，
散花天女敛柔尖。
不辞强步同高韵，
鸿迹春来几处添。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1274','送陈瑞卿还临清为其子天泽赋','顾清','明','驱车戒行迈，
复此官道周。
昔来冰雪交，
今还风日柔。
青骢系柳枝，
好鸟鸣相求。
冠盖罗四筵，
眷言各绸缪。
感此自难别，
况怀瓜葛忧。
清源雄剧地，
南北当襟喉。
选代苦不易，
眷毗良以优。
暂割骨肉恩，
且为旬月留。
长安富车马，
迟尔看来游。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1275','送东平守张元之赴黎平','顾清','明','东州棠树好，
又剖越南鱼。
地域衡潭尽，
星文翼轸馀。
长才须历试，
远俗贺宁居。
已有侏俪子，
循山候隼旟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1276','嘲卫景玉','顾清','明','闻说城西射雁归，
水清沙冷雁高飞。
将军不是无长箭，
为惜春风好羽衣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1277','题张通判春江载月图','顾清','明','月出大江平，
仙舟上国行。
回帆混天影，
发棹动春声。
远树光疑湿，
虚窗梦与清。
知君济川具，
聊复试初程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1278','送李徵伯之曲阜','顾清','明','远游君未曾，
发轫便东鲁。
平生仰止心，
一往了千古。
尼聃本通家，
复此缔姻与。
岂徒升门堂，
行且窥奥序。
君才自豪宕，
云梦口吞吐。
兹行信天假，
为尔辟襟宇。
冥搜穷日观，
旷览极鳌屿。
必有浩荡辞，
凌风振珩瑀。
念君千金躯，
垂堂有前语。
圣言本非外，
吾道足自取。
归哉慎勿迟，
高堂念风雨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1279','又次钱世恩韵','顾清','明','问道趋东鲁，
联舆有稚圭。
侍闱看乍远，
吟辖动还齐。
观海云浮地，
登山月傍梯。
预知篇翰富，
双从锦囊奚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1280','访陈时雨不遇次刘文敷韵','顾清','明','童子应门语自真，
锦囊何处觅阳春。
刘郎莫叹空归去，
更有斜阳独坐人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1281','毛閒翁百岁预寿','顾清','明','天子十四载，
昭阳纪灵辰。
间翁寿百岁，
弧筵启青春。
孙子天上归，
板舆奉慈亲。
扶携献春酒，
盛事倾海滨。
我明始驭宇，
元气会九垠。
历岁三十馀，
六合熙同仁。
翁实生此时，
所得固已淳。
葆真遗世网，
委顺随化钧。
自从结发来，
白首如一晨。
譬彼凌寒松，
本异凡卉伦。
动息有至理，
往来无杂宾。
閒居谈往事，
听者疑古人。
尝言十六七，
文皇当北巡。
金舆映朝日，
目睹天人真。
自攀鼎湖龙，
五拜重光新。
虽微海田变，
冠盖几湮沦。
念此劝翁饮，
无负尊前身。
南山晚更绿，
时菊长精神。
悠然东篱下，
想见无怀民。
愿得假羽翼，
杖几承清尘。
作诗预为寿，
转盻莺花瞵。
从今岁一篇，
积卷如车轮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1282','兵部侍郎杨公挽诗','顾清','明','乞归未许更承恩，
总为朝廷仗老臣。
帷幄尚纡千里策，
冰霜已瘁百年身。
中州清气还嵩洛，
后代公言属缙绅。
一卷昆山去思录，
便应谈笑离风尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1283','寿刘碧窗','顾清','明','半欹乌帽引清觞，
无柰斑衣绕膝长。
百岁好怀当此日，
一年佳节尚重阳。
黄花近竹深承露，
绿橘辞林浅带霜。
既醉有诗还自庆，
只应身健咏时康。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1284','题潞河别意卷','顾清','明','两字功名一剑歌，
舟航南北乱机梭。
夕阳沙上流连意，
只有青山见最多。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1285','春江漫兴','顾清','明','人间七贵五侯，
江湖蒻笠羊裘。
细雨鸳鸯沙上，
微风舴艋船头。
侬家五湖迤东，
此意于君更浓。
一派桃花流水，
十年马首西风。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_1286','送友人','顾清','明','清凉国里列仙儒，
坐拥溪山画不如。
黄卷上堂朝日后，
青衿分閤晚灯初。
晴岚捲翠遥侵户，
瀑水分光欲浸裾。
便欲从君寻九曲，
隐屏仙掌更萦纡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1287','送刘宗哲进士尹束鹿','顾清','明','长材宜德选，
望邑丽神州。
黄甲非身贵，
青箱本国谋。
弦歌深里巷，
雨露足田畴。
矫首西山月，
清光夜夜秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1288','孚若时章约九日广恩寺登高雨不及赴','顾清','明','白云观西红叶堆，
重阳有约携尊罍。
游人不出看白雨，
老僧闭户生青苔。
乾坤此景复几尔，
造化于物何廉哉。
未能骑马且独酌，
菊花许我明朝开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1289','戴溪山挽诗','顾清','明','海鹤东飞不记程，
溪山犹是昔时清。
城门傥有重来日，
应笑儿童白发生。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1290','戴溪山挽诗','顾清','明','末俗崎岖巧智多，
纷纷夭札柰愁何。
青山不尽思公意，
落日空闻伐木歌。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1291','赋栖翠楼送曹良金出使归省','顾清','明','群山绕湖湖绕山，
高楼突起湖山间。
湖光如蓝山如黛，
云近百里趋凭阑。
主人不出日高坐，
笑弄烟雾招云鸾。
云鸾空飞渺无迹，
但见苍苍竹树相回环。
芳荪小松亦何意，
点缀几格娱清閒。
大郎新归自天上，
春衣五色宫花斑。
楼前拜舞楼上醉，
山水亦似回欢颜。
烟凝不知晚色改，
潦尽更觉湖波宽。
登高作赋远莫致，
目极吴江枫叶丹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1292','送罗允恕归省','顾清','明','满庭兰玉翠交加，
近日西江更几家。
累叶书香传祖父，
同时科甲际亨嘉。
三秋别思初惊雁，
五色宫袍重染霞。
为问山中閒太史，
也应飞梦向东华。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1293','题石田春江钓鱼图','顾清','明','重江迢递水烟通，
天设沧洲著钓翁。
返照入山迷紫翠，
平林过雨杂青红。
閒边岁月真输子，
忙里莺花正恼公。
为问中流容点笔，
扁舟画我载泠风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1294','题竹送阮大经还金陵','顾清','明','十载江东忆旧游，
竹林斜日坐深秋。
长安道上红尘满，
赖有清风消客愁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1295','谭雅祥使归寿母','顾清','明','皇华夹道拥归装，
喜气遥看满北堂。
天上瑞云垂五彩，
人间佳节傍重阳。
早时贤范熊丸在，
再世诸孙玉树长。
七十一峰青在望，
若为登拜捧霞觞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1296','罗先生归田八景为赋其四','顾清','明','云表三青巘，
萧生昔栖迟。
缃素久已散，
荒台仍故基。
落日循岭圃，
逍遥面崔嵬。
当年选幽胜，
花竹绕阶墀。
千龄亦未远，
俯仰有馀悲。
勿讶岩居子，
缅想希安期。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1297','罗先生归田八景为赋其四','顾清','明','双溪走岩麓，
上有真仙居。
萧爽荫珠树，
虚閒开玉除。
先生读易罢，
杖屦或来于。
东寮紫鸾笙，
西馆青霞裾。
招摇弭绛节，
想象凌清都。
日暮篮舆去，
天风送步虚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1298','罗先生归田八景为赋其四','顾清','明','高榆荫灵境，
秩祀岁有虔。
烹羊击我鼓，
老稚走纷然。
落日更起舞，
酣歌间骈阗。
少壮远行役，
投老归农田。
乡邻既无故，
孙子亦多贤。
但愿岁常稔，
听此终馀年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1299','罗先生归田八景为赋其四','顾清','明','梅花搅我梦，
欹枕五更初。
头陀闵群昧，
霜金吼桐鱼。
一击尘梦醒，
再声灵襟虚。
须臾万籁动，
鸣鸡遍前墟。
起坐视檐隙，
明星犹在隅。
却忆长安日，
整冠趋朝车。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1300','送刘景星教肥乡','顾清','明','常日黄梁说梦游，
明朝匹马度邯沟。
山连王屋排空下，
云在天门抱日浮。
枕里卢生迷岁月，
皮间季野有阳秋。
丈夫功业时来建，
肯向青藜叹白头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1301','孚若出示乃兄九三先生瑶草篇敬题其后','顾清','明','达人遗世网，
心与元化冥。
高居养灵和，
土石被华精。
英英庭下草，
罗骈不知名。
明冰比皓质，
文玉擢修茎。
群芳不敢伍，
煜煜扬翘英。
我愿采掇之，
恐是玉山粳。
持以莳千亩，
媲彼尧阶蓂。
路远伤后时，
怅望吴峰青。
载歌小阮词，
感我金兰生。
青云果善颂，
白雪宛遗声。
馀芳倘许拾，
相携泛蓬瀛。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1302','为卢悦清题竹四首','顾清','明','卢郎老益清，
正似雪中竹。
岁寒林下游，
还许王猷续。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1303','为卢悦清题竹四首','顾清','明','雷雨过前溪，
竹色犹黯惨。
泥中有龙孙，
戢戢露头颔。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1304','为卢悦清题竹四首','顾清','明','风吹楚云去，
一半在君山。
帝子不可见，
江空闻佩环。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1305','为卢悦清题竹四首','顾清','明','凌晨步东林，
满地散珩瑀。
举头见朝阳，
傍有青鸾舞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1306','沈石田画杨君谦僧普泰雪夜谈玄图','顾清','明','石田山水此第一，
仪曹鲁山迹亦奇。
月明满天雪在地，
听取两翁无语时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1307','为定默然题吴僧画兰二首','顾清','明','猗猗芳兰，
在彼幽谷。
孰为我徒，
清泉修竹。
清泉涓涓，
修竹苍苍。
荪也可人，
蔚乎相望。
明窗若空，
左右图史。
永言诸君，
乐自今始。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_1308','为定默然题吴僧画兰二首','顾清','明','吴有高人，
得笔三昧。
洒墨飞空，
坠不沾地。
化为幽兰，
殊妙特妍。
相所于归，
繄定默然。
煜煜者兰，
岩岩者石。
咨尔丛林，
兹焉作式。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_5_1309','山水小景','顾清','明','江柳青青带薄烟，
鸬鹚飞尽水如天。
幽人看得青山熟，
一任东风拍钓船。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1310','送费千户袭职还松','顾清','明','流水平林带郭斜，
将军门巷野人家。
百年勋荫馀乔木，
三月春风想落花。
何日燕游还此地，
向来谈笑即抟沙。
王师未斩楼兰首，
看尔腰间似莫邪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1311','和许启衷给事春日','顾清','明','细雨閒门客到稀，
偶临池水见晴晖。
浮萍本是风中絮，
争得还随柳絮飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1312','即事和前人','顾清','明','新出燕雏不记归，
清晨捲帘到夕晖。
苔痕渐于细雨长，
榆荚正得斜风飞。
北边稍喜烽火息，
南国却嗔鱼雁稀。
赖得相期有钟子，
未应终遣壮心违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1313','邃庵','顾清','明','达人隐城市，
端居穆幽深。
虽当车马交，
而无尘土侵。
侧径入迤𨓦，
层轩递明阴。
萧森间水竹，
窈窕想云岑。
朝回隐几坐，
幽意宛山林。
想当缔构初，
岂有远世心。
抗席展图史，
分庭盍朋簪。
覃恩穷海岳，
清言振璆琳。
譬彼九皋唳，
风听彻重阴。
鸿飞二十载，
俯仰成古今。
高云复南逝，
何时续幽寻。
行窝倘有作，
千里续遗音。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1314','送杨承家','顾清','明','邃翁天下奇，
之子亦超越。
琅玕映珊瑚，
文采争焕发。
识君虽未几，
一见眸已豁。
方期托芝兰，
告别何仓卒。
江东名胜地，
京口豪隽窟。
槐黄逼秋期，
腹笥撑突兀。
三杯脱宝剑，
百步挽明月。
穿杨何足奇，
会见石羽没。
清江柳方绵，
紫陌花未歇。
晴空正无云，
万里见孤鹘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1315','送宫谕李子阳先生赴南京太常少卿','顾清','明','典学东朝旧史臣，
南台礼乐荷新恩。
百年景运当熙洽，
三代遗文入讨论。
花竹竞誇官署好，
江山深拱帝京尊。
只愁未了閒居赋，
又被东风催北辕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1316','刘舜卿祖父母挽诗','顾清','明','极目襄垣道，
萧萧落叶秋。
人犹避骢马，
梦已隔丹丘。
比穴看明镜，
同归想玉楼。
馀芳知未歇，
孙子在瀛洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1317','沈廷用以尺籍事来京却归赋别','顾清','明','老去江湖气未消，
欲将长剑倚云霄。
十年几作登楼梦，
一笑元非折简招。
枥下尽馀宛騕袅，
军中谁是霍嫖姚。
浩歌一曲指归路，
白鹤城西又晚潮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1318','送张信卿知归德州','顾清','明','短亭官柳下，
长路酒杯前。
待解薰风缆，
频回落日鞭。
龚黄新宠命，
梁宋古山川。
去去应传得，
歌谣满日边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1319','送陈玉畴提学南畿','顾清','明','圣学久不讲，
斯文日陵夷。
纷纷事佔毕，
青黄互镌追。
岂无豪隽人，
柰此场屋縻。
离章务迎合，
出意追新奇。
公言著简册，
启彼捷径岐。
坐令青衿子，
释耒拾秉遗。
所操谅如此，
即事吁可知。
陈侯儒林彦，
宪府久声驰。
以彼冰檗操，
树此文章麾。
色笑春雨霁，
槚楚秋霜威。
矧伊根本地，
允矣列郡规。
指挥苟有向，
风行草争靡。
走也章句士，
久堕荆棘蹊。
前瞻若有见，
内顾靡所施。
六籍本大道，
旁搜竟奚为。
赠言剧深愿，
迥澜此其时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1320','石邦秀侍御再按陕西乃弟翰检先生索赋','顾清','明','又见皇华映陕郊，
遗民应念使君劳。
关河尚有风尘警，
弹压还须在绣袍。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1321','石邦秀侍御再按陕西乃弟翰检先生索赋','顾清','明','青云双凤立朝阳，
䌽笔春生白简霜。
心识西行非远别，
夜来绿草满池塘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1322','沈士登初入学梦人诵诗有细丝曾钓海鳌来之句是岁集选得富春丞乃子陵隐处因赠此诗','顾清','明','梦里金鳌忆细丝，
桐江只在富春西。
久知万事皆前定，
肯向浮生叹不齐。
坐上溪山明画鹢，
人间岁月等醯鸡。
两株松外千竿竹，
吟得新诗到处题。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1323','蒋济民自光禄署丞调主靖安簿满考入京乞致仕赋以送之','顾清','明','黄龙浦南云水乡，
八月鲈鱼三尺长。
远游不柰乡思苦，
归去正及秋风凉。
内朝供奉参鹭羽，
西江抚字留甘棠。
丈夫事业无小大，
看取老圃寒花香。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1324','王师仁少宰挽诗','顾清','明','曾瞻旌旆立江边，
过眼棠阴二十年。
黄阁盐梅閒老手，
青山松桂富新篇。
人高晚节踰三让，
帝有馀恩贲九泉。
拟奠生刍不知处，
碧云无际海南天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1325','王思德寄歙研吴笺','顾清','明','歙样新传胜紫琳，
函封远自柏台深。
隐光似截波间玉，
涵润长流月畔金。
笺素一时争焕发，
烟霞当日记追寻。
西江使节冰霜重，
泚笔銮坡伫好音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1326','东阙池上作次杭世卿吏部韵','顾清','明','灵沼溶溶雨欲飞，
水东林苑望中微。
云光倒涌金堤去，
寒色遥从锦树归。
诗出镐京歌在藻，
地因龙首忆承晖。
君王自是稀游衍，
鱼鸟无从识画衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1327','李徵伯挽诗','顾清','明','鸣雨送残夜，
青灯黯无光。
坐念绝代人，
今古永相望。
美德岂足恃，
令我初志荒。
忽复疑梦假，
衾襚已充箱。
掩涕不忍视，
起步空徊徨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1328','李徵伯挽诗','顾清','明','忆昨听鹤亭，
与君初接言。
神交四千里，
从此成弟昆。
诵我避水书，
意气蔼兰荪。
十年事几变，
俯仰犹旦昏。
已矣萧朱心，
伤哉复谁论。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1329','李徵伯挽诗','顾清','明','间岁苦离索，
旧游若云萍。
与君每共叹，
忍复此长瞑。
元龙按近甸，
旦暮涕已零。
遥遥两汪子，
此信何时聆。
虚檐团云影，
永夜双烛荧。
清欢可复继，
即此成千龄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1330','李徵伯挽诗','顾清','明','数短得气清，
才高与时龉。
黄鹄当摩空，
岂复须再举。
乃知摧折意，
造物忍如许。
空梁飘素帷，
幽架落残楮。
矫首青云衢，
槐黄泪如雨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1331','李徵伯挽诗','顾清','明','元宾既无禄，
长吉亦早亡。
古人泪未尽，
今子重夭伤。
憎能岂天心，
念此谁纪纲。
䌽㡛饰文木，
袭君锦绣肠。
下入三泉底，
千秋长閟藏。
惟应箕尾际，
永夜腾光芒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1332','李徵伯挽诗','顾清','明','生死犹寤寐，
昔人屡言之。
梦君执我手，
明言两无疑。
问死恨草草，
怀存亦依依。
及论重来理，
调笑名我痴。
肯綮出妙语，
徘徊指还岐。
幽林犹彷佛，
高垄俨崔嵬。
永念结沉痛，
萧条谁与归。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1333','松岭长春为周淳甫母寿','顾清','明','匡山回望翠成林，
春色分明此地深。
雨露独承千载润，
冰霜不异一生心。
高标彷佛丹梯外，
佳气氤氲碧涧浔。
何日潘园奉周览，
东风十里步清阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1334','张廷肃宪副致仕归中途得二郎子德捷报','顾清','明','先生绣斧辞荣日，
令子青云擢秀年。
宦辙九霄馀熟路，
书香一脉是真传。
傍阶霜菊深承露，
夹户星榆欲造天。
惆怅无因接宾燕，
碧山回望渺风烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1335','画马为内学生题','顾清','明','毵毵嫩绿垂杨短，
冉冉晴沙御堤软。
骅骝行惯稳不惊，
圉人徐牵不教远。
飞黄食料三品丰，
青丝络首飘风騣。
曾见沙场征战苦，
方知此物是真龙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1336','冬至谒陵次允升太史送行韵','顾清','明','出门愁望北风骄，
百里园陵亦未遥。
馀雪印堤尘不动，
诸山迎日雾全消。
松楸夹道如前日，
冠佩中天限此宵。
想得群仙会朝罢，
并瞻云物庆丰饶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1337','雪山次吴宁庵先生韵','顾清','明','夸娥失喜巨灵号，
腾六平分缩地劳。
孤牖忽惊银海立，
两峰谁论玉山高。
嵚岩似欲生云母，
融液犹堪瀹涧毛。
为报朝阳莫相妒，
先生吟笔正翻涛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1338','雪山次吴宁庵先生韵','顾清','明','未雪风姨已怒号，
为山无乃雪重劳。
人间牟麦明年富，
坐里蓬婆一夜高。
目眩有时还拄笏，
神游他日想寒毛。
阳坡数曲如溪涧，
应待春风送海涛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1339','良金秋官录囚江右有发其同官不谨事者所司衔旧怨窜君名其中调东昌督马通判众知其诬而莫与辨也诗以送之','顾清','明','东观图书共昔年，
西曹风月许联编。
论心合在青云上，
抚事空嗟白璧前。
晓日鹓鸿犹尺只，
春风駉駜又三千。
池鱼塞马俱休论，
且读南华第一篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1340','壬戌元宵应制绝句八首','顾清','明','楼前灯火合彤霞，
云里箫韶引翠华。
散出黄柑齐拜赐，
玉皇遥在七香车。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1341','壬戌元宵应制绝句八首','顾清','明','两宫慈寿极尊亲，
圣主承欢一万春。
放出金莲长不谢，
扶来玉辇静无尘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1342','壬戌元宵应制绝句八首','顾清','明','银幡赐了敕观灯，
次第风光满镐京。
看到筵前鸠拂舞，
九农春事已关情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1343','壬戌元宵应制绝句八首','顾清','明','华星宝月满长安，
绣屋金釭夜未阑。
遥望千门起庭燎，
尚宫先辇奏回銮。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1344','壬戌元宵应制绝句八首','顾清','明','紫坛回仗溢天津，
特敕金吾弛夜巡。
为有蕃禧助阳令，
六街花柳一时新。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1345','壬戌元宵应制绝句八首','顾清','明','宵旰忧勤十五年，
鳌山灯火亦初筵。
小臣未识鱼龙戏，
中宴先歌蟋蟀篇。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1346','壬戌元宵应制绝句八首','顾清','明','紫檀红蜡夜频添，
万岁声中乐未厌。
华月正当云母障，
微风莫动水精帘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1347','壬戌元宵应制绝句八首','顾清','明','乾清前殿夜将分，
万烛交光绚䌽云。
传敕明朝散灯宴，
词臣好进劝农文。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1348','后二日有旨再赋律诗四首','顾清','明','乐岁逢春物物宜，
圣人行乐是乘时。
天垂玉烛三千纪，
地涌金莲十万枝。
星阁捲帘红日近，
虹桥按曲䌽云迟。
愿因欢庆思幽隐，
更法光明事缉熙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1349','后二日有旨再赋律诗四首','顾清','明','千灯高列奏宫悬，
五凤齐飞拱御筵。
春到上元真富贵，
月临双阙正清圆。
甘泉西北长无警，
瀛海中间大有年。
暂弛金吾三夕禁，
未妨宣室九宾延。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1350','后二日有旨再赋律诗四首','顾清','明','好景新春属上元，
蓬山排日会群仙。
丛金间玉灯千树，
翔凤回鸾月一天。
直以升平留燕赏，
肯将光景付流连。
䌽云遥望笙歌合，
知奏邠风第几篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1351','后二日有旨再赋律诗四首','顾清','明','紫皇宫阙夜通明，
飞阁回廊白昼行。
宸极本同天下乐，
霓裳不度月中声。
河山表里归全盛，
云物光华溢太清。
愿祝圣人千万寿，
年年灯火看升平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1352','许百户从军普安州至潞渚卒时其子鲁从予游赋此吊之','顾清','明','拟作燕歌赠粤行，
剑棱中断不成声。
一天冻雨红旗敛，
万里炎烟碧草横。
假息忍看徵侧在，
裹尸谁吊伏波营。
伤心最忆湖阴路，
垂柳閒门几送迎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1353','郊行忆徵伯与德卿希大联句','顾清','明','故人丘垄望中孤，
古木荒村旧路纡。
野奠有怀空酹酒，
交游无兴更携壶。
人间流落文章在，
梦里依稀涕泪枯。
此日九原如可作，
问君曾记玉楼无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1354','郊行忆徵伯与德卿希大联句','顾清','明','把笔英姿在眼中，
笑谈曾共此堂东。
乾坤苍莽游何处，
花雪追随梦未终。
价重连城惊毁璧，
气消神骏想追风。
悲歌亦是伤春调，
却与伤春调不同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1355','郊行忆徵伯与德卿希大联句','顾清','明','石桥归路又斜阳，
旧日经行宛未忘。
何物山川收间气，
向来星斗避寒芒。
青乌未卜前冈吉，
白雪空传下里章。
一滴九泉今定到，
骑龙休问白云乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1356','送道士周翠岩还松江','顾清','明','飙轮不到海东头，
梦里三山日夜浮。
归去有时应驾鹤，
别来几处见乘牛。
风清晓殿思金磬，
云淡春空送䌽辀。
借问赤松千载后，
幅巾还许伴清游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1357','送萧指挥还金山','顾清','明','将军承宠出明光，
归骑东风满路香。
家有六韬藏虎豹，
身堪百战扫豺狼。
北来烽火边无警，
南去波涛海不扬。
细柳绕营春日静，
雅歌谁与共壶觞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1358','寄高曾唯','顾清','明','千里南河入望赊，
美人有约赋皇华。
乡音不远经冬雁，
云路常瞻八月槎。
官好水曹清彻底，
名高玉树净无瑕。
北堂春日花如锦，
时向公馀奉小车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1359','送吴汝玉下第用己未春韵','顾清','明','建业西风忆系舟，
燕台此别又经秋。
也知和璧终传世，
恨向荆江复倚楼。
且莫临岐伤远道，
要须游刃视全牛。
长安春色年年似，
一样王孙烂漫游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1360','送百户徐钦袭职还松江','顾清','明','曲墙垂柳荫清池，
十载高门路不迷。
尽说柏舟同节苦，
惊看玉树与云齐。
恩光晓日瞻龙仗，
行色秋风入马蹄。
拂拭家藏旧弓剑，
从今步步上丹梯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1361','赋蟠桃图为张时震父母寿','顾清','明','玄洲髣髴海东涯，
海岸蟠桃大比瓜。
画入彩缣疑着雾，
望迷仙苑欲生霞。
稀年令德真相配，
紫府丹台别是家。
我欲金壶借馀墨，
一枝并写杏园花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1362','维扬魏文璧工诗能琴善画幅巾布袍游京师萧然不与尘土杂将还与德卿御史各赋诗送之','顾清','明','清沟绿树绕江都，
树里人家画不如。
舣棹十年同过鸟，
临流此日羡閒居。
乾坤老眼丹青在，
江海神游梦寐馀。
西北月湖连甓社，
几时携手弄明珠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1363','题扇寿爱蔬吴先生尊人','顾清','明','江海归来一幅巾，
东风八十四回春。
日长勘罢参同契，
坐对青山即故人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1364','泰和萧生将赴临汀驿留三日为予写真赋此为赠','顾清','明','本自烟江坐钓矶，
春风强使著荷衣。
不知面目从来假，
更与萧郎问是非。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1365','泰和萧生将赴临汀驿留三日为予写真赋此为赠','顾清','明','南望临汀路八千，
皇华四牡日纷然。
江湖或有商岩相，
倘可因君送上天。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1366','送张晦夫长史之沂州','顾清','明','犹记征车逐后尘，
离亭回首十经春。
衣冠稷下谁公右，
礼乐河间合此新。
长日横经当便坐，
有时纡锦见乡邻。
绿杨骑马城坳路，
应向西风忆故人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1367','还金行为叔武郎中赠济南姚龙','顾清','明','故人留金儿不闻，
故人已死人谁云。
昨日结交今有变，
何况天涯生死分。
延州挂剑事已矣，
济南高风见吾子。
金还故人事则已，
事吾当然非有以，
江海千秋歌义士。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1368','送宁庵学士赴南院','顾清','明','紫清仙吏亦分曹，
瀛海晴虹隔翠涛。
词下掖垣花欲动，
讲回前殿日初高。
城临秋水迎飞盖，
阁倚春风想运毫。
为谢白云荆渚上，
楼船不似北河劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1369','送盛春雨还吴','顾清','明','未来消息满长安，
小住何妨趣驾还。
海内正悬春雨望，
山中谁放夏云閒。
每寻燕语多高论，
转觉鸿飞不易攀。
翘首阊门烟月路，
几时携酒扣玄关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1370','哭次儿天叙寄两弟五首','顾清','明','孤根托浅土，
所赖众叶扶。
斧斤日相寻，
谁能不伤枯。
根伤叶乃落，
叶落根转孤。
不知天地仁，
根也真何辜。
仰天天苍苍，
扣地惟黄垆。
有语不可道，
泪下如倾珠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1371','哭次儿天叙寄两弟五首','顾清','明','虎狼亦爱子，
乌鸟亦恋雏。
生子不能庇，
悲恨当何如。
伯也归故乡，
漂泊无宁居。
仲子最孝谨，
性复爱诗书。
百方挠其中，
一病辞寒庐。
垂死与母言，
血泪沾衣裾。
沈思不忍道，
命也有生初。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1372','哭次儿天叙寄两弟五首','顾清','明','养蠹伤桂根，
击鼠伤定盆。
盆伤鼠故在，
桂死蠹转蕃。
明明世间事，
瞀乱与谁论。
吾儿曾闵性，
至死无馀言。
念之益我痛，
作诗愬烦冤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1373','哭次儿天叙寄两弟五首','顾清','明','十年住京国，
日与忧患随。
逢人得家信，
十书九攒眉。
芝兰日以瘁，
荆棘日以肥。
宿累本在我，
馀殃及吾儿。
种树已结子，
养雏已能飞。
一朝委尘土，
烦冤当告谁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1374','哭次儿天叙寄两弟五首','顾清','明','汝母初来时，
骨肉共团栾。
依依恋微禄，
幸尔免饥寒。
负乘知有愧，
酷罚倘可宽。
弱女在旅殡，
十年犹苦酸。
如何复及尔，
中道摧羽翰。
萧条古僧房，
兄妹两孤单。
疏窗对寒雨，
念之伤肺肝。
何当归尔魂，
恸哭淞水干。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1375','乔时章除瑞安侯训导侯实慈寿宫弟时章内翰师召子也','顾清','明','长乐清风动内朝，
汉宫阴马宋高曹。
外家多福遵慈训，
西塾延宾得隽髦。
永日青襟环讲坐，
有时红烛对挥毫。
相看益重酬恩地，
身是銮坡旧凤毛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1376','南有蛮为阴子淑宪副作','顾清','明','南有蛮，
穴都匀，
反乎覆，
傲以嚚。
反噬厥主戕我民，
鸱张四顾掠且焚。
繄阴侯，
算若神，
戢我武，
绥以文。
绥之弗来歼乃群，
蛮破胆，
伏以驯。
释不问，
弘我仁，
豕入其笠吾谁嗔。
呜呼普安城，
亦吾人，
一不戒，
血成津。
胡为不遣当使君，
呜呼胡为不遣当使君。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1377','程德望祠部于书室前凿池作亭秋望落成而正之内翰适至因名其亭曰登月室曰聚奎要予同赋','顾清','明','方塘开我前，
明月出我东。
仙人骑鹤来，
憩我亭之中。
调笑弄月影，
徘徊吟天风。
夜久月渐高，
光满池若空。
遗我丹桂枝，
自携白芙蓉。
飘然凌风去，
千秋怀德容。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1378','程德望祠部于书室前凿池作亭秋望落成而正之内翰适至因名其亭曰登月室曰聚奎要予同赋','顾清','明','文星近东壁，
煌煌照图书。
千秋五纬聚，
煜煜联明珠。
岂徒兆文运，
皇步跻亨衢。
美哉君子堂，
春风迓簪裾。
高会既有以，
嘉名谅非虚。
君看庭下人，
星斗罗襟襦。
高朗自今始，
太史徵明符。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1379','送汤千户还吴','顾清','明','留守将军金虎符，
明光传警肃周庐。
新恩宠拜双龙阙，
别路光生驷马车。
投笔书生终刻印，
入关童子已抛繻。
楼船八月吴江燕，
谁共雕盘荐玉鱼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1380','宗伯傅体齐先生挽诗','顾清','明','两朝名德重儒绅，
西掖南宫列近臣。
典礼百年归考论，
文章四海入陶钧。
春风遽撤朝回座，
夜月徒伤画里神。
地下青溪定相待，
霓旌先后想纷纶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1381','送顾汝馨','顾清','明','通家人物旧知名，
十载相看倍眼明。
捧檄君方感毛义，
思贤我复到颠闳。
青云未觉流芳远，
白发多应别路生。
无限羁愁与乡思，
并先秋雁过吴城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1382','舜臣以诗慰问次韵','顾清','明','故人千里寄新诗，
正是愁人阁泪时。
黄鸟有情依灌木，
碧萝无命托松枝。
寻思往事多艰阻，
却悟深盟是祸基。
长叹一回还自慰，
重哀宁望老天知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1383','卫景玉生辰席上作','顾清','明','我生于君后三算，
我及君游已十年。
浮世升沈几搔首，
高秋风物又登筵。
银钩欲转薇花月，
金兽初腾柏子烟。
他日仙班只今定，
丹梯须让海鸥先。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1384','戏简王汝楫','顾清','明','短日西风木叶飞，
游人无处不思归。
连廒百室如云峙，
肯念吴儿未授衣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1385','方石先生季父逸老以宝庆守致仕先生名其居曰悬车旧第宝庆殁先生有诗命次其韵','顾清','明','执鞭无地候巾车，
逸老编中识面初。
露冕犹闻下江汉，
云山谁与画衡庐。
青槐古柏京尘远，
寒日西风宰树疏。
莫向方岩诵哀些，
竹林回首正欷歔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1386','题画鹊','顾清','明','朝阳欲上万年枝，
九色光芒射绀衣。
昨夜银河济灵驾，
露华寒湿未禁飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1387','题花鸟二绝','顾清','明','边鸾不起林良老，
海内丹青合到谁。
晴日窗间弄沙鸟，
楚烟湘树不胜思。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1388','题花鸟二绝','顾清','明','黄凫不食聚沙觜，
芦鸡相将踏清泚。
飞燕翩翩软风里，
江乡春晴景如此。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1389','五马行赠宋舜和之广信','顾清','明','翩翩五马城东隅，
车载两轓兼隼旟。
雪晴尘清马蹄健，
长鸣跋地当云衢。
汉家太守唐刺史，
握节专城殿千里。
古来青史亦吾人，
肯使诸公尽专美。
西江望君如望云，
驱车跃马无逡巡。
闻道群偷先出境，
已识新侯是宋均。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1390','送赵起龙兼简其季父济民','顾清','明','白鹤城西是旧游，
赵家亭馆菊花秋。
乡关客邸劳魂梦，
风物天涯惜去留。
高隐久应忘世味，
美材还合树勋猷。
竹林会语从容地，
真诀参同可再䌷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1391','送吴克常南京光禄监事','顾清','明','通家亲戚故乡人，
临别相逢意转亲。
晤语留连下城日，
宦程迢递促车尘。
高冈合止冲霄翼，
浅水宁容纵壑鳞。
朱雀乌衣壮游地，
为君惆怅十年春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1392','送朱文宿谒告东还','顾清','明','天寒游子正思家，
手把离觞感物华。
乡梦五更犹禁漏，
归轩千里即仙槎。
庭萱屡报东风鹊，
宫锦争看上苑花。
同学故人应问我，
绿莎春雨候江沙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1393','十二月十一日进会典','顾清','明','黄盖亭亭拥赭函，
箫韶声起殿东南。
百年盛事中天见，
八圣深仁薄海覃。
尧典合从虞史润，
周官不假汉儒参。
愿言善述光前训，
竹帛千秋作美谈。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1394','明日宴礼部','顾清','明','大官供帐称殊恩，
队舞番歌出内园。
礼肃上公尊奭旦，
书成新典迈虞轩。
雍容不止过三爵，
披览何由望九阍。
经幄小臣沾醉甚，
但歌天保对尧尊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1395','送沈继昌','顾清','明','丝纶阁里凤凰毛，
五彩朝阳映碧霄。
出使口衔天语重，
拜辞衣傍御香飘。
里门驻节惊梅蕊，
驿路逢春问柳条。
为忆圣情深眷倚，
肯耽山水后趋朝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1396','戴宝之祖韶轩翁挽诗','顾清','明','西风林壑晚凄其，
叹息仪刑不可追。
天地并临刲股夕，
里闾相泣盖棺时。
谋深丰芑金楼册，
心切苞桑白傅词。
翘首玉辉原上路，
几人下马读穹碑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1397','廿一日夜坐忆亡儿','顾清','明','清夜长吟动四邻，
吟成人静独沾巾。
不知此段缠绵意，
天地相关复几人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1398','廿一日夜坐忆亡儿','顾清','明','视不成形举目存，
青灯一盏近黄昏。
彭殇竟是谁分出，
妄使瞿昙欲断恩。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1399','茅山书屋','顾清','明','小茅山下三间屋，
养默斋中万卷书。
竹帛散馀嗟往事，
海桑迁后复吾庐。
檐头树色低侵帙，
门里泉流曲贯除。
想见日长佔毕倦，
时来凭槛数游鱼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1400','封知府叶公挽诗','顾清','明','百岁閒身五马封，
向来江海复谁同。
门阑庆建看诸子，
兄弟椿津对两翁。
身后诗书方自远，
眼前林壑便忧空。
碧山烟雨淮南路，
尚想扁舟理钓筒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1401','次韵启衷给事病后见寄','顾清','明','宋玉杨朱各有悲，
杜陵曾借草堂资。
由来造物多儿戏，
毕竟风流是我师。
梦里青山休作意，
眼前黄卷足新知。
春风几日开西馆，
聊欲携尊问所疑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1402','赋僮仆欢迎贺叔武尊人都宪致仕','顾清','明','陶令还家日，
欢迎走仆僮。
人间长见画，
林下复添公。
物色殊相近，
遭逢夐不同。
飞腾会明盛，
扬历践昭融。
苕水犹遗爱，
横山早息戎。
全归渠亦喜，
远涉路何穷。
指点桑榆茂，
传观里巷空。
挽衣参稚子，
扶杖杂村翁。
黄菊霜前约，
青山雨后功。
行藏自吾道，
消息任天工。
晚景看如此，
皇恩信有终。
丹青如解写，
何羡洛城东。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1403','题学生画','顾清','明','枝头野花红欲语，
草绿犹带朝来雨。
狂蜂浪蝶不自持，
下上东风作容与。
画师好手亦难逢，
陶成已老况孙龙。
南薰殿里和丹粉，
犹堪一笑解天容。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1404','送史景贤同知考绩','顾清','明','君侯北州英，
淳直自天予。
青云二十载，
安驾何容与。
朅来东吴郡，
已复三刈黍。
庞统足方展，
休徵名日举。
于焉朝天行，
万里看凤翥。
尧门开九重，
舜目周万宇。
才良合高位，
疲瘵念慈父。
舟行望不尽，
目断斜阳渚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1405','月桂秋香送刘生还宜春应举','顾清','明','月桂生月宫，
一月一开落。
逢秋气弥盛，
芬馥遍寥廓。
世人望影空裴𧙪，
刘郎自是神仙才。
兄弟相携月中去，
正值秋风花烂开。
嫦娥玉手亲折赠，
双枝香满黄金台。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1406','姚平夫挽诗','顾清','明','完节非今日，
清心自昔年。
由来孤竹操，
不逐艳阳迁。
旅殡烦僚友，
归装富简编。
尚馀潜德在，
合并鲁男传。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1407','华听竹挽诗','顾清','明','好在延祥竹，
秋风日日情。
幽人不复到，
虚节为谁清。
干蛊名无愧，
贻谋事有成。
乡邦听舆论，
合附孝门铭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1408','次韵王用常下第写怀','顾清','明','漫说龙蟠与蠖伸，
亨衢何遽不为迍。
才如贾谊宁终斥，
美若陈平岂惯贫。
岐路只于忙里错，
头颅须识本来真。
眼前掬水翻荷地，
一笑相看剩几人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1409','近为儿侄辈屈澄夫先生于小园东曙有诗次韵二首','顾清','明','久知矾弟忆梅兄，
又见新篇月露呈。
虚馆可能留国士，
旧游端喜袭香名。
骚坛此日初申令，
棋社何人敢订盟。
尽有残膏被来裔，
未应飘泊叹浮生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1410','近为儿侄辈屈澄夫先生于小园东曙有诗次韵二首','顾清','明','安车久不到岩阿，
水部无人复姓何。
秋浦白云天际远，
夕阳红树屋边多。
笔精又展郇公帖，
才钝愁闻郢客歌。
眼底桐枝未盈把，
几时亲见十寻过。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1411','初至芸轩宅夜坐联句','顾清','明','良夜城南旧草堂，
十年重继此灯光。
文章翰苑声华重，
懒散林泉鬓发苍。
庭树看于前日大，
酒杯偏向故人长。
出门翘首梅花月，
又见天心转一阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1412','次高进之韵','顾清','明','读书思力行，
挟策几凝想。
纷纷事酬对，
顾影数离像。
譬彼旱岁槔，
久矣困俯仰。
知言何敢云，
有愧钟期赏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1413','数日不过东园澄夫先生有月桂诗见示且归功于封殖之厚次韵奉答时腊月朔也','顾清','明','看花久不到墙东，
不道寒丛也自红。
培殖可能符善颂，
故应嘉气与君同。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1414','子南兄弟联取科名此予所素期而果不缪者计偕北上酌酒赋诗皆平居游处言语精神之实不复以文而故人情厚者当自慨然也','顾清','明','短屋疏帘野水边，
几宵灯火共周旋。
联飞本拟看三凤，
吉梦先教协两犍。
远道风尘初旅食，
清朝簪冕是家传。
临岐不尽平生意，
山海当年有喻篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1415','新蔡张孝子以乙丑岁寿七十其子什贰守松江松人为瀛海奇观图以赠为赋长句','顾清','明','海山桃花千岁红，
海日下照珠玲珑。
诸山卓立金芙蓉，
直上正值浮离宫。
飞霞紫气流无穷，
缟衣孤骞背青空。
下视六合尘溟濛，
尘区逼隘鸟触笼。
井蛙瓮鸡纷蠛蠓，
划然翘首骇所逢。
欲往从之渺难踪，
先生七十颜如童。
前身乃是浮休翁，
别来海波几桑蓬。
旧游历历宛目中，
七还九转非吾功。
至行自与神明通，
丹台峨峨银阙重。
姓名已隶东皇公，
他年飙轮许相从。
还驾此，
鹤来江东。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1416','题萧指挥便面','顾清','明','云海东南道路长，
海山云树共苍苍。
扁舟何日寻萧史，
一望蓬莱入渺茫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1417','望云思亲图','顾清','明','白云飞空往复还，
行人道上坐长叹。
亲庭偶与云路值，
云飞宁与人相关。
梁公去来几千载，
抚卷为君增叹嘅。
天涯望云伤客心，
膝前一刻千黄金。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1418','往在京师赵君希德有南游之约四月廿五风雨中忽相见于东楼留两月别去将由金陵视其侄锦衣君而归赋此为赠','顾清','明','极目燕云望海鸿，
江楼一笑雨兼风。
行边戏语三年约，
梦里清欢两月同。
归棹细穿汀草绿，
别尊新剥水菱红。
京华南北多亲旧，
为说音书近懒通。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1419','杏东','顾清','明','为觅董仙家，
春山满杏花。
朝阳三亩地，
返照一林霞。
厚德初乡里，
幽栖几岁华。
长生容我问，
应不在丹砂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1420','松岩','顾清','明','孤松何亭亭，
孤生岩之阿。
俯视千仞溪，
仰瞻郁嵯峨。
嵯峨不可攀，
劳心其如何。
空谷无馀音，
伐檀有遗歌。
惟应负苓子，
千载重来过。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1421','傍鸥亭','顾清','明','江南水乡多白鸥，
水神封作烟波侯。
主人作亭江水上，
却傍鸥鸟为邻州。
鸥飞有时渡江去，
小亭终日临江住。
亭兮傍鸥鸥傍亭，
君其问诸忘机生。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1422','同年宋良佐巡按得代以书留别赋此寄赠','顾清','明','黄叶柴门忆驻鞍，
瓜期屈指又秋残。
玉尊不及沙头饯，
明月长留海上寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1423','同年宋良佐巡按得代以书留别赋此寄赠','顾清','明','十载青云逐后尘，
冰霜此日见阳春。
书生别有迂谈在，
拟托阳关赠故人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1424','同年宋良佐巡按得代以书留别赋此寄赠','顾清','明','百年天下是金瓯，
根柢东南此四州。
同日震惊非小异，
使君何以慰宸忧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1425','同年宋良佐巡按得代以书留别赋此寄赠','顾清','明','亩税丁庸自祖宗，
巧名新意日重重。
归班第一章封奏，
民力东南久已穷。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1426','同年宋良佐巡按得代以书留别赋此寄赠','顾清','明','袨服奇装巧日增，
百金财可一缣成。
苇帘布缘黄絁被，
时为封章达圣明。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1427','同年宋良佐巡按得代以书留别赋此寄赠','顾清','明','圣人初政日方升，
独立台端仗老成。
一道歌谣听不尽，
须知四海望升平。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1428','里生杨和为令尹张侯写百禽从凤图','顾清','明','云间一峰名凤凰，
峰形宛类凤飞翔。
凤飞百鸟争趋跄，
林峦涧谷皆文章。
德辉一閟几千霜，
空有遗迹留青苍。
贤明令君起番易，
胸襟五色云锦香。
尚书双履出尚方，
云飞飘然来帝乡。
和风甘雨相扶将，
物无疵疠年谷穰。
疲癃鼓舞歌循良，
有如凤凰集高冈。
百禽从之鸣锵锵，
乃知往迹未为祥。
杨生妙手边与王，
生绡数幅写朝阳。
抢榆喧啾俛复昂，
菲红闪翠杂丹黄。
九苞凝立和以庄，
鹰鹯鸮鹘雕鹗鸧。
外若矫亢中已降，
云中阿阁金榜长。
晓日照耀腾金光，
一飞下视堪舆方。
旧巢依然朱栱傍，
即都归圣协宫商。
坐见四海登虞唐，
圣人南面垂衣裳。
一峰回首，
惟有春云十里郁郁封甘棠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1429','送李原复佥宪岭南','顾清','明','君昔还家我为客，
客邸论诗坐连夕。
酒壶棋局间嘲诙，
眼底十年犹历历。
君今为客我留家，
南云望望渺天涯。
钟情已怀儿女恋，
回首况对江梅花。
梅花的的映空碧，
君到南中我应北。
南与北，
转暌违，
梅花心事更谁知。
岁寒冰雪金台下，
犹可因风寄一枝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1430','味梅图','顾清','明','羊酪莼羹各有宜，
崇桃积季漫多姿。
岁寒一种真滋味，
只许龙山处士知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1431','丙寅春胡大声自桐庐守参政湖藩过松话旧诵予送通守殷君诗因用韵赋以识别','顾清','明','人物西江第一流，
八年麾盖滞东州。
新恩宠亚三湘镇，
远道争迎五两舟。
春宴喜闻京国语，
云帆高望渚宫收。
公馀为有江湖思，
还采蘋花寄旧游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1432','瞻云图','顾清','明','昔年白云飞，
亲在高堂思。
我归今日白云飞，
亲在重泉空泪垂。
云飞天边无定所，
到处瞻云泪如雨。
重泉冥冥閟长夜，
云光不到泉台下。
如令孝子勿思亲，
应是青天断却云。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1433','寿钱玉涧','顾清','明','玉涧水，
清且深，
流不息，
穷古今。
山头雨歇百谷聚，
白虹一道来沈沈。
涧傍老人眼双碧，
手弄涧泉坐白石。
泉流到海几清浅，
明年花甲从头转。
酿涧水，
作春醅，
采涧芹，
荐寿杯。
沐浴饮食无凶菑，
此中自可度千岁，
何必跨鹤游蓬莱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1434','经锄别业','顾清','明','昔年劬学带经锄，
万卷新开垄上居。
沈浸何妨问晴雨，
经纶聊复试菑畬。
晚风檐隙垂秧马，
残月窗间落蠹鱼。
莘野彭丘谁近远，
诗成转觉爱吾庐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1435','林塘晓霁','顾清','明','海日初照天苍凉，
远村近村浮浅黄。
垂杨两岸不见水，
中间一道开天光。
游蜂薨薨高下飞，
乳燕拂水翻乌衣。
老农携锄放田水，
平陂簇簇秧针肥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1436','五月晦日同汪教授集傅教谕鼎顾东曙戚舜和刘文瑞俞民威游黄耳祠归用席间联句韵却寄诸公','顾清','明','红桃夹竹记初来，
重到槐阴满绿苔。
城郭几番风雨过，
山林依旧佛灯开。
莫论往事催霜鬓，
且续新吟逭酒杯。
最可白云知我意，
瞰窗临水久徘徊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1437','琴泉','顾清','明','泠泠石上泉，
衎衎松下琴。
泉流合琴奏，
为君写清心。
天风岩际来，
舞乱长松阴。
舍琴面流泉，
风水有馀音。
悠然遂忘去，
华月上青林。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1438','简华峰教谕乞莲栽','顾清','明','园亭无竹使人俗，
池馆无莲也寂寥。
梦入镜湖当六月，
接天青盖拥红桡。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1439','简华峰教谕乞莲栽','顾清','明','行人秋早长安去，
中夏分莲不太忙。
但有碧䇶传别酒，
任他红里倚新妆。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1440','郡斋三咏次金贰守仲仁韵','顾清','明','高压重城郡圃东，
分明一笔倚青空。
云蒸不作昙花雨，
神运遥生月殿风。
此日育王重锡号，
向来毛颖谢论功。
李藩未试南山判，
傥可提携入汉宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1441','郡斋三咏次金贰守仲仁韵','顾清','明','空无海祲杂江氛，
一片湘帘映楚云。
不捲几年长袅袅，
平铺终日自沄沄。
康王谷口珠千斛，
龙女机中线五纹。
更爱晚凉新月上，
玉钩双与画檐分。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1442','郡斋三咏次金贰守仲仁韵','顾清','明','亭下阑干曲曲通，
浅红深紫斗帡幪。
低迷似欲留歌扇，
缛丽深疑蠹女工。
浓渍一番高阁雨，
生香不断画帘风。
绳床最爱清晨坐，
满耳薨薨听蜜翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1443','郡博汪先生约观莲病目不及赴赋此奉谢兼简邑博傅先生龙渊负苓二徵士','顾清','明','濯缨亭下水如罗，
二十年前倚槛歌。
春服久荒沂上路，
荷花仍发镜川波。
飞觞自笑成孤坐，
放棹谁能许再过。
见说华峰红十丈，
有人携酒候烟萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1444','池莲著一花用前韵报诸公约花开就赏','顾清','明','不知风叶展青罗，
愁断南湖水调歌。
汉女有情先委佩，
洛妃无伴独淩波。
峰头玉井难为配，
画里金屏不啻过。
已洗青尊酌芳露，
要看文旆倚云萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1445','华峰莲开用前韵见招奉答','顾清','明','越女红妆盖绿罗，
薰风长忆扣舷歌。
却从五纬联珠地，
涌出双峰湛玉波。
此日凭阑增慷慨，
当年挟册几经过。
洄渊落木无穷意，
敢谓乔松择女罗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1446','金仲仁母太孺人寿','顾清','明','翟茀初乘自粉闱，
朱幡继宠又兰枝。
中州礼训娴觿佩，
南国鲜芳入鼎滋。
七十再逢添算日，
三千长记采桃时。
宾筵向晚笙歌沸，
犹恨嫦娥出海迟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1447','庭鹤再雏送刘太守参政陕西','顾清','明','瑶台双白鹤，
飞来栖我庭。
栖我庭，
岁一伏，
两雏生。
一雏死，
两悲鸣。
松阴宛转巢复成，
巢成复引两雏行。
丹砂犹隐顶，
白雪已垂翎。
成都未识赵公马，
缑岭那闻王子笙。
成都缑岭知何处，
忽报主人留鹤去。
主人去去登岩廊，
鹤亦双翎日夜长。
他年欲觅庭下迹，
千仞遥同威凤翔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1448','拙隐','顾清','明','时方贵巧辩，
我口讷如壶。
时方务驰骋，
我足挛如拘。
岂无当世心，
老此田园居。
方凿不受枘，
直钓难为渔。
以兹甘静退，
庶以全吾初。
分井艺黍稷，
引绳树松梧。
蓄酒为宾燕，
明灯课儿书。
此外百无事，
悠然弄玄珠。
山水足清晏，
园林堪画图。
逍遥遂百岁，
从人嗤守株。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1449','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','三年望东林，
几日又当别。
盈盈谷水波，
一苇谁共折。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1450','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','溪莼牵紫丝，
念子良已久。
不在秋风前，
不在秋风后。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1451','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','寒瓜削成菹，
入眼犹自绿。
借问长安儿，
此味还知不。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1452','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','泽国有幽人，
城中稀复见。
曾观论史书，
吾党有腼面。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1453','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','龙宫带明湖，
倒影疑可掇。
何当酌清泠，
一洗尘中渴。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1454','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','祗园数峰碧，
不易布地金。
谁续菱溪记，
为公传此心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1455','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','公欲空万有，
谁哉记三生。
结习知未断，
斯文独钟情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1456','颐浩辩公寄莼菜瓜菹有别久不见渴心生尘之语因以为韵作绝句八首寄谢','顾清','明','长谷水千顷，
青天月一轮。
有尘飞不到，
何处却生尘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1457','腊月一日与文瑞访定庵于北山别后奉寄','顾清','明','平林回步草堂深，
二十年前此日心。
尘土自能迂俗驾，
云山曾不碍幽寻。
孤标共指中流镇，
高咏犹闻正始音。
珍重寒江夜深别，
满衣星彩动华簪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1458','从北山泛吴淞往苏州夜泊千墩文瑞出陈司训子进所藏吴小仙邯郸图索题穷冬远游空江夜话亦人间一梦也为书绝句','顾清','明','风雨官舟蜡炬残，
吴淞江上说邯郸。
人间到处谁非梦，
只有卢生入画看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1459','江中阁浅次金缓斋韵','顾清','明','浦口停帆换小舟，
故人家近不须愁。
竹林隐约分岐路，
禾廪高低见有秋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1460','江中阁浅次金缓斋韵','顾清','明','千古心期嗟击磬，
百年功业类藏钩。
吴江一道看如带，
可是先生志未休。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1461','题华文远所藏五松图','顾清','明','湖头看木翠团栾，
总合丹青画里看。
冠剑昂然五君子，
岁寒长得倚阑干。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1462','嘉兴道中怀昨游有作先寄文瑞仍约访宗孝御史','顾清','明','楼船徐度鼓逄逄，
忆别追游俯碧窗。
几日壶觞并残岁，
连宵风雨卧空江。
云边暗数青山九，
竹里谁怜白鹤双。
明日城东访曹植，
锦袍嬴得醉春釭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1463','怡庵先生致政归喜而有作','顾清','明','璧水江都继有声，
乡人尤羡此归荣。
九重云里恩袍烂，
三十年前弟子迎。
松菊喜欢依旧主，
溪山次第入閒行。
夜来光节堂前月，
更比寻常一倍明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1464','丁卯北行定庵以诗赠次韵奉谢','顾清','明','策名那复敢怀安，
却上离亭强笑欢。
三釜正怜蓬户暖，
九重深恐玉楼寒。
还闻奭旦陪周主，
屡报夔龙补舜官。
北极一星光日盛，
知公终夕倚云看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1465','定庵用东坡过清虚堂韵重赠奉和','顾清','明','江头凫鹥踏晴沙，
江岸黄蜂喧早衙。
行人倚棹不忍发，
红旗罥落樱桃花。
十年京华足乡梦，
麻绖被体方还家。
沈悲结痛无与愬，
夜啼愧杀城头鸦。
䌷书有诏不得住，
彤管中夜飞金葩。
忆君恋土肠万结，
短发几对残灯爬。
明晨复当拜公别，
何异渴吻思龙茶。
赠言珍重灿珠玉，
不知驽马空鞭挝。
端明退居乡俗美，
安石不起苍生嗟。
祝公眉寿强饮食，
慎勿高想淩青霞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1466','姚德夫晚翠诗','顾清','明','共惜春红好，
谁看晚翠深。
涧边长郁郁，
霜后独森森。
秾冶非吾事，
幽贞回此心。
山中有园绮，
垂白更相寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1467','题陆承祖扇','顾清','明','放翁归日鬓初星，
几从琴尊上小亭。
芳草不知人已去，
春来依旧自青青。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1468','松南书屋为章先生赋','顾清','明','吴松自昔诗书国，
得似君家亦未多。
缃帙牙签数椽屋，
百年相继住烟萝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1469','松南书屋为章先生赋','顾清','明','中舍仙游不可招，
依然旧隐傍江皋。
云礽见说多才俊，
有日天风起凤毛。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1470','婴医王舜规有母服持荣寿堂卷索题书此以吊','顾清','明','初日杲杲射北堂，
流辉弄影照明珰。
堂前兰玉芬以芳，
青霞织帔鬓有霜。
含饴映日坐堂隍，
海桃实成花又发。
蓬莱水清尘污袜，
啼乌声乾山月阙。
东望银台路明灭，
天下同心泪成血。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1471','别先茔','顾清','明','松杉郁郁带重冈，
榆柳阴阴绕曲塘。
曾有至人留宝谶，
敢期孙子滥朝章。
人间日月三年速，
地下泉源百世长。
愿竭痴顽了公事，
年年负土上玄堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1472','孙文博雪溪卷','顾清','明','溪流抱村自幽绝，
奇绝更著三冬雪。
玉沙银浦烂不收，
瑶草琪花连夜发。
主人画船携酒炉，
渔舠傍舷来卖鱼。
借问五更朝路客，
何如貂袖拥冰须。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1473','二月朔文瑞天民携酒为予发程泊舟跨塘桥赋此','顾清','明','兰舟冲雨出江城，
别鲁朝周两绪萦。
黄柳万家愁里湿，
碧云千里醉时横。
更生好学时方蹇，
宋玉多才赋未成。
安得相携便同去，
五更联马听鸡鸣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1474','吴江夜泊寄长儿天彝八首','顾清','明','飞盖桥边月漾沙，
顺流东去即侬家。
若为得共舟人语，
转过船头向早霞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1475','吴江夜泊寄长儿天彝八首','顾清','明','高堂双鬓已如丝，
此日何堪更远离。
宽我百忧惟汝在，
莫令思我在家时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1476','吴江夜泊寄长儿天彝八首','顾清','明','高楼朝日启帘栊，
两叔相望百步中。
我不在家渠即父，
莫令疏远坠门风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1477','吴江夜泊寄长儿天彝八首','顾清','明','佳儿如玉眼如珠，
临别牵衣泪满裾。
爱惜护持勤教诲，
书香一脉正关渠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1478','吴江夜泊寄长儿天彝八首','顾清','明','乡邻自昔有贤愚，
小忿閒言悉弃除。
惟有自修堪禦侮，
亲贤戒暴远谗夫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1479','吴江夜泊寄长儿天彝八首','顾清','明','家人小过莫轻笞，
渠在渠家亦是儿。
赏罚有条知痛痒，
自然亲附不暌离。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1480','吴江夜泊寄长儿天彝八首','顾清','明','门户晨昏慎启关，
家庭内外切防闲。
深更出饮清朝卧，
此是人家百弊端。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1481','吴江夜泊寄长儿天彝八首','顾清','明','木有根株水有源，
祖先祠墓合亲尊。
岂徒追报崇彝典，
亦要流传教子孙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1482','枫桥与文瑞天民别兼简乡里诸公','顾清','明','重洗红螺捲翠帘，
阖闾城外雨毵毵。
青山旧识如东道，
画楫相将类左骖。
旅食几年仍蓟北，
离怀千种又江南。
前途渐远须分手，
更欲留连待酒酣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1483','渡江','顾清','明','朝食大江南，
午泊大江北。
江流号天堑，
我行才只尺。
江路日以远，
客舟何时转。
美人青云中，
望望愁岁晚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1484','过扬州访吴汝玉见其子某云葬踰年矣一恸赋此','顾清','明','君墓已宿草，
我犹思见君。
相望一江水，
真隔万山云。
直谊今谁似，
高谈可再闻。
阿咸才甚美，
应足振遗芬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1485','扬州水关作','顾清','明','三过扬州十五年，
中间日月似流泉。
平山花竹隋宫柳，
又落东风一梦边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1486','黄家闸阁浅寄吕梁刘水部天祺','顾清','明','吕梁天下险，
我行今已三。
旱气烁汴泗，
上源日以廉。
悬流飞沫不复旧，
但见两涯乱石熊虎交巉岩。
水衡使者今刘彝，
人力到处天工回。
漕纲万艘连夜发，
谈笑对客仍尊罍。
官居花竹尤清绝，
别后梦魂犹髣髴。
北河连夕空系舟，
悔不为君三日留。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1487','皮沟闸阁浅都水曹元孝郎中以书来迓自云困于沽头走笔戏简','顾清','明','五日度两闸，
得水如得珠。
蠖行不数里，
已复困泥涂。
升高望留城，
忽得上沽鱼。
谓言渴聚面，
柰此川路纡。
阳侯自云尔，
辙鲋当何如。
北河非西江，
纲粟有天厨。
附骥尚千里，
攀龙矧吾徒。
但恐洪流沛，
分手复趑趄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1488','砚瓦沟','顾清','明','鲁桥南畔拂尘衣，
仰止东山思欲飞。
前去宫墙应甚近，
砚沟新水墨花肥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1489','世恩国声二郎中留饮南旺分司夜以小舟送抵北闸即事有赋','顾清','明','严鼓声中万柝喧，
连樯影里度归船。
缘舻宛转疑穿巷，
丛炬传呼若耀蝉。
云海几人真契合，
骚坛五岁此留连。
微吟更比抛砖陋，
满握璠玙想嗣篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1490','安山闸遣闷','顾清','明','泊舟安山下，
爱此嘉树阴。
登厓望河曲，
连樯矗如林。
有隶前致词，
兹惟民蠹蟫。
徵丁动千计，
索雇赢百金。
郡小岁仍俭，
诛求力难任。
称贷倚富室，
羊羔日浸淫。
情知剜心苦，
且免肌骨侵。
日午水满闸，
棹夫兀如喑。
淹留已自困，
复此伤予心。
青天如有知，
披云露遥岑。
排空各献秀，
为我清烦襟。
尘区自扰扰，
物外长愔愔。
安得向此中，
逍遥委朝簪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1491','临清候闸自辰踰未都水闭门而镇守中人饯其同官于河下','顾清','明','舟出清源万马奔，
斜阳舣棹自清晨。
主人谢客关河闭，
惭愧金珰贝带人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1492','发临清一日至郑家口','顾清','明','汶水欲尽卫水来，
两水夹舟喧万雷。
经旬守闸僮仆困，
千里顺流心眼开。
长风飗飗若绳引，
曲岸宛宛疑天回。
月明倚棹郑家口，
梦在谷亭呼酒杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1493','武城县','顾清','明','孤城赤立倚官河，
隔水人家亦未多。
怪得连坊表科第，
宣尼曾此听弦歌。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1494','德州仓厅与陈深渊先生夜话','顾清','明','从来迂阔笑吾儒，
果是真儒亦未迂。
邂逅平原话新事，
一番惆怅掩残书。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1495','杨青驿怀原复佥宪先寄原鲁','顾清','明','千里漳河欲尽头，
美人曾此驻兰舟。
图南暂息云中羽，
拱北重瞻海上楼。
眉宇几时消鄙吝，
江湖到处长离忧。
皇华会有嵩呼事，
先遣双鱼报早秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1496','直沽即事','顾清','明','漳水东流接海天，
寻常鱼蟹不论钱。
横空一网如云密，
玉食还曾到御前。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1497','读魏武则天事用石楼太史韵','顾清','明','乱来天意长奸雄，
一语深投月旦公。
岂谓三袁尽河北，
更教诸葛起隆中。
烟消赤壁沉雄俊，
树冷西陵怨女童。
不及人狼祖馀知，
化牛犹得占江东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1498','读魏武则天事用石楼太史韵','顾清','明','阿师留发拜昭仪，
绛缕初封不记谁。
海内渐看归圣母，
榻前空自属佳儿。
天徵鸟梦垂双翼，
鬼作人妖有四眉。
早与文皇作男子，
乾坤更是一番奇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1499','记梦中句','顾清','明','张生长安居，
日听车音响。
他年乘斑轮，
车音想非想。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1500','考试应天泊龙江和宫谕傅先生韵','顾清','明','山川依旧画图开，
客况多应晚色催。
孤月近人随浪涌，
落霞如鹜度江来。
清游幸不疏连璧，
盛事还闻颂有莱。
却傍紫垣占宝气，
直从牛斗贯三台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1501','铜鼓行','顾清','明','楼船行，
铜鼓鸣，
和以横笛间丁宁。
空江深夜天宇澄，
稀声要眇杂铿吰。
隐如仙乐度青冥，
贵人中坐憺无营。
流星捷报前几程，
徵丁索馈百里惊。
儿童喜闻铜鼓音，
不知铜鼓伤予心。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1502','毬杖行','顾清','明','击毬本戎戏，
毬杖取南中。
云帆下河曲，
专使董成功。
此物本轻细，
连艘竟何庸。
春秋富当宁，
典学希商宗。
荡心圣有戒，
传闻岂雷同。
舟行不可问，
为尔心忡忡。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1503','十月朔还至通州雨三日不止','顾清','明','雨滴篷窗浪打舷，
听风听水不成眠。
家人相忆心千里，
肯信连宵潞渚边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1504','得家书报长孙应阳入小学','顾清','明','孙儿生质颇清明，
只在收心养性成。
看罢平安二更尽，
耳边如听读书声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1505','戊辰子南下第归为书其扇','顾清','明','横云山前小赤壁，
长记扁舟晚泊来。
山风吹人难久住，
明年候子黄金台。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1506','忆家园廿六首','顾清','明','三十年前手自移，
眼看一本作千枝。
翠翘红萼东墙下，
几为贫交入梦思。',NULL,'','{"preface": "端午日雨窗独坐顾前庭草木葱茜怅然有乡国之怀因追记家园卉木花果各赋一诗其间或故有而今亡或昔无而今有栽培位置历历在目前鱼积薪之叹废兴存殁之感略于此具焉存之使后人观之无忘其初云尔", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1507','忆家园廿六首','顾清','明','苍然五树积烟霞，
数里遥看是我家。
后进只今千百辈，
草堂谁识旧生涯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1508','忆家园廿六首','顾清','明','潮红香颊翠襟披，
流落频伤未遇时。
廿载断魂招不得，
系情多赋八篇诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1509','忆家园廿六首','顾清','明','海棠西畔石榴东，
的的寒花映晚空。
旧迹渐沦忘不得，
苍苔翻恨落英红。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1510','忆家园廿六首','顾清','明','窗西一阵绿云浓，
眼见萌芽到拂空。
成实不教霜后荐，
只因多雨更多风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1511','忆家园廿六首','顾清','明','红杏初开锦作山，
别来花实渐阑珊。
春风似为人离别，
还是春风不断閒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1512','忆家园廿六首','顾清','明','三月东园花压阑，
种花人去我来看。
不须烂漫开千朵，
惜取芳根伴岁寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1513','忆家园廿六首','顾清','明','百干相扶共一根，
纷纷红蚁缀枝繁。
春风不用歌行苇，
但遣封培付子孙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1514','忆家园廿六首','顾清','明','鸭脚当年自一时，
瓦盆雕砌影毰毸。
黄封不遇头纲使，
争得淩云百尺姿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1515','忆家园廿六首','顾清','明','花发园亭记别离，
忆花又过别离时。
赤瑛盘上筠笼里，
各自伤心各自知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1516','忆家园廿六首','顾清','明','高架新梢绿刺檐，
坐来幽意满江南。
不知华月清池上，
谁共凉阴酌晚酣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1517','忆家园廿六首','顾清','明','山崦移来玉一丛，
竹林深映小桃红。
别来消息知何似，
依旧无言对晓风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1518','忆家园廿六首','顾清','明','畚土薶根旋作畦，
数竿萧瑟映疏篱。
绿云凉月西窗晚，
寻我林间旧刻诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1519','忆家园廿六首','顾清','明','两丛高下映波红，
疏柳池边落照中。
无限江南摇落意，
燕山几日又西风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1520','忆家园廿六首','顾清','明','不将幢节驻羊家，
几伴西楼坐月斜。
零落瑶华应不恨，
绿阴青子在窗纱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1521','忆家园廿六首','顾清','明','一株秾烈破春寒，
曾是刘郎刮眼看。
今日前身谁复记，
赤霞空炼九还丹。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1522','忆家园廿六首','顾清','明','神龙不畜蹄涔水，
威凤宁栖枳棘丛。
试起橐驼论种树，
此公何得在盆中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1523','忆家园廿六首','顾清','明','灵苗体性本清虚，
风叶犹堪醉里书。
危石幽阑画楼畔，
撩人归思半因渠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1524','忆家园廿六首','顾清','明','人言闰月厄黄杨，
此语分明太激昂。
得与婆娑同晚岁，
任他萧艾过人长。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1525','忆家园廿六首','顾清','明','平原宅里看移根，
百日高花不负恩。
纶阁西头见新月，
分明清影近黄昏。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1526','忆家园廿六首','顾清','明','吴国春深试手栽，
燕山秋晚报花开。
灵椿老大无材段，
奕叶芬芳为尔培。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1527','忆家园廿六首','顾清','明','似欲淩空且屈蟠，
夹门双影碧团团。
油幢不合书生建，
争得薰风日倚阑。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1528','忆家园廿六首','顾清','明','屈叶回柯巧蔽亏，
画檐三面碧参差。
琉璃隔坐非吾有，
冰雪相看正尔期。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1529','忆家园廿六首','顾清','明','华顶虚传十丈红，
方塘只在小桥东。
天机云锦应无赖，
烂漫西风夕照中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1530','忆家园廿六首','顾清','明','绿嫩青酣井字畦，
柳塘东畔竹林西。
阿儿暴富人应妒，
岁晚平添百瓮齑。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1531','忆家园廿六首','顾清','明','侬家世业本耕农，
远客思乡却自侬。
柳外平畴夜来梦，
万行新绿舞薰风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1532','卧病','顾清','明','重云积九夏，
永昼恒涔涔。
溽暑不可耐，
沈痾复见侵。
隐几西窗下，
悠然怀故林。
繁红已结实，
秾绿正敷阴。
凉风振水竹，
窗闼有馀音。
欲往川陆阻，
居然劳我心。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1533','病起将朝寄卢宗尹','顾清','明','思君不可见，
我病君忽来。
相逢执手间，
未药心已开。
刀圭入我口，
晴风扫阴霾。
病发不我会，
君来岂予媒。
乃知平生交，
冥契神所该。
清秋肺气苏，
栉发临花台。
行当跨鞍出，
呜佩朝蓬莱。
却寻广成子，
一笑空同回。
作诗先报君，
此报非瑶瑰。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1534','鲁司成振之将乞终养梦公服秉笏乘青羊而驰及命下乃八月乙未十五日饯于宗易太史西园即席有赠','顾清','明','梦里青羊且信疑，
今朝南楚定归期。
先生六馆人师上，
圣代千秋孝理时。
朱橘正堪霜后荐，
锦衣行见膝前嬉。
三公一日谁轻重，
莫问重来鬓有丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1535','送刘公勋太学兼简尊翁聘君文仪进士','顾清','明','海门寒月三江水，
天阙晴云五凤楼。
别路此时频目极，
两乡千里各神游。
诗书不断通家好，
尊酒难浇壮士忧。
往见周郎话相忆，
北风归思满沧洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1536','题公勋水仙扇面','顾清','明','到家花正发，
别路梦先知。
月落西湖上，
何人共赋诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1537','十一月望月食既历戌亥子三时乃复','顾清','明','日食又月食，
两年三见之。
天心果仁爱，
吾道合清夷。
怅望云间路，
苍茫夜半时。
怀君复思土，
愁乱不成诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1538','己巳待泮潞渚单氏两翁以乡里来会长者八十二少者七十三皆朴茂淳古类山谷中人溯其生当宣德正统间得气之方厚者也为之感叹适有以画竹惠者因书其上赠之正月二十日','顾清','明','手披双竹写新诗，
往伴高堂两鬓丝。
总是目前稀有物，
升平父老岁寒枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1539','题画赠寓馆罗翁及单希贤','顾清','明','京华相识半乡人，
潞渚逢君意更亲。
认取画中山好处，
草堂归访故园春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1540','题画赠寓馆罗翁及单希贤','顾清','明','南州乡里北州身，
看画思乡总未真。
若到练川佳绝处，
也应回首潞河春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1541','题菜赠杨翁普能时年七十三断肉六十年矣','顾清','明','上沃泉甘野水边，
乌菘紫芥各纷然。
主人为尔都忘味，
更伴清斋六十年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1542','题菊赠天津张信千户','顾清','明','我家老圃金芍药，
独立岁晚淩霜风。
新图赠君为君寿，
白头相对即苍松。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1543','田上堠','顾清','明','田上堠，
堆复堆，
官新筑，
圆若腄。
贵人赐田连帝畿，
不封不筑民终以为私。
上植柳，
傍作围，
牛羊不践雨不颓。
堠不颓，
民不走，
为君耕，
为君守。
但愿贵人千万寿，
免为他人作封堠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1544','秋屿为田廷相郎中赋','顾清','明','水心著山自可画，
况是潦尽霜清时。
使君于此兴不浅，
绝境使我心先驰。
蓬莱犹恨弱水远，
浮玉更比金焦奇。
星槎何日同汗漫，
归来重赋游仙词。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1545','重过安山','顾清','明','安山闸下停舟处，
旧日风光又眼前。
试问阿蜣功满未，
柳阴旋转自年年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1546','黄家闸南数里地旷多盗丁卯北行阁浅三宿是日风帆迅疾家童指示其处为之怃然','顾清','明','此地曾三宿，
重来尚眼明。
寒泉高岸下，
还似昔时清。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1547','下邳阻风简天民','顾清','明','漳河溯流兼溯风，
汾河贵人不相容。
清河一日可千里，
南风逆浪势转雄。
方舟野宿频相失，
忧水忧风过三日。
篷窗晚立看风樯，
过眼鸿毛天一方。
请公小忍不须闷，
待渠定时吾亦进。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1548','阻风邳南第七屯百户王君留宿薄暮风止行二里馀复作与天民舟相失戏书示风','顾清','明','小住复颠狂，
泊我空滩外。
听汝吾弗嗔，
汝宁亦知愧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1549','望露筋庙作','顾清','明','荒陂下残日，
疏木出古祠。
伊昔露筋媛，
明灵此栖迟。
渺然葭苇乡，
挺此冰玉姿。
仙骨谅已蜕，
英风浩无涯。
想当野宿日，
宁与庙食期。
颓垣不踰肩，
缺瓦苔参差。
不知春秋祀，
有土能不遗。
堂堂七尺躯，
冠带称男儿。
婉婉形势途，
所觊在一资。
使当生死际，
宁复顾四维。
念此欲下拜，
风樯浩南驰。
沧波望不尽，
目极空烟霏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1550','伐薪','顾清','明','秋霖害我稼，
卒岁沦洪渊。
青山富薪槱，
猛虎当昼眠。
炊人屡告罄，
饥仆怒争先。
平生怯懦心，
蜂虿等戈鋋。
会众伐金鼓，
长驱陟其巅。
我进彼亦退，
芟夷砉无前。
方舟杂稛载，
浩歌戒言旋。
阴风海上来，
白雨如奔川。
飘零不自救，
狼籍遍原田。
虎暴厌人肉，
村墟哭相传。
履险指一爨，
命邻伥鬼编。
幸胜天复尔，
栽培岂其然。
生人亦已久，
秽德熏彼玄。
鸱枭啄鸾凤，
阘茸乘后贤。
横奔不复制，
伊郁谁当宣。
由来城门火，
横及池中鲜。
严霜下百草，
岂择兰与荃。
沮洳本自处，
屡空谁尔怜。
似闻老农说，
丰穰在明年。
行看饫浆酒，
岂复忧厨烟。
小忍济乃大，
天运有推迁。
再拜谢老农，
买金镌尔言。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1551','十月一日梦抑之得告还乡赋诗送别寤而记其首句因足成之','顾清','明','水心亭下木兰舟，
昨夜分明赋远游。
消息眼前无可问，
满天风雨独登楼。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1552','顾德章尊人龙川介寿卷','顾清','明','吾宗东吴秀，
奕叶多俊良。
矫矫龙川翁，
早脱名利场。
归来自洪都，
十年鬓犹苍。
以彼文字游，
放此云水乡。
春风介眉寿，
珠玉间笙簧。
蔼蔼亭林云，
幽幽玉山堂。
上下千载馀，
声华蔚相望。
何当驾扁舟，
共泛川上光。
手携蟠桃枝，
酌彼昆崙觞。
再歌行苇篇，
和以伐木章。
佳期自今始，
矫首希青阳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1553','十一月十一日极寒','顾清','明','十分饥馑十分寒，
目见伤心耳亦酸。
袖手茅檐对残日，
此身犹是论思官。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1554','经始方洲田舍有忧其难成者赋此答之','顾清','明','无食始学稼，
南村寻老农。
沙田积雨后，
沮洳连云空。
方将葺栋宇，
拥褐歌年丰。
沿源渡水曲，
骋望出丘中。
岁晏草木尽，
空江来远风。
顾影忽自笑，
葛巾飏飞蓬。
平生坎壈身，
何事非所躬。
已为后时计，
况当吾岁穷。
情知倚市利，
远胜刺绣工。
所安谅在此，
违性伤我衷。
填海有精卫，
移山有愚公。
决策自今始，
有善吾其从。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1555','周文焕致槐栽十二本列植道南美而且巨不日成阴矣诗以谢之庚午正月望日','顾清','明','水后江村万木童，
閒人门巷一时空。
薰风六月清阴遍，
好与周郎赋角弓。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1556','周文焕致槐栽十二本列植道南美而且巨不日成阴矣诗以谢之庚午正月望日','顾清','明','蜀江桤木三年大，
魏国槐阴四海平。
先遣黄花劝秋驾，
老夫还此听音声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1557','方洲示役夫','顾清','明','田夫具畚锸，
问我功何始。
我功亦汗漫，
我屋当素拟。
前临有方洲，
后枕须曲水。
相泥以为深，
因以崇我址。
亏盈岂予心，
一举成二美。
行当艺椒兰，
且复树梧梓。
连村翳桑麻，
接畛被穈芑。
勉旃相予成，
为尔歌至喜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1558','旧岁三月阻风于清河屯田百户王君致香椿一本涉淮济江颠沛数矣而此特无恙每一顾之心未尝不在淮北也发春伊始移植朝阳赋以志感','顾清','明','白门斜日阻归航，
野老墙头碧玉长。
感遇不辞千里别，
侨居又是一年强。
流光荏苒嗟予老，
行路閒关备尔尝。
浅薄无能系思忆，
宦途留此作甘棠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1559','题彭君言归省卷','顾清','明','青衫拟著慰亲颜，
已著青衫卒未閒。
他日三公真不换，
鸳鸯湖上䌽舟还。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1560','足梦中语','顾清','明','相期不我会，
天上嫁张硕。
琅风凝矞云，
轮囷倚空碧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1561','迎牛于子南','顾清','明','千金买宝剑，
尘匣空挂壁。
卖剑买牛耕，
百口歌足食。
有牛无剑，
古且为之。
矧剑不往，
而牛自来。
水田和软牛腯肥，
日耕十亩不言疲。
腰间宝铗光陆离，
逢时还足斩鲸鲵。
不然力耕老东菑，
作诗迎牛属牛儿，
此意只可吴郎知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1562','寿萱图为董徵吉张德馨题','顾清','明','萱草花，
开北堂。
凤翎鹄咮参差光，
采而佩之百忧忘。
金章谢庭子，
绣腹王家郎。
花前拜舞进瑶觞，
花枝暖拂春风香。
酒不尽，
花益芳。
重帷深深春昼长，
更六十年春未央。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1563','四月十八日泖港舟中作','顾清','明','渐喜逢人少，
扁舟傍野塘。
绿波侵隐几，
细雨对分秧。
潮长汀蒲短，
风微岸芷香。
沙边双白鸟，
来往亦相忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1564','题爱山卷','顾清','明','好山吾亦爱，
知子钟情处。
郁郁横空云，
中有王裒树。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1565','书陆服周扇用包汝调韵','顾清','明','诗笔纵横格气深，
故人应是渼陂岑。
秋来白发知多少，
犹自松间抱一琴。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1566','五月十四日遣闷','顾清','明','五月吴天漏，
三江禹迹芜。
闾阎自生死，
城郭且徵输。
窘蹇医疮计，
苍茫卒岁储。
南阳有召杜，
异代直堪吁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1567','雨后文仪欲过小楼閒话诗以速之','顾清','明','买得仙人缩地符，
三江七泽尽吾区。
诸公为有登楼兴，
来看扬州白马湖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1568','米船叹','顾清','明','秋田生浪甑生苔，
日望米船江上来。
闻道城中有新令，
米船临到却翻回。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1569','题画送王贰守入京','顾清','明','行路人人说好官，
一舟如叶上长安。
君王若问东南事，
不似江山画里看。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1570','鹿门遗隐','顾清','明','襄阳耆德世空传，
谷口清风有象贤。
心识双桥何日到，
青山无数夕阳边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1571','鹿门遗隐','顾清','明','江海收身五十馀，
青山不改旧园庐。
人来欲问遗留计，
孙子躬耕又读书。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1572','送陈经历奉表留都兼简秋闱诸君子','顾清','明','宦薄身清职事閒，
每蒙骑马扣柴关。
朝来喜色盈眉宇，
又向金陵饱看山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1573','送陈经历奉表留都兼简秋闱诸君子','顾清','明','山水金陵是昔游，
海鹏云鹗正当秋。
相逢为道长林下，
每夕披襟望斗牛。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1574','闻宗孝御史复冠带','顾清','明','旋拂葱袍整惠文，
圣朝元不负忠臣。
赤墀鹓鹭频回首，
次第春风接后尘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1575','闻宗孝御史复冠带','顾清','明','雨露冰霜总化工，
逢干何必羡夔龙。
向来陈迹浮云变，
看取层崖雪后松。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1576','题画送都指挥袁君归河间','顾清','明','江海三年拥使旌，
江风不动海波宁。
瀛州可是垂纶地，
万里燕然要勒铭。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1577','题画送陈子进教谕贵池','顾清','明','秋浦山川似若耶，
广文官舍列仙家。
无因得附星槎便，
箕踞长松看九华。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1578','题画送祁通判朝明年正月时宦瑾伏诛海内拭目以观新化','顾清','明','雪后蓬莱万景鲜，
䌽云红日在尧天。
江湖不及元正会，
遥听升歌采菽篇。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1579','午窗睡起杜以芳持扇索诗走笔书赠','顾清','明','流水湾头竹半欹，
夕阳山外鹤归迟。
幽亭独坐无穷意，
只恐钟期亦未知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1580','芸屋储书','顾清','明','青青庭下草，
芬馥掩椒兰。
能令脉望走，
使我缃帙完。
邺侯彼何人，
插驾万轴攒。
而我千载馀，
触事如面垣。
孙翁识恨晚，
闻风起三叹。
缔构亦已勤，
畜聚良独难。
不知几年心，
成此万玉山。
屋下五䌽衣，
万卷胸中蟠。
小出已高第，
远图未容殚。
春风开寿尊，
酒绿衣裳斑。
愿以卷中训，
永奉膝下欢。
青山拂新图，
虹光起檐端。
何当淩七峰，
一快平生观。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1581','文仪别予赴会试风甚留宿拈韵赋此为赠','顾清','明','错指长云怪石尤，
海天回首是瀛洲。
飙轮未会三山驾，
文笔先题五凤楼。
到手锦标堪一笑，
临岐红烛且须留。
前年六博非空兆，
有待金羊送䌽辀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1582','和进之壬戌雪中作','顾清','明','冰柱谁家长万尺，
世人未见神仙宅。
昆崙五城楼十二，
一一银山半天白。
天河倒挂楹栋间，
下视蓬婆等卷石。
东方有士古袁安，
平生自信干人难。
闭门僵卧三日雪，
早起翻念神仙寒。
书生未试多濩落，
此事几为流俗叹。
草堂相对一尊酒，
龙公水妃互奔走。
须臾㳽漫天地变，
崖堑区区复何有。
瓦沟何恨太飘忽，
桧顶何亲独淹久。
从来幸不分町畦，
此日宁须问容受。
晚来笔冻可柰何，
满庭落叶寒风多。
嫦娥矫立碧云里，
似欲斗彩撩清哦。
我今有诗亦不作，
此雪讵堪还更落。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1583','辛未元旦试笔','顾清','明','五十看加二，
浮生事可几。
未论前迹缪，
已觉故人稀。
把酒怜青镜，
临风眷素衣。
渔童江上去，
拂我旧苔矶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1584','送陆时敏之长沙','顾清','明','犹记蓝袍拂暗尘，
诗成二十九回春。
年催绿鬓看俱老，
身有青衫不当贫。
宣室久虚前席地，
草亭还有著书人。
荆吴风物皆相似，
莫为思乡咏白蘋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1585','题杭文锡扇','顾清','明','园实畦芼杂水英，
墨卿收拾太多情。
不知烟雨湖头路，
犹有和盐一味清。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1586','题海鹤图寿陈畏庵太守','顾清','明','合共祥麟侍衮龙，
回翔暂息海门风。
蓬山二月群仙会，
又看桃花一度红。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1587','题郑节之丹崖卷','顾清','明','谷口清风不可攀，
丹崖千仞白云间。
人来欲问长生诀，
瑶草春风尽日閒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1588','松山','顾清','明','种松傍青山，
因与青山名。
山耶不知松，
松亦两忘形。
天风夜半来，
共作江涛声。
清境不易到，
新图空复情。
千秋无我弃，
相携斸仙苓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1589','猛虎三首','顾清','明','猛虎昔当路，
猎夫远潜身。
麒麟在山中，
左右良已勤。
一朝猛虎死，
弯弓射麒麟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1590','猛虎三首','顾清','明','麟也亦有咎，
但非猎夫知。
不射亦不免，
射之宁复辞。
但恨豺与狼，
纷纷满山蹊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1591','猛虎三首','顾清','明','射麟麟不嗔，
射虎虎伤身。
虎纵不敢射，
可射宁独麟。
射者每如此，
所以虎欺人。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1592','东曙寄诗志局为教甚多次韵奉答盖各言其志而亦互相发也','顾清','明','举世纷纷役此生，
腐儒身后独矜名。
可能绮陌金丸子，
并有箕山颍水清。
米传未消陈寿耻，
酱封须待子云明。
南楼昨夜凭阑望，
耿耿银潢带玉衡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1593','次韵畏庵太守罢郡后作','顾清','明','鸰原接羽忆当年，
梓里亲耕召父田。
正好棠阴看露冕，
谁令清瑟改朱弦。
池鱼岂识焚城火，
塞马还留偃盖天。
莫学君家老仙伯，
云台从此便高眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1594','畏庵和章趣成郡志末有三泖九峰遗似屣之句再叠反骚','顾清','明','忧国寻常愿有年，
几番骑马看湖田。
心劳为绾阳城印，
调古谁聆单父弦。
三泖共涵卿士月，
九山犹戴使君天。
不应便作江边屣，
已是桑林一岁眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1595','畏庵和章趣成郡志末有三泖九峰遗似屣之句再叠反骚','顾清','明','故国遗文四百年，
消沈已似海东田。
编摩滥把丹青笔，
心赏谁分燥湿弦。
缃夹远封应有日，
藜灯深夜敢诬天。
横云片玉书堆近，
多少英雄地下眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1596','畏庵既定四城门名有诗见示次韵','顾清','明','使君无复眷吴侬，
归兴飘然万里篷。
临发匆匆缮城圃，
古人元有认真风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1597','题徂徕山人小景二幅','顾清','明','山头已自雨霏霏，
江上美人犹未归。
趣放兰舟迎接取，
免教云雾湿仙衣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1598','题徂徕山人小景二幅','顾清','明','远山近山玉作堆，
东村西村梅乱开。
王猷兴尽已归去，
不道山童沽酒来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1599','题竹六言','顾清','明','北固谁家江岸，
丁卯何处溪桥。
春尽烟波渺渺，
月明风竹萧萧。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_1600','宿天民西庄用丁卯枫桥留别韵','顾清','明','碧玉绕村溪宛转，
青丝拂岸柳毵毵。
风光岁晚初停棹，
旅宿春深几并骖。
真隐底须寻谷口，
返招应与赋淮南。
银筝画烛通宵燕，
还似枫桥待酒酣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1601','固齿白玉膏歌为祁通判作','顾清','明','神仙玉膏人不识，
煮玉和云化为液。
溪藤均敷藤一色，
嗅之馨香扪无迹。
罗千有家蛲蚑宅，
风淩火焮震摇兀，
剪而封之还如石。
我闻三年索不得，
使君一封盈数百。
端棱而方长而白，
桓圭两挺瑶琚析。
老罗见之三太息，
君来何迟使予厄。
龈之边兮腭之侧，
启封粲然云白黑。
炎熇以清震淩息，
坐令食饮滋甘泽。
使君之仁薰两邑，
歌谣已自盈阡陌。
我歌玉膏裁举一，
玉兮固齿仁固国。
我与斯人同寿域，
玉膏之歌兮歌宁溢。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1602','王义士助丧卷为王贰守题','顾清','明','太学资钱囊久竭，
丹阳麦舟篙橹绝。
彭城义士古秦豪，
青史他年合三杰。
王侯一生慎许人，
手卷索诗遥赠君。
东南两岁沟壑满，
放笔怀贤空暮云。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1603','为南村题蟠桃图寿喻守','顾清','明','蟠桃子熟金累累，
参差接到花开时。
仙山阔远谁貌得，
使君燕寝回春姿。
海山千里春茫茫，
东风是处桃花香。
使君有意能小待，
实成亦是三千霜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1604','陈都阃汝玉以思亲册求题久未有以复也二月君提兵过江赋此为别伫闻捷音把笔以俟','顾清','明','都将牙旗出海门，
长淮北去净妖氛。
平生一掬思亲泪，
誓与天家策异勋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1605','陈都阃汝玉以思亲册求题久未有以复也二月君提兵过江赋此为别伫闻捷音把笔以俟','顾清','明','茔木青青雨露垂，
赴君还忆别亲时。
须知列鼎关心句，
便是元戎奏凯诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1606','黄岩有水出天台下流入海湍悍能败舟土人呼为恶溪艾斋陈君募乡人筑长堤截而回之民用无患是岁与施彦器宪副访予云间赋此为赠','顾清','明','愚公移山骨成丘，
精卫塞海徒怀忧。
岂知天台万壑里，
一夜绝险成安流。
筑堤回波谁始谋，
艾斋老人今白头。
老人头白何所求，
名与此水俱千秋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1607','彦器以迕逆瑾破家有诗述怀自题曰处困为书三绝句','顾清','明','天津城下泊归船，
回首江湖遂渺然。
邂逅云间话畴昔，
不知今日是何年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1608','彦器以迕逆瑾破家有诗述怀自题曰处困为书三绝句','顾清','明','长叹朱家亦男子，
閒思剧孟是何人。
江头抗手送君别，
愁见官亭柳色新。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1609','彦器以迕逆瑾破家有诗述怀自题曰处困为书三绝句','顾清','明','脉脉江流渺渺春，
北河消息半虚真。
乾坤大有蓬飞客，
不用文词效楚人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1610','招北野诸公看花','顾清','明','杏花初发望君来，
望君不来桃又开。
花开不向枝头看，
看取北墙红满苔。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1611','刘时遇行人使占城过松留一宿而别','顾清','明','环王封域海云连，
汉使旌旗日月悬。
星象五州占驿骑，
鱼龙千里避楼船。
华堂列炬翻疑梦，
紫禁联镳又隔年。
奇绝胜游须有赋，
并将王会入新编。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1612','竹西草堂','顾清','明','鹤城西南瑁湖曲，
湖上森森万竿竹。
竹林西畔屋三间，
六月清风洒冰玉。
林间一径曲当门，
知君有意求多闻。
肩舆他日许直造，
共倚东窗看绿云。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1613','锡山王应藩工真行书尤善题署予辑郡志为予留数月将归赋此赠之','顾清','明','王郎运笔如运帚，
大字如盘一挥手。
有时细意写乌丝，
蚊脚蝇头满窗牖。
松江古志新刻成，
龙宫塔庙俱镌铭。
淩云巨榜专有待，
不学韦公白发生。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1614','次韵杨崇周有怀见寄','顾清','明','手披红印启封题，
回首龙山落日西。
别路十年云几变，
王孙何处草还萋。
心期晻霭川原隔，
时节参差土炭低。
为马为龙自君道，
可能怀宝视群迷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1615','闻先生竹亭','顾清','明','种竹人何在，
閒亭故俨然。
名因王子传，
兴入武公篇。
夜雨凉生坐，
晴云绿满川。
人来问孙子，
玉立遍阶前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1616','云西为郭道士赋','顾清','明','白云西畔是君家，
萧洒轩窗占物华。
我欲时来看修竹，
洞门无遣白云遮。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1617','云西为郭道士赋','顾清','明','童子东山采药归，
石桥流水漾斜晖。
回头笑指来时路，
满眼白云横翠微。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1618','王西园画郑节之杏林深处图','顾清','明','郑家杏林如董家，
王郎笔底腾朝霞。
青山周遭屋半隐，
中有石鼎熺灵砂。
平生活人不计功，
年年杏林花实红。
花红实落又成树，
只恐青山十里无地容春风。
林日深，
花日密，
丹砂几时成，
令我知消息。
分君一匕，
与君同升。
超凌太虚，
飞步紫清。
归来弭节杏林下，
还问春风别后几度飞红英。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1619','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','三十六年前此日，
几多般涉到今辰。
夜来为汝从头数，
泪落残灯忆老亲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1620','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','生汝艰迍惜汝深，
遗踪历历怕追寻。
苦心自是当年事，
汝母当年更苦心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1621','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','同生两弟一堪悲，
更欲相亲不可追。
曾看东园春帖子，
春光都在紫荆枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1622','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','吾家积德是镃基，
致有如今汝合知。
人误听从他自误，
莫将我是学人非。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1623','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','昔年我似汝年时，
涉历艰难汝所知。
人道好人容易做，
好人偏足受驱驰。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1624','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','眼前地步放教宽，
尽著前行后便难。
我祖分明有先样，
一生曾不用机关。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1625','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','诸君置酒合欢声，
一半从前见汝生。
自古仲尼称至圣，
恂恂乡党似无能。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1626','六月廿二日天彝生辰诸亲友携酒来贺蓼莪棠棣并感予怀因书俗语为八绝句示之','顾清','明','失人憔悴得人昌，
尺寸何须较短长。
但得好人长作伴，
自然门户有辉光。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1627','题孙丹霞小景','顾清','明','拂空翠盖摇双桐，
桐阴袅袅来天风。
仙山秋日如春融，
琪花瑶草长丰茸。
道人晏坐侍青童，
玉尊缥醴清若空。
洪厓有约浮邱公，
青禽误集东皇宫。
飙轮西来滞瀛蓬，
停觞思入虚无中。
皇览揆予始鸿濛，
五十四载遗尘踪。
玄纲袖领繄尔宗，
馀事复到临池工。
良常西麓新宫崇，
金书玉刻腾蛟龙。
幼霞回首玄卿翁，
人间天上将无同。
蟠桃正熟火枣红，
水边处处黄花丛。
青山隐隐云重重，
归来何时寻赤松。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1628','曹定庵寿八十一','顾清','明','九山南下富林庄，
横浦斜连八曲塘。
长向云霄目双凤，
独馀霜柏峙高冈。
诗书盛有诸孙继，
齿发谁如暮景强。
八十春秋重起算，
广成今在水云乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1629','九日鹤塘庄过黄耳祠次高进之韵六首','顾清','明','平泉何处李家庄，
茅屋疏篱也夕阳。
三径就荒吾不恨，
红糕绿醑满田香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1630','九日鹤塘庄过黄耳祠次高进之韵六首','顾清','明','五亩园池六尺垣，
清溪一曲正当门。
鹤雏牛犊皆诗料，
剩有美谈留子孙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1631','九日鹤塘庄过黄耳祠次高进之韵六首','顾清','明','二陆亭台昔未荒，
几番重九插萸房。
无人可论当年事，
又说江湖与庙堂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1632','九日鹤塘庄过黄耳祠次高进之韵六首','顾清','明','漫说新庄类午桥，
几年风雨困飘摇。
扁舟此日堪乘兴，
来逐归潮去上潮。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1633','九日鹤塘庄过黄耳祠次高进之韵六首','顾清','明','又向东村访佛祠，
衰容数被野鸥窥。
不须更答三人问，
沂水风雩竟阿谁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1634','九日鹤塘庄过黄耳祠次高进之韵六首','顾清','明','丛木回冈费讨寻，
鹤泾回望九皋深。
洛阳游子归何日，
碧草春风岁岁心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1635','过锦溪访曹古松时年九十二以不及再见送予甚远为之怆然临别赠此','顾清','明','锦溪重过老人居，
三十年来一梦馀。
扫榻又扶迎客杖，
挥金曾买教孙书。
衣冠故国风逾永，
水竹深村画不如。
回首弧南光似月，
未须临别重嗟吁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1636','送张教授之嘉兴','顾清','明','乐平门下久知名，
湖学东来重有情。
楩梓旋应充国器，
枌榆看已入乡盟。
无端作恶缘新命，
便可相期是耦耕。
最喜家书十分便，
春波一夕到珠泾。',NULL,'','{"preface": "前进士蕲水张君容之程太史正之高弟也自归安教华亭士庆得师而君亦乐其风土方卜居焉而嘉兴之命至得邻之喜惜别之怀交战于中而言固有不能尽也", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1637','蒲葵扇歌送何朝宗教谕之同安','顾清','明','天生蒲葵作凉箑，
野人乍见呼棕叶。
柄端出叶叶作摺，
里棱外棱刚鬣鬣，
中攒边展凤翎接。
边际筠丝压妥贴，
通体天成此人合。
汉宫纨素出剪裁，
南阳白羽须编排。
丹青组绣却走避三舍，
纸屏石枕尚觉非全才。
先生南海我北海，
一叶轻凉为谁采。
翩然乘风致我傍，
簟几一时颜色改。
君今去我向闽关，
扇亦收藏箧笥间。
明年把扇京尘里，
相忆千山重万山。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1638','将游佘山先寄北野先辈','顾清','明','北山长羡草亭幽，
有愧山灵欠一游。
明日扁舟下横浦，
只愁烟雨漫林丘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1639','北野书约东路见候用前韵','顾清','明','蛇头凤尾好寻幽，
我亦西湾占一丘。
水墨画图三十里，
不妨分作雨中游。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1640','夜闻雪作口占','顾清','明','山水皆言八曲幽，
何人肯向雪中游。
于今便合成嘉话，
不待他年记某丘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1641','和顾德彰閒居四咏','顾清','明','窗日谁添一线阴，
分明此日见天心。
星占紫极先三正，
气始黄钟冠五音。
簪佩晓趋天阙迥，
炉香燕坐草堂深。
君诗欲并三阳贺，
羲画朝来已过临。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1642','和顾德彰閒居四咏','顾清','明','老大惊看岁月新，
天王布德本平均。
年占喜属申连酉，
统法遥从汉改秦。
衔袖几违当殿拜，
披图共指隔年春。
向来光景谁能再，
敢复流连负此身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1643','和顾德彰閒居四咏','顾清','明','流金破肉总鸿钧，
十月由来是小春。
应为几年阴作沴，
故教残岁物回新。
朔南自古殊风气，
刑德于时有屈伸。
閒客未知调燮事，
愿因和煦幸罢民。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1644','和顾德彰閒居四咏','顾清','明','前推无合后无离，
并戴圆穹履厚基。
毕竟谁形复谁色，
怪来相迕适相随。
短凫长鹤宁为病，
秋菊春兰各一时。
试问阳坡两黄犊，
还思清庙作纯犠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1645','腊月十二日宝善堂上梁书示儿辈','顾清','明','此堂成后屋俱新，
忆旧看新一怆神。
总谓承恩缘小子，
岂知馀庆自先人。
爱隆手足延殊姓，
让洽家庭及四邻。
此是小年亲目见，
万金留汝付儿孙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1646','癸酉正月陆时敏以诗赠行次韵','顾清','明','客途南北几暄凉，
又见旗亭柳色黄。
往事尽随春物变，
离情直与暮云长。
人将黼绣轻韦布，
我视江湖只庙廊。
昨夜小斋清梦里，
一编还共短檠光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1647','与文瑞天民会散不寐用定庵丁卯赠行韵','顾清','明','岂有谟谋益治安，
又将离别间交欢。
江湖十载头看白，
风木中宵梦已寒。
病骨可堪仍远客，
薄才犹喜是閒官。
南村花竹西庄柳，
何日归来曳杖看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1648','定庵用壬申寿诗韵赠行敬和','顾清','明','小车不肯驻山庄，
短棹依然傍野塘。
忽听骊驹歌柳陌，
似从鸣鸟集梧冈。
仙龄九十春犹浅，
客路三千里更强。
何日朝簪能谢却，
归来先诣郑公乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1649','除暴行寿子乾太守','顾清','明','五更梦虎方说虎，
天明馈肉来使府。
惊喜出门呼问故，
府兵杀虎如杀兔。
星流一矢镜眸破，
电激双矛夹心膂。
咆哮欲起蹋两股，
锦绷就舁气犹怒。
去年海门妖血腥，
今年西江犹弄兵。
使君四境贴以宁，
分明此物来象成，
有吾梗者残其形。
书生方拟趋神京，
乡园回首坦不惊。
何以报君双兕觥，
愿君百福仍千龄。
保我民物跻升平，
春田更赋驺虞行。',NULL,'','{"preface": "二月十七晓梦虎入门甚恐方言于家人而闻府中得虎已而太守喻侯命吏以肉馈夫虎猛而暴物其象为盗兵人之所甚恶也猛虎就戮此盗息民安之象人之所甚乐也除民之所恶以全其所乐此仁人之事得寿得福之基也越七日为侯生辰乃作除暴行俾从伶歌以为寿云", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1650','圌山长甚出孟渎即见之舟人呼为随山谓连绵不断若随人上下也阻风泊一夕','顾清','明','青山傍我舟，
势若随人去。
因之得随名，
万古滨江住。
我来潮正落，
龈腭尽呈露。
仰攀鱼龙窟，
凛有覆压惧。
登高足力倦，
望远关百虑。
重来复何时，
记取停舟处。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1651','题陆文质云槎卷','顾清','明','仙人乘槎真有无，
晴窗拭眼开新图。
新图只尺意万里，
云涛烟浪相萦纡。
烟云萦纡望不极，
中有兰舟一叶荡漾疑凭虚。
仙翁长髯紫霞裾，
少年早侍红云居。
红云晓趋误一蹶，
三年谪诵轩农书。
下方夭札帝所闵，
翩然复此来清都。
东浮玄洲掠蓬壶，
西历翠水经天衢。
背挽北斗招黄姑，
银潢俯弄明月珠。
青烟九点嗟尘区，
梅花烂漫三江隅。
平生缪识兰台儒，
结习未断蚩泠符。
官舟风雨夜深卧，
犹有远梦来催逋。
数行一笔尚可想，
银钩间错珊瑚株。
张骞浪语空片石，
屈子远游终旧闾。
君才岂必谢时辈，
十年早已歌归欤。
向来汗漫等鸿迹，
此日逍遥同泽车。
升天入地岂异路，
流行坎止真吾徒。
君不见行人倚棹汶河上，
回首烟江思钓鱼。',NULL,'','{"preface": "此卷留子斋中久矣北上倥偬携之以行夜泊赵家村梦云槎督趣甚急书数行而寤髣髴可想遂足成之而关河羁旅行云倦鸟之怀略于此具矣先生览之宁无亦怅然矣乎四月十五日", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1652','过东昌访前贰守郝公适公生辰赋此为寿郝在松职专治水守廉奉公今不易得也四月二十一日','顾清','明','别驾当年治五茸，
苞苴无迹稻田丰。
每从父老歌遗爱，
何意轩墀拜下风。
鹤骨未嫌金带重，
凤雏还拟碧霄翀。
葵花榴萼知人意，
相及生辰满眼红。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1653','张虞咨以南京左军都事满考乞致仕升鸿胪寺丞南归会于崇武驿托附平安有感书赠','顾清','明','少保清风激懦夫，
家声不忝又鸿胪。
宠光再锡传弓里，
世味三年染鼎馀。
南浦风烟增怅望，
西亭竹树想扶疏。
何由便得从君去，
免向平安问鲤鱼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1654','五月八日书事','顾清','明','紫殿朝回白玉堂，
常时鹓鹭俨成行。
愁来隐几西窗下，
欲起孙通拜奉堂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1655','五月廿二日马上作','顾清','明','新雨长安道，
行行爱好山。
美人何处也，
骑马又空还。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1656','合州训导丘陵资阳训导徐泰皆贡自安宁持原复提学书来临别各赋一诗为赠泰之先吾华亭人也','顾清','明','万里谁传北海书，
碧鸡山下有双鱼。
归装带得诗盈卷，
不遣空行到石渠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1657','合州训导丘陵资阳训导徐泰皆贡自安宁持原复提学书来临别各赋一诗为赠泰之先吾华亭人也','顾清','明','西州文学故乡人，
京邑相逢意自亲。
归见邺侯烦致语，
江湖情事若为伸。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1658','涯翁六十七岁寿诗','顾清','明','玉堂黄阁四朝班，
甲第安车未老閒。
名姓儿童传海外，
文章琬琰遍人间。
情悬北阙时占岁，
家近西城饱看山。
自是皇穹寿平格，
不烦大药驻朱颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1659','赋荆树同春送顾文明','顾清','明','共爱君家好弟兄，
两株荆树一庭荣。
秾华正似提孩日，
扶倚还同急难情。
绕砌芝兰添秀色，
并巢乌鹊助欢声。
新诗不为将归赋，
传与乡邻作美评。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1660','苦热行寄傅北潭尚书','顾清','明','苦热不可耐，
触事增烦忧。
烦忧将柰何，
怫郁汗交流。
解衣坐盘礴，
四顾靡所投。
起步望北潭，
想见林居幽。
绿树交夏阴，
清波映浮鯈。
于焉赋归来，
俯仰百虑休。
男儿江海心，
所至希良游。
轩裳亦何有，
庶以平生酬。
熊掌既我有，
生鱼复焉求。
天风日暮起，
朱光顿然收。
华月流前庭，
碧云淡西楼。
且复一尊酒，
吾道付沧洲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1661','李太史宗易母恭人边氏寿七十','顾清','明','夫君东海接棠阴，
令子西垣早盍簪。
纪德未惭群彦后，
升堂已是十年心。
尊中月滟秋容满，
诰里鸾回御墨深。
向夕后堂歌吹沸，
锦绷重抱玉森森。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1662','东城夜归与孚若联句','顾清','明','城上月初起，
马头尘不飞。
天开万里碧，
漏出九门稀。
衢路人欲静，
云林僧未归。
谁知玉京地，
此夕共清晖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1663','送沈东溪告归长洲','顾清','明','宦途南北事多违，
几日相逢又送归。
官好旧坊初视篆，
病来新带总添围。
天连茂苑三江近，
水绕漳河一雁飞。
莫谓鲈乡便堪老，
禁中朋辈十分稀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1664','宗易西园会散作','顾清','明','西园日落更留宾，
醉别何曾谢主人。
犹忆午风亭上坐，
草香花馥似深春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1665','拟归','顾清','明','朝出江南耕，
暮归江北休。
南北十馀里，
往来一叶舟。
情欣农亩谐，
迹与林塘幽。
田父荷锄来，
立语依清沟。
谓言今岁占，
禾麦皆好收。
内翰能不嫌，
社鼓乐田头。
我本农圃人，
迷涂始回辀。
同心不待召，
同气自相求。
勤苦谢父老，
相依愿千秋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1666','与李仁仲副使酌别','顾清','明','杏苑留题一字行，
玉堂收卷亦联名。
流云逝水惊浮世，
尘榻虚窗又短檠。
诗律看于前日细，
宦情尤觉暮年轻。
盘江只尺回翔地，
肯为临岐白发生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1667','李太夫人麻氏寿八十','顾清','明','高堂秋色避春辉，
四坐金绯拥绣帷。
宝副六珈明䌽翠，
锦袍双鹤动烟霏。
青云并见诸孙贵，
黄阁新迎驷马归。
愿学鲁人歌燕喜，
百龄长得奉音徽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1668','九月十四日赵尔锡西庄泛舟和涯翁韵','顾清','明','胜会复佳辰，
溪山汗漫身。
谁能百岁健，
不放两眉颦。
展席云当树，
回舟风起蘋。
谢公多逸兴，
归榻更留人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1669','九月十四日赵尔锡西庄泛舟和涯翁韵','顾清','明','重到曾游地，
浑疑梦里身。
树看前日大，
眉共一时颦。
杖几分林樾，
壶觞间渚蘋。
锦囊归路远，
落日更思人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1670','九月十四日赵尔锡西庄泛舟和涯翁韵','顾清','明','好在邻庄树，
亭亭玉立身。
独游无我拒，
往事复谁颦。
山果红疑橡，
汀花白是蘋。
板桥深涧里，
应有武陵人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1671','双节堂为郑立之参议赋','顾清','明','姑之心，
冰与清，
妇之心，
玉与贞。
谁知贞玉与清冰，
两世一门双节并。
双节并，
两心毕，
百年秪为三泉日。
三泉相见堪一莞，
葛源之流今日远。
君不见州司举例表门楣，
双节遣孤同一辞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1672','归善唐汝达尝侍其先君教华亭京邸相逢恍如一梦于其赴铜鼓学也赋以赠之','顾清','明','怪底相逢熟姓名，
春风曾及见趋庭。
八千里外身如梦，
三十年来鬓未星。
剩有书香留仕版，
不将尘鞅愧山灵。
湘南风月堪娱弄，
可复怀人到鹤亭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1673','周伯明出按山西有纸屏留师邵御史家尝借用之上有二月十九日与曹孚若联句次韵','顾清','明','柏台春半气犹寒，
柱史新除旧姓桓。
列岳望风奸吏竦，
清尊对雨故交欢。
词华此会真三绝，
邻曲何因忝二难。
兴到不知貂续丑，
月明犹拂素屏看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1674','送汪器之太史赴南京司业','顾清','明','汪家兄弟皆奇才，
联飞齐上黄金台。
驰声东观二十载，
一官不调众所猜。
朝来忽报除书下，
却指南雍问官舍。
雁行分飞心万结，
聊复对床相慰藉。
白楼兄行复情亲，
聚首一堂春日温。
岂徒文字破落莫，
直使风俗还真淳。
官河水寒冰欲结，
车轮已驾不可脱。
试问功名际会难，
何似别离情更切。
江东山水梦游中，
故人更思罗与丰。
因君寄语翻作恶，
目极江云千万重。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1675','哭怡庵先生','顾清','明','手拆乡书泪满衣，
西风落木正离离。
谁知总角横经子，
便到苍颜哭寝时。
儿女有情知眷恋，
门墙无地答恩私。
马驼原上青荧石，
傥许南容赞一辞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1676','陆玉厓讣至','顾清','明','旧宅频过有所思，
耿兰书到一沾衣。
回看别路音尘尽，
独立西风鬓发稀。
不逐青阳媚桃李，
独馀晚节照金绯。
九泉二俊如相遇，
应恨不同公早归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1677','十二月朔郊坛候驾作','顾清','明','季冬初吉已条风，
圣主严禋下法宫。
云覆玉衢阴不动，
日升旸谷晕微红。
十年海宇怀生息，
乙夜精诚彻昊穹。
词苑小臣新扈从，
几回翘望五天中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1678','桧亭示和涯翁慈恩寺二诗次韵奉答','顾清','明','慈恩寺前海子头，
谢傅锦衣怀昔游。
委巷曲街人尽改，
石桥斜日水还流。
山林本是当时意，
霖雨何期此日收。
莫唱阳春满都下，
明朝传入凤凰楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1679','桧亭示和涯翁慈恩寺二诗次韵奉答','顾清','明','宝坊高处凤城头，
山色湖光引胜游。
山作青龙平地起，
湖分白练绕城流。
觥船屡向松阴泻，
棋局长教月下收。
回首车尘红十里，
都人应起望仙楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1680','陆水村母淑人寿八十','顾清','明','甫里仙人姑射姿，
平湖楼阁自瑶池。
帘间绣帔金钗拥，
天上斑衣玉带垂。
倚户目随江路永，
称觞心逐海云驰。
岁寒风格长生信，
只有梅花最得知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1681','刘参议维信赴广东索诗未及赋而其子应占入翰林因以寄贺','顾清','明','使节初传五岭秋，
郎君又报上瀛洲。
书香父子贤相继，
文学朝廷宠更优。
到处江山争送喜，
向来烟雨莫深愁。
旬宣益重酬恩地，
只尺薇垣即凤楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1682','铁柯为刘与清司寇赋','顾清','明','万牛鼓橐冶不销，
万山积雪冻不凋。
疾雷动地风倒海，
亭亭百尺撑云霄。
老夔却顾走百里，
鸱鸢蝼蚁不敢窟穴安敢巢。
铁之柯，
谁可拟，
秋台老卿古柱史。
麾之不去招不来，
骨力风棱正相似。
君不见龙之年蛇之祀，
奸臣窃柄天下靡。
天下靡，
此老挺立风尘里。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1683','除夕谕病齿','顾清','明','五十三脱齿，
久知非少媚。
明晨复加五，
岂复为尔讳。
尔家已漂摇，
尔意独濡滞。
去尔非吾情，
虐我宁尔利。
尔职在咀嚼，
兹事久已废。
牵联两不忍，
无乃并为累。
山石有时泐，
天星有时坠。
矧我露电姿，
而汝复予寄。
截肱斯壮夫，
恋栈非良骥。
挥手谢罗千，
勇决真吾契。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1684','浣溪沙 庚午二月廿二日书感时水后疫疠盛行守臣美迁去部使者方加税督责甚严','顾清','明','陌上风花半欲飞。
楼头更著筦弦催。
伤心自起探斜晖。
燕子作双翻水去，
蜂儿成阵采香归。
园林谁为管芳菲。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1685','甲戌郊坛分献用三江院长韵','顾清','明','天郊分职限西东，
天路平瞻月在空。
爟火举时纷列宿，
燎烟回处肃泠风。
百神礼秩山川外，
万国春生俎豆中。
遥听广庭金石奏，
似将无悔谢玄功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1686','元夕壶阴石潭会西轩用前韵','顾清','明','浮云海内几西东，
此夕尘襟一笑空。
已放银花开火树，
更邀明月共清风。
江湖地忆他年远，
松柏心知早岁同。
看取白头黄太史，
夜灯方下读书功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1687','送宋舜和参政之桂林兼简时措宪副伯玉亚参','顾清','明','万玉参天说桂山，
好风明月送飞鸾。
官评廿载朝端美，
行色三春画里看。
乡里故人惊会合，
遐方稚子亦歌欢。
公馀为有怀人意，
东北停云日倚阑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1688','施先生希禄佐永州有善政秩满借留入为宗人府经历升知云南姚安府惜其迟暮而喜远人之得所依也作三绝句送之','顾清','明','青衫白发换绯金，
二十年来一日心。
说与南人应鼓舞，
零陵城下有棠阴。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1689','施先生希禄佐永州有善政秩满借留入为宗人府经历升知云南姚安府惜其迟暮而喜远人之得所依也作三绝句送之','顾清','明','三月都城日日风，
尘埃不见小桃红。
青山满目看行色，
一雨朝来秪为公。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1690','施先生希禄佐永州有善政秩满借留入为宗人府经历升知云南姚安府惜其迟暮而喜远人之得所依也作三绝句送之','顾清','明','燕山立马望姚州，
极目晴云鸟外浮。
记取他年传循吏，
冰天桂海一时收。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1691','武举锁院对月有怀孙贞甫','顾清','明','广庭风柝转三更，
坐拥青绫看月生。
明月故人江外去，
一尊谁与饯东城。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1692','洞庭春宴为徐子容太史母寿用己未送归省韵','顾清','明','林屋山深春昼迟，
桃花成实柳花飞。
里门驻节父老喜，
膝下奉觞游子归。
三洞鱼龙闻广乐，
两峰云日丽晴晖。
不知宫锦筵前舞，
何似当年五䌽衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1693','刘君克柔以亲老思归适有南京尚宝卿之命喜而索诗','顾清','明','申浦风烟接鹭洲，
符台锁钥近龙楼。
几年空作飞云望，
此日真成衣锦游。
潞渚汶河新得雨，
白鱼红蟹正当秋。
都亭极目行尘尽，
恨不相随并䌽舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1694','六月二十五日大雨次卢师邵御史韵','顾清','明','快雨频来溽暑时，
老夫乘兴正临池。
不知马鬣云头泻，
顿有鹅群席下嬉。
到处转输应利涉，
向来枯槁亦堪悲。
商岩孰与颜车近，
恭默方廑九五思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1695','雨不止用前韵','顾清','明','诗成又是雨来时，
次第南池望北池。
屏翳可知阴作沴，
丰隆真以怒为嬉。
颓垣毁壁时惊坐，
下泽高原各自悲。
向晚薄寒侵病骨，
玉楼深处不胜思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1696','雨止十峰有和篇再叠','顾清','明','既雨何如未雨时，
分明涸辙望天池。
商羊不作庭中舞，
河伯谁从海上嬉。
红日伫闻祥凤语，
凉风还为决明悲。
三江昔岁亲逢此，
梦里犹怀痛定思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1697','是夕师邵隔墙送酒侑以原韵三叠奉酬','顾清','明','久雨偏当酒尽时，
庭前空羡雨成池。
美人肯为呼墙送，
狂客何妨秉烛嬉。
我辈笑谈为故事，
邻家舂爨有馀悲。
檐沟又作飘萧响，
明日阴晴且莫思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1698','师邵以墙头过浊醪为韵赋五绝句依次答之','顾清','明','学有卢前愧，
居邻孟氏芳。
此夕添嘉话，
双尊过短墙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1699','师邵以墙头过浊醪为韵赋五绝句依次答之','顾清','明','积雨限来往，
空斋真卧游。
窗中望佳树，
正尔屋西头。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1700','师邵以墙头过浊醪为韵赋五绝句依次答之','顾清','明','美酒饷不辞，
古调高难和。
莫补墙头缺，
且放鸱夷过。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1701','师邵以墙头过浊醪为韵赋五绝句依次答之','顾清','明','有酒呼墙送，
此意殊不恶。
渠将圣者清，
冒彼贤人浊。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1702','师邵以墙头过浊醪为韵赋五绝句依次答之','顾清','明','赋诗兼酌酒，
顾我岂能豪。
味君辞意美，
终日醉醇醪。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1703','师邵复以诗送酒副双尊之句仍以一壶情所寄四句意能多散于篇内因效建除体次第用之招与十峰同饮','顾清','明','一室环潦水，
壶尊空倚墙。
情驰北邻彦，
所谓天一方。
寄我五字吟，
四返意弥长。
能许冲泥过，
多哉招杜康。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1704','七月一日招孚若师邵唐信伯周文仪饮效师邵作','顾清','明','一雨时物润，
壶瓜皆可烹。
情知饱食愧，
所乐在良朋。
寄迹且仁里，
四邻多俊英。
句读脱陈朽，
意气淩高冥。
能来共菲恶，
多谢楼君卿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1705','席间呈诸公','顾清','明','一月十日雨不休，
壶藤瓜蔓生蜗牛。
情知春旱已无麦，
所可复望秋田收。
寄巢燕子湿两翅，
四散飞落谁家楼。
句法清雄卢柱史，
意气剧为苍生忧。
能言有笔断有斧，
多少阴妖凭社丘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1706','题扇用敬所韵','顾清','明','坐爱水木秀，
閒吟招隐诗。
童子趣归去，
前山月上时。
清风消暑溽，
好雨报秋成。
借问林间老，
应无白发生。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1707','雨后独酌得王鹤坡秋夜不寐诗有感遂用其韵','顾清','明','忆昨震雷雨，
势欲倾我床。
我床幸无恙，
己复颓我墙。
羁人多怀思，
异形同肺肠。
与君隔千里，
远迩俱他乡。
霖晦动旬浃，
何由觌天光。
晚酌西轩下，
双鲤忽堕傍。
愿随飘风去，
联坐举一觞。
川流正浩瀚，
我舟不可方。
会合知几时，
仰视云天苍。
还坐三叹息，
孰云归路长。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1708','丁器之将赴建平诵予乙丑赠归之作且问原复动静俯仰十年不胜故旧天涯之感因用原韵作两绝句送之','顾清','明','吴江岁晚促归船，
临发题诗尚宛然。
十载长安如一梦，
又携风月过桐川。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1709','丁器之将赴建平诵予乙丑赠归之作且问原复动静俯仰十年不胜故旧天涯之感因用原韵作两绝句送之','顾清','明','郎步溪头系客船，
家山回首思依然。
公馀剩有登临地，
见说南湖似剡川。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1710','七月十六日乡人会饯两邑新尹于寓舍既罢不寐旋书所感得三十四韵论其格制不足言诗而朴野恳悃拟诸田夫野老之词或可备询访之一二也','顾清','明','吾邦古壮县，
驰望自宋唐。
胜国登使府，
因之启上洋。
官曹虽日崇，
阡陌仍故疆。
宋季已穷蹙，
取民犹甚凉。
一坏贾绵州，
再困朱管张。
浸淫到国初，
乃至十倍强。
浮名累仁政，
有识空叹伤。
宣祖痛裁损，
经纶更文襄。
民力既以纾，
赋入乃有常。
公家无阙事，
帑廪有馀藏。
后来诸君子，
率由如旧章。
至今乡父老，
稽首周侍郎。
粤从近岁来，
智者好纷更。
或云时世异，
古法今难行。
或云广储积，
典守为民殃。
墉坊一以决，
狐鼠恣披壤。
但见私税增，
不闻公廪穰。
己巳及庚午，
诸仓惟栋梁。
苟能实蠲税，
犹或幸小康。
功名掩慈惠，
白纸栽青桑。
都将烟水区，
指作禾黍场。
一字挂经费，
年年理逋亡。
从此遂困弊，
萧然类穷乡。
去夏复霖雨，
湖田尽沧浪。
监司不肯奏，
郡邑徒苍皇。
荒租二十万，
积雪傅严霜。
君子清庙器，
牛刀试新芒。
顾此凋瘵馀，
宜尔劳运量。
立国自有本，
为政自有纲。
不闻慈母子，
饥寒啼路傍。
往迹既非远，
后贤蔚相望。
区区闵人穷，
寝食热衷肠。
愿见德化成，
联飞入明光。
还将镂青管，
浓墨书循良。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1711','寿定庵八十三用十峰韵','顾清','明','绕宅青山列画屏，
磨崖到处可镌铭。
神仙上界犹官府，
尘海中间几醉醒。
高咏雅情追白社，
远书精札乱黄庭。
年来两负中秋会，
遥听笙歌入翠冥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1712','和卢师邵中秋马上作','顾清','明','美人宴罢玉京城，
归骑垂鞭踏月行。
风露九霄纷滉漾，
山河万里共澄清。
却思江路经年别，
直恐冰轮未晓倾。
安得淩风驭仙骥，
桂花相倚看吹笙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1713','崔世兴宅会饯白岩宗伯限韵作','顾清','明','北来行李半图书，
归去诗囊满后车。
云海尚留今夕暇，
弦歌尤爱此堂虚。
谢公把酒梅应笑，
络秀生儿玉不如。
回首旧游心历历，
江风江月正愁予。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1714','赵尔锡席上限韵送前人','顾清','明','莫遣江楼画角鸣，
明朝楼外有人行。
清尊石鼎连宵话，
远道江云十载情。
黄菊尚馀金谷酒，
青山故绕石头城。
遥知落日浮仙棹，
潮送寒流似掌平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1715','送吴栋卿谒告归兼简黄克明胡希文二太学','顾清','明','拟向清江听棹歌，
好官无奈病身何。
思山梦绕沿洄路，
拜阙恩承浩荡波。
灵药可寻宁惮远，
旧书重读不嫌多。
胡黄二俊知邻里，
想见寻常载酒过。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1716','钱御医仁仲父母寿诗','顾清','明','钱铿之孙老不狂，
读书卖药吴市傍。
贤妻八十古孟光，
裙襦相对和以庄。
夜灯密线针如芒，
膝前佳儿五䌽裳。
手携刀圭倚明光，
三年不见心徬徨。
春风回首吴云翔，
尽遣妻孥归奉觞。
要我作歌歌寿昌，
君家恩宠未可量，
老人之寿亦未央。
君不见前星掩耀今十霜，
几夕红光流画堂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1717','十峰约陪喻府君夜坐明日有诗次韵','顾清','明','落叶风轩暮已扃，
偶从华简挹兰馨。
情深旧雨连今雨，
兴洽花瓶乱酒瓶。
化俗无心鱼在水，
翀霄有待鹤梳翎。
醉来更觉盘菹美，
欲向齐奴问韭萍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1718','移灯赏菊和十峰','顾清','明','寒丛可似浣溪花，
也逐银灯上碧纱。
满地月明摇墨晕，
一襟凉气拂霜华。
旋浮绿酒须𢬵醉，
遍插乌巾未当奢。
却恐夜阑人欲睡，
宠光明日拜公嘉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1719','送衍圣公用涯翁尔锡席上韵','顾清','明','振鹭歌残驷马鸣，
蓬山燕罢锦衣行。
西风远道三秋日，
落木洄渊万古情。
别卷荐赓怀麓韵，
前旌应过子游城。
川流夙昔知安稳，
极目晴云到海平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1720','卢师邵宅会文太仆宗严用鸣字韵','顾清','明','童子垂头蟋蟀鸣，
诗联不断酒频行。
青山梦绕来时路，
黄菊香留晚岁情。
一斗尚堪呼我屋，
五言谁可犯君城。
明朝共约慈恩去，
为听骊驹意未平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1721','小轩山颓辇置涯翁园亭石斋少师继有太湖之贻翁喜有诗山成次韵奉贺','顾清','明','颓然不肯驻荒台，
移入名园始快哉。
竦立正当青嶂近，
静观疑有白云来。
池亭绿野添幽致，
斧凿龙门想旧裁。
得与奎章并题品，
也胜尊酒为渠开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1722','辩公以诗谢香次韵却寄','顾清','明','澄湖楼阁带重江，
云影天光动八窗。
髣髴梦中曾一到，
棹歌惊起白鸥双。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1723','辩公以诗谢香次韵却寄','顾清','明','青鞋布袜是家常，
犹欠云门一瓣香。
心识庙湾桥下路，
来时不拟问渔郎。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1724','辩公以诗谢香次韵却寄','顾清','明','谁说诗人鬓未霜，
芬华久矣谢春芳。
灰中芋栗能分我，
只与江湖作漫郎。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1725','辩公以诗谢香次韵却寄','顾清','明','拔足红尘九十霜，
云西自作水仙王。
他年为续三生话，
元老东坡本一乡。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1726','宴别喻府君用定庵韵','顾清','明','诗人且莫赋民劳，
万事分明系我曹。
试看吴乡几蛙灶，
何曾渤海暂牛刀。
官评不爽民心古，
舆论无惭素履高。
已是邦人凝望久，
且𢬵今夕醉松醪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1727','宴别喻府君用定庵韵','顾清','明','客路深知岁晚劳，
檄书先已被东曹。
遗民正望行春马，
归梦犹悬午夜刀。
黄霸赐金偏得厚，
于公车盖转应高。
日斜风力欺人面，
更尽双觚玉色醪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1728','儿子天彝病起有诗报信用韵答之','顾清','明','南州多暖北州寒，
十月黄花锦作团。
独把一枝情万种，
见花何似见人难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1729','儿子天彝病起有诗报信用韵答之','顾清','明','薄晚天风特地寒，
小窗思汝坐栾团。
医方可是全无效，
却是寻方对病难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1730','儿子天彝病起有诗报信用韵答之','顾清','明','霜月中天树影寒，
绕阶风叶走团团。
此时独坐心千里，
谁信来难去更难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1731','儿子天彝病起有诗报信用韵答之','顾清','明','怒作火炎忧水寒，
昆冈成炭水成团。
须知医学通儒学，
两字功夫养性难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1732','和陆时敏客中写怀','顾清','明','隔墙车马涨红尘，
睡起东窗一欠伸。
朝谒懒从多病得，
笑谈情有故乡真。
汀花岸草牵心远，
社燕秋鸿过眼频。
莫信洛阳春似锦，
洛阳元是一般春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1733','和陆时敏客中写怀','顾清','明','蜉蝣岂见海成尘，
尺蠖宁知屈是伸。
自古风花暂时好，
由来傀儡几曾真。
道途信我从桥便，
功业从他览镜频。
幸有一觞堪对举，
不须遥羡隔江春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1734','宣城徐士元浮沈州县二十年始有南台之选其阅历多矣将能为国家建久远之策而不诡于玉石朱紫之辨乎故诗以叙别而不及其他','顾清','明','美人家在古宣州，
少日曾同白下游。
青眼十年重酒盏，
绿波千里又官舟。
江山近识桓生马，
风月平分谢朓楼。
无限离情与乡思，
暮天云树满汀洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1735','朱文宿侍御移居东邻与孚若过访席间联句得二韵明日足成','顾清','明','莫厌移居客过频，
为君深喜得芳邻。
诗书二十年前会，
乡国三千里外身。
河水未冰鱼正美，
江船近到酒犹新。
独惭蹇劣非公辈，
还许青云接后尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1736','冬夜四清次孚若韵','顾清','明','未有金犀辟夜寒，
每蒙龙凤赐宫团。
自分玉岭千寻润，
小试春旗一叶单。
屋里松涛从地起，
窗前梅月几时看。
飘然便欲淩风去，
清浅蓬莱水又宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1737','冬夜四清次孚若韵','顾清','明','小阁垂帘夜不寒，
萦空一缕碧团团。
芳菲似与梅风细，
缥缈应怜鹤梦单。
名重水沈催试取，
火微云母自添看。
明朝满眼金炉畔，
朝退还携两袖宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1738','冬夜四清次孚若韵','顾清','明','楸枰的历晓星寒，
熊虎貔貅各就团。
稍出偏师当一面，
从教空国战三单。
雄雌汉楚危时决，
黑白商颜静里看。
自是人间有机械，
先生心事本来宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1739','冬夜四清次孚若韵','顾清','明','灞桥驴子雪冲寒，
东阁梅花玉作团。
思入空云千态变，
巧争天女一丝单。
芬华肯逐当时好，
真相还应具眼看。
尚有一篇烦束晢，
玉缸春酒夜来宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1740','十二月一日寄书天彝有感用煮茶韵','顾清','明','一冬今夕始知寒，
起斲清冰试小团。
水品无劳问鸿渐，
火攻聊欲效田单。
肠间古字搜应遍，
灰里仙书默自看。
好办百株供岁晚，
归期报与客心宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1741','先母忌辰有感用前韵','顾清','明','游子天涯感岁寒，
梦回清泪欲成团。
人间空想萱枝茂，
地下谁怜雁影单。
衣线密缝犹有在，
儿孙满眼若为看。
三牲列鼎嗟何及，
惭负皇恩似海宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1742','和白楼祭酒游狮子山卢龙观登阅江楼故址二首','顾清','明','金猊作山雄踞蹲，
异境灵踪不尽论。
涧户雨晴浮玉气，
石坛春暖长龙根。
三峰远势分襟带，
九派长流入吐吞。
一自阳春传白下，
几回江月梦黄昏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1743','和白楼祭酒游狮子山卢龙观登阅江楼故址二首','顾清','明','名山巀立大江前，
圣祖宸游地俨然。
宫树戴云犹五色，
涧花回辇欲千年。
楼台极目烟中市，
犀象连舻海外船。
无限平生登览意，
苍崖须继白楼镌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1744','谈以嘉寄友山墨竹求贞庵诗','顾清','明','众水必返壑，
万木终归根。
乾龙抱四德，
维贞乃生元。
谈子魁杰士，
诗书富钻刓。
汗漫四十载，
及此见本原。
浪迹混成市，
深居乃丘园。
逝将游化初，
岂止超笼樊。
神交友山翁，
遗墨宝玙璠。
缄题远寄我，
知君未忘言。
长安日出馀，
车马阗朱门。
清言颂夔契，
高步趋炎轩。
纷纷未渠已，
兀兀空自烦。
引领望五茸，
高云碧巑岏。
衢陌转纡曲，
轩窗开晏温。
登楼唤云槎，
隔巷招南村。
逍遥共水石，
啸傲同琴樽。
以兹遂百岁，
谁知轩冕尊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1745','彭城王肃之自分守叠茂擢湖广江西参副入掌京营拜中都留守','顾清','明','天立三京巩帝图，
濠梁千古汉枌榆。
河山结秀犹龙气，
留守承恩重虎符。
万福威名闻草木，
班超功业在羌胡。
他年并入云台画，
争看貂蝉映美须。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1746','奉和涯翁闻雪枕上作','顾清','明','启户儿童有笑声，
一冬无雪雪今晴。
却思丛竹应薶没，
戏剔残灯与斗明。
江上小舟还自汎，
屋头春鸟为谁鸣。
轻云薄日新题句，
总是商岩未了情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1747','寿王艾坡','顾清','明','西湖东畔瓮山阿，
灵草年深绿满坡。
林壑为公增媚妩，
杖藜终日共婆娑。
天生寿骨如彭祖，
人道医名似华陀。
闻说新庄更幽胜，
一尊还许醉烟萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1748','和施聘之十五日退朝作','顾清','明','汉阙朝回地，
蓬山雪霁天。
凤瞻云外辇，
雷想殿前鞭。
绿漾铜池水，
青浮绮陌烟。
太平公等在，
未可让前贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1749','送陆时敏分教建安','顾清','明','怡柑堂下菊花前，
把酒摊书四十年。
感旧不知吾老矣，
忆归翻为子欣然。
吴山越峤行千里，
云谷沧洲赋几篇。
往问诸君定相识，
苍崖似有姓名镌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1750','长安新街成次师邵韵','顾清','明','七宝宫城玉斧修，
斩新天路快同游。
平看白日行龙角，
近觉青山在马头。
禹甸会来凡几译，
康衢歌罢已千秋。
何当四海均如此，
水宿云飞各自由。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1751','翰林斋居和十峰听琴二十四韵','顾清','明','王春重禋祀，
斋居百工休。
寥寥古槐厅，
无风亦萧飕。
落日众鸟归，
感我林居幽。
起步视天宇，
明星一何稠。
赋形穹壤间，
岂不诚有由。
鸣凤跂阿阁，
凫鹥散沧洲。
云鹏与斥鴳，
各自从其俦。
与子昔少壮，
挟书隘乡州。
坐谈轻白璧，
高步希丹丘。
虽怀黍稷愧，
稊稗亦已秋。
策名二十载，
实也非吾仇。
重来岁云暮，
庶以追前游。
卜居幸仁里，
款洽皆名流。
侧闻官评美，
信尔学殖优。
载观听琴作，
骚选合并收。
朗吟向清夜，
何止消百忧。
惟此清庙器，
流传自虞周。
南风既广大，
岐山亦优柔。
共惟千载意，
历历心与眸。
筝竽乱人耳，
此物委道周。
不逢君子徒，
竟作空山舟。
朋游本沙聚，
岁月亦川流。
钟子既长往，
雍门今白头。
惟有十样笺，
可以修龙楼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1752','西轩夜坐各赋一物孚若得瓷瓯师邵牙箸文宿银𧣴予得红烛','顾清','明','停停双红烛，
照此清夜阑。
主人为无寐，
佳客得尽欢。
玉虫落金钗，
绛蜡萦铜盘。
愿言四座光，
昭我一寸丹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1753','庆成宴上作和伯明侍御','顾清','明','郊禋又喜一番成，
金殿晨开淑气迎。
风里旌旗飏日彩，
云中金石应春声。
十年正德当熙运，
万国倾心仰圣明。
既醉有诗还索和，
并将无逸颂升平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1754','承天门迎驾和九和殿讲','顾清','明','燔燎中天报礼成，
六龙回首万人迎。
天应不断酬丰岁，
臣也何惭继颂声。
五色画旗风里掣，
九斿云䍐日边明。
群公不用频瞻望，
皇路年来似掌平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1755','再和九和宴上作','顾清','明','紫坛殷荐九功成，
黄屋初筵百福迎。
千羽尽消豺虎气，
箫韶齐作凤凰声。
条风暗逐龙楼转，
迟日偏当黼座明。
报与万方须鼓舞，
泰阶连夜十分平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1756','次韵伯明谢九和灯圆','顾清','明','火蛾市里珠论斗，
面茧筵中芡满盘。
犹记薰风初作穟，
不知春雪解成团。
圆疑藻井重光漏，
美在灵砂一粒丹。
食罢乡心渺无赖，
江楼灯月好谁看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1757','待隐园为邃庵冢宰赋','顾清','明','先生奇才天下闻，
先生早达非隐沦。
名园十亩手自辟，
远意正在桑榆曛。
苍生日夕要霖雨，
碧山岂得留閒人。
君不见晋公绿野晚始就，
魏公老圃当秋芬。
人生适志亦有日，
弹丸鸮炙空劳神。
隐待园，
园待隐，
尘海茫茫几时尽。
会须重梦竹间翁，
烟雨春风谢招引。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1758','天秩读书灵济宫有怀','顾清','明','明灯照尊酒，
举觞情不怡。
去尔复几远，
而当怀别离。
男儿四方志，
问学乃镃基。
弱龄逝已迈，
盛年方及期。
离忧与志养，
轻重理不疑。
仙宫昼无人，
况此良夜迟。
清心照千古，
澄虑彻万微。
岂徒美藻翰，
立诚其在兹。
我壮已失学，
守官愧无为。
庶几子复孙，
努力酬恩私。
体我对酒意，
惜汝当春时。
无令金根子，
空负城南诗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1759','分得铁面送施聘之南巡','顾清','明','使君清冰心，
其面乃如铁。
冰心与铁面，
表里双映澈。
鮀朝莫我媚，
贲育莫我折。
端如九鼎峙，
神奸过而灭。
又如明镜照，
百里见妖孽。
前年按东关，
边圉方狡猾。
闻声已宵逝，
况敢𠞓旄节。
今年复何事，
豸角指山越。
朝辞诣阙下，
风采动班列。
想当顾盻间，
狐兔已无穴。
颓风煽末世，
澜倒不可截。
群情爱软媚，
众目憎泠洌。
安得公百辈，
共把霜台臬。
枭除凤乃至，
莠尽禾始活。
君心与君面，
天为苍生设。
往哉慎所向，
嚬笑有窥窃。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1760','观梅奉和涯翁韵','顾清','明','雪深江路记横枝，
二月京城始见之。
远客有情频借问，
孤根异土不同时。
修篁此日方求友，
秾李当年亦费诗。
应是晚风偏爱惜，
故飘香蕊落金卮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1761','扶风令','顾清','明','扶风有健令，
战死略阳城。
略阳岂无令，
城破俨冠缨。
飞章报主帅，
尽掩张巡名。
天监日月昭，
狐兔可逃刑。
下诏赠官爵，
推恩及孤𡞦。
忠愤一以雪，
义声若雷霆。
回看略阳子，
澌灭无留形。
生世岂不死，
所贵死有称。
漠北拜苏武，
陇西惭李陵。
我歌扶风令，
永激晋代英。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1762','赵恒斋挽诗','顾清','明','问族王孙贵，
名家理学宗。
黔江初振羽，
稷下晚疏封。
馀泽流忠孝，
隆恩贲始终。
西山春草合，
无地蹑仙踪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1763','闻刘南村将至先寄','顾清','明','正喜床头新酒熟，
忽闻江外故人来。
不知灵鹊谁传与，
闹乱檐前日几回。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1764','次韵石东滹都宪咏台中松竹二首','顾清','明','傲霜凌雪到参天，
曾见春花几度妍。
光引赤墀朝上日，
秀分苍柏晚来烟。
人疑灵物风雷变，
我视孤根铁石坚。
何待他年歌蔽芾，
大夫新律自超然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1765','次韵石东滹都宪咏台中松竹二首','顾清','明','抚遍檐松偃蹇枝，
小窗惊见玉参差。
却看尘土无容地，
似与琴尊有素期。
声散午风醒客梦，
影分凉月动吟髭。
虞庭正议箫韶事，
莫遣伶伦左右知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1766','张麟庆泽堂','顾清','明','江水东流入海深，
水边华构百年心。
行人未识君家世，
看取堂前乔树林。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1767','题画','顾清','明','小艇临江岸，
纶竿只漫垂。
无鱼亦归去，
不到雨来时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1768','与南村夜话用周伯明韵兼寄时行','顾清','明','江海重来二十春，
中间人事几回新。
朝端我正怀莘老，
谷口谁当画子真。
吟倚石台云绕足，
醉褰风幔月迎人。
扁舟便得从君去，
先过张翰觅紫莼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1769','南村归兴十首','顾清','明','思家千里梦，
恋阙万重心。
欲去频回首，
烟霏满上林。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1770','南村归兴十首','顾清','明','岸添山雨阔，
帆送晓风轻。
利涉从兹始，
遥遥思帝京。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1771','南村归兴十首','顾清','明','云生岱岳顶，
秀结鲁城阴。
仰止嗟环辙，
千秋万古心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1772','南村归兴十首','顾清','明','奔流形道体，
绝壁见神功。
去去吾休也，
危途一梦中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1773','南村归兴十首','顾清','明','纶钓贫难忍，
王侯贵不终。
江边有行客，
归兴十分浓。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1774','南村归兴十首','顾清','明','自有两山来，
几人此经过。
青山默无语，
识人知最多。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1775','南村归兴十首','顾清','明','携将双凤团，
来试九龙脉。
临流啜花磁，
更忆长安客。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1776','南村归兴十首','顾清','明','倚棹虹桥下，
凉风吹葛巾。
家山看渐近，
鱼鸟自相亲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1777','南村归兴十首','顾清','明','扁舟下三泖，
试拂旧纶竿。
鲈鱼三尺雪，
飞上水精盘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1778','南村归兴十首','顾清','明','田园正收穫，
行李忽在门。
此乐不可说，
令人劳梦魂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1779','前题次十峰司宪韵','顾清','明','锦作坡陀绣作丛，
四时晨暮郁葱葱。
梧桐夹道飞丹凤，
杨柳平沙散玉骢。
万岁峰高空翠里，
广寒宫起蔚蓝中。
行人拟得相如赋，
拜赐江南作隐翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1780','前题次十峰司宪韵','顾清','明','南客扁舟欲去时，
好风真与客心期。
云边已似见乡社，
篷底从教卧水师。
行路一番嗟往事，
诗篇几处有新知。
飞来燕子不相识，
却上沙头杨柳枝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1781','前题次十峰司宪韵','顾清','明','篷底哦诗正寂寥，
忽看肤寸起岧峣。
回翔未欲淩霄汉，
津润先应及楚翘。
五彩何年歌烂漫，
九农今日愿丰饶。
河阳旧事还堪省，
几度秋霜换斗杓。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1782','前题次十峰司宪韵','顾清','明','彭城天险亦岷峨，
南北舟航倍几多。
激浪奔流无日夜，
长年三老费撝诃。
试看急缆牵危舸，
何似方塘湛绿波。
欲趁此行铭剑阁，
苍崖先遣百人磨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1783','前题次十峰司宪韵','顾清','明','泗亭秋色已荒凉，
更拟淮阴一瓣香。
飞鸟未随弓力尽，
黄流差比券言长。
荣华自古能谁在，
山水无情默自伤。
一语到君尤足恨，
湖头空负碧霞觞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1784','前题次十峰司宪韵','顾清','明','又复扁舟过此中，
向来明月几弦弓。
山形依旧两眉绿，
江水无尘一镜空。
白鸟去边天欲尽，
青枫落后岁将终。
图经漫有新题字，
一笑烦君问雪鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1785','前题次十峰司宪韵','顾清','明','囊里探春粟粒芳，
松间敲火石泉香。
从来乳酪风斯下，
此日山林意更长。
定有诗篇记清赏，
谁从杖屦合分尝。
吟成更作东南笑，
极目龙山入杳茫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1786','前题次十峰司宪韵','顾清','明','鸱夷不见五湖舟，
香径真成麋鹿游。
客梦几回空历历，
江流千古只悠悠。
天随钓处堪终老，
张翰归期不待秋。
记取一时生色画，
兰桡斜倚白蘋洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1787','前题次十峰司宪韵','顾清','明','湖水泖水分浊清，
渔舟客舟谁重轻。
陆机张翰旧同里，
仙鹤鲈鱼并有名。
长笛数声江月曙，
青山九点暮云平。
一时尽落先生手，
未信烟波也世情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1788','前题次十峰司宪韵','顾清','明','君来三吴占有秋，
君去正及吴田收。
蓑衣但除雨淅沥，
衲袄不怕风萧飕。
烟中白鹤叫野水，
竹间黄耳眠高丘。
眼前此地亦可念，
旧来总属华亭侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1789','初伏喜雨次未斋殿讲韵','顾清','明','老火淩稚金，
乾坤郁炉烘。
田农望时雨，
十候靡一中。
商羊蹋两翅，
玄豹隐尘霿。
苍头挥巨箑，
却立嗟腕痛。
此时天公心，
髣髴为尔动。
驱雷驾长云，
横海截明蝀。
初开瓦沟瞥，
忽作渠溜閧。
淙淙殊未已，
密密欲无空。
儿嬉集堂坳，
万斛试一㔶。
老夫病不寐，
还作江海梦。
青秧间白水，
碧树黄鸟哢。
絺帷凉到骨，
翻恐墨池冻。
起来望西山，
云气犹澒洞。
回翔如有意，
邀我作诗送。
须臾朝阳照，
五彩变龙凤。
岩峦数百里，
眩晃莫抟控。
轻阴拂高城，
馀润溢朱栋。
蔬畦及稻垄，
盎盎流乳湩。
即看禾连箱，
已觉齑满瓮。
坡仙记新亭，
妙语托深讽。
骊珠与肪玉，
至美等儿弄。
此物方施行，
我道堪哀恸。
清风频戒秋，
炎令将过仲。
河流满诸闸，
日夜走方贡。
床头幸有酒，
一笑且从众。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1790','寿定庵先生用周伯明韵','顾清','明','八十从头四见春，
年来诗笔更清新。
不知后进谁堪继，
顿觉仙才自有真。
远道风尘频入梦，
清时林壑也须人。
横塘八曲中秋燕，
正得银鱼配紫尊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1791','悔轩宗伯将赴南都出山水横幅索题上有敬所诗因次其韵','顾清','明','君不见长安列第罗金屏，
山亭水阁纷纵横。
洞门落日烟雾合，
回转天地迷阴晴。
又不见岷江五月蛟龙怒，
雷奔直下空舲渡。
千钧一发寄黄头，
只尺顿殊人鬼路。
川平山远画者谁，
旷朗一洗丰肥痴。
涂行室偃各有适，
此意只许尧民知。
纶竿未挂珊瑚树，
谁识先生会心处。
行看巨舸济中流，
且为江山发新句。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1792','次韵马文明光禄和冯子佩雨中观莲','顾清','明','山花何如水花洁，
江乡又作三年别。
银潢一派写秋光，
绿浪红云几明灭。
孤标不藉阑槛护，
皓质岂因泥滓涅。
江梅冲寒面如玉，
岩松积岁髯疑铁。
清严淑丽各有态，
根性已是多生结。
铜池碧影落天镜，
东轩未到吾能说。
一泓便有五湖意，
造物信可儿童窃。
翠盘跳珠散凉雨，
梦回晓枕声未绝。
恍疑误入水仙府，
万队红妆拥旌节。
鉴湖终期明主赐，
云锦只恐天机撤。
书生俭算亦有计，
胜赏直与吟诗折。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1793','以诗寄师邵御史戏书其后','顾清','明','新诗写寄乐天赓，
斜日虚檐坐晚晴。
莫道閒官无一事，
挥毫还记唱筹声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1794','奉和涯翁西郊观稼是日得乡书有感','顾清','明','江乡为别近三年，
沙水频侵柳外田。
多稼喜闻西郭咏，
清风正想北楼眠。
深村野老藜羹饭，
华屋佳人锦瑟筵。
欲问从来调燮事，
黄花开满夕阳天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1795','杜古狂寿意二首','顾清','明','杜郎胸中富丘壑，
笔墨到处生烟云。
名高价重爱者众，
入眼太半疑非真。
君家此卷得何易，
无乃意气相感此老始肯留心神。
洞门阴阴六月寒，
石角下坠临奔湍。
湍崖逆上不知几百里，
别有琪花瑶草烂漫无由看。
仙人宴坐长松下，
风髯飘萧貌閒暇。
山童拾得紫芝归，
笑指蓬莱问灵驾。
灵驾参差晓未还，
洞庭林屋有无间。
风烟不杂人间世，
云气遥通海外山。
海外相逢今几秋，
蟠桃一熟岁行周。
主人六十正年少，
更约花开寻旧游。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1796','杜古狂寿意二首','顾清','明','东华老人七十强，
全家旧住古钱塘。
湖山绕屋凝清光，
圣人北狩开明堂。
云从金舆飞渡江，
尔来百年双阙傍。
老眼厌见车尘黄，
心思湖山归路长。
高堂晓日悬蓬桑，
湖山忽在堂中央。
瑶台仙人古衣裳，
飘萧鬓发临匡床。
松风吹花满山香，
麻姑远来称寿觞。
身骑白鹿青丝缰，
仙姬一双婉清扬。
金桃玉醴各有将，
青鸾飘摇云际翔。
阿母欲下云苍苍，
老人再拜承寿昌。
吾皇寿域开八荒，
云飞川泳皆康庄。
千载白云还帝乡，
何必湖山怀一方，
呜呼何必湖山怀一方。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1797','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','君书自充腹，
犹有临渊心。
抚卷惜年少，
悠然怀故林。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1798','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','庭下两尊绿，
墙头一竿轻。
无诗可充钓，
积甒空如京。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1799','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','不学雉登木，
还同鹤在阴。
怜材复爱客，
无那主人心。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1800','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','子声岂云恶，
我食惭无功。
怀哉祖豫州，
起舞深夜中。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1801','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','昔贤重交结，
在始不在终。
君看千顷波，
宁作壶醴醲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1802','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','我壮本无似，
况此岁月过。
垂橐视稛载，
其谁得之多。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1803','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','石湖到昆山，
中带淞江脉。
却被幽蓟儿，
呼作三侬客。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1804','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','芳邻盛文会，
老我亦滥巾。
却忆西亭子，
寂寞谁与亲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1805','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','骥子堕地时，
送喜凭邮竿。
闻声想神骏，
举足凌九盘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1806','师邵以南村归兴韵赋邻好十篇奉答','顾清','明','旧卷拟立案，
新题更分门。
何人为剪纸，
一返皮陆魂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1807','师邵每有诗督和甚急九和侍讲尝题其后曰立案而还之闻者大笑既用以赋诗债复次韵嘲之','顾清','明','新篇落笔递酬赓，
不放秋天几日晴。
只有未斋新例好，
且教风雨暂停声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1808','永感堂为同年王威远赋时自郧阳入朝过家上冢','顾清','明','客意逢秋自感伤，
还将此意赋君堂。
儿童岂识晨昏乐，
老大空惊岁月忙。
闾里有人誇昼锦，
乾坤无地答春阳。
惟应一点忠贞志，
青史千秋表义方。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1809','中秋夜客散步月中庭忽忆陆舜卿南归乞诗时正多雨索笔书赠','顾清','明','高飞独鹤想华亭，
出海冰轮到晓清。
林影波光四千里，
看君一路镜中行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1810','送余德辉御史赴安陆判官得月字','顾清','明','郢客歌阳春，
希声入寥泬。
和者不数人，
千秋竟消歇。
君今郢中去，
感我生素发。
冰霜只自许，
白日谁担揭。
驱车涉远道，
万里在超忽。
江乡富兰茝，
庶足充揽撷。
怀人应有赋，
去国那能恝。
行矣欲何言，
赠子天心月。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1811','子元太仆惠小山巾次韵奉谢','顾清','明','苏老危巾四百年，
还从离合见方圆。
临皋亭下一回首，
丛桂林间别有天。
萧散最便麋鹿性，
风流不上绮罗筵。
晚来月照西窗下，
犹恨鬅鬙鬓影偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1812','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','鹤雏新长又生芝，
好事传闻定几时。
曲水坐间流咏富，
小山丛里恨归迟。
清宵见月频回首，
永日停云独举卮。
愿托微芳染馀润，
春风长满谢家池。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1813','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','长因南北叹参辰，
岂谓儿童抗主宾。
地向紫芝篇里重，
人看白发镜中新。
寒林松柏心空在，
清庙圭璋体自纯。
何日西湖能载酒，
为公重庆北堂春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1814','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','园林非绿野，
宾客盛兰亭。
鹤驭迎仙气，
芝房染德馨。
闻歌思水调，
忆别愧山灵。
何日抛尘鞅，
逍遥共百龄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1815','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','换骨灵苗待九蒸，
重闻高咏报祥徵。
凡材岂有青冥想，
仙掌虚烦玉露凝。
云谷放歌从此近，
竹林调舞记吾曾。
画图莫著桃花并，
恐误渔郎入武陵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1816','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','仙人茹五芝，
其一乃瑶草。
薰然蕴灵和，
千秋一飧饱。
青云逗玄光，
独立万物表。
长愿采掇之，
驻此颜色好。
丹青间藻翰，
为我助幽讨。
因之发深悟，
永谢商颜老。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1817','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','蓬门何意长兰芝，
吉梦春来似有期。
乡里衣冠多善颂，
词林珠玉盛传诗。
阶前迥与群芳别，
画里争看五色奇。
为谢东风好披拂，
此根终合在铜池。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1818','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','双飞唳月林间鹤，
九叠蟠云石上芝。
携鹤采芝何日是，
高歌聊把菊花卮。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1819','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','鹤巢山亭上，
其下多紫芝。
芝生鹤雏长，
举目皆天机。
云水非江海，
丹青辞栋楣。
信美不可即，
有时梦见之。
轩裳亦何以，
坐此长别离。
高歌谢园绮，
往矣吾其随。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1820','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','曾入玄光洞里天，
却来亭下兆延年。
林园幸接三吴秀，
孙子惭非二谢贤。
人爱朵云歌郁郁，
鹤惊丛露舞蹁蹁。
薰渐更有诸公在，
谁羡同舟李郭仙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1821','天彝生日乡里诸公会于小园赋鹤亭芝瑞诗各次其韵奉谢','顾清','明','夙抱林野性，
自非鹓鹭姿。
天风一借便，
并入云楼栖。
玉池饮宵露，
珠树扬朝曦。
由来际时幸，
岂谓缘德滋。
嫖姚不顾家，
千古称雄奇。
况此事文墨，
曾无筹幄帷。
频年树松桂，
仅与萧艾齐。
痴儿强解事，
徒手搏象犀。
藩墙既自理，
舂锸亦躬持。
遂令三亩间，
童奴日奔驰。
且为息偃地，
敢与祥祯期。
华篇竞藻饰，
嫫母成西施。
缅怀群仙会，
大火犹未西。
绀瓜落霜刃，
朱李来冰池。
虽微钟鼎盛，
颇与山林宜。
尘沙隔远道，
企望空垂颐。
安石出较早，
渊明归恨迟。
载歌嗣高韵，
正值黄花时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1822','营缮所副姑苏陆云与予同年生而母尚无恙乞归得许以小像索题为书绝句','顾清','明','鹤骨崚嶒鬓有丝，
青衫才著便思归。
高堂幸有亲堪养，
未必功名与愿违。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1823','九日世兴席上有感用齐山韵','顾清','明','城阙秋风木叶飞，
西山落日翠烟微。
园亭到处花自好，
鸿雁来时客未归。
短发有情怜破帽，
长绳无计挽斜晖。
寻常遍插茱萸地，
注目江云空湿衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1824','陆腾远将赴吉安来别因及其乡榜书名之异赋以为赠','顾清','明','灯火秋堂记拆名，
朱衣真有暗中灵。
从知好事皆前定，
果见高文策大廷。
人向官曹论中外，
我期功业在丹青。
西江第一庐陵郡，
且为龙泉试发硎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1825','王参政叔武自太原入朝首索西江赠行之作盖丁夘岁赵叔鸣郎中倡首逋欠几十年矣小轩夜半相对惘然为书此卷末亦因以复叔鸣也','顾清','明','古木回廊玉署东，
几宵相对烛花红。
风云浩荡君能健，
鬓发苍浪我已翁。
到手酒杯浑似梦，
隔年诗债已书空。
贞元旧曲犹堪按，
一笑无忘此会同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1826','王汝楫同年将之武定出留别一章次韵为赠','顾清','明','相期紫陌听鸡鸣，
又报金屏录姓名。
红日正当双阙丽，
碧天遥指片鸿轻。
尝来冷暖应知味，
语到闾阎不尽情。
二十四年青眼在，
一时翘首望君行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1827','崔世兴席上涯翁限韵送圣公','顾清','明','班行连月喜从公，
望望尼山马又东。
梦绕宫墙千里外，
情深冰玉此堂中。
檐花暗结灯前白，
海日将腾夜半红。
不尽一时留别意，
诗成翻恨酒无功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1828','十月十二日夜纪梦','顾清','明','卧游忘近远，
忽在田野间。
田家正收穫，
篱落整且完。
北林五间屋，
西厢亦复然。
纸窗映红日，
机杼鸣关关。
东墙列嘉树，
高廪如丘山。
老稚各有事，
往来纷不閒。
出门唤童御，
小艇维江干。
沿洄迷处所，
中道历险艰。
时闻异人语，
妙理彻肺肝。
鸣鸡忽戒旦，
斗帐梅花寒。
心同理罔间，
时至物有先。
欹枕思往路，
桃源杳漫漫。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1829','有菊为盛德彰赋','顾清','明','江南人家誇有竹，
君家有竹还有菊。
延年一脉是仙传，
不数江头千亩绿。
茅檐萧洒纸窗净，
竹阑宛转苔阶曲。
畦分种别人事尽，
雨沐风晞生意足。
八月欲尽九月初，
霜风渐高木叶枯。
邻家萧条我富贵，
金钗玉佩罗庭除。
湘累放逐怨枯槁，
渊明亦为五斗驱。
南阳老人空寿考，
食粟饮水终痴愚。
不如先生生长太平世，
读书卖药至老不受樊笼拘。
菊花本是萧散物，
亦自乐与君为徒。
自从入京师，
十年无地容挥锄。
盆栽担买不快意，
梦中往往寻郊居。
老去君方厌尘土，
病来我正思江湖。
青山何日遂东去，
一舟定与鸱夷俱。
疏篱矮屋时入眼，
枫叶芦花堪画图。
此时我家菊亦盛，
亭馆亦可罗尊壶。
君来不惮百里远，
我能无酒为君沽。
长安在西向东笑，
只恐春风桃李背面偷揶揄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1830','开化徐进士良节介其友谢锦衣汝容求南峰书院诗汝容故剡人康乐之后也因托以起意','顾清','明','谢家旧说东山公，
徐家南峰亦穹窿。
东山南峰相去不知几百里，
峰头云气往往直与东山通。
前飞紫凤后覆釜，
金钱石佛交帡幪。
其间突兀见精舍，
创始乃自开原翁。
诗书簪组不绝百年内，
至今乡里传高风。
古愚肯构已足尚，
节也中兴还有功。
别来三载劳梦寐，
时与谢家孙子画里心神融。
君不见黄头马下三尺水，
一滴起自天瓢中。
江湖庙廊虽异处，
竹帛钟鼎将无同。
他年驷马入闾里，
远记列斋灯火相对三更红。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1831','华鲸母邹氏挽诗','顾清','明','梁孟高材偶，
朱陈奕代亲。
家人柔得正，
樛木厚无伦。
频藻严时荐，
筐箱遍族姻。
移天情独至，
拔俗见尤真。
几日犹华屋，
中宵忽聚尘。
机丝空寂寂，
环佩俨申申。
彤管嗟终古，
玄堂不再晨。
桂山寒日晚，
风叶助沾巾。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1832','送王良弼赴清流训导兼简薛用章','顾清','明','通波门外石桥边，
坐拥皋比二十年。
战力未输春昼蚁，
宦程聊试越江船。
一尊绿酒城南道，
九点青峰海上天。
为问西楼薛夫子，
肯教尘匣绣龙泉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1833','送阙廷实抚州训导有怀高进之','顾清','明','长忆寻君过石桥，
吴松江上雨萧萧。
十年往事同春梦，
一点乡心逐暮潮。
馀兴犹堪赋芹藻，
好官何必定金貂。
阳关拟唱无人和，
落尽灯花独自谣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1834','冬至前一夕梦书六字甚异','顾清','明','自古元良惟国本，
由来天子重丘民。
升平事业无多字，
把笔翻思梦里身。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1835','题浔阳送客扫雪烹茶二小画','顾清','明','一曲琵琶月满船，
虾蟆陵下玉生烟。
江州便作天涯念，
更有潮阳路八千。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1836','题浔阳送客扫雪烹茶二小画','顾清','明','兰苕无计续鸾胶，
雪水重逢锦帐羔。
合与诗家作谈柄，
老韩谋国未应高。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1837','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','正月吴江好放船，
雪消冰泮水如天。
江头杨柳千千树，
记得东风似去年。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1838','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','二月吴江燕子飞，
河豚欲上荻芽肥。
侬家艇子前洲里，
贪看春波忘却归。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1839','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','三月吴江柳正青，
柳花飞去半为萍。
蔬畦麦陇蔷薇架，
妆点田家作画屏。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1840','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','五月吴江赛屈原，
红旗画楫满晴川。
鸱夷漂泊谁家事，
寂寞胥门一炷烟。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1841','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','六月吴江锦作天，
青蒲绿柳间红莲。
渔郎日见不知爱，
空在江边住百年。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1842','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','七月吴江斗巧天，
鸡头菱角䌽楼前。
青裙荡桨谁家女，
独自中流唱采莲。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1843','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','八月吴江泊钓船，
芙蓉花下绿杨边。
鸳鸯一双堪入画，
只可遥看莫近前。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1844','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','九月吴江空水鲜，
菊花篱落晚霞天。
诗中尽说斜川好，
不道斜川在眼前。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1845','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','十月吴江大有年，
耞声两岸夕阳天。
竞舂白粲输官里，
不遣乡胥恼夜眠。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1846','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','冬半吴江水未坚，
芦花枫叶尚依然。
沙头一派天书字，
知道鸿飞若个边。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1847','旧有诵十二月吴江竹枝歌者戏效之得三首而止十一月廿三夜不寐因足成之诗成梦乘马上曲磴地名湖塘遇小儿杜姓者同行论处世之道甚悉','顾清','明','腊月吴江更自妍，
梅花开近竹林边。
王猷可惜空归去，
不见新晴雪后天。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_1848','吊钱慎庵太医用前寿诗韵','顾清','明','谓君不狂君竟狂，
人间不住归山傍。
七十八年驹隙光，
高论久矣闻蒙庄。
铅砂伏鼎夜光芒，
无乃尸解遗冠裳。
不然白云游帝乡，
斑衣麻绖惨佪偟。
奋飞恨不从云翔，
向来寿斝今奠觞。
痛君不见诸孙昌，
君今神游何可量，
上下四方与中央。
吴山松柏夜有霜，
君归来兮俨高堂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1849','挽慎庵诗成而其配徐孺人讣亦至仍用前韵','顾清','明','吴天岁暮风雨狂，
玉树双陨吴门傍。
前者梁鸿后孟光，
愁云直掩皋家庄。
青天宝婺收精芒，
酒浆麻枲及衣裳。
身在闺门名在乡，
游子秋来思偟偟。
封书几逐南雁翔，
宫醪本拟称寿觞。
恸哭无地歌耆昌，
燠寒旨甘谁节量。
听绝城乌夜未央，
起看明月满天霜，
魂兮何之杳空堂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1850','京城见鲈鲈惟松江有之志异也','顾清','明','墨章银质雪肤肌，
乍见分明忽复疑。
物色旧传乡土重，
气机应与地灵移。
苞间霜橘如相待，
水底丝莼或未知。
莫怪尊前倍惆怅，
病来方有季鹰思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1851','次韵十峰病起写真','顾清','明','不见文园又几朝，
一杯仙露渴全消。
戏书重挽千钧弩，
试饮还欹五石瓢。
吟对馆松犹翠羽，
起看宫柳欲青条。
生绡昨日看图画，
更觉红颜比昔韶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1852','周伯明三锡堂','顾清','明','春色河阳自满堂，
明年豸绣接龙章。
南陔孝子无遗恨，
昼日康侯并宠光。
林屋晚霞明曳䌽，
玉山晴翠落飞觞。
承恩此去应难计，
庭树阶兰日夜长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1853','腊月十六夜','顾清','明','金鼓齐声振羽林，
九重宫殿夜沈沈。
霜庭屡转千官影，
玉宇谁怜万里心。
北雪再看过晚岁，
南冰长是结层阴。
愁来欲共嫦娥语，
又跨蟾蜍下碧浔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1854','月食复圆和师邵','顾清','明','八万神工七宝精，
为谁残缺为谁盈。
苍茫直恐冰轮尽，
次第还当玉座明。
万国山河仍旧影，
中军笳鼓送馀声。
卢仝此夕应无寐，
吟倚霜台到五更。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1855','山妻六十效乐天体','顾清','明','练裳竹笥忆萧然，
又到人间六十年。
我学鲍宣方自愧，
君于桓少定谁贤。
已看儿女诸房满，
始有金珠两鬓全。
白首青山是何日，
举杯重赋鹿车篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1856','山妻六十效乐天体','顾清','明','生朝甲子值元辰，
腊月风光动早春。
算巧适逢三会合，
岁行初届六周旬。
曾闻孟母中闺礼，
不耻韦郎少日贫。
一酌尊前重有感，
几时同洒太姑坟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1857','乡里诸公寄生辰诗各次其韵奉谢','顾清','明','五云阿阁聚鸾凰，
岂有鹪鹩合并翔。
附翼本因风浩荡，
托身多幸世明昌。
频占好梦池生草，
愿比遐龄日在桑。
锦轴瑶篇春拜赐，
玉堂连夜起虹光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1858','乡里诸公寄生辰诗各次其韵奉谢','顾清','明','上堂儿女笑扶将，
犹忆斑衣介寿昌。
远道忽传来锦字，
寒斋惊见起龙光。
山中草树便麋鹿，
天上箫韶协凤凰。
愿把一杯歌引翼，
白头相趁老柴桑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1859','乡里诸公寄生辰诗各次其韵奉谢','顾清','明','高价青山不可赊，
车尘衮衮暗东华。
久𢬵后饮屠苏酒，
无计长留若木花。
未就丹砂怜我老，
有来云锦拜公嘉。
春风忽送还家梦，
一路桑阴夹苧麻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1860','乡里诸公寄生辰诗各次其韵奉谢','顾清','明','望入梅林水月昏，
故人何处倒芳尊。
不将远道忘嵇吕，
每有新诗托孟崙。
朴学半生非世用，
閒官廿载是天恩。
春风又负花前醉，
空玩羲爻六四坤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1861','乡里诸公寄生辰诗各次其韵奉谢','顾清','明','莱子新年舞袖长，
直从腊雪到春光。
相将柳信连梅信，
次第椒觞间鹤觞。
共指松筠能傲岁，
不知苕苇怕经霜。
高秋拟续凌云赋，
题榜还应说仲将。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1862','乡里诸公寄生辰诗各次其韵奉谢','顾清','明','书生事业每多誇，
又向诗篇荷宠嘉。
德耀晚年犹举案，
伯鸾少日本无家。
皇恩未许堂开锦，
命服初看帔有霞。
渡海摘桃非我事，
三年孤负赏梅花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1863','乡里诸公寄生辰诗各次其韵奉谢','顾清','明','吴田秋晚稻如京，
似共痴儿更有情。
瓮里但知春酒满，
人间不管世途荣。
书灯列屋看诸子，
诗卷分题属友生。
得向眼前同一醉，
也应无羡海波清。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1864','除夕用伯明旧韵','顾清','明','天时人事默乘除，
又报春光到客居。
老去生涯随分足，
病来朝籍几行虚。
云中凤阙瞻华表，
赋里山堂想遂初。
儿女夜深浑不寐，
桃符要看晓灯书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1865','除夕用伯明旧韵','顾清','明','懒习平生欠扫除，
时于岁晚惜诸居。
犹嫌韩老送蓝褛，
肯学相如赋子虚。
日月未殊千载上，
阳和又是一元初。
灯花似送新年喜，
忙检东方杂卜书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1866','丙子元日示云孙时其弟应芝将晬阳寅辰录四','顾清','明','春衫簇簇称时裁，
喜道新年上学来。
接得屠苏满堂拜，
不知小弟已先杯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1867','丙子元日示云孙时其弟应芝将晬阳寅辰录四','顾清','明','儿童贺岁满堂前，
一样心情两地悬。
争得便成东下计，
不教凝望五云边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1868','丙子元日示云孙时其弟应芝将晬阳寅辰录四','顾清','明','阳孙今日已成立，
诸弟荆花共一丛。
凭仗春风好培养，
并将书笔继衰翁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1869','丙子元日示云孙时其弟应芝将晬阳寅辰录四','顾清','明','春光又到小楼东，
几日春花烂漫红。
细想别离缘底事，
鲈鱼刚要待秋风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1870','和师邵春日登慈恩寺镜光阁及归途即事','顾清','明','春入慈恩寺，
云楼面水轩。
佛光悬日月，
空界了名言。
兜率吟边近，
沧溟坐里翻。
更须花满地，
车马便应繁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1871','和师邵春日登慈恩寺镜光阁及归途即事','顾清','明','祗园开胜地，
金刹俯层轩。
水月澄空相，
伽陵象佛言。
慈云低树湿，
瑞叶入窗翻。
若论三乘事，
微吟已自繁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1872','和师邵春日登慈恩寺镜光阁及归途即事','顾清','明','佳节重欢娱，
游人胜两都。
笙歌填陆海，
日月丽天衢。
健想凌云笔，
奇观隐市壶。
子桑空隐几，
幽恨可能无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1873','和师邵七言绝二首','顾清','明','病里春光只漫消，
碧山回望转迢遥。
慈恩阁上题诗客，
正得君王放早朝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1874','和师邵七言绝二首','顾清','明','老去文园渴未消，
甘泉春从属车遥。
倦来一枕山窗梦，
满耳黄蜂闹午朝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1875','和伯明岁朝用姜礼部梦宾韵','顾清','明','閒意穷千古，
浮生共百年。
感时争晓暮，
触念有陈鲜。
宫柳思含翠，
庭芸看列钱。
自今赓丽句，
直接赏花天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1876','再和消字韵','顾清','明','几日东风冻未消，
千门柳色望中遥。
椒花柏叶宜春酒，
应待明年共早朝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1877','再和消字韵','顾清','明','鬓雪初凝未拟消，
后来难定以前遥。
寻春走马长安客，
虚度升平又两朝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1878','和孚若闻秋成寄贺郡守喻侯及元旦口占二首','顾清','明','乡书一日两番收，
画出黄云卧垄头。
沾足未论天下事，
萧条顿解客边愁。
舟看西郭千艘拥，
路想南庄一径幽。
喜极病中忘戒饮，
自呼新酿试深瓯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1879','和孚若闻秋成寄贺郡守喻侯及元旦口占二首','顾清','明','松炉残火晓犹明，
高阁微风送漏声。
珠斗渐低长乐观，
䌽云应绕未央城。
青春并阻瞻龙仗，
往事閒思听鹿鸣。
二十五年同仕版，
遭逢谁不愿升平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1880','陈复清挽诗捡讨原大之父','顾清','明','我闻清隐翁，
遗世希由巢。
君清复如翁，
可望不可招。
市城无濡足，
诗书有神交。
妙迹想颜柳，
高吟诵韦陶。
良材陨空谷，
见谓神理遥。
遗编付两郎，
一一彩凤毛。
联飞入天门，
光价动紫霄。
褒章极华衮，
后禄方滔滔。
巨镛靡连响，
浅渚无惊涛。
缅怀神仙驾，
八表同游遨。
时还抚旧乡，
含笑停云旓。
惟有风木心，
终天感飘摇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1881','予既赋京城见鲈有晓之者曰此名大口鱼北州素有似鲈而实非也昔人谓蟛蜞为蟹予何以异焉乃叠前韵','顾清','明','鲤质嘉鱼又鲫肌，
从来物类有相疑。
纤鳞俨带三江色，
巨口都将一字移。
张翰此时成独笑，
陆佃当日未曾知。
蘼芜杜若参差地，
更在诗人细入思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1882','庆成宴和师邵','顾清','明','圜丘礼罢岁犹新，
衢室筵开意更亲。
龙见九重瞻圣主，
鹿鸣三殿引嘉宾。
分曹舞队番番锦，
攒䌽宫花叶叶春。
却忆早时承宠地，
钧天浑似梦中身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1883','庆成宴和师邵','顾清','明','锦筵高列映青春，
宝扇徐开见圣人。
庆礼载承禋祀举，
治功应与岁华新。
须知鼓瑟吹笙意，
正在忠言谠议陈。
既醉有诗还索和，
弦歌一夕遍芳邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1884','初度有感用庚戌岁韵','顾清','明','百年强半一生中，
双鬓频经万里风。
人世悲欢几蕉鹿，
山林日月自瀛蓬。
曾尝蘖檗知甘苦，
为嗅萧兰识异同。
覆载莫酬巾履在，
不胜翘首向蜚鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1885','初度有感用庚戌岁韵','顾清','明','上策难成拟就中，
蹉跎又到落梅风。
向来弧矢羞长剑，
此日江湖羡短蓬。
睡眼不知乡社远，
繇言刚与客心同。
归期未要灯花趣，
自有高飞塞上鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1886','海虞施君精地理卜筮之学别予南去约以高秋会于云间走笔有赠','顾清','明','浮世纷纷未有涯，
著朱骑马遍京华。
相逢尽访君平肆，
归去谁同博望槎。
林下晚风催试葛，
雨前新火待烹茶。
高秋为有扁舟兴，
白鹤城西是我家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1887','和十峰闻西涯赏梅有感','顾清','明','听说梅花百感新，
去年同是赏花人。
病来东阁诗俱瘦，
老觉西湖意转亲。
授简不妨还赋雪，
攀条无计可留春。
何时烟月溪桥路，
斗取筇枝见在身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1888','走笔留汪秀夫','顾清','明','风尘隔绝几星周，
一笑相逢百虑休。
浮世荣华云过雨，
男儿意气鹗横秋。
卞和抱璞终成宝，
李广驰声不在侯。
总角交游閒散地，
未妨三日更迟留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1889','松守喻侯讣至有感','顾清','明','万事无言已盖棺，
蜀江回首是青山。
浮生毕竟谁寿夭，
客路从知有往还。
千古桐乡终祀邑，
他年汉史或须班。
令人转觉巢由贵，
不与醯鸡杂瓮间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1890','送盛有菊良医之济南','顾清','明','卜相无成拟作医，
达人千古共心期。
名家独数中吴旧，
直谊多应我辈知。
今日宗藩宜永寿，
几年朝路惜分岐。
灵光退直从容地，
还对黄花诵我诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1891','三山廖彦正往以新喻司训同校文南都秩满升吉安推官来别得备闻兵兴以来故人行事消息之详且出示其尊人德翁遗像及诸名人题咏临觞永叹赠以是诗','顾清','明','画帘红烛共秋堂，
十载长安重此觞。
往事剧谈悲露草，
新诗传看总琳琅。
江山六一馀文藻，
职事皋陶旧典章。
更喜同官有交契，
并将钦恤赞循良。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1892','送三儿应举予己酉乡试初场前夕梦乘雾登鸡鸣山及半见日出惊寤众以为祥既乃下第而三儿天秩以是日生今二十有八年矣始遣其应举因感前事书此励之庶几不以离忧而妨远业也四月十五日识','顾清','明','云开日出四山明，
忆在金陵梦尔生。
俯仰卅年谈往事，
扶摇今日看初程。
儿童亦解登科好，
老我宁为别绪萦。
若到仲游旧时地，
也应回首望天京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1893','陈丕显以贡入京将还试乡闱阅其近作赋以赠之','顾清','明','每从场屋叹拘缠，
送子临风一怅然。
王路到来长似砥，
圣言何必总如天。
炎风赤日三千里，
夜雨寒灯二十年。
选作上清堪一笑，
也应元只旧时钱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1894','松江歌送吴宿威太守','顾清','明','松江之水清若空，
松江之流浩无穷。
西起太湖东距海，
馀波直去通瀛蓬。
桑麻黍稌夹两岸，
极目四望烟云重。
横塘直浦一百二十交灌注，
往往云雨兴蛟龙。
自从神禹来，
图牒朗昭融。
孙龙肇启号，
伯言继疏封。
李唐作邑元建郡，
遂与三吴齐长雄。
圣朝疆域遍四海，
岁事半资苏与松。
诸贤经济各有以，
蘋藻独荐双崖翁。
我生不及际全盛，
尚见诸仓盈济农。
何人巧作忧民计，
颠倒簿领资顽凶。
徵科岁滋储廪竭，
对面无地寻窠踪。
前年己巳及庚午，
诸湖积雨江发洪。
流尸塞道官束手，
有识仰面吁苍穹。
张公复始喻公赞，
五年补葺无遗功。
衢槐未成京兆死，
拦街竹马悲儿童。
使君五马今复东，
江头父老情喁喁。
望君不来待君久，
眼中几见旌旗红。
老人有怀言莫通，
我歌松江写其衷。
歌声有竟情莫终，
总在使君心耳中。
呜呼安得此江还似双崖日，
归钓鲈鱼作野翁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1895','原复宪使书来称其门下张君某之贤书至而原复已没为之怆然君分教嘉定赋此送之亦以终原复意也','顾清','明','短李书来剩说君，
相逢消息不堪闻。
杏花东国还时雨，
鸿雁南天空断云。
师道本缘天下立，
襟期重感故交分。
瓣香为有南丰意，
应向龙塘吊白云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1896','王廷辅除广东盐课提举有不堪其事之虑赋此勉之','顾清','明','古人重立事，
今人重致身。
功业苟有托，
富贵安足论。
迢迢越王州，
连峰入青云。
岂无近要途，
跋此高嶙峋。
榷海已非古，
严征重疲民。
庙选及吾子，
此意良已勤。
刑罚有至教，
催科有深仁。
金谷诚琐末，
乘田彼何人。
新雨残暑尽，
清风肃衣巾。
缅怀都门饯，
杂遝罗众宾。
而我病莫致，
徘徊独凝神。
挥毫愿有赠，
目送征车尘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1897','读叶文庄病目诗有感','顾清','明','狼籍残书研几偏，
毵毵寒雨北窗前。
客心正似泾东老，
长在池亭竹树边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1898','卫景玉生辰用壬戌岁韵','顾清','明','回首丹梯思渺然，
还从此日话当年。
晓星残月双青眼，
东阁西亭几玳筵。
犹有强弓堪射雁，
可能长剑复凌烟。
仙班次第休重论，
一着商颜已自先。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1899','骢马吟送同年于器之副宪浙江','顾清','明','骢马行，
骨权奇。
连钱被体玉琢蹄，
绣衣五采金带围。
据鞍顾盻生光辉，
临发长鸣振金羁。
振金羁，
向江东，
吴山飞度越岭重。
眼中自不见豺虎，
敢有狐鼠留行踪。
狐鼠空，
豺狼伏，
骢马行，
来乎复。
汉家烽火照甘泉，
昨日单于栖上谷。
范生揽辔，
志在澄清，
我爱张子，
埋轮都亭。
君不见天闲尚有未纯驷，
可使骅骝长地行。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1900','杂书五首','顾清','明','唐家重考牧，
毛仲最承恩。
开筵待宋璟，
速客烦至尊。
宾从满高堂，
日晏湛清樽。
把盏不及釂，
飘风送回轩。
主人不敢讶，
四座悄无言。
何异百鸟群，
仰视孤凤骞。
良史剧善绘，
丹青俨如存。
何当得再拜，
一醒尘目昏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1901','杂书五首','顾清','明','美人鲜妆坐，
膝下锦绷儿。
珍果半衔袖，
黄柑带青枝。
可爱故不与，
绕床牵母衣。
文举方四岁，
掉头扬青眉。
得果尚取小，
焉能为尔嬉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1902','杂书五首','顾清','明','荠堇不同味，
萧兰不共根。
云鹏与斥鴳，
所乐各有存。
本是麋鹿性，
而当絷缨繁。
缨繁已自困，
更使舞当轩。
方将龁野槁，
难报刍秣恩。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1903','杂书五首','顾清','明','抚事意不适，
掩书翻自疑。
皇穹降民德，
圣言岂予欺。
云胡康庄道，
蹶入千仞溪。
皮伤毛焉附，
巢破卵则危。
同舟济江海，
生死理共之。
宁当风波际，
篙楫自纷披。
曲突见谓早，
焦头竟何裨。
永念竦毛骨，
中宵起呼衣。
展转竟达旦，
欲言当语谁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1904','杂书五首','顾清','明','妾本田家女，
出身事蚕桑。
十三学抛梭，
十五成文章。
二十嫁夫婿，
上堂奉姑嫜。
伯姒调鸣瑟，
小姑弄金簧。
清声激四坐，
欢乐殊未央。
回眸忽自失，
羞涩归下房。
明灯发图史，
彤管有遗芳。
先哲岂予侮，
永矢期勿忘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1905','甲戌定庵生日涯翁有八十三回秋月圆之句乙亥仍用韵但改三为四约岁赋一篇今年未及赋而捐馆追用翁意奉补此章僭不自量正可发寿筵之一粲也','顾清','明','麓堂诗例起年年，
八十五回秋月圆。
海上衣冠今洛社，
壶中日月自尧天。
烟霄未远三山路，
锦绣难追十客筵。
试向骚坛论晚节，
此情端合为公偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1906','送冶斋先生孙君能下第南归','顾清','明','东南人物重毗陵，
陆相声华动帝廷。
门下老生惭继武，
膝前孙子解传经。
滦江木叶催鸿阵，
阿阁天风想凤翎。
好约他年话今日，
鹄袍争似柳衫青。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1907','陈约庵诗贺迁官次韵寄谢','顾清','明','紫阁层台矗九成，
人言此地即蓬瀛。
一经佔毕惭粗浅，
十载遭逢荷圣明。
高会想闻乡里盛，
壮图全倚太阶平。
东山不为苍生起，
翻使迂疏浪得名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1908','用韵寿周北野七十','顾清','明','九转灵砂已七成，
仙家犹道隔蓬瀛。
雪中苍柏神逾胜，
竹里黄花眼独明。
松水看于春酒绿，
玉峰遥共海云平。
不知今日雎阳社，
早晚还容托姓名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1909','再用韵写怀一首','顾清','明','秋入乡园百宝成，
老农相忆话登瀛。
浮云直与吴天永，
落日偏依谷水明。
怀土梦归文并美，
升高望远意难平。
寻思张翰成何事，
只为鲈鱼万古名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1910','序庵许分菊促以小诗','顾清','明','买得园亭未有花，
分明秋色在邻家。
酒阑梦醒空惆怅，
犹有馀香袭帽纱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1911','冬夕饯师邵柱史出按西川用子容侍读韵','顾清','明','骢马昂然不受驯，
绣衣清拂晓霜新。
高堂正尔歌眉寿，
远道无劳赋小旻。
到处豺狼应迹扫，
别来山水更情亲。
春风不尽怀人意，
都在青枫与绿蘋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1912','十月六日会同年于城东归途有作','顾清','明','宫槐影里散鸣珂，
还忆联镳杏苑过。
天地百年欢会少，
风云四海别离多。
苍生喜有诸公在，
素食其如贱子何。
相约岁寒期不负，
五湖烟水一渔蓑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1913','桧亭见和催菊韵奉答','顾清','明','绕遍秋城看菊花，
清狂都放此君家。
淋漓醉墨烦教护，
剩费东墙几幅纱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1914','桧亭见和催菊韵奉答','顾清','明','秋花元不似春花，
清冷秾华各当家。
昨夜午风亭上醉，
一般银烛照笼纱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1915','桧亭见和催菊韵奉答','顾清','明','由来雪桧与霜花，
岁晚相看共一家。
乱插满头君莫笑，
几人白发映乌纱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1916','何廷佩方伯临别索诗用珂字韵','顾清','明','门外骊驹白玉珂，
十年南北断经过。
腰犀颇觉君来重，
鬓雪惊看我已多。
诗草正题戎有翰，
烛花休问夜如何。
明朝烟雨潇湘路，
惟见溪翁理钓蓑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1917','庭下决明','顾清','明','独立西风里，
萧然自不堪。
是谁增客思，
呼作望江南。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1918','奉饯壶阴学士之南院兼简整庵少宰白楼太常','顾清','明','十月官河未有冰，
北风清利䌽帆轻。
词林我正惭先步，
学海时方重老成。
六馆旧人怀指授，
三山新赋入经营。
容台吏省皆邻近，
早晚邮筒不论程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1919','蓉溪书屋为金','顾清','明','西川山水天下奇，
绵州更好芙蓉溪。
溪流百里到城下，
上有茅屋临清漪。
长松荫门白日静，
密竹绕宅青春迟。
屋中旧书几千卷，
一一牙签分架垂。
主人家本东州彦，
衣冠世泽闻邦畿。
高门大字榜孝子，
亦有梅屋工文辞。
柯条远布极万里，
书香一脉犹连支。
功名奕叶到孙子，
兰台石室争峨巍。
天机云锦出桑苧，
清庙簠簋资耕犁。
丹青数尺小斋里，
尚想清夜闻吾伊。
平桥曲渚往复回，
林亭水阁相因依。
扁舟泊岸何所待，
溪风飒飒吹人衣。
溪风吹衣人未归，
钧天须人运璿玑。
江湖廊庙本异处，
轩冕山林非一时。
惟有芙蓉最相忆，
开花长满屋东篱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1920','崇府长史王先生珙清壬子荐名时寔预试事往以公事入都索诗为别赋此奉寄','顾清','明','宦途南北叹蓬萍，
一笑翻令别恨生。
三十年来托深契，
四千人里愧虚名。
每从朱邸开鱼素，
如在红帘听鹿鸣。
开道府中无限乐，
主君今日汉东平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1921','赋瑶池图寿滕洗马先生母六十','顾清','明','瑶池遥遥何处所，
乃在昆崙之颠阆风之阻。
琪花瑶草四时春，
白鹤青鸾日翔舞。
西王母，
家上宫，
乘游云，
蹑飞龙。
时来池上燕仙客，
倒影幻入龙绡中。
䌽衣退直下金銮，
门前车马来翻翩。
入门一笑把春酒，
却道画里如堂前。
陶家亲，
孟家母，
图史流传俱不朽。
不知当日寿堂前，
还有人如画中否。
画中堂上竟谁真，
神仙要是古贤人。
不须更问瑶池路，
再住人间六十春。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1922','竹泉为黄克清赋','顾清','明','种竹深开径，
疏泉小作池。
情缘淇水旧，
迹是考槃遗。
渚月怜清影，
林风想渌漪。
暂来还复此，
鱼鸟莫相疑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1923','叶文庄公孙尚源与予居同巷铨授大名府判诗以送之','顾清','明','海内文庄六十年，
玉山回望渺风烟。
范公素有先忧志，
韦相惟馀后嗣贤。
西郭旧游追杜曲，
北州名郡数澶渊。
由来骥子轻千里，
稳上青云不用鞭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1924','壶阴阻冰河下用前赠行韵见寄有悔心焉走笔戏荅','顾清','明','空江一棹倚层冰，
颇觉胸中万应轻。
阮籍不为穷路哭，
冯夷近报水仙成。
清宵梦与群龙伍，
彩笔诗将八柱营。
前日雪窗还独坐，
有人疑是洛川程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1925','壶阴阻冰河下用前赠行韵见寄有悔心焉走笔戏荅','顾清','明','有冰刚欲道无冰，
此意于人亦未轻。
长策正因忙里误，
好诗翻为坐来成。
修蛇已想鳞薶壑，
顾兔行看魄载营。
何以报君堪一笑，
只将春水算初程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1926','除夕望三儿不至','顾清','明','生来长是绕襟裾，
不为功名遣读书。
旅食今宵定何处，
别时初夏岁云除。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1927','除夕望三儿不至','顾清','明','仲冬初日报行期，
任尔留连是到时。
行说坐思缘有报，
当时犹恨报来迟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1928','除夕望三儿不至','顾清','明','少年东抹更西涂，
菽水高堂亦望予。
今日更无人望我，
秪应长是我思渠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1929','丁丑元旦杂书','顾清','明','百里宿舂粮，
千里三月裹。
三飧适苍莽，
既返腹犹果。
云鹏快九万，
斥鴳抢榆可。
玄间函万类，
厖钜杂纤琐。
王公与舆皂，
意适无尔我。
季孙周公富，
参也肘双裸。
当其商声歌，
万物等瓜蓏。
飞鼯笑鸠拙，
蚿亦怜鳖跛。
鹤长断斯悲，
凫短续讵妥。
为谢守株翁，
君计良未左。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1930','东曙寄答去岁生辰和韵之作若不以予言为然者再叠奉酬','顾清','明','一年归计又成赊，
却望春城感物华。
海雁忽来云外信，
江梅应发槛前花。
人将勋业期安石，
我自风流忆孟嘉。
终拟一筇寻老伴，
商量晴雨问桑麻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1931','次韵用常有怀见寄兼送三儿失举还京因以自叹之作二首','顾清','明','茅屋藜灯对雨然，
小桥西畔竹篱边。
天涯莫道浑忘却，
久矣西斋一榻悬。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1932','次韵用常有怀见寄兼送三儿失举还京因以自叹之作二首','顾清','明','休从场屋论功名，
晚达何须让早成。
八十前头看梁颢，
白袍元是一书生。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1933','李谷泉七十','顾清','明','虚皇台殿五云边，
有客閒居七十年。
仙籍溯源来苦县，
家山回首是琴川。
神骖野鹤时过海，
手植檐松欲造天。
昨夜瑶坛霜月下，
焚香犹诵蕊珠篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1934','甲戌郊祀斋居落齿有作正月十二日再落一齿用前韵亦斋居也','顾清','明','痴人老犹童，
览镜思妍媚。
摘白整冠巾，
谓老真可讳。
不知齿牙脱，
还复可留滞。
忆昨尔初生，
玉白铦锋利。
相从能几何，
竟作铅刀废。
得非本根拨，
无乃言语累。
初危冀犹安，
凛凛忧尔坠。
及兹两决绝，
忽若还重寄。
投非东窗梭，
去作下坂骥。
从兹慎语笑，
至理得深契。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1935','二月廿日贡院中作','顾清','明','今日不乐是何辰，
千花万花明上春。
洞庭明月湘江水，
望望风帆思故人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1936','陆希哲下第注临江推官与之酌别','顾清','明','婉娈峰头片玉明，
馀光千古落东城。
才名泮水誇年少，
宦业云衢属老成。
五色共知经眼误，
一尊还许对花倾。
向来万事皆蕉鹿，
听取西江讼理声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1937','先师友兰张先生祠堂落成其子公佩来告将别赋此祠在斜泾之阳超果寺之西南庑即旧之学舍今主僧道俊所作也','顾清','明','萧寺同游五十年，
京华一笑两茫然。
流光如此可复几，
朋辈到今谁更贤。
旧业斋房闻再整，
新祠蘋藻亦粗涓。
临岐不尽追攀意，
总在斜湾落照边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1938','送周成德知养利州壬子同年','顾清','明','古嵩山下一城安，
井落参差画里看。
黎庶几年占得岁，
朱幡此日快凭阑。
才名岂必惭诸子，
忠信由来重百蛮。
合浦明珠连穴乳，
大书行见石崖刊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1939','中元谒陵三江以诗送次韵留别时连雨初霁','顾清','明','逗晚邻钟忽报晴，
已𢬵三日踏泥行。
攀髯空复随鹓侣，
奏赋谁当拟墨卿。
红日仰瞻三殿夐，
浮云莫遣四山生。
奉辞却恐题诗误，
把笔频教候启明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1940','郊行涉淖屡濒危殆晚憩鲍监南斋用前韵','顾清','明','久晴思雨雨思晴，
晴日依然是雨行。
屡涉泥涂愧舆皂，
敢誇轩盖后公卿。
良苗近甸高低满，
王气诸陵日夜生。
细听白头宫监语，
劫灰何必问昆明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1941','拟谒泰陵不果还宿僧房再用前韵','顾清','明','斜日长林散晚晴，
群公西上我东行。
空瞻洛汭歌神禹，
无复甘泉扈长卿。
石马风烟悲古道，
玉衣絺绘俨平生。
愁眠更觉宵天永，
滴尽铜龙未肯明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1942','又绝句','顾清','明','甘雨和风十九年，
群生长养不知天。
桥山厥有神灵卫，
莫问风沙与水泉。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1943','题三江所藏吕纪画鹰','顾清','明','千峰无云秋气高，
独树倚壑风萧骚。
萝茑翳荟青黄交，
飞泉触石迸山腰。
奔流十里怒未消，
绝壁仰视愁𤠔猱。
黑鹰孤鶱不受绦，
砉尔下集疑冲飙。
雉惊兔走鼪狐嗥，
老罴崛强倚窟巢。
呀喙睒目为矜骄，
两雄自古忌相遭。
欲动不动心俱劳，
丹山有鸟文九苞。
梧栖竹食韵箫韶，
朝阳独立万羽朝。
吾欲良工运彩毫，
恰有十幅鹅溪绡。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1944','荐溪宫谕省觐归赋诗末就而别八月七日礼部南斋独坐怅然有怀足成奉寄','顾清','明','铁篴风前早识君，
还从石室见多闻。
圭璋世与连城价，
鸾凤天成五色文。
春酒玉尊催献寿，
夜筵红烛感离群。
停云又入西堂梦，
不道仙凡路已分。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1945','芙蓉书舍为瓯滨宗伯赋','顾清','明','开元寺里芙蓉树，
曾见先生学易年。
好语盛传三策后，
高花独出九秋前。
溪山剩有馀芳在，
霄汉应多别梦牵。
欲识旧题无恙否，
碧纱深护翠蛟缠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1946','定庵八十六岁诗','顾清','明','横塘高宴复今年，
八十六回秋月圆。
霜柏转深云里色，
醯鸡空老瓮中天。
梦随白鹤周三岛，
坐想清风拂四筵。
平格自应天所眷，
寿昌端的为谁偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1947','有怀约斋先生用前韵奉寄','顾清','明','学海驰声四十年，
归来霜月几回圆。
春晖寸草俱无恨，
轩冕山林共一天。
乡论古今西洛社，
寿觞先后北山筵。
题诗转益莼鲈思，
久矣诸公乐事偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1948','膳部主事林贞孚告归为令祖泉山翁寿','顾清','明','我初从仕来京国，
泉翁六旬头尚黑。
明年翁寿八十五，
闻道康强只如昔。
蓬瀛严邃璧水清，
玉衡金钥重两京。
岂直文章师后进，
实有勋华流汗青。
海天诸山玉削成，
重崖叠嶂通仙灵。
高云可望不可即，
时见一鹤横青冥。
西风八月雁南翔，
孙子锦衣称寿觞。
九重似有非熊梦，
还拥蒲轮朝上方。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1949','胡仲申录囚过家索诗为尊翁七十七寿','顾清','明','又是江乡一度秋，
依然霁色满江楼。
缑仙几约吹笙会，
汉使真成衣锦游。
棋局酒杯滋有味，
黄花翠竹不关愁。
横塘八曲传诗例，
次第还应置两邮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1950','庄舜举自京学出教平原予随计时尝止宿其地客途风景宛在目中怀昔感今斐然有作','顾清','明','德州南下路茫茫，
犹记征车驻夕阳。
廿载宦程霜鬓改，
九秋离思海云长。
川原近带齐封古，
芹藻遥分鲁頖香。
梁桷岁寒颛有待，
未须回首问鲈香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1951','惟中太史出示先宪副所得东吴夏卿墨竹为题绝句','顾清','明','太常写竹时，
相向四君子。
悬之白玉堂，
叶叶清风起。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1952','松江判府史君瑭廉靖爱民民亦爱之董漕还便道省亲赋以为寿','顾清','明','洛川老人古耆英，
七十九年生太平。
室中孟光年稍长，
云冠鹤袂长裙青。
斑衣五采双鹭明，
五年从宦江南行。
王程有暇许归觐，
千里周道迂双旌。
江南之政惠以清，
民歌甘棠歌所生。
河阳板舆止偏侍，
亦有具庆无荣名。
洛川之乐无与京，
我作新诗遥寄声。
愿言百岁齐不老，
看取棠阴江外成。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1953','伯畴宫谕登第予同考春闱今年又得其子彦式魁省试伯畴可谓不亡而予亦与有荣矣彦式告归逆妇俯仰慨然赋此为赠','顾清','明','两入南宫二十年，
惯看鹏鹗上云天。
一经不忝玄成后，
片玉还留大宋先。
瀛海木天虚夜直，
彩屏红烛待春筵。
经纶事业今方始，
未学相如驷马旋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1954','忆李文正公次崔世兴符台韵','顾清','明','碧山投老始成游，
总为昭陵土一抔。
片语不留身后计，
一生长抱域中忧。
人非金石谁千古，
世有神仙定十洲。
欲识姓名传远近，
遥天星斗大江流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1955','忆李文正公次崔世兴符台韵','顾清','明','又见青山雪后童，
神游何处蹑星虹。
无金可铸春风象，
有笔难形化雨功。
洛社衣冠觞咏里，
孔庭诗礼笑言中。
追寻不觉成今古，
犹对遗编望小同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1956','百川至海图为太常杨典簿题','顾清','明','百川起西北，
浩浩东南驰。
东驰日夜不一息，
共指沧溟同所归。
昆崙与蓬丘，
相望万里何崔嵬。
泯然一气交灌注，
馀波直浸扶桑枝。
扶桑晓日流虹光，
正照君家清平逸老之高堂。
堂前嘉树俨成行，
红兰紫蕙共芬芳。
十年京国劳梦寐，
一日海上尘襟凉。
翻思年少驰骋日，
却似川流初滥觞。
川流学海竟到海，
君意更比川流长。
百年才半未为老，
浮天浴日何可量。
劝君一卮，
祝君寿康。
蓬莱清浅我不见，
海筹十屋毕竟成荒唐。
但愿清平老人百岁长无事，
与君终日击壤歌康庄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1957','寄王世禄指挥','顾清','明','君来袖里有双鱼，
君去匆匆不办书。
忆别正当梅发候，
相逢长记雁飞初。
淮阴功业人非远，
郤克诗书味有馀。
云路诸公尽青眼，
争教甓社久遗珠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1958','次韵顾德章冬夜失鸡','顾清','明','望断城南尺五天，
赤冠金距故昂然。
江鸥日落犹能舞，
塞马风高不受牵。
飞入五坊应赐锦，
梦回三市已登筵。
明年许我山中去，
烂煮黄肥醉谪仙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1959','葵轩为陈锦衣彦良赋','顾清','明','长安四月花满城，
葵花独自向阳倾。
赫曦当午辉四溟，
垂辉弄影照君庭。
庭下千花团绣楹，
纷如玉节间红旌。
仪鸾退直花下行，
日华相荡锦衣明。
日也有时经洞冥，
此花向日无阴晴。
秋风花谢子还成，
明年向日还层层。
我来看君花正荣，
徘徊轩砌有馀情，
作歌为尔传嘉名。
君不见金张七叶空富贵，
惟有葵心一点可与金石垂千龄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1960','腊日雪次彭幸庵去岁午门燕归韵','顾清','明','瞭然天意不须猜，
向日同云晓未开。
瑞木又飞前度叶，
金茎不赐去年杯。
愁心欲遍天涯草，
远信谁传陇上梅。
极目贺兰山下路，
几时风雨净氛埃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1961','三叠东曙麻字韵','顾清','明','酒熟床头不用赊，
美人何处诵南华。
千门欲动王孙草，
三径犹存处士花。
林壑几时还窈窕，
乾坤今日本清嘉。
閒来会得环中意，
未遣愁心作乱麻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1962','看牲回闻赐迎驾衣喜而有作','顾清','明','紫坛黄道直如弦，
玉宇清宵月正圆。
北向星辰环斗极，
南来骑火烛天田。
礼从涤濯严先戒，
官忝寅清愧昔贤。
独喜回銮消息近，
锦袍明日赐楼前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1963','送李龙臣分教吉安','顾清','明','故人选作儒官去，
还自当年一布衣。
老矣诗书方有味，
旧来朋辈觉全稀。
经纶已识从心始，
功业谁论与愿违。
努力西江文物地，
伫瞻鸣凤起朝晖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1964','黄坡储君视其弟丽中于翰林河冰既开索诗为别时戊寅正月也','顾清','明','黄溪溪上一坡斜，
茅屋青林映白沙。
摩诘辋川空见画，
文卿华谷旧通家。
怀人梦绕西堂草，
为客春深上苑花。
容易北来容易去，
看君何必泛仙槎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1965','即事和三江','顾清','明','尘沙日日起春阴，
纵有红芳未许寻。
正尔眼前怜蛱蝶，
双飞无地不园林。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1966','张元瑞司寇乞归觐不许命有司存问诸公皆贺以诗予亦同作','顾清','明','红缨白羝双作牵，
绿尊缥醴黄封全。
尚书传诏太守宣，
车骑杂遝隘里廛。
天子敬老还贪贤，
安阳未得昼锦旋。
高堂齐寿百福骈，
锡尔难老加蕃延。
老臣再拜舞堂前，
臣身踵顶恩皆天。
天念臣息臣预怜，
馀生何以效尘涓。
圣朝孝理万国平，
山林无事日高眠，
但饮春酒歌尧年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1967','月溪行送杨士宜叶','顾清','明','黄龙浦南明月溪，
溪水带月流清辉。
明珠百斛自天泻，
白虹一道无声驰。
涵清毓秀无与泄，
君家草堂偏得之。
百年流泽潜灌注，
森然玉树生阶墀。
伯也早蹑青云梯，
接武仲季连孙枝。
孙枝晚出秀而整，
夐立青琐增门楣。
河阳白云忽在念，
回首却望溪堂归。
是时青春三月暮，
溪柳绿暗飞黄鹂。
入门喜色可想见，
萱枝玉佩扶重闱。
留司禹钧面丹渥，
西川孟博垂金绯。
池边芳草林下竹，
三年不见情依依。
人间至乐亦有几，
如君况是青阳时。
都门送君酌君酒，
感我双鬓秋蓬飞。
君不见谷阳城南瑁湖上，
垂杨一径通幽栖。
五年梦想不可到，
极目松梓空烟霏。
诸孙长大儿子老，
相将不辨某与谁。
盛年一去难再得，
好事入手无濡迟。
酒阑君去我独立，
遥见江路飞红旗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1968','石斋为阁老杨公赋','顾清','明','万书插架帘几清，
朝回燕坐百虑澄。
是为石斋公所名，
公意本自羲皇经。
人生有欲随颠冥，
惟介乃立静乃贞。
介焉如石静以确，
一字可以终身行。
先生读易五十载，
神明久在筌蹄外。
细看华榜揭修楹，
正似武公歌懿戒。
岩廊特立表缙绅，
嵩高峻极华岳尊。
三神不随巨鳌抃，
一柱独止洪河奔。
十年黄阁佐万几，
矢口应笔皆天机。
昭回何止饰万物，
大有甘润苏癃疲。
名高位重心转下，
时复青山梦回驾。
向来一去四海嗟，
况此焦枯正炎夏。
介于石，
断可知，
公今岂是丘园时。
平泉往事可一笑，
仇池雪浪空崔嵬。
须公辅佐太平了，
还赋此石歌公归。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1969','东亭用三江韵','顾清','明','高亭屹立省堂东，
碧瓦朱阑面面同。
花日静熏旸谷暖，
竹风清散楚台雄。
无多簿领昼如岁，
有赫文光夜起虹。
题字主人今北海，
玉尊从此不教空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1970','过海子桥张氏旧居作','顾清','明','水边杨柳映楼台，
楼上红窗面面开。
风景不殊人事别，
夕阳沙岸首频回。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1971','丝瓜棚成次三江韵','顾清','明','丝瓜生而蔓，
蔓缘棚着花。
棚成蔓斯衍，
蔓远实转加。
松桧喜岩峻，
蘋萍乐卑洼。
巢禽与穴蚁，
各自宁其家。
东亭富阑楯，
岂乏援与笆。
先生太古心，
夙昔厌纷奢。
故将丘园景，
点缀幢节衙。
缚苇架樗柳，
连棚成咄嗟。
棚材有欹直，
瓜蔓从猗斜。
坐看花叶重，
纷如瑜掩瑕。
朝章重绮绘，
野服便葛麻。
潭潭春卿居，
钜丽兼清华。
高甍绿槐覆，
琐户红帘遮。
中间忽着此，
岂不心境遐。
看花金钱大，
食实冰蛹嘉。
嫌名幸毋讳，
去垢终无邪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1972','沙河主人后园枣实甚繁感而有述','顾清','明','牡丹红径尺，
一败即空枝。
枣花大于米，
结实反累累。
世途争外骛，
衒巧复矜奇。
仪衍雄辩说，
潘陆姱文辞。
华藻炫缃素，
声名倾一时。
终然木强子，
铭功汉鼎彝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1973','天莫雨','顾清','明','天莫雨，
雨湿衣，
雨自湿衣人不知。
昨日往矣今复兹，
人而知之宁弗思。
人苟弗思，
呜呼雨兮空尔为。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1974','天莫雨','顾清','明','地莫水，
水襄陵，
水襄陵兮人不得耕。
人不得耕，
连廒百万谁与盈。
捶肉及骨宁尔矜，
人苟弗矜，
呜呼水兮空复情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1975','孙员外性甫奉使过家为其父双泉翁寿翁以建宁推官致仕','顾清','明','闽海归来万虑轻，
双泉风月旧同盟。
于公治狱天留庆，
韦相传经世有名。
得意云山千嶂绕，
上堂衣绣五花明。
期颐亦是寻常祝，
要看瀛波到底清。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1976','题子渊内翰所藏画册','顾清','明','高树带秋色，
扁舟移晚凉。
兰桡经过处，
细细白蘋香。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1977','题子渊内翰所藏画册','顾清','明','往时波上人，
今为林下花。
相对默不语，
清心玉无瑕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1978','题子渊内翰所藏画册','顾清','明','疏篁倚长松，
烟梢拂空碧。
下想有佳处，
俯视空叹息。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1979','题子渊内翰所藏画册','顾清','明','崇台出林表，
前对万仞峰。
坐久群籁息，
辽天起松风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1980','东滨为陆鸿胪文东赋','顾清','明','东江南去接东湖，
湖上人家画里居。
绿树映门皆合抱，
清波动影欲侵裾。
诗书并沐明时宠，
山水遥连故国馀。
何日扁舟遂归志，
西风相引钓鲈鱼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1981','题东滨父子趋朝图','顾清','明','先皇龙飞登俊英，
岁在庚戌君飞腾。
甲戌今皇临大廷，
郎君接武振华缨。
尚书光禄郎而卿，
分曹右选参本兵。
天门晓开日未升，
红霞紫气绕觚棱。
玉街无尘青引绳，
冠裳佩履俨徐行。
前者长孺后元成，
小夫雅愿止金籯。
君家世德远有承，
华亭启土绍嘉兴。
贞元相君尤有名，
昆山婉娈谷水清。
诗书亹亹来云仍，
纷如玉笋间瑶桢。
朝廷有道四海平，
凤将九子不足惊。
画师不惮理丹青，
我老犹能继颂声，
请君多买鹅溪缯。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1982','次韵水村书王山农梅花诗后','顾清','明','少年冲雪探梅时，
那识溪山有险夷。
今日短筇遥伫立，
无言空咏老农诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1983','次韵水村书王山农梅花诗后','顾清','明','老农应未兴全空，
犹有湖船倚短篷。
待得春风消息透，
六桥都在暗香中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1984','定庵八十七诗','顾清','明','一番诗历又新年，
八十七回秋月圆。
桂老欲飘云外子，
鹤飞不尽海南天。
成仙自有松乔骨，
问道谁当杖几筵。
遥忆庆堂簪佩合，
兰桡重系竹西偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1985','瞻柏堂次韵为东滹石先生赋','顾清','明','摇落川原万木枝，
太行西向碧参差。
曾经彩凤回翔地，
长似甘棠蔽芾时。
风露广庭天籁迥，
邮签高阁午阴迟。
封培不尽思贤意，
欲起韩侯重赋诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1986','次韵送冯濯庵亚卿扈从巡边','顾清','明','祖道衣冠尽列卿，
早凉天气兽袍轻。
飞龙正协防边令，
司马新兼足饷名。
紫塞封疆犹瀚海，
红云城阙俨神京。
王师不作犁庭战，
须使遐方识圣情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1987','出郊书所见','顾清','明','危垣高树接重城，
转入前村路几程。
总是贵人行乐地，
隔林斤斧尚丁丁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1988','出郊书所见','顾清','明','少小生来少小荣，
人间辛苦不曾经。
新坟数仞青山下，
大字穹碑表姓名。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1989','出郊书所见','顾清','明','丝衣骏马踏尘轻，
相见无劳问姓名。
白发五经林下客，
何曾一日似君行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_1990','寄王质庵司马','顾清','明','片玉峰头一雁飞，
龙江湾上锦衣归。
向来西洛空图画，
今日东山果是非。
物外幽寻嗟我后，
眼中完节似公稀。
菊花岁晚开应遍，
谁共携壶上翠微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1991','送钱子中赴南监','顾清','明','西风淅沥吹衣裳，
天衢回首江云长。
平生拾芥看朱紫，
半醉拂剑飞冰霜。
龙山朝日自佳气，
石城秋月还清光。
明年此时桂花下，
路人共指砖桥郎。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1992','长安道中见菊调李序庵','顾清','明','九月欲尽十月催，
到处黄花烂漫开。
西园有花独不放，
直要渊明携酒来。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_5_1993','友人李民畏别号鹤峰尝欲予作诗未果也乌伤之任别有日矣为歌以送之','顾清','明','鹤城九峰俱有名，
后来鹤峰名更清。
鹤峰只在九峰里，
题品往往由先生。
鹤峰鹤城相对起，
烟水四周三百里。
峰前一径画图开，
翠竹碧梧清似水。
先生藏名三十年，
鹤亦周旋云水间。
一声此日彻天上，
回首翻愁蕙帐閒。
蕙帐閒兮猿亦惊，
作歌为尔谢山灵。
不须驰烟向驿路，
不须移文到山亭。
君不见九苞鸣鸟本在丹山外，
终为箫韶仪舜庭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1994','对雪次未斋宫谕韵','顾清','明','未能高卧学袁安，
颇忆星堂酒𧣴宽。
尺素忽来江外鲤，
虚庭正舞月中鸾。
盈盈似欲窥帘入，
密密谁从着手抟。
散满川原银海溢，
望迷城苑玉楼寒。
梁园赋客愁无寐，
金帐佳人坐损欢。
鹜阵可容还再击，
絮裘浑已不胜单。
炉头榾柮灯明灭，
枕里梨云路杳漫。
剡曲夜山通四望，
颍阴初日耀三竿。
清游此地堪乘兴，
白战当年故有坛。
我笔纯矛逢利槊，
君词轻橹下平滩。
西池古调悲黄竹，
南国新题想玉盘。
早晚青阳散重冱，
依然火伞覆炎官。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_1995','己夘新正二日沈仁甫自滇南寄新刻古乐府至中有所会拟作一首','顾清','明','金尊美酒思共传，
朱弦玉琴思和弹。
倾河赴海不复还，
昆崙东下波湍湍。
忧来无端不可删，
青灯照人愁夜寒。
夜长漫漫殊未阑，
高楼管弦声正驩。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1996','定庵兄孙从哲之官便道还家赋此豫寿','顾清','明','班行惊喜问公年，
八十八回秋月圆。
诗律开元大历际，
园亭绿野午桥天。
山田熟后酒盈瓮，
海鹤来时客满筵。
遥望庆堂疑可见，
寿花重压鬓丝偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1997','定庵寄诗贺六十次韵奉谢','顾清','明','入眼新篇玉映金，
挥毫如对草堂深。
后生日月真虚度，
前辈文章自古心。
洛社何年侍钟鼓，
吴田频岁苦霪霖。
烦公乞与长生诀，
免使霜毛上玳簪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_1998','精膳郎中侯纶母张宜人寿七十','顾清','明','五丝蹙云双帔长，
珠冠翠蕤明两珰。
早年身侍两姑傍，
良人执戟戍边方。
齐眉举按上高堂，
夜灯课子青藜光。
良人已矣诸孤昌，
大者名在六郡良。
小者南省尚书郎，
诸孙阶下俨成行。
瑶环瑜珥间珩璜，
花前迭进奉霞觞。
花枝拂帘风日香，
人间总谓天茫茫。
有如人斯天岂忘，
新年七十鬓微霜。
药饵不御身康强，
门前晋水春洋洋。
谓君酿取酒千缸，
君家此乐殊未央。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_1999','送张豫卿赴汝宁推官','顾清','明','淮南淮北万重山，
悬瓠城高紫翠间。
月旦有评乡俗美，
农桑无隙讼庭閒。
青云骥足当千里，
红日龙楼在九关。
好竭明清赞钦恤，
对花翘首望君还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2000','元夕未斋席上次赵类庵韵','顾清','明','合有新诗记此朝，
好天良会故人招。
千门华月春如盎，
三日东风冻已消。
银瓮酒香分锦荔，
䌽屏灯影乱虹桥。
只应不及双龙辇，
飞上鳌山听凤箫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2001','仆永感人也今岁生辰又值亡妻百日顾文宿兄弟求王宗颜诗寄新酒及仙山松鹤图为寿以前三日至览之怆然遂用其韵','顾清','明','白发萧然懒孝先，
黄庭读遍不成仙。
怀人举目三星在，
抚事伤心五鼎全。
幸有好诗传美酒，
转添愁思入新年。
何如置我西湖上，
一醉田家锦树筵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2002','初度前一日有感','顾清','明','君年六十我为寿，
六十明朝谁寿侬。
岁月不知人事并，
儿童刚道酒杯重。
牛眠未了山头事，
蝶化难追梦里踪。
惟有旧时明镜在，
一番惆怅掩芙蓉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2003','送顾舟卿便道省亲用别张豫卿韵','顾清','明','出郭依稀见海山，
君家元在海山间。
梁鸿德耀贤相配，
谷口襄阳老更閒。
红树拂云明翠节，
黄花隐户隔松关。
此中便是神仙宅，
何必灵砂访大还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2004','送陈子文','顾清','明','昔年倚棹清江浦，
两岸丁丁沸斤斧。
漕舟岁计动逾万，
此地寻常当七五。
年深法久人情玩，
弊孔纷纷劳葺补。
君今捧檄向淮壖，
正是青云初著鞭。
相逢数语尽肯綮，
平生经济岂徒然。
唐家善漕称刘晏，
第一造舟推庙算。
纲条宽衍物力纾，
费止一时人永便。
今人何必非古人，
今代文襄晏后身。
连云大厦须营构，
试手江边聊看君。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2005','次韵三江赐玉有述','顾清','明','团云莹润截肪齐，
亲见承恩出禁闺。
不比兰支汎觿佩，
直从银赏到金犀。
馀辉毕竟还瀛屿，
珍贡遥应度合黎。
九十武公方德进，
循墙无事首频低。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2006','吾乡先辈勇退急流者二人宪副定庵先生今八十八宪佥一斋先生今八十四予既数为定翁赋诗而宪佥不及非阙典欤何生行赋此以谢不敏且为他日乡邦故事云','顾清','明','金沙西涘白云东，
鹤发萧然两寿翁。
月旦并高诸子论，
衣冠相望古人风。
雪中松柏寒逾劲，
露下芙蓉晚更红。
一曲长生何日听，
诗成翘首向飞鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2007','过崔茂仁都尉东斋适其子凤徵生日壁有仙人骑鹤图三江为题绝句予亦同作','顾清','明','平阳宅里看图画，
想见王孙毓秀年。
应是玉真亲抱送，
还骑一鹤上寥天。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2008','读涯翁来鹤楼诗有感用前韵','顾清','明','江楼南下水茫茫，
远客归心鹤共翔。
丁令不来华表柱，
左卿今老白云乡。
斑衣旧竹应千个，
绿发新松定几行。
独倚危阑送孤目，
海云真与暮天长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2009','沈石田画为敬所阁老题','顾清','明','桐树江头夏日长，
沈沈水色映山光。
幽人倚立桐阴里，
消受閒边一味凉。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2010','沈石田画为敬所阁老题','顾清','明','经纶事重国恩深，
心忆青山未许寻。
忽见石田新画障，
一时高兴满云林。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2011','沈石田画为敬所阁老题','顾清','明','神仙上界犹官府，
清世閒行有几人。
了却盐梅霖雨事，
还公林下水边身。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2012','保宁何重器尝通守松江以福建盐课提举致仕其子鉴鏊入太学频辱惠音且存问吾乡故旧甚悉感其雅情赋此奉寄','顾清','明','锦屏山北阆州城，
心识君家到未能。
万里有情传尺素，
一时回首共青冥。
云阶接武人如玉，
江寺寻春酒似渑。
若问吴乡旧游伴，
梦回东望晓天星。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2013','东亭之东有丛竹竹外有松望之翳如也三江移竹于北墙而分其半植之南轩各赋一诗因次其韵','顾清','明','东墙飞来两青松，
北墙新篁阴更浓。
主人有意物两遂，
凤自凤兮龙自龙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2014','东亭之东有丛竹竹外有松望之翳如也三江移竹于北墙而分其半植之南轩各赋一诗因次其韵','顾清','明','五月一雨醉湘筠，
江北江南路不分。
月明夜半凤双语，
主人髣髴东亭君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2015','也适轩写怀和水村冢宰','顾清','明','达人任真性，
于世鲜求馀。
山林与城市，
所在靡絷拘。
孔明南阳日，
栖止一草庐。
及当将相权，
艺桑不千株。
走也林壑士，
尘途失东隅。
方将策驽蹇，
而与飞黄俱。
长夏平津馆，
文酒共清娱。
投之金玉章，
重以来禽书。
一吟消暑溽，
再玩忘时虞。
飞云当我前，
不去两踟蹰。
缅怀清池曲，
水华应遍舒。
馀欢似许续，
将子问何如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2016','送玉峰少宰之南都兼简东川太宰用三江韵','顾清','明','满屋图书散未收，
西风日夜趣仙舟。
回看玉署希同辈，
却望金陵感昔游。
鹏翼共知前路远，
菊花应及到时秋。
东川坐里从容语，
霖雨于今合九州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2017','车驾亲征江右命濯庵行北边再用前韵寄赠','顾清','明','荷橐甘泉陋长卿，
前驱声里铁山轻。
皇威庙略咸无外，
北伐南征并有名。
秦塞百城兵似月，
周原千里稻如京。
归来合奏平边颂，
不写阳关惜别情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2018','送柴德美给事赴南京光禄寺少卿','顾清','明','凉飙动城阙，
时序忽以遒。
驾言适郊墅，
旷漭增离忧。
离忧将奈何，
赖有酒盈舟。
俯倾一杯渌，
仰视高云流。
物色既如此，
君行安可留。
毂下有遗直，
江东非远游。
乡园自密迩，
山水复清幽。
愿保金玉音，
以应同声求。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2019','蔡东轩都尉六十八有诗自寿次韵为贺','顾清','明','身与瑶姬并得仙，
兰枝同秀玉同坚。
车轮几从三山驾，
鞶帨曾分八茧绵。
沁水林园今孰盛，
晋卿文采世争传。
小春明日长生燕，
遥听鸾箫又隔年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2020','竹轩为黄处士题','顾清','明','山翁满山都种竹，
竹里开轩面面山。
何处更容尘土入，
有时遥送岭云还。
诗书偃仰遂百岁，
霄汉飞腾任九关。
报道春风消息好，
孙枝又长箨龙斑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2021','道中大风扬尘戏为四语清河饮刘锦衣庄因足成之','顾清','明','西风吹尘日何之，
浊河东注无归时。
昆崙常高海常下，
万古不解痴人疑。
蜉蝣生尽一日乐，
孟尝死有千年悲。
此言堪笑亦有悟，
酒到但饮无多辞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2022','道逢丧车有感','顾清','明','铙丁丁，
鼓冬冬。
挽且歌，
哭以从，
短箫间歌起悲风。
歌者会有哭，
哭者会有终。
白日西下黄河东，
此歌此哭宁终穷。
惟有柩中人，
一去万古长瞢瞢。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2023','次韵答申天锡都阃','顾清','明','忆在严城听霜角，
青绫坐拥灯花落。
将军裔本申包胥，
部曲勇过王镇恶。
腰间龙纹七宝刀，
壮气直与燕山高。
誓将沙漠靖狐鼠，
肯为班行论雁羔。
诗来遣我怀南浦，
一片旌旗送笳鼓。
儒生为将今几人，
解与三军道酸苦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2024','次韵望居庸','顾清','明','连山限夷夏，
中断出奇雄。
绝地蟠金锁，
横天结翠幪。
尘沙飞不到，
羊马贡还通。
今日班司马，
谁铭瀚海功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2025','亡宜人生日有感用乙亥岁韵','顾清','明','象服遗容故俨然，
繐帷尊酒又残年。
灞陵共隐嗟予晚，
北郭安贫藉尔贤。
千里关河愁跋涉，
一封云垄待归全。
鹿车本约山中赋，
翻作东城薤露篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2026','庚辰正月过海子桥望西山晴雪烂然','顾清','明','湖桥柳色已津津，
回首西山泼烂银。
天意自知寒不久，
并将奇丽作新春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2027','十二日会东亭三江举杜韵各赋','顾清','明','瞢腾十日春光里，
又到东亭把酒时。
馀寒勒雨强作雪，
东风荡柳欲成丝。
气序暄凉催旦暮，
路岐南北有欢悲。
尊前且莫思閒事，
满眼莺花总要诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2028','生日三江石潭携酒见过且以诗补寿六十次韵为谢','顾清','明','生辰何幸偶群龙，
一笑吾翁若亦翁。
为涉岁年知冷暖，
懒从蓍历问穷通。
能诗未许澄江朓，
爱客何妨北海融。
看取向来歌舞地，
玉梅零乱䌽云空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2029','生日三江石潭携酒见过且以诗补寿六十次韵为谢','顾清','明','丹砂未就鼎中龙，
黄历频催镜里翁。
韦曲园林三月梦，
蓬山舟楫几年通。
灯花入夜偏能喜，
鬓雪逢春可得融。
为问此时公不醉，
百壶留取待谁空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2030','乡年友程御史良用子然随计来见喜君之有后而惜其年之不永也诗以吊之','顾清','明','相逢问讯一悲凉，
回首江云宰木长。
千古交期只文字，
百年心事有冰霜。
身因许国终羁旅，
天以馀忠付两郎。
高卧九原无复恨，
此生曾不愧冠裳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2031','送瓯滨谒陵用三江韵时方南征','顾清','明','奉礼晨趋左掖朝，
鸣銮回首属车遥。
神灵灞浐瞻如在，
氛祲江淮坐已消。
迎燕暖风初应律，
压尘轻雨不崇朝。
光明更有西陵月，
偏照宗臣奠桂椒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2032','寿韩司徒贯道','顾清','明','洪洞老仙初八十，
曾见垂绅立大廷。
风云一变嗟人世，
林壑三秋即幔亭。
黄发正宜松菊伴，
紫霄相续凤凰翎。
欲知后进瞻依切，
长傍弧南候景星。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2033','酒熟招时敏及诸贡士饮用其韵','顾清','明','青杏林间腊酒开，
绿蘋江外故人来。
客身无病心无事，
有约相过不用催。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2034','定庵寿诗','顾清','明','明年诗社合更年，
八十九回秋月圆。
红烛犹能映缃卷，
乌纱曾不愧青天。
三更海鹤通仙梦，
八曲鲈鱼上锦筵。
独拜尊前知有日，
客星今列五湖偏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2035','走笔和时敏客中写怀','顾清','明','扰扰蚊䖟倦扑缘，
欲将朝槿待椿年。
清江白石风尘外，
凤阁龙楼日月边。
騕袅名驹争骏捷，
修罗天女漫雄妍。
落花芳草天涯遍，
回首千门一怅然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2036','五月朔大雨新霁瑶空湛然西山翠色可挹','顾清','明','雷雨千峰过，
乾坤万里清。
天街一回望，
无限古今情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2037','和时敏病中写怀端午日作','顾清','明','红芳满地绿阴残，
风雨中宵送晓寒。
有客静边时得句，
几人忙里欲辞官。
且斟内苑菖蒲绿，
休忆炎州荔子丹。
看得此身同逆旅，
不妨随处托交欢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2038','明日看牲回作','顾清','明','尘沙不动午风轻，
阊阖西垣小队行。
白日正当龙尾道，
青山故绕凤凰城。
虞郊玉帛群灵格，
汉帝旌旗四海平。
安得升中告成事，
万人歌舞入瑶京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2039','席仁同黎一卿许伯诚三御史出巡与之酌别','顾清','明','新雨长安不动尘，
联翩驿骑向江云。
更生旧业留天禄，
桓典清风肃惠文。
镜里秋毫知历历，
壁间幽蠹漫纷纷。
还朝别有嘉猷献，
四牡皇华是昔闻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2040','纶褒晋锡卷赋者甚盛刘紫岩学士序之要予同作','顾清','明','文武声名简帝衷，
玺书频岁策戎功。
不留片垒风尘际，
尽屈群猷指掌中。
壮士偃戈眠细柳，
词人操翰拟彤弓。
南征别有殊恩在，
早晚銮舆入汉宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2041','和伯明大理舟中见寄时考满南还','顾清','明','岐路长亭复短亭，
斜阳望尽草犹青。
忽惊锦字云中下，
如见兰舟柳外停。
西省䌽衣人似玉，
北堂眉寿鬓初星。
邻盟定许重来续，
梦里时时接凤翎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2042','时敏将赴宜春以诗留别次韵为赠','顾清','明','南北舟车日往还，
朝簪无奈镜中斑。
一杯复此送君去，
三径何年共我閒。
长谷烟波增怅望，
仰山云木待跻攀。
春风坐里从容地，
不似韩公始抗颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2043','王子仪将赴南京中府都事与乃兄子贞中舍来别赋此兼简成国朱公','顾清','明','少傅优游绿野春，
郎君连步上青云。
螭坳簪笔瞻天近，
戎幕依莲惜雁分。
庆历朝廷方偃武，
琅琊子弟并能文。
中军况有诗书帅，
横槊风流未足云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2044','杨从龙郑采东二给事钩考边储临别有赠','顾清','明','计省忧时纡庙略，
夕郎承诏出边城。
八州分野占星气，
一路风云拥使旌。
经国理财当世务，
登车揽辔古人情。
微吟不尽临岐赠，
伫想嘉猷答圣明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2045','送倪郎中本端守南雄','顾清','明','越江才子南宫彦，
二十年来又作州。
画戟去冲梅岭雪，
青藜还梦玉堂秋。
邦人喜得文章守，
蛮客应无匦篚忧。
心识晚成须远到，
不胜离思绕沧洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2046','八月六日会燕新守孔君时久雨忽霁喜而有述','顾清','明','经旬苦雨隔宵晴，
童子张筵有笑声。
渤海正须龚遂去，
德星今傍五茸明。
银缸照席花频剪，
采玉飞觞令始行。
留取甘棠他日赋，
一杯先与庆西成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2047','有怀味苓赋诗未就闰八月廿三夜梦与诵之有所更定而不甚明了寤而足成','顾清','明','西亭桥下路逶迤，
中有幽人双鬓丝。
长年读易懒出户，
逢人把酒亦吟诗。
山田十亩自云足，
车盖满城浑不知。
何当便了閒居赋，
为说推敲梦里时。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2048','寿石为杨阁老赋','顾清','明','左掖连蓬岛，
南山直上林。
具瞻隆一代，
寿域启来今。
参井垂光厚，
岷峨结秀深。
精英应霄汉，
呼吸有晴阴。
紫阁淩遥跂，
丹梯极峻临。
为云霈膏润，
作柱定崎嵚。
夕雾濡文豹，
朝阳集瑞禽。
芝兰春掩映，
松柏晚萧森。
入昼星分彩，
登歌玉振音。
朋来崧华并，
礼绝省台钦。
不转惟恒性，
长存是古心。
永宜邦国殿，
未受雪霜侵。
功业岐阳鼓，
文章泗水金。
终期荐韶轸，
一奏午风吟。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_2049','为前人赋存耕','顾清','明','邠风无逸两青箱，
几叶留传到此堂。
人在江湖梦霖雨，
心将稼穑比羹墙。
三峰秀石宜高廪，
九月黄花映晚香。
拟祝遐龄自公有，
新图留取记时康。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2050','送汪德声御史按闽中','顾清','明','无诸旧国考亭乡，
柱史乘轺代省方。
三山云物归揽结，
八州风纪待恢张。
扫除芜翳要霜雪，
濡喣槁瘁宜春阳。
公馀别有天下喜，
两袖清风朝北堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2051','有感','顾清','明','了知非是不能忘，
六十年来梦几场。
掩却残书坐深夜，
一灯依旧短檠光。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2052','厚斋阁老寿诗凯旋后作','顾清','明','瀛洲仙步接黄扉，
兼总钧衡赞化机。
名德共推今日重，
寿龄无愧古人稀。
朋尊欲趁梅边举，
櫜鞬新经海上归。
一曲南山和常武，
馀音遥傍五云飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2053','敬亭和赏菊联句至十月未已次韵奉谑且为芍药寻盟二首','顾清','明','开缄奕奕见风神，
百过赓酬意转新。
栗里黄花偏耐晚，
谢庭红药已含春。
追攀未觉亭台夐，
题品时应翰墨亲。
指屈东风宁几日，
只愁无地著吟身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2054','敬亭和赏菊联句至十月未已次韵奉谑且为芍药寻盟二首','顾清','明','间梅依竹几丛丛，
曾伴渊明醉屋东。
秀质自然天力与，
芳香不逐岁华穷。
琴尊胜会留清赏，
旗鼓骚坛合顺风。
走遍凤城车马地，
几人高兴与公同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2055','淑人大祥奠柩前用乙亥韵','顾清','明','忽忽流光又此辰，
此中何意复经春。
君应地下怜诸幼，
我合愁中过六旬。
五鼎不消明镜恨，
一灯翻忆布衣贫。
东风得与同归便，
自斸青松荫两坟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2056','三江诗约尝酒次韵','顾清','明','落落晨星榜下人，
芬芬曲米帝京春。
从教徐邈论贤圣，
自识陈登有主宾。
霜菊未消金蝶粉，
画松如舞玉龙鳞。
留连要看先生醉，
醉草淋漓逼晋真。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2057','竹亭清节为胡大声司寇赋','顾清','明','问君竹亭何处所，
言在龙山之阳荆江之浒。
江水渺渺山青青，
水边种竹中作亭。
山风时来奏竽籁，
江月下照凝霜冰。
当时作亭亦漫尔，
人诵公清名日起。
皇孙题榜郁嵯峨，
清风几处表行窝。
武夷山前溪水碧，
越王城上海云多。
秋台月冷霜华重，
心绕南云不成梦。
起来挥翰走新图，
要我题诗作清閧。
竹亭竹亭今若何，
自公来后几人过。
鸿爪雪泥增怅望，
石阑苔径想婆娑。
君不见召南茇舍终烟草，
惟有甘棠一曲千古被弦歌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2058','春圃为医士范凤赋','顾清','明','尔家文正穷居日，
愿为良医惜不得。
天章一日面重瞳，
四海春风歌庆历。
善救不遗天地功，
一圃虽小春风同。
圃也有穷春不穷，
往为尔祖闳家风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2059','颁历后谒陵过清河望僧庐有怀蔡东轩郡尉','顾清','明','曾同襆被宿招提，
行役匆匆未有诗。
岁月几新官历样，
人家依旧小茅茨。
成仙合自萧郎分，
抚景偏多宋玉悲。
行过石桥犹驻马，
此情应与故人知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2060','凉水河东望','顾清','明','乱山深处小峥嵘，
匹马曾经月下行。
古戍风烟通曲巷，
野人篱落带寒坰。
百年几处频遗迹，
他日何人此问名。
回首夕阳晴更好，
碧烟横带永安城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2061','饮酒三首','顾清','明','忧来无端际，
雨雪仍雾昏。
家人馈我食，
有酒忽盈尊。
此物本非恶，
此时情更欣。
一举不计觞，
颓然成暝醺。
生材古云难，
长养良亦勤。
夭夭中林植，
几时到干云。
一朝困野火，
谁念空我园。
弃置莫与置，
沈思空烦冤。
已矣当告谁，
悲哉无复论。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2062','饮酒三首','顾清','明','烈火玉不变，
冲波山不迁。
人生亦何易，
俛首就拘挛。
昔称朝阳凤，
今为腐鼠鸢。
所丧知几何，
所希尚茫然。
愁来不能饮，
举觞酹苍天。
王业思传后，
蒸黎固无愆。
愿生岂弟人，
为时长才贤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2063','饮酒三首','顾清','明','生世苦不永，
远期惟百龄。
势位亦奚须，
要以吾志行。
志意苟不立，
区区复谁营。
蠖屈礼舆皂，
熊蹲视冠缨。
陪侧有傔从，
方间有灵明。
氓也各有心，
此理予所懵。
问之谅未可，
酒到且复倾。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2064','辛巳元日和未斋立春有感','顾清','明','馀寒弩力尽千钧，
晴日箫声已弄春。
即有落英粘舞袖，
未须啼鸟劝游人。
江东父老谈张翰，
谷口风烟望子真。
试向钗梁看䌽胜，
一番攒剪一番新。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2065','恩封豸绣为卢师邵父恒斋寿','顾清','明','神羊一角骏且灵，
心识枉直知奸贞。
因之遂有触邪名，
楚人作冠秦汉仍。
至今台府表仪刑，
卢郎铁面飞霜冰。
俨然象服当明廷，
豺狼屏息虎遁形。
彼狐鼠者敢咿嘤，
帝曰汝贤谁尔成。
往贻尔亲予尔荣，
匪予之荣繄尔情。
鸾书入山猿鹤惊，
林芳谷秀纷来迎。
吴丝致密䌽缕精，
五云灼烁千花明。
新年七十鬓未星，
夜灯密字还如蝇。
泮宫吹笙歌鹿鸣，
石湖梅花连洞庭。
行来无碍出入轻，
肩舆扁舟惟所胜。
郎君出使拥文旌，
吴船万里上青城。
朋尊献寿舞前楹，
庭前堂上总欢声。
他年犀玉麟袍赪，
还想豸角高峥嵘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2066','生辰饮酒用吴与贤韵时有所感走笔乱书不计其无伦次也','顾清','明','青灯照案犹前夕，
病眼看朱顿成碧。
风尘浩荡愁如海，
如此年华尚为客。
今日何日心神开，
喜有新诗佐欢伯。
吟君瑶篇，
酌我大白。
陈王藻思过八斗，
刘伶酒肠仅一石。
长途漫漫竟何止，
直恐蜗壳黏高壁。
瑶台何许空怅望，
黄竹白云同一拍。
寻思百岁等石火，
秪有尘编耐䌷绎。
长安春深冰雪尽，
和气如云盎阡陌。
楼卿饱饫五侯鲭，
贾傅尚虚宣室席。
人情自昔无终尽，
天道由来有损益。
彭铿至老无千岁，
赵璧虽奇不盈尺。
但得四海同仁寿，
烂醉康衢歌帝泽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2067','淑人迁柩至祖送还书感八首','顾清','明','日日青山劝我归，
明朝为尔定归期。
宵残展转不成寐，
却悔当年下钓矶。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2068','淑人迁柩至祖送还书感八首','顾清','明','寻常白发怜予老，
今日青山独尔归。
肠断不堪临别处，
还将好语慰孤儿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2069','斋居','顾清','明','日暮浮云尽，
瑶空湛虚明。
北辰俨中居，
列宿环四营。
搀抢既不动，
彗孛亦潜精。
朗月行中街，
垂辉彻洞冥。
感此念畴昔，
忽如初梦醒。
泠然遂忘寐，
整冠候鸡鸣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2070','斋居','顾清','明','层轩荫嘉树，
素月流青空。
珠光激翠羽，
绮丽难为容。
起步下中庭，
徘徊西复东。
童子讶我然，
窃语窥窗栊。
焦枯望霖雨，
隆蕴思泠风。
鯈鱼濠梁上，
岂识蒙庄翁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2071','驾至保定志喜','顾清','明','星流百骑拥前茅，
传说君王到渭桥。
灵雨隔宵清辇路，
好风和日飏鸾翘。
讴歌久属三灵拟，
冠剑行趋五夜朝。
愿祝群公同一德，
共扶尧日丽层霄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2072','归鹤辞','顾清','明','鹤飞去兮空江长烟，
鹤归来兮春酒宾筵。
入门兮矫顾，
驯予阶兮绕予轩。
浅水兮平田，
怀鷇雏兮宛当年。
忽飘然兮何意，
思寥廓兮翔骞。
仙人兮华表，
俯城郭兮依然。
信水云兮增旷宁，
旧巢兮长捐。
廉珠兮不远，
和璧兮终全。
哄满堂兮一笑，
歌南飞兮间朱弦。
惟人生兮一世，
与万物兮周旋。
虽含灵兮我异，
同声气兮相宣。
凤千仞兮览辉而萃止，
鸾五色兮顾影而蹁跹。
苟颛颛于饮啄兮，
亦奚以间于鹰鹯。
月明兮沙渚粲，
缟衣兮映修竹之娟娟。',NULL,'','{"preface": "家有双鹤飞去旬日龙山都谏得之以归适予生辰会客与竹泉杜君偕至四坐咸喜举酒属予为归鹤辞客去而辞成既以为龙山谢并寄竹泉为一时嘉话云时癸未正月也", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2073','题画留杨士宜别','顾清','明','隐隐青山渺渺江，
兰舟过处水花香。
故人别后能相忆，
时展新图送一觞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2074','是日晚独酌小吴山下','顾清','明','捲却图书坐晚凉，
小山松柏共苍苍。
本非清庙朱弦器，
曾上銮坡白玉堂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2075','是日晚独酌小吴山下','顾清','明','圣主湛恩宽雨露，
美人嘉赠比琳琅。
一杯自劝忽成醉，
明日扁舟真故乡。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2076','十一日晚登舟已大醉夜梦读书喜而有作','顾清','明','年年指作还乡计，
不道还乡是此年。
便整朝衣辞汉阙，
旋收行李上吴船。
皇恩未报儿孙在，
清论犹存首领全。
千里客途聊足恃，
梦中长自理尘编。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2077','天津吊张千户','顾清','明','南客停舟问草堂，
北人相见说文张。
宝刀金甲閒清世，
缃帙牙签有古香。
仙梦不思尘路险，
别怀应共海天长。
他时化作辽东鹤，
还指华亭是故乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2078','天津晓发','顾清','明','层城高阁倚苍茫，
南客归舟此望洋。
天运亦如河势转，
年华争得海波长。
踏风轻燕翩翩语，
近水閒花细细香。
遥看黄头牵百丈，
此身今已在江乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2079','新桥风雨夜泊用生辰饮酒韵','顾清','明','骤雨飘风不终夕，
江山万古横青碧。
人生此意要识取，
身在乾坤谁主客。
神仙十洲更三岛，
将相五侯连九伯。
当年富贵穷意气，
毕竟松林纸钱白。
曾闻冠剑画麒麟，
复道轩悬赐金石。
英声白日飞紫电，
高槩云松倚青壁。
时移地改须臾事，
侧耳清商非旧拍。
朱门华屋自荆杞，
青雀彩鸾空络绎。
岂知此日陶家翁，
葛巾曳杖柴桑陌。
书生濩落靡所似，
少也空空老何益。
已从西掖伴群英，
又向南宫分半席。
太农赋粟几钟庾，
奉常书功无寸尺。
空江夜眠复何惧，
归去扁舟游七泽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2080','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','潞河流水碧湾环，
此日何期照病颜。
举目家园疑可见，
依稀尚有百重山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2081','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','曾参石室润鸿休，
又见蒲轮降鹄头。
归去太平犹许颂，
未应诗酒只赓酬。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2082','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','扁舟临发更迟迟，
无复人间富贵机。
却忆少年春试日，
月明携卷候彤闱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2083','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','君王六乘代来初，
云从飞龙水送鱼。
敢谓老臣耽暇佚，
青山种树要全书。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2084','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','久矣人间却步行，
依然枳棘道边生。
扁舟始羡江湖子，
乱入风波坦不惊。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2085','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','猛虎有时还入市，
飞鼯何自可凌云。
临风一笑掩青史，
只恐今文累古文。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2086','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','急雨翻河电掣空，
分明此意识天翁。
老臣负乘今知免，
归卧陶家一榻风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2087','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','少不如人老岂如，
并将衰病益空疏。
茂陵词笔吾何敢，
赖有清言慰索居。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2088','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','吴丝衫子洛京尘，
点染从来岂一人。
七字衮华君幸许，
更烦松石颂长春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2089','六月十日过分水王主事舜夫留宿明日以十绝句追送次韵答之','顾清','明','识调知音钟子期，
爱贤推毂郑当时。
老夫病矣无能役，
看子飞腾定不疑。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2090','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','英雄未遇亦何疑，
恨是遭逢启祸基。
试论淮阴香火地，
何如云梦槛车时。
鸿沟未判犹辞彻，
炎历方新却构豨。
一语夜深三族并，
此情惟有舍人知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2091','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','习隆书奏野祠空，
此地千秋享卧龙。
论世合居莘野后，
际时何忝渭川逢。
微卢庸濮争奔走，
蛇虎风云俨卫从。
我亦瓣香遥稽首，
玉京原庙有遗容。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2092','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','泸江五月渡三军，
白羽风前断瘴云。
两字服心知有以，
一时成算岂徒云。
南人总识天威重，
北伐终嗟汉鼎分。
剩欲起公论此事，
邺宫吴苑几斜曛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2093','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','浣花溪上草堂幽，
世乱公来客此州。
卜筑旋应烦地主，
感怀时复为君忧。
飘飘身世辽东管，
落落篇章邺下刘。
拟驾吴船问遗迹，
不胜江水日东流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2094','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','鹿儿朝脱锦绷胎，
鼙鼓中宵动地来。
兄弟两州同日起，
嚣尘万里一时开。
遗文金石留官样，
古庙丹青落旧材。
闻道至人元不死，
鬼卢空自费阴猜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2095','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','忆昨銮舆播奉天，
先生陪从若甘泉。
文章已出留侯上，
筹策仍推贾傅前。
一自贞元仇正论，
直从元祐讲遗编。
高山四海同瞻仰，
况复桑榆共一川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2096','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','一夕元戎扫地回，
遗民已抱左衽哀。
如何寸纸中宵下，
竟折长城万里材。
本意鸣銮向河洛，
自甘浮海过温台。
英祠千古犹生气，
并入胥江作怒雷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2097','十二日至济宁秦凤山示和彭幸庵吊古诸作次韵八首','顾清','明','一代文场此隽雄，
贾生才调武侯忠。
堪嗟国破家仍破，
毕竟身穷道未穷。
神降紫云徵瑞始，
龙归黑水报君终。
丹青密迩宫墙畔，
不负成仁取义功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2098','十七日渡淮','顾清','明','惊喜呼尊酒，
长淮此日过。
乡园看渐近，
风水阅来多。
白发从稀短，
青山许啸歌。
却思前去事，
一任理南柯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2099','廿一日渡江','顾清','明','昨日渡长淮，
今日渡长江。
长江更比长淮阔，
凌空自有飞凫双。
凫双飞，
风不起，
天清清，
水㳽㳽。
眼中不复见尘沙，
只有青山如画里。
青山如画画不如，
十年归梦绕吾庐。
山中猿鹤休惊咤，
从今日日青山下。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2100','四燕诗为吴立斋司空赋','顾清','明','白下西风仙桂香，
折花归去燕黄堂。
文如鸑鷟宁榛杞，
质比璠玙合庙廊。
旅语两阶参币篚，
歌登三阕间笙簧。
安阳昼锦从兹始，
好荐南山第一觞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2101','四燕诗为吴立斋司空赋','顾清','明','才向秋堂听鹿鸣，
南宫春燕接恩荣。
上公押坐金貂重，
仙乐从风律吕清。
一代文章真幸会，
三场吃着岂平生。
午桥胜日群仙醉，
还忆宫花照面赪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2102','四燕诗为吴立斋司空赋','顾清','明','殿头钟鼓动春雷，
天子圜丘锡庆回。
尘土几人纡梦寐，
衣冠频岁许追陪。
于今鹤发重江远，
当日宫花两鬓开。
青琐有人遥献寿，
黄封还自日边来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2103','四燕诗为吴立斋司空赋','顾清','明','合乐升歌动缙绅，
泮宫开燕礼嘉宾。
尚书谢政閒居日，
太守兴贤化俗辰。
文物正当明盛治，
典型重见老成人。
肩舆十里虹桥晚，
无限青云拥后尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2104','宋西庄寿诗为懋思太学赋是日迎予西郊','顾清','明','白发归来荷主恩，
西庄六十正开尊。
云边江树收残梦，
月里天香识旧痕。
䌽笔珠玑争璀璨，
锦堂丝竹间清温。
南飞一曲从今始，
百过新腔不厌番。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2105','八月一日奉叔父且閒翁游鹤泾田舍','顾清','明','几年空作思归引，
今日还登至喜堂。
风浪拍天收短棹，
云山满目映斜阳。
良畴近绕渊明宅，
修竹遥连大阮庄。
清世宴游那易得，
赐金休问橐中黄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2106','范秉之有诗见赠次韵酬之','顾清','明','钟鼎园林志岂违，
燮调批抹本同机。
千年宝历中兴运，
一幅纱巾处士衣。
惠远特容元亮饮，
子皮悬想季鹰归。
小山无数丛生桂，
共领幽香亦未迟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2107','九月三日见梅','顾清','明','枝头忽见首惊回，
墙柳犹青菊未开。
应为主人归太晚，
故将春色点池台。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2108','章文远送菊名报君知言其早也而已过重阳五日矣次韵戏酬并邀东曙澄夫元吉共赏','顾清','明','为是重阳合有诗，
一枝先遣报君知。
临风有恨无人会，
恰值渊明止酒时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2109','章文远送菊名报君知言其早也而已过重阳五日矣次韵戏酬并邀东曙澄夫元吉共赏','顾清','明','一年好景寻常过，
总为东篱菊未开。
消释西风两家恨，
傍秋亭下小车来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2110','十七日得黄克明书报八月四日封事','顾清','明','劲弩分张不露弮，
叠双连中巧无前。
林中袖手心如水，
重为西风一怅然。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2111','吴克学郎中自义兴访予西湖之上即席有诗因共游天马山历樱桃湾绝吴松而归次韵为赠','顾清','明','漫郎心事漫郎知，
曾及昭陵在御时。
风雨幸收千里棹，
山龙深愧八蚕丝。
相过转益沧洲兴，
投赠难胜白雪词。
珍重横塘晚来别，
碧云无限古今思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2112','对菊用秉之韵','顾清','明','尘沙合眼梦园庐，
岂谓霜前自把锄。
一样黄花数行柳，
风光敢道洛阳无。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2113','对菊用秉之韵','顾清','明','竹格绳床间采楹，
野亭新立自题名。
晚来一枕西风里，
欲起湘累问独醒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2114','次韵唐清之见寄','顾清','明','旧西湖上小亭台，
远道时时梦里回。
懒散一身今我有，
升平三策待君恢。
病多野客传方与，
閒有山人送酒来。
若论午桥吾岂敢，
竹间深径倘容开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2115','傍秋亭次韵','顾清','明','茅茨初结构，
邻里悦迎逢。
高树收残雨，
清溪度远风。
束书看好在，
尊酒未言空。
为问庭前菊，
还能桃李容。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2116','至日有怀絅庵先生','顾清','明','东去颓波孰与还，
周旋长忆頖林间。
松姿不逐群芳改，
鹤貌偏于众羽閒。
真践几人同锦袭，
乐游到处有青山。
新阳肇锡元正祉，
争看莱衣五䌽斑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2117','冬至待晓作','顾清','明','掩书明烛坐宵分，
起视中庭烂五云。
占岁喜丰绿旧俗，
闭关无扰迪前闻。
人间冰雪千山涌，
地底炎阳一燧焚。
消息此中轻过眼，
后来傍睨只纷纷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2118','三江石潭寄和天津晓发诗且得十月初报次韵','顾清','明','瀛海蓬山路渺茫，
柴门流水自洋洋。
后来消息人谁在，
前去乾坤日已长。
閒把钓竿移竹影，
偶寻书卷落芸香。
愁来隐几心千里，
不道江湖自一乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2119','次韵高颐元','顾清','明','长忆城东走看春，
转头俱作白头人。
插花骑马知非事，
把笔题诗故有神。
悬圃岂知鸾掖贵，
玉芝谁数上方珍。
青冥剧有追攀意，
只恐真仙不易邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2120','次韵前人自寿且请入会','顾清','明','物生天壤间，
孰与天运长。
日月有薄蚀，
蛟龙有晦藏。
木贱乃多寿，
花妍类无香。
先生学古士，
文不数班杨。
名场四十载，
万足争奔忙。
遗珠满暗室，
袖手不下堂。
德充诱斯浅，
神胜体益康。
譬彼姑射仙，
无伤亦莫伤。
时于苍生病，
中宵起徬徨。
嘉辰集同社，
作诗代暄凉。
洛俗遵教礼，
颍评公否臧。
终当齿末坐，
不作攒眉狂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2121','病齿欲脱儿辈忧之书三十韵以广其意','顾清','明','我齿落已惯，
人闻亦寻常。
今年一齿杌，
儿曹忽惊皇。
云此口之户，
位称文学堂。
禄算系崇替，
言音资品量。
不似颐颔间，
亏残有遮藏。
咀嚼纵少利，
形颜固无伤。
一笑谓儿子，
汝言吾岂忘。
我本田舍子，
传家只耕桑。
偶然诵书史，
遂登文翰场。
懒散二十载，
纡朱佩金章。
槁虚生蠹蟫，
负乘来寇攘。
扁舟四千里，
隆赫当秋阳。
亲交喜我还，
我亦念旧乡。
炎焦夹醇酎，
合沓钟胃肠。
致困诚有以，
扶颠亦多方。
根柢既以拨，
枝条孰能当。
翻思赤舌初，
雷风挟冰霜。
傍观为缩颈，
亲知走如狂。
生还自不意，
敢复希太康。
齿缺患语讹，
老韩方亦良。
复云妨贵仕，
我已归农庄。
此外惟年寿，
岂不在彼苍。
乳饮且百岁，
我犹能糗粻。
所念齿发衰，
壮志或少荒。
百里行未半，
前途凛瞿塘。
青编有圣贤，
绿野有稻粱。
持满自我力，
干誉期尔行。
兹事苟不忒，
吾生从短长。
存乎彼诚善，
去也谁能防。
无为重戚戚，
此物本太刚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2122','十二月五日奠黄西坡泊渔水洼待晓即事','顾清','明','渔水洼边夜泊舟，
荻花飘叶两飕飕。
江湖日月摧残岁，
霄汉风云感昔游。
未了桑弧心万里，
待烹鸡黍恨千秋。
无惭独有青珉字，
光与长庚一样流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2123','修墓感怀用癸酉奉辞韵','顾清','明','不随鸾凤集梧冈，
归伴凫鹥散野塘。
馀力天将贲园垄，
修名我已愧文章。
新添白发星星短，
旧植青松个个长。
毕竟痴顽了何事，
十年多幸免垂堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2124','定庵挽诗','顾清','明','公昔还山我出山，
我归公已厌人间。
名高白傅身仍健，
诗比陶翁意更閒。
乡里后生遵楷范，
庙堂诸老问容颜。
玉屏西面青荧刻，
时有游人拂藓斑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2125','岁云晚矣园居独谣追始惟今斐然有述八章','顾清','明','岁晚园亭木叶稀，
小窗寒日净辉辉。
升平屡检新颁历，
老懒空存旧赐衣。
今古一场藏鹿梦，
江湖几处钓鱼矶。
閒来屈指平生事，
犹欠青山一早归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2126','岁云晚矣园居独谣追始惟今斐然有述八章','顾清','明','桂宫秋燕鹿鸣杯，
玉陛春闻绕殿雷。
日月九天垂景气，
风云四海辱追陪。
当时华国惭知己，
今日全身幸匪才。
试问陆家亭上鹤，
一声宁到洛阳来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2127','岁云晚矣园居独谣追始惟今斐然有述八章','顾清','明','科第云阶接月梯，
菲才何幸得攀跻。
两朝盛制兼文武，
五榜贤名入品题。
白日青空下星斗，
䌽帘红烛灿珠犀。
当时共事今馀几，
一半昆崙弱水西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2128','岁云晚矣园居独谣追始惟今斐然有述八章','顾清','明','青镜衰容每自怜，
世人描画岂其然。
朱衣象笏承君宠，
野泊林栖本性天。
閒引鹤行松径里，
偶寻梅憩石桥边。
西风日送长安信，
但报升平一万年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2129','过子南旧居还坐新宅有怀一閒处士书示子南','顾清','明','百年能几何，
今我忽已老。
重来旧游地，
恻恻伤中抱。
风光宛畴昔，
但觉朋游少。
原田看日辟，
垣屋且增好。
周览回堂序，
流尘蔼芳草。
佳儿瑶环秀，
未食看已饱。
诗囊及酒斝，
还此坐倾倒。
林光奄西驰，
起视白日皎。
深情念萝附，
远意托鸿矫。
勉旃期努力，
慰此重泉杳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2130','祝参议鸣和以诗问讯次韵答之','顾清','明','荣达世所慕，
弃捐时共伤。
朝登天子陛，
夕下尚书堂。
邻里不知故，
相随上河梁。
扬铃望九山，
指顾忽在傍。
山灵讶我归，
猿鹤亦徊偟。
江海云鸿下，
高冈威凤翔。
兹理诚坦然，
何必挠衷肠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2131','壬午元旦拜阙回作','顾清','明','三朝玉帛万方陈，
新岁新元新圣人。
元德应天乘泰运，
岁风从律转芳辰。
楼头阳鸟鸣先日，
云里仙桃色醉春。
江海老臣遥拜庆，
钧天犹恐梦中身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2132','三日对客语','顾清','明','田农仓积起耕耘，
蚕女机丝粲五纹。
万化流行视家政，
百灵趋走听心君。
墦间醉酒妻孥恨，
暮夜辞金天地闻。
此外有占吾弗问，
直须亲与见羲文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2133','东园与用常子南饮用常出口令曰新正乐事要予赋诗','顾清','明','共道新正乐事多，
廿年朋旧此经过。
红罗屋下花开早，
碧玉枝间鸟语和。
六博转曹誇胜采，
七言流响变笙歌。
频来莫谓韶光惜，
转眼薰风舞绿荷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2134','春日与客谈旧事有不能忘者纪以小诗','顾清','明','贤科采掇误知名，
素卷青衣守进呈。
两字早从提笔定，
白头空愧古人情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2135','春日与客谈旧事有不能忘者纪以小诗','顾清','明','洛阳红紫闹春光，
五剧三条锦绣香。
跬步不诒今日愧，
将军一语更难忘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2136','春日与客谈旧事有不能忘者纪以小诗','顾清','明','二十年前赋赏花，
诗成不敢向人誇。
春风东阁分题试，
却望青山感物华。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2137','春日与客谈旧事有不能忘者纪以小诗','顾清','明','城上青山绕凤楼，
朝回无事日寻游。
白头相望沧江外，
冷落西风二十秋。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2138','春日与客谈旧事有不能忘者纪以小诗','顾清','明','炙手当途势莫攀，
书生犹作有无间。
绨袍一语风波际，
只恐吾人有愧颜。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2139','春日与客谈旧事有不能忘者纪以小诗','顾清','明','浅薄寻常愧伐檀，
衰麻才脱报迁官。
清华玉署非常选，
可识当时下笔难。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2140','春日与客谈旧事有不能忘者纪以小诗','顾清','明','欲出家园意万端，
几烦飞札下长安。
春风坐里双尊绿，
添得西州泪不乾。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2141','春日与客谈旧事有不能忘者纪以小诗','顾清','明','宦途先后上京船，
每见搀行费挽牵。
明日水平风力便，
一般停棹潞河边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2142','春日与客谈旧事有不能忘者纪以小诗','顾清','明','官罗新赐印封全，
擎出天门众手传。
怪道比他颜色异，
文皇庚子进来年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2143','上元日祭友兰先师与公佩文远享胙因呈二君','顾清','明','新祠香火旧庭阶，
古木依然傍砌台。
黄卷一生惭报称，
青衿此日幸归来。
晨星落落嗟同辈，
社栎萧萧叹匪才。
安得两髦还似昔，
夕阳相伴挟书回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2144','读味苓所著桑阴梦戏书其后','顾清','明','浮世奔忙梦一场，
谈生开口笑黄粱。
不知郑老桑阴里，
更有黄粱一倍忙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2145','生辰用味苓韵','顾清','明','玉碗清泠沃蔗霜，
金尊琥珀湛云光。
诗歌白雪传腔缓，
舞合前溪引队长。
内史功名付烟草，
野王台榭亦荒冈。
诸君肯向花前醉，
何必当时绿野堂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2146','生辰用味苓韵','顾清','明','东风不管鬓丝长，
醉草时看墨数行。
花鸟大家谁彼此，
溪山到处可壶觞。
平原相业三千履，
诸葛生涯八百桑。
一笑向君重握手，
傍秋亭外又斜阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2147','次尤南渠元吉韵','顾清','明','尧民仁寿歌尧极，
万里欢声动殊域。
老臣衰病得归来，
尚欲两疏希仲伯。
青春灯火连生宴，
几夕狂眸乱朱碧。
朱碧荧煌皆帝祉，
赐金本为馀生拟。
箧中抖擞兔园编，
夜案犹堪课孙子。
若论天平何敢云，
君无多谈触监史。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2148','送富子超使荆州兼简汪秀夫太守','顾清','明','春风江上木兰花，
黄柳堤连白鹭沙。
宠命北来喧鹊语，
使旌西去拂星槎。
冰壶自许心相映，
椿树初看鬓有华。
往见汪齮道相忆，
此身今在不须嗟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2149','别后作用前韵','顾清','明','朱碧惊看眩眼花，
清泠记数白鸥沙。
人间又破炊粱梦，
海上还瞻贯月槎。
城柳依依萦别绪，
江流脉脉送年华。
卢仝吻渴茶烟细，
欲请齐奴暂咄嗟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2150','次高进之生辰韵','顾清','明','老夫初度元正节，
六十三回月廿三。
白发欺人不可奈，
青山对酒欲辞酣。
元从识字先知一，
未到通方解指南。
径躐寸阶今未敢，
家徒四壁早能堪。
心香一瓣惟宣父，
赘学千岐断晦庵。
归老幸逢新化理，
迂疏未悔腐儒谈。
晴檐映日黄绵煦，
阴磴扪萝玉佩毵。
苍柏转深霜后色，
红蕉暗结雨中甘。
层峰浥浥初融雪，
绝巘霏霏欲上岚。
斗正尧天开泰运，
尘清瀚海罢征骖。
从伶且止南飞奏，
听与吴农赋八蚕。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_5_2151','游南庄','顾清','明','春江晴日漾龙鳞，
笑上兰舟不问津。
云里遥山指秦望，
水边虚落想春申。
百年顾我青鞋在，
双鬓从他白发新。
归路月明喧鼓吹，
鸳鸯扑漉起青蘋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2152','谒外祖墓','顾清','明','古柏森森映墓门，
路人遥指陆家村。
阳元可能成宅相，
辅嗣只应传外孙。
十载宦途惟有梦，
五更风木重消魂。
凄凉泉下人难见，
酹酒空持野酿温。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2153','乡里诸公会东园颐元有诗次韵','顾清','明','东园春燕集良俦，
竹色花阴处处幽。
酒令角朋争采胜，
诗篇信手趣赓酬。
云中鸡犬谁亲见，
海上轮竿我已收。
南浦小堂仍不恶，
肯来同泛木兰舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2154','乡里诸公会东园颐元有诗次韵','顾清','明','新雨江村万绿肥，
小园红白未全稀。
望尘金谷吾何敢，
流水兰亭或庶几。
姚合久抛筇竹杖，
顾雍非爱北山薇。
今朝重读高轩过，
正始遗音的可希。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2155','晚步中庭侍人褚氏问今三月半耶曰然笑曰京中日日思归今归来九月矣喜溢颜面予闻而欣然记以小诗','顾清','明','京华日日想閒居，
今日林间九月馀。
怪道春来多乐事，
朝云此语亦堪书。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2156','饮酒','顾清','明','尘区三十载，
川陆几洄沿。
归来长林下，
缅想独依然。
形迹虽从化，
中怀庶未迁。
亲交不我弃，
尊俎日流连。
一醉靡吝情，
漫歌遂成篇。
白日高临照，
苍穹俨回旋。
往哉谅匪易，
行矣兹乾乾。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2157','饮酒','顾清','明','故人饮我酒，
坐我清湖浔。
中燕游后园，
俛手交绿阴。
侧磴度别渚，
回堂面长林。
西日明远陂，
流光荡我襟。
喟然怀往哲，
兹地几登临。
亭台无遗构，
风木有馀音。
想当古人时，
岂不亦似今。
运去鸣鸟寂，
时来蛩蠋吟。
无为后者惜，
绿醑方在斟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2158','与聂令饮聚奎亭作','顾清','明','三十年前庆落成，
白头重此见峥嵘。
山川不息英灵气，
星汉遥增日月明。
漫学鲁诗歌在泮，
敢先周士试吹笙。
天机未欲分明语，
梦里泥金有姓名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2159','四月廿七日有感','顾清','明','桑阴幂地水侵秧，
忆在长安望故乡。
今日一杯桑下醉，
不知何以答穹苍。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2160','四月廿七日有感','顾清','明','阊阖西头素扆陈，
去年今日万方新。
沧江白发频回首，
云里龙颜识未真。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2161','弘治己酉盆池莲一茎三花八月梦登鸡鸣山见日出众以为异是秋予下第而三儿生自是栽莲未始成也五月十日方小试盆池一花追忆往事诗以记之','顾清','明','碧玉波间品字红，
转头三十四薰风。
天机云锦人看汝，
汲水薶盆我已翁。
日畔早霞争借彩，
月中香雾已浮空。
书生结习真堪笑，
时复凭阑忆梦中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2162','西园即事','顾清','明','百株高柳眼中栽，
十亩荒园手自开。
白发渐多难断遣，
青鞋无恙许追陪。
行田数共邻翁语，
看竹时从野寺回。
昨日近庄传喜事，
水南新筑钓鱼台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2163','五月十七日有感','顾清','明','起望青山一浩歌，
茫茫天意竟云何。
百年正惜流水短，
双鬓其如感慨多。
墨客有情悲素茧，
阳侯无计挽颓波。
愁来转觉渔郎好，
白首烟江只钓蓑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2164','邑博王东之杖文四川却从关中赴春试扪参历井之胜过家上冢之荣此一行也兼之而梁桷同升又以益儒林之美谈矣旗亭抗手歌以扬之','顾清','明','岷峨晴翠落鲸波，
牛斗灵光出太阿。
万里风烟归揽结，
三川麟凤入搜罗。
花明帝里春将近，
云绕乡山路不多。
往与门生作同榜，
曲江先后引鸣珂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2165','赵叔敬佥宪示和东湖诗次韵写怀因以为赠','顾清','明','袖手青山敛夕晖，
渔蓑抛在绿苔矶。
水心云月閒相映，
陂里鱼凫各有依。
客梦几惊前路险，
天机谁信此中微。
西塘一夜凉风起，
已觉莼丝入箸肥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2166','赵叔敬佥宪示和东湖诗次韵写怀因以为赠','顾清','明','飞将才名困数奇，
卧龙生计一茅茨。
也知世有屠沽乐，
不疗人歌婉娈饥。
镜里晓妆看的的，
墦间归步亦施施。
乾坤若竟无真是，
长使痴人笑不痴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2167','赵叔敬佥宪示和东湖诗次韵写怀因以为赠','顾清','明','苦吟常日笑寒郊，
岂为牢愁赋楚骚。
匹马看花曾上苑，
短筇舒啸有东皋。
新知几折冯驩券，
旧绣谁论范叔袍。
明月满船江上别，
一声听唱越山高。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2168','赵叔敬佥宪示和东湖诗次韵写怀因以为赠','顾清','明','清时四海卧征鼙，
到处江山路不迷。
访古近留吴相宅，
思归先梦若耶溪。
红莲碧沚元相间，
林鹤梁鹙岂并栖。
闻说宝峰书万卷，
直将牛鼎视羹藜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2169','池莲着十花中一朵自房中复起楼子旧未尝见也','顾清','明','十朵参差一样红，
䌽楼重起绿房中。
不知物理关人事，
为有文章夺化工。
官路晓槐阴密映，
客堂春草梦先通。
白头笑我长林下，
时傍西风候塞鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2170','送高进之应举用丙午韵','顾清','明','当年早识柯亭琯，
今日初弹贡禹冠。
秾艳谢馀知果硕，
冰霜历尽见材难。
不妨官柳频萦骑，
自有天瓢为染翰。
一样风光凤城里，
木犀偏耐晚秋看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2171','用常令子文徵与三儿同应举用常有诗次韵为赠','顾清','明','袖里牙签一脉香，
挥毫长笑紫微忙。
平生忝作通家老，
今日看登选佛场。
清世文章皆炳蔚，
而翁才气本巍昂。
月明天路凉如水，
争羡扶摇接翅翔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2172','杨西潭赋天香玉兔赠三儿行次韵为谢','顾清','明','一气分职司炎凉，
商飙夕起回朱光。
玉蟾飞出海中央，
金波万丈开银塘。
上有木犀蟠古香，
荫以青云漱玉浆。
垂辉布彩遍圆方，
吐生亿载毛如霜。
注目广寒腾紫芒，
五豝但说驺虞良。
亦有白凤昭明昌，
玄霜捣成和桂芳。
下与浊世开昏狂，
圣人食之齐彼苍。
彼二子者空驰翔，
悬崖擘空彩翠彰。
谁其作者关西郎，
妙思不受铢分量。
翻思少日膂力刚，
吮豪探韵誇用强。
偶然朱衣许成章，
八分遂使三军张。
小儿学步试登场，
一番已挫铅刀铓。
南州才士真堵墙，
又逐阳侯观渺茫。
高飞为颉低为颃，
秀才但祝今年康。
五茸西北天衢长，
五星再启文明祥。
新图玉轴文锦装，
新篇古制来柏梁，
小生何以副称扬。
绿烟荡漾清晖旁，
一段丽景难为详。
走观连日隘里坊，
为君珍袭重缥缃。
留与上林春日并将，
珊瑚珉玉赋旁唐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2173','赠医僧始芳用龙山韵','顾清','明','空王心事药王名，
尘劫中间第几生。
卷却青囊留不住，
一帆江海看扬灵。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2174','览窦氏回文诗爱其音调古拟作六首','顾清','明','神圣兴运乘元真。
宸严尊居端佩绅。
禋宗敬事肃秋春。
仁贤登扬振幽沦。
陈思怀忧隐呻嚬。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2175','览窦氏回文诗爱其音调古拟作六首','顾清','明','高岗梧栖凤鸣和。
韶箫按曲引工歌。
调鼎金铉玉梅鹾。
朝堂明辟列衡阿。
巢由轸怀忧如何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2176','览窦氏回文诗爱其音调古拟作六首','顾清','明','江湖放浪狎飞凫。
双桨画舟隐蒲菰。
泷风惊梦午酣馀。
窗虹贯月夜堂虚。
扛鼎巨笔采椽如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2177','览窦氏回文诗爱其音调古拟作六首','顾清','明','商金凄冽冰丝弦。
苍青湛澄明空烟。
昂昂立鹤霜庭前。
慷慨抒怀寄诗传。
长路萦心怆华年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2178','览窦氏回文诗爱其音调古拟作六首','顾清','明','皇羲肇文成五三。
光辉蔚郁深侵涵。
缃缥珍袭重签函。
章组谢来归村南。
筐箱薶茧作老蚕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2179','览窦氏回文诗爱其音调古拟作六首','顾清','明','纹绣重袭密丽绵。
筠金间玉续匏弦。
分派九河洪涤宣。
薰兰承蕙藉简编。
坟典遗基隆圣贤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2180','邹邦辅求诗为塾师吴晋卿寿','顾清','明','邹阳书里见吴融，
曾记江楼一笑同。
华发西风吟别后，
碧山寒雨梦游中。
六千甲子春方始，
再世门生道愈隆。
拟折梅花寄君寿，
杖藜行遍鹤桥东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2181','送郡守张君柩还书感','顾清','明','客路心知有往还，
驿亭回首一酸颜。
孤云去鸟重江外，
炎日凄风两月间。
名与赤诚流白简，
身将朱绂葬青山。
相逢且莫深惆怅，
犹胜高凉不赐环。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2182','送胡仲申佥宪四川','顾清','明','落落风标四坐倾，
翩翩豸绣五花明。
星分井络承天宠，
路转江门识使旌。
三尺清平几官府，
一经忠孝旧家声。
行边好景还堪画，
绿水芙蓉绕郡城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2183','次韵秦凤山旧岁颁历喜雪','顾清','明','初元新朔遍尧天，
衔袖彤庭快睹先。
武接夔龙曾此地，
梦回霄汉已三年。
卿云又属赓歌里，
飞雪应消喜气前。
白首长林更何事，
只将多稼拟春田。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2184','次韵中秋无月','顾清','明','一年好景三秋半，
把酒还思玉宇寒。
细雨不堪论旧约，
痴云空自恼清欢。
江头几处凭阑望，
天上何人倒影看。
拟续新声歌水调，
长虹终夜绕豪端。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2185','唐民重身短而长于医且善吟咏张龙山给事呼为小仙君遂以自号','顾清','明','青冥上界多官府，
城郭閒居且静便。
留客坐谈成橘隐，
下帘高卧即壶天。
新诗不作人间语，
灵药多从海外传。
乘兴有时还过我，
小车花下亦轩然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2186','寒菊次秉之韵','顾清','明','蹙金攒碧一丛深，
延引三阳自六阴。
因笑百泉观物老，
只从梅蕊见天心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2187','姚絅庵示读近报及和叶竹窗二首次韵奉答并寄竹窗','顾清','明','十载京尘扑面红，
角巾常恐后诸公。
陶潜此日方知是，
徐邈当年也号通。
近海溪塘鱼并美，
中天楼阁栋俱隆。
相期甚愧先生厚，
无复郊亭七日龙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2188','姚絅庵示读近报及和叶竹窗二首次韵奉答并寄竹窗','顾清','明','隋珠赵璧鲁堂玙，
本自遐生又僻居。
搜剔果能无逸坠，
明扬应不载诗书。
梅边彩笔流清咏，
竹里幽窗想旧庐。
襕褐并游今几在，
白头相望渺愁予。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2189','次韵叶竹窗有怀鹤滩惟馨','顾清','明','城头西日淡寒辉，
回首同游迹渐微。
华表不归丁令鹤，
带围空褪沈郎衣。
多情转益黄花病，
上药难医白发稀。
惟有九山长不变，
自从相识见崔巍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2190','绳孙生南渠有诗次韵','顾清','明','前年花甲报更旬，
今岁庭萱送喜频。
姚察著书方有托，
酂侯传世敢同伦。
宾筵笑我连沾醉，
学海从渠远问津。
若见阿翁论父执，
杖藜还许奉清尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2191','絅庵和西园即事叠韵奉酬','顾清','明','缘溪野菊不须栽，
直到深冬烂漫开。
白日在天随处照，
青山无主要人陪。
酒香邻屋时相引，
诗送邮筒日几回。
若话旧游公亦懒，
千江波浪九层台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2192','雪景为郑节之题','顾清','明','蓑衣蒙肩笠覆顶，
拥髯倚钓坐深暝。
扁舟到处即吾家，
风雪不忧天地冥。
金门朝日五彩晖，
朱衣前进白简随。
鞠躬屏息虞谗讥，
为问此翁知不知。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2193','腊月六日视墓地归作','顾清','明','百岁生涯一颗逢，
芒鞋踏遍五湖东。
岂知海鹤冲霄地，
只在家山举目中。
旧识野人谣谶熟，
无心蓍策繇言同。
馀龄此外嗟何事，
俛首临深履薄翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2194','兼山并寿为何参之二亲赋','顾清','明','东山亭亭青插空，
西山娟好金芙蓉。
两山并秀何所似，
孟光白首陪梁鸿。
儿孙学礼仍学诗，
群峰罗立玉参差。
双尊腊蚁更拜庆，
醉过梅稍月满时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2195','吊宋西庄用己卯寄君韵','顾清','明','华屋高门接两庄，
川原暮色黯青苍。
歌钟不复楼心燕，
泪眼来看膝下郎。
长路客心知耿耿，
旧缄书迹自行行。
秪应堂构无遗恨，
荆树春风满院香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2196','淑人生日奠柩前仍用乙亥岁韵','顾清','明','此生敢道不逢辰，
绣幰曾看内苑春。
谢朓青山仍叠嶂，
维摩空室几由旬。
伤心岁月难忘旧，
满眼儿孙不当贫。
一语报君须慰意，
凤冈南麓有新坟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2197','癸未元日用壬午韵','顾清','明','欹枕残宵万迹陈，
白头那复笑陈人。
书囊上下三千岁，
甲子依稀四百辰。
冠剑此时天上会，
湖山前日梦中春。
涓流钜海无穷意，
俯仰乾坤只病身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2198','雪后登楼用沈西潜韵','顾清','明','残年掷我去堂堂，
颇觉青春日月长。
载酒有人过栗里，
上书无事讼安昌。
凭阑草木欣欣动，
倚棹凫鹥款款翔。
别有淡交真味在，
万签棐几碧芸香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2199','雪后登楼用沈西潜韵','顾清','明','冻云飞散晓来天，
举目青山九点全。
竹笋迸阶犹带雪，
柳枝低槛欲生烟。
閒寻广受还乡事，
偶到机云入洛年。
八百里封还若此，
龙阳何况木奴年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2200','初九日见红梅约味苓同赏是日新作水楼亦欲诗人过之为后来嘉话也','顾清','明','白牛溪上负苓翁，
华发萧然碧两瞳。
坐拥诗书忘永日，
醉吟花柳又东风。
王侯宅第烟霄外，
泉石交游梦想中。
风阁水帘今在眼，
且来先看早梅红。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2201','立春有感用辛巳韵','顾清','明','忆昔诸贤秉化钧，
万方同醉洛阳春。
丝红缕绿盘心菜，
剪碧涂金胜里人。
往事不堪重理梦，
短吟聊与当传真。
君王圣德同尧舜，
愿倚青阳颂日新。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2202','旦起偶书','顾清','明','起临青镜拂冠巾，
又见江南一度春。
老觉杖藜行处稳，
病于方药试来真。
吟思好句翻疑梦，
坐爱名山不近人。
六十四年多少事，
向来何敢道全身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2203','生辰次味苓韵','顾清','明','生筵酒盏接元春，
次第风光到此辰。
梦好协公桑荫传，
诗来锡我上方珍。
园林钟鼓非前辈，
廊庙江湖亦老臣。
孱弱愿期交引翼，
共瞻尧日万年春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2204','次姚絅庵韵','顾清','明','少年学步希攀龙，
后生先辈殊而同。
文场接轸借光价，
海月下照沧江虹。
当时庠序总豪俊，
公于其间尤长雄。
岁行壬子我忝窃，
公意夙与神灵通。
黄旗捷足走夜半，
隐若平地行丰隆。
升沉不作时世态，
江头别酒双壶崇。
刘蕡何必下李邰，
云龙竟尔乖相从。
虚名我亦自知我，
厚抱世岂能忘公。
南安一世仅小试，
梁栋已奏苏湖功。
至今诸生诵遗训，
有若汉士希林宗。
閒居诗笔老益进，
人意所澹公偏浓。
犬马之龄亦奚有，
大篇投赠何舂容。
祓除牛舌鸡口秽，
涤荡柳眼梅花风。
寒林索莫幽谷閟，
顷刻万景回春融。
尘区奔走三十载，
微命岂不悬青穹。
樯掀舟舞几阽殆，
梦中每想垂纶翁。
致君有意苦才薄，
击壤且逐康衢童。
养鱼池南鹤泾北，
归来两见春花红。
去时众雏皆长大，
丹玉冠顶黄金瞳。
长鸣一声起烟际，
哀怨似吊吴臣忠。
洛阳羁客竟不返，
草堂空锁青山松。
小奴获稻试春酿，
一瓮晓熟天门冬。
弧南光烛斗牛分，
诸老百福神皆充。
相携一笑醉花底，
便可写入丹青中。
不作云台卧华顶，
亦合桓荣陪李躬。
寻思却恨公不饮，
未怕北海尊罍空。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2205','生辰会两学广文有以烟火为戏者因成四韵','顾清','明','贮烟含雾结机丝，
旁络中联鬼不知。
一炬么微平地起，
万花纷骇入云披。
龙蛇杂出星辰下，
霹雳交从指掌驰。
直到上头人喝采，
满衣灰烬踏泥归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2206','诸广文见和叠韵奉酬','顾清','明','万变灵通火一丝，
只应师偃未曾知。
宝王珠络浮空下，
神女龙绡隔雾披。
明月上时雷炮发，
暗尘惊处火轮驰。
词臣正忆鳌山盛，
为谢嘉宾缓缓归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2207','别驾高君解绶归众皆叹惜竞为诗以送之予亦继作','顾清','明','听鹤亭前酒一卮，
柳条花萼共依依。
也知物色皆天予，
但觉风光与愿违。
羁绁可能长客路，
云山从此谢尘衣。
漻然冰玉脂膏地，
犹喜吾人有是非。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2208','钟卿密绣衣示近报有怀傅文穆公','顾清','明','十庙威神俨在天，
万邦黎庶尚多贤。
皋夔事业诚遐矣，
房杜襟怀亦朗然。
两手果能藏万目，
一时何以易千年。
令人转忆临川老，
屈指怀忧廿载前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2209','六言','顾清','明','园林日日春风，
市喧不到墙东。
犬卧落红篱下，
莺啼新绿阴中。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_5_2210','桂林谭君教吾松六年甚得士子心忽闻罢去相与骇叹而莫知所从徐考其名与君之为人正相反也于其行诗以白之','顾清','明','花自含仁絮自飞，
春风着物本何私。
秪应鶗鴂中宵起，
不尽芳兰九畹滋。
江月有情千里共，
湘流无恙此心知。
瑞莲池上题诗在，
总是诸生去后思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2211','数日不过西亭忽木兰着三花平生所未睹也涉笔书此招味苓同赏','顾清','明','天随诗里洞庭船，
玉貌云孙故俨然。
游遍洛阳曾不见，
赏音今日付朱弦。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2212','味澜','顾清','明','飞泉出巨壑，
百里回澜翔。
酌之味其甘，
仰视云山苍。
山高土滋厚，
土厚泉益芳。
浸灌富畦垄，
回环固陵冈。
谁知一滴润，
中有千林香。
先生青乌胄，
家在云水乡。
常言九峰青，
孰与三江长。
妙契一以握，
川灵走奔忙。
我老怀首邱，
君来协吾祥。
盘盘凤山麓，
南趋向朝阳。
溪流左右带，
落此团玉光。
顾会本旧浦，
祥泽亦名塘。
须君一染指，
为我终其臧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2213','仙鹤褚道人尝欲得一诗久未能答近和元吉寿篇见者谓似游仙体因书以贻之然终不近也','顾清','明','曾立萧台缥缈天，
尘心一堕八千年。
却从海上三山驾，
来集城南五色泉。
辽鹤再闻中夜语，
葛龙深抱午时涎。
绿章赤字无人检，
犹在虚皇玉案前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2214','四月七日陪约庵适斋二太守东园鸿胪龙山都谏登超果一览楼望西隐堂有感还饮翠林精舍作时西隐火已一年而寺主杰峰亦化去矣是日翠林亦病出蔬馔延客故末句云云','顾清','明','天台楼阁冠群山，
童稚游歌日倚阑。
岁月不知青鬓改，
松梧长绕碧窗寒。
尘龛落日悲弹指，
劫海何人更助澜。
赖得远师容客醉，
不教啼鸟怨春残。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2215','来鹤楼次周北野韵','顾清','明','江上楼成记鹤来，
鹤飞江外几徘徊。
仙人不作临皋梦，
游子新从洛下回。
天末远风传嘹亮，
竹间斜月见毰毸。
何时重续城南会，
高咏南飞送一杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2216','闰四月三日北庄分秧约味苓同观与联句','顾清','明','千金难买俞塘北，
百亩新开水曲庄。
相约明朝移短棹，
绿阴传酒看分秧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2217','闰四月三日北庄分秧约味苓同观与联句','顾清','明','绿阴传酒看分秧，
曲水萦回送羽觞。
画里兰亭诗七月，
一时流咏遍江乡。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2218','蒋文藻水竹村居','顾清','明','閒身不属樊笼琐，
茅屋偏宜水竹村。
尽日枕书芸阁静，
有时挥翰墨池翻。
娟娟翠羽凉生坐，
落落清瑶澹迤门。
赢得白头心眼净，
春风长见长儿孙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2219','出都时馆中诸君有晚庭侍咏联句其后不预者相继有作近方寄至次韵荅之','顾清','明','匡时无计乞身难，
望望云西九点山。
雷雨恩深天作解，
桑榆景近鸟飞还。
词中郢客重闻调，
枕里卢生已度关。
犹有感怀诗未了，
桔槔长夏不曾閒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2220','出都时馆中诸君有晚庭侍咏联句其后不预者相继有作近方寄至次韵荅之','顾清','明','曾传初诏未央前，
举目金容尚俨然。
天地冰霜春不间，
江湖星斗夜常悬。
无心海鸟当人下，
可画云山与屋连。
珍重故人相慰意，
一时分付钓鱼船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2221','夜梦为人作幽居诗得二句嫌其寂寞而止既寤因足成之','顾清','明','苔生井干草生阶，
不见马蹄门外来。
风月满庭书满架，
一尊时对碧山开。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2222','和杨时望新居杂咏','顾清','明','盛年驰远志，
将老思閒静。
天运有消息，
人事递丰省。
自从大道丧，
阶磩生榛梗。
欣荣亦偶然，
沦伏岂非幸。
诗班未可笑，
过涉且灭顶。
惟虑西潭月，
照此胸中耿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2223','和杨时望新居杂咏','顾清','明','道存无穷达，
志适忘远近。
子桑七日病，
岂忆惠施问。
由也号升堂，
乃作穷途愠。
君家三赋翁，
天球振空韵。
才高徒后名，
事往嗟颓运。
何以发清谣，
东邻有芳酝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2224','和杨时望新居杂咏','顾清','明','卜居须仁里，
结友须良契。
湘累江潭行，
纫佩必兰蕙。
蓬麻两因依，
腐蠸终蝥蜹。
君看稷下生，
肯乞墦间祭。
吾徒幸閒居，
尘境息啁嘒。
玄文倘许窥，
乌藤尚堪曳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2225','和杨时望新居杂咏','顾清','明','月出新雨馀，
桐阴落金井。
经旬困隆郁，
扪颈欲生瘿。
飘然怀灵仙，
愿作䌽鸾请。
鸾飞空冥冥，
去入无穷境。
靡求焉有争，
不暑安知冷。
下视区中人，
纷纷逐风影。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2226','题阮袭之合浦还珠卷','顾清','明','子丧目与丧，
孙归目亦明。
嗣承真一线，
游历恍他生。
舞袖春花媚，
书灯夜案清。
云阶绳武地，
细话十年情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2227','题阮袭之合浦还珠卷','顾清','明','邂逅惊迟暮，
暌违熟姓名。
三场先后榜，
四海弟兄情。
病阻临溪饯，
愁闻触暑行。
因诗叙奇事，
流咏满江城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2228','法驾导引','顾清','明','骖龙驾，
骖龙驾，
龙驾引鸾旌。
罗列三光俱在下，
青云回首玉皇城。
风露杳冥冥。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_2229','法驾导引','顾清','明','金风袅，
金风袅，
飞佩度银泓。
仙袂六铢凉似水，
搏桑东望火云蒸。
回首指蓬瀛。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_2230','法驾导引','顾清','明','雷隐隐，
雷隐隐，
列缺挟飞车。
一掷火铃三万里，
人间何处着妖邪。
归路海天霞。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_2231','法驾导引','顾清','明','祥云起，
祥云起，
云起四天明。
宝月宫中光气满，
流黄一道坠明星。
万寿圣人生。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_2232','法驾导引','顾清','明','歌万寿，
歌万寿，
稽首玉宸尊。
下视九州云五色，
群龙济济会天门。
一气俨长存。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_5_2233','再用翰林诸公韵','顾清','明','人间行路古来难，
亦有南山与北山。
莼菜可能羊酪美，
张翰不共陆机还。
云林窈窕时孤往，
蓬户寻常夜不关。
翘首群龙会霄汉，
沧洲天放老夫閒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2234','再用翰林诸公韵','顾清','明','糠秕因风偶在前，
向来淘汰岂徒然。
臣生得失鸡虫比，
帝德光华日月悬。
野鹜自非威凤侣，
三江元共五湖连。
夜来一枕游仙梦，
亲见秦皇驾海船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2235','读天游集','顾清','明','君平成都隐，
室无儋石储。
罗冲家万金，
往遗倾后车。
我馀子不足，
遗我将安居。
笑谓平生过，
酬称良非虚。
我尝宿卿家，
周览子室庐。
见子朝夕间，
汲汲无少舒。
我卜不下堂，
垂帘常晏如。
馀钱累数百，
凝尘委床隅。
以兹对相较，
岂不我有馀。
王生景芳躅，
特笔天游书。
览之重有感，
长叹仰天衢。
斯贤诚旷代，
冲也今亦无。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2236','读天游集','顾清','明','文僖尹西洛，
宾幕皆鸿儒。
希踪郭延卿，
野服临其居。
荒僻少过从，
未见诸公如。
菲然具杯案，
班荆叙欢娱。
日昳群吏集，
麾盖满庭除。
公等皆何官，
骑从尔云都。
盘飧靡加味，
体貌不殊初。
谈咏西山暮，
出门送登车。
诸公恍自失，
累日增叹吁。
襟怀有如此，
声利岂能驱。
下视望尘子，
飞龙翔太虚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2237','枯木竹石为郑节之题','顾清','明','霜凋孤桐树，
槎牙碧琅玕。
夜半山月出，
飞下两青鸾。
幽人适不寐，
清影上阑干。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2238','闻客言有省','顾清','明','也识随时好，
难忘泥古心。
交丝易为幔，
孤植鲜成林。
邈矣期千岁，
悠哉寄一琴。
草堂人静夜，
三讽白圭吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2239','和杨时望','顾清','明','睡起江楼日未颓，
小园篱落豆花开。
归迟野鹤鸣相及，
见惯沙鸥眼一猜。
春梦一场成独笑，
秋风万里为谁来。
木犀枝上青青蕊，
已办分香入酒杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2240','南京摺扇名天下成化间尤重李昭骨王孟仁画兼之者誇以为奇而今不可得矣明善内弟以听泉主人扇索题其画则孟仁笔也展玩数四旧京风致宛在目前为书此以志感','顾清','明','李郎扇骨王郎画，
三十年前盛有名。
老眼摩挲旧时墨，
却思骑马凤台行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2241','次韵答陈鲁南','顾清','明','魏阙江湖总帝臣，
碧山金马亦平分。
机云此日真无恨，
随陆当年也未文。
清浅几湾松谷水，
飘摇一片海天云。
只应细雨斜风调，
未可群仙上界闻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2242','庭前有柏屏闵其束缚命小童解之因题四韵','顾清','明','山中霜柏自亭亭，
多事园丁强作屏。
剪截共惊鸾尾锻，
屈缠何异楚囚扃。
濠梁水上鱼能乐，
茂叔窗前草自青。
释缚解围俄顷事，
拂云从汝到千龄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2243','絅庵先生悬弧中夏而延客以初冬致贺诚后时矣而馀觞犹可掇也辄成四韵庸助笑言','顾清','明','寒日西风净帽纱，
清尊绿酒对黄花。
閒思往事三春梦，
老觉流年两鬓华。
元节未妨寒食拜，
寿觞应共海筹加。
小车莫厌频来驻，
前辈如公更几家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_5_2244','芙蓉金菊间开','顾清','明','时至园林百卉芳，
纷纷紫绿间青黄。
芙蓉不带春风面，
依旧寒花一处香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2245','往岁阻风江上尝登圌山望海门孙思和逸想楼甚近而未之到也诵守溪翁之作遐思渺然敬次其韵','顾清','明','连云不见五城楼，
曾立金鳌顶上头。
回首乾坤双雪鬓，
海风吹梦落沧洲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2246','寓感四首','顾清','明','依阿每得意，
肮脏常失时。
古人已共叹，
末路转多岐。
芝兰掩萧艾，
鸑鷟避鸢鸱。
人众天可胜，
而我犹人猗。
欣欣讵可遏，
悄悄空自悲。
惟当秉明哲，
大运随所之。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2247','寓感四首','顾清','明','短辔纡长驾，
行行未渠已。
川途屡回互，
常恐迷所指。
天机妙倚伏，
人事亦难拟。
寻常婚媾筵，
中有寇戎垒。
有时涛波翻，
举网得双鲤。
流行随大化，
百岁讵能几。
温凉久矣更，
甘苦亦如此。
谐俗诚以难，
抱拙长已矣。
谅无当世资，
庶曰寝息美。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2248','寓感四首','顾清','明','江河亘九地，
日月丽九旻。
明者必有本，
流者必有源。
一极肇万有，
至理无馀言。
行人望逆旅，
所觊一榻温。
黄昏幸即次，
遽欲隳乃垣。
以彼虫鼠智，
妄启般倕门。
高言视一世，
举目皆童昏。
六籍炳明训，
灵扃俨威神。
十室且忠信，
寰中岂无人。
谁欤仗三尺，
屏此魑魅群。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2249','寓感四首','顾清','明','濂洛继绝学，
紫阳集群儒。
微言析豪末，
精义穷锱铢。
冰泮解众惑，
春融归一初。
馀功及藻翰，
金石垂楷模。
高踪邈难继，
诡辔启殊途。
掇拾珙璧瑕，
进彼珉与玞。
蔀屋虽见斗，
肺肝本昭如。
彼狂谅已矣，
蒙也真何辜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_5_2250','淑人启土有感随事写怀用辛巳韵','顾清','明','修门同入不同归，
归日青山未敢期。
鸾匣君今正丘首，
渔竿我亦上苔矶。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2251','淑人启土有感随事写怀用辛巳韵','顾清','明','五十年中几别离，
谁知此别遂长归。
红颜白发终千古，
敢向苍苍怨小儿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2252','淑人启土有感随事写怀用辛巳韵','顾清','明','今日青山始是归，
为君三过着麻衣。
可怜稚女随人哭，
问着阿婆浑未知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2253','淑人启土有感随事写怀用辛巳韵','顾清','明','为君砻石为君辞，
几度含毫湿素衣。
两字龙光三锡命，
一行先上赤缯旂。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2254','淑人启土有感随事写怀用辛巳韵','顾清','明','并居华屋更无时，
回首风尘两鬓丝。
坐拥孤衾听寒雨，
此情犹望有人知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_5_2255','昔司空表圣辞官后预营冢圹与宾客同游世传以为达予葬淑人迫于岁暮功虽未讫而规制定矣营度往还得绝句十二首目之曰生游棹歌非敢仰希先躅亦聊以寄兴云尔','顾清','明','瑁湖烟水接通波，
问讯塘桥路不多。
